pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can ever use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Small unusable-ish gaps (10..=20) are risky since min item is 10; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 60.0 * tightness;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }
    // Many fitting bins: slight pressure to keep flexibility, prefer tighter bins anyway.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: when many bins are open, discourage spreading into loose fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Lookahead coupling: if next item fits the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // If next item would be blocked by a wasteful small gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Mean-residual coupling: prefer bins whose post-residual sits near the mean
    // (keeps residual distribution homogeneous and packable).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: attractive early or when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && post_residual < 10 { 250.0 } else { 0.0 };
        score -= 40.0 + 30.0 * (1.0 - progress) + poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 1) are pure waste; penalize quadratically.
    if post_residual < 1 {
        score += 1000.0;
    }
    // Penalize "awkward" residuals: gaps that fit nothing likely to arrive.
    // Treat gaps below half of the mean residual as increasingly dead.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual - post_residual as f64) * 1.5;
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward placements that still leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + post_residual.min(next_item_size) as f64 * 0.25;
        } else {
            // The next item won't fit here afterwards: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Open-bin pressure: discourage spreading across many bins, but relax
    // pressure as the stream progresses (closing bins early is fine later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.5 - 1.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // If several bins fit, prefer the tightest fit (smallest post residual
    // already captures this, but add tie-breaker against huge leftovers).
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no good existing fit exists (large dead-space
    // penalty on chosen bin) or when few bins are open early on.
    if bin_residual == bin_capacity {
        let fallback_cost = 15.0 + open_bins_count as f64 * 1.2 - 10.0 * progress;
        score = fallback_cost + (bin_capacity - item_size) as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits exactly or well into this bin afterwards
            score -= 60.0 * (1.0 - diff / 100.0);
            if diff == 0.0 {
                score -= 400.0;
            }
        } else {
            // dead space relative to lookahead item: penalize small unusable gaps
            score += 0.8 * (nxt - post_residual as f64);
        }
    }

    // Penalize leaving residual that nothing (10..80) can use
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Prefer tighter bins relative to mean residual
    score += 1.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        let poor_fit = item_size as f64 > mean_residual + 10.0;
        if poor_fit || mean_residual < item_size as f64 {
            score -= 150.0 + 50.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        } else {
            score += 200.0 + 100.0 * crowded;
        }
    }

    // Mild pressure to consolidate late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 interface, but small gaps < ~12 are
    // nearly always dead) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is excellent.
        score -= 40.0;
    }

    // Reward when post_residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if the lookahead item would be blocked by this placement.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonable fit exists; encourage opening new bins only when fits are bad.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the "useful" direction (large residual absorbs big future items).
    if (bin_residual as f64 - mean_residual).abs() > 0.0 {
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate handling: it is attractive only when this is the last
    // item or when existing fits are poor (large post_residual / dead space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64).min(20.0); // 0 for empty bin itself
        let _ = poor_fit;
        // Base cost of opening a bin, reduced late in the stream.
        score = 25.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // empty bin can always take the next item
        }
        if fitting_bins_count == 1 {
            // Some bin fits; only open a new one if that fit leaves dead space.
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Perfect fit for the lookahead item: strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // lookahead item cannot use this bin's remainder
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: more open bins => prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it costly unless current bin would leave big waste.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * -1.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild tie-break: prefer bins with low residual relative to mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1..~15) can use it.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0; // up to +120 for 1-unit slivers
    }

    // Reward near-perfect fills (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual >= 11 && post_residual <= 30 {
        score -= 8.0; // still a very usable window
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 15.0;

    // Pressure from number of open bins: discourage scattering across many bins.
    score += (open_bins_count as f64).powf(0.9) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 10.0; // next item just misses: gap likely wasted
        }
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer new bin
    // when all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        score = 55.0 - tightness * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin anyway
        }
    }

    // Slight drift with stream progression: later in stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A gap is "dead" if nothing in the size range can ever use it.
    // Items are 1..=100, but small gaps are only usable by small items.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize small unusable gaps superlinearly.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        // gap too small even for the next item -> likely dead space
        score += 25.0 + 0.5 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        // absolutely tiny gap: pure waste
        score += 40.0;
    }

    // Reward tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // --- Lookahead coupling: leave room for the next item if possible ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // this bin can also absorb the next item
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress); // early on, avoid stranding gaps
    }

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- Open-bin pressure: with many open bins, consolidate ---
    score += 0.15 * open_bins_count as f64;

    // --- Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin residuals homogeneous, easier future packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- New-bin candidate handling ---
    // A fresh empty bin (residual == capacity) should only win when the fit
    // elsewhere is poor: give it a moderate baseline penalty that scales
    // with how much of it the current item would consume.
    if bin_residual == bin_capacity {
        // utilization of the new bin by this item
        let util = item_size as f64 / bin_capacity as f64;
        // big items justify a new bin; small items should reuse open bins
        score = 45.0 - 30.0 * util;
        if post_residual == 0 {
            score -= 60.0; // exact fill still fine
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        score += 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = (pr % 10 == 0) as i32
            + (pr % 20 == 0) as i32
            + (pr % 25 == 0) as i32
            + (pr % 50 == 0) as i32;
        score -= 6.0 * harmonic as f64;

        // Dead-space penalty: tiny unfillable leftovers
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Integer-division threshold: leftover large enough to host a mid item
        if pr / 20 >= 1 {
            score -= 3.0;
        }
        if pr / 40 >= 1 {
            score -= 3.0;
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
            // harmonic bonus if residual after next item is a nice class
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 && r2 > 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly
    // mismatched with the item (poor fit everywhere).
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64; // = post_residual for new bin
        let mean_gap = (mean_residual - item_size as f64).abs();
        // prefer new bin when mean residual is far from item and open bins few
        score += 20.0 - 0.5 * mean_gap - 0.5 * open_bins_count as f64;
        // late in stream, avoid scattering
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        let _ = fit_quality;
    }

    // Mild pressure to fill already-open bins tightly
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    if post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        score += waste_frac * waste_frac * 30.0;
    } else {
        score -= 25.0; // perfect fill
    }

    // Reward bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: penalize leaving residual that fits the next item badly
    // (residual too small to be useful), reward residual that pairs with next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 6.0 * (nx / cap); // next item can also fit here
        } else if post_residual > 0 {
            let dead = post_residual as f64 / cap;
            score += dead * 20.0 * (1.0 - progress); // dead space matters more early
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // or few bins can fit the item.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let poor_fit = 1.0 - fill_ratio.min(1.0);
        let open_bonus = (open_bins_count as f64).ln().max(0.5);
        score = 40.0 - fit_pressure * 30.0 - poor_fit * 25.0 * open_bonus - progress * 10.0;
        // If a near-perfect fit exists elsewhere, discourage new bin.
        if fill_ratio > 0.85 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Mild global balancing: prefer bins with residual near mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream: favor consolidation into fewer bins.
    if open_bins_count > 1 && progress > 0.7 && bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 45.0 - 2.5 * post_residual as f64;
    }
    // Medium gaps that only fit tiny items are mildly penalized.
    if post_residual > 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward very tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Perfect-fill bonus for new empty bin handling: prefer existing bins that nearly fill.
    if post_residual as f64 <= (bin_capacity as f64 * 0.05) {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; keep score of new bins higher.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot use the leftover, penalize leaving a mid-size gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 12.0;
    }

    // New-bin candidate calibration: empty bin should look average; adjust with mean residual.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + mean_residual * 0.2 + open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: post_residual can hold next item with little slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable remainder.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize creating tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure
    }

    // Compare against mean residual: bins with more slack than average are better targets.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, be more willing to open new bins (keep residual large);
    // later, consolidate to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when many bins are open or early on.
        score -= 8.0 * progress + 0.2 * open_bins_count as f64;
    } else {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += (dead_threshold - post_residual + 1) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    score += (open_bins_count as f64).powf(1.2) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creates a gap the next item cannot use: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate handling: attractive early or when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit_gap = mean_residual - item_size as f64;
        let poor_fits = mean_fit_gap < 0.0 || mean_residual > 70.0;
        if poor_fits || progress < 0.15 {
            score -= 35.0 + (mean_residual - 50.0).abs() * 0.3;
        } else {
            // Mid-stream: prefer filling existing bins; penalize new bins mildly.
            score += 15.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins with residual close to mean (keeps bin states balanced).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average upcoming item.
    if post_residual < item_size {
        score += 8.0 * (item_size - post_residual) as f64;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 4.0 * (next_item_size as f64 / 100.0);
        }
        // Chain fit: post_residual exactly matches next item is ideal.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps spread even),
    // but reward packing into fuller bins (classic best-fit) instead.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fullness;

    // Global state coupling: many open bins -> prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if open_bins_count > 4 {
        score -= 3.0 * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // no good fit exists or the stream is early and bins are crowded.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let crowding = (open_bins_count as f64 / 8.0).min(2.0);
        let early = 1.0 - progress;
        score += base_penalty - 8.0 * crowding * early;
        // If next item is large, a fresh bin is fine.
        if next_item_size >= 60 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild time-horizon modulation: late in stream, be greedier about tight fits.
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals that are "nice"
    // fractions of capacity (multiples of common item sizes) are reusable.
    let pr = post_residual;
    let reusable = (pr == 0)
        || (pr % 10 == 0)
        || (pr % 20 == 0)
        || (pr % 25 == 0)
        || (pr % 50 == 0);
    if reusable { score -= 12.0; }

    // Dead space: tiny residual that almost nothing can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is king.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic coupling: exact divisibility of post_residual by next item
            let n = next_item_size;
            if pr % n == 0 {
                score -= 18.0 + (pr / n) as f64 * 2.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; slight penalty for wasting lookahead
            score += 4.0;
            // If next item exactly equals residual class modulo capacity, soften
            if (next_item_size + pr) % 100 == 0 {
                score -= 6.0;
            }
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should only win when the
    // current bin's fit is poor. Give the empty bin a moderate baseline.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.1 - (open_bins_count as f64) * 0.5;
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / cap) * 10.0;
        // Early in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 8.0;
    }

    // Slight preference for bins with below-average residual (more filled).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Integer-division threshold on residual thirds: bins whose residual
    // falls in the "middle third" of capacity are flexible.
    let third = bin_capacity / 3;
    if post_residual >= third && post_residual < 2 * third {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (1..100 interface => threshold calibrated at 12) are pure waste.
    if post_residual < 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 12.0);
    }
    // "Sweet spot": post_residual that can still host a mid-size item is valuable.
    if post_residual >= 12 && post_residual <= 40 {
        score -= 18.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: default cost, reduced only when the current bin's post
    // residual would be dead space AND the next item needs real room.
    if bin_residual == bin_capacity {
        score = 50.0;
        if post_residual < 12 && next_item_size > 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // This bin can't host the next item; slight penalty so a bin that chains
        // both items wins when otherwise equal.
        score += 8.0;
    } else if next_item_size > 0 {
        score -= 6.0;
    }

    // Mild bonus for bins below mean residual (rebalancing fragmentation).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 18.0;
        } else if pr % 25 == 0 {
            score -= 12.0;
        } else if pr % 20 == 0 {
            score -= 10.0;
        } else if pr % 10 == 0 {
            score -= 7.0;
        }
        // Small unusable dead space is bad: penalize tiny residuals hard.
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 40.0;
    }

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how tightly next item fits (harmonic residue).
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
            if slack as u32 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // This bin becomes dead after placing current item.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual state.
    score -= (bin_capacity as f64 - mean_residual) * 0.05;

    // Mild pressure against opening new bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 - open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Fit tightness: prefer bins where the item occupies a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: with many open bins, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the mean residual is too small for the item.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 1.1);
        if poor_alternatives {
            score -= 70.0;
        } else {
            score += 90.0 + open_bins_count as f64 * 5.0;
        }
    }

    // Mild alignment with mean residual: bins below mean residual are tighter fits.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is better, handled by base term.

    // Aggressive 2-step lookahead: if the next item exactly matches post_residual,
    // this placement sets up a perfect fill — heavily reward.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this one: mild reward, scaled by closeness.
            score -= 6.0 * (ni / pr);
        } else {
            // Next item won't fit: penalize dead space left behind.
            score += 4.0 * (ni - pr) / bin_capacity as f64 * 100.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residuals far below mean wastes space; reward leaving large usable residuals.
    let mr = mean_residual;
    if mr > 0.0 {
        let pr = post_residual as f64;
        if pr >= mr {
            score -= 2.0 * (pr - mr) / bin_capacity as f64 * 10.0;
        } else {
            score += 2.0 * (mr - pr) / bin_capacity as f64 * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate mildly, so it's chosen only
    // when open bins would leave very large post residuals.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in the stream, opening bins is cheaper; later, discourage more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins that will be well-utilized overall.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 3.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold anything useful are poison.
    // Treat post_residual below a "usable threshold" as dead space and penalize hard.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 4.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fill is excellent.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (1.0 + post_residual as f64);
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chains placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Post residual can't hold next item: mild penalty scaled by wasted capacity.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin (residual == capacity) is cheaper.
    score += 0.3 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; attractive when open bins are few.
        score += 5.0 - 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: if this bin is far below average residual (already tight),
    // prefer packing here to consolidate.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small post_residual that nothing can use (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic class of post_residual: bins whose residual falls in
    // "reusable" classes (multiples of 10, 20, 25, 50) are attractive.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 25 == 0 {
        score -= 8.0;
    }
    if pr % 50 == 0 {
        score -= 8.0;
    }
    // Odd/awkward classes are mildly penalized.
    if pr % 2 == 1 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this is a chaining opportunity - reward it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item can't use this residual: residual becomes dead weight
            score += pr as f64 * 0.15;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): prefer it only when post_residual would
    // be large (i.e., item is small relative to capacity) or no good fits exist.
    if bin_residual == bin_capacity {
        // Base bias so a new bin is usually worse than a decent fit...
        score += 25.0;
        // ...but a fresh bin gives full flexibility for future items.
        score -= open_bins_count as f64 * 0.5;
        // If the item leaves a very large residual, new bin is fine.
        if post_residual >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Prefer fuller bins overall: compare residual to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.2;

