    let fill = 1.0 - post / cap;
    score += 12.0 * progress * (1.0 - fill).powi(3);

    // Reward near-perfect fits with a smooth quadratic bonus.
    if post <= 5 {
        score -= 8.0 * (1.0 - post as f64 / 6.0).powi(2);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
