        }
    }

    // Penalize bins far from mean residual (fragmentation smoothing), smooth term.
    let dev = (post - mean_residual).abs();
    score += 0.02 * dev * dev / (1.0 + progress);

    // New-bin candidate: neutral-ish baseline that competes with poor fits.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly when many bins are open and
        // the item would leave a tight fit elsewhere; smoothed via progress.
        score = cap * (0.35 + 0.35 * progress) + 0.008 * cap * cap * 0.0;
        score += 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals falling into "dead zones" that few item sizes can fill.
    // Items are 1..=100, so a residual r is fillable if some future item <= r arrives.
    // Small residuals (< 10-ish) are nearly dead; large residuals are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // nearly unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 34 {
        score += 10.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with the classic size grid; reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd residuals slightly penalized (less likely to be exactly filled).
    if post_residual % 2 == 1 {
        score += 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with next item: if the next item exactly fills the post residual,
    // strongly favor this bin (chain completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
