    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward if the next item also fits into the leftover space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual as f64 - next_item_size as f64).min(30.0);
    }
    // Penalize dead space that the next item cannot use.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64 - (bin_residual as f64 - next_item_size as f64).max(0.0);
        score += waste.max(0.0) * 2.0;
    }

    // Prefer bins tighter than the mean residual (well-filled bins).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Mild penalty for opening a new bin early in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize creating dead space that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room that the next item can still fill.
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Reward filling bins that are already tight (relative fill ratio).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Penalize bins that deviate far above the mean residual (fragmentation risk).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or the stream is early (long horizon to amortize).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= bin_capacity / 2 { 5.0 } else { 0.0 };
        score += 15.0 - large_item_bonus - (1.0 - progress) * 10.0;
        // Never open a new bin if a perfect fit exists elsewhere; the -1000
        // above already handles that, but add safety margin for near-perfect.
        if post_residual <= 2 {
            score += 500.0;
        }
    }

    // Mild late-stream pressure to consolidate into fewest bins.
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks at 0.5, smooth bell in [0,1]
    score -= 12.0 * norm_pr * norm_pr * (1.0 - norm_pr) * t * cap;

    // Penalize tight fits more strongly as the stream progresses (dead space matters late)
    score += 8.0 * norm_pr * norm_pr * progress * cap;

    // Reward near-perfect fits with a smooth cubic dip
    let perfect = 1.0 - norm_pr;
    score -= 20.0 * perfect * perfect * perfect * cap;

    // Lookahead coupling: smooth quadratic interaction with next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 10.0 * fit_next * nxt * (1.0 - progress);
        score += 6.0 * (1.0 - fit_next) * nxt * progress;
    }

    // Last-chance bonus: smooth sigmoid-like emphasis when few fitting bins
    let scarcity = 1.0 / fitting_bins_count as f64;
    score -= 15.0 * scarcity * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify leftover space ---
    // Classes: perfect fill (0), small dead zone (1..=10), medium (11..=25),
    // large usable (26..=50), half-empty (>50).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -30.0 // perfect packing: strongly favored
    } else if pr <= 10 {
        12.0 // small dead space: nearly useless
    } else if pr <= 25 {
        3.0 // moderate dead space
    } else if pr <= 50 {
        -6.0 // still broadly usable
    } else {
        -10.0 // more than half empty: very flexible
    };
    score += class_penalty;

    // --- Modulo arithmetic on post_residual: align leftovers with common item sizes ---
    // Items 1..100; harmonic residues mod 10, 25, 50 capture common size alignments.
    let m10 = pr % 10;
    let m25 = pr % 25;
    let m50 = pr % 50;
    if m10 == 0 { score -= 4.0; }
    if m25 == 0 { score -= 3.0; }
    if m50 == 0 { score -= 2.0; }
    // Residues close to zero are more reachable by small items; penalize odd residues.
    if m10 >= 1 && m10 <= 4 { score -= 1.5; }
    if m10 >= 6 && m10 <= 9 { score += 1.5; }

    // --- Integer-division thresholds: can a "typical" next item fit? ---
    // A leftover that exactly matches the lookahead item is golden.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0; // exact fit for the known next item
        } else if pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.3; // close fits favored
        } else {
            score += (next_item_size - pr) as f64 * 0.4; // can't host next item
        }
        // Harmonic bucket of the lookahead item (mod 10 classes)
        let nb = (next_item_size / 10).max(1);
        let pb = pr / 10;
        if pb >= nb { score -= 2.0 * (pb - nb) as f64; }
    } else {
        // Last item: only perfect fill matters, otherwise everything is waste.
        score = pr as f64 * 2.0 - 20.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && pr < bin_capacity as u32 {
        score -= 15.0;
    }

    // --- New-bin candidate handling: only prefer a fresh bin when nothing fits well ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of consuming a whole new bin.
        score = cap * 0.55;
        // During early stream, opening bins is cheap/necessary.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins already fit the item, opening new is wasteful.
        score += 8.0 * fitting_bins_count as f64;
        // Small items don't justify a new bin.
        if item_size <= 30 { score += 15.0; }
    }

    // --- Crowd penalty: too many open bins with scattered residuals ---
    if open_bins_count > 8 {
        score += 0.05 * (open_bins_count as f64 - 8.0);
    }

    // --- Mean-residual coupling: prefer bins near the fleet mean (balanced draining) ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable dead space (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect-fit lookahead: if next item exactly fills post_residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits here: mild reward, keeps bin useful
        score -= (next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: discourage opening new bins when few bins open,
    // encourage consolidating when many bins are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Prefer bins with residual above mean (keep balanced set of usable bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: only attractive if current item is huge relative to
    // typical residuals and no good fit exists
    if bin_residual == bin_capacity {
        if item_size > 60 {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect lookahead fit: place here, this bin becomes ideally packed next step
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit after this placement: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack / 10.0);
        } else {
            // Dead space: next item cannot use the leftover
            score += 15.0;
        }
    }

    // Reward tight fits of the current item
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize leaving residual far below mean residual (wasting usable space elsewhere)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when open bins would create bad dead space
    if bin_residual == bin_capacity {
        // baseline preference for reusing bins unless lookahead says otherwise
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<= 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Perfect lookahead pairing: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless open bins are fragmented
    // (mean residual high but this bin's fit is poor) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        // If the stream is nearly done and open bins are very fragmented, opening
        // a fresh bin can be cheaper: relax the penalty.
        if progress > 0.7 && fragmentation > 0.5 {
            score -= 12.0;
        }
        // With many open bins and high mean residual, prefer consolidation instead.
        if open_bins_count > 4 && fragmentation > 0.35 {
            score += 10.0;
        }
    }

    // Mild preference for filling larger-residual bins when many are open,
    // to keep the residual distribution balanced.
    if bin_residual != bin_capacity {
        let gap = bin_residual as f64 - mean_residual;
        score += 0.08 * gap;
    }

    // Late-stream urgency: squeeze into existing bins as total_items approaches.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with polynomial coupling to stream progress.
    // Early on, prefer tight fills (low post_residual); late, residual matters less.
    let progress_weight = 1.0 + 0.8 * progress * progress;
    let mut score = pr * progress_weight;

    // Quadratic dead-space penalty: small-but-nonzero residuals are wasteful.
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Reward near-perfect fits with a smooth bump around norm_pr ~ 0.
    score -= 20.0 * (-norm_pr * 8.0) * (1.0 - progress * 0.5);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Mean-residual coupling: penalize bins far from the fleet mean (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for proliferating bins early.
    score += open_bins_count as f64 * progress * 0.5;

    // New-bin candidate: keep it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify dead space by integer division thresholds ---
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Perfect fit reward (harmonic class 0)
    if post == 0 {
        score -= 60.0;
    } else if post < eighth {
        // Tiny unusable sliver: penalize as dead space
        score += 25.0 + (eighth - post) as f64 * 0.5;
    } else if post < quarter {
        // Awkward quarter-class residual: mild penalty
        score += 10.0;
    } else if post < bin_capacity / 2 {
        // Half-class residual: neutral-ish, slight reward
        score -= 5.0;
    } else {
        // Large residual (still roomy bin): reward keeping usable space
        score -= 15.0;
    }

    // Modulo-arithmetic coupling: residuals divisible by common item sizes are reusable
    if post > 0 && next_item_size > 0 {
        if post % next_item_size == 0 {
            score -= 20.0; // next item would tile this bin perfectly
        } else if next_item_size <= post {
            let k = post / next_item_size;
            // reward proportional to how many copies of next item fit
            score -= 6.0 * k as f64;
        } else {
            // next item cannot fit in this bin's post-residual: penalize more
            // if the gap is small (bin becomes stranded)
            score += 12.0;
        }
    }

    // Lookahead: if next item fits in residual BEFORE this placement it might
    // belong here instead; penalize consuming a bin that would host next item exactly
    if next_item_size > 0 && bin_residual == next_item_size && post != 0 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, tighten the race: prefer smallest post_residual
        score -= 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if the current item would leave a harmonic-friendly residual
        // (post_residual divisible into quarters), soften the penalty
        if post % quarter == 0 || post % eighth == 0 {
            score -= 15.0;
        }
        // late in the stream with many open bins, opening fresh is less bad
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: placing into a bin already below mean residual
    // concentrates waste; prefer bins above the mean (keeps small bins for small items)
    if (post_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Stream progression: as stream ends, waste matters less than bin count
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for any item are pure waste.
    // Penalize unusable gaps heavily; reward residuals that can still hold plausible items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: nothing can ever fit here
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, zero waste
    } else {
        // Usable gap: reward proportionally, but slightly favor tighter fits.
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Nonlinear dead-space curve: gaps just below common item sizes are especially bad.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 40.0 {
        // penalize gaps that fall just short of typical item sizes
        let near_miss = (gap - (gap / 10.0).floor() * 10.0) / 10.0; // closeness to a multiple of 10
        score += 10.0 * (1.0 - near_miss);
    }

    // Open-bins pressure: when many bins are open, prefer consolidation into existing ones.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    if bin_residual != bin_capacity {
        score -= 12.0 * open_pressure;
    } else {
        // New bin candidate: only attractive when current bins are crowded or poor fits.
        score += 5.0 * open_pressure;
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // blocks the next item
    }

    // Stream progression: early on, tolerate more open bins; later, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: placing into a bin below mean residual reduces fragmentation.
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward when the next item fits the post-residual exactly ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Reward tight 2-step chains: smaller leftover after next item is better
            score -= (bin_capacity as f64 - slack_after_next as f64) * 0.9;
            if slack_after_next == 0 {
                // Perfect 2-step fill: strongly favored
                score -= 60.0;
            } else if slack_after_next <= 10 {
                // Near-perfect chain
                score -= 25.0;
            } else {
                // Larger slack after next item: mild penalty scaled by slack
                score += slack_after_next as f64 * 0.35;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space creation
            score += 12.0 + (next_item_size as f64 - post_residual as f64).min(40.0) * 0.3;
        }
    } else {
        // Last item: purely minimize post residual
        score -= 20.0;
    }

    // --- Relative to mean residual: prefer bins whose post-residual sits near the mean ---
    // (keeps residuals homogeneous, improving future fit chances)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // --- Last-chance bin: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling: opening a new bin should only win if the best
    //     existing fit is poor (large post residual) or late in the stream ---
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Fresh empty bin: baseline score = its post residual (= capacity - item),
        // plus a penalty that shrinks as the stream progresses / many bins are open
        let open_penalty = 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        score += open_penalty;
        // But if next item is large and would fit a fresh bin well, soften penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // --- Early stream: slightly discourage fragmenting bins when few bins are open ---
    if open_bins_count <= 2 && bin_residual < bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    // Small deterministic tie-breaker favoring tighter fits
    score += (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space thresholds asymmetrically:
    // post_residual in 1..10 is "dead space" that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward using bins with larger residuals when the item is big
    // (big items should go into emptier bins).
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap * (1.0 - fill_fraction);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item would have fit here but not after placement: penalize.
            score += 10.0 * (1.0 - fill_fraction);
        }
    }

    // Time horizon: early in the stream, be conservative about opening new bins
    // (favor filling existing ones); late in the stream, tightness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - fit_ratio);

    // If many bins are open, encourage consolidating into existing bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the item is huge or no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: open a new bin
        } else {
            // Prefer new bin only for very large items that would leave
            // unusable slivers in existing bins.
            let sliver_risk = (post_residual as f64) / bin_capacity as f64;
            score += 18.0 * (1.0 - sliver_risk) + 10.0 * fill_fraction;
            // Late in stream, prefer existing bins to avoid leftover spread.
            score += 15.0 * progress;
        }
    }

    // Mild noise-free tie-break: prefer bins with residual closest to item size.
    score += 0.05 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer tight fits (low post residual), scaled non-linearly.
    let mut score = pr_norm * pr_norm * 40.0 + pr_norm * 20.0;

    // Reward high fill ratio (item consumes most of the residual) via smooth cubic coupling.
    let fr = fit_ratio.min(1.0);
    score -= fr * fr * fr * 30.0;

    // Stream progress interaction: as stream progresses, penalize leftover dead space more strongly.
    let prog_term = progress * progress * (1.0 - progress);
    score += prog_term * pr_norm * 60.0;

    // Coupling with mean residual: bins far from mean residual get a mild penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * 5.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + progress * 25.0;
    }

    // Lookahead: if next item fits exactly into post residual, reward heavily (smooth quadratic).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= (1.0 - gap * gap) * 15.0;
        } else {
            // Next item won't fit here: penalize leaving large residual that may become dead space.
            score += (nx / cap) * 8.0;
        }
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" residue classes are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible follow-up item are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    }

    // Modulo arithmetic on post_residual: residuals near multiples of 10
    // (harmonic anchors of the capacity) are more reusable.
    let anchor = post_residual % 10;
    score -= (5 - ((anchor as i32) - 5).abs()) as f64 * 0.8;

    // Integer-division thresholds: classify post_residual into coarse bands.
    let band = post_residual / 25; // 0..4
    score -= band as f64 * 3.0;

    // Fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 25.0;

    // Perfect-fit harmonic classes: post_residual in {0, 20, 25, 30, 40, 50}
    // pairs well with common item sizes.
    let perfect: [u32; 6] = [0, 20, 25, 30, 40, 50];
    if perfect.contains(&post_residual) {
        score -= 12.0;
    }

    // Lookahead coupling: reward residuals that exactly or nearly fit the
    // next item (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / cap) * 10.0;
        } else {
            // next item cannot fit here: penalize by the mismatch
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are nearly exhausted or the item is huge.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 55.0 - pressure * 60.0 + (item_size as f64 / cap) * 20.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual alignment: prefer bins close to the fleet's mean residual
    // (keeps the bin pool homogeneous in harmonic terms).
    score += (pr - mean_residual).abs() * 0.25;

    // Slight late-stream conservatism: keep bins tighter as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Smooth penalty for tight-but-usable residuals being squandered.
        score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above good fits.
        score = bin_capacity as f64 * 0.9 + 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 1 {
            // Opening a new bin when only one bin fits is very bad.
            score += 50.0;
        }
    } else {
        score -= 0.3 * open_bins_count as f64;
    }

    // Mean residual coupling: bins deviating far below mean residual are tighter fits; prefer them.
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_next = post_residual >= next_item_size;
        if fit_next {
            // Next item fits perfectly after this placement -> strong reward
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit -> penalize dead space
            score += 8.0 + gap * 0.15;
        }
        // Perfect 2-chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: minimize residual waste directly
        score -= 5.0;
    }

    // Prefer bins tighter than the mean (good fits), penalize loose bins
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 12.0;
        // New bin is attractive only if current item nearly fills it and next item is large
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.9 {
            score -= 15.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 4.0;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // Penalize large unusable dead space: residuals that are too small
    // for a typical future item are "dead".
    let dead = (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;
    score += 0.6 * dead;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.15 * next_fit as f64;
    }
    // If next item would NOT fit after placement, penalize slightly
    // (we waste the residual for the lookahead item).
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Give the empty bin a base cost
    // that grows with the number of open bins (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to mean residual, opening
        // a fresh bin may be reasonable: reduce the penalty.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, keep bins open and flexible
    // (favor smaller post_residual less aggressively); late in the
    // stream, close bins out tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - fill);

    // Slight preference to spread load when many bins are open with
    // high mean residual (avoid fragmentation pile-up).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with smooth polynomial shaping.
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Non-linear coupling of wasted space with stream progress:
    // early on, small waste is fine; later, waste becomes more costly.
    let waste_penalty = norm_post * norm_post * (0.5 + 3.0 * progress * progress);
    score += waste_penalty * cap;

    // Reward tight fits (small post_residual) increasingly as stream advances.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (2.0 + 6.0 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * progress;
    }

    // Smooth interaction with mean residual: prefer bins close to mean residual
    // (balanced usage), penalized smoothly by deviation.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 5.0;

    // Lookahead: reward leaving space for the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx) / cap;
        let gap01 = if gap < 0.0 { 0.0 } else { gap };
        score -= gap01 * (1.0 - gap01) * (3.0 + 4.0 * progress);
    }

    // Mild preference to fill existing bins rather than open new ones,
    // scaled smoothly by number of open bins.
    score += (open_bins_count as f64).ln() * 0.3 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "dead zone" classes: too small to be useful (<= 20)
    if post_residual > 0 && post_residual <= 20 {
        score += 40.0 * (1.0 - frac);
    }
    // Reward residuals that are large "harmonic" classes: multiples of 25 or 50
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // reward proportionally, penalize waste beyond next item
            let slack = post_residual - next_item_size;
            score -= 30.0 - (slack as f64).min(30.0);
            if slack > 0 && slack <= 10 {
                score += 10.0; // tiny dead space after next item is bad
            }
        } else {
            // next item cannot fit here: penalize by how badly it misses
            let miss = next_item_size - post_residual;
            score += (miss as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: discourage opening new bins unless current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // baseline score for a fresh bin: its residual is capacity, add fixed penalty
        score += 55.0 + 30.0 * (1.0 - progress);
        // allow new bin when open bins have low mean residual (fragmented state)
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for bins tighter than the mean (good fill balance)
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1) are already captured by post_residual,
    // but gaps that are small relative to typical item sizes are worthless.
    // Penalize the "unusable band" hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium dead space (10..30) is risky: only items <= that size fit.
    if post_residual >= 10 && post_residual < 30 {
        score += 1.2 * (30.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; penalize opening new bins when pressure is high.
    let pressure = open_bins_count as f64 / 20.0;
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * pressure;
    } else {
        score -= 3.0 * pressure;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent (chains two items).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover -> dead space likely
        score += 8.0;
    }

    // Mean-residual coupling: bins far below the mean residual are the
    // "emptiest" fits; prefer filling bins that deviate least from the mean
    // to keep a balanced set of usable residuals.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by tightness
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item does not fit: penalize large leftover dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred targets
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Late in the stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Discourage opening a new bin when a decent fit exists in open bins
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual > 0 {
        // Dead space is worse if it's below typical item sizes.
        let dead = post_residual as f64;
        if dead < 30.0 {
            score += (30.0 - dead) * 0.6;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_fit = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_fit as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving a big gap it almost fits.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += gap * 0.5;
            }
        }
    } else {
        // Last item: just fill anything.
        score -= 5.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the emptiest bins to consolidate.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be conservative with new bins (long future),
    // late in the stream, filling existing bins matters more anyway.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate (bin_residual == bin_capacity): opening a new bin is only
    // attractive when the fit into existing bins is poor. Base new-bin score already
    // includes post_residual = capacity - item_size; adjust with global state.
    if bin_residual == bin_capacity {
        // Penalty grows with number of open bins having usable residual.
        score += 20.0 * (open_bins_count as f64).ln().max(0.0);
        // Early on, discourage new bins more (plenty of future items to fill them,
        // but consolidation keeps options open).
        score += 10.0 * (1.0 - progress);
        // If mean residual across open bins can't accommodate this item well,
        // opening a new bin becomes reasonable: reduce penalty.
        if (mean_residual < item_size as f64) {
            score -= 30.0;
        }
        // If next item is large and wouldn't fit typical residual, a fresh bin
        // preserves capacity for it.
        if next_item_size > 0 && mean_residual > 0.0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight preference for bins with larger residual consumed
        // efficiently; also mild bonus for reducing open-bin spread.
        score += 0.1 * ((mean_residual - bin_residual as f64).abs());
    }

    // Global consolidation pressure: many open bins -> favor filling existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Non-linear decay of residual value as the stream progresses:
    // late in the stream, leftover space is less likely to be usable,
    // so penalize large residuals more strongly.
    let progress_coupling = norm_pr * norm_pr * (0.5 + progress) * cap;
    score += 0.35 * progress_coupling;

    // Reward tight fits, more aggressively early (bins stay flexible)
    // and less aggressively late (tight fits are the only thing that matters).
    let tightness = (bin_residual - item_size) as f64 / cap;
    let tight_bonus = (1.0 - tightness).powi(3) * cap;
    score -= (0.6 - 0.25 * progress) * tight_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.5 * cap * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fill_ratio = nxt / (pr + 1.0);
            score -= 0.3 * cap * fill_ratio * (1.0 - progress * 0.5);
        } else {
            // Dead space for the known next item: penalize proportionally.
            let waste = (nxt - pr) / cap;
            score += 0.25 * cap * waste * waste;
        }
    }

    // Prefer bins whose residual is close to the mean residual (balance),
    // with a smooth quadratic deviation term.
    let dev = (pr - mean_residual) / cap;
    score += 0.2 * cap * dev * dev;

    // New-bin candidate: make it moderately attractive only when residuals
    // across open bins are already small (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let mean_pressure = mean_residual / cap;
        score = cap * (0.9 - 0.4 * progress) - 0.3 * cap * (1.0 - mean_pressure);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "useful"
    // for future items (multiples of common size classes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: exact fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 2: residual in small "dead zone" (1..=9) is nearly useless waste.
    if post_residual >= 1 && post_residual <= 9 {
        score += 30.0;
    }

    // Class 3: residual divisible by common item granularity (10) is reusable.
    if post_residual % 10 == 0 {
        score -= 25.0;
    }
    // Half-class: divisible by 5 still decent.
    else if post_residual % 5 == 0 {
        score -= 10.0;
    }

    // Class 4: residual that exactly fits the lookahead item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // leftover after also placing next item; reward proportionally
            let two_left = (post_residual - next_item_size) as f64;
            if two_left % 10 == 0 {
                score -= 40.0;
            }
            score -= 15.0 * (1.0 - two_left / cap);
        } else {
            // next item cannot fit here: penalize slightly, worse if gap is tiny
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * gap.min(50.0);
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual
    // is truly unusable dead space. An empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; make it slightly worse than a decent fit
        // but better than wasting a large residual on a tiny item.
        score = cap + 5.0;
        // If the item is small relative to residual and some open bin is nearly
        // empty of usable space, opening new is fine (handled by comparison).
        if item_size <= 20 && fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper (more future items to pair).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // Penalize placing small items into large residuals (waste of space).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.3 {
            score += 25.0 * (0.3 - fill_ratio) * 10.0;
        }
        // Reward good fill ratio.
        if fill_ratio > 0.8 {
            score -= 20.0;
        }
    }

    // Mild preference to spread load when many bins are open with slack.
    if (mean_residual - pr).abs() < 5.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0; // tiny gaps heavily penalized
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward using bins whose residual is large enough to still be useful afterward.
    if post_residual >= 10 && post_residual <= 80 {
        score -= 15.0; // keeps bin reusable for typical future items
    }

    // Penalize leaving a gap that exactly matches nothing useful:
    // prefer post_residual >= next_item_size so the next item can also fit here.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0; // lookahead chain fit: excellent
        } else if post_residual > 0 {
            score += 10.0; // next item cannot chain into this bin
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin;
    // make the empty-bin candidate less attractive when bins are plentiful.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        score = (bin_capacity - item_size) as f64;
        score += open_bins_count as f64 * 8.0; // pressure to fill existing bins
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // a fresh bin can chain the next item
        }
    } else {
        // Existing-bin bonus scales down as open bin count grows (consolidation).
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Late-stream tightening: near the end, avoid leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step chain: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 45.0;
        } else if diff <= 5 {
            score -= 25.0 - diff as f64 * 3.0;
        } else if diff <= 15 {
            score -= 8.0 - diff as f64 * 0.4;
        }

        // Penalize leaving dead space that neither the next item nor anything small can use.
        if post_residual < 10 && post_residual > 0 {
            score += 6.0; // small useless sliver
        }

        // If next item cannot fit this bin's post_residual, mild penalty proportional to gap.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: maximize fill, i.e., minimize post_residual.
        score += post_residual as f64 * 0.5;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well or bin is fresh.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 10.0 * progress;
        // If the next item perfectly chains into a fresh bin, encourage opening.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 40.0;
        }
        // Discourage opening when a good fit exists elsewhere.
        if post_residual <= 15 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Reward near-perfect fills generally.
    if post_residual <= 2 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post / cap);
    score -= 60.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Base cost of opening a new bin; reduced late in stream or when
        // existing residuals are large (plenty of slack overall).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let slack = (mean_residual / cap).clamp(0.0, 1.0);
        score += 35.0 - 30.0 * progress * slack - 10.0 * (1.0 - slack);
        // Discourage new bin if a large next item could use this empty bin.
        if next_item_size as f64 >= 0.6 * cap {
            score += 15.0;
        }
    }

    // Lookahead coupling: reward bins whose residual after placement can
    // still hold the next item (keeps bins usable), penalize near-misses.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 8.0;
        } else if post > 0.0 && nx - post <= 15.0 {
            score += 10.0 * (1.0 - (nx - post) / 15.0);
        }
    }

    // Congestion pressure: many open bins with low mean residual -> prefer
    // packing into existing bins rather than spreading.
    if open_bins_count > 3 {
        let pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 12.0 * pressure * ((open_bins_count as f64).ln() / (10.0f64).ln()).min(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate large residuals; late, penalize dead space quadratically.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += 12.0 * progress_poly * (pr / cap) * (pr / cap) * cap;

    // Reward tight fits: subtract for small post_residual, amplified by progress.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * (0.5 + progress_poly);

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (pr - nxt) / cap;
            score -= 6.0 * chain_fit * (0.4 + 0.6 * progress_poly);
        } else {
            // Next item won't fit here; penalize proportionally to wasted residual.
            score += 4.0 * (pr / cap) * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress_poly);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.02 * (open_bins_count as f64) * ((pr - mean_residual).abs() / cap);

    // New-bin candidate: prefer it only when no good fit exists (high residual everywhere).
    if bin_residual == bin_capacity {
        score = cap - 2.0 * progress_poly * (mean_residual / cap) * cap;
        if fitting_bins_count == 1 {
            score += 20.0; // never open new bin if this is the only fitting one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division thresholds
    let cls = post_residual / 10; // 0..=10 harmonic class
    let frac = post_residual as f64 / cap;

    // Penalize dead-space classes: residuals that are small but not zero are worst
    score += match cls {
        0 => if post_residual == 0 { -30.0 } else { 15.0 }, // perfect fit reward
        1 => 25.0, // 1..9 nearly unusable
        2 => 18.0,
        3 => 10.0,
        4 => 5.0,
        5 => 0.0,
        6 => -2.0,
        7 => -4.0,
        8 => -6.0,
        9 => -8.0,
        _ => -10.0, // mostly-empty bin, keep it flexible
    };

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty if we leave awkward residual
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill = item_size as f64 / cap;
        // new bin good if it captures a big item cleanly and few fitting bins exist
        score = 60.0 - 45.0 * fill - 8.0 * (fitting_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
        // late in stream, prefer consolidating into open bins
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // prefer tighter fits among open bins
        score -= 10.0 * (1.0 - frac);
        // spread load: mildly favor bins below mean residual
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Modulo coupling: reward residuals that are multiples of common item granularities
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..9)
    // are unusable gaps -> strong penalty so the optimizer avoids creating them.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits: the smaller the post_residual above the dead zone,
    // the better. Quadratic tightening of the base term.
    score += 0.02 * (post_residual as f64).powi(2) / 100.0;

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (i.e., fuller bins), penalize emptying sparse bins further.
    score += 0.35 * ((bin_residual as f64 - mean_residual).abs()) * 0.1
        - 0.5 * (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate (bin_residual == bin_capacity) gets penalized
    // proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // Slight reward for using existing bins when bin count is high.
        score -= 0.4 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward
    // for reserving this bin accordingly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Late-stream tightening: as the stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact match between post_residual
    // and the next item's size (this bin will be perfectly filled in two steps).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 40.0; // perfect two-item fill
        } else if gap <= 5.0 {
            score -= 25.0 - gap * 3.0;
        } else if gap <= 15.0 {
            score -= 10.0 - gap * 0.5;
        } else {
            // next item cannot use the leftover well; penalize proportionally
            score += gap * 0.3;
        }

        // If the next item fits exactly in the CURRENT residual (before placement),
        // maybe we should keep this bin untouched for it — mild penalty for consuming it.
        if next_item_size == bin_residual {
            score += 15.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here anyway; filling this bin now is good
            score -= 5.0;
        }
    } else {
        // Last item: prefer minimal leftover, i.e., tightest fit.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual below the mean are "fuller";
    // prefer filling those further to compact waste.
    let r = post_residual as f64;
    let mean_gap = r - mean_residual;
    score += mean_gap * 0.25;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Dead-space penalty: leftover that is too small to hold even the smallest
    // plausible item (<= 10) is pure waste; heavily penalize.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when no open bin offers a decent fit — i.e., when this
    // call is for the empty bin itself and the fit is loose.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes (capacity - item_size) immediately.
        // Make new bins moderately unattractive unless lookahead suggests a
        // large residual is valuable (next item large).
        let waste = (bin_capacity - item_size) as f64;
        score += 8.0 + waste * 0.35;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0; // new bin can host the next item too
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += open_bins_count as f64 * 0.4 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead space wedge
    } else if post_residual >= 10 && post_residual < 34 {
        score += 3.0; // moderately awkward residual
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size {
            // next item could go here instead; mild penalty for consuming that option
            score += 2.0;
        }
        // Perfect pairing: post residual exactly matches next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: only open a new bin when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        // Opening a new bin is penalized by how many open bins exist (avoid fragmentation),
        // but rewarded early in the stream when item is small.
        score += 18.0 * (1.0 - progress);
        score += open_bins_count as f64 * 1.5;
        score -= 10.0 * (1.0 - fit_quality);
        // If no open bin fits well (this call is the new bin itself), the baseline
        // post_residual = capacity - item_size already reflects the leftover.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap * (open_bins_count as f64).ln().max(1.0);

    // Late-stream pressure: as stream ends, avoid opening bins and prefer dense packing.
    let urgency = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * urgency * (bin_residual as f64 / bin_capacity as f64);

    // Slight preference for bins whose residual is close to item size (exact-ish fits).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smooth Hermite ramp in [0,1]
    // Tighter packing favored as stream progresses: penalize residual quadratically
    score += poly * (pr / cap) * (pr / cap) * 30.0;

    // Reward filling bins nearly exactly, smoothly scaled by progress
    let tightness = 1.0 - (pr / cap);
    score -= poly * tightness * tightness * 10.0;

    // Lookahead coupling: if next item fits the post-residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + poly * 4.0;
    } else if next_item_size > 0 {
        // penalize dead space that blocks the next item, smoothly
        let waste = (next_item_size as f64 - pr).min(cap);
        score += (waste / cap) * 8.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 + poly * 10.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - pr) * 0.05;

    // New-bin candidate: penalize mildly so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + poly * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/2, 1/4, 1/5 of C)
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;

    // Reward placements landing on harmonic boundaries (clean splits)
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else {
        if post_residual <= quarter {
            score -= 6.0;
        } else if post_residual == fifth {
            score -= 5.0;
        } else if post_residual == quarter {
            score -= 5.0;
        } else if post_residual == half {
            score -= 4.0;
        }
    }

    // Modulo-10 harmonic class: small post_residuals divisible by 10 pair well
    // with the 10-multiple item class; odd/prime residuals are dead space.
    let mod10 = post_residual % 10;
    if mod10 == 0 && post_residual > 0 {
        score -= 3.0;
    } else if mod10 != 0 {
        score += (10 - mod10) as f64 * 0.4; // penalize non-aligned dead space
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // extra reward if next item also lands on a harmonic residual
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 2.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to wasted potential
        score += 2.0;
    }

    // Integer-division threshold: post_residual / item_size ratio classes
    if item_size > 0 {
        let ratio = post_residual / item_size;
        if ratio >= 2 {
            score -= 4.0; // bin can host >=2 more of this class
        }
    }

    // Last-chance bin: strongly prefer using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current residual is tiny
    // or the fit is very poor (large post_residual with small item).
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= half && item_size < fifth {
            score -= 25.0; // opening is fine when this item is small relative to fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits, must open
        }
    }

    // Stream progression: early on, be picky about tight fits; later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (post_residual as f64) * 0.1;
    score += progress * (open_bins_count as f64) * 0.3;

    // Mean residual coupling: if this bin is below mean residual, prefer filling it
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (min size 1, but realistically small gaps are wasted)
    // are heavily penalized. Gap in (0, 10] is near-unusable "dead space".
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after this placement; slight penalty
        // proportional to how much we block it.
        score += 8.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; favor
    // filling existing bins and penalize opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 6.0 * pressure;

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 30.0;
        // But if this bin would be nearly empty anyway (item is large),
        // a new bin is reasonable.
        score -= 0.15 * item_size as f64;
        // If existing bins are congested (low mean residual), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild progression coupling: late in the stream, be more conservative
    // about wasted space.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits after this placement — good chaining
            score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit; penalize wasted post_residual scaled by its size
            score += 0.3 * post_residual as f64;
            // small post_residual unusable by next item is mild dead space
            if post_residual < next_item_size && post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average when lookahead is bad
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.2 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 120.0 - 0.8 * item_size as f64;
    }

    // Early in stream: slightly prefer filling existing bins to build density
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: square the post-residual for non-linear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Last-chance bin: heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += 6.0 * (waste / 100.0);
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: mildly penalize by default, but allow opening
    // a new bin when existing bins would leave large dead space or the item
    // would be a poor fit everywhere.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (exploration).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty *= 1.0 + 1.5 * progress;
        // If no open bin fits well, opening is attractive.
        if fitting_bins_count == 0 || (post_residual as f64) > 0.35 * bin_capacity as f64 {
            new_bin_penalty -= 30.0;
        }
        score += new_bin_penalty;
    }

    // Global state coupling: if mean residual is high, prefer consolidating
    // into bins with residual close to the mean (balance spreading).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * (dev / bin_capacity as f64);

    // Prefer larger residual bins slightly (put items where space exists),
    // scaled down as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Tight fits are increasingly valuable as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= (bin_residual as f64 - pr) * (0.35 + 0.45 * progress) * tightness * tightness;

    // Penalize dead space that no plausible future item can use (smooth ramp)
    let dead = (pr - next_item_size as f64).max(0.0);
    score += 0.5 * dead * dead / cap * (0.5 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.6 + 0.4 * progress);
    }

    // Mild load-balancing: avoid draining bins far below mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead synergy: reward if next item fits snugly into resulting residual
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let gap = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - gap / cap) * (0.5 + 0.5 * progress);
    }

    // Slight preference for consolidating into existing bins vs. opening new ones
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into "clean" classes
    // (0, 5, 10, 20, 25, 50) are reusable by common item sizes; odd/prime residues are dead space.
    let pr = post_residual as u32;
    let class_bonus: f64 = match pr {
        0 => 12.0,
        5 | 10 | 20 | 25 | 50 => 6.0,
        _ if pr % 10 == 0 => 4.0,
        _ if pr % 5 == 0 => 2.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Perfect fit is always excellent.
    if pr == 0 {
        score -= 30.0;
    }

    // Integer-division threshold: post_residual bucketed by fifths of capacity.
    let fifth = (pr * 5) / bin_capacity.max(1);
    score -= (4 - fifth.min(4)) as f64 * 1.5;

    // Lookahead coupling: reward if next item can fit exactly into the post-residual;
    // penalize if post-residual is in the awkward gap where next_item_size almost fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: keep this bin alive with a compatible residue
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
        } else if post_residual > 0 && next_item_size - post_residual <= 10 {
            // awkward near-miss residue: dead space trap
            score += 6.0;
        }
        // modulo-harmonic: next item's residue class vs this bin's residue class
        if (next_item_size % 10) == (pr % 10) && pr > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is large
    // or all existing fits are terrible (large post_residual).
    if bin_residual == bin_capacity {
        // fresh bin: baseline cost of a new bin grows with how many bins are already open
        score += 10.0 + 0.5 * open_bins_count as f64;
        if item_size >= 50 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
    }

    // Slight preference for filling fuller bins early in the stream; late in the stream,
    // be greedy about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0 * (1.0 - (post_residual as f64) / cap);

    // Mean-residual context: if the fleet is full, prefer tight placements harder.
    if (post_residual as f64) > mean_residual {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // (1..=100 range, so anything < 1 is impossible; but tiny gaps relative to
    // likely next item sizes are waste). Penalize "unusable" gaps hard.
    let dead_threshold = if next_item_size > 0 { next_item_size as f64 } else { 20.0 };
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in post_residual, mild penalty for wasting the gap
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Open-bins pressure: discourage opening new bins when few bins are open
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Base cost of opening a new bin, softened as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 15.0 * progress;
        // Extra pressure if there are fitting alternatives
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(4.0);
        }
    } else {
        // Reward using existing bins, more so when many are open
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !new_bin_candidate {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins with residual close to (below) the mean,
    // i.e. consolidate fragmentation into fewer bins
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Slight preference for larger post_residual overall (keeps flexibility)
    score -= post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
