    }

    // New-bin candidate: only attractive when current fit is very poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 70.0; // fresh bin gives exact lookahead fit
        }
    }

    // Mild consolidation pressure: fewer open bins -> prefer already-open bins.
    score -= open_bins_count as f64 * 0.05;

