        score -= 50.0;
    }

    // Penalize dead space that no future item (size >= 10... but unknown dist, use small threshold) can use.
    if post_residual > 0 && post_residual < 20 {
        score += 6.0; // awkward sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, heavily favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it moderately
    // attractive only when open bins have poor fits or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 45.0 + 20.0 * (1.0 - progress) - 5.0 * crowding.min(4.0);
        // If next item is huge, an empty bin is valuable for it; slightly less eager to consume it now.
        if next_item_size >= 70 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins),
    // keeping large-residual bins free for large future items.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Mild penalty for spreading across too many open bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual < bin_capacity {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let base = post_norm.powi(2) * (1.0 + progress) + post_norm * (1.0 - progress).powi(2);

    // Reward tight fits: subtract more as post_residual shrinks, weighted by progress.
    let tight_bonus = (1.0 - post_norm).powi(3) * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual across open bins.
    let dead_pen = ((post - mean_residual) / cap).abs().powi(2) * 0.3;

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    let lookahead = if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        -0.25 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap)
    } else if next_item_size > 0 {
        0.15
    } else {
        0.0
    };

    // Last-chance fitting bonus: strongly favor the only bin that fits.
    let last_chance = if fitting_bins_count == 1 { -0.8 } else { 0.0 };

    // Mild pressure to prefer existing bins over opening new ones as stream progresses.
    let new_bin_bias = if bin_residual == bin_capacity {
        0.3 + 0.4 * progress
    } else {
        0.0
    };

    let mut score = base - tight_bonus + dead_pen + lookahead + last_chance + new_bin_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction classes. Residuals in "useful" classes (multiples of
    // common item sizes / large enough for small items) get rewarded.
    let pr = post_residual;
    let class = if pr == 0 { 0 }                  // perfect fit: best
        else if pr <= 10 { 1 }                    // nearly dead space
        else if pr % 20 == 0 { 2 }                // aligned with 20-multiples
        else if pr % 10 == 0 { 3 }                // decade-aligned
        else if pr >= 30 { 4 }                    // roomy, reusable
        else { 5 };                               // awkward mid-range

    let class_bonus = match class {
        0 => 40.0,
        1 => -25.0,
        2 => 12.0,
        3 => 8.0,
        4 => 6.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: how many "typical small items" (size ~10)
    // still fit in the leftover? More reusable => better.
    let small_fits = pr / 10;
    score -= small_fits as f64 * 2.0;

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0 + (next_item_size as f64 / cap) * 10.0;
    } else if next_item_size > 0 && next_item_size > pr {
        // next item won't fit here; slight penalty proportional to waste
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should score high (bad) unless
    // no good placement exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.9;
        // If few bins fit the item, opening a new bin is more acceptable
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Early in stream, opening bins is fine (need containers anyway)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // Large items pair well with fresh bins
        if fill_frac > 0.6 {
            score -= 15.0;
        }
    } else {
        // Prefer tighter fits among open bins: reward high fill fraction
        score -= fill_frac * 15.0;
        // Slight preference for bins below mean residual (pack tight bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // If many bins can fit, mild penalty to spread less-desirable fits
        if fitting_bins_count > 3 {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or too small
    // for the typical next item) are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 10u32;
        if post_residual < dead_threshold {
            score += 40.0 * (dead_threshold - post_residual) as f64;
        }
        // Gap too small for the lookahead item -> likely permanent dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.35 * post_residual as f64;
        }
    } else {
        // Perfect closure of a bin is highly desirable.
        score -= 25.0;
    }

    // Reward tight fits (small waste relative to item size).
    score -= 8.0 * (item_size as f64 / (item_size + post_residual).max(1) as f64);

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; becomes attractive only
        // when existing fits are bad (their dead-space penalties dominate).
        score += 30.0 + 6.0 * pressure;
        // Early in the stream a fresh bin is fine; late, be conservative.
        score -= 10.0 * (1.0 - progress);
    } else {
        // Slight reward for consolidating into already-open bins.
        score -= 2.0 + 0.5 * pressure;
    }

    // Mean-residual coupling: if the stream's bins are generally tight
    // (low mean residual), filling this bin well matters more.
    if mean_residual > 0.0 {
        let tightness = 1.0 - (post_residual as f64 / mean_residual).min(2.0) / 2.0;
        score -= 4.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward a post_residual that exactly matches next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match for the next item: strong reward
        if diff < 0.5 {
            score -= 30.0 + 10.0 * (1.0 - progress);
        } else if post_residual as f64 >= nxt {
            // Next item still fits after this placement: mild reward scaled by closeness
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to wasted gap
            score += 8.0 + 0.15 * (nxt - post_residual as f64);
        }
        // Dead space threshold: residuals below 10 are hard to fill (min item size)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // --- Relative-to-mean coupling: prefer bins whose residual is above average ---
    if post_residual as f64 > mean_residual {
        score -= 0.10 * (post_residual as f64 - mean_residual);
    } else {
        score += 0.10 * (mean_residual - post_residual as f64);
    }

    // --- Last-chance bonus: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well:
        // penalize new bins mildly so tight fits win, but keep it viable
        // when open bins would create large dead space.
        let dead_if_open = if next_item_size > 0 && post_residual < next_item_size {
            0.5 * (next_item_size as f64 - post_residual as f64)
        } else {
            0.0
        };
        score += 15.0 + 5.0 * progress - dead_if_open;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post-residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score -= 50.0; // perfect fill
        } else if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            // lookahead item fits into the leftover space: strong reward
            let exact = 1.0 - ((post_residual as f64) - (next_item_size as f64)) / (bin_capacity as f64);
            score -= 25.0 * exact;
        } else if next_item_size > 0 {
            // leftover too small for next item: mild penalty scaled by waste
            score += 8.0 * tightness;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins with slack: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score -= 2.0 * pressure.ln().max(0.0);

    // Time horizon: late in stream, favor packing into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - tightness);

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins have little room or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.5;
        let many_open = open_bins_count as f64 > 5.0 + 10.0 * (1.0 - progress);
        if poor_fit_elsewhere || many_open {
            score -= 10.0; // allow opening a fresh bin
        } else {
            score += 25.0; // discourage wasting a fresh bin early
        }
    }

    // Small residual bonus for bins already partially filled (reduce bin count).
    if bin_residual < bin_capacity {
        score -= 5.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear squashing
    let tightness = (pr / cap).powi(2) * cap;
    let mut score = tightness * (1.0 + 0.8 * progress);

    // Dead-space penalty: residuals too small for the smallest plausible item
    let dead = (1.0 - (pr / 20.0).min(1.0)) * (pr / cap) * 30.0;
    score += dead * (0.5 + 0.5 * progress);

    // Smooth coupling with mean residual: prefer bins below mean residual
    // (fill emptier-relative bins first to consolidate space)
    let mean_gap = (mean_residual - pr) / cap;
    score -= 12.0 * mean_gap / (1.0 + mean_gap.abs());

    // Last-chance bonus: only bin that fits -> strong reward to use it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.3);
    }

    // Lookahead: if next item would fit the post-residual, reward this placement
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        if next_fits {
            let ratio = next_item_size as f64 / pr.max(1.0);
            score -= 18.0 * ratio * (1.0 - ratio);
        } else {
            score += 6.0 * ((next_item_size as f64 - pr) / cap).min(1.0);
        }
    }

    // New-bin candidate handling: neutral-ish base, penalize opening new bins
    // when existing bins fit reasonably well (post_residual == cap means empty bin)
    if bin_residual == bin_capacity {
        score = cap + 15.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
        // allow new bin if all fits are terrible (large dead space everywhere)
        score -= 20.0 * (mean_residual / cap).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by modulo-10 bands.
    let class = post_residual % 10;
    // Class 0 (perfect multiples of 10) leaves maximally reusable residue.
    score -= (10 - class) as f64 * 0.7;

    // Integer-division thresholds: residue small enough to be "dead" (< 10)
    // is penalized heavily unless it's exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Lookahead coupling: does the residue form a harmonic pair with next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_fit = post_residual - next_item_size;
            score -= pair_fit as f64 * 0.5;
            // harmonic: next item leaves residue in a reusable class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's residue; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // modulo resonance between item and next item sizes
        if (item_size + next_item_size) % 100 == 0 {
            score -= 20.0;
        } else if (item_size + next_item_size) % 50 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fits = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score = score.max(0.0) + 60.0 - poor_fits * 45.0 - (mean_residual - item_size as f64).max(0.0) * 0.3 - progress * 5.0;
    }

    // Fraction-of-capacity coupling: prefer bins whose post residual is a
    // small fraction of capacity (tight packing).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual < typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse if no future item can use it (lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Early in stream, slightly favor consolidating
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual).

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect 2-step match: post_residual exactly equals next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits afterwards: mild reward proportional to closeness.
            let slack = pr - nxt;
            score -= 20.0 / (1.0 + slack / nxt);
        } else {
            // Dead space relative to the lookahead item: penalize the gap.
            let gap = nxt - pr;
            score += 0.8 * gap;
        }

        // Two-step chain: post_residual can hold next item and leave a small tail.
        if post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail <= 10 {
                score -= 10.0; // near-perfect two-item packing
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins that stay
    // near/below the mean (keeps the bin population balanced, avoids fragmenting).
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when other bins fit the item.
        if fitting_bins_count > 0 {
            // Attractiveness of opening new bin rises with how bad existing fits are:
            // if current item leaves big dead space in any existing bin, new bin wins.
            let dead = (bin_capacity - item_size) as f64;
            if dead < 5.0 {
                score -= 70.0; // perfect fit in fresh bin
            } else {
                score += 15.0 + 0.5 * dead;
            }
        } else {
            score -= 40.0; // nothing fits, must open new bin
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual already does most of this).

    // Lookahead: if the next item fits exactly in the post-residual, this is a great pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more waste: mild penalty proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
        } else {
            // Next item won't fit here anyway; slightly prefer bins whose post-residual
            // is small so the next item goes elsewhere or a new bin absorbs it.
            score += 2.0;
        }
    }

    // Penalize leaving large dead space: post_residual below the minimum item size is wasted.
    if post_residual < 10 {
        score -= 5.0; // tiny residual is fine, bin is essentially full
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.2;
    } else {
        // Larger leftover: penalize quadratically to discourage fragmenting bins.
        score += (post_residual as f64 - 20.0).powi(2) * 0.02;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large (poor fit anywhere)
        // or no open bin fits at all.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let no_fitters = fitting_bins_count == 0;
        if large_item || no_fitters {
            score -= 20.0;
        } else {
            // Penalize spreading across many bins when a reasonable fit exists.
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer packing into existing bins rather than leaving them idle.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= mean_residual * 0.05 * (0.5 + progress);
    }

    // Mild preference for reusing bins as the stream matures (stabilization).
    if bin_residual < bin_capacity {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (post_residual small). Late: allow spreading
    // since remaining stream shrinks, weight on post_residual decays.
    let decay = 1.0 - 0.6 * progress * progress;
    score += decay * (post / cap) * (post / cap) * cap * 0.5;

    // Dead-space penalty: residuals too small for typical items are wasted.
    let dead = (10.0 - post).max(0.0) / 10.0;
    score += dead * dead * 15.0;

    // Reward last-chance bins (avoid opening new bin needlessly).
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (prefer uniform residual landscape).
    score += ((post - mean_residual) / cap).powi(2) * 8.0;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to leftover.
        score += 3.0 * (post / cap) * (1.0 - progress);
    }

    // Prefer filling existing bins over opening new ones as stream progresses.
    score -= 4.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: keep it slightly unattractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + (mean_residual / cap) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of capacity wasted after placement.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += post_frac * post_frac * 40.0;

    // Harmonic class of post_residual: perfect fills (0) heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual >= 50 {
        // Large residual is flexible only if it can host typical future items.
        score -= 5.0;
    } else {
        // Dead zone 11..49: mod-10 class coupling with next item.
        let class = post_residual % 10;
        if class >= 8 {
            score -= 6.0; // near-decade residuals pair well with small items
        } else if class <= 2 {
            score -= 4.0;
        } else {
            score += 6.0; // awkward mid-class dead space
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 25.0 - (leftover as f64).min(25.0);
        } else {
            // Next item would need a new bin if we place here; slight penalty
            // when this bin is the only fitting one (forced placement anyway).
            if fitting_bins_count == 1 {
                score += 0.0;
            } else {
                score += 10.0;
            }
        }
    }

    // New-bin candidate handling: empty bin should only win when fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin decays as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 45.0 - 15.0 * progress;
        // Opening more bins is pricier when many are already open and empty-ish.
        open_cost += (open_bins_count as f64) * 1.5;
        // If many bins fit, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            open_cost += 20.0;
        }
        // Exception: very large items leave unusable residue in open bins;
        // prefer a fresh bin so the residual stays large/flexible.
        if item_size >= 60 {
            open_cost -= 25.0;
        }
        score += open_cost;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to avoid opening a new bin.
        score -= 35.0;
    }

    // Mean-residual coupling: placing into a bin below the mean residual
    // balances the pool, slightly rewarded.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest
    // likely future item (<= ~15) are nearly worthless -> heavy penalty.
    if post_residual < 15 {
        score += 60.0 * (1.0 - (post_residual as f64) / 15.0);
    } else if post_residual <= 25 {
        // Small-but-usable gap: moderate penalty, tighter is worse.
        score += 20.0 * (1.0 - ((post_residual - 15) as f64) / 10.0);
    } else {
        // Larger residuals are flexible; reward proportionally.
        score -= 0.3 * ((post_residual - 25) as f64);
    }

    // Perfect fit reward: leaving exactly zero is ideal (bin fully closed).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 15.0 {
            score -= 35.0 * (1.0 - gap / 15.0);
        }
    }
    // If next item would NOT fit here but fits nowhere else either,
    // keep residual as large as possible.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the waste would be extreme.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating
    // into existing bins rather than spreading out.
    score += 0.5 * open_bins_count as f64;

    // Mean-residual coupling: if average residual is tight, closing
    // bins efficiently matters more.
    score -= 0.2 * mean_residual;

    // New-bin candidate: only attractive when the item is large and
    // would leave a big unusable gap elsewhere, or few bins open.
    if bin_residual == bin_capacity {
        // Neutral base: its raw score is post_residual = capacity,
        // already high; add pressure so it loses unless fits are bad.
        score += 10.0;
        if item_size >= 70 {
            score -= 30.0; // huge item: fresh bin often best
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
    }

    // Late-stream tightening: near the end, minimize total footprint.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item's size (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Exact match bonus: next item fills bin perfectly to zero.
        if gap < 0.5 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual is dead space for the next item; penalize proportionally.
        score += 0.6 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // unless the item is large and would leave big fragmentation elsewhere.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
        score += 45.0 - 10.0 * pressure;
        if item_size >= 60 {
            score -= 15.0; // big items: fresh bin is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin also chains well
        }
    }

    // Mild late-stream tightening: waste less as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize creating small unusable dead space (post residual too small for typical future items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize if placing here leaves a residual that cannot host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps room for the next item
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 6.0; // this placement destroys a bin that could host next item
        }
    }

    // Prefer filling bins with residual close to mean (keeps distribution balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer larger residual bins early, tighter bins late in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 0.05 * bin_residual as f64;
    score += progress * 0.05 * bin_residual as f64;

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            (post_residual as f64 / bin_capacity as f64).min(1.0)
        };
        score = bin_capacity as f64 - 30.0 * desperation - 10.0 * progress;
    }

    // Mild penalty for opening many bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = pr * pr / cap;

    // Smooth cubic coupling: small post-residuals get extra reward late in stream.
    let norm_pr = pr / cap;
    score -= (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize bins far from the mean residual (smooth dispersion term).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 2.0;

    // Lookahead coupling: reward residuals that still admit the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (pr >= n) as i32 as f64;
        let tightness = ((pr - n) / cap).max(0.0);
        score -= fits_next * (1.0 - tightness) * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer the only bin that fits (smooth ramp).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // Mild congestion penalty to discourage hoarding many open bins.
    score += (open_bins_count as f64).ln() * 0.1;

    // New-bin candidate: neutral-ish baseline with slight progress-dependent cost.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residual bucket via integer division (class width 10)
    let class = post_residual / 10;
    // Penalize residuals that fall in "waste" classes (1..9 small dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Reward leaving residuals that common small items (1..=class*10) can fill
    let fillable = (class as f64) * 10.0;
    score -= 0.5 * fillable;

    // Modulo-10 coupling: residual divisible by 10 is more "usable"
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits the post residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
        // extra reward if next item exactly fills it
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize leaving medium dead space
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // placements would create bad dead space
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if all open bins would leave awkward residuals, new bin becomes attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if post_residual >= 20 && open_bins_count > 0 && mean_residual < 15.0 {
            score -= 30.0 * progress;
        }
    }

    // Encourage tight packing into bins below mean residual (denser bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Waste-aversion: quadratic penalty on small leftover space
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += (10.0 - pr).max(0.0) * (10.0 - pr).max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual in (0, 10) is pure waste; residual >= 10 can still host min-size items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // gap only usable by very small items: moderate penalty
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // residual too small for next item: slight penalty for blocking lookahead
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but relax it when the fit into this fresh bin is large.
        score += pressure * 4.0;
        score -= 8.0 * fill_ratio;
    } else {
        // Existing bin: mild reward scaled by pressure to keep bins consolidated.
        score -= pressure * 0.5;
    }

    // Prefer bins with below-average residual (tighter bins) to consolidate waste.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 2.0 * (mean_residual - bin_res_f) / bin_capacity as f64;
    } else {
        score += 2.0 * (bin_res_f - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // Perfect two-item fill: post_residual == next_item_size is ideal.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: prefer tightest fit, mild bonus.
        score -= 5.0;
    }

    // Prefer bins that are already "worn in" (low residual relative to mean).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Deter opening a new bin unless the fit is genuinely tight.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow a new bin when current post-residual would be very wasteful.
        if post_residual > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (small post_residual is already rewarded by base).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * (fit_ratio - 0.85);
    }

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize wasting space if post_residual is stranded.
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.5;
        if !poor_fit {
            score += 35.0;
        } else {
            score += 5.0 - 10.0 * progress;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if mean_residual > 40.0 && open_bins_count > 3 {
        score -= 3.0;
    }

    // Time horizon: late in stream, be more conservative, prefer tight fits only.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * p2 + 1.5 * p3);
    score += 0.8 * coupling * cap * 0.01;

    // Penalize dead space quadratically, modulated by progress
    score += (norm_pr * norm_pr) * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) especially early
    score -= 2.0 * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize mildly unless residual would be tiny
    if bin_residual == bin_capacity {
        let waste = norm_pr - (item_size as f64 / cap);
        score += 4.0 - 2.0 * (1.0 - norm_pr);
        if next_item_size as f64 <= pr && next_item_size > 0 {
            score -= 3.0;
        }
        let _ = waste;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.5 * (next_item_size as f64 / cap) * (0.5 + progress);
    }

    // Mean residual divergence penalty
    score += 0.4 * (pr - mean_residual).abs() / cap;

    // Open bins pressure
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over
    let class = (post_residual / 10) as f64; // integer-division class (decile)

    // Reward small post_residual strongly (tight fit), with harmonic decay.
    score -= 60.0 * (-frac * 8.0).exp();

    // Penalize "dead" residuals that few item sizes can use.
    // Items are 1..=100; a residual r is only usable if next items <= r.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can host the lookahead item: reward, scaled by how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-snug / 30.0).exp();
        } else {
            // Lookahead cannot use this residual: penalize dead space.
            score += 15.0 + 0.3 * (post_residual as f64);
        }
    }

    // Modulo arithmetic on post_residual: residuals in "nice" classes
    // (multiples of 10 / 5) are more likely reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Integer division thresholds on post_residual: tiny leftovers are bad.
    if post_residual / 10 == 0 {
        score += 20.0; // post_residual < 10: nearly unusable
    } else if post_residual / 10 == 1 {
        score += 8.0;  // 10..19: only small items fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: mild penalty to prefer consolidation elsewhere.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when the stream is
    // early or the current fit is terrible (large post_residual class).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / cap) > 0.5;
        if poor_fit || progress < 0.1 {
            score -= 30.0; // open a new bin rather than waste a big residual
        } else {
            score += 50.0; // keep using existing bins mid/late stream
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — finishing it off is good.
    let dev = mean_residual - post_residual as f64;
    score -= 0.1 * dev;

    // Mild stream-progress scaling of tight-fit reward.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 40 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: fewer open bins is better; penalize spreading.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tight bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: prefer bins whose post_residual
    // closely matches the next item's size (perfect chaining), penalize
    // post_residuals that leave awkward dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        // Reward near-exact match for the next item.
        score -= 30.0 * (-gap / 8.0).exp();
        // Penalize post_residuals that can't host the next item at all
        // (wasted slot) but only mildly — item may still chain later.
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post / nxt.max(1.0));
        }
        // Extra reward for exact chain: post_residual == next_item_size.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: bins already small relative to the
    // fleet should be drained first (avoid fragmenting many bins).
    score -= 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 10.0; // still leaves a useful tiny slot? no — tiny slot bad
            score += 18.0; // net: discourage creating dead space in sole option
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when the item is large or no good open-bin fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - large_item); // mild penalty, reduced for big items
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // room to chain next item in fresh bin
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Slight preference to fill earlier-opened bins as stream matures
    // (keep open bin count low).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals that are too small for likely future items.
    if post_residual > 0 {
        let min_useful = 10.0; // smallest conceivable item
        let usable = (post_residual as f64 / 100.0).clamp(0.0, 1.0);
        if post_residual < 10 {
            score += 25.0 * (1.0 - post_residual as f64 / 10.0);
        }
        let _ = min_useful;
        let _ = usable;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here; mildly reward.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward leftovers
            // that are smaller than the next item.
            let gap = next_item_size - post_residual;
            if gap < next_item_size {
                score += 4.0 * gap as f64 / next_item_size as f64;
            }
        }
    }

    // Global state: when many bins are open with high mean residual,
    // discourage opening new bins (favor consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are underused
        // and we're late in the stream.
        let underuse = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 10.0 + 35.0 * underuse * (0.5 + 0.5 * progress);
        // But if no open bin fits well (post_residual of this fresh bin is ideal
        // relative to item), allow it: score stays at post_residual + penalty,
        // so a very tight existing fit still wins.
    }

    // Mild reward for filling bins as the stream progresses (reduce bin count).
    score -= 6.0 * (1.0 - progress) * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Penalize spreading across too many open bins when mean residual is low.
    if open_bins_count > 4 && mean_residual < 25.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer tight fits (small post-residual), scaled by item size so
    // large items are packed more aggressively.
    let mut score = pr * (0.6 + 0.8 * fit_ratio);

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, tolerate larger residuals (bins can be reused);
    // late in the stream, heavily penalize wasted space.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 0.8 * progress * pr / cap;
    score *= progress_coupling;

    // Reward when the lookahead item fits exactly in the post-residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= (1.0 - slack) * (1.0 - slack) * 8.0 * (1.0 - progress);
    }

    // Penalize dead space that no plausible item can use (min item size 1,
    // but small residuals under typical item sizes are wasteful).
    let dead_threshold = cap * 0.2;
    if pr < dead_threshold {
        let d = pr / dead_threshold;
        score += (1.0 - d) * (1.0 - d) * (4.0 + 6.0 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild penalty proportional to congestion: spreading across many bins
    // is costly; prefer filling existing bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * (pr / cap);

    // Slight preference for bins with residuals close to the mean (balance
    // residual distribution, smooth quadratic term).
    score += 0.5 * (pr - mean_residual) * (pr - mean_residual) / (cap * cap);

    // New-bin candidate handling: an empty bin has high post_residual; make
    // it attractive only when the current item is large or no good fit exists.
    if bin_residual == bin_capacity {
        score -= 2.0 * fit_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "waste classes".
    let residue = post_residual % 10;
    let class = post_residual / 10; // integer division threshold: 0..10 tenths of capacity

    // Penalize dead space: small post_residual that is unusable (residue 1..9 wastes space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin is great, but tiny unusable slivers are fine actually
        score -= 30.0; // net reward: filling a bin almost completely is desirable
    }

    // Reward tight fits via harmonic fraction of capacity used.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 15.0;
        // perfect two-item packing reward
        if slack_after_next == 0 {
            score -= 20.0;
        } else {
            score += 0.3 * slack_after_next as f64;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: penalize leaving medium residuals that block nothing
        score += 0.15 * post_residual as f64;
    }

    // Harmonic class bonus: residuals in class 0 (exact fill) or divisible by common item sizes.
    if post_residual == 0 {
        score -= 18.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0; // class divisible by 20 pairs with typical items
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    // and lookahead suggests a big item needing fresh capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / bin_capacity as f64).min(1.0);
        let mut new_bin_score = 45.0; // default: discourage opening new bins
        if next_item_size > 0 && next_item_size > mean_residual && post_residual < next_item_size {
            new_bin_score -= 30.0; // fresh capacity useful for the lookahead item
        }
        if open_bins_count > 6 && pressure > 0.35 {
            new_bin_score += 10.0 * pressure;
        }
        if progress > 0.9 {
            new_bin_score += 8.0; // late stream: consolidate rather than spread
        }
        score = score.max(new_bin_score);
    }

    // Mild consolidation: prefer bins below mean residual (tighter bins first).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>= ~10, or
    // >= next_item_size) can use are heavily penalized.
    let min_useful = next_item_size.max(10) as f64;
    if post_residual > 0 {
        let usable = if (post_residual as f64) >= min_useful { 1.0 } else { 0.0 };
        if usable == 0.0 {
            // Dead space: waste proportional to residual size, strongly penalized.
            score += 60.0 + post_residual as f64 * 2.0;
        } else if (post_residual as f64) < min_useful * 1.5 {
            // Marginal fit for the lookahead item: mild penalty.
            score += 15.0;
        }
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 25.0;
    } else if fill_ratio > 0.75 {
        score -= 10.0;
    }

    // Perfectly closed bins are ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are large/fragmented or no bin fits well.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual > (bin_capacity as f64 * 0.4);
        let no_choice = fitting_bins_count == 0;
        let base = 35.0
            + (mean_residual / bin_capacity as f64) * 20.0
            + open_bins_count as f64 * 1.5;
        if fragmented || no_choice {
            // Opening a new bin is reasonable: keep score moderate.
            score = base;
        } else {
            // Existing bins are healthy: make the new bin unattractive.
            score = base + 80.0;
        }
        // Toward the end of the stream, prefer closing out existing bins.
        score += (1.0 - progress) * 10.0;
    }

    // Small tie-breaker toward bins whose residual is close to the item.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
