}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight fit), with non-linear polynomial coupling.
    let mut score = post + 0.15 * post * post / cap;

    // Reward filling the bin more as the stream progresses (early: keep space flexible).
    let tightness = 1.0 - post / cap;
    score -= progress * 40.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 12.0 * gap * gap * (1.0 - progress);
        } else {
            // Reward bins whose leftover fits the next item exactly well.
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 8.0 * fit_quality * fit_quality * (1.0 - progress);
        }
    }

    // Last chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // Slight penalty when many bins compete, encourage consolidation.
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // Deviation from mean residual: prefer bins that reduce residual variance.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // New empty bin candidate: penalize unless it is genuinely attractive
    // (e.g., item is large relative to capacity, or late stream with many bins).
    if bin_residual == bin_capacity {
        let large_item = item / cap;
        let mut penalty = 30.0 * (1.0 - large_item) * (1.0 - large_item);
        // Late in stream, consolidation pressure drops; allow new bins more freely.
        penalty *= 1.0 - 0.5 * progress;
        // If no open bin would otherwise fit, opening is fine (fitting_bins_count==1 case).
        if fitting_bins_count == 1 {
            penalty *= 0.3;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" (residual < smallest item) are nearly worthless -> penalize
    // leaving them, reward bins that can still absorb future items.
    let dead = if post_residual < 10 && post_residual > 0 { 1.0 } else { 0.0 };
    score += dead * 60.0;

    // Modulo-class coupling: residuals congruent to common item sizes (10,20,...,80
    // steps) are reusable. Reward residuals divisible by small granularity.
    let gran = 10u32;
    if post_residual % gran == 0 {
        score -= 12.0;
    } else {
        // quantize mismatch penalty based on distance to next multiple of gran
        let dist = gran - (post_residual % gran);
        score += (dist as f64) * 0.8;
    }

    // Integer-division threshold on post_residual: classify into tiers
    let tier = post_residual / 20; // 0..5
    score -= match tier {
        0 => 5.0,          // tiny residual left, but item fit well
        1 => 2.0,
        2 => 0.0,
        3 => -3.0,         // roomy bin still usable
        _ => -5.0,
    };

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; if post_residual is small, fine (bin is done),
            // if large, we waste capacity -> penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in stream or few bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // if next item is large, a fresh bin is attractive
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: small leftover gaps (1..=9) are nearly unusable
    // since future items are typically >= 10; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Gaps that exactly fit the lookahead item are valuable; reward them.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Gaps that could fit the next item are moderately useful.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    }

    // Open-bins pressure: prefer consolidating into existing bins,
    // penalize slightly proportional to how many bins are already open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: reserve it for large items or when no good fit exists.
    // Give the empty bin a mild handicap so existing tight fits win.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the item fills more than half a fresh bin, opening is more attractive.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below average,
    // it's already tight — favor using it up.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow slightly more tolerance for spreading items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for large leftover space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose residual can host the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (next_item_size as f64);
        } else {
            // Penalize leaving residual just barely below next item (dead space).
            let gap = (next_item_size as f64) - post_residual as f64;
            if gap < 20.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state coupling: many open bins with low mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual - post_residual as f64).abs();
    score += 0.1 * consolidation * (1.0 + open_bins_count as f64 / 20.0);

    // Late in the stream, prefer filling existing bins harder.
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and mean residual across open bins is small (nothing reusable).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 40.0;
        if fit_quality < 0.2 && mean_residual < 15.0 {
            score -= 55.0; // open new bin when open bins are nearly full anyway
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of residual quality with stream progress
    let tightness = 1.0 - norm_pr; // how well item fills bin
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space more as stream progresses
    score += 40.0 * norm_pr * norm_pr * norm_pr * progress;

    // Lookahead: reward if next item can fit in post residual (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns).abs();
        let kernel = (-fit_gap / 30.0).exp();
        score -= 20.0 * kernel * (1.0 - progress);
    }

    // Last-chance bonus: smooth sigmoid on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 15.0 * last_chance;

    // Mean residual deviation penalty (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Slight preference for consolidating bins as open bin count grows
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize mildly unless residual is huge relative to item
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score += 5.0 + 30.0 * waste * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by integer division.
    // Small leftovers (dead space) are penalized super-linearly.
    let cls = post_residual / 10; // harmonic class 0..10
    match cls {
        0 => score -= 60.0,                       // perfect fit (0-9 leftover)
        1 => score -= 20.0,                       // near fit
        2 => score += 5.0,                        // awkward ~20 leftover
        3 => score += 12.0,                       // ~30 leftover (bad: fits few items)
        4 => score += 18.0,                       // ~40 leftover
        5 => score += 15.0,                       // ~50 leftover (fits mid items)
        6 => score += 8.0,
        7 => score += 3.0,
        _ => {}                                   // large leftovers are naturally scored high
    }

    // Coupling: leftover that exactly accommodates the lookahead item is gold.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 45.0;                        // chain fit: next item nests perfectly
        } else {
            score -= (20.0 * next_item_size as f64) / (post_residual as f64 + 10.0);
        }
    } else if next_item_size > 0 {
        // leftover too small for the next item -> it becomes dead space
        score += 10.0 + 0.3 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Penalize opening new bins when many bins could fit the item (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * fitting_bins_count as f64;
        // Early in stream, tolerate new bins slightly more (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier future packing).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Modulo harmonic: leftovers that are multiples of 10 are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any post_residual that is small but
    // non-zero is nearly unusable (min item size 1, but small gaps rarely
    // match future items). Penalize the "dead zone" aggressively.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening more
    // by penalizing the fresh-bin candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 6.0 * open_bins_count as f64;
        // But late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Slight pressure to keep the number of open bins in check by
        // favoring fuller bins when many bins are open.
        score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement; if next item cannot fit any resulting gap,
    // add mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0;
            } else if slack <= 10 {
                score += 8.0;
            }
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins whose post_residual brings them
    // closer to the mean residual (balanced depletion across bins).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item can also go here: reward proportional to closeness
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space relative to lookahead item: penalize gap
            score += 50.0 * (diff / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 * progress);

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 10.0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // penalize leaving a gap just barely too small for next item
        if post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) >= next_item_size - 3 {
            score += 12.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating (favor bins below mean residual)
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: late in stream, be more conservative (avoid new bins, pack tightly)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;
    if bin_residual == bin_capacity {
        // new-bin candidate: costly early, very costly late
        score += 15.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0 * (1.0 - fit_ratio);
        }
    }

    // Mild penalty for very loose fits regardless
    if fit_ratio < 0.4 && bin_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: polynomial in normalized post residual modulated by stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Prefer tighter fits as stream progresses
    score -= 10.0 * (1.0 - norm_pr) * progress;

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (0.5 + 0.5 * progress);
        } else {
            score -= 4.0 * (1.0 - (pr - nx) / cap) * poly;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Mild pressure toward reusing bins vs opening new ones
    let mean_res_norm = mean_residual / cap;
    score += 3.0 * (mean_res_norm - norm_pr) * (1.0 - progress);

    // Slight penalty for opening a new bin early, reward late when bins are many
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 8.0 - open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes define "usable" dead space
    let pr = post_residual;
    let class = pr % 10;
    // Small dead space classes (0..=5) are nearly perfect fits: strong reward
    if class <= 5 {
        score -= 12.0 - 2.0 * class as f64;
    } else {
        // Larger awkward classes: penalize proportionally
        score += 0.35 * (class as f64 - 5.0);
    }

    // Integer-division threshold: post_residual bucketed by quarter capacity
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 4.0; // tiny leftover: bin effectively closed, but waste is locked
    } else if pr < 2 * quarter {
        score -= 3.0; // half-ish residual still useful
    } else {
        score -= 1.5; // large residual, flexible
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match on tens digit: next item aligns with residual class
            let nclass = next_item_size % 10;
            let match_bonus = if nclass == class { 10.0 } else if (next_item_size as f64 / pr as f64) > 0.7 { 6.0 } else { 2.0 };
            score -= match_bonus;
        } else {
            // Next item won't fit here: penalize leaving residual that blocks lookahead
            score += 0.25 * (next_item_size as f64 - pr as f64);
            // But if residual is tiny, bin is done anyway — mild reward
            if pr < 10 {
                score -= 5.0;
            }
        }
    } else {
        // Last item: just minimize waste
        score -= 8.0;
    }

    // Last-chance bin before opening a new one: strong reward to avoid bin proliferation
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score = 55.0 - crowded * 0.5 - (post_residual as f64) * 0.1;
        // Late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 6.0; // discourage new bin when alternatives exist
        }
    }

    // Fraction-of-capacity fill reward: filling large fraction of current residual is good
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_frac;

    // Mean residual coupling: when mean residual is low, conserve space tightly
    score += 0.05 * (mean_residual - pr as f64);

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, minimum item size) are worthless.
    if post_residual < 10 {
        score -= 25.0; // perfect or near-perfect fill is highly desirable
    } else if post_residual <= 20 {
        score += 6.0; // small gap is mostly dead space
    } else if post_residual <= 35 {
        score += 2.0; // mildly risky gap
    } else {
        score -= 3.0; // large residual retains flexibility
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fewer suffice.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If next item is huge relative to current, opening fresh may be wise.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter packs).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in stream: be more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/tight fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: if next item fits exactly into the post residual,
    // this placement is doubly desirable.
    if next_item_size > 0 {
        let pr = post_residual as u32;
        if pr == next_item_size {
            score -= 60.0;
        } else if pr > next_item_size && pr - next_item_size <= 10 {
            score -= 25.0;
        } else if pr < next_item_size {
            // Dead space for the known next item: penalize proportionally.
            score += (next_item_size - pr) as f64 * 0.5;
        }
        // If next item is large and won't fit anywhere else, keep residual flexible.
        if next_item_size > 50 && pr < next_item_size {
            score += 10.0;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.5 {
            score -= 20.0 * fill_ratio;
        } else {
            score += 15.0;
        }
        // More open bins already -> less eager to open another.
        score += open_bins_count as f64 * 2.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can reuse this bin's post-residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving a residual just barely too small for the next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss < 15.0 {
                score += 0.8 * miss;
            }
        }
    }

    // New-bin candidate logic: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        // Slight exploration bonus early, penalty later when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        score += 0.6 * open_bins_count as f64;
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.15 * mean_residual;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: late in the stream, be greedier about tight fits.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * horizon * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: penalize leftover space, non-linearly (small residuals are cheap, large ones costly)
    let mut score = norm_post.powf(1.8) * cap;

    // Smooth coupling: late in the stream, dead space matters more (fewer chances to fill it)
    score += progress * norm_post.powf(2.5) * cap * 2.0;

    // Reward tight fits: interaction between item size and residual shrinkage
    let tightness = norm_item * (1.0 - norm_post);
    score -= tightness * cap * 1.5;

    // Smooth quadratic interaction of item size with progress: big items into open bins early is fine,
    // late big items should prefer best-fit strongly
    score += progress * norm_item * norm_item * cap * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 1.2 * (1.0 - progress * 0.5);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= fit_quality * cap * 0.9 * (0.5 + progress);
    }

    // Penalize creating residuals that are too small for the smallest plausible item,
    // with smooth severity based on how close to the dead-zone boundary
    let dead = (norm_post * 10.0).floor() / 10.0;
    if dead > 0.0 && dead < 0.1 {
        score += (0.1 - norm_post) * cap * (1.0 + progress);
    }

    // Mild pressure to consolidate: when many bins are open, prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 2.0;

    // New-bin candidate: residual == capacity. Make it attractive only when item is large
    // or existing fits are poor; otherwise the base post-residual cost already competes.
    if bin_residual == bin_capacity {
        score -= norm_item * cap * 0.6;
        score += (1.0 - progress) * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual that is too small to hold any plausible
    // future item (harmonic class of small leftovers) is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Harmonic classes on post_residual via integer division thresholds:
    // leftover divisible into useful chunks is good, awkward leftovers are bad.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr / 20; // 0..=4 harmonic class of leftover size
        score -= 8.0 * (cls as f64);
        // awkward leftovers: not reusable for common item sizes
        if next_item_size > 0 && pr < next_item_size && pr < 30 {
            score += 20.0;
        }
    }

    // Lookahead: reward if the next item exactly or nearly fits the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + next_fit);
        if post_residual == next_item_size {
            score -= 50.0; // perfect two-item closure
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // residual after placement in fresh bin
        // penalize opening new bin when current bin would leave decent leftover
        if bin_residual >= item_size && (bin_residual - item_size) >= 10 && fitting_bins_count >= 1 {
            score += 35.0;
        }
        // open a fresh bin if current placement would strand tiny dead space
        if bin_residual >= item_size && (bin_residual - item_size) < 10 {
            score -= 55.0;
        }
        // early in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (consolidating emptier bins).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Small tie-breaker toward fewer open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: dead space unless residual < 10.
            if post_residual >= 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are crowded or mean residual is low.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 6.0 + mean_residual * 0.6;
        score += 55.0 - pressure.min(55.0);
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count >= 2 {
            score += 40.0;
        }
    }

    // Open-bin count pressure: mild penalty per open bin for any placement that leaves a mid-range gap.
    if post_residual >= 10 && post_residual <= 25 {
        score += open_bins_count as f64 * 1.5;
    }

    // Late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits here; mild reward scaled by tightness of fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space proportionally.
        let dead = next_item_size - post_residual;
        score += 0.15 * dead as f64;
    }

    // Penalize very small unusable residuals (< typical min item size).
    if post_residual < 10 {
        score += 12.0 + (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced, saves big bins).
    score += 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 25.0 * scarcity;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // opening fresh bin helps future large items
        }
    }

    // Early in stream: slightly favor consolidation to build tight packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // residual can't host next item: mild penalty scaled by waste
            score += 1.5 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: prefer it only when the item is large relative to
    // a fresh bin and existing fits are poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bonus = 4.0 * fill_ratio;
        if fitting_bins_count == 0 {
            new_bonus += 10.0;
        } else if fitting_bins_count == 1 {
            new_bonus -= 5.0;
        } else {
            new_bonus -= 2.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bonus -= 3.0 * progress;
        // Many open bins with high mean residual: reuse them instead.
        new_bonus += (open_bins_count as f64) * 0.05 * (mean_residual / bin_capacity as f64);
        score -= new_bonus;
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual
    let fit_ratio = item_size as f64 / cap;

    // Base: reward tight fits via non-linear polynomial of post residual
    let mut score = 3.0 * x * x - 2.0 * x * x * x; // smoothstep-like: low score for small post residual

    // Penalize leaving dead space that nothing can use
    let dead = if next_item_size > 0 && post_residual < next_item_size { post } else { 0.0 };
    score += 2.5 * (dead / cap) * (1.0 + progress);

    // Reward bins that leave room for the lookahead item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
        score += 0.8 * gap * gap;
    }

    // Last-chance bonus: strongly favor this bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - fit_ratio);
    }

    // Late-stream coupling: prefer filling existing bins more aggressively as stream progresses
    score -= progress * 1.5 * (1.0 - x);

    // Slight penalty proportional to crowding of open bins
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual deviates below mean (tighter bins first)
    score += 0.3 * ((mean_residual - post) / cap).max(-2.0).min(2.0);

    // New-bin candidate: make it unattractive unless item is huge relative to residual space of others
    if bin_residual == bin_capacity {
        score += 4.0 - 2.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fraction bands
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;

    // Dead-space penalty: residuals too small to hold anything useful (items >= 1)
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if post_residual <= 2 {
        score -= 300.0; // near-perfect
    } else {
        // harmonic class via integer division on residual
        let class = post_residual / 10; // decade classes
        score += (class as f64) * 5.0;
        // modulo-based dead-zone detection: residuals in (0,10) are waste unless next item fits
        if post_residual < 10 && next_item_size > post_residual {
            score += 40.0;
        }
    }

    // Reward if the lookahead item exactly fits the post residual (chain packing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            // partial usability reward, scaled by how well it fits
            let frac = next_item_size as f64 / pr.max(1.0);
            score -= 60.0 * frac;
        } else {
            // next item cannot use this residual: penalize by wasted fraction
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Tight fit reward relative to capacity quarters
    if pr <= quarter {
        score -= 30.0 * (1.0 - pr / quarter);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when residual classes are all bad
    if bin_residual == bin_capacity {
        let congestion = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() + 1.0 };
        let mean_fit = (mean_residual - item_size as f64).max(0.0);
        score = 0.5 * cap + 3.0 * mean_fit + 25.0 * congestion;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 40.0; // big next item: fresh bin is fine
        }
    }

    // Slight preference for bins below mean residual (balance load across harmonic classes)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the smallest plausible item
    // (or the lookahead item) are heavily penalized.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Reward exact fit strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones
    // (the empty new-bin candidate gets bin_residual == bin_capacity, so its
    // tightness reward is low; add explicit pressure proportional to openness).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else {
        score -= 1.0 * open_bins_count as f64 * 0.2;
    }

    // Prefer bins whose residual is near the mean (balanced packing),
    // penalize outliers that create fragmented residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead synergy: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin can also host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Slack left after hypothetically hosting next item: mild reward for tight chains.
            let slack = (post_residual - next_item_size) as f64;
            score -= (30.0 - slack * 0.35).max(-15.0);
        } else {
            // Next item cannot follow here: penalize dead space, worse when close to next size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Reward very tight fits (little post residual) especially relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.25;
    } else {
        score += (pr - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the new-bin candidate unless it enables a perfect 2-step chain.
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && post_residual == next_item_size;
        if !perfect_chain {
            score += 35.0;
        }
        // Early in the stream, new bins are cheap; late in the stream, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Slight penalty for tiny unusable slivers (< 10) that likely become dead space.
    if pr > 0.0 && pr < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual is good, but amplify).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small dead space: mildly penalize relative to medium leftovers.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post-residual, reward chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Extra reward if next item exactly fills the bin after this one.
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // Post-residual too small for the next item: dead space penalty grows
            // as the leftover becomes unusably small relative to item range.
            let waste = post_residual as f64;
            if waste > 0.0 {
                score += 3.0 * (1.0 - waste / (bin_capacity as f64));
            }
        }
    }

    // New-bin candidate: penalize so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 35.0;
        // Late in the stream, be more conservative about opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 20.0 * progress;
        // If many bins are already open and mean residual is high, avoid new bins.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            new_bin_penalty += 10.0;
        }
        // If the item is huge and next item is also large, a fresh bin may be wise.
        if item_size > bin_capacity / 2 && next_item_size > bin_capacity / 2 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Crowding: with many open bins, prefer consolidating into bins with low residual.
    if open_bins_count > 1 {
        score += 0.05 * (open_bins_count as f64 - 1.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild preference for bins whose residual is close to the mean (balanced use).
    score += 0.02 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling: residual waste penalized more as stream progresses
    let prn = pr / cap;
    let tightness = 1.0 - prn;
    score += 18.0 * prn * prn * (0.5 + progress) * tightness;

    // Reward tight fits (small post_residual) with a smooth non-linear term
    score -= 25.0 * (1.0 - prn).powi(3) * (1.0 + 0.5 * progress);

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 6.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            score -= 4.0 * (pr - nx) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: mildly penalized early (prefer filling open bins),
    // less penalized late when open bins are fragmented
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 8.0 * (1.0 - progress) * (1.0 + (open_bins_count as f64 / 10.0).min(1.0));
        score -= 3.0 * progress;
    }

    // Fragmentation penalty relative to mean residual of open bins
    score += 2.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by residue class
    let pr = post_residual;
    let class = pr % 10;
    // Perfect-fit class heavily rewarded
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 4.0;
    } else if pr >= 90 {
        score += 30.0; // huge dead space, bad
    }

    // Integer-division thresholds: pairability of post_residual with next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here afterwards -> chain bonus
            let fits_perfectly = pr == next_item_size;
            if fits_perfectly {
                score -= 45.0;
            } else {
                score -= 10.0 + (pr - next_item_size) as f64 * 0.15;
            }
        } else {
            // next item won't fit in this bin's remainder
            score += 6.0;
            // penalize leaving remainder in awkward band (just below next size)
            if pr >= next_item_size.saturating_sub(6) {
                score += 12.0;
            }
        }
    }

    // Fraction-of-capacity coupling
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 20.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening unless current residuals are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < 12.0;
        let mut open_penalty = 28.0;
        if tight { open_penalty += 25.0; }
        if open_bins_count == 0 { open_penalty = -100.0; }
        // lookahead-aware: open early if next item is large
        if next_item_size > 60 { open_penalty -= 15.0; }
        score += open_penalty;
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item (1..~10) is wasted space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // dead space: unusable tiny gap
        } else if post_residual < 25 {
            score += 15.0; // risky gap: fits only very small items
        } else if post_residual < 50 {
            score += 5.0;  // moderately reusable gap
        } else {
            score -= 10.0; // large residual remains: bin stays flexible
        }
    } else {
        score -= 25.0; // perfect fill: zero waste
    }

    // Reward tight fits: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading out; penalize candidates that leave scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (0.5 + 0.5 * progress);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item can fit into the post-residual,
    // reward keeping that pairing possible; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size > bin_residual && next_item_size <= post_residual + bin_capacity {
            // next item won't fit here anyway; neutral
        } else {
            score += 8.0; // kills the lookahead opportunity
        }
    }

    // Mean-residual coupling: bins whose residual deviates favorably from the mean
    // (i.e., we use up a bin that is unusually full already) get a bonus.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 10.0 * dev;

    // New-bin candidate handling: an empty bin is a fallback; make it mildly
    // attractive only when no open bin offers a tight fit, otherwise keep it
    // dominated by good existing placements.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins are open.
        score += 5.0 + 1.5 * open_bins_count as f64;
        // If nothing else fits well (many bins but few candidates), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already handled by base).
    // Reward when the leftover space exactly matches the next item's size (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.6;

        // Strong bonus if next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize if next item cannot fit anywhere after this placement (dead space creation).
        if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: penalize bins with residual far above mean (hoarding space).
    let res = post_residual as f64;
    score += (res - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin costly unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if this item leaves a perfect slot for the next item in a fresh bin, allow it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Late in stream: consolidate aggressively, discourage new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    // Small penalty for leaving awkward mid-range gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can't hold the next item (wasted capacity).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect lookahead fit: strong reward.
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when existing
    // fits are terrible (large post residual) or late in the stream.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64 / bin_capacity as f64; // ~1 - item/100
        let mut penalty = 30.0 - 15.0 * progress;
        // If many bins fit the item, opening a new one is rarely worth it.
        if fitting_bins_count > 1 {
            penalty += 8.0 * (fitting_bins_count.min(6) as f64);
        }
        // If mean residual across open bins is large, they should be used first.
        penalty += 0.25 * mean_residual;
        // But if item is huge and would leave a tiny unusable gap, soften penalty.
        if fit_quality < 0.25 {
            penalty -= 10.0;
        }
        score += penalty.max(0.0);
    }

    // Mild global pressure: with many open bins, encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for leaving residuals that are "standard" gaps
    // (multiples of small common sizes keep future packing flexible).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (low post_residual), with non-linear emphasis.
    let mut score = pr * (1.0 + 2.0 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, mild penalty for large residuals; late, strong penalty (consolidate).
    let p_weight = 0.5 + 2.5 * progress * progress;
    score += p_weight * (pr / cap) * (pr / cap) * cap;

    // Reward bins whose residual closely matches the item (smooth Gaussian-like term).
    let fit_gap = (bin_residual as f64 - item) / cap;
    score -= 8.0 * (-fit_gap * fit_gap * 40.0).exp();

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if nxt > 0.0 && nxt <= pr {
        let gap = (pr - nxt) / cap;
        score -= 6.0 * (-gap * gap * 60.0).exp();
    }

    // Penalize wasting a nearly-full bin on a small item (dead space creation).
    score += 3.0 * (pr / cap) * (item / cap);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // in existing bins (large item relative to mean residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = item / mean_residual.max(1.0);
        score += 12.0 - 10.0 * (poor_fit * poor_fit).min(1.0) - 4.0 * progress;
        score += 0.5 * open_bins_count as f64;
    } else {
        // Slight preference for bins with residual below mean (fill fuller bins first).
        score += 0.8 * ((bin_residual as f64 - mean_residual) / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let post_class = (post_residual / quarter) as f64; // 0..4
    let next_class = (next_item_size / quarter) as f64; // 0..4 (0 => no next item)

    // Reward when the leftover post_residual belongs to a class that a future
    // small item (<= 25% capacity) can still fill: leftover is "usable".
    let small_next = (next_item_size > 0 && next_item_size <= quarter) as f64;
    score -= 14.0 * small_next * (1.0 - post_class / 4.0);

    // Penalize dead space: residual that no item class can pair with.
    // If next item is large (3rd/4th class), a small post_residual is dead space.
    let big_next = (next_item_size > 3 * quarter) as f64;
    score += 10.0 * big_next * (post_class < 2.0) as i32 as f64;

    // Perfect fit / near-perfect fit via modulo arithmetic on post_residual.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % quarter == 0 {
        score -= 12.0; // leftover is exactly a harmonic fraction: reusable
    } else if post_residual <= quarter / 2 {
        score += 8.0; // tiny sliver: wasted capacity
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is neutral-to-good when the
    // current fit is bad or the next item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_fit = (post_class >= 3.0) as i32 as f64; // huge leftover after placement
        score = 40.0 - 20.0 * bad_fit - 6.0 * (next_item_size as f64 / cap);
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Coupling with mean residual: bins far below mean residual are "fresh";
    // prefer filling bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 5.0 * tightness;
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (post_class > 2.0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size 1
    // threshold we treat < 10 as fully dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0; // nearly dead space
    }

    // Reward tight fits (exact fill is ideal).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // If this bin can also fit the next item after placement, big reward (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Placing here strands the next item; penalize proportionally to gap.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor filling;
    // few open bins -> tolerate opening new bins less harshly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 50.0)) * (0.5 + 0.5 * progress);

    // New-bin candidate: opening a new bin wastes all existing residuals;
    // penalize more when open bins have healthy mean residual.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * pressure;
        if fitting_bins_count == 1 {
            score -= 45.0; // but if no real alternative, allow it
        }
    } else {
        score += 2.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits after this placement
            score -= 120.0 / (1.0 + lookahead_gap as f64);
            if lookahead_gap == 0 {
                score -= 250.0; // perfect 2-item chain
            }
        } else {
            // next item won't fit; penalize large wasted residuals
            score += 0.6 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) relative to mean residual
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;
    score -= 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        // new-bin candidate: score = capacity baseline; adjust by stream progress and mean residual
        score = bin_capacity as f64
            + 40.0 * (mean_residual / bin_capacity as f64)
            - if next_item_size > 0 && next_item_size >= item_size { 30.0 } else { 0.0 };
        // keep new bin attractive only if no open bin can take item well
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
