pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: penalize residual more late in the stream (smooth polynomial)
    let prog_term = 1.0 + 0.8 * progress * progress + 1.2 * progress * progress * progress;
    score *= prog_term;

    // Reward tight fits: subtract smooth function of item fraction
    let tightness = item_size as f64 / cap;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Mean residual interaction: bins deviating below mean residual are more attractive
    score -= 0.3 * (mean_residual - pr).max(0.0);

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize if post residual cannot fit next item but bin_residual could
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt && bin_residual as f64 >= nxt {
            score += 8.0 * (1.0 - nxt / cap);
        }
        if pr >= nxt {
            score -= 5.0 * (1.0 - progress) * (pr - nxt) / cap;
        }
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" integer-division classes are rewarded.
    let cap_f = bin_capacity as f64;
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range)
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Reward residuals that are "harmonically clean" fractions of capacity:
    // divisible by quarter/eighth classes => easier future packing
    if pr % quarter == 0 && pr > 0 {
        score -= 25.0;
    } else if pr % eighth == 0 && pr > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the slack after the next placement
            if slack as u32 % eighth == 0 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack / cap_f);
            }
        } else {
            // next item cannot follow in this bin: mild penalty scaled by tightness
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins: reward small post_residual relative to capacity
    score -= 30.0 * (1.0 - (post_residual as f64) / cap_f);

    // Progress-based opening of new bins: early in stream, opening new bins
    // is cheap; late, prefer compacting into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate score: baseline slightly above a perfect fit
        let mut nb = 0.35 * cap_f;
        // open new bin when open bins are crowded or lookahead is large
        if next_item_size >= 50 { nb -= 15.0; }
        if progress < 0.3 { nb -= 10.0; }
        if mean_residual < 20.0 { nb -= 20.0; }
        score = nb;
    } else {
        // existing bin: penalize when bin deviates far from mean residual
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately small gaps are only usable by small items; penalize scaled by tightness.
        score += 18.0 * (1.0 - post_residual as f64 / 25.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward placements that leave room for the known next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that cannot host the next item: dead space penalty.
        score += 10.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, favor reuse (penalize opening new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 8.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 15.0 + 4.0 * pressure;
    } else {
        // Reusing an existing bin gets a mild bonus that grows with pressure.
        score -= 2.0 * pressure.min(10.0);
    }

    // Prefer bins whose residual is close to the mean (balanced packing) only mildly;
    // prefer using bins with SMALL residual to consolidate waste.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for larger residual bins when item is large (avoid fragmenting).
    if item_size > bin_residual / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual close to 0)
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10.0 {
        score -= 35.0;
    } else if pr <= 20.0 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // Next item nests perfectly: strong reward scaled by tightness
            let gap = pr - nx;
            if gap == 0.0 {
                score -= 55.0; // two-item exact fill
            } else {
                score -= 30.0 * (1.0 - gap / cap);
            }
        } else {
            // Next item will NOT fit here: penalize wasted residual,
            // worse when the leftover residual is small but unusable
            let waste = pr / cap;
            score += 18.0 * waste * (nx - pr) / nx.max(1.0);
        }
    }

    // Penalize bins whose residual deviates badly from mean residual
    score += 0.35 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // mild openness to new bins early, penalized later to consolidate
        score += 8.0 + 20.0 * (1.0 - early) - 4.0 * open_bins_count as f64;
        // if next item is large, a fresh bin is fine
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Discard spreading items across many open bins
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize large dead space if the leftover can't hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (post_residual as f64 / next_item_size as f64);
        } else if post_residual >= next_item_size {
            // Reward bins whose leftover can absorb the lookahead item.
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and a fit exists.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        score = bin_capacity as f64 * 0.9;
        // More attractive early in the stream or when open bins are mostly full.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0; // next item needs a fresh bin anyway
        }
    } else {
        // Prefer bins with residual close to item_size (best fit flavor).
        let gap = (bin_residual - item_size) as f64;
        score += gap * 0.3;
        // Slight bonus for spreading load when many bins open.
        score -= 0.05 * open_bins_count as f64;
        // Time-varying exploration: later in stream, prioritize compacting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress * (1.0 - tightness);
    }

    // Coupling with mean residual: bins far below mean are less urgent to fill.
    if (bin_residual as f64) > mean_residual {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual, with mild non-linear pressure on dead space.
    let mut score = pr + 0.05 * pr * pr / cap;

    // Reward tight fits (small post_residual relative to capacity) smoothly.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness;

    // Stream-progress coupling: as the stream advances, squeeze existing bins harder
    // (smooth polynomial in progress) to avoid leaving many half-empty bins.
    let squeeze = 3.0 + 9.0 * progress * progress;
    score -= squeeze * tightness;

    // Penalize bins whose residual deviates from the mean residual (fragmentation signal),
    // with strength growing over the stream.
    let dev = (pr - mean_residual).abs() / cap;
    score += (2.0 + 6.0 * progress) * dev * dev;

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward;
    // if it fits at all, mild reward; otherwise penalize creating a gap the next item can't use.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni == pr {
            score -= 15.0;
        } else if ni < pr {
            score -= 4.0 * (ni / pr.max(1.0));
        } else {
            score += 3.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): add a fixed opening cost
    // plus a mild discount early in the stream (when spreading items is cheap),
    // and a penalty when many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.4 * open_bins_count as f64 - 6.0 * (1.0 - progress);
        // Penalize opening a new bin for a small item (wastes capacity).
        score += 0.08 * (cap - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits, strongly penalize large wasted space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;
    score += 0.35 * (post_residual as f64 / cap).powi(2) * cap;

    // Harmonic class of post_residual: residue classes modulo 10.
    // Small "nice" residuals (0..=10) are ideal; penalize awkward classes.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0 - 1.5 * class;
    } else {
        // residuals in (10, 50] are semi-usable; above that mostly dead space
        let dead = (pr.saturating_sub(10)) as f64;
        score += 0.25 * dead;
        // modulo threshold: multiples of 5/10 pair better with typical items
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else { score += 3.0; }
    }

    // Integer-division thresholds: can the next item land here?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or with small harmonic residue
            let npr = pr - next_item_size;
            let nclass = (npr % 10) as f64;
            if npr == 0 { score -= 45.0; }
            else if npr <= 10 { score -= 18.0 - 1.2 * nclass; }
            else { score += 0.15 * (npr as f64); }
            score -= 5.0; // general lookahead bonus
        } else {
            // next item cannot use this bin: penalize proportionally to gap
            let gap = (next_item_size - pr) as f64;
            score += 0.10 * gap;
            if gap <= 10.0 { score += 6.0; } // near-miss is painful
        }
    } else {
        // last item: any residual is pure waste
        score += 2.0 * pr as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * post_residual as f64;
    }

    // New-bin candidate: open a fresh bin only when current fits are poor
    // or the stream is early (amortize future items into fresh capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.6 && post_residual > 15;
        if poor_fit || progress < 0.25 || open_bins_count == 0 {
            score -= 40.0 + 20.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        // fresh bin pairs well if next item is large relative to capacity
        if next_item_size >= bin_capacity / 2 { score -= 10.0; }
    }

    // Mean-residual coupling: when open bins are already slack, avoid
    // adding another slack bin; prefer filling the slacker ones.
    score += 0.05 * (mean_residual - post_residual as f64);
    if open_bins_count > 12 {
        score += 0.03 * post_residual as f64 * (open_bins_count as f64 / 12.0).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 interface, but small gaps < ~12 are
    // nearly always dead) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is excellent.
        score -= 40.0;
    }

    // Reward when post_residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if the lookahead item would be blocked by this placement.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonable fit exists; encourage opening new bins only when fits are bad.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the "useful" direction (large residual absorbs big future items).
    if (bin_residual as f64 - mean_residual).abs() > 0.0 {
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate handling: it is attractive only when this is the last
    // item or when existing fits are poor (large post_residual / dead space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64).min(20.0); // 0 for empty bin itself
        let _ = poor_fit;
        // Base cost of opening a bin, reduced late in the stream.
        score = 25.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // empty bin can always take the next item
        }
        if fitting_bins_count == 1 {
            // Some bin fits; only open a new one if that fit leaves dead space.
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits snugly into the resulting residual (next <= post_residual)
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here afterwards: penalize proportionally to wasted space
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste;
    }

    // Exact fill of the bin
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize tiny unusable residuals (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare residual against mean residual: prefer bins with less residual (tighter packing)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score = -100.0; // must open a bin
        } else {
            // Opening a new bin is only better if the best fit would leave a bad residual;
            // make new bin slightly unattractive so good fits win.
            score = new_bin_base + 15.0;
            if next_item_size > 0 && bin_capacity.saturating_sub(item_size) >= next_item_size {
                score -= 10.0; // new bin can also take the next item comfortably
            }
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (post_residual as f64 - ni).abs();
        if post_residual as u32 >= next_item_size {
            score -= 30.0 / (1.0 + diff);
        } else {
            score += 5.0 * diff / cap;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Global residual pressure: prefer filling bins when mean residual is high
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: late in the stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: penalize opening a new bin unless the item is huge
    if bin_residual == bin_capacity {
        let waste_threshold = 0.4 * cap;
        if post_residual as f64 > waste_threshold {
            score += 40.0;
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (many items left to fill); late, waste is costly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (post / cap) * (post / cap) * 20.0;

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * item * 0.3;

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fill = (post - nxt).max(0.0) / cap;
        // next item exactly fills this bin after placement -> big bonus
        score -= (1.0 - gap / cap) * (1.0 - gap / cap) * 15.0 * (1.0 - progress);
        // leftover after hypothetical next placement penalized mildly
        score += fill * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins far from mean residual (prefer balanced fills) with smooth coupling.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 10.0 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when no good fit exists,
    // via smooth interaction with mean residual of open bins.
    if bin_residual == bin_capacity {
        let mean_pressure = mean_residual / cap;
        // if open bins are quite full on average, opening new bin is fine
        score = 40.0 + 60.0 * (1.0 - mean_pressure) * (1.0 - progress * 0.5);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 penalize dead space
    let r = (post_residual % 10) as f64;
    score += r * 0.35;

    // Perfect-fit harmonic classes: post_residual in {0, 25, 50, 75, 100} strongly rewarded
    if post_residual == 0 { score -= 40.0; }
    if post_residual == 50 { score -= 15.0; }
    if post_residual == 25 || post_residual == 75 { score -= 8.0; }

    // Integer-division thresholds: small post_residual bands are bad (unusable slivers)
    if post_residual > 0 && post_residual < 10 { score += 12.0; }

    // Next-item compatibility via modulo classes
    if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits here too: reward, scaled by how well it divides the residual
        let fit2 = post_residual - next_item_size;
        if fit2 % 10 == 0 { score -= 14.0; }
        score -= 6.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual too small for the next item: penalize if it becomes dead space
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are truly bad,
    // but allow opening late in the stream when mean residual is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count == 1 { score += 40.0; }
    }

    // Tight fits (post_residual small but usable) favored relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Cap new-bin score so it can win only against badly fragmented bins
    if bin_residual == bin_capacity && score < 30.0 { score = 30.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100 interface => anything < 10 is near-certain waste,
    // < next_item_size is waste against the known lookahead).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        if post_residual < 10 {
            score += 45.0; // unusable dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 22.0; // cannot host the lookahead item
        } else {
            // smooth tightness reward: smaller usable gap => better
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Exact match of lookahead into post_residual is a jackpot.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.15 * item_size as f64;
    }

    // Open-bin pressure: many open bins => discourage spreading, prefer tight
    // packing into existing bins; few open bins => opening a new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced when few bins are open,
        // increased when many bins are open and mean residual is high.
        score = 40.0 + pressure * 6.0 + (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // lookahead won't fit anywhere anyway
        }
    } else {
        score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight stream-phase adaptation: late in the stream, favor closing bins out.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins that are nearly filled.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // 2-step lookahead: reward post_residual that closely matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let lookahead_bonus = (1.0 - gap / bin_capacity as f64).max(0.0);
        score -= 20.0 * lookahead_bonus * (next_item_size as f64 / bin_capacity as f64);
        // Penalize residual too small for the next item (dead space for step 2).
        if (post_residual as u64) < next_item_size as u64 {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are already tight; prefer them.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly discouraged unless current bins would leave bad fits.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Slight penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 25 {
        score -= 12.0;
    } else {
        score += (post_residual as f64 - 25.0) * 0.35;
    }

    // Dead-space penalty: residual too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // next item can't use this leftover; penalize stranded residual
            score += 15.0;
        }
    }

    // Global state: when many bins are open with slack, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early (bins accumulate), less late.
        score += 15.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.4;
        // But if this item is huge and mean residual is small, new bin may be fine.
        if item_size > 60 && mean_residual < (item_size as f64) {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight reward relative to how full it already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late stream: become more conservative, favor consolidating into existing bins.
    if progress > 0.8 {
        if bin_residual != bin_capacity {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: quadratic penalty on post_residual (dead space), modulated by progress.
    let mut score = pr * (1.0 + 0.9 * progress) + 0.0035 * pr * pr * (1.0 + 0.6 * progress);

    // Cubic coupling: large residuals become more costly late in the stream.
    score += 0.00004 * pr * pr * pr * progress;

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    score -= (cap - pr) * (cap - pr) / (cap * cap) * 12.0;

    // Lookahead: penalize if next item fits well in post_residual (reserve it),
    // reward if this placement leaves post_residual usable by next item poorly elsewhere.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (nxt / pr)) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when open bins exist
    // and residuals are still large on average.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.25 * open_bins_count as f64 + 0.05 * mean_residual * (1.0 - progress);
    }

    // Fragmentation pressure: spread between this bin and mean residual.
    score += 0.02 * (pr - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins grouped by residual magnitude classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;

    // Reward tight fits strongly (waste minimization), with harmonic decay.
    score -= 30.0 * fill_frac * fill_frac;

    // Harmonic class: post_residual mod 10 — small residues are "dead space classes".
    let residue_class = post_residual % 10;
    score += match residue_class {
        0 => -6.0,          // perfectly divisible residual: reusable
        1..=3 => 1.0 + residue_class as f64, // awkward small slack
        4..=9 => 0.0,
        _ => 0.0,
    };

    // Integer-division thresholds on post_residual: classify usability for next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: big reward, scaled by tightness of that future fit.
            let future_fit = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - future_fit / cap);
        } else {
            // Bin becomes dead for the lookahead item: penalize proportionally.
            score += 4.0 * (next_item_size - post_residual) as f64 / cap * 10.0;
        }
    } else {
        // Last item: pure waste minimization.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 12.0                      // base cost of opening a bin
               + 6.0 * congestion
               + 5.0 * (1.0 - progress);
        // If existing bins fit the item, discourage new bin further.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // New bin is good if item is large (fills it well).
        score -= 12.0 * (item_size as f64 / cap);
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 4.0;

    // Last-chance bin pressure: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bin pressure: many open bins -> discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = open_bins_count as f64 * (2.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty + 10.0;
    } else {
        score -= 5.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // dead space relative to upcoming item
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 50.0;
        } else if gap <= 5.0 {
            score -= 20.0 - gap * 2.0;
        } else {
            score += gap * 0.5;
        }
        // Penalize post_residual too small for next item but nonzero (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 5.0;
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin unless the fit in existing bins is terrible
    if bin_residual == bin_capacity {
        // New bin: base cost of consuming fresh capacity
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no alternative
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 >= mean_residual {
            score -= 15.0; // fresh bin enables a good future fit
        }
    }

    // Slight preference for keeping fewer open bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly favor small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that is too small to ever hold a minimum-size item
    if post_residual < 10 {
        score += 60.0; // nearly unusable sliver
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            // reward proportionally, but penalize leaving another sliver
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
            if slack_after_next < 10 {
                score += 20.0;
            }
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // competition: mild penalty so best-fitting bins still win via tightness
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // Global state: when many bins are open with high mean residual, discourage
    // spreading into new space; encourage filling existing bins
    if open_bins_count > 0 {
        let mean_res_ratio = mean_residual / bin_capacity as f64;
        // high mean residual => bins are mostly empty => favor consolidating
        score += 15.0 * mean_res_ratio;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity,
    // i.e. post_residual == bin_capacity - item_size. Penalize opening a new bin
    // unless the current fit is bad (large post_residual).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, decaying slightly over time as
        // consolidation becomes harder
        let new_bin_cost = 55.0 - 20.0 * progress;
        score += new_bin_cost;
        // if the item is large relative to capacity, a fresh bin is more attractive
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild bonus for placing into bins early in the stream (keeps options open later)
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: reward small post_residual non-linearly
    let tight_fit = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight_fit * (0.5 + progress);

    // Penalize dead space that grows quadratically when post_residual is small but unusable
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap * cap;
        } else {
            // lookahead fits: reward smooth proximity
            let d = (pr - nx) / cap;
            score -= 6.0 * (1.0 - d).powi(2);
        }
    }

    // Last-chance bonus with smooth sigmoid-like term
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr * norm_pr);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual interaction: prefer bins near the mean early, deviating late
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Mild preference to fill existing bins as stream progresses
    score -= progress * item_size as f64 * 0.05;

    // New-bin candidate penalty, decaying with progress
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common size steps
    // (e.g. multiples of 10, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        // Dead-space penalty: residual too small for the smallest plausible item
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }
    }

    // Lookahead coupling: reward residuals that can also host the next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
            // integer-division threshold: how many next items fit after this one
            let k = pr / next_item_size.max(1);
            score -= (k.min(3)) as f64 * 4.0;
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Tight-fit reward: item fills a large fraction of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins -> prefer consolidation into emptier bins
    if open_bins_count > 4 {
        score -= mean_residual * 0.05;
    }

    // Late in the stream: avoid opening new bins, favor tight fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 + (fitting_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Fit tightness: prefer bins where the item occupies a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: with many open bins, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the mean residual is too small for the item.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 1.1);
        if poor_alternatives {
            score -= 70.0;
        } else {
            score += 90.0 + open_bins_count as f64 * 5.0;
        }
    }

    // Mild alignment with mean residual: bins below mean residual are tighter fits.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fills (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        let diff = if post_residual >= next_item_size {
            post_residual - next_item_size
        } else {
            next_item_size - post_residual
        } as f64;

        // Exact match: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to tightness of the pair.
            score -= 400.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a gap next item nearly fits.
            score += 50.0 * (1.0 - diff / bin_capacity as f64);
        }

        // Penalize post_residual in the awkward zone just below typical item sizes.
        if post_residual > 0 && post_residual < 10 {
            score += 120.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 500.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins early in the stream when open bins could fit well.
    if bin_residual == bin_capacity {
        score += 80.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // But allow new bin if fit would be very poor in all open bins.
        if post_residual > 60 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below a
    // "useless threshold" is penalized quadratically (fragmentation).
    let frag = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 0.8
    } else {
        0.0
    };
    score += frag;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64 - ni).abs() < 0.5 {
            score -= 18.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            // next item still fits: mild bonus proportional to leftover tightness
            score -= 6.0 * (1.0 - ((post_residual as f64 - ni) / 100.0));
        } else {
            // next item won't fit here: penalize slightly more for larger waste
            score += 3.0 * (ni - post_residual as f64).min(30.0) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        // extra urgency late in the stream
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * t;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer using existing bins when the fit is decent (post_residual small).
        // New bin gets a baseline penalty that shrinks when existing fits are bad.
        score += 30.0;
        // But late in the stream or with many open bins, opening fresh space is
        // cheaper than fragmenting; reduce the penalty.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * t;
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // If mean residual is low (bins nearly full), a new bin is attractive.
        score -= (mean_residual / 10.0).min(5.0);
    }

    // Discourage spreading: prefer bins with below-mean residual (fuller bins)
    // to keep some bins large for future big items.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0 * ((res_f - mean_residual) / 100.0);
    }

    // Mild penalty for very large leftovers that only huge items could use,
    // scaled by stream position (early: keep flexibility; late: consolidate).
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 50 {
        score += 6.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post-residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, dead space matters more.
    let prog_term = progress * progress * (1.0 - progress) * 4.0;
    score += 30.0 * prog_term * norm_pr;

    // Penalize residuals too small for typical items (unusable slivers).
    let small_thresh = 0.12;
    if norm_pr < small_thresh && norm_pr > 0.0 {
        score += 15.0 * (small_thresh - norm_pr) / small_thresh;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward residual that can still hold the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (ni / cap);
        } else {
            score += 5.0 * (ni / cap);
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish baseline, only attractive when fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover mod capacity-fraction bands.
    // Leftovers that form "good harmonic classes" (multiples of common item
    // sizes 10/20/25/50) are rewarded; awkward classes are penalized.
    let pr = post_residual;
    let class_reward: f64 = if pr == 0 {
        -40.0 // perfect fill
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -7.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr < 10 {
        30.0 // dead space: too small for any item
    } else {
        0.0
    };
    score += class_reward;

    // Dead-space penalty grows when leftover cannot host the lookahead item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 6.0; // leftover stays useful for the next item
        } else if pr < 10 {
            score += 10.0; // guaranteed dead space
        } else {
            score += 4.0; // leftover too small for the known next item
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest fits more aggressively.
        score -= (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit here would be poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - poor_fit); // empty bin scores ~25 unless fit is tight
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin can fit: opening is necessary
        }
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 0 {
            score -= 10.0 * progress; // open bins nearly full -> fresh bin ok
        }
    } else {
        // Existing bin: reward using mean residual as tie-breaker pressure.
        score -= (mean_residual - bin_residual as f64).abs() * 0.05;
    }

    // Slight preference for filling bins that are already well used.
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A gap is "dead" if nothing in the size range can ever use it.
    // Items are 1..=100, but small gaps are only usable by small items.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize small unusable gaps superlinearly.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        // gap too small even for the next item -> likely dead space
        score += 25.0 + 0.5 * post_residual as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        // absolutely tiny gap: pure waste
        score += 40.0;
    }

    // Reward tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // --- Lookahead coupling: leave room for the next item if possible ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // this bin can also absorb the next item
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress); // early on, avoid stranding gaps
    }

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- Open-bin pressure: with many open bins, consolidate ---
    score += 0.15 * open_bins_count as f64;

    // --- Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin residuals homogeneous, easier future packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- New-bin candidate handling ---
    // A fresh empty bin (residual == capacity) should only win when the fit
    // elsewhere is poor: give it a moderate baseline penalty that scales
    // with how much of it the current item would consume.
    if bin_residual == bin_capacity {
        // utilization of the new bin by this item
        let util = item_size as f64 / bin_capacity as f64;
        // big items justify a new bin; small items should reuse open bins
        score = 45.0 - 30.0 * util;
        if post_residual == 0 {
            score -= 60.0; // exact fill still fine
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        score += 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect match: next item exactly fills this bin -> huge reward
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward, scaled by how snugly it fits
            score -= 25.0 - (pr - ni) * 0.25;
        } else {
            // Next item won't fit after placement: penalize wasted opportunity
            score += (ni - pr) * 0.5;
        }
        // Bonus if next item fits *now* in this bin but wouldn't after placement
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 10.0; // placing current item destroys a slot for the next one
        }
    }

    // ---- dead-space penalty ----
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + (10 - post_residual) as f64;
    }

    // ---- tightness relative to fleet mean residual ----
    // Prefer bins that are fuller than average (small residual vs mean)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // ---- last-chance bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // ---- new-bin candidate: keep as fallback, cost grows with open bins ----
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.6 + progress * 5.0;
    }

    // ---- mild early-stream exploration: spread load early, tighten late ----
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 1.6 * tightness * tightness * bin_capacity as f64;

    // Penalize residual that is likely unusable dead space (too small for typical items).
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 0.9 * (25.0 - post_residual as f64);
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact pairing is golden.
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: mild penalty scaled by how far off we are.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap.min(40.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0 + 0.35 * open_bins_count as f64;
        // Late in the stream, opening new bins is riskier (residuals may go unused).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 7.0 * (fitting_bins_count as f64).min(4.0);
        }
        // But if mean residual across open bins is small (poor future hosts),
        // a fresh bin becomes more attractive.
        score -= 0.12 * mean_residual;
    }

    // Global state coupling: when many bins are open with large mean residual,
    // prefer packing into existing space to consolidate.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
        score += 0.02 * open_bins_count as f64;
    }

    // Item-size interaction: large items should prefer very tight bins.
    if item_size > 60 {
        score -= 0.1 * (item_size - 60) as f64 * tightness;
    }

    // Small deterministic tie-break to avoid exact ties between equivalent bins.
    score -= 0.001 * (bin_residual as f64).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: dead space, penalized more heavily later in the stream
    let mut score = post * (1.0 + 0.8 * prog2 + 0.6 * prog3);

    // Non-linear waste penalty: squared normalized residual, weighted by progress
    score += cap * post_norm * post_norm * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with smooth decay
    let tightness = 1.0 - post_norm;
    score -= 12.0 * tightness * tightness * tightness * (1.0 + progress);

    // Last-chance bin: strong smooth bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins with residual above mean (keeps a spread of usable bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev * (1.0 - progress);

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = if post >= nxt {
            1.0 - (post - nxt) / cap
        } else {
            post / (nxt + 1.0)
        };
        score -= 8.0 * compat * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residual is very wasteful
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: modulo classes on capacity fractions.
    // Capacity 100 -> classes of 10. Residuals that are "harmonic" (small, class-aligned)
    // are less useful for future items; large residuals should be preserved.
    let cap = bin_capacity as f64;
    let class_size = cap / 10.0;
    let post = post_residual as f64;

    // Penalize residuals that fall into awkward classes: 1..9 (too small for most items,
    // not zero). Reward exact class boundaries (0, 10, 20, ...) which pair well.
    let class_index = ((post / class_size).floor() as i64).max(0);
    let class_offset = post - class_index as f64 * class_size;
    if post > 0.0 && class_offset > 0.0 {
        // Dead space inside a class: the smaller the offset, the worse the waste density.
        score += (class_size - class_offset) * 0.8;
    }
    // Exact-fit / boundary classes get a bonus proportional to remaining class size.
    if class_offset == 0.0 && post > 0.0 {
        score -= 6.0;
    }

    // Integer-division thresholds: residual >= 2*next_item_size means the bin can
    // still host the lookahead item after this one -> strong bonus.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= 2.0 * nx {
            score -= 12.0;
        } else if post >= nx {
            score -= 7.0;
        } else if post > 0.0 {
            // Lookahead cannot use leftover: penalize proportionally.
            score += (nx - post).min(15.0) * 0.6;
        }
    }

    // Modulo coupling on post_residual with lookahead: perfect complementarity
    // (post_residual == next_item_size) is ideal.
    if next_item_size > 0 && post == next_item_size as f64 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Opening a new bin is cheap early, expensive late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + pressure * 1.5 + progress * 10.0;
        // If the lookahead item is huge, a fresh bin is more valuable.
        if next_item_size as f64 > cap * 0.5 {
            score -= 10.0;
        }
    }

    // Mild preference to fill emptier bins first (balance load).
    if bin_residual < bin_capacity {
        score -= (mean_residual - post).clamp(-20.0, 20.0) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for future items (assume min item size ~1..100, dead zone < 20).
    if post_residual < 20 && post_residual > 0 {
        score += (20 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits into the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item almost fits but not quite (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate: make empty-bin selection costly unless item is large
    // relative to open bins' residuals (poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Progress-based mild adaptation: later in stream, tighten more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: next item fills this bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item leaves a small usable remainder.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap);
    }
    // Penalize residuals too small for the next item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Penalize deviation from mean residual: prefer bins that are either
    // near-full (low residual) or keep the residual distribution balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference to fill tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Discourage opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space: post_residual that is too small to be useful
    let min_useful = 10u32;
    if post_residual < min_useful && post_residual > 0 {
        score += 18.0 * (min_useful - post_residual) as f64;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; mild penalty for wasting space
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's a great fit
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful if existing bins fit decently
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 10.0 * progress;
        // But if item is large and fits perfectly in a fresh bin, reduce penalty
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // Few fitting bins and high open-bin count: discourage yet another bin
        if open_bins_count > 4 && fitting_bins_count > 1 {
            score += 8.0;
        }
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Slight preference for filling more of the bin as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += coupling * pr_norm * pr_norm * cap * 0.5;

    // Penalize large residuals more strongly as stream progresses (less time to fill them)
    let late_penalty = progress * progress * pr_norm * cap;
    score += late_penalty;

    // Reward tight fits (small post_residual) especially when the next item can use the space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_bonus = if pr >= nxt {
            1.0 - ((pr - nxt) / cap).abs()
        } else {
            -(nxt - pr) / cap
        };
        score -= match_bonus * (1.0 - progress) * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mildly discourage spreading across many open bins
    score += (open_bins_count as f64).ln() * 0.5;

    // Favor bins with residual near mean (balanced packing), smooth quadratic
    let dev = pr - mean_residual;
    score += 0.1 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: best-fit style — smaller post_residual is better.
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: group dead space into capacity fractions.
    // Classes: 0 (perfect), 1..=10 (micro), 11..=25 (small), 26..=50 (medium), >50 (large).
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward tighter classes (subtract per class level).
    score -= (4 - class) as f64 * 6.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // Reward chains that keep future residual in a "usable" harmonic class.
            if nxt_post <= 10 { score -= 25.0; }
            else if nxt_post <= 25 { score -= 12.0; }
            else if nxt_post > 50 { score += 10.0; }
        } else {
            // Next item can't fit here after placement: slight penalty for blocking.
            score += 8.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of small
    // common sizes (10, 20, 25) are more likely reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when open
    // bins have plenty of room. Penalize the fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: its post_residual equals capacity - item_size.
        let fresh_post = bin_capacity - item_size;
        // Penalize opening a new bin proportionally to existing usable slack.
        score += 30.0 + mean_residual * 0.4 + (open_bins_count as f64) * 2.0;
        // But if item is huge and fits poorly anywhere (post_residual tiny),
        // fresh bin is fine: offset the penalty.
        if fresh_post <= 10 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        score += progress * 15.0;
    }

    // Penalize leaving dead space far from mean residual (waste alignment).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Mild global pressure toward fewer open bins: prefer existing bins.
    if bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the new-bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: small post_residual gaps that nothing (min size 1..~10) can use.
    if !is_new_bin {
        if post_residual > 0 && post_residual < 10 {
            // unusable sliver: strong penalty proportional to wasted capacity
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 20 {
            // risky zone: only tiny items can use it
            score += (20 - post_residual) as f64 * 3.0;
        }

        // Reward near-perfect fits (tight packing) aggressively.
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 5 {
            score -= 25.0;
        }

        // Lookahead: if the next item can fit exactly into post_residual, big reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next < 10 {
                score -= 35.0;
            } else {
                score -= 8.0;
            }
        }
        // Penalize if next item will NOT fit in the leftover (forces future bin churn)
        if next_item_size > post_residual && post_residual < 10 {
            score += 5.0;
        }

        // Last-chance bonus: if this is the only bin that can fit the item,
        // strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    } else {
        // New bin: base cost of opening a bin (fresh residual is high, so
        // post_residual alone already looks bad; add explicit opening cost).
        score += 15.0;

        // Opening a new bin is more acceptable when many bins are open
        // (parallel packing headroom) and early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= open_bins_count as f64 * 2.0;
        score -= (1.0 - progress) * 10.0;

        // If no existing bin fits well (current bin would leave a sliver),
        // opening a new bin becomes attractive: the caller compares scores.
        if bin_residual < item_size {
            // unreachable for new-bin call, guard only
        }
        if post_residual < 10 && !is_new_bin {
            score -= 20.0;
        }
    }

    // Mild pressure: many open bins -> discourage spreading; few open bins -> allow.
    score += open_bins_count as f64 * 1.5;

    // Nudge toward bins with residuals near the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fill bin perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item fits too; reward tightness of the pair packing.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 40.0_f64.min(200.0 / (1.0 + pair_waste));
        } else {
            // Next item won't fit here; penalize dead space that blocks it.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when reasonable fits exist, except for very large items
    // where a fresh bin may be better.
    if bin_residual == bin_capacity {
        if post_residual <= 20 && next_item_size <= post_residual {
            // fresh bin fine for big items
        } else {
            score += 25.0;
        }
    }

    // Mild preference to fill nearly-full bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that no future item (min size 1, typical 10..80) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score -= 6.0; // still usable by small items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack);
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post_residual waste.
        score += 0.5 * post_residual as f64;
    }

    // Prefer bins with larger residual when many bins are open (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (bin_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    // Discourage spreading across too many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let open_bins_scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        let desperation = open_bins_scarcity * 60.0 + fullness * 30.0 + progress * 10.0;
        // Base cost of a fresh bin; discount when desperate.
        score += 55.0 - desperation;
        // If next item is large, a fresh bin gives it room.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Mild time-horizon adaptation: early on, be conservative about fragmentation.
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 0.5 * progress) + pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits (small post_residual), stronger later in stream
    score -= (1.0 - pr_norm).powi(3) * (10.0 + 20.0 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += (gap / cap) * (5.0 + 15.0 * progress) * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
        if pr_norm * cap >= cap * 0.5 {
            score -= 8.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit dominates everything.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover: small post_residual classes are good,
    // dead-space classes (post_residual < 10) are terrible.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible into clean harmonic slots (e.g. 10,20,25,50)
    if post_residual % 10 == 0 || post_residual % 25 == 0 {
        score -= 12.0;
    }
    // Class B: post_residual can exactly host the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Lookahead fits into the leftover: strong reward scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / c);
        if slack == 0.0 {
            score -= 25.0; // exact two-item fit
        }
    }
    // Lookahead cannot use the leftover: penalize proportionally
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - pr / c);
    }

    // Dead space: leftover below minimum item size is wasted capacity
    if post_residual < 10 {
        score += 30.0 * (10.0 - pr);
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins: reward closeness of fill fraction to capacity
    let fill = (bin_capacity - post_residual) as f64 / c;
    score -= 10.0 * fill * fill;

    // Early in the stream, encourage bin diversity (penalize new-bin bias later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Slight preference for bins below mean residual (balance load)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 90.0 } else if post_residual < 20 { 45.0 } else { 0.0 };
        score += dead;
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Last-chance bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream
        score += open_bins_count as f64 * 8.0 + progress * 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for next item: penalize
        score += 15.0;
    }

    // Prefer bins below mean residual (pack into emptier bins less; favor fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that hypothetical placement
            let two_step_left = post_residual - next_item_size;
            score -= 100.0 - (two_step_left as f64) * 1.5;
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Penalize small dead space that nothing (min size 1..100) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins with residual below mean (tighter packing)
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 120.0 - mean_fullness * 100.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // fresh bin useful for upcoming larger items
        }
    }

    // Slight early-stream preference to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits in post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // penalize leaving residual that is slightly too small for next item (dead space)
            let gap = (next_item_size as f64) - (post_residual as f64);
            if gap < 10.0 {
                score += 2.0 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so if good fitting bins exist
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * (open_bins_count as f64);
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
        // late in stream, opening new bins is more acceptable (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balance), avoid outlier bins
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for fuller bins when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let mut score = post;
    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = post_norm * post_norm;
    let cubic = quad * post_norm;
    score += 12.0 * quad * (0.5 + progress) * cap * 0.01;
    score -= 8.0 * cubic * (1.0 - progress) * cap * 0.01;
    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 15.0 * tightness * tightness * (0.4 + 0.6 * progress);
    // Penalize waste relative to mean residual of open bins
    score += 0.05 * (post - mean_residual).abs();
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 + progress);
    }
    // Prefer keeping room for a known next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 5.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }
    // Mild penalty for proliferating bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * 0.1;
    // New-bin candidate: penalize unless fit is poor
    if bin_residual == bin_capacity {
        score += 4.0 + 20.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes by residue mod 10
    let r = post_residual;
    let class = r % 10;
    // Penalize small non-zero residues (unusable slivers)
    if r > 0 {
        let sliver_penalty = match class {
            1 | 2 | 3 => 12.0,
            4 | 5 => 6.0,
            6 | 7 => 3.0,
            _ => 0.0,
        };
        score += sliver_penalty;
    }

    // Reward filling the bin tightly (post_residual near zero is good)
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // prefer leaving room that matches harmonic classes of likely next items
            let gap = post_residual - next_item_size;
            score += 0.4 * gap as f64;
            if gap % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals are large/wasted
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        // if mean residual across open bins is large, opening a new bin is wasteful
        score += 0.8 * mean_residual;
        // early in stream, reusing bins is cheap; later, allow spreading
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // if many bins can fit, prefer them over new bin
        score += 2.0 * fitting_bins_count as f64;
    }

    // Prefer bins whose residual is close to item size (tight fit) over huge bins
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * slack;

    // Slight preference to keep fewer open bins when residuals are balanced
    if (mean_residual - post_residual as f64).abs() < 5.0 && open_bins_count > 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for typical future items (unusable small gaps).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else if post_residual > 0 {
            score += ((next_item_size as f64) - (post_residual as f64)) * 0.3;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (favor filling existing bins) by penalizing the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // Early in the stream, opening bins is cheap; later it is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Mildly favor bins with residuals close to the item (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (filling the emptiest bins first keeps tighter bins available).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post residual is good.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.0; // no-op guard

    // 2-step lookahead: if the next item exactly or nearly fits the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            // Perfect 2-item packing: fill bin completely with current + next item.
            score -= 60.0;
        } else if gap > 0 {
            // Next item fits after this one; the smaller the leftover, the better.
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward space.
            score += 15.0 * ((-gap) as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins with residual near/below mean are
    // natural targets; avoid wasting the fullest bins on loose fits.
    let res_f = bin_residual as f64;
    if res_f > mean_residual + 0.5 * item_size as f64 {
        score += 8.0; // this bin is much emptier than average; keep it flexible
    } else if res_f < mean_residual {
        score -= 5.0; // tighter-than-average bin: prefer using it
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current item
    // is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 {
            score -= 20.0; // large item: a fresh bin is fine
        } else {
            score += 30.0; // small item: strongly prefer existing open bins
        }
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for filling bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in stream, be picky; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional dead space penalty: small post_residual is good, but
    // tiny-but-nonzero residuals are wasted space. Reward exact fit strongly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 30.0 * (1.0 - tightness); // near-perfect fill
    } else {
        // penalize residuals that are unlikely to be reused by typical items
        score += 8.0 * tightness * (post_residual as f64).sqrt();
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 - 0.1 * next_item_size as f64;
        } else {
            // slack wasted relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Mean residual coupling: bins far below mean residual are "loose" —
    // prefer filling them; bins above mean are tight — slight penalty.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits badly everywhere else or there are no open bins.
    let is_new_bin = bin_residual == bin_capacity && open_bins_count > 0;
    if is_new_bin {
        // base cost of a fresh bin
        let mut nb = 45.0;
        // cheaper to open when many bins are open and mean residual is small
        nb -= 0.5 * open_bins_count as f64;
        nb -= 0.2 * mean_residual;
        // cheaper when this bin is the only fitting option anyway
        if fitting_bins_count <= 1 {
            nb -= 55.0;
        }
        // early stream: tolerate new bins; late stream: consolidate
        nb *= 1.0 - 0.4 * progress;
        score += nb;
    } else if open_bins_count == 0 {
        score -= 20.0; // must start somewhere
    }

    // Mild preference for bins whose residual is close to item_size (snug fit)
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: prefer tight fits (penalize large residuals); later: tolerate larger residuals
    score += prn * (8.0 - 12.0 * progress + 6.0 * p2) * 10.0;
    // Smooth interaction: squared residual term modulated by progress
    score += (prn * prn) * (20.0 * p3 + 5.0) * 6.0;

    // Reward good fit for the next item (lookahead)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        score -= (1.0 - diff / cap) * 15.0 * (1.0 - progress * 0.5);
    } else {
        // Last item: strongly prefer minimizing residual
        score -= (cap - pr) / cap * 25.0;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - prn);
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += open_bins_count as f64 * 0.5 * prn;

    // New-bin candidate: penalize opening a new bin unless residual would be small
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * (item_size as f64 / cap);
    }

    // Small tie-breaker toward bins whose residual is below the mean (tighter bins)
    score += (pr - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: quantize post_residual into capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (pr / (cap_f * 0.25)).floor(); // 0..4 harmonic class

    // Penalize residuals that are awkward classes (dead space unlikely to be reused)
    let dead_penalty = match quarter as u32 {
        0 => 60.0,            // nearly full: excellent
        1 => 12.0,            // leaves < 25: hard to fill
        2 => 25.0,            // leaves < 50: moderate
        3 => 18.0,            // leaves < 75
        _ => 5.0,             // wide open
    };
    score += dead_penalty;

    // Exact-fit bonus via modulo arithmetic
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.35; // chain placement reward
            // extra reward when next item exactly consumes remainder class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            score += 10.0; // remainder unusable for next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (smaller post_residual already does this)
        score += (fitting_bins_count as f64) * 0.5;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (pr - mean_residual) * 0.4;

    // New-bin candidate handling: only attractive late in the stream or when open bins are crowded
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 55.0 - 25.0 * progress - crowd * 1.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // pairing large items in fresh bins
        }
    }

    // Integer division threshold: reward residuals divisible into likely item classes
    if post_residual >= 20 && (post_residual / 20) * 20 == post_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residual gaps that are too small
    // to be useful for typical future items (unusable dead space).
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable sliver -> heavy penalty.
            score += 60.0;
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 30 {
            score += 12.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, mild tolerance for spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Mean residual coupling: if this bin's post_residual is far below the
    // mean, we are compacting well; reward it.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // fit is bad (large dead space) and the next item could use a full bin.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 20;
        let next_needs_room = next_item_size > 0 && next_item_size >= post_residual;
        if bad_fit || next_needs_room {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Lookahead: if the next item exactly fits the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Late-stream compaction: as the stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact match is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small-but-unusable residuals (dead space below min item size 1..=100
        // treat residual < next_item_size as potentially dead only if no future fit).
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 60.0 * tightness * tightness;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual too small for next item: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "dying";
    // prefer packing into them to consolidate.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 30.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 20.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect 2-step chain or current bins are poor fits.
    if bin_residual == bin_capacity {
        let base_penalty = 120.0 + 0.3 * open_bins_count as f64;
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        // Early in stream, fresh bins are cheaper (fewer open bins to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base_penalty * (1.0 + progress) - chain_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Reward if next item fits reasonably into post residual
            let r = post_residual as f64;
            score -= 20.0 * (next_item_size as f64 / r);
        } else {
            // Next item won't fit here: slight penalty for leaving awkward gap
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin opening when decent existing bins exist, unless current
    // fit is terrible and mean residual is high (bad fragmentation).
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // Opening a new bin: penalize more when current best fit is decent
            score += 35.0 * (1.0 - fit_quality);
            // But if mean residual is large (fragmented bins), opening is less bad
            score -= (mean_residual / bin_capacity as f64).min(1.0) * 15.0;
        } else {
            score -= 50.0; // must open a bin
        }
    }

    // Prefer packing into bins with low residual among peers (fill fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time-horizon coupling: early in stream, be conservative (favor balanced fills);
    // late in stream, be aggressive (close bins tightly).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste term with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate some slack
    // since consolidation matters less, but squared term keeps waste penalized.
    let mut score = pr * (1.0 + 0.8 * progress) - 40.0 * progress * norm_pr * (1.0 - norm_pr);

    // Reward filling bins nearly perfectly (small post_residual) increasingly over time.
    score -= 30.0 * progress * (-pr / 25.0).exp();

    // Penalize opening a new bin when existing bins fit, more strongly as stream progresses.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0 + 50.0 * progress + 5.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // If the next item is large, a fresh bin is more attractive.
        let nxt = next_item_size as f64;
        if nxt > 0.0 {
            score -= 25.0 * (nxt / cap) * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 30.0 * progress;
    }

    // Penalize leaving residual far from mean residual structure: dead space that
    // deviates from the fleet average is less reusable.
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 35.0 * (-gap / 20.0).exp();
    } else if next_item_size > post_residual as u32 {
        // Next item cannot use this residual; penalize large stranded residuals mildly.
        score += 10.0 * norm_pr * norm_pr;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residual space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits: post_residual in the smallest harmonic classes is good.
    let tight_bonus = if post_residual == 0 {
        40.0
    } else if post_residual <= bin_capacity / 10 {
        25.0
    } else if post_residual <= bin_capacity / 5 {
        15.0
    } else if post_residual <= bin_capacity / 3 {
        5.0
    } else {
        0.0
    };
    score -= tight_bonus;

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item-size classes (multiples of 10) are reusable, reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd/unusable residuals (small but nonzero) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap_f);
        } else {
            // Next item won't fit here: mild penalty scaled by wasted potential.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr) / cap_f; // open bins hold little
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
        score += 18.0 - 14.0 * fragmentation.max(0.0) - pressure.min(6.0);
    }

    // Mild preference for fuller bins relative to current mean residual.
    score -= 3.0 * ((mean_residual - pr) / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it cannot hold even the smallest plausible item (1..100, assume ~10 typical).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space relative to capacity: non-linear quadratic penalty on wasted fraction
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing bins
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if mean residual is high, prefer bins that reduce variance
    // (i.e., bins whose residual is far from the mean get a slight penalty)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small gap), slight penalty for near-miss
    if next_item_size > post_residual && post_residual > 0 && (next_item_size - post_residual) <= 10 {
        score += 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    // Empty bin has post_residual == bin_capacity - item_size, large residual -> penalize.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 2.0;
        // But if item is large, a fresh bin may be fine
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Early stream: be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement is ideal (chains perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next <= 10 {
                score -= 120.0;
            }
            // Penalize residual that is large but still unusable for next item.
            if post_residual < next_item_size {
                score += 60.0;
            }
        } else {
            // Post-residual cannot host next item: penalize proportional waste.
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    }

    // Compare against mean residual: bins with residual near the mean are
    // "typical"; prefer placing into bins whose residual is close to item
    // size (tight packing) relative to the fleet average.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when
    // no good fit exists. Make the empty bin moderately unattractive by
    // default, but attractive when current bins would leave large waste.
    if bin_residual == bin_capacity {
        let best_possible_waste = (bin_residual as f64 - item_size as f64) - (post_residual as f64);
        // Base penalty: prefer filling existing bins when reasonably tight.
        let existing_tight = (bin_residual as f64 - item_size as f64);
        if existing_tight <= 15.0 && fitting_bins_count >= 1 {
            score += 400.0; // existing bin is tight, don't open new one
        } else if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score += 250.0;
        } else {
            // Poor fits everywhere: opening a new bin is fine.
            score -= 50.0 + best_possible_waste * 0.0;
        }
        // Late in the stream, slightly favor consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Mild preference to spread load when many bins are open (keeps
    // residuals balanced and usable for future items).
    score += (open_bins_count as f64) * 0.5;

    // Penalize leaving residuals in the "dead zone" (too small for the
    // minimum item but nonzero) — unusable space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small but nonzero residuals (dead space), more so if the
    // lookahead item cannot use them.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if next_item_size == 0 || next_item_size > post_residual {
            score += dead * 60.0;
        } else {
            // Lookahead item fits: reward leaving a useful gap.
            score -= (post_residual as f64 - next_item_size as f64).abs() * 0.5;
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * (open_bins_count as f64).ln().max(1.0) * 15.0;

    // Time-horizon modulation: early on, be exploratory (favor tight fits less
    // rigidly); late in the stream, tighten packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    // Global residual context: if mean residual is small, avoid wasting this
    // bin's remaining space; if mean residual is large, prefer consolidation.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.4;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 120.0 * desperation;
        // A new bin is better if the item is large and future items may be big.
        score += item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + progress) - pr_norm * progress * 0.5;
    score += poly * bin_capacity as f64 * 0.35;

    // Reward tight fits more strongly as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * (1.0 + progress) * 12.0;

    // Penalize near-empty post residual that wastes capacity, smoothly
    let waste = (1.0 - pr_norm).powi(3);
    score += waste * 8.0 * (1.0 - progress);

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: prefer bins whose post residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // New bin candidate: penalize mildly, more when many bins open / late stream
    if bin_residual == bin_capacity {
        score += 18.0 + 0.4 * open_bins_count as f64 + 10.0 * progress;
    }

    // Mean residual alignment: prefer bins close to mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near 0 are "perfect fits".
    // Class residual into capacity fractions via integer division thresholds.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= eighth {
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 20.0;
    } else if post_residual > quarter && post_residual < 2 * quarter {
        score += 10.0; // awkward middle zone: dead space
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (harmonic classes of 10..80) are more likely to be filled later.
    let r = post_residual;
    if r >= 10 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 40 == 0) {
        score -= 8.0;
    }
    // Odd, prime-ish residuals are hard to reuse.
    if r > 0 && r % 10 != 0 {
        score += 4.0;
    }

    // Lookahead coupling: does next_item_size fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 55.0;
        } else if next_item_size < r {
            score -= (r - next_item_size) as f64 * 0.5;
        } else {
            // next item can't use this residual: penalize proportionally
            score += (next_item_size - r) as f64 * 0.15;
        }
        // Harmonic pair check: item + next divisible into capacity
        if (item_size + next_item_size) % bin_capacity == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        // Base penalty keeps new bins closed unless existing fits are bad.
        let mut new_bin_score = 35.0 + openness * 2.0 - progress * 5.0;
        // If next item is huge and mean residual is small, opening early is fine.
        if next_item_size >= 60 && mean_residual < 25.0 {
            new_bin_score -= 20.0;
        }
        // If no open bin fits (this call is the only fitting one and it's empty),
        // the new bin must win.
        if fitting_bins_count == 1 {
            new_bin_score -= 100.0;
        }
        return new_bin_score;
    }

    // Mild preference for tighter bins among equals.
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let post_f = post_residual as f64;
    let item_f = item_size as f64;
    let next_f = next_item_size as f64;
    let open_f = open_bins_count as f64;
    let fit_f = fitting_bins_count as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mean_res = if mean_residual.is_finite() {
        mean_residual.max(0.0)
    } else {
        0.0
    };
    let mean_ratio = (mean_res / cap_f).clamp(0.0, 1.0);

    let is_new_bin = bin_residual == bin_capacity;

    // Residual that a fresh bin would have after taking the current item.
    let escape_residual = (cap_f - item_f).max(0.0);

    // Estimate residual mass/mean in bins other than the candidate bin.
    let other_total = if is_new_bin {
        mean_res * open_f
    } else if open_bins_count > 1 {
        (mean_res * open_f - bin_residual as f64).max(0.0)
    } else {
        0.0
    };

    let other_mean = if is_new_bin {
        if open_bins_count > 0 { mean_res } else { 0.0 }
    } else if open_bins_count > 1 {
        other_total / (open_bins_count - 1) as f64
    } else {
        0.0
    };

    // If the total residual in all other open bins cannot fit the next item,
    // then no other open bin can possibly accept it.
    let certain_no_next_support = next_f > 0.5 && other_total + 0.5 < next_f;

    let next_support = if next_f > 0.5 {
        if certain_no_next_support {
            0.0
        } else {
            (other_mean / next_f).clamp(0.0, 1.0).max(0.25)
        }
    } else {
        1.0
    };

    let mut score = post_f;

    // Exact fills are highly desirable; they create no future dead space.
    if post_f <= 0.5 {
        score -= 100.0 + 60.0 * (1.0 - progress);
    } else if next_f > 0.5 && post_f + 0.5 >= next_f {
        // The next item still fits here: reward tight but feasible placement.
        let excess = ((post_f - next_f) / cap_f).clamp(0.0, 1.0);
        score -= 1.5 + 0.05 * next_f * (1.0 - excess) + 2.0 * (1.0 - excess);
    } else if next_f <= 0.5 {
        // Final item: any remaining residual is permanent waste.
        score += 0.04 * post_f;
    } else {
        // post_residual is too small for the next item: dead-space regime.
        let gap = next_f - post_f;
        let weak_dead = 5.0 + 0.18 * next_f + 0.22 * gap;
        let strong_dead = 14.0 + 0.85 * next_f + 0.85 * gap + 5.0 * progress;

        let dead_penalty = if escape_residual + 0.5 < next_f {
            // A fresh bin would also fail to fit the next item, so opening
            // a new bin does not rescue the lookahead. Use moderate pressure.
            weak_dead + 0.10 * gap
        } else if certain_no_next_support {
            // No other open bin can take the next item, and a fresh bin could.
            // Burning this bin's residual is highly undesirable.
            strong_dead
        } else {
            // Other bins may support the next item; stay conservative and
            // avoid unnecessarily opening a new bin.
            weak_dead + 0.15 * (strong_dead - weak_dead) * (1.0 - next_support)
        };

        score += dead_penalty;
    }

    // Pressure against activating/opening a new bin when alternatives exist.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can fit the item: the new bin is unavoidable.
            score -= 1000.0;
        } else {
            let fresh_can_serve_next = certain_no_next_support && escape_residual + 0.5 >= next_f;

            let new_bin_penalty = if fresh_can_serve_next {
                // Rare safe case: opening now prevents a future bin while no
                // other open bin can host the lookahead item.
                2.0 + 0.06 * open_f + 0.60 * fit_f
            } else {
                // General strong pressure: many open bins or many alternatives
                // make opening yet another bin risky.
                38.0
                    + 0.30 * open_f
                    + 1.80 * fit_f
                    + 6.0 * next_support
                    + 4.0 * mean_ratio
                    + 3.0 * (1.0 - progress)
            };

            score += new_bin_penalty;
        }
    }

    // Last-chance bonus for the only bin that can currently fit the item.
    if !is_new_bin && fitting_bins_count == 1 {
        let last_chance_reward = if next_f <= 0.5 || post_f + 0.5 >= next_f {
            8.0 + 0.06 * next_f
        } else if escape_residual + 0.5 < next_f {
            5.0 + 0.04 * next_f
        } else if certain_no_next_support {
            0.5
        } else {
            1.0 + 2.5 * next_support
        };

        score -= last_chance_reward;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits snugly with small slack (near-perfect 2-step chain).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted opportunity.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // Reward tight fits overall (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Exact fill of the bin is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Compare residual against mean residual: prefer filling below-average bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: keep its score moderate so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 10.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: near-exact fits are heavily favored.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize small dead space that no future item (>=10) can use,
    // but only when post_residual is truly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead coupling: bonus if the next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward for a chain: next item leaves a decent residual too.
            let chain_residual = post_residual - next_item_size;
            if chain_residual >= 10 {
                score -= 6.0;
            }
        } else if next_item_size > bin_residual {
            // Next item won't fit here anyway; waste matters less.
            score -= 3.0;
        } else {
            // Next item fits current bin but not post-placement: conflict penalty.
            score += 8.0 * (1.0 - tightness);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: when many bins are open, consolidate.
    let pressure = (open_bins_count as f64 / (1.0 + total_items as f64)).min(1.0);
    score += pressure * (mean_residual - post_residual as f64).abs() * 0.3;

    // Prefer bins whose residual is below the mean (pack tighter bins first),
    // leaving larger residuals in other bins more flexible.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Time horizon: early in the stream, be conservative (avoid near-full bins
    // that trap small residuals); late in the stream, fill aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * (post_residual as f64 / bin_capacity as f64) * 10.0;
    score -= t * 8.0 * tightness;

    // New-bin candidate: baseline cost of opening a bin, modulated by how bad
    // the alternatives would be. Opening is favored when item is large or
    // existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let waste_here = post_residual as f64; // = capacity - item
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 30.0 + waste_here * 0.5 - poor_fits * 60.0 - t * 15.0;
        // If next item is small, a fresh bin retains flexibility.
        if next_item_size > 0 && next_item_size <= waste_here as u32 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: prefer tight fits, with a non-linear polynomial shaping of wasted space.
    let mut score = post + 12.0 * pr * pr * cap;

    // Smooth polynomial coupling of waste with stream progress:
    // waste matters more early (keep bins reusable), less late.
    let p = 1.0 - progress;
    score *= 0.6 + 0.8 * p * p;

    // Reward filling a bin almost completely, amplified by progress.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: only bin that fits -> strong discount.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual can't hold next item but a tighter
    // alternative could; reward if it can (smooth interaction with progress).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post >= ni {
            score -= 8.0 * (ni / cap) * (0.5 + progress);
        } else {
            score += 6.0 * ((ni - post) / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many open bins (encourages closing bins).
    score += 0.4 * open_bins_count as f64 * pr;

    // Deviation from mean residual: prefer bins with residual near mean (balanced packing).
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate: make opening a new bin costly unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - tightness);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "nice" sizes
    // (multiples of 10, or small enough to likely be filled by future items)
    // are rewarded; awkward leftovers are penalized.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,                 // perfectly harmonic leftover
        1..=3 => score += 3.0,              // awkward sliver
        4..=7 => score -= 2.0,              // medium utility leftover
        _ => score += 1.0,                  // slightly awkward
    }

    // Integer-division tiers of post_residual: coarse harmonic bands.
    let tier = pr / 10;
    score -= (tier as f64) * 1.5;           // prefer leaving more usable space overall

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    if pr <= 5 {
        score -= 20.0;
    } else if pr <= 15 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this is a chained perfect fit — strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 15.0;                  // leaves a harmonic residue again
        } else if next_item_size > pr {
            // next item won't fit here; penalize leaving large dead space
            score += (pr as f64) * 0.2;
        }
        // bonus if next item is small and post_residual is in a friendly class
        if next_item_size <= pr && pr % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if pr > 40 {
            score += 8.0;                   // but not if it wastes half a bin
        }
    }

    // New-bin candidate handling: opening a new bin is penalized mildly,
    // unless current bins would leave very awkward residues.
    if bin_residual == bin_capacity {
        score = 100.0 - (item_size as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 60.0;                  // no alternative: new bin is fine
        }
        // early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
    }

    // Prefer filling bins that are already mostly full (small residual),
    // coupling with mean residual across open bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference to keep number of open bins small.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 2.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // over creating more; when few bins are open, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // New-bin candidate: make it moderately attractive when residual capacity
    // across open bins is high but fragmented, or when this bin is fresh.
    if bin_residual == bin_capacity {
        // Prefer new bin if no open bin fits well (post_residual small gaps avoided above),
        // but penalize opening bins when few items remain.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score += 8.0 - (remaining / (total_items.max(1) as f64)) * 4.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual - next_item_size < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: leftover is likely dead space.
        score += 8.0;
    }

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: as the stream advances, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_boost = 1.0 + 0.8 * progress;

    // Core waste term: penalize leftover space super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0 * progress_boost;

    // 2-step lookahead: reward exact or near-exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward proportionally to how snug it is.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit here: penalize leaving a stranded gap.
            score += 15.0 + 0.5 * gap;
        }
        // Bonus if post_residual is small enough to be nearly useless anyway (swept clean).
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // Relative to mean residual: bins with residual below mean are "tighter" — prefer them.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins densely.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 * 1.05 && fitting_bins_count > 0;
        if decent_fit_exists {
            score += 35.0; // penalize opening a new bin when a fit exists
        } else {
            score -= 5.0; // slight encouragement when everything else is bad
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual is already the base).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize leaving dead space that no plausible item (1..=100) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: reward if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or
    // existing residuals are large/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score -= 30.0 * pressure * (0.5 + 0.5 * progress);
        score += 20.0 * (1.0 - pressure); // penalize opening bins when good fits exist
        if fragmentation > 0.5 {
            score -= 5.0;
        }
        // Prefer keeping bins open early when many are already open.
        if open_bins_count > 3 && fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Mild bonus for balancing residuals across open bins.
    score += 0.03 * (post_residual as f64 - mean_residual).abs();

    // Slight preference for filling bins as the stream progresses.
    score -= 5.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64)) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
