pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of common
    // item sizes (10, 20, 25, 50) are more "usable" later.
    let r = post_residual;
    let mut harmony_bonus = 0.0;
    for m in [10u32, 20, 25, 50] {
        let rem = r % m;
        let dist = rem.min(m - rem) as f64;
        harmony_bonus += (1.0 - dist / (m as f64 / 2.0)) / m as f64;
    }
    score -= harmony_bonus * 6.0;

    // Small post-residual = tight fit: strongly reward.
    if r <= 5 {
        score -= 30.0;
    } else if r <= 10 {
        score -= 18.0;
    } else if r <= 20 {
        score -= 8.0;
    }

    // Dead-space penalty: residual that no plausible item (1..=80) can
    // pair with efficiently — penalize mid-range leftovers.
    if r > 20 && r < 30 {
        score += 6.0;
    }
    if r > 60 && r < 70 {
        score += 2.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // next item fits but leaves another residue: mild reward scaled by fit quality
        let leftover = (r - next_item_size) as f64;
        score -= 10.0 * (1.0 - leftover / 100.0);
    } else if next_item_size > 0 {
        // next item cannot follow here: slight penalty proportional to gap
        score += ((next_item_size - r) as f64) * 0.08;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the
    // current bin would leave a large, awkward residue.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: it's a fresh resource; neutral-ish,
        // but becomes attractive if existing fits are poor.
        score -= 15.0;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Reward using already-open bins to limit bin proliferation,
        // scaled by how many bins compete (scarcity).
        score -= 3.0 / (open_bins_count as f64).max(1.0);
    }

    // Mean-residual coupling: if this bin is far below the mean residual
    // (i.e., we're consuming the fullest bin well), reward it.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.05;

    // Stream progression: late in the stream, prefer tighter packing
    // (avoid opening bins that will be barely used).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if r > 40 {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += (dead_threshold - post_residual + 1) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    score += (open_bins_count as f64).powf(1.2) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creates a gap the next item cannot use: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate handling: attractive early or when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit_gap = mean_residual - item_size as f64;
        let poor_fits = mean_fit_gap < 0.0 || mean_residual > 70.0;
        if poor_fits || progress < 0.15 {
            score -= 35.0 + (mean_residual - 50.0).abs() * 0.3;
        } else {
            // Mid-stream: prefer filling existing bins; penalize new bins mildly.
            score += 15.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins with residual close to mean (keeps bin states balanced).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space (residual below min item size).
        if post_residual < 10 {
            score += 50.0 + (10.0 - post_residual as f64) * 5.0;
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let match_quality = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 30.0 * match_quality; // tight lookahead fit is desirable
        } else {
            // Next item cannot fit here; slight penalty proportional to gap.
            score += 5.0 + (nxt - post_residual as f64) * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fits),
    // penalize bins looser than average (wasteful placement).
    let diff = post_residual as f64 - mean_residual;
    score += 0.4 * diff;

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great
    // lookahead chain (e.g. item + next item fit nicely together).
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let chain_bonus = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            40.0 * (1.0 - (item_size + next_item_size) as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        score += base_penalty - chain_bonus;
    }

    // Mild stream-progression term: later in stream, be slightly more conservative
    // about waste since fewer chances to amortize.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 2.0 * progress * post_residual as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic suppression of dead space
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // chain fit: next item nearly fills leftover too
            let chain_left = post_residual as f64 - next_item_size as f64;
            if chain_left <= 10.0 {
                score -= 5.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally to wasted capacity
            score += (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: usually discouraged, but attractive when current bin is a bad fit
    if bin_residual == bin_capacity {
        let bad_fit = if bin_residual < item_size { 0.0 } else { (post_residual as f64 / bin_capacity as f64) };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.3 + mean_residual * 0.05;
        score += 25.0 + pressure;
        // open a new bin if it would leave a very usable large residual and few fitting bins
        if fitting_bins_count <= 2 && post_residual >= 50 {
            score -= 20.0 + 15.0 * (1.0 - progress);
        }
        let _ = bad_fit;
    }

    // Mild preference for bins with below-mean residual (consolidate emptier bins)
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev;
    }

    // Late-stream consolidation: prefer filling nearly-full bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = 1.0 + 2.0 * progress * norm_pr - progress * norm_pr * norm_pr;
    let mut score = pr * poly;

    // Reward tight fits: item filling most of the bin gets a bonus.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small for typical future items.
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    score += 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (bin_residual as f64 / cap);

    // New-bin candidate: penalize opening a new bin unless residual is large.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 0.5 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which "octave" of the capacity it occupies.
    let item_class = (item_size * 4) / bin_capacity; // 0..3 coarse class
    let next_class = if next_item_size == 0 { 9 } else { (next_item_size * 4) / bin_capacity };

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // residuals below the smallest item (class gap) are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Perfect-fill bonus: exact match leaves zero residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: does next item's class complement post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fits: reward leaving a compatible residue
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_fit_quality / cap);
        // bonus if next item exactly consumes the residue
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // lookahead cannot use the residue: penalize proportional to wasted class
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / cap * 10.0;
    }

    // Modulo harmony on capacity fractions: reward post_residual near
    // multiples of common item sizes (10,20,25,50).
    for m in [10u32, 20, 25, 50] {
        let r = post_residual % m;
        let d = r.min(m - r) as f64;
        score -= 3.0 * (1.0 - d / (m as f64 / 2.0));
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // base cost of opening a bin
        score += 35.0;
        // if many bins can fit, discourage new bin
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // if item is huge (top harmonic class), a fresh bin is fine
        if item_class >= 3 {
            score -= 20.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // if mean residual across open bins is large, they have room
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild pressure to balance residuals: prefer bins close to mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins whose residual matches item's harmonic class.
    let res_class = (bin_residual * 4) / bin_capacity;
    if res_class == item_class {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Medium dead space (10..20) is risky too: only items >=10 can use it.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize adding to bins when many bins are open,
    // but only mildly; dead-space term dominates.
    score += (open_bins_count as f64) * 1.5;

    // Progression: later in the stream, be more conservative about residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // New empty bin candidate: only attractive when this bin's fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0 - fill_ratio * 0.0; // baseline penalty
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0; // large item into fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post_residual is already base score).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 50.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize post_residual that is too small for next item but large enough to be dead space.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 50.0;
        }
    }

    // Late-stream consolidation: tighten up as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space quadratically (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny residual is great (nearly perfect fit)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward dead zone
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here anyway; slight penalty for wasting space
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when open bins have plenty of room.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But allow new bin if existing bins are nearly full (low mean residual).
        score -= mean_residual * 0.2;
    } else {
        // Reward using existing bins, more so as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (0.5 + progress);
        // Prefer bins with residual close to item (best-fit flavor).
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.05 * fit_gap;
        // Prefer bins whose residual is below mean (consolidate emptier space elsewhere).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized post-residual (dead space), convexly penalized.
    let x = pr / cap;
    let mut score = x * (1.0 + 1.6 * x * x);

    // Smooth non-linear coupling with stream progress: later in the stream,
    // dead space becomes increasingly costly (fewer chances to fill it).
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 18.0 * prog_term * x * x;

    // Tight fits are rewarded: small post_residual relative to item size.
    let it = item_size as f64;
    let tightness = it / (pr + it + 1.0);
    score -= 6.0 * tightness * tightness;

    // Exact / near-exact fit bonus (smooth via exponential).
    score -= 10.0 * (-pr as f64 / 4.0).exp();

    // Lookahead coupling: if next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score -= 7.0 * (-gap / 10.0).exp();
        score += 2.0 * (pr - n).max(0.0) / cap;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - prog_term * 0.5);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation).
    score += 0.6 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish score that only wins when all fits are bad.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 12.0 * prog_term - 0.25 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity/10 buckets
    let class = post_residual % (bin_capacity / 10); // 0..9
    // Rewards for landing on "usable" residual classes (multiples of 10, 25, 50)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 3.0;
    }
    // Penalize tiny dead-space classes (1..5 residual is nearly unusable)
    if post_residual < 5 {
        score += 15.0;
    } else if class <= 4 && post_residual > 5 {
        score += 3.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 12.0;
            }
            if nxt_post < 5 {
                score += 8.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this residual; penalize proportional waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; attractive only if current fit is bad
        score = 40.0 + post_residual as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // slightly favor new bin if it will pair item + next item cleanly
            if (item_size + next_item_size) % 10 == 0 && item_size + next_item_size <= bin_capacity {
                score -= 8.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Progress-based mild pressure to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;
    if open_bins_count > 8 && bin_residual < bin_capacity {
        score -= 1.0;
    }

    // Prefer bins tighter than the mean residual (good fill)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Tiny unusable gap: heavy penalty.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            // Larger gaps are more reusable: mild reward.
            score -= 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 3.0 * pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use this gap: penalize leaving a gap it can't fill.
            score += 5.0;
        }
    }

    // New-bin candidate handling: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how wasteful existing fits are.
        let waste = (post_residual as f64) * 1.5;
        let desperation = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        score = 70.0 + waste.min(40.0) - desperation - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (small post_residual).
    let mut score = post;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post - nxt).abs();
        if post >= nxt {
            // Next item fits perfectly -> strong reward.
            score -= 30.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 25.0; // perfect chain bonus
            }
        } else {
            // Next item won't fit here; penalize proportionally to leftover dead space.
            score += 0.3 * gap;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins),
    // penalize placing into bins that are already much looser than average.
    score += 0.5 * (mean_residual - post);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect 2-step chain.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post >= nxt {
            score -= 45.0 * (1.0 - (post - nxt).abs() / cap);
        }
        // More open bins -> slightly cheaper to open another? No: fewer open bins -> prefer reuse.
        score += 2.0 * open_bins_count as f64;
    }

    // Late in the stream, be more conservative about wasted space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits scaled by dead space nonlinearity
    let waste = post_residual as f64;
    score += (waste * waste) / (bin_capacity as f64);

    // If this is the ONLY fitting bin, strongly favor it (last chance)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: penalize leaving residual that fits neither current nor next item well
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            // next item can also go here: good chaining, reward proportional to chain tightness
            score -= 0.5 * n * (1.0 - progress * 0.3);
        } else if (post_residual as u32) < next_item_size && post_residual > 0 {
            // dead space for the next item
            score += 0.3 * ((post_residual as f64).max(1.0) / n) * 50.0;
        }
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // Base penalty to prefer reusing open bins
        let mut new_bin_score = 60.0;
        // Large items relative to capacity are fine to start a new bin
        let frac = item_size as f64 / bin_capacity as f64;
        new_bin_score -= frac * 90.0;
        // If few bins fit the item, opening new bin is safer
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        // Late in the stream, avoid proliferating bins
        new_bin_score += progress * 40.0;
        // Many open bins with high mean residual: prefer reusing
        new_bin_score += (open_bins_count as f64).sqrt() * 5.0 + mean_residual * 0.2;
        // If item is huge and would leave big residual anywhere, new bin is fine
        if item_size >= 70 {
            new_bin_score -= 50.0;
        }
        score += new_bin_score;
    }

    // Slight preference for bins with residual close to item (best-fit flavor)
    score += (bin_residual - item_size) as f64 * 0.05;

    // Coupling with global mean residual: bins far from mean residual are slightly deprioritized
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Smooth tightness measure: how well the item fills the bin (0..1)
    let fill = item_size as f64 / bin_capacity as f64;
    let tightness = (1.0 - (post_residual as f64 / bin_capacity as f64)).clamp(0.0, 1.0);

    // Non-linear reward for tight fits, amplified by progress:
    // quadratic + quartic coupling keeps it smooth, no piecewise constants.
    let tight_reward = tightness * tightness * (1.0 + 2.0 * progress) + tightness.powi(4) * progress;
    score -= 8.0 * tight_reward;

    // Penalize dead space that is too small to be useful later:
    // a smooth bump around small residuals (wasted capacity), scaled by mean residual.
    let dead = post_residual as f64 / bin_capacity as f64;
    let dead_bump = dead * (1.0 - dead) * 4.0; // peaks at 50% residual
    score += 3.0 * dead_bump * (1.0 - progress);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let next_fits = (next_item_size <= post_residual) as f64;
        let next_tight = if post_residual > 0 {
            1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64).abs()
        } else {
            0.0
        };
        score -= 5.0 * next_fits * next_tight.max(0.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        // Smooth "regret" of the best possible placement vs. this fresh bin
        let regret = (post_residual as f64 / bin_capacity as f64 - 0.5).clamp(0.0, 1.0);
        score += 4.0 * (1.0 - scarcity) * (1.0 + progress);
        score -= 6.0 * regret * scarcity;
    }

    // Mild load-balancing: prefer bins whose residual is near the mean,
    // penalizing outliers via squared deviation.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev * dev * (1.0 - progress);

    // Small smooth preference for consolidating into fewer bins as stream ends.
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward exact/near-exact fills heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class: post_residual divisible by common item classes (10, 20, 25, 50)
    let classes = [10u32, 20, 25, 50];
    let mut harmonic_bonus = 0.0;
    for c in classes.iter() {
        if post_residual % c == 0 {
            harmonic_bonus += 30.0;
        }
    }
    // If next item exactly matches a harmonic class of the residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        for c in classes.iter() {
            if post_residual % c == 0 && next_item_size % c == 0 {
                harmonic_bonus += 60.0;
            }
        }
        if next_item_size == post_residual {
            harmonic_bonus += 500.0;
        }
    }
    score -= harmonic_bonus;

    // Penalize dead space: residual too small for the smallest plausible item (1..100 unknown, use ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Lookahead coupling: if next item cannot fit this bin's post_residual, mild penalty
    if next_item_size > 0 && next_item_size > post_residual {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: only open a new bin if current fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer reusing open bins
        score += 120.0;
        // But if many bins fit, still prefer existing ones more
        if fitting_bins_count > 2 {
            score += 80.0;
        }
        // If very few fitting bins and mean residual is fragmented, allow new bin
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
        // Prefer new bin if mean residual across open bins is small (all nearly full)
        if mean_residual < 15.0 {
            score -= 50.0;
        }
    }

    // Mild reward for using bins with larger residuals (best-fit bias already via post_residual)
    score -= 0.1 * (bin_residual as f64 - pr);

    // Slight preference for bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    // Integer-division threshold on post_residual: penalize awkward thirds
    if post_residual > 0 && post_residual % 3 != 0 && post_residual < 33 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 1) are pure waste; penalize quadratically.
    if post_residual < 1 {
        score += 1000.0;
    }
    // Penalize "awkward" residuals: gaps that fit nothing likely to arrive.
    // Treat gaps below half of the mean residual as increasingly dead.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual - post_residual as f64) * 1.5;
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward placements that still leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + post_residual.min(next_item_size) as f64 * 0.25;
        } else {
            // The next item won't fit here afterwards: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Open-bin pressure: discourage spreading across many bins, but relax
    // pressure as the stream progresses (closing bins early is fine later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.5 - 1.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // If several bins fit, prefer the tightest fit (smallest post residual
    // already captures this, but add tie-breaker against huge leftovers).
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no good existing fit exists (large dead-space
    // penalty on chosen bin) or when few bins are open early on.
    if bin_residual == bin_capacity {
        let fallback_cost = 15.0 + open_bins_count as f64 * 1.2 - 10.0 * progress;
        score = fallback_cost + (bin_capacity - item_size) as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);

        // Perfect chain: item + next item fills bin completely
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Next item leaves a tiny dead space too (double-chain)
        else if post_residual > next_item_size {
            let second = post_residual - next_item_size;
            if second <= 10 {
                score -= 30.0;
            }
        }
    } else {
        // Last item: prefer tightest fit strongly
        score += 50.0;
    }

    // Relative to mean residual: prefer bins that are already relatively full
    let rel = mean_residual - post_residual as f64;
    score += 2.0 * rel;

    // Penalize large unusable dead space after placement
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny dead space is fine if bin nearly full
    }
    if post_residual > 50 {
        score += 10.0; // leaving half a bin empty is wasteful
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: default neutral-ish; open new bin only if it looks better
    if bin_residual == bin_capacity {
        score += 25.0 + 0.15 * open_bins_count as f64;
    }

    // Slight preference to fill older bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward if the next item can fit in the post residual (chained placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain_tightness;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating dead space the next item cannot use.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - item_size as f64).abs() / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; later, prefer consolidating into open bins.
        score += 6.0 + 14.0 * (1.0 - progress) - 10.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        }
    }

    // Prefer filling bins with larger residuals (reduce global fragmentation).
    if bin_residual < bin_capacity {
        let above_mean = bin_residual as f64 - mean_residual;
        score += 0.05 * above_mean.max(0.0);
    }

    // Mild penalty for spreading across many open bins when a compact option exists.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress) + 40.0 * x * x * (0.5 + progress);

    // Reward tight fits: interaction between post_residual and item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Penalize dead space that next item cannot use (smooth coupling).
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let usable = (pr - nx).max(0.0) / cap;
        score += 25.0 * usable * (0.5 + 0.5 * progress);
        let gap = (pr - nx).abs() / cap;
        score += 15.0 * gap * gap;
    }

    // Last-chance bonus: only fitting bin -> strong reward, stronger late in stream.
    if fitting_bins_count == 1 {
        score -= 60.0 * (0.4 + 0.6 * progress);
    }

    // Slight penalty when many bins are open and this one is far from mean residual.
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 10.0 * dev * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: make empty bin attractive only when residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - x).abs();
        score += 55.0 - 70.0 * fragmentation * (0.3 + progress);
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact fills are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classing: leftover mod 10 buckets (typical granularity of sizes)
        let class = post_residual % 10;
        // Leftovers that pair with the smallest items (1..=10) are semi-usable
        if class == 0 {
            score += 5.0; // multiple of 10: still reachable by small items
        } else {
            score += class as f64 * 0.8; // ragged leftovers penalized
        }
        // Usability window: leftover must be >= min item size to matter at all
        if post_residual < 10 {
            score += 60.0; // near-dead space
        }
    }

    // Best-fit core with non-linear tightness reward
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= tightness * tightness * 40.0;

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 40.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item can't use this leftover: mild penalty scaled by waste
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(80.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate logic: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // penalize opening new bins, more when many bins are open or many fit
        score += 90.0 + 3.0 * open_bins_count as f64 + 8.0 * fitting_bins_count as f64;
        // early stream: cheaper to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if mean residual is large, opening new bins wastes capacity
        score += 0.4 * mean_residual;
    } else {
        // slight preference for existing bins when mean residual is low (compact state)
        score -= 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small leftover gaps are unusable; penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual < 20 {
        score += 5.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post residual, this placement is attractive.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item would exactly fill post residual, extra reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Mean residual coupling: bins tighter than average are worth filling further.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Brand-new empty bin candidate: penalize so it is chosen only when
    // the item fits poorly everywhere else (large item relative to capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (bin_capacity - item_size) as f64;
        // Opening a new bin is fine if it would create a very tight fit anyway.
        if post_residual <= 5 {
            score -= 35.0;
        }
    }

    // Late in the stream: slightly prefer reusing bins to keep total count low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill = (bin_residual - post_residual) as f64;
    score -= (fill / cap) * (fill / cap) * 40.0;

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is costly: penalize unless nothing else is reasonable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 0.15 * open_bins_count as f64 - 8.0 * progress;
        // If the next item would perfectly fill the leftover of this item, opening is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= (1.0 - leftover_after_next as f64 / cap) * 20.0;
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, use it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 22.0;
        }
        // Penalize leaving dead space the lookahead item cannot use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // Reward bins whose residual is close to the mean (keeps bin states balanced).
        score += ((post_residual as f64 - mean_residual) / cap).abs() * 6.0;
    }

    // Perfect fit jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 30.0 * norm_pr * norm_pr
        + 60.0 * progress * norm_pr * norm_pr
        - 25.0 * (1.0 - progress) * norm_pr;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 15.0 * fit_next * (pr - nxt).min(30.0) / 30.0;
        score += 10.0 * (1.0 - fit_next) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (class 0) are gold.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Dead-space penalty grows super-linearly for mid-range waste.
    if post_residual > 10 {
        score += (post_residual as f64 - 10.0) * (post_residual as f64 - 10.0) * 0.05;
    }

    // Harmonic bucket of post_residual via integer division on 25-wide classes
    // (quarter-capacity harmonics). Waste in the 1..25 band is recoverable by
    // small items; waste above 50 is a half-empty bin.
    let quarter = post_residual / 25;
    match quarter {
        0 => score -= 10.0,
        1 => score += 5.0,
        2 => score += 15.0,
        _ => score += 30.0,
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained harmonic fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead credit proportional to how well next item fills leftover.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= fill * 20.0;
        // Penalize leaving a gap the next item cannot split into a good class.
        let gap_after = post_residual - next_item_size;
        if gap_after > 0 && gap_after < 10 {
            score += 10.0; // creates a tiny dead sliver
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer existing bins unless the new bin
    // would be clearly better (i.e., penalize the empty-bin call mildly so
    // it only wins when all open bins score badly).
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if stream is early and bins are scarce, allow opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 && open_bins_count < 3 {
            score -= 60.0;
        }
        // If mean residual of open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.8;
    }

    // Modulo-10 harmonic class of item_size: items that are exact divisors
    // of capacity pack well with complements; nudge accordingly.
    let comp = bin_capacity - item_size;
    if comp % 10 == 0 {
        score -= 5.0;
    }

    // Slight preference for filling fuller bins (tighter packing).
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items (1..=12)
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: post_residual small but still usable
    if post_residual >= 12 && post_residual <= 30 {
        score -= 10.0;
    }

    // Last-chance bin bonus: only one bin fits, strongly prefer it over new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: penalize opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
    } else {
        // Favor using existing bins slightly more as open count grows
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item fits in post_residual, mild reward
    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 5.0;
    }
    // If next item cannot fit in post_residual but could fit a fresh bin, penalize creating blocking residual
    if next_item_size > post_residual && post_residual > 0 && post_residual < 12 {
        score += 20.0;
    }

    // Progression: late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mean residual coupling: avoid bins far below mean residual (fragmented bins)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits snugly (small slack after the lookahead placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - lookahead_slack as f64 / 100.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        let dead = next_item_size - post_residual;
        score += 0.8 * dead as f64;
    }

    // Favor tight fits relative to mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable slivers (< 10) that likely can't fit future items.
    if post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when open bins leave bad fits.
    if bin_residual == bin_capacity {
        let bad_open = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 45.0 };
        score = bin_capacity as f64 * 0.9 + bad_open - (open_bins_count as f64 * 2.0);
        if fitting_bins_count == 1 { score += 30.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 25.0;

    // Penalize leaving dead space that cannot fit typical upcoming items
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward bins that can also host the lookahead item after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer filling existing ones over opening new
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64;
    score -= crowd.min(20.0) * 0.6 * (0.5 + progress);

    // Prefer bins below mean residual (fill emptier-relative space wisely)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: penalize opening a new bin unless the fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > mean_residual + 10.0 {
            score += 10.0;
        }
    }

    // Slight bonus for exact fills
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger leftovers (exploration);
    // late in the stream, strongly prefer tight fits.
    let pr_norm = pr / cap; // 0..1
    let poly = pr_norm * pr_norm * (1.0 + progress) + 0.5 * pr_norm * progress;
    score += 40.0 * poly;

    // Reward when the lookahead item fits into the post residual (chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let chain_tightness = 1.0 - (pr - nxt) / cap;
            score -= 6.0 + 8.0 * chain_tightness * (1.0 + progress);
        } else {
            // post residual too small for next item: penalize proportionally to wasted fraction
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate handling: only attractive if current open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        // crowd small => bins nearly full => opening new bin is fine.
        score = cap * (0.35 + 0.5 * crowd) - 8.0 * (1.0 - crowd);
    } else {
        // Mild reward for filling fuller bins relative to mean residual.
        score -= 3.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bins leaving residual in "reusable" classes
    // (multiples of 10, small residuals) are rewarded; awkward mid-range residuals penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill, always great
    } else if pr < 10 {
        score -= 25.0; // tiny dead space, nearly perfect
    } else if pr % 10 == 0 {
        score -= 18.0; // harmonic class: residual aligns with typical item granularity
    } else {
        // penalize non-harmonic residuals, worse near the middle of the range
        let mid_penalty = 8.0 * (1.0 - ((pr as f64 - 50.0).abs() / 50.0));
        score += mid_penalty;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward proportionally to tightness of that fit
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - 0.2 * slack;
            if slack == 0.0 { score -= 10.0; } // exact chain fit
        } else {
            // next item won't fit: penalize, scaled by how much it misses
            let miss = (next_item_size - pr) as f64;
            score += 0.15 * miss.min(40.0);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: empty bin gets a baseline cost so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 45.0;
        // opening early in the stream or when few bins are open is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        if open_bins_count == 0 { score -= 50.0; }
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 60 { score -= 10.0; }
    }

    // Prefer tighter bins overall: compare residual to mean residual of open bins
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Integer-division threshold: bins whose residual is in [item_size, item_size+5]
    // are near-perfect fits; reward them
    if bin_residual >= item_size && (bin_residual - item_size) <= 5 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible future item are heavily penalized.
    let min_gap = 12.0f64.min(post_residual as f64);
    if (post_residual as f64) < min_gap {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Reward tight fits (small relative waste).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Penalize bins with residuals far below the mean (already cramped),
    // prefer bins whose residual is close to the item (perfect nesting).
    let gap_to_item = (bin_residual as f64 - item_size as f64).abs();
    score += 0.4 * gap_to_item;

    // Open-bin pressure: discourage scattering across many bins early.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item is large, avoid leaving awkward mid-sized gaps.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let late = step_index as f64 / total_items.max(1) as f64;
        let poor_options = (fitting_bins_count == 0) as i32 as f64
            + (fitting_bins_count == 1 && bin_residual - item_size < 10) as i32 as f64;
        // Base cost of opening a new bin, discounted when alternatives are bad.
        score += 25.0 - 30.0 * poor_options - 10.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that closely matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-gap / 20.0).exp(); // strong bonus when next item fills this bin's leftover
        // exact 2-step completion: item + next item fill bin perfectly
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // if next item cannot fit anywhere afterwards, avoid leaving a just-barely-useless gap
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // last item: prefer minimal waste
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits (small post_residual relative to capacity)
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize creating dead space below the minimum item size (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins whose residual is already below average (consolidating fullness)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight bias toward keeping few open bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so a decent fit in an existing bin wins
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 {
            // opening fresh is attractive if current best leftover wouldn't fit the next item well
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 6.0 * (-gap / 15.0).exp();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap < 10 {
                score -= 15.0;
            } else {
                score += gap as f64 * 0.5;
            }
        } else {
            // Next item cannot use this bin's leftover; mild penalty for large leftovers.
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins among many open bins (first-fit-decreasing-like pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * open_bins_count as f64 * 2.0;

    // Global state: if mean residual is high, encourage consolidating into existing bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = post_residual as f64 > 0.4 * bin_capacity as f64
            || (fitting_bins_count == 0);
        if large_item || poor_fit {
            score -= 20.0 + 15.0 * progress;
        } else {
            score += 30.0;
        }
        // Early in the stream, opening fresh bins is cheaper (more future items to fill them).
        score -= (1.0 - progress) * 10.0;
    }

    // Time horizon: late in the stream, be more conservative; avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.9 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Small nudge toward bins whose residual is a multiple-friendly size for common items.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, with a smooth non-linear (quadratic) waste term.
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Coupling: waste matters more as stream progresses (fewer chances to reuse space later).
    score *= 1.0 + 0.8 * progress * (1.0 - pr_norm);

    // Tight fits (small post_residual) reward: subtract a smooth bonus.
    score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        // Next item cannot fit: penalize leaving moderately large dead space.
        score += 4.0 * pr_norm * (1.0 - progress);
    }

    // Encourage balancing residuals: prefer bins near the mean residual (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Crowding: with many open bins, slightly favor filling existing bins over new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify dead space into residue classes ---
    let pr = post_residual;
    let class = pr / 10; // coarse class (0..10)
    let rem = pr % 10;   // fine residue

    // Reward post-residuals that fall into "usable" harmonic classes:
    // residual >= 50 is half-bin reusable; residual in [30,50) is medium;
    // residual in (0,10) is dead space -> penalize.
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr >= 50 {
        score -= 18.0 + 0.2 * (pr as f64 - 50.0);
    } else if pr >= 30 {
        score -= 8.0;
    } else if pr >= 10 {
        score -= 2.0 + 0.1 * class as f64;
    } else {
        // dead space < 10: penalize heavily, worse the smaller it is
        score += (10 - pr) as f64 * 1.5;
    }

    // Fine residue bonus: post_residual divisible by common item granularities
    if rem == 0 {
        score -= 3.0;
    } else if rem == 5 {
        score -= 1.5;
    }

    // --- Coupling with next item (lookahead k=2) ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly in the leftover: strong reward
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 25.0;
            } else if slack <= 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use the leftover: mild penalty scaled by gap
            let gap = next_item_size - pr;
            if gap <= 10 {
                score += 4.0; // near-miss: annoying dead space likely
            }
        }
    } else {
        // last item: prefer tightest fit only
        score -= 5.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // this is the only bin that fits; opening a new bin costs ~1 unit of waste
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // plenty of alternatives: be picky about tight fits
        score += 3.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // brand-new bin: attractive only if existing bins are crowded or fit is poor
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let base = 35.0; // opening a bin is expensive
        let discount = crowding * 20.0
            + if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score = base - discount + item_size as f64 * 0.1;
        // if next item is large, a fresh bin is safer
        if next_item_size >= 60 {
            score -= 6.0;
        }
        return score;
    }

    // --- Progression coupling: late in stream, consolidate aggressively ---
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= progress * 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins below mean residual (filling the emptier ones balances the pool)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Many open bins: encourage closing small-residual bins
    if open_bins_count > 8 && post_residual < 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize wasting a large bin on a small item when residual stays huge.
    if post_residual > 70 {
        score += 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 8.0 * (open_bins_count as f64);
        // But if nothing else fits well, new bin is fine (handled by fitting count below).
    } else {
        // Reward using existing bins, more so when they are crowded.
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item can't reuse the gap -> dead space likely.
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early stream: be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly or well
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain fit
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0; // near-perfect chain fit
        }
        // If next item can't fit here, penalize leaving moderate dead space
        if next_item_size > post_residual && post_residual > 0 {
            score += 0.3 * post_residual as f64;
        }
    } else {
        // Last item: just minimize residual
        score += 0.1 * post_residual as f64;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if current bin would leave a big residual
        // and mean residual is already high
        score += 40.0 - 0.4 * post_residual as f64;
        score += 0.2 * (mean_residual - post_residual as f64).max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    } else {
        // prefer tighter fits relative to mean residual
        let tightness = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * tightness;
        score -= 5.0; // slight bias toward existing bins
    }

    // Late in stream: reduce waste more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful later.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 2.0 * (item_size as f64) / (1.0 + post_residual as f64);
    }

    // Lookahead: if the next item fits perfectly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins whose residual is below mean residual (more filled bins first).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in the stream, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64) / (bin_capacity as f64);

    // Many open bins: favor filling existing ones over opening new bins.
    score += 0.3 * (open_bins_count as f64);

    // New-bin candidate: penalize unless residual of this bin is large and item is small.
    if bin_residual == bin_capacity {
        score += 12.0 - 0.1 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) && item_size > 0;

    // Smooth non-linear waste model: waste grows super-linearly for tiny residuals.
    let mut score = 100.0 * x * x + 40.0 * x * x * x * x;

    // Coupling with stream progress: late in the stream, tight fits matter more.
    let tightness = 1.0 - x;
    score -= 25.0 * tightness * (0.5 + progress);

    // Penalize residuals that are small but not zero (dead space), smoothly.
    let dead = (x * (1.0 - x) * 4.0).powi(2); // peaks at x=0.5
    score += 15.0 * dead;

    // Reward bins whose residual is close to the next item size (smooth coupling).
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs() / cap;
        score -= 20.0 * (-8.0 * diff * diff).exp();
    }

    // Divergence from mean residual across open bins: prefer balanced or extreme fills smoothly.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize smoothly, scaled by how many bins already fit the item.
    if is_new_bin {
        let base = 30.0 + 25.0 * (1.0 - progress);
        score += base + 20.0 * (fitting_bins_count as f64).ln_1p();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it aligns with common item sizes
    let pr = post_residual;
    // Reward residuals that are multiples of common size classes (10/20/25/50)
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 12.0; }
        if pr % 20 == 0 { harmony += 8.0; }
        if pr % 25 == 0 { harmony += 8.0; }
        if pr % 50 == 0 { harmony += 10.0; }
        score -= harmony;

        // Dead space penalty: small, non-harmonic residuals are wasted
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 && pr % 10 != 0 {
            score += 15.0;
        }

        // Integer-division threshold: classify residual into thirds of capacity
        let third = bin_capacity / 3;
        if pr < third {
            score += 5.0; // small leftover, mildly bad unless zero
        } else if pr >= 2 * third {
            score -= 3.0; // roomy bin still, fine
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 60.0;
        } else {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 8.0; // next item won't fit here; slight penalty
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling more-open bins when many bins are open (keep bin count down)
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.5;
    }

    // New-bin candidate: only attractive when item is large relative to typical residual
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 30.0 + progress * 10.0;
        } else {
            score += 20.0; // keep using open space when it's plentiful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual, mildly penalize leaving a mid gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Progression: early on, be slightly more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward bins where the leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space unless it's tiny.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 6.0 + 0.3 * dead;
            }
        }
    }

    // Relative to mean residual: prefer bins already below-average residual (consolidation).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
        // Early in stream, opening bins is cheaper; late, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that is
    // too small to ever fit a future item (min size 1..100, typical >=10)
    // should be penalized extra.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score += 40.0 * (1.0 - waste_ratio); // tiny unusable sliver
        } else {
            score += 5.0 * waste_ratio;
        }
    } else {
        score -= 25.0; // perfect fill: strong reward
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post_residual can't fit next item but a slightly larger residual would,
    // penalize mildly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 4.0; // this placement blocks a good next fit
        }
    }

    // Time horizon: early in the stream, be more conservative with open bins
    // (keep residuals flexible); late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: when mean residual across open bins is low,
    // filling any remaining space is more valuable.
    score -= 0.05 * mean_residual * (1.0 - progress);

    // Many open bins: prefer filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: empty bin should only win when the fit into open bins
    // would be very poor. Penalize the fresh bin moderately.
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if the item is huge relative to capacity, a fresh bin is fine
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let poly = base * base * (1.0 - base);
    let mut score = pr as f64;
    score -= 18.0 * poly * (1.0 + progress);
    let tight = 1.0 - (item_size as f64 / cap);
    score += 12.0 * tight * tight * progress;
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 8.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (-gap / cap) * progress;
        }
    }
    score += 0.5 * (mean_residual - pr).abs() / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions
    let class = post_residual % 10;
    // Penalize residuals in "awkward" classes (small but not zero)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space penalty
    }
    match class {
        0 => score -= 8.0,           // perfectly divisible residual
        1 | 2 | 3 => score += 4.0,   // sliver classes
        _ => {}
    }

    // Integer division thresholds on post_residual
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 6.0; // near-full bin: good, but slightly less priority than exact fit
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Lookahead coupling: can next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item won't fit here regardless; slight reward for using space now
            score -= 3.0;
        } else {
            // next item fits: reward tight packing chains
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 15.0; // chain closure
            } else if gap < 10 {
                score += 5.0; // creates tiny dead space for next item
            } else {
                score -= 4.0;
            }
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins when many are open (avoid bin proliferation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual - item_size) < 5 && item_size < bin_capacity;
        if bad_fit {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit a "typical" small item
    // (anything below the minimum plausible item size band) are dead weight.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.10);
    if (post_residual as f64) < dead_threshold {
        // Unusable sliver -> heavy penalty scaled by how close to zero it is.
        score += (dead_threshold - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits: the smaller the waste relative to the item, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheap so slightly favor fresh capacity
    // when the fit would leave a large awkward gap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 1.5;

    // Coupling with mean residual: if this bin is much emptier than average,
    // filling it is valuable (reduces fragmentation spread).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.4;

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and post_residual barely misses it, penalize a bit.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // New-bin candidate handling: an empty bin should only win when the best
    // existing fit is poor. Give the empty bin a moderate baseline so tight
    // existing fits (which subtract a lot) beat it, but bad fits don't.
    if bin_residual == bin_capacity {
        score = 45.0
            + post_residual as f64 * 0.5
            + open_bins_count as f64 * 2.0
            - if next_item_size > 0 && next_item_size <= bin_residual { 10.0 } else { 0.0 };
        // Late in the stream, opening new bins is more costly.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (low post_residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Prefer bins where the next item leaves minimal dead space too.
            score -= (30.0f64).min(slack as f64 * 1.5);
            // Bonus if next item fits with near-zero remainder.
            if slack <= 5 {
                score -= 60.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to wasted lookahead potential.
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: leaving a bin far below average
    // residual means creating outlier dead space; penalize.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + item_size as f64 * 0.5;
    }

    // New-bin candidate: make it moderately attractive only when the item is large
    // and no good fit exists (large post_residual elsewhere would be wasteful).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Encourage new bins early when few bins are open and item is big.
        if item_size >= 70 && open_bins_count <= 2 {
            score -= 30.0;
        }
        // Late in the stream, prefer filling existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
    }

    // Slight preference for tighter existing bins (smaller residual before placement).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: exact fill gets a big reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted space, scaled by capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 120.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0) * 0.5; // exact lookahead fit rewarded most
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover too small for next item: penalize dead space proportionally.
        score += (post_residual as f64) * 0.6;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the empty-bin candidate mildly,
    // more so early in the stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 80.0 + openness * 10.0 - progress * 30.0;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= item_size {
            score -= 25.0;
        }
    }

    // Global pressure: when mean residual is low, conserve remaining space
    // (penalize using a bin that leaves more than the average leftover).
    if bin_residual < bin_capacity {
        let diff = post_residual as f64 - mean_residual;
        score += diff * 0.15;
    }

    // Prefer filling bins with smaller residual first (best-fit tiebreak).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 40.0 * poly;

    // Reward tight fits more aggressively as the stream advances (smooth coupling).
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize post_residual that cannot accommodate the lookahead item (smooth decay).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 15.0 * gap * (1.0 - gap) * (0.5 + 0.5 * progress);
        let waste = if pr < next_item_size as f64 { (next_item_size as f64 - pr) / cap } else { 0.0 };
        score += 25.0 * waste * waste;
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0) * pr_norm;
    }

    // Interaction with mean residual: prefer bins near the mean (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize slightly so it is chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress - 6.0 * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space below the smallest item (<=10) is worthless.
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Modulo classes on post_residual: residuals that divide capacity into usable chunks are good.
    let pr = post_residual;
    if pr % 50 == 0 && pr > 0 {
        score -= 12.0; // exact half-capacity residual: very reusable
    } else if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: residuals in [10,30] are prime targets for small items.
    if pr >= 10 && pr <= 30 {
        score -= 5.0;
    } else if pr > 80 {
        score += 4.0; // huge residual means item was tiny; mild penalty vs saving space
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Perfect-ish match: post_residual close to next item size
            let gap = (pr as i64 - next_item_size as i64).unsigned_abs();
            if gap <= 5 {
                score -= 14.0;
            } else if gap <= 15 {
                score -= 7.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential
            let overshoot = next_item_size - pr;
            score += (overshoot as f64) * 0.35;
        }
    } else {
        // Last item: prefer filling bins tightly
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 1.5;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else if mean_r < item_size as f64 + 8.0 {
            score -= 8.0; // open bins are tight; fresh bin reasonable
        } else {
            score += 22.0; // decent fits exist; discourage opening new bin
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (mean_residual / bin_capacity as f64);

    // Mild penalty for spreading across many open bins when mean residual is large.
    if open_bins_count > 4 && mean_residual > 40.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space relative to capacity: large leftover gaps are wasteful.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 30.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Mean residual divergence: avoid bins that deviate wildly from the average state.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: penalize opening a new bin unless all else is bad.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * -0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect chain: next item exactly consumes remaining space
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving dead space the next item can't use
        if post_residual > 0 && next_item_size > post_residual {
            score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins below mean (consolidate emptier space usage)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin is a fallback
    if bin_residual == bin_capacity {
        // Opening a new bin is fine if item is large (poor fit elsewhere likely)
        let large = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 45.0 * large;
        // Later in the stream, slightly prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // But if many bins are open and none fit well, new bin may be better
        if open_bins_count > 5 && fit_ratio < 0.5 {
            score -= 20.0;
        }
    }

    // Small penalty for creating tiny unusable residuals (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space (wasted capacity that is hard to reuse)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    } else if item_size == bin_residual {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 0.03 * next_item_size as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global pressure: many open bins -> discourage opening new bins
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost plus pressure-scaled penalty
        score += 8.0 + 3.0 * pressure;
        // but allow new bins when existing residuals are fragmented (low mean residual)
        if mean_residual < 15.0 {
            score -= 5.0;
        }
    }

    // Time horizon: late in the stream, tighten up and avoid new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Mild preference for filling bins below the mean residual (balance fragmentation)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Tightness reward: prefer larger item share of the bin
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, with non-linear (quadratic) growth in normalized residual
    let norm_post = pr / cap;
    let mut score = norm_post + 1.5 * norm_post * norm_post;

    // Smooth coupling of residual waste with stream progress:
    // early on, large residuals are acceptable (bins stay open); late, waste is costly
    score += 2.0 * norm_post * progress * (1.0 - progress * 0.5);

    // Lookahead: reward residuals that can host the next item (smooth sigmoid-like fit)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = pr / nxt;
        let reward = 1.0 / (1.0 + (-2.0 * (fit_ratio - 1.0)).exp());
        score -= 3.0 * reward;
        // Exact fit bonus for next item
        if pr == nxt {
            score -= 2.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress;
    }

    // Prefer bins tighter than the mean residual (smooth coupling)
    score += 0.5 * ((pr - mean_residual) / cap);

    // Penalize spreading across many open bins mildly
    score += 0.02 * open_bins_count as f64 * norm_post;

    // New-bin candidate: neutral baseline with slight progress-dependent reluctance
    if bin_residual == bin_capacity {
        score = 1.0 + 1.5 * progress + 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by modulo 10.
    // Leftovers in classes {0} are "perfect"; classes {1..=5} are dead-ish space;
    // classes {6..=9} can still host medium items.
    let post_mod = post_residual % 10;
    let class_bonus = match post_mod {
        0 => -6.0,
        1..=5 => 4.0 + post_mod as f64,
        _ => -1.5,
    };
    score += class_bonus;

    // Integer-division threshold: how many "harmonic slots" of size 10 remain.
    let slots = post_residual / 10;
    score -= (slots as f64) * 2.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item nests
            let nest = (post_residual - next_item_size) % 10;
            score -= 4.0 - (nest as f64) * 0.4;
        } else {
            // next item won't fit here: slight penalty scaled by overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += (over as f64) * 1.2;
        }
    }

    // Capacity fraction coupling: reward bins whose fill fraction crosses 0.5 / 0.75 thresholds.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac >= 0.75 {
        score -= 5.0;
    } else if fill_frac >= 0.5 {
        score -= 2.5;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
        score += 20.0 - crowd.min(18.0);
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Mild tie-break toward bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste. Penalize hard as post_residual approaches unusability.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space: nothing can ever use this gap.
        score += 80.0;
    } else if post_residual < 25 {
        // Only tiny items can use it: partial dead-space penalty.
        score += 30.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Tightness reward: the smaller post_residual relative to capacity, the better,
    // but only when it stays usable.
    if post_residual >= 10 {
        score -= 0.35 * (bin_capacity as f64 - post_residual as f64);
    }

    // Open-bin pressure: discourage scattering across many bins slightly,
    // favoring bins that keep the fleet compact.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit would create dead space.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // no open bin fits well or the item would leave dead space everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base reluctance to open new bins.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if existing bins would leave dead space, a fresh bin is fine.
        if post_residual >= 25 {
            score -= 15.0;
        }
        // Lookahead: if next item is huge, a fresh bin with large residual is valuable.
        if next_item_size > 60 && post_residual >= next_item_size as u32 {
            score -= 20.0;
        }
    } else {
        // Lookahead coupling: reward bins whose post_residual can still host the
        // next item; penalize bins that would strand the lookahead.
        if next_item_size > 0 {
            if post_residual >= next_item_size as u32 {
                score -= 8.0;
            } else {
                score += 6.0;
            }
        }
        // Discourage near-empty old bins being drained wastefully when mean
        // residual is high (fragmentation signal).
        if post_residual as f64 > mean_residual + 30.0 {
            score += 10.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly
    // (avoid opening new bins) since leftover waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 30.0 * progress;
    } else if post_residual < 10 {
        score -= 20.0 * progress; // late stream: eliminate dead space aggressively
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Strong reward for perfect 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post - nxt).abs();
        score -= 60.0 * (1.0 - diff / cap).powi(3);
        // Exact match: big bonus
        if diff == 0.0 {
            score -= 80.0;
        }
        // Penalize leaving a gap that next item cannot use
        if nxt > post {
            score += 15.0 * (1.0 - (nxt - post) / cap);
        }
    }

    // Penalize dead space that is too small for typical items
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0;
        // But attractive if lookahead fits perfectly in a fresh bin
        if next_item_size > 0 && (post - nxt).abs() < 1.0 {
            score -= 50.0;
        }
    }

    // Context: many open bins with high mean residual -> tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * (mean_residual - post) * (0.5 + progress);

    // Slight preference for tighter fits overall
    score += 0.1 * post * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that likely cannot be filled later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 20.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize when lookahead item can't follow into this bin.
        score += 0.15 * next_item_size as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly when many open bins already have slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if mean residual is too small to fit the item anywhere nicely, allow new bin.
        if mean_residual < item_size as f64 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Prefer bins below mean residual (consolidate slack into emptier bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Prefer filling bins with large residual early to reduce fragmentation.
    score -= 0.05 * bin_residual as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Slight preference to keep a diversity of residual sizes; penalize very large post
    // residual when it exceeds typical item size range.
    if post_residual > 80 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth progress-weighted dead-space penalty: later in the stream, small residuals matter more
    let dead_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress * progress);
    score += 40.0 * dead_penalty;

    // Reward tight fits (small post_residual) more aggressively as stream progresses
    let tight_reward = (1.0 - norm_pr).powi(3) * (0.5 + progress);
    score -= 30.0 * tight_reward;

    // Last-chance bonus: penalize new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 20.0 * fit_quality * (1.0 + progress);
        } else {
            // penalize residuals that cannot host the next item, scaled by gap
            score += 10.0 * ((nx - pr) / cap) * (1.0 - progress);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (smooth interaction)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: mild penalty early, growing penalty late (favor consolidation over time)
    if bin_residual == bin_capacity {
        score += 5.0 + 60.0 * progress * progress;
        // but allow new bin if it would leave a perfectly reusable residual for next item
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) == item_size {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 18.0;
        } else if pr % 25 == 0 {
            score -= 12.0;
        } else if pr % 20 == 0 {
            score -= 10.0;
        } else if pr % 10 == 0 {
            score -= 7.0;
        }
        // Small unusable dead space is bad: penalize tiny residuals hard.
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 40.0;
    }

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how tightly next item fits (harmonic residue).
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
            if slack as u32 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // This bin becomes dead after placing current item.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual state.
    score -= (bin_capacity as f64 - mean_residual) * 0.05;

    // Mild pressure against opening new bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 - open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size (1) are impossible,
    // but "effectively dead" gaps are small residuals unlikely to fit future items.
    // Penalize small non-zero post_residual heavily (strict dead space avoidance).
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 0.8;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item if it fits (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Wasted gap that cannot host the next item: extra penalty.
        score += 10.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 20.0 * fill_ratio;
    }

    // Open-bin pressure: penalize picking among many open bins slightly,
    // but when this is the ONLY fitting bin, strongly favor using it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large dead space (poor fits) and there is meaningful load ahead.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Prefer new bin more when few open bins are available and mean residual is low.
        score -= 3.0 * open_bins_count as f64;
        score += 0.4 * mean_residual;
        // Late in stream, prefer reusing existing bins.
        score += 30.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain match is highly desirable.
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.35 * over;
        }
    }

    // Compare post residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize very small dead space (fragmentation) more than moderate leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer compact bins when many bins are open.
    score += 0.15 * (post_residual as f64) * (open_bins_count as f64 / 10.0);

    // Slight progression bias: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 {
        let min_item = 1.0f64;
        let waste = if (post_residual as f64) < min_item { 0.0 } else { post_residual as f64 };
        score += 0.15 * waste;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            score += 8.0; // would strand this bin's space
        }
        // Chain fit: residual after hypothetically placing next item
        let chain = post_residual as f64 - next_item_size as f64;
        if chain >= 0.0 {
            score -= 0.1 * chain;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: mild preference for fullest (smallest residual) handled via post_residual already

    // Time horizon: early in stream, prefer opening new bins to keep flexibility;
    // late in stream, consolidate into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening new bin is attractive if item is large and no good fit exists
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count <= 1 {
            score -= 20.0 * large_item;
        }
    } else {
        // Slight bonus for using existing bins as stream matures
        score -= 5.0 * progress;
    }

    // Global state coupling: if mean residual is high, prefer filling bins with large residual
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap;

    // Penalize proliferation of open bins early
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Small noise-free tie-breaker proportional to item size (prefer big items in emptier bins)
    score += 0.02 * (item_size as f64) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: reward tight fits (low post residual), non-linearly.
    let mut score = pr * pr / cap;

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, dead space matters more (fewer future items to fill it).
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += pr_norm * pr_norm * 20.0 * progress_weight;

    // Reward using bins that are already fairly full (residual close to item).
    let fill_pressure = 1.0 - (bin_residual as f64 / cap);
    score -= 15.0 * fit_ratio * fill_pressure;

    // Penalize leaving a residual that no typical item (1..100) fits well:
    // awkward gaps (small but nonzero) are dead space.
    let awkward = (pr_norm * (1.0 - pr_norm)).sin();
    score += 10.0 * awkward * awkward;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.5 * (open_bins_count as f64) * progress;

    // Prefer bins whose residual is near the mean residual (keeps bin sizes balanced).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Slight bias against opening a new bin when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Residuals that are "waste" classes (small, hard to fill) get penalized.
    let pr = post_residual as i64;
    if pr > 0 {
        // Penalize small dead space: residual < 10 is nearly unusable.
        if pr < 10 {
            score += 60.0 - (pr as f64) * 5.0; // residual 1..9 -> +55..+15
        }
        // Modulo classes: residual divisible by 5 or 10 is more reusable
        // since item sizes 1..100 often cluster on multiples of 5/10.
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Integer-division thresholds on post_residual / next_item_size:
        // if next item fits exactly into the post residual, big reward.
        if next_item_size > 0 {
            if next_item_size == pr as u32 {
                score -= 30.0;
            } else if next_item_size < pr as u32 {
                let ratio = pr as f64 / next_item_size as f64;
                // reward when next item leaves a small second residual
                let second = pr as u32 - next_item_size;
                if second < 10 {
                    score -= 8.0;
                }
                // harmonic ladder on ratio: exact multiples are good
                if ratio.fract() == 0.0 {
                    score -= 5.0;
                }
                // penalize if next item cannot fit anywhere else well
                score += (ratio - 1.0).min(3.0) * 2.0;
            } else {
                // next item won't fit here: slight penalty for tight coupling
                score += 3.0;
            }
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild crowding penalty scaled by how many bins compete
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Tightness reward: filling a large fraction of current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Progress-based modulation: early in stream, be conservative with
    // new bins; late, allow more aggressive spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate detection: prefer opening a new bin only when the
    // item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // opening a new bin is penalized when mean residual can still host
        // typical items; rewarded when residuals are fragmented.
        score += 15.0 + mean_r * 0.3 - progress * 10.0;
        if item_size >= 50 {
            score -= 10.0; // large items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // current + next cannot share a bin anyway: new bin is fine
            score -= 12.0;
        }
    } else {
        // Placing into an existing bin conserves bins: general reward.
        score -= 8.0;
        // Reward keeping residuals near the mean (balance the pool).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Small global pressure: more open bins -> prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 100.0; // perfect or near-perfect fill is highly rewarded
    } else if post_residual <= 20 {
        // gaps that only the smallest items can use: moderate dead space
        score += 15.0;
    } else if post_residual <= 35 {
        score += 5.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits the post-residual gap, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 {
        // penalize blocking the known next item
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; relax when many bins are open and fits are poor
        let poor_fit_pressure = if post_residual == bin_capacity && fitting_bins_count == 0 { 0.0 } else { 60.0 };
        score = 100.0 + poor_fit_pressure + mean_residual * 0.2 - open_bins_count as f64 * 1.5;
    }

    // Mild alignment with mean residual: prefer bins whose residual is close to the item need.
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    } else if post_residual <= 8 {
        score -= 150.0;
