    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 500.0; // next item fills this bin exactly
        } else if (gap as f64) <= 5.0 {
            score -= 250.0;
        } else if (gap as f64) <= 15.0 {
            score -= 80.0;
        }
        // Penalize leaving large unusable slivers the next item cannot use.
        if next_item_size as f64 > post_residual as f64 && post_residual > 0 && post_residual < 10 {
            score += 200.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to capacity, opening a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    // Slight preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

