        score -= 8.0;
    }

    // Lookahead: if the next item can fit in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 5.0 + 4.0 * chain_quality;
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item can't use, scaled by dead-space size.
        let waste = post_residual as f64;
        score += 0.05 * waste;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin,
    // especially when the residual would be small.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate: it should generally lose to any decent fit, but win when
    // all placements leave large dead space. Compare against the waste this bin would create.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when existing bins waste a lot.
        score += 12.0;
        // Late in the stream, opening a new bin is cheaper than fragmenting (fewer future items to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
        // If many bins are open and residuals are fragmented, a fresh bin is more attractive.
        score -= 0.05 * open_bins_count as f64;
        // If mean residual is small (fragmented state), new bin looks better.
        if mean_residual < item_size as f64 {
            score -= 3.0;
        }
    }

    // Global fragmentation pressure: when mean residual across open bins is large,
    // prefer bins that reduce the spread (place into bins with residual far from mean is fine;
    // prefer consuming the largest residuals to consolidate).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.03 * dev;

    // Mild time decay: early on, keep flexibility (avoid very small residuals being created
    // from large bins), later exploit tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.02 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
    let _ = total_items;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = post_residual;
    let _ = fitting_bins_count;
    0.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;

    // Dead-space penalty: leftover in (0,10) is nearly unusable for min-size items
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Harmonic class rewards: leftovers that are multiples of common item sizes are reusable
    match pr {
        0 => score -= 30.0,                      // perfect fit
        10 | 20 | 25 | 50 => score -= 18.0,      // highly reusable classes
        _ => {}
    }
    if pr >= 10 && class == 0 {
        score -= 8.0;                            // any multiple of 10 is decent
    }
    // Odd awkward residues (1..9 remainder classes) penalized mildly
    if pr >= 10 && class != 0 {
        score += class as f64 * 0.6;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // harmonic compatibility: next item divides / nearly divides leftover
            if pr % next_item_size == 0 {
                score -= 12.0;
            }
            let frac = next_item_size as f64 / pr as f64;
            if frac > 0.7 {
                score -= 10.0 * frac;
            }
        } else {
            // next item won't fit here; leftover likely becomes dead space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin should only win when fit is poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, softened early in stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * 0.55 - 15.0 * (1.0 - progress);
        if item_size as f64 / cap > 0.8 {
            score -= 20.0; // big items are fine in fresh bins
        }
    }

    // Prefer filling bins tighter than the current mean residual
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold anything useful are poison.
    // Treat post_residual below a "usable threshold" as dead space and penalize hard.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 4.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fill is excellent.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (1.0 + post_residual as f64);
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chains placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Post residual can't hold next item: mild penalty scaled by wasted capacity.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin (residual == capacity) is cheaper.
    score += 0.3 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; attractive when open bins are few.
        score += 5.0 - 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: if this bin is far below average residual (already tight),
    // prefer packing here to consolidate.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but weight by how "usable" the leftover is.
    let residual_f = post_residual as f64;
    let cap_f = bin_capacity as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let diff = (residual_f - next_f).abs();
        // Exact match: strong bonus (subtract heavily).
        if diff < 0.5 {
            score -= 30.0;
        } else if next_f <= residual_f {
            // Next item fits in the leftover: mild bonus scaled by closeness.
            score -= 8.0 * (1.0 - diff / cap_f);
        } else {
            // Next item does NOT fit the leftover: penalize dead space.
            score += 5.0 + 10.0 * (diff / cap_f);
        }
    } else {
        // Last item: just minimize post_residual (already the base).
        score += 0.0;
    }

    // Penalize leftover space that is too small to ever be useful (dead space).
    // Assume smallest plausible item ~ 1..=10; leftover < 10 is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Compare post_residual against mean residual: leaving a bin far below the
    // mean residual wastes capacity elsewhere; prefer bins whose leftover is
    // either zero or near the mean (still usable).
    if mean_residual > 0.0 {
        let rel = (residual_f - mean_residual).abs() / mean_residual;
        score += 4.0 * rel;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (subtract to lower score).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or many bins are already open (avoid bin explosion).
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / cap_f;
        // Prefer new bin for big items; penalize for small items.
        score += 20.0 * (1.0 - load_frac);
        // If few bins fit the item, opening fresh is more acceptable.
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins with tighter current residual among equals
    // (best-fit tiebreak already via post_residual; add small coupling).
    score += 0.05 * (bin_residual as f64 - residual_f - item_size as f64).abs();

    // Slight penalty proportional to number of open bins to discourage sprawl.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared penalty on wasted space
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins could fit, unless the fit is very tight
    if bin_residual == bin_capacity {
        let tightness = post_residual as f64 / bin_capacity as f64;
        let early = 1.0 - progress;
        // New bin is more acceptable early in the stream or when item is huge
        let new_bin_penalty = 25.0 * (1.0 - tightness) * (0.4 + 0.6 * (1.0 - early));
        score += new_bin_penalty;
        // If item nearly fills the bin, opening fresh is fine
        if item_size as f64 >= 0.85 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward residual
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins with residuals close to the mean (keep bin population homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild preference for using existing bins as stream progresses (avoid bin proliferation)
    if bin_residual != bin_capacity {
        score -= 3.0 + 5.0 * progress;
    }

    // Penalize very small unusable residuals slightly more when many bins are open
    if post_residual < 10 {
        score += 8.0 * (open_bins_count as f64).sqrt().min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer small post-residual, with a smooth non-linear dead-space penalty.
    // Squared term punishes large leftover space super-linearly.
    let mut score = pr + 0.35 * pr * (pr / cap) * (1.0 + progress);

    // Tightness reward: smooth interaction between fill ratio and stream progress.
    let fill_ratio = 1.0 - (pr / cap);
    score -= 12.0 * fill_ratio * fill_ratio * (0.5 + 0.5 * progress);

    // Perfect fit bonus (non-linear, saturating).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0 * (1.0 - (post_residual as f64) / 6.0);
    }

    // Dead-space trap: leftover space too small for typical future items.
    let min_useful = 1.0f64.min(pr) * 1.0; // keep grounded
    let _ = min_useful;
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Lookahead coupling: reward if next item can use the post-residual,
    // penalize if next item nearly fits but wastes the slot.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() < 1.0 {
            score -= 10.0;
        } else if ni > pr {
            score += 4.0 * ((ni - pr) / cap);
        } else {
            score -= 3.0 * (1.0 - (pr - ni) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: make empty bins mildly unattractive early, more so
    // when many bins are open with usable mean residual.
    if bin_residual == bin_capacity {
        let openness = if open_bins_count > 0 { (open_bins_count as f64).ln() } else { 0.0 };
        score += 6.0 + 2.5 * openness + 10.0 * (1.0 - progress);
        // But if no other bin really fits well, allow new bin (handled by
        // last-chance subtraction on the other candidate).
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (concentrate waste in fewer bins), smooth tanh-like coupling.
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * diff.tanh();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls in.
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Dead-space penalty: residuals that no plausible item (1..100) can use well.
    // Small residuals (1..10) are nearly dead; moderate ones (11..50) are semi-usable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: excellent
    } else if post_residual <= 10 {
        score += 45.0; // nearly dead space
    } else if post_residual <= 25 {
        score += 18.0;
    } else if post_residual <= 50 {
        score -= 4.0; // still very fillable
    } else {
        score -= 10.0; // large residual, keep flexible
    }

    // Integer-division harmonic classes: residual bucket via capacity/8 octaves.
    let octave = post_residual / (bin_capacity / 8).max(1);
    score += match octave {
        0 => 8.0,
        1 => 0.0,
        2 => -2.0,
        3 => -6.0,
        4 => -8.0,
        5 => -6.0,
        6 => -2.0,
        _ => 2.0,
    } as f64;

    // Lookahead coupling: reward residuals that exactly or nearly fit next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 50.0; // chains a perfect follow-up fit
            } else if slack <= 10.0 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item cannot go here anyway; residual is dead for the lookahead.
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - frac);
    }

    // New-bin candidate handling: an empty bin has maximal flexibility; prefer it
    // only when existing bins would be left with unusable slivers.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / ((step_index.max(1) as f64).max(1.0)).sqrt();
        // Mild bias: opening new bins is fine early, penalized when many bins are open.
        score += 30.0 + 4.0 * pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big item coming: fresh bin is attractive
        }
    }

    // Modulo harmonic class on post_residual: some residues pair notoriously badly.
    let r = post_residual % 10;
    score += match r {
        0 => -3.0,          // round residue, easy reuse
        1 | 9 => 4.0,       // awkward off-by-one slivers
        5 => -1.0,
        _ => 0.0,
    } as f64;

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * frac;

    // Mean-residual coupling: bins far from the mean get a nudge toward balance.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual <= 5 {
        score -= 25.0; // near-perfect fit
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small for the smallest plausible item (1..100, min 1),
    // but practically gaps < 10 are rarely reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // creates dead space
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0; // next item can't use this bin's remainder
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 3.0 * (0.5 + progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize slightly so existing usable bins win,
        // but allow opening when open bins are crowded (high pressure reduces penalty).
        score += 8.0 - pressure.min(7.0);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin — prefer filling it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item still fits after placement: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Placing here leaves a small unusable gap for the next item: penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.4 * (next_item_size - post_residual) as f64;
    }

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize bins far below the mean residual (wasteful use of a roomy bin)
    // when tighter options exist.
    if (bin_residual as f64) > mean_residual + 15.0 && fitting_bins_count > 1 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good existing option exists
    // (i.e., current bin's post-residual would be a small dead gap).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0
            - 15.0 * progress
            - if next_item_size > 0 && post_residual >= next_item_size { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize small dead space that is hard to fill later (awkward gap).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Bonus if post-residual matches next item size exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (post_residual as f64);

    // Time horizon: early on, be picky (penalize loose fits); late, accept anything that fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when residuals are poor or item is large.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual >= item_size as f64;
        if mean_fit && fitting_bins_count > 1 {
            score += 25.0; // discourage opening new bin when alternatives exist
        } else {
            score -= 5.0;
        }
        if item_size > 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling between post_residual and stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let coupling = pr * (1.0 + 0.6 * progress + 0.9 * prog2 + 0.5 * prog3);

    let mut score = coupling;

    // Reward tight fits with a smooth quartic-ish term on fill ratio
    score -= 18.0 * fill * fill * fill;

    // Penalize dead space relative to mean residual, smoothly scaled by progress
    let dead = (pr - mean_residual) / cap;
    score += 6.0 * dead * (1.0 + prog2);

    // Last-chance bonus (smooth exponential of scarcity)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving room for next item, smooth interaction
    let n = next_item_size as f64;
    if n > 0.0 {
        let fits_next = pr >= n;
        let slack = (pr - n).max(0.0) / cap;
        if fits_next {
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * (n / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins, smooth in count
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);

    // Encourage opening fresh bins late in stream when residual is large
    score += 3.0 * prog3 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals that few item sizes can use
    // Items 1..100; small residuals are hard to fill.
    let dead = match pr {
        0 => 0.0,
        1..=9 => 30.0 + (10 - pr) as f64 * 3.0,
        10..=19 => 8.0,
        20..=29 => 3.0,
        30..=49 => 0.0,
        50..=99 => -2.0, // large leftover still usable
        _ => 0.0,
    };
    score += dead;

    // Modulo-3 coupling between post_residual and next_item_size:
    // reward when next item can plausibly fit the leftover
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact modular harmony bonus
            if pr % next_item_size == 0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot use leftover: penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.4;
        }
        // harmonic class match: both in same decade residue class
        if class == next_item_size % 10 && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity
    if bin_residual == bin_capacity {
        // penalize new bin unless current item is huge relative to residual spread
        score += 15.0;
        // but if item is large (>50) and mean residual is small, new bin is fine
        if item_size > 50 && mean_residual < 30.0 {
            score -= 20.0;
        }
        // lookahead: if next item is large, a fresh bin preserves pairing potential
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Fraction of stream progressed: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mild penalty proportional to open bins to discourage sprawl
    score += open_bins_count as f64 * 0.1;

    // Slight nudge toward tighter bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Penalize gaps that are too small to hold even the smallest plausible item,
        // with a sharp non-linear blow-up as the gap shrinks.
        let dead_threshold = 10.0_f64.min(cap * 0.1);
        if pr < dead_threshold {
            score += (dead_threshold - pr) * 12.0 + (dead_threshold - pr).powi(2) * 4.0;
        }
        // General super-linear penalty on leftover space: exact fit is heavily rewarded.
        score += (pr / cap).powi(3) * 60.0;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < f64::EPSILON {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use this gap: penalize proportionally to wasted space.
            score += (post_residual as f64 / cap) * 15.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (6.0 + 8.0 * progress);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless
    // the resulting dead space would be terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        if post_residual > 0 && (post_residual as f64) < cap * 0.1 {
            score -= 5.0; // mild nudge to use it despite small gap
        } else {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only if no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a new bin
        } else {
            // Competing with existing bins: make new bin costly, but cheaper when
            // existing residuals are fragmented (high mean residual with poor fit).
            let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
            score += 35.0 - fragmentation * 10.0;
        }
    } else {
        // Reward using bins whose residual is close to the item (tight packing).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= tightness * 10.0;
    }

    // Mild global pressure to keep mean residual low (consolidation).
    score += (mean_residual / cap).max(0.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less dead space is better, nonlinearly emphasized.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // 2-step lookahead: if the next item exactly fills the post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fits into post_residual
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit in the leftover: penalize large leftovers
            let excess = (next_item_size - post_residual) as f64;
            score += 0.3 * excess;
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score += 10.0;
    }

    // Relative to mean residual: prefer placing into below-average-residual bins
    // (keeps large-residual bins available for large future items).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 45.0;
        score -= large_item_bonus;
        // Early in the stream, slightly discourage hoarding new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.01;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item cannot use the leftover: penalize large waste.
            score += post_residual as f64 * 0.3;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins early, more later.
        score += 15.0 + 60.0 * progress;
        // But if no open bin fits well (this bin would be very tight), allow opening.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: reward using bins as stream progresses.
        score -= 10.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0;
    }

    // Prefer bins whose residual is close to mean (keep residuals balanced).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: dead space penalized more heavily as stream progresses
    let poly = norm_post * norm_post * (0.5 + 2.5 * progress);
    score += 20.0 * poly;

    // Tight fit reward, modulated by progress
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Reward using bins that fit, especially last-chance bins
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // Prefer bins with residual below mean (consolidate large gaps)
    score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Lookahead: bonus if next item can still fit in post-residual
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 3.0;
        } else if next_item_size as f64 <= bin_capacity as f64 {
            score += 2.0 * norm_post;
        }
    }

    // New-bin candidate: prefer opening a new bin only when few bins fit or item is large
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count <= 1 || norm_item > 0.6 {
            -10.0
        } else {
            6.0 + 4.0 * (open_bins_count.min(20) as f64).sqrt()
        };
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = post / cap_f;

    // Harmonic classes: residual divisible by common item sizes is reusable
    let post_u = post_residual;
    let harmonic_bonus = if post_u == 0 {
        -30.0 // perfect fit, strongly favored
    } else if post_u % 10 == 0 {
        -8.0 // aligns with 10-unit granularity
    } else if post_u % 25 == 0 {
        -6.0
    } else if post_u % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward residual
    };
    score += harmonic_bonus;

    // Penalize large dead space (waste) non-linearly
    score += 0.6 * frac * frac * cap_f;

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_u {
            score -= 12.0; // chain placement possible
            // Extra reward if next item exactly fills residual
            if next_item_size as u32 == post_u {
                score -= 15.0;
            }
        } else {
            score += (next_item_size as f64 - post) * 0.3; // dead space for lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: discourage spreading, favor tight bins
    if open_bins_count > 3 {
        score += 0.4 * (open_bins_count as f64 - 3.0);
    }

    // Early in stream: allow more bins; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress;

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.1;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (< 10) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual close to item size (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Dead space is worse late in the stream when fewer chances remain to reuse gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 25.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: prefer filling existing bins over opening new ones.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, bonus; if not, penalize leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Prefer bins with residual below mean (already partially filled).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // New-bin candidate: make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (low post residual) non-linearly.
    score -= (1.0 - post / cap).powi(4) * 30.0;

    // 2-step lookahead: if the next item can fit into post_residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize dead space proportionally to gap.
            let gap = (nxt - post) / cap;
            score += gap * 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 15.0 + 25.0 * (1.0 - pressure) - 10.0 * progress;
        // Opening a new bin is fine if it enables a perfect 2-item chain.
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) >= next_item_size {
            score -= 30.0;
        }
    }

    // Slight preference for bins whose residual deviates favorably from mean residual.
    score -= (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: only one fitting bin, avoid wasting it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally to waste
            score += 0.05 * post_residual as f64;
        }
    }

    // Prefer bins with below-average residual (concentrate waste in few bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only for poor fits.
        score += 20.0 + 25.0 * progress;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
        // Opening new bin is attractive when open bins are crowded and full.
        if open_bins_count > 0 && mean_residual < item_size as f64 * 1.5 {
            score -= 18.0;
        }
    } else {
        // Mild reward for keeping many bins productive.
        score -= 0.02 * open_bins_count as f64;
    }

    // Prefer using larger-residual bins for large items to avoid fragmentation.
    if item_size > bin_capacity / 2 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;
    let smooth_progress = progress * progress * (3.0 - 2.0 * progress);

    let mut score = pr * (1.0 + 0.35 * smooth_progress);

    // Reward tight fits, more strongly late in the stream
    score -= 12.0 * tightness * tightness * (0.5 + smooth_progress);

    // Penalize leaving dead space relative to mean residual
    if pr > mean_residual {
        score += 0.25 * (pr - mean_residual) * (1.0 - smooth_progress);
    } else {
        score -= 0.15 * (mean_residual - pr) * smooth_progress;
    }

    // Last-chance bin: strong bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * tightness;
    }

    // Lookahead: favor bins whose post-residual matches next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if pr >= next_item_size as f64 {
            score -= 6.0 * (1.0 - gap / cap) * (0.4 + 0.6 * smooth_progress);
        } else {
            score += 0.2 * gap;
        }
    }

    // Discourage spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - smooth_progress);

    // Non-linear coupling of fill fraction with progress
    score -= 5.0 * (fit_ratio * tightness) * smooth_progress;

    // New-bin candidate: mildly penalize unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * smooth_progress + 0.3 * mean_residual * smooth_progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes.
    // Residuals divisible by 10 are more likely to be exactly filled later.
    let pr = post_residual as i64;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 12.0,
            1 | 9 => 2.0,
            2 | 8 => 4.0,
            3 | 7 => 6.0,
            4 | 6 => 8.0,
            _ => 10.0,
        };
        score -= class_bonus;

        // Integer-division thresholds: small residuals are dead space.
        let q = pr / 10; // number of full 10-slots
        if q == 0 {
            score += 30.0; // residual < 10: nearly unusable
        } else if q <= 2 {
            score += 8.0;
        } else {
            score -= 6.0; // roomy remainder is fine
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Tight-fill reward: post_residual small relative to capacity.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and no good fit exists.
    if bin_residual == bin_capacity {
        let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0
            + 15.0 * (1.0 - item_size as f64 / 100.0)
            + 10.0 * (open_bins_count as f64).tanh()
            - 12.0 * prog;
        // If next item could combine with this one's leftover, opening is fine.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Lookahead: if next item exactly fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let rem = post_residual - next_item_size;
            score -= 10.0 * (1.0 - rem as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    // to consolidate small leftovers.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Mild diversity pressure: many open bins -> favor filling existing ones.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for medium gaps that fit few future items.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits, small penalty to discourage near-dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: keep it slightly unattractive unless current bin wastes space.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.3;
    }

    // Progress-based nudge: late in stream, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize leaving a gap smaller than next item (dead space trap).
            let gap = (post_residual - next_item_size.min(post_residual)) as f64;
            score += 50.0 + gap.min(next_item_size as f64);
        }
    }

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins could accommodate the item well.
    if bin_residual == bin_capacity {
        score += 80.0 + mean_residual * 0.5;
        // If current item is large relative to capacity, opening a new bin is less bad.
        score -= (item_size as f64 / bin_capacity as f64) * 60.0;
    }

    // Mild preference for using emptier bins (relative to mean residual) to preserve fuller bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight tightening pressure as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use (sizes >= 1)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 + 15.0 * chain;
    } else if next_item_size > post_residual {
        // next item won't chain here; penalize wasted potential slightly
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many fitting bins => prefer the fullest one (highest fit_ratio already does this);
    // add mild penalty when bin is far fuller than average residual (avoid fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in stream, prefer closing bins tightly; early, allow new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 60.0 - 55.0 * scarcity - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize quantities
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post_frac = (post_residual as f64 / cap).clamp(0.0, 1.0);
    let item_frac = (item_size as f64 / cap).clamp(0.0, 1.0);
    let next_frac = (next_item_size as f64 / cap).clamp(0.0, 1.0);

    // Smooth polynomial coupling: residual waste grows super-linearly
    // with stream progress (late waste is harder to recover).
    let waste_term = post_frac.powi(2) * (1.0 + 3.0 * progress) + post_frac.powi(4) * (1.0 + 5.0 * progress);
    score += 30.0 * waste_term;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = (-6.0 * post_frac).exp();
    score -= 12.0 * tightness * (1.0 + item_frac);

    // Lookahead: if the next item fits the post-residual, reward this placement
    // smoothly via a Gaussian-like coupling of next size to post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64) / cap;
        let chain_fit = (-20.0 * diff * diff).exp();
        score -= 8.0 * chain_fit;
        // Penalize if post-residual becomes unusable for the next item
        let unusable = (post_frac * (1.0 - post_frac)).max(0.0);
        score += 4.0 * unusable * (next_frac / (post_frac + 1e-6)).min(2.0) * (post_frac < next_frac) as i32 as f64;
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: a fresh bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin early; relax late.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (open_bins_count as f64 + 3.0)).sqrt();
        score += 20.0 * (1.0 - progress) + 10.0 * openness * post_frac;
        // But if mean residual of open bins is very low (all nearly full),
        // opening a new bin is reasonable.
        let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 18.0 * (1.0 - mean_frac).powi(3);
    }

    // Mild penalty for spreading across many bins when mean residual is small.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: mod classes on capacity fractions
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward near-tight fits: post_residual in small classes (0..=10) heavily favored
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post <= 5 {
        score -= 45.0;
    } else if post <= 10 {
        score -= 30.0;
    } else if post <= 20 {
        score -= 12.0;
    } else if post <= 30 {
        score -= 4.0;
    }

    // Penalize dead space in the "unusable" class: post_residual smaller than any
    // plausible future item (items >= 1, but small leftovers are hard to use)
    if post > 0 && post < 10 {
        score += 8.0;
    }

    // Modulo arithmetic on post_residual: multiples of 10 pair well with
    // typical item sizes (items often land on 10-multiples)
    if post % 10 == 0 && post > 0 {
        score -= 10.0;
    }
    // Odd/awkward residues (mod 5 == 1 or 3) are slightly less reusable
    if post > 0 && (post % 5 == 1 || post % 5 == 3) {
        score += 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size as i64 == post {
            score -= 55.0;
        } else if (next_item_size as i64) <= post && next_item_size > 0 {
            // next item fits but leaves its own residue; scale by how tight
            let nxt_res = post - next_item_size as i64;
            score -= 20.0 - (nxt_res as f64) * 0.5;
        }
        // if next item does NOT fit here, this bin is a dead end for lookahead
        if (next_item_size as i64) > post {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins unless the fit is poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if no open bin fits well (large post_residual everywhere), allow it
        if post == cap {
            // score already includes post_residual = capacity; keep penalty
        }
    }

    // Prefer filling bins with smaller residuals first (best-fit core already
    // does this via post_residual); add mild pressure toward low mean_residual
    score += mean_residual * 0.05;

    // Slight late-stream tightening: as stream progresses, avoid waste more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are worst-case outcomes.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Nonlinear waste penalty: post_residual relative to bin capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // If the next item could fit into this bin's post_residual, reward keeping it viable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the known next item: penalize more if it's dead space.
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += pressure * 0.8;

    // New-bin candidate handling: opening a new bin is only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when existing bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 + 0.3 * fragmentation;
        if item_size >= 70 {
            // Large items: opening a fresh bin is often wise.
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    }

    // Slight preference for bins with below-mean residual (keep balance of usable space).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Dead space: next item cannot fit into the leftover.
        let waste = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.5 * waste;
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    score -= 20.0 * (1.0 - post_residual as f64 / cap);

    // Penalize bins far from mean residual (avoid fragmenting the bin pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when it enables the lookahead chain
    // (e.g., current item plus next item nearly fill a fresh bin) and few bins fit.
    if bin_residual == bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if next_item_size > 0 && pair >= cap * 0.9 && fitting_bins_count <= 2 {
            score -= 45.0;
        } else {
            score += 30.0;
        }
    }

    // Slight pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal, large leftover is dead space.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize small unusable residuals (dead space below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item still fits: mild reward proportional to slack after it
            let second_left = post_residual - next_item_size;
            if second_left < 10 { score -= 15.0; } else { score -= 4.0; }
        } else {
            // next item won't fit here: penalize leaving awkward mid residuals
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual < (item_size as f64) + 5.0 {
        score += 8.0 * (1.0 - progress);
    }
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when item is large relative to
    // capacity or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        } else if big_item > 0.6 {
            score -= 5.0 + 10.0 * (big_item - 0.6);
        } else {
            score += 15.0 + 20.0 * (0.6 - big_item); // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let x = r / c; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = x * x * (2.0 - x) * c;

    // Smooth coupling with stream progress: late in stream, tighter fits matter more
    score += 15.0 * progress * x * (1.0 - x);

    // Penalize residual that wastes space relative to mean residual of open bins
    score += 0.05 * (r - mean_residual).abs();

    // Lookahead: reward post residual that can host the next item (smooth kernel)
    if next_item_size > 0 && (next_item_size as f64) <= r {
        let fit_quality = 1.0 - ((r - next_item_size as f64) / c).abs();
        score -= 8.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item cannot fit in post residual: penalize dead space
        score += 4.0 * x * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - x);
    }

    // Many open bins: mild penalty to avoid bin proliferation unless tight fit
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals that are "nice"
    // fractions of capacity (multiples of common item sizes) are reusable.
    let pr = post_residual;
    let reusable = (pr == 0)
        || (pr % 10 == 0)
        || (pr % 20 == 0)
        || (pr % 25 == 0)
        || (pr % 50 == 0);
    if reusable { score -= 12.0; }

    // Dead space: tiny residual that almost nothing can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is king.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic coupling: exact divisibility of post_residual by next item
            let n = next_item_size;
            if pr % n == 0 {
                score -= 18.0 + (pr / n) as f64 * 2.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; slight penalty for wasting lookahead
            score += 4.0;
            // If next item exactly equals residual class modulo capacity, soften
            if (next_item_size + pr) % 100 == 0 {
                score -= 6.0;
            }
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should only win when the
    // current bin's fit is poor. Give the empty bin a moderate baseline.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.1 - (open_bins_count as f64) * 0.5;
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / cap) * 10.0;
        // Early in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 8.0;
    }

    // Slight preference for bins with below-average residual (more filled).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Integer-division threshold on residual thirds: bins whose residual
    // falls in the "middle third" of capacity are flexible.
    let third = bin_capacity / 3;
    if post_residual >= third && post_residual < 2 * third {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize leaving a gap that cannot fit typical items (dead space zone).
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 10.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot use the leftover space, penalize dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open bins pressure: prefer existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when open bins would waste space.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - item_size as f64;
        if avg_waste > 20.0 && open_bins_count > 0 {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    // Mild stream progression coupling: early on, be conservative with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Smaller leftover gap after next item is better.
            let gap = post_residual - next_item_size;
            score -= 50.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportional to wasted lookahead potential.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins tighter than average (small residual relative to mean).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins already fit reasonably well,
    // but allow new bins early in the stream or when the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill = item_size as f64 / bin_capacity as f64;
        score += 80.0 - 60.0 * fill - 20.0 * progress;
        // New bin is attractive if no open bin has decent room relative to item.
        if bin_residual < item_size {
            score -= 1000.0;
        }
    }

    // Mild preference for using more of the bin (tight packing).
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 25.0 * tight * tight;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            score -= 3.0; // lookahead-friendly placement
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * (2.0 + open_bins_count as f64).ln();

    // Mild deviation penalty from mean residual: avoid fragmenting the fleet.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early on, allow new bins (explore); late, prefer existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 6.0 + 14.0 * progress;
        // Opening a new bin is worthwhile if it keeps space for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0 * progress;
        }
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: quadratic dead-space penalty (smooth, non-linear in post_residual)
    let mut score = pr * (1.0 + 1.5 * norm_pr);

    // Smooth non-linear coupling of dead space with stream progress:
    // later in the stream, wasted space is more costly
    score += 20.0 * norm_pr * norm_pr * progress * (1.0 - progress * 0.5);

    // Reward tight fits: subtract proportionally to fill ratio, cubic coupling
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * fill * fill;

    // Lookahead: penalize if post_residual cannot fit next item (smooth hinge)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += 6.0 * (gap / cap) * (1.0 + progress);
        } else {
            // reward bins that can also host the next item, smoothly
            score -= 4.0 * (pr / cap) * (nx / cap);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins; mean-residual coupling
    score += (open_bins_count as f64).ln() * 1.5 + 0.02 * (mean_residual - pr).abs();

    // New-bin candidate: make empty bin attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score = 0.35 * cap + 25.0 * (1.0 - fragmentation) * (1.0 - progress) - 8.0 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that land in "useful" classes
    // (divisible by common small item sizes 10..50), penalize dead-space classes.
    let post = post_residual;
    if post > 0 {
        let mut class_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post % d == 0 {
                class_bonus += 8.0;
            }
        }
        if post % 5 == 0 {
            class_bonus += 2.0;
        }
        score -= class_bonus;
        // Very small dead space is bad unless it's exactly zero
        if post < 10 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Integer-division threshold on post_residual vs next item
    if next_item_size > 0 {
        if post >= next_item_size {
            // Next item fits here: reward proportional to tightness
            score -= 12.0 + 0.3 * (next_item_size as f64);
            // Harmonic class: post_residual % next_item_size small => good chain
            let r = post % next_item_size.max(1);
            score -= 0.2 * (next_item_size - r) as f64;
        } else {
            // Next item won't fit here: penalize hoarding space
            score += 0.15 * (post as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize moderately, more when open bins are few
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Early stream: opening bins is fine; late stream: prefer filling
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins near the mean (balanced packing)
    score += 0.1 * ((bin_residual as f64) - mean_residual).abs();

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to hold
    // even the smallest plausible future item are pure waste. Penalize heavily
    // when the gap falls into the "dead zone" (nonzero but < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: fully consume the bin, strongly reward.
        score -= 25.0;
    } else {
        // Usable leftover: mild reward proportional to how much remains usable.
        score -= 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, using it avoids
    // opening a new bin. Reward strongly, scaled by how well the item fills it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading out.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin (bin_residual == bin_capacity)
    // should only win when the fit into open bins would be terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with open bin count.
        score += 20.0 + open_bins_count as f64 * 2.0;
        // If the item fits snugly in the fresh bin (small leftover), it's a
        // reasonable opening; otherwise discourage.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score += 25.0;
        }
        // Early in the stream, opening bins is cheaper (need capacity anyway).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if the next item would fit into this bin's post_residual,
    // reward this placement (chaining items together).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Prefer bins whose residual is close to the mean (keep residuals uniform),
    // avoiding extreme outliers.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
