pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Tightness: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Penalize small dead space that nothing (min size 1..10) can use later.
    if post_residual > 0 && post_residual < 12 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this bin's remainder: mild penalty for wasting space.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more liberal with open bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fill_ratio;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with large mean residual -> prefer
    // filling existing bins; few open bins -> slight openness to new bins.
    if open_bins_count > 3 {
        score -= 0.8 * open_bins_count as f64;
    }
    score += 0.3 * mean_residual * (1.0 - fill_ratio);

    // New-bin candidate handling: an empty bin is a fallback; only win when the
    // item is huge (poor fit anywhere) or late in the stream.
    if bin_residual == bin_capacity {
        let huge_item = item_size as f64 > 0.8 * bin_capacity as f64;
        let base_penalty = if huge_item { 25.0 } else { 70.0 + 40.0 * (1.0 - progress) };
        score += base_penalty;
        if next_item_size > 0 && next_item_size <= bin_capacity && huge_item {
            score -= 20.0; // new bin can still host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // how snugly item fills bin

    // Reward tight fits (small post_residual relative to bin) with smooth coupling to progress.
    let tight = 1.0 - fit_ratio.min(1.0);
    score -= 30.0 * tight * tight * (1.0 + progress);

    // Penalize leaving dead space that can't fit typical items (mean residual context).
    let dead = post_residual as f64 / cap;
    score += 20.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: prefer new bin only when existing residuals are large
    // and the fit is loose.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let mean_tight = (mean_residual / cap).clamp(0.0, 1.0);
        // New bin attractive when open bins are mostly full (small mean residual).
        score += 15.0 * (1.0 - mean_tight) * (1.0 - mean_tight);
        score += 10.0 * (1.0 - fit_ratio.min(1.0)) * (1.0 - progress);
        // Lookahead: opening a fresh bin is good if next item is large.
        if next_item_size > 0 {
            let next_big = next_item_size as f64 / cap;
            score -= 20.0 * next_big * next_big * (1.0 - progress);
        }
    } else if next_item_size > 0 {
        // Reward placing here if next item fits into the resulting residual.
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 6.0 * progress;
        }
    }

    // Mild pressure against hoarding many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and mod 25.
    let r = post_residual;
    let residue10 = (r % 10) as f64;
    let residue25 = (r % 25) as f64;
    let harmonic = residue10 / 10.0 + residue25 / 25.0;

    // Penalize awkward residuals (non-zero small residues = dead space).
    if r > 0 {
        score += harmonic * 6.0;
        if r < 10 {
            score += 30.0; // tiny unusable sliver
        }
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 60.0;
    }

    // Coupling with lookahead item: does the leftover match a harmonic class of next item?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Next item fits here too -> reward tight coupling.
            let leftover2 = r - next_item_size;
            score -= 25.0;
            score += (leftover2 % 10) as f64 * 0.8;
            if leftover2 == 0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot use the leftover; penalize proportionally.
            score += (next_item_size - r) as f64 * 0.15;
        }
    }

    // Integer-division thresholds on residual thirds/quarts of capacity.
    let q = r / 25; // 0..4
    score += match q {
        0 => 12.0,
        1 => 4.0,
        2 => 0.0,
        3 => -6.0,
        _ => -10.0,
    };

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: bias toward reuse when open bins are numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_bins_count as f64 * 3.0 - mean_residual * 0.1 - progress * 5.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to the item itself.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 8.0;

    // Reward filling a bin that is more than half consumed.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (penalize opening new bins / spreading items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).sqrt() * 2.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // no open bin offers a decent fit (mean residual is low or item is large).
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 || (fitting_bins_count == 0) {
            score -= 30.0; // nothing fits well elsewhere: open a new bin
        } else {
            score += 35.0 + mean_gap * 0.5; // discourage wasteful new bins
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item: mild penalty scaled by gap.
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
