        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item cannot fit in leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        }
    }

    // Compare against mean residual: prefer bins below-mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // More competing bins that fit => mild penalty for wasting a scarce residual
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Late in the stream: consolidate into existing bins more aggressively
    score -= 10.0 * progress * tightness;

    // New empty bin candidate: should only win when open bins are badly fragmented
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when many items remain
        let horizon = if total_items > step_index { (total_items - step_index) as f64 } else { 1.0 };
        let mut new_bin_cost = 55.0 - 15.0 * (horizon / 1000.0).min(1.0);
        // if the next item is large and current residuals are large, opening fresh is attractive
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_bin_cost -= 12.0;
        }
        // if this bin is the only fitting bin, opening new is rarely better
        if fitting_bins_count <= 1 {
            new_bin_cost += 30.0;
        }
        score = new_bin_cost + 1.0; // slightly worse than a perfect fit in an open bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 14.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize more when post residual is wasted.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Early in the stream, be more willing to spread items (avoid fragmentation later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // Compare against mean residual: bins below-mean residual are scarce space, favor filling them.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by how poorly open bins fit.
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else if fitting_bins_count == 1 { 0.5 } else { 0.15 };
        let waste = if post_residual == bin_capacity { 0.0 } else { (bin_capacity - post_residual) as f64 / bin_capacity as f64 };
        score += 45.0 - 35.0 * poor_fit + 20.0 * waste;
        // Late in stream, prefer reusing open bins to avoid excess bins.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + t) - 2.0 * norm_pr * (1.0 - t) + t * t;
    score += 12.0 * poly;

    // Reward tight fits, scaled by progress
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness * (0.5 + t);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 6.0 * (gap / cap) * (1.0 + gap / cap) * (1.0 - 0.5 * t);
        } else {
            score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - t);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - t) + 5.0;
    }

    // Prefer bins with residuals far from the mean (consolidation)
    score += 4.0 * ((pr - mean_residual) / cap).abs() * (1.0 - t);

    // Mild pressure against accumulating many open bins late in stream
    score += 0.5 * open_bins_count as f64 * norm_pr * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes of 10.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = (post_residual % 10) as f64;

    // Reward residuals that are exact multiples of 10 (harmonic alignment):
    // such gaps are reusable by common item sizes (10,20,...,80).
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else {
        score += post_class * 0.35; // penalize awkward off-class dead space
    }

    // Non-linear dead-space penalty: small residuals are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // nearly unusable sliver
    } else if post_residual < 20 {
        score += 6.0;
    } else if post_residual >= 20 && post_residual <= 40 {
        score -= 4.0; // sweet spot: fits half the small item range
    }

    // Integer-division threshold coupling: post_residual / 20 classes.
    let post_quarter = post_residual / 20;
    score -= post_quarter as f64 * 2.5;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match: next item leaves an aligned residual again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let fullness = 1.0 - (bin_residual as f64 / cap);
    score -= fullness * 8.0;

    // New-bin candidate handling: neutral baseline, but discourage opening
    // new bins when good fitting bins exist and mean residual is high.
    if bin_residual == bin_capacity {
        score += 10.0;
        if mean_residual >= item_size as f64 {
            score += 12.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
    }

    // Mild pressure toward fewer open bins when mean residual is low.
    score += (open_bins_count as f64).ln() * (mean_residual / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste -> heavy penalty, super-linear.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Gap too small even for the lookahead item: mildly wasteful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few bins -> opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 6.0 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; small bonus if the
        // next item could combine with this item's residual.
        score += 30.0 + pressure;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Reward placing into bins below the mean residual (fill emptier bins),
        // penalize raiding the fullest bins.
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Post-residual too small for next item: penalize dead space more.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 35.0;
        // More open bins with low mean residual => opening new bin is worse.
        score += open_bins_count as f64 * 2.0;
        score -= mean_residual * 0.4;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // But if no open bin can fit (fitting_bins_count==0 among open bins),
        // the new-bin call is the only option; make it clearly lowest.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > item_size {
            score -= 10.0;
        }
    } else {
        // Open bin: mildly favor bins whose residual deviates from mean
        // (consolidate fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / c; // normalized post residual in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Reward tight fits more strongly as stream progresses (smooth polynomial)
    let tightness = (1.0 - prn) * (1.0 - prn);
    score -= (0.5 + 2.0 * p2 + 1.5 * p3) * tightness * c;

    // Penalize residual that is polynomially "dead" (too small to be useful) with progress coupling
    let dead = (prn * (1.0 - prn)).ln_1p(); // peaks mid-range, negative at edges
    score += (1.0 - progress) * 10.0 * (0.0 - dead);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual (smooth quadratic match)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs() / c;
        score -= 8.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        // Penalize if post residual is just barely too small for next item
        if pr < nxt {
            score += 5.0 * (1.0 - (nxt - pr) / c);
        }
    }

    // New-bin candidate: penalize opening new bins mildly early, more late
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * p2 + 10.0 * p3;
        // But if mean residual of open bins is low, new bin is attractive
        score -= (mean_residual / c).max(0.0) * 15.0;
    }

    // Mild preference for fuller bins relative to open-bin count
    score += 2.0 * (open_bins_count as f64).ln_1p() * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 / mod 25 create
    // "dead space classes". Penalize residuals that fall into awkward classes.
    let pr = post_residual;
    if pr > 0 {
        let m10 = pr % 10;
        let m25 = pr % 25;
        // small nonzero residues are worst (unusable slivers)
        score += 3.0 * (10 - m10.min(10 - 0)) as f64 * 0.1 * (m10 as f64 / 10.0);
        if m25 > 0 && m25 < 10 {
            score += 2.5; // awkward quarter-class
        } else if m25 == 0 {
            score -= 1.5; // clean quarter class
        }
        if pr % 20 == 0 {
            score -= 1.0;
        }
    }

    // Fractional fill thresholds via integer division of post_residual
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let threeq = 3 * bin_capacity / 4;
    if post_residual <= quarter && post_residual > 0 {
        score += 4.0; // bin nearly full: good, but keep priority ordering right
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 6.0;
    } else if post_residual < 10 {
        score -= 3.0;
    } else if post_residual >= threeq {
        score += 2.0; // leaving huge space: poor fit
    } else if post_residual > half {
        score += 1.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's class pairs well
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 || slack == 0 {
                score -= 3.0;
            } else {
                score -= 1.5;
            }
        } else {
            // next item won't fit here; penalize more if this bin was "spent"
            let overhang = next_item_size - post_residual;
            score += 0.05 * overhang as f64;
        }
    }

    // Last-chance bonus: this is the only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // neutral-ish baseline; opening a new bin wastes nothing if mean residual is high
        score = 0.5 * cap + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 1.0;
        }
        if fitting_bins_count == 0 {
            score -= cap; // no alternative, must open
        }
    }

    // Stream progression: early on, be conservative about wasting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 2.0;
    }

    // Prefer denser bins when many bins are open (consolidation pressure)
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 12.0; // gaps <= 12 are nearly useless for items >= 10
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 25.0;
    }
    // Zero residual is perfect: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: discourage scattering items when many bins are open,
    // but allow new-bin opening when few bins exist.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but relax when this bin would otherwise create dead space.
        let mut nb = 15.0 + pressure * 2.5;
        if (post_residual as f64) < dead_zone && post_residual > 0 {
            nb -= 20.0; // opening fresh bin beats creating dead space
        }
        if post_residual == 0 {
            nb -= 10.0;
        }
        score += nb;
    } else {
        score -= pressure * 0.4;
    }

    // Lookahead: if the next item fits snugly into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 25.0;
        } else if (leftover as f64) < dead_zone {
            score += 15.0; // next item would create dead space here
        } else {
            score -= 8.0;
        }
    }

    // Mild alignment with mean residual: prefer bins near the mean to balance load.
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits with small leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 15.0 - (leftover_after_next as f64).min(15.0);
    }
    // Next item would leave very tight fit in this bin — mild reward anyway (tight packing)
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Penalize dead space relative to mean residual of open bins
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) > mean_r {
        score += 0.15 * (post_residual as f64 - mean_r);
    } else {
        score -= 0.10 * (mean_r - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Late in the stream: tighten packing further
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Discard tiny useless slivers
    if post_residual < 5 && post_residual > 0 {
        score += 10.0;
    }
    // Perfect closure: bin exactly filled
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear)
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    // Items are >= 1; small post-residuals (<10) are likely wasted.
    if post_residual < 10 {
        score -= 25.0; // perfect closure bonus
    } else if post_residual < 20 {
        score += 8.0; // awkward dead zone
    }

    // Lookahead: if next item fits the post-residual, this is a great pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_tightness = next_item_size as f64 / post;
        score -= 30.0 * pair_tightness;
    } else if next_item_size > post_residual {
        // next item won't fit here; mildly penalize leaving stranded space
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let pressure = (open_bins_count as f64) * (mean_residual / cap);
    if bin_residual != bin_capacity {
        score -= 4.0 * pressure;
    }

    // Time horizon: late in the stream, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post / cap);

    // New-bin candidate handling: empty bin should only win when it's genuinely
    // better; give it a moderate baseline penalty that tight-fit rewards elsewhere
    // can overcome.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * (1.0 - fit_ratio);
        // Early in the stream, opening bins is cheap.
        score -= 30.0 * (1.0 - progress);
        // If no open bin fits, this call is the only option anyway; soften penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate loose fits; late in stream penalize them more
    let progress_coupling = norm_pr * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Reward when leftover can still fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (norm_pr * cap - nxt).max(0.0) / cap;
        score -= 0.8 * fits * (1.0 - progress);
    }

    // Penalize dead space that is too small for the minimum item (1..100 range)
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 1.5 * dead;

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild dispersion penalty: prefer bins near mean residual (balanced use)
    let dev = (pr - mean_residual).abs() / cap;
    score += 0.3 * dev * dev;

    // Slight preference for filling bins rather than proliferating them
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition capacity into 10-unit classes.
    let class = (post_residual / 10) as f64;
    score += class * 2.5;

    // Modulo-10 resonance: dead space that is a multiple of 10 is more reusable.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 == 5 {
        score -= 3.0;
    } else {
        score += (5 - mod10) as f64;
    }

    // Perfect-fit harmonic: post_residual exactly matches next item's class.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap % 10 == 0 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual cannot host next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Integer-division thresholds on item size (harmonic thirds of capacity).
    let third = bin_capacity / 3;
    if item_size > 2 * third {
        score -= 6.0; // large items: pack tightly, avoid wasting big bins
    } else if item_size < third {
        score += 2.0; // small items prefer residual-rich bins
    }

    // Last-chance bonus: this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer only when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual < 15.0;
        let poor_fit = post_residual > 0 && post_residual < 10;
        if crowded || poor_fit {
            score -= 5.0;
        } else {
            score += 20.0 + mean_residual * 0.3;
        }
    }

    // Progress-aware tightening: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Mean residual coupling: penalize bins far below mean (fragmented).
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Penalize residuals too small for the lookahead item if they are still
    // large enough to be "usable in principle" — a near-miss is costly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward placements that still leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, be less picky.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when existing bins would waste badly, by penalizing it
    // mildly but keeping its base residual high (it already starts high).
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 5.0;
        // If nothing fits well (this call is the fallback), allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, tighten up: avoid leaving scattered small residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mean-residual coupling: if average residual is already low, waste hurts more.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead match: next item exactly fills the post residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits within post residual (chain feasibility)
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tightness / bin_capacity as f64);
    }
    // Next item would be wasted on this residual: penalize leaving residual
    // that neither fits next item nor is small
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins with residual near mean (balanced),
    // penalize very tight or very loose bins
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize large dead space that nothing else can use
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // nearly perfect fill
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a good fit (post_residual large) and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so open bins usually win
        score += 55.0;
        // but if post residual (== capacity - item) is small, item is big, new bin fine
        score -= 0.5 * post_residual as f64;
        // late in stream, avoid opening new bins
        score += 30.0 * progress;
        // many open bins: prefer filling them
        score += 2.0 * open_bins_count as f64;
    }

    // Tight fit reward: item fills most of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Mild preference to keep large residuals for large future items
    if next_item_size > 40 && post_residual > next_item_size {
        score += 5.0; // don't burn a big residual if next item is large but could fit elsewhere
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward chains: if the lookahead item fits in the post residual,
    // this bin continues to be productive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item cannot use.
        score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: make it expensive unless the best available fit is poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Cheaper to open a new bin early in the stream (long horizon amortizes),
        // and when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        score -= 6.0 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual of open bins is large, open bins are roomy; new bin less needed.
        score += 0.15 * mean_residual;
        // If the next item is big, a fresh bin keeps flexibility.
        if next_item_size >= item_size && next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, favor consolidating into
    // existing bins rather than opening new ones (handled above), and prefer
    // bins whose residual is below the mean (tighter bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Small time-horizon modulation: late in the stream, be more conservative
    // about wasting space (dead space penalties grow).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex to punish large dead space
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling: dead space matters more as stream progresses
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score *= progress_weight;

    // Perfect-fit reward: subtract strongly when post_residual is tiny
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 18.0 * tightness * tightness * tightness;

    // Lookahead: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let next_norm = next_item_size as f64 / cap;
        score -= 10.0 * fits_next * (0.5 + next_norm);
        // bonus if next item exactly fills remaining space
        let exact = ((post_residual == next_item_size) as i32 as f64) * (6.0 + 14.0 * progress);
        score -= exact;
    }

    // Last-chance bin: strong reward when only this bin fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Slight penalty when many open bins (encourage consolidation)
    score += 2.0 * (open_bins_count as f64).sqrt();

    // Mean-residual alignment: prefer bins near mean residual (smooth kernel)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: multiples of 10 / 25 are "usable" dead space
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        // awkward residue class: penalize proportional to distance from next multiple of 10
        let d = 10 - (pr % 10);
        score += d as f64 * 1.5;
    }

    // Integer-division thresholds: residual in the "large item" band is valuable
    if pr >= 40 {
        score -= 10.0;
    } else if pr >= 25 {
        score -= 5.0;
    } else if pr >= 10 {
        score -= 2.0;
    } else if pr > 0 {
        // tiny dead space
        score += 6.0;
    }

    // Lookahead: if next item fits into post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= pr {
        score -= 30.0 + (pr - next_item_size) as f64 * 0.5;
        // harmonic bonus: next item leaves a multiple of 10 behind
        if (pr - next_item_size) % 10 == 0 {
            score -= 12.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item won't fit here: mild penalty scaled by how far off
        score += ((next_item_size - pr).min(40)) as f64 * 0.4;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 70.0;
        // late in stream, prefer consolidating into open bins
        new_bin_score += progress * 40.0;
        // many open bins with slack: discourage opening another
        new_bin_score += open_bins_count as f64 * 3.0;
        // if mean residual is small (bins are full-ish), new bin is fine
        new_bin_score -= mean_residual * 0.8;
        // if item nearly fills a bin by itself, new bin is natural
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 50.0;
        // lookahead: if next item is huge, a fresh bin pairs well
        if next_item_size >= 50 {
            new_bin_score -= 25.0;
        }
        // last chance override: no other bin fits, new bin must look good
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        score += new_bin_score;
    }

    // Slight tie-break toward bins with residual below mean (tighter bins first)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically gaps < ~15 are hard to reuse) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 + (15 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 - lookahead_fit * 0.5;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
    } else {
        // Using existing bins relieves pressure when open_bins_count is high.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins below mean residual (balance / keep big gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits after this placement: reward tightness of the pair.
            let pair_waste = post - nxt;
            let tightness = 1.0 - (pair_waste / bin_capacity as f64);
            score -= 30.0 * tightness * tightness;
            // Perfect pair bonus
            if pair_waste == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally to overflow gap.
            let gap = nxt - post;
            score += 0.25 * gap;
        }
    }

    // Penalize large residual relative to mean residual (dead space hoarding).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = post_f / mean_residual;
        if rel > 1.0 {
            score += 5.0 * (rel - 1.0);
        } else {
            score -= 5.0 * (1.0 - rel);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all existing fits are terrible.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin: large residual is fine, but discourage wasteful opens.
        score = 60.0 + post_f;
        if next_item_size > 0 && (next_item_size as f64) <= post_f {
            score -= 20.0;
        }
        if fitting_bins_count == 1 {
            // Never open a new bin when this is the only fitting open bin.
            score += 100.0;
        }
    }

    // Late-stream tightening: as stream progresses, prefer filling bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_f / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 15.0 * fit_ratio;
    }

    // Penalize leaving small-but-unusable dead space (post_residual in awkward zone).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny dead space is nearly useless
    } else if post_residual >= 10 && post_residual < 25 {
        score -= 5.0; // still useful for small future items
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize more if we wasted a big residual
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are quite full
    // or there are no open bins / no real alternative.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // Prefer new bin when existing bins are crowded (low mean residual)
            // and this item is large; otherwise penalize fragmentation.
            let crowded = mean_residual < item_size as f64 * 0.5;
            let late = step_index as f64 / (total_items.max(1) as f64);
            if crowded {
                score -= 20.0 + 15.0 * late;
            } else {
                score += 30.0 + 25.0 * (1.0 - late);
            }
            // Large items benefit from a fresh bin more often.
            if item_size > 60 {
                score -= 12.0;
            }
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer reusing existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio.min(1.0));

    // Slight preference for bins whose residual is far below the mean (more filled).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post_residual (prefer tight fits)
    let mut score = pr * (1.0 + norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early on, larger residuals are acceptable.
    let coupling = 1.0 + progress * (1.0 - progress) * 2.0;
    score += 8.0 * norm_pr * norm_pr * coupling;

    // Reward leaving room for the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            let fit_quality = 1.0 - (slack / cap);
            score -= 6.0 * (1.0 - fit_quality * fit_quality) * (1.0 - progress);
        } else {
            // lookahead won't fit: mild penalty scaled by shortfall, smoothed
            let short = (-slack / cap).min(1.0);
            score += 4.0 * short * short * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Penalize spreading across too many open bins relative to progress
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * progress.max(0.05));
    score += 2.0 * bin_pressure * norm_pr;

    // Alignment with mean residual: prefer bins whose residual deviates smoothly
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: prefer small post_residual, with harmonic (divisibility) shaping.
    // Harmonic classes: post_residual divisible by 10 is "clean" class -> slight reward.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    } else {
        score += 1.0; // messy residue class penalized
    }

    // Integer-division thresholds: dead space tiers.
    if post_residual < 10 {
        score -= 6.0; // perfectly closed-ish bin, excellent
    } else if post_residual < 20 {
        score -= 2.0;
    } else if post_residual >= 80 {
        score += 5.0; // nearly untouched bin being used — wasteful
    }

    // Lookahead coupling: reward if next item fits the post residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item cannot use leftover; penalize proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
        // modulo harmony: next_item_size shares residue class with post_residual
        if post_residual % 10 == next_item_size % 10 {
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        score = 60.0
            - (mean_residual / bin_capacity as f64) * 30.0
            - (open_bins_count as f64).sqrt() * 4.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;
    if bin_residual != bin_capacity {
        score -= progress * 2.0;
    }

    // Tie-break: prefer bins whose residual is close to mean (keeps distribution balanced).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (non-linearly).
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // worst dead space
        } else if post_residual <= 20 {
            score += 20.0;
        } else if post_residual <= 35 {
            score += 6.0;
        } else {
            // large residuals are partially useful: mild reward
            score -= 8.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Reward exact match with the lookahead item (reserve space smartly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // dead space relative to known next item
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; the new-bin candidate (residual == capacity)
    // gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
        // early in the stream, opening a bin is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    } else {
        // encourage tight packing when bins are plentiful
        score -= 0.05 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Slight preference for bins below the mean residual (fill emptier-side variance).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual < 5 {
        score -= 25.0;
    } else if fit_ratio < 0.1 {
        score -= 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 5.0 {
                score -= 15.0;
            } else if slack < 15.0 {
                score -= 6.0;
            } else {
                score -= 2.0 / (1.0 + slack);
            }
        } else {
            // next item cannot fit here: penalize leaving a gap the next item can't use
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(30.0);
        }
    }

    // Relative-to-mean-residual shaping: prefer bins tighter than average
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no good existing option
    if bin_residual == bin_capacity {
        // base penalty to prefer filling existing bins
        score += 20.0;
        // but if existing bins are badly fragmented, new bin becomes attractive
        if mean_residual > 0.0 {
            let fragmentation = mean_residual / bin_capacity as f64;
            if fragmentation > 0.5 {
                score -= 25.0 * (fragmentation - 0.5);
            }
        }
        // early in stream, opening a bin is cheap and useful
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Penalize creating medium dead space (unusable for typical items)
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small gaps still useful for small items
    } else if post_residual >= 10 && post_residual < 25 {
        score += 3.0; // awkward mid-range residual
    }

    // Slight preference to spread load when many bins open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual already favored by base term.

    // Lookahead: if the next item fits in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.25 * (next_item_size as f64);
        // extra bonus if next item fills almost exactly
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // penalize creating residual too small for next item (dead space risk)
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that can fit, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless open bins are quite full (low mean residual).
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score += 30.0;
        // open new bin earlier if mean residual across open bins is small
        score -= mean_residual * 0.2;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if open bins are numerous, avoid spreading
        score += 0.5 * open_bins_count as f64;
    }

    // Reward placing into bins with residual close to item size (best-fit sharpening)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Slight preference to fill bins that are already partially used
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized residual
    let norm_post = post / cap;
    score += 8.0 * norm_post * norm_post * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly over time
    score -= 6.0 * (1.0 - norm_post).powi(2) * (0.5 + progress);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 10.0 + 10.0 * progress;
    }

    // Lookahead: favor leaving a gap that fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap_err = (post - nxt) / cap;
            score -= 4.0 * (-gap_err * gap_err * 40.0).exp();
        } else {
            // gap too small for next item: penalize proportionally to dead space
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 + 5.0 * progress;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_post;

    // New empty bin candidate: penalize unless item is large or fits poorly elsewhere
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score = cap * 0.6 - 6.0 * fill_ratio * fill_ratio * (1.0 + progress) - 3.0 * (1.0 - norm_post);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below-average residual (denser bins)
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: which capacity-fraction bucket does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..8 harmonic class

    // Reward placements landing on nice harmonic boundaries (small dead space classes)
    match post_class {
        0 => score -= 40.0,                       // near-perfect fill
        1 => score -= 18.0,                       // tiny residual, likely dead space but small
        2 => score -= 6.0,                        // quarter residual: very reusable
        3 => score += 4.0,                        // awkward 3/8 residual
        4 => score -= 10.0,                       // half residual: broadly reusable
        5 => score += 6.0,                        // awkward 5/8 residual
        6 => score -= 2.0,                        // 3/4 residual: reusable by small items
        7 => score += 8.0,                        // near-empty: wasted placement
        _ => {}
    }

    // Modulo-10 harmonic: residuals divisible by common item sizes are more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit: post residual becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 35.0; // existing bins nearly full; fresh bin is fine
        }
        // late in stream, keep few bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Prefer tighter existing bins slightly: deviation from mean residual
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Small penalty per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    } else {
        // Penalize gaps too small to fit the lookahead item (k=2 lookahead)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Small unusable-ish gaps (< 20) get a mild extra penalty
        if post_residual < 20 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize spreading across many open bins when few
    // bins fit the item (encourage consolidation).
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin is a fallback; make it slightly
    // unattractive unless existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no open bin fits well (many dead-space penalties accrued),
        // opening fresh is fine: the +15 is small relative to dead-space penalties.
    }

    // Tight-fit reward: leaving a residual exactly matching the next item is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mean-residual coupling: bins far below mean residual are "loose"; prefer
    // filling tighter bins (larger fill fraction) to keep residuals uniform.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild progression term: later in the stream, be slightly more conservative
    // about opening new bins (fewer leftover partial bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect match where the
    // next item exactly fills the residual this placement would leave.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // perfect 2-chain: item + next item close this bin
        } else if post_residual > next_item_size {
            // next item fits but leaves further slack; reward proportionally
            score -= 60.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
            // penalize the leftover after the hypothetical next placement
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here; mild penalty proportional to the gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight-fit reward: minimal dead space relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize placements that leave a small, hard-to-use residual
    // (dead space trap: 1..=9 units left over).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with below-mean residual (fill emptier bins first keeps
    // tight bins available for small future items), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * (mean_residual - bin_residual as f64) * (0.5 + 0.5 * progress);

    // Discard the brand-new-bin option unless current bins are genuinely poor fits:
    // new bin starts with full residual, so give it a mild handicap unless
    // many bins are open and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        score += 15.0;
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 30.0; // fragmentation: prefer fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leftover dead space proportionally.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Penalize creating residuals that are too small to be useful later
    // (dead space below the minimum plausible item size).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Time horizon: early in the stream, be more selective (prefer good fits);
    // late in the stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into bins with residual close to mean.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
        if open_bins_count > 8 {
            score -= 3.0; // encourage closing bins when too many are open
        }
    } else {
        // New-bin candidate: acceptable early, penalized when many bins are open
        // or when a fitting bin exists with decent fit.
        score += open_bins_count as f64 * 1.5;
        if fitting_bins_count >= 1 {
            score += 5.0;
        }
        // Opening a new bin is fine if current item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
