    let mut score = pr * (1.0 + 0.35 * progress);

    // Reward tight fits (post_residual near 0) non-linearly.
    let tightness = 1.0 - pr / c;
    score -= (tightness * tightness) * c * 0.5;

    // Penalize small unusable post-residual that is still nonzero (dead space),
