    // Lookahead coupling: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 15.0 * (1.0 - gap / c).powi(3);
        // Penalize leaving post residual that next item barely misses.
        if nxt > pr && nxt <= bin_residual as f64 {
            score += 8.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score -= pressure * (c - pr) * 0.1;

    // Mean residual coupling: if this bin is below mean residual (tighter), slight reward.
    score -= 0.15 * (mean_residual - pr);

    // New-bin candidate handling: make empty bin attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || fit_ratio < 0.35;
        score = if poor_fit { c * 0.4 - 10.0 * (1.0 - fit_ratio) } else { c * 1.2 + 30.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap;
    // Penalize small-but-nonzero leftovers (unusable dead space)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space, worst outcome
        } else if frac < 0.2 {
            score += 20.0; // low class residual
        } else if frac < 0.4 {
            score -= 10.0; // decent residual
        } else {
            score -= 25.0; // large residual keeps bin useful
        }
    } else {
        score -= 80.0; // perfect fit: strongly reward closing bin exactly
    }

    // Integer-division thresholds on post_residual (harmonic classes of 25)
    let class = post_residual / 25;
    score -= match class {
        0 => 0.0,
        1 => 8.0,
        2 => 14.0,
        _ => 18.0,
    } as f64;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 0.3 * slack;
        // Exact next-item fit is especially good
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        score += 12.0; // next item cannot use this residual
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let good_existing = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs() / cap
        } else {
            1.0
        };
        score += 90.0 - 60.0 * good_existing;
        // Early in stream, new bins are cheap; late, prefer packing
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild pressure to fill fuller bins when many bins are open
    score -= 0.05 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    // Items range 1..=100, so any post_residual > 0 can technically fit something, but
    // tiny gaps (< 12) are statistically near-unusable for typical distributions.
    let dead = if post_residual == 0 {
        0.0 // perfect fit: zero waste, heavily rewarded below
    } else if post_residual < 12 {
        40.0 // unusable sliver
    } else if post_residual < 25 {
        18.0 // poor gap
    } else {
        0.0
    };
    score += dead;

    // Reward exact / near-exact packing proportionally to tightness.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the current bin
    // would leave a bad gap. Penalize the fresh bin mildly so real fits win;
    // add pressure scaling with open_bins_count so we don't hoard empty bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing space.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement is a chain setup — reward it strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 12 {
            score -= 12.0;
        }
        // If placing here leaves a gap the next item cannot use, penalize.
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Early in the stream, allow slightly looser fits to build reusable bins;
    // later, tighten up as remaining slack becomes the dominant cost.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residuals close to the item (best-fit flavor on top).
    score += 0.2 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            // Perfect 2-step match: subtract big bonus.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item can't use the remainder: penalize dead space scaled by gap.
            score += 12.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: minimize waste directly.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins tighter than average are precious, prefer using them.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 8.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 4.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin (only fitting bin): strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins exist and the fit is loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = post_residual as f64;
        score += 10.0 + 40.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (waste / bin_capacity as f64) * (1.0 - 0.5 * progress);
        // But allow new bin if no open bin fits well (fitting_bins_count == 0 means only new bin candidate).
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Slight early-stream bonus for keeping bins open (flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver below min item size
    }

    // Lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 6.0; // next item cannot use this bin
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to avoid spreading items thin.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).sqrt();
    }

    // Global state coupling: prefer filling bins when mean residual is low (bins nearly full).
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 3.0 * mean_gap / (bin_capacity as f64);
    } else {
        score += 3.0 * (-mean_gap) / (bin_capacity as f64);
    }

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_ratio = (item_size as f64) / (bin_capacity as f64);
    score += (1.0 - progress) * 10.0 * fill_ratio;
    score -= progress * 6.0;

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate adjustment: only attractive for large items early on.
    if bin_residual == bin_capacity {
        score -= 5.0 * fill_ratio * (1.0 - progress) - 2.0 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: quadratic coupling of post_residual with stream progress
    score += 0.35 * (pr / cap) * (pr / cap) * (1.0 + progress) * cap;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward leaving space exactly matching next item, penalize wasteful large leftovers
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let match_bonus = 1.0 - ((pr - n).abs() / cap);
        score -= 25.0 * match_bonus * match_bonus;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize, with decay as stream progresses (consolidate late)
    if bin_residual == bin_capacity {
        score += 55.0 - 30.0 * progress + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins below mean residual (consolidate emptier bins first)
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes mod 10.
    let post_class = post_residual % 10;
    // Dead space that is NOT a multiple of 10 is "disharmonic" -> penalize.
    let disharmony = (post_class as f64) / 10.0;
    score += disharmony * 18.0;

    // Perfect harmonic closures: post_residual in {0, 10, 20, 30} are reusable slots.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 30 && post_residual % 10 == 0 {
        score -= 25.0;
    }

    // Fraction-of-capacity thresholds on bin_residual.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    if residual_frac > 0.9 {
        // Nearly full bin: prefer to close it out.
        score -= 20.0 * residual_frac;
    } else if residual_frac < 0.2 && bin_residual != bin_capacity {
        // Barely-touched existing bin: deprioritize, keep big bins for big items.
        score += 12.0;
    }

    // Integer-division threshold on next_item_size: does the next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainable: next item slots perfectly here.
            let next_class = next_item_size % 10;
            score -= 15.0 + (10 - next_class) as f64;
        } else {
            // Next item won't fit here; penalize wasting a good residual on a bad split.
            score += 8.0 + (next_item_size.saturating_sub(post_residual) as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let base = 45.0 + (item_size as f64) * 0.5;
        // Prefer new bin when open bins are already loose on average.
        let mean_frac = mean_residual / bin_capacity as f64;
        score = base + mean_frac * 30.0;
        if next_item_size > 0 && next_item_size > item_size {
            // Big item coming: opening fresh bin now is doubly good.
            score -= 18.0;
        }
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Slight preference to spread load when many bins open (balance residuals toward mean).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible future item can fill
    // (below the minimum item size of 1, treat tiny gaps as pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver => heavy penalty
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize large leftover gaps proportionally (waste pressure).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins would create
    // significant dead space or are scarce.
    if bin_residual == bin_capacity {
        score = 95.0 + post_residual as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0; // forced new bin anyway
        }
        if post_residual + item_size <= bin_capacity && post_residual < 15 {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would be blocked by post residual (tight gap), penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Progress: late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact match between post_residual and next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-step chain
        }
        // Penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin boost
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 && post_residual as f64 <= mean_residual {
            score += 10.0;
        }
    }

    // Tight fits are excellent
    if post_residual <= 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fit tightness: reward near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small leftover that likely can't host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further slack: mild reward scaled by usage
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize large leftover slightly
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Time horizon: early in the stream, be more willing to open new bins
    // (score new-bin candidate better); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (14.0 - 22.0 * progress);

    // Mean residual coupling: if open bins are on average roomy, discourage
    // adding to a sparse bin and encourage new-bin usage less.
    let sparse = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 6.0 * sparse;

    // Slight penalty for opening a new bin when an existing bin would end up
    // with usable residual close to the mean.
    if new_bin > 0.0 && post_residual as f64 > mean_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    // Smooth non-linear coupling: reward high fill more strongly as stream progresses.
    score -= (fill_ratio * fill_ratio) * (1.0 + 2.0 * progress) * 30.0;
    // Penalize small unusable dead space (post_residual below typical item sizes) with smooth term.
    let dead = (25.0 - post_residual as f64).max(0.0) / 25.0;
    score += dead * dead * 20.0;
    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * chain_fit;
    }
    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Penalize opening new bins when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        score -= 10.0 * progress; // early on, new bins are cheaper
    }
    // Mild preference for bins below mean residual (balance residuals smoothly).
    score += 0.1 * (bin_residual as f64 - mean_residual);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by capacity fractions (modulo arithmetic)
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12

    // Dead-space classes: small post_residual is great (near-perfect fit)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= eighth {
        score -= 30.0; // nearly full bin
    } else if post_residual <= quarter {
        score -= 10.0;
    } else {
        // post_residual in (25,100): check harmonic residue classes mod 10
        let r = post_residual % 10;
        // residuals divisible by 10 are "harmonic" (likely to fit future round items)
        if r == 0 {
            score -= 6.0;
        } else if r <= 2 || r >= 8 {
            score += 4.0; // awkward residue, likely dead space
        }
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chains perfectly
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= eighth {
                score -= 18.0;
            } else {
                score += slack as f64 * 0.25; // penalize leaving gap next item only partially uses
            }
        } else {
            // next item can't follow into this bin: mild penalty proportional to mismatch
            let mismatch = next_item_size - post_residual;
            score += (mismatch % 25) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score = cap * 0.9;
        // more attractive late in stream or when few bins fit
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // new bin can absorb the pair
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Prefer tighter bins: reward small bin_residual relative to capacity
        score += (bin_residual as f64 / cap) * 8.0;

        // Prefer bins whose residual deviates favorably from mean residual
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;

        // Many open bins: encourage consolidation into existing bins
        if open_bins_count > 4 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are pure waste.
    let min_item = 1u32;
    let dead = if post_residual < min_item {
        0.0
    } else {
        post_residual as f64
    };

    // If the leftover gap cannot fit the NEXT item, it is much more likely dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0 + 0.35 * post_residual as f64;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect pairing with the lookahead item: strong reward.
        score -= 30.0;
    }

    // Progressive dead-space penalty: gaps below typical item sizes are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few are
    // open, slightly favor reusing existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more when few bins are open or stream
        // is late (opening new bins late wastes capacity).
        score += 25.0 + pressure + 20.0 * progress;
    } else {
        // Reward reusing an existing bin, scaled by how tight the fit is.
        score -= 4.0 + 0.10 * (bin_residual - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Mean-residual coupling: if this bin's post-placement residual is far below the
    // mean, we are consolidating space well; reward that.
    score -= 0.15 * (mean_residual - post_residual as f64).max(-50.0).min(50.0);

    // Final strict dead-space shaping: quadratic penalty on unusable remainder.
    score += 0.02 * dead * dead / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff; // penalize mismatch with lookahead item
        if post_residual as i64 == next_item_size as i64 {
            score -= 60.0; // perfect 2-step chain: fill bin completely next turn
        } else if post_residual > next_item_size {
            score -= 5.0; // lookahead item still fits after this placement
        } else {
            score += 10.0; // lookahead item won't fit: dead space risk
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful spread).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tightening bins: small post_residual is good (but avoid 1-9 dead zones).
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny unusable sliver
    } else if pr == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only prefer it when this item is huge relative to residual
    // or the fit is terrible (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let tightness = post_residual as f64 / bin_capacity as f64;
        if tightness > 0.6 {
            score -= 30.0; // item nearly fills a fresh bin anyway
        } else {
            score += 35.0; // discourage opening new bin for small items
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.9 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that exactly accommodate the next item.
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 20.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
        if mean_residual > item_size as f64 {
            score += 8.0; // existing slack could have absorbed the item
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate slack into similar bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight time decay: later in the stream, tolerate larger residuals less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize large residuals more (dead space matters)
    let progress_coupling = progress * (norm_pr * norm_pr * cap);
    score += 0.8 * progress_coupling;

    // Reward tight fits (small post residual) with smooth quadratic bonus
    let tightness = 1.0 - norm_pr;
    score -= 4.0 * tightness * tightness * item_size as f64 / cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * lookahead_fit * lookahead_fit;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize leaving awkward residuals
        score += 2.0 * norm_pr;
    }

    // Penalize bins far below mean residual (fragmentation avoidance), smoothly
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 + progress);

    // Mild penalty for too many open bins, smoothed by progress
    score += 0.05 * (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; competing bins with poor fits will score higher
        score = cap * (0.9 + 0.3 * progress) - 5.0 * (fitting_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 10.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are heavily rewarded,
    // small dead space (1..=9) is penalized, mid-range residuals are fine.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 9 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with typical item sizes; reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let rem_after_next = post_residual - next_item_size;
            if rem_after_next % 10 == 0 {
                score -= 15.0;
            }
            // Penalize if next item would leave tiny dead space
            if rem_after_next > 0 && rem_after_next <= 9 {
                score += 12.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to the gap
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Slightly cheaper to open new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (compact bins),
    // keeping large residual bins available for large items.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: bins with residual in [item_size, item_size+15)
    // are "tight fits", mildly preferred.
    let div = bin_residual / (item_size.max(1));
    if div == 1 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (min item size = 1 in the worst case, but small gaps under
    // ~12 are statistically hard to reuse) are heavily penalized.
    let min_useful = 12.0;
    if (post_residual as f64) < min_useful {
        score += 60.0 + (min_useful - post_residual as f64) * 8.0;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // compacting into existing bins.
    score += open_bins_count as f64 * 0.15;

    // New-bin candidate (empty bin): make it moderately expensive so we only
    // open a new bin when existing fits would create bad dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening a new bin is cheaper (fewer future items
        // to fill it), relax the penalty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward
    // this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item fits in post residual, mild reward; if it nearly fits,
    // small penalty for leaving an awkward gap.
    else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Slight preference for bins tighter than the average residual
    // (pack into fullest bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect-fit bonus: residual becomes 0 or very small
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // 2-step lookahead: strongly reward when next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 55.0 * (1.0 - next_fit_quality / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Penalize if next item cannot use the leftover space (dead space creation)
        score += 0.8 * (next_item_size as f64).min(post_residual as f64);
    }

    // Compare post residual against mean residual across open bins
    // Favor bins whose post residual stays near/below the mean (balanced packing)
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) unless current bins are too full
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / (bin_capacity as f64);
        // Open a new bin only if existing bins are quite full or no bins fit well
        score += 45.0 - 40.0 * avg_fullness;
        if fitting_bins_count == 0 {
            score -= 50.0; // no other bin fits; new bin is necessary
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // new bin can host both items nicely
            let combined = item_size + next_item_size;
            if combined >= bin_capacity - 5 {
                score -= 30.0;
            }
        }
    }

    // Slight preference for filling more-opened bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 8.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.15 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward leaving exactly enough room for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize spreading across many open bins; encourage consolidation.
    score += 0.4 * open_bins_count as f64;

    // Reward bins with residuals below the running mean (denser bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early (prefer filling open bins),
        // but allow it late when open bins are crowded.
        score += 12.0 - 10.0 * progress - 0.2 * mean_residual;
    } else {
        // Early on, mildly prefer bins with more residual room (flexibility);
        // late, prefer tightest fit.
        score += (1.0 - progress) * 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post residual, with non-linear sharpening.
    let mut score = pr + 0.5 * (pr / cap) * (cap - pr);

    // Smooth non-linear coupling of residual with stream progress:
    // later in the stream, dead space matters more (convex penalty).
    let norm_pr = pr / cap;
    score += progress * 20.0 * norm_pr * norm_pr;

    // Reward tight fits: sigmoid-like smooth term on item size fraction.
    let tightness = item_size as f64 / cap;
    score -= 8.0 * tightness * (1.0 - tightness) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).max(0.0);
        score -= 5.0 * (slack / cap) * (1.0 - slack / cap);
        // Penalize if post residual is just barely below next item (wasted near-miss).
        if pr < nx {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (empty bin): make it less attractive unless item is huge.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * tightness;
    }

    // Deviation from mean residual: prefer bins that reduce dispersion smoothly.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in a "harmonic" band (small dead space, e.g. <= 20% of capacity)
    if post_residual <= bin_capacity / 5 {
        score -= 18.0;
    }
    // Class B: mid band (20%..40%)
    else if post_residual <= 2 * bin_capacity / 5 {
        score -= 6.0;
    }
    // Class C: large residual left (40%..60%) — wasteful placement, penalize
    else if post_residual <= 3 * bin_capacity / 5 {
        score += 8.0;
    }
    // Class D: huge residual left (>60%) — strongly discourage
    else {
        score += 20.0;
    }

    // Integer division threshold: perfect-fit modulo classes (residual divisible by 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 7.0; // leaves a "harmonic" chunk usable by typical items
    } else if post_residual > 0 {
        score += 2.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or near-exact lookahead fit
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 30.0;
            } else if slack <= cap * 0.1 {
                score -= 15.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over / cap) * 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Prefer fuller bins: tighter packing when the bin is nearly full
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 10.0;

    // Avoid opening new bins early in the stream; allow later when open bins are crowded
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many open bins still have room
        let crowd = mean_residual / cap;
        score += 15.0 + (1.0 - progress) * 25.0 + open_bins_count as f64 * 0.5 - crowd * 10.0;
    } else {
        // Slight penalty scaled by how much this bin deviates from mean residual
        score += ((pr - mean_residual).abs() / cap) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual that cannot fit the next item
    // is unusable dead space -> heavy penalty proportional to its size.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * post_residual as f64;
        // Slightly less brutal if the gap is tiny (near-perfect fill now).
        if post_residual <= 5 {
            score -= 20.0;
        }
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Reward residuals that exactly (or nearly) match the lookahead item:
    // this bin will be perfectly consumed next step.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 10 {
            score -= 12.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (penalize the alternative implicitly by
    // rewarding this one).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more strongly when
    // open bins already exist and the item is small.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0 + 0.35 * item_size as f64
            + 2.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / (total_items.max(1) as f64));
        score += new_bin_penalty;
    }

    // Open-bins pressure: mildly discourage spreading across many bins;
    // favor bins whose residual deviates favorably from the mean.
    score += 0.15 * open_bins_count as f64;
    if bin_residual as f64 > mean_residual {
        score -= 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Waste-based tightness term: fraction of bin used by this item.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits exactly into the post residual (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Penalize leftover after the hypothetical next placement (waste beyond 2 steps).
            let after_next = (post_residual - next_item_size) as f64;
            score += 0.6 * after_next;
            if after_next < 10.0 {
                score -= 10.0; // near-perfect 2-step chain
            }
        } else {
            // Next item won't fit here; penalize proportionally to the mismatch.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: purely minimize post residual.
        score -= 5.0;
    }

    // Favor tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when existing bins could take the item,
    // unless the item is large and would leave a big residual elsewhere.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 50 && fitting_bins_count >= 1 {
            score += 10.0; // prefer existing bins for large items
        }
    }

    // Late in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (open_bins_count as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that can never host a typical future item.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 2.5 * (dead / 100.0).powi(3) * 100.0;
    }

    // Perfect closure bonus: bin exactly filled.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, this placement chains well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 5.0 + 4.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: residual becomes waste unless small.
        score += 1.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins: prefer filling existing ones over spreading.
    let crowding = open_bins_count as f64;
    score += 0.15 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Relative to mean residual: bins with more room than average can absorb items.
    let diff = mean_residual - post_residual as f64;
    score += 0.05 * diff;

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, prioritize closure and tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: make empty bins moderately attractive only
    // when no open bin offers a good fit (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        let escape_threshold = 0.5 + 0.3 * progress;
        if post_residual as f64 >= item_size as f64 {
            // This is the new-bin call itself.
            if (bin_capacity - item_size) as f64 / bin_capacity as f64 > escape_threshold
                && fitting_bins_count > 1
            {
                score += 8.0; // discourage opening when decent fits exist
            } else {
                score -= 3.0; // encourage fresh bin when fits are poor
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress);
    score += 40.0 * poly;
    // Reward tight fits, weighted more early in the stream
    score -= (1.0 - norm_pr) * (1.0 - progress) * 12.0;
    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + progress);
        } else {
            score -= 0.3 * (1.0 - progress);
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    // Mild preference for consolidating into fewer bins
    score += open_bins_count as f64 * 0.05;
    // Pull toward mean residual to balance bin usage
    score += 0.1 * (pr - mean_residual);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" the leftover space is.
    // Residuals in fine-grained classes (small mod 10) are more likely to host
    // future items of small sizes, which are common under unknown distributions.
    let post_class = post_residual / 10; // coarse class 0..=10
    let post_mod = post_residual % 10;   // fine remainder

    // Reward small post_residual classes (tight fits) via non-linear decay.
    let class_reward = match post_class {
        0 => 40.0,                       // perfect / near-perfect fit
        1 => 22.0,
        2 => 12.0,
        3 => 6.0,
        4 => 2.0,
        5 => 0.0,
        6 => -1.5,
        7 => -2.5,
        8 => -3.5,
        9 => -4.5,
        _ => -5.0,                       // near-empty bin leftover
    };
    score -= class_reward;

    // Fine remainder bonus: residuals that are multiples of 5 align with
    // typical item granularity, making them more usable.
    if post_mod == 0 {
        score -= 3.0;
    } else if post_mod == 5 {
        score -= 1.5;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1),
    // but practically anything < 10 is nearly dead given typical granularity.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness of that pairing.
            let pair_class = (post_residual - next_item_size) / 10;
            score -= (12.0 - pair_class.min(6) as f64 * 2.0).max(0.0);
        } else {
            // Next item won't fit here: mild penalty scaled by how far off.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 20.0).min(8.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are
    // already quite full on average (mean residual small) and this item fits
    // poorly everywhere. Penalize new-bin slightly otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        // Opening a new bin is attractive when existing bins are dense and
        // many bins are open (stream is wide).
        let new_bin_bonus = 30.0 * mean_fullness * (1.0 + progress) - 10.0;
        score -= new_bin_bonus;
        // Slight inherent reluctance to open bins early.
        score += 8.0 * (1.0 - progress);
    }

    // Mild preference to fill emptier bins when many are open (balance pressure).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Progress-based tightening: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps below the minimum item size
    // are pure waste; penalize them quadratically.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Small gaps that likely cannot host future items (below ~10% capacity)
    let small_gap_threshold = bin_capacity as f64 * 0.10;
    if (post_residual as f64) < small_gap_threshold && post_residual > 0 {
        score += (small_gap_threshold - post_residual as f64) * 2.0;
    }

    // Reward tight fits (low post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + tightness)) * 15.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing bins
    // and avoid opening new ones; when few bins are open, be more tolerant.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open_bins_count grows,
        // but relax pressure late in the stream or if no other bin fits well.
        score += 20.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If lookahead item is large, a fresh bin is attractive
        if next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward using it, more so under pressure
        score -= pressure * 0.5;
    }

    // Last-chance bin: strongly favor placing here to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space w.r.t. lookahead: mild penalty scaled by gap size
        score += ((next_item_size - post_residual) as f64) * 0.05;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (consolidating space into fewer, fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Stream progression: early on, be conservative about new bins;
    // late in the stream, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.
    // Penalize wasted space relative to bin capacity (dead-space shaping).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect chain: next item fills this bin exactly -> strong reward.
        if gap == 0.0 {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement: scale reward by closeness.
            score -= 35.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit here: penalize, worse if we leave a big unusable gap.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Compare against mean residual: prefer bins that are already below-average
    // residual (i.e., more filled) to consolidate fill.
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // the item is large or current open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Large items leave little residual anyway; new bins good early or when
        // mean residual is small (open bins nearly full).
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0);
        let new_bin_bonus = 18.0 * item_frac + 15.0 * (1.0 - fragmentation) + 8.0 * progress;
        score -= new_bin_bonus;
        // Opening a bin for a tiny item is wasteful.
        if item_frac < 0.35 {
            score += 25.0;
        }
        // If many open bins can fit, discourage opening yet another bin.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill * fill;

    // Penalize dead space that is too small to hold even the smallest item (size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; decreases late in the stream when consolidation matters less.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score = 55.0 + 20.0 * (1.0 - progress);
        // If item is large relative to capacity, opening a fresh bin is more reasonable.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins are open with low mean residual, prefer spreading onto fresh bins.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
    }

    // Global state: when mean residual across open bins is high, prefer bins below the mean
    // (drain the emptier bins first to close them out).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Mild time-horizon coupling: early in stream, be conservative (prefer tight packing);
    // later, allow slightly more freedom to close bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: penalize wasted space, non-linearly
    let mut score = post * (1.0 + 0.5 * post_norm);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in the stream, penalize residual quadratically (compact now).
    let phase = progress * std::f64::consts::PI;
    let late_weight = 0.5 * (1.0 - phase.cos()); // 0 -> 1 smoothly
    score += late_weight * post_norm * post_norm * cap;

    // Dead-space penalty: residual that nothing typical can use
    let dead = (post_residual as f64 - item_size as f64).max(0.0);
    score += 0.3 * (dead / cap) * dead;

    // Last-chance bin: strongly favor using it if it fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += 2.0 * ((nx - post) / cap);
        }
    }

    // Prefer bins whose residual is close to the mean residual (balance),
    // with smooth quadratic term
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Many open bins: encourage consolidation by penalizing new-bin usage
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Slight preference for tighter fits overall (item fills bin well)
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * late_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 act as "dead space bands".
    let res = post_residual % 10;
    let dead_penalty = if res == 0 { 0.0 } else { 1.0 + 0.3 * (10 - res) as f64 };
    score += dead_penalty;

    // Integer-division threshold: post_residual bucketed by capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter / 2 {
        // tiny leftover: nearly perfect fit, reward strongly
        score -= 25.0;
    } else if post_residual < quarter {
        score -= 8.0;
    } else if post_residual <= half {
        score -= 4.0;
    } else {
        // wasteful: large residual left, penalize mildly extra
        score += 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item won't fit here: leaving big residual is wasted
            score += 0.05 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer tighter bins relative to mean residual (best-fit coupling).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Harmonic class of item_size: items near capacity fractions are "awkward".
    let awkward = (item_size % 10 == 7) as f64 * 2.0 + (item_size > half && item_size < half + quarter) as f64 * 3.0;
    if awkward > 0.0 && post_residual > 0 {
        score += awkward;
    }

    // Progress-based new-bin discouragement: early stream, allow new bins; late, squeeze.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and progress.
        score += 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if open bins would leave terrible residue, opening is fine (handled by their scores).
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin attractive
        }
    }

    // Mild open-bin consolidation pressure.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are never truly dead, but residuals that can't hold
    // the next item are costly if next_item_size is a common size.
    // Penalize "awkward" gaps: post_residual in (0, item_size) already
    // captured by base, but amplify tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        // Dead space sliver: gap too small for typical items.
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (post_residual near zero) superlinearly.
    if post_residual == 0 {
        score -= 40.0; // perfect fit bonus
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Penalize gaps that cannot fit the lookahead item (creates forced split).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward gaps that exactly or generously fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (handled implicitly since new bin has max residual); add consolidation
    // pressure by penalizing bins whose residual is far below mean residual
    // when many bins are open.
    let open_f = open_bins_count as f64;
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * open_f * dev; // prefer bins with less residual than average (fuller bins)
    } else {
        // New-bin candidate: make it unattractive unless current fit is bad
        // or bin fleet is saturated. Base penalty scales with open bins.
        score += 20.0 + 3.0 * open_f;
        // If no open bin besides this candidate fits, allow new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild reward for filling large items into fuller bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual strongly preferred.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if post_residual >= next_item_size {
            // Next item can also fit here: strong lookahead reward.
            score -= 20.0 - (gap as f64).min(20.0);
            // Exact chain match: excellent.
            if gap == 0 {
                score -= 15.0;
            }
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize leaving residuals that are small but unusable (below min item size ~1..100 range guess).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Discourage opening new bins when several bins already fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64;
    }

    // Early in the stream, be slightly more willing to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * fill * fill;

    // Penalize dead space that is too small to be useful later
    // (small post_residual is good, but a residual that can't fit
    // a typical next item is wasted). Non-linear dead-space penalty.
    if post_residual > 0 {
        let dead = (post_residual as f64) / bin_capacity as f64;
        if post_residual < 10 {
            score += 25.0 * (1.0 - dead); // tiny sliver: strong penalty
        } else {
            score -= 6.0 * dead; // moderate leftover: mild reward
        }
    } else {
        score -= 30.0; // perfect fit: strong reward
    }

    // Lookahead coupling: if the next item fits exactly in the
    // post_residual, big reward; if next item won't fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * open_pressure * (1.0 - progress);

    // New-bin candidate handling: only allow opening a new bin when
    // the item is large relative to residual pressure and existing
    // bins are badly fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let item_big = item_size as f64 / bin_capacity as f64;
        let allow_new = fragmentation * item_big;
        // Base cost of a new bin, discounted if fragmentation is severe
        score += 55.0 - 45.0 * allow_new.min(1.0);
        // Late in the stream, opening new bins is cheaper than waste
        score -= 20.0 * progress;
    }

    // Mild penalty for placing into bins far below the mean residual
    // (keeps residuals balanced so future fits remain possible).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: penalize leftover space quadratically (wasted capacity grows superlinearly)
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling with stream progress: late in the stream,
    // dead space becomes more costly, so weight grows like a smooth ramp.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= progress_weight;

    // Reward tight fits: small post_residual relative to capacity gets a discount.
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * it * 0.5;

    // Reward bins whose residual can still host the next item (lookahead k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack) * nxt * 0.3 * (1.0 - progress);
        } else {
            // Penalize leaving residual too small for the next item (dead space)
            score += (nxt - pr) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this one is far from mean residual,
    // encouraging consolidation toward average fill.
    let dev = (pr - mean_residual).abs();
    score += dev * 0.05 * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: make empty bins attractive only when residual fits are bad.
    if bin_residual == bin_capacity {
        score = pr * pr / cap + 8.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "reusable" class (small or exactly matching common item sizes) are favored.
    let class = post_residual / 10; // integer division threshold classes 0..=10
    match class {
        0 => score -= 30.0,                 // near-perfect fit, tiny dead space
        1 => score -= 18.0,                 // leftover 10..19, very reusable
        2 => score -= 12.0,                 // leftover 20..29
        3 => score -= 8.0,
        4 => score -= 5.0,
        5 => score -= 3.0,                  // half-full leftover, moderately useful
        6 => score += 1.0,
        7 => score += 3.0,
        8 => score += 6.0,
        9 => score += 10.0,
        _ => {}                             // class 10 handled by new-bin logic
    }

    // Reward exact modulo alignment: leftover divisible into 10-blocks is flexible.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (20.0 - slack as f64 * 0.4).max(0.0);
        } else {
            // next item won't fit here; penalize leaving large stranded space
            if post_residual > 25 {
                score += (post_residual as f64 - 25.0) * 0.15;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins mildly unattractive unless the fit is
    // poor everywhere (post_residual large means item left lots of space anyway).
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, opening bins is cheaper (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Tie-break: spread load across bins when many are open.
    if open_bins_count > 4 {
        score += 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // tiny dead space: nearly full bin, but gap too small for min item
            score += 25.0 * (10.0 - pr);
        } else {
            // decay reward for larger residuals: prefer tight fits
            score -= 18.0 * (-pr / 22.0);
        }
    } else {
        // perfect fill
        score -= 30.0;
    }

    // Reward exact match with lookahead item size (k=2 lookahead synergy).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // residual cannot host next item: mild penalty scaled by gap
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Mean-residual coupling: penalize bins far below mean residual (they hoard space)
    // unless they are the tightest fits.
    score += 0.15 * (mean_residual - pr).max(0.0);

    // New-bin candidate handling: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // base new-bin cost grows with stream progression (sunk consolidation)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 25.0 * progress;
        // allow new bin if the item would leave a large awkward residual elsewhere
        if post_residual <= 15 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tight fit)
    if post_residual == 0 {
        score -= 50.0; // perfect fit bonus
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fit: next item closes this bin
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: post residual is dead space risk
            score += 0.10 * post_residual as f64;
        }
    }

    // Relative to mean residual: bins below mean residual are "tight" — prefer using them
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bin would leave large unusable residual
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score += 20.0;
        // but attractive if item is large relative to capacity and no good fit exists
        if item_size as f64 > 0.5 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can also host next item
        }
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to item size (avoid fragmenting large residuals)
    let waste = (bin_residual - item_size) as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual,
    // penalize if post_residual is large enough only for a wasteful fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual; dead space risk scales with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are nearly full or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_util = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize new bins when open bins are still quite empty.
        score += 45.0 * avg_open_util;
        // Late in the stream, closing out bins tightly is more valuable.
        score += 10.0 * (1.0 - progress);
        // A big item into a fresh bin wastes less potential than into a partial bin
        // when the partial bin's leftover would be unusable anyway.
        if item_size >= 50 {
            score -= 0.2 * (item_size as f64 - 50.0);
        }
    } else {
        // Prefer placing into bins already below-average residual (consolidate waste).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Mild preference to keep the number of open bins from exploding.
        score += 0.3 * open_bins_count as f64;
    }

    // Global pressure: when many bins are open, prefer tight fills even more.
    score -= 2.0 * fill_ratio * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted post-residual, with non-linear growth
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: small residuals are more tolerable early, worse late
    let deadness = (1.0 - norm_pr).powi(3);
    score += 20.0 * progress * deadness * norm_pr;

    // Reward tight fits (post_residual near zero) via smooth quadratic bonus
    score -= 15.0 * (1.0 - norm_pr * norm_pr) * (1.0 - progress);

    // Lookahead: penalize if post-residual can't fit next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let fits = if pr >= ns { 1.0 } else { 0.0 };
        score -= 10.0 * fits * (1.0 - gap / cap) * (1.0 - progress);
        score += 8.0 * (1.0 - fits) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (fill emptier bins) — smooth term
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "reusable"
    // classes (multiples of 10, or large enough for common items) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Post-residual harmonic class: modulo 10 residue (items often arrive in
    // multiples of 5/10; zero-residue post-residuals are highly desirable).
    let residue = post_residual % 10;
    if residue == 0 {
        score -= 6.0; // perfect harmonic alignment
    } else if residue <= 2 {
        score -= 1.0;
    } else if residue >= 7 {
        score += 4.0; // large dead-space wedge, hard to fill
    }

    // Integer-division threshold: can post_residual still host the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Chainability bonus, scaled by how snugly the next item fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 8.0 + 6.0 * snug;
        } else {
            // Post-residual too small for lookahead: penalize dead space,
            // but lightly if it is a tiny sliver (< 10) which is unavoidable.
            if post_residual > 0 && post_residual < 10 {
                score -= 2.0;
            } else {
                score += 5.0;
            }
        }
        // Harmonic coupling: next item's class vs post_residual class.
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 4.0; // both aligned on the same harmonic grid
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer reusing a well-filled bin; only allow
    // a fresh bin when current bin would leave a bad wedge and lookahead won't fit.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline moderate score; attractive only if open bins are
        // already fragmented (low mean residual) or it's early in the stream.
        score = 0.45 * cap;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0; // big lookahead item benefits from a fresh bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 6.0; // existing bins are cramped; a new one is fine
        }
        // Penalize opening new bins when many are already open and usable.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Reuse reward: the fuller the bin before placement, the better.
        let fill_before = 1.0 - (bin_residual as f64) / cap;
        score -= 10.0 * fill_before;
        // Perfect fit detection.
        if post_residual == 0 {
            score -= 15.0;
        }
        // Mean-residual coupling: prefer bins below mean residual (tighter bins).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Stream phase modulation: early on, be more exploratory (favor tight fits
    // less aggressively to keep flexible residuals); late, pack hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the next item: extra penalty.
        score += 8.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // making a new empty bin less attractive.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // Early in stream, slightly favor consolidation into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is better, handled by base term.

    // Aggressive 2-step lookahead: if the next item exactly matches post_residual,
    // this placement sets up a perfect fill — heavily reward.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this one: mild reward, scaled by closeness.
            score -= 6.0 * (ni / pr);
        } else {
            // Next item won't fit: penalize dead space left behind.
            score += 4.0 * (ni - pr) / bin_capacity as f64 * 100.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residuals far below mean wastes space; reward leaving large usable residuals.
    let mr = mean_residual;
    if mr > 0.0 {
        let pr = post_residual as f64;
        if pr >= mr {
            score -= 2.0 * (pr - mr) / bin_capacity as f64 * 10.0;
        } else {
            score += 2.0 * (mr - pr) / bin_capacity as f64 * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate mildly, so it's chosen only
    // when open bins would leave very large post residuals.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in the stream, opening bins is cheaper; later, discourage more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins that will be well-utilized overall.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 3.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: non-linear bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect-fit style bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 20 {
        score += 0.5 * (20 - post_residual) as f64;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive early in the stream or when the
        // current item fits poorly everywhere (large post_residual elsewhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * progress;
        // Discourage hoarding too many open bins late in the stream.
        score += 0.3 * open_bins_count as f64 * progress;
        // If the item leaves a large gap in an existing bin anyway, new bin is fine.
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 6.0;
        }
    } else {
        // Prefer bins with larger residuals for big items (best-fit style balance).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 5.0 * fit_ratio;
        // Slight preference for bins below mean residual (balance load).
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Mild global pressure: with many open bins, consolidate into existing ones.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Smooth non-linear coupling: polynomial in post_residual scaled by progress
    let norm_pr = pr / bin_capacity as f64;
    score += 12.0 * (norm_pr * norm_pr) * progress;
    score -= 8.0 * (norm_pr * norm_pr * norm_pr) * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / bin_capacity as f64;
        score += 15.0 * gap * gap;
        // Reward residual close to (but >=) next item size
        let fit_margin = (pr - next_item_size as f64).abs() / bin_capacity as f64;
        score -= 6.0 * (1.0 - fit_margin) * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.15 * progress;

    // Tight-fit reward
    if item_size == bin_residual {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 500.0;
        return score;
    }

    // Harmonic class of post_residual: dead space quality
    // Class 0: post_residual <= 10 (nearly unusable) -> excellent, pack it tight
    // Class 1: 11..=20 -> still good
    // Class 2: 21..=50 -> mediocre
    // Class 3: >50 -> wasteful
    if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    } else if post_residual <= 50 {
        score += 15.0;
    } else {
        score += 40.0;
    }

    // Harmonic residue: does post_residual leave a "nice" chunk (multiple of 10)?
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward, more so if it's a tight fit
            let slack = post_residual - next_item_size;
            score -= 40.0;
            if slack <= 10 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit: penalize leaving large dead space
            if post_residual > 25 {
                score += (post_residual as f64) * 0.3;
            }
            // If next item fits a fresh bin but not this residual, opening a new bin
            // that fits both is attractive; penalize this bin more when residual is large
            if next_item_size + item_size <= bin_capacity && post_residual > 30 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many open bins: consolidate; few open bins: fresh bin is cheap
    if open_bins_count > 6 {
        score += 10.0;
    } else if open_bins_count <= 2 {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity - item_size.
    // Only attractive early in the stream or when item is large relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if progress < 0.3 || large_item || mean_residual < (item_size as f64) {
            score -= 30.0;
        } else {
            score += 60.0;
        }
    }

    // Mild drift toward tighter packing as stream progresses
    score += (step_index as f64 / (total_items.max(1) as f64)) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead_zone = 20.0; // gaps <= 20 are likely unusable for typical items
        if (post_residual as f64) < dead_zone {
            score += (dead_zone - post_residual as f64) * 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and can fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0;
    }

    // Open-bin pressure: with many open bins, prefer packing tighter into existing bins.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += post_residual as f64 * 0.05 * pressure;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Mean residual coupling: if mean residual is large, encourage consolidating.
    score += (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    if post_residual < 10 {
        score -= 300.0;
    }

    // Lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit; penalize wasted residual relative to gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Mild penalty for high fragmentation potential
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize creating dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 30 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin — unless the fit is very poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we don't frivolously open bins.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 60.0;
        }
        // If item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Lookahead: if the next item would fit perfectly in the post residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        }
        // Penalize if placing here leaves post_residual that wastes the next item's fit.
        if next_item_size > post_residual && post_residual < 15 {
            score += 15.0;
        }
    }

    // Global state: spread load when mean residual is high (bins fragmented),
    // prefer filling fuller bins when mean residual is low.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_res_norm = mean_residual / bin_capacity as f64;
    if mean_res_norm > 0.5 {
        score -= 8.0 * mean_res_norm; // consolidate into existing space
    }
    // Late in the stream, be more conservative about opening new bins.
    if progress > 0.8 && is_new_bin {
        score += 20.0 * progress;
    }

    // Mild preference for bins that are already relatively full.
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let item = item_size as f64;

    // Base: post-residual, non-linearly coupled with stream progress.
    // Early on, small residuals matter less (room to grow bins); late, dead space is costly.
    let mut score = pr * (1.0 + 2.0 * progress * progress) + 0.35 * (pr * pr) / cap;

    // Smooth saturation of fill fraction: reward tight fits.
    let fill = item / cap;
    score -= 18.0 * fill * (1.0 - fill * 0.5);

    // Lookahead: penalize residuals that can't hold the next item, reward those that can.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 10.0 * gap * (1.0 - gap) + 4.0 * progress * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening bins unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 120.0 - 40.0 * pressure - 15.0 * (1.0 - progress);
    }

    // Mild penalty for deviation from mean residual (prefer balanced bins).
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Slight penalty for many open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "harmonically clean"
    // (multiples of common item-size classes 10/20/25/50), penalize awkward leftovers.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fill
    } else {
        if pr % 10 == 0 { class_bonus -= 12.0; }
        if pr % 20 == 0 { class_bonus -= 8.0; }
        if pr % 25 == 0 { class_bonus -= 8.0; }
        if pr % 50 == 0 { class_bonus -= 6.0; }
        // awkward zone: tiny unusable scraps (1..10) or just-above-half slivers
        if pr < 10 { class_bonus += 40.0; }
        let half = bin_capacity / 2;
        if pr > half && pr <= half + 10 { class_bonus += 10.0; }
    }
    score += class_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic fit quality of the remaining slack after next item
            if slack % 10 == 0 { score -= 10.0; }
            if slack == 0 { score -= 25.0; }
            score += (slack as f64) * 0.15;
        } else {
            // next item cannot use this residual: penalize large wasted residuals mildly
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins unless the fit is bad; modulate by open bins count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 20.0 * progress + (open_bins_count as f64) * 1.5;
    }

    // Prefer tighter fits generally: penalize proportion of capacity wasted.
    score += (post_residual as f64 / cap) * 10.0;

    // Mean residual drift: if this bin's residual is far below mean, it's a good squeeze.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit reward: small positive residual that is still usable.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1;
    }
    // If next item is close but does not fit, mild penalty for wasted chain.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score += pressure * 1.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if post_residual < 10 {
            score += 35.0; // but still reject near-dead placements
        }
    }

    // New-bin candidate: attractive early, or when all fits are poor.
    if bin_residual == bin_capacity {
        score = post_residual as f64; // = bin_capacity
        let stream_progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - stream_progress);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 25.0;
        }
        // Prefer new bin over bins that would leave dead space.
        if post_residual_dead_exists(mean_residual) {
            score -= 5.0;
        }
    }

    score
}

fn post_residual_dead_exists(_mean_residual: f64) -> bool {
    // placeholder-free coupling: keep behavior deterministic and simple
    false
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // leftover after next item placement
            let tail = post_residual - next_item_size;
            score -= 30.0 * (1.0 - tail as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Reward bins tighter than mean residual (well-utilized bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin early in the stream less, later more
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 60.0 * progress;
    }

    // Small bonus when few bins fit the item (scarcity)
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for the smallest future item
    // (sizes >= 1, so dead space is anything > 0 that likely can't be used).
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { post_residual as f64 };
        score += 1.5 * dead;
    }

    // Lookahead: bonus if next item exactly fills the post-residual (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Mild reward if next item still fits after this placement.
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = (fitting_bins_count as f64).max(1.0);
        let mut new_bin_penalty = 10.0 + 0.3 * open_bins_count as f64;
        new_bin_penalty -= 6.0 * progress; // late in stream, fresh bins less harmful
        // If mean residual across bins is large, open bins are wasteful -> new bin OK.
        new_bin_penalty -= 0.15 * mean_residual;
        // If no existing bin fits well (fit_ratio high everywhere), new bin is fine.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 20.0;
        }
        score += new_bin_penalty / scarcity;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling them.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
        score += 0.2 * open_bins_count as f64;
    }

    // Discourage leaving residuals in the awkward 1..10 band (unusable for most items).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize residual more strongly
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 20.0 * progress_coupling * norm_pr * norm_pr;

    // Reward tight fits (near-zero residual) smoothly
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64) as f64;
        if fits_next >= 0.0 {
            score -= 12.0 * (1.0 - fits_next / cap);
        } else {
            // penalize leaving residual too small for next item (dead space)
            score += 6.0 * (-fits_next / cap);
        }
    }

    // New-bin candidate: make empty bins less attractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress - 10.0 * (mean_residual / cap);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    // Residuals in "harmonic" classes that pair well with small items (multiples of 10, 20)
    // are less dead than awkward classes (e.g. 1..9 leftover).
    let awkward = (post_residual % 10 != 0) as f64;
    score += awkward * 6.0;

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact harmonic match: post_residual can host the next item exactly (next fits leaving 0 or a multiple-of-10 residue).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 45.0;
        } else if next_post % 10 == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual cannot host the lookahead item: dead space unless tiny.
        score += (next_item_size as f64) * 0.35;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize moderately so it only wins when all open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the current item is large relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Integer-division threshold coupling: favor bins whose residual class matches item's complement class.
    let complement_class = (bin_capacity - item_size) / 10;
    if class == complement_class && post_residual > 0 {
        score -= 12.0;
    }

    // Mild waste penalty scaled by stream position (early: keep options open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.05 * (1.0 - progress);

    // Discourage scattering across many open bins when mean residual is already small.
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted forever.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and progress.
        score += 8.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But if next item would leave this bin with unusable space anyway,
        // opening a new bin is less bad.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            score -= 6.0;
        }
    } else {
        // Reward using existing bins when residual is well above mean (large gap).
        if (bin_residual as f64) > mean_residual + 5.0 {
            score -= 3.0;
        }
    }

    // Lookahead: prefer bins whose leftover can still hold the next item.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Small slack above next item is good but degrade quickly.
            score -= 150.0 * (-slack / 25.0).exp();
        } else {
            // Next item cannot fit here: penalize leftover dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Penalize small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Relative to mean residual: prefer bins that keep mean residual balanced.
    let mr = mean_residual - post_residual as f64;
    score += 0.5 * mr;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when current bin fits poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // If lookahead fits perfectly in a fresh bin, encourage opening it.
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }
        // Discourage new bins when plenty of open bins fit the item.
        if fitting_bins_count >= 2 {
            score += 80.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: penalize if next item fits well in post_residual (save space),
    // reward if next item would NOT fit (no reason to preserve space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64 / bin_capacity as f64) * 25.0;
        } else {
            score += 8.0;
            // If next item barely misses fitting, dead space is more costly.
            let miss = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            if miss < 0.2 {
                score += (0.2 - miss) * 50.0;
            }
        }
    }

    // Time horizon: early in stream, be picky (avoid fragmentation); late, accept fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 15.0;

    // Global residual pressure: if mean residual across open bins is low,
    // opening new bins is costly; favor filling existing bins.
    score -= (mean_residual / bin_capacity as f64 - 0.5) * 10.0;

    // Penalize bins that are already quite full when many alternatives exist.
    if fitting_bins_count > 2 {
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score += fullness * fullness * 10.0;
    }

    // Slight penalty for opening a new bin when open bins fit well.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + mean_residual * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Non-linear polynomial coupling of residual with stream progress
    let base = r
        + 24.0 * rn * rn * (1.0 - progress)
        + 18.0 * rn * rn * progress
        - 10.0 * rn * (1.0 - progress) * progress * 4.0 * progress * (1.0 - progress);

    // Lookahead: reward if next item fits exactly into post_residual
    let mut lookahead = 0.0;
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            lookahead -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            lookahead -= 12.0 * (1.0 - gap / cap);
        } else {
            lookahead += 6.0 * (1.0 - n / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    let mut last_chance = 0.0;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        last_chance -= 15.0 + 20.0 * progress;
    }

    // Penalize deviating from mean residual (keep bins homogeneous)
    let homog = 3.0 * (r - mean_residual).abs() / cap;

    // New-bin candidate handling: neutral-ish, slightly penalized early
    let new_bin_pen = if bin_residual == bin_capacity {
        8.0 + 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64
    } else {
        0.0
    };

    let mut score = base + lookahead + last_chance + homog + new_bin_pen;

    // Smooth saturation of wasted space via cubic term
    score += 15.0 * rn * rn * rn * cap * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = (pr % 10 == 0) as i32
            + (pr % 20 == 0) as i32
            + (pr % 25 == 0) as i32
            + (pr % 50 == 0) as i32;
        score -= 6.0 * harmonic as f64;

        // Dead-space penalty: tiny unfillable leftovers
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Integer-division threshold: leftover large enough to host a mid item
        if pr / 20 >= 1 {
            score -= 3.0;
        }
        if pr / 40 >= 1 {
            score -= 3.0;
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
            // harmonic bonus if residual after next item is a nice class
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 && r2 > 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly
    // mismatched with the item (poor fit everywhere).
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64; // = post_residual for new bin
        let mean_gap = (mean_residual - item_size as f64).abs();
        // prefer new bin when mean residual is far from item and open bins few
        score += 20.0 - 0.5 * mean_gap - 0.5 * open_bins_count as f64;
        // late in stream, avoid scattering
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        let _ = fit_quality;
    }

    // Mild pressure to fill already-open bins tightly
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 15.0;
        } else {
            score -= 3.0;
        }
    }
    // Penalize if next item cannot use the leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Allow new bin only if no open bin would leave a tiny dead gap anyway.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Early stream: opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins whose residual is above mean
    // (fill the emptier bins first to consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item also fits here: reward proportionally to tightness of the pair
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - pair_waste * 0.35;
        } else {
            // Dead space relative to the lookahead item: penalize quadratically
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.08;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving more than average waste is bad, less than average is good.
    score += (post_residual as f64 - mean_residual) * 0.45;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize very small unusable post residuals (dead space) unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Early in stream: encourage consolidation into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0
            && post_residual > 0
            && (post_residual == next_item_size || post_residual >= next_item_size);
        if good_fit_exists {
            score += 35.0; // discourage opening new bin when lookahead fits existing bin
        } else {
            score -= 5.0; // slightly favor fresh bin when fits are poor
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: squared residual waste
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward near-perfect fits (residual close to zero)
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect pair
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving large awkward gaps
            score += 0.5 * (post_residual as f64).powi(2) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when item fits poorly everywhere else.
    // New empty bin has huge post_residual, so squared waste already penalizes it;
    // add a mild fixed opening cost, discounted early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress;
        // Opening a new bin is more attractive when few bins can fit the item
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Prefer filling bins whose residual is close to the mean (keeps residual distribution tight)
    score -= 8.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    // Mild pressure to consolidate when many bins are open
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p = 0.5 + progress;
    let poly = norm_pr * (1.0 + p * norm_pr + p * p * norm_pr * norm_pr);

    let mut score = 2.0 * poly * cap;

    // Prefer tight fits: reward small post_residual strongly
    score -= (item_size as f64 / cap) * 12.0;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let waste = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.6 * (waste / cap) * (1.0 + progress);
    } else {
        // Last item: strongly reward closing bins as full as possible
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Slight preference for consolidating into fewer bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-ish baseline, penalize slightly unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (0..=4). Small classes are good (tight fit),
    // large classes waste capacity.
    let q = (bin_capacity as f64 / 5.0) as u32; // 20 for C=100
    let class = post_residual / q; // 0..=5
    let class_penalty = match class {
        0 => -30.0, // residual < 20% : excellent packing
        1 => -15.0, // residual 20-40%
        2 => 0.0,
        3 => 10.0,
        4 => 22.0,
        _ => 0.0,   // new empty bin candidate handled below
    };
    score += class_penalty;

    // Fine-grained exact-fit reward: reward small post residuals nonlinearly.
    if post_residual <= q {
        score -= (q - post_residual) as f64 * 0.8;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item sizes (10/20/25/50) are reusable "harmonic" slots.
    if post_residual > 0
        && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0)
    {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this bin (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            // reward proportional to how tight the double fit is
            score -= (bin_capacity as f64 - next_left as f64) * 0.25;
        } else {
            // next item cannot fit here: penalize leaving medium dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        // penalize new bins mildly; relax late in the stream when mean
        // residual is small (open bins are too full for future items)
        let mut new_bin_score = 55.0 + mean_residual * 0.5;
        if mean_residual < item_size as f64 + 10.0 {
            new_bin_score -= 25.0; // open bins cannot host upcoming items well
        }
        if openness > 8.0 {
            new_bin_score += (openness - 8.0) * 2.0; // too many open bins already
        }
        if progress > 0.9 {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    // Integer division threshold: penalize residuals in awkward ranges
    // (just above half capacity) that few items can use.
    let half = bin_capacity / 2;
    if post_residual > half && post_residual < bin_capacity {
        score += (post_residual - half) as f64 * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if no plausible future item can use it well.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // Waste ratio: fraction of the bin left over after placement.
        let waste_ratio = gap / cap;
        // Penalize heavily when the gap is small but nonzero (dead space).
        if gap < 10.0 {
            score += 30.0 * (10.0 - gap) / 10.0; // small slivers are pure waste
        } else {
            // Larger gaps: mild penalty growing with waste ratio.
            score += 5.0 * waste_ratio;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= gap {
            let slack = gap - next;
            if slack == 0.0 {
                score -= 25.0; // perfect pairing
            } else if slack < 10.0 {
                score += 10.0; // would create a new dead sliver
            } else {
                score -= 8.0 * (1.0 - slack / cap); // decent follow-up fit
            }
        } else {
            // Next item cannot fit here: mild penalty, this bin is a dead end for lookahead.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress) * 0.5;
    score += pressure;

    // Prefer bins whose residual is close to the item (tight fit reward).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 4.0 * tightness;

    // New-bin candidate: neutral baseline with slight cost, only chosen when
    // open bins score poorly (their dead-space penalties push them above this).
    if bin_residual == bin_capacity {
        score = cap * 0.75 + pressure;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when it's the only fitting option
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post residual (tight fit).
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // ideal chain: this bin becomes perfectly reusable
    }

    // Near-match lookahead: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: post residual becomes dead space unless tiny.
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            // Penalize dead space that is too small for the next item,
            // scaled by how far below the next item it falls.
            score += 10.0 + 20.0 * (1.0 - dead / next_item_size as f64);
        }
    }

    // Reward bins whose residual is already below the mean (they are "used up");
    // packing into them keeps the mean residual of remaining bins high/usable.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; discourage early/needless opening.
        score += 55.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // But if lookahead suggests current bins would leave bad dead space,
        // a fresh bin becomes competitive: reduce penalty when item is large.
        if item_size >= 60 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain the next item too
        }
    }

    // Slight stream-progression pressure: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space that is too small to be useful later (items >= 10 typical,
    // but interface allows 1..100, so weight against next_item_size when known).
    let min_useful = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 12.0 * (min_useful - post_residual as f64) / min_useful;
    }

    // Lookahead: reward bins whose post_residual can hold the next item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when many open bins already fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with number of fitting alternatives.
        score += 10.0 + 3.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If mean residual across open bins is high, prefer using open bins.
        score += 0.5 * mean_residual;
    } else {
        // Slight preference for fuller bins (lower residual before placement).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Global state: with many open bins, tighten packing to avoid bin sprawl.
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    // Mild time-decay noise-free exploration term coupling lookahead and progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 40.0 * poly * (0.5 + progress);

    // Penalize large post residual as stream matures (quadratic in progress)
    score += pr_norm * pr_norm * 30.0 * progress;

    // Reward tight fits
    score -= (item_size as f64 / cap) * (1.0 - pr_norm) * 10.0;

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Coupling with mean residual of open bins: prefer bins below mean residual
    score += 5.0 * (mean_residual - pr) / cap;

    // Many open bins: slight penalty to opening new ones, reward consolidation
    if bin_residual == bin_capacity {
        score += 15.0 * (open_bins_count as f64).sqrt() * (0.5 + progress);
    } else {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals falling into "dead zones" that few item sizes can fill.
    // Items are 1..=100, so a residual r is fillable if some future item <= r arrives.
    // Small residuals (< 10-ish) are nearly dead; large residuals are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // nearly unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 34 {
        score += 10.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with the classic size grid; reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd residuals slightly penalized (less likely to be exactly filled).
    if post_residual % 2 == 1 {
        score += 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with next item: if the next item exactly fills the post residual,
    // strongly favor this bin (chain completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 8.0 * tight;
        } else {
            // next item cannot use the post residual: penalize wasted space
            score += 0.15 * pr;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing residuals
    // are all small (poor fits) and the item is large.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        // open new bin if mean residual is small relative to item size
        let pressure = (item_size as f64) / cap;
        if mean_frac < pressure * 0.6 {
            score -= 20.0 + 10.0 * pressure;
        } else {
            score += 15.0; // discourage wasteful new bins
        }
        // early stream: slightly favor consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Tie-break toward tighter existing bins: reward closeness of fit.
    let tightness = 1.0 - frac;
    score -= 5.0 * tightness;

    // Spread penalty: bins far below mean residual waste capacity elsewhere.
    if (bin_residual as f64 - mean_residual).abs() > 40.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (min size 1..=100, but small gaps < 10 are
    // nearly unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, strongly favor this bin; if the residual is just barely
    // too small for the next item, penalize (wasted opportunity).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.4 * miss;
        }
    }

    // Tightness reward relative to current residual: prefer bins where the
    // item fills a large fraction of available space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading into
    // bins with large residuals; when few bins are open, be permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean residual (keeps the
    // bin pool homogeneous, leaving one large-residual bin as buffer).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when item is large and no open bin
    // fits well, or late in the stream with few open bins.
    if bin_residual == bin_capacity {
        let late = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        let no_fit = (fitting_bins_count == 0) as i32 as f64;
        score = 150.0 - 60.0 * large_item - 40.0 * no_fit - 20.0 * late + 5.0 * pressure;
        // Never open a new bin for a tiny item when a bin fits.
        if item_size < 30 && fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post_residual) strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits into the post-residual, this is
    // a great pairing — reward it proportionally to how snugly it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 - slack.min(150.0);
        if slack == 0.0 {
            score -= 200.0; // perfect 2-item chain fill
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize relative to mean residual.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
        if post_residual < 10 {
            score += 100.0; // tiny unusable sliver
        }
    }

    // Prefer filling fuller bins over emptier ones (relative to mean residual).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current item leaves a large
    // awkward residual in every open bin (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && item_size >= 50 && post_residual < next_item_size {
            score -= 200.0; // fresh bin pairs well with next item
        }
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
    }

    // Mild preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range):
    // residual in (0, 10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize leaving a gap that the NEXT item cannot use (lookahead k=2).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }
    // Reward leaving exactly enough room for the next item (chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Early in the stream: encourage spreading items to create diverse residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && bin_residual == bin_capacity {
        score -= 10.0 * (0.3 - progress);
    }
    // Late in the stream: consolidation matters; penalize opening new bins.
    if progress > 0.7 && bin_residual == bin_capacity {
        score += 20.0 * (progress - 0.7);
    }

    // Compare bin residual against the mean residual: prefer bins with below-average
    // residual (i.e., fuller bins) to keep a spread of large residuals available.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Mild penalty for many open bins: discourage bin proliferation.
    score += 0.8 * open_bins_count as f64;

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Squared coupling: penalize large post_residual quadratically (wasted space).
    score += 0.35 * (post / cap) * post;

    // Smooth dead-space term: residuals too small for typical items are dead.
    let dead = ((post / cap) - 0.25).abs();
    score -= 12.0 * (-dead * dead * 4.0).exp();

    // Stream-progress interaction: early on, keep bins flexible (penalize tight fits);
    // late, prefer tight fits strongly.
    let tightness = 1.0 - post / cap;
    score += (0.5 - progress) * 20.0 * tightness * tightness;

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 8.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size as f64 - post) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score += 18.0 - 14.0 * frag * open_bins_count.min(10) as f64;
    }

    // Mean-residual deviation coupling: prefer bins whose residual tracks the mean.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (near-perfect fills) are strongly rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Integer-division thresholds on post_residual: leftover <= 10 is dead-space free.
    if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 18.0;
    } else if pr <= 30 {
        score -= 6.0;
    }

    // Modulo-arithmetic harmonic classes: residuals that are divisors-friendly
    // (pr % 25 == 0) pair well with common item sizes.
    if pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }
    // Odd, awkward residuals are penalized.
    if pr % 2 == 1 && pr > 15 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= 10.0;
            // Harmonic pairing: next item leaves another tiny residual.
            if pr - next_item_size <= 10 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): neutral baseline tied to mean residual.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + mean_residual * 0.25;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Fraction-of-capacity coupling: reward fills close to capacity fractions.
    let fill_frac = 1.0 - prf / cap;
    score -= fill_frac * fill_frac * 20.0;

    // Stream progression: late in stream, tighten bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Avoid spreading across too many open bins when mean residual is high.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual + 20.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (>= 1) are pure waste. Penalize tiny gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Smooth dead-space penalty scaled by how unusable the gap is
        // relative to the minimum plausible item size.
        score += 0.15 * (post_residual as f64).powf(1.4);
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness);

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins, and make opening a new bin less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 20.0 + 8.0 * open_bins_count as f64 + 30.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64 * (1.0 - tightness);
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // this placement chains nicely; otherwise penalize leaving a gap the
    // next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Mild alignment with mean residual: prefer bins below-average residual
    // (i.e., fuller bins) to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the residual after this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fit, strongly prefer
        } else if post_residual > next_item_size {
            // next item fits too; reward tighter chains
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.4;
        } else {
            // dead space relative to lookahead: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.6;
        }
    }

    // Prefer bins already below mean residual (tighter bins absorb item better).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin wastes the average open residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // penalize new bins when open bins have plenty of usable space
        score += 25.0 + pressure * 50.0 - progress * 10.0;
        // allow new bin if next item is large and won't fit anywhere later
        if next_item_size > 60 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Mild reward for very tight residual fits (little waste left overall)
    if post_residual <= 10 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual, non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post residual, big reward for chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * (next_item_size as f64);
        } else {
            // Waste: post residual can't host next item; penalize proportionally to leftover.
            let waste = post_residual as f64 / cap;
            score += 12.0 * waste;
            // If next item could have fit before this placement, this was a squandered chance.
            if next_item_size <= bin_residual as u32 && next_item_size > post_residual {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: only bin that fits the item — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is usually bad unless all open fits are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.85 + 10.0 * tightness; // baseline high cost for a fresh bin
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open new bin
        } else if fitting_bins_count == 1 {
            score -= 15.0; // weak alternative to the last-chance bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with slack: discourage opening yet another.
        score += 0.4 * open_bins_count as f64;
    }

    // Mild global-pressure coupling: when open bins are slack on average,
    // favor bins below the mean residual (tighter bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Early stream: allow more exploration of fresh bins; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let x = norm_pr * (1.0 - progress);
    score -= 30.0 * x * x;
    score += 8.0 * norm_pr * progress * (1.0 - progress);
    score -= 12.0 * (pr / (mean_residual + 1.0)).powi(2) * (1.0 - progress);
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (pr - nx).abs() / cap;
        score += 20.0 * gap * gap * (1.0 - progress);
        score -= 10.0 * (1.0 - gap) * (1.0 - progress) * (1.0 - norm_pr);
    }
    score += 0.5 * open_bins_count as f64 * progress * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot band" does it land in?
    // Class 0 = perfect fit (0), class 1..=4 = small dead space, higher = waste.
    let class = post_residual % 10;
    score -= match post_residual {
        0 => 60.0,
        _ if class == 0 => 12.0,                       // multiple-of-10 residual is reusable
        _ if post_residual < 10 => 25.0,               // dead space < 10 unusable
        _ => (class as f64) * 0.5,                     // mild penalty by remainder
    };

    // Harmonic coupling: does next item divide into post_residual nicely?
    if next_item_size > 0 && next_item_size <= post_residual {
        let q = post_residual / next_item_size;
        let r = post_residual % next_item_size;
        if r == 0 {
            score -= 20.0 + 5.0 * q.min(5) as f64;     // exact divisibility: strong reward
        } else {
            score -= 8.0 - (r as f64) * 0.3;           // partial fit reward, decayed by waste
        }
    } else if next_item_size > 0 {
        // next item cannot fit here regardless; slight penalty for stranding capacity
        score += 4.0;
    }

    // Integer-division thresholds on residual fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac >= 0.5 {
        score -= 10.0;                                  // keep large-capacity bins attractive
    } else if frac < 0.1 {
        score += 15.0;                                  // near-full bin: low priority unless exact
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it early in stream or when open bins are fragmented
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = 45.0 - progress * 20.0 + fragmentation * 3.0;
    }

    // Mild preference to fill bins with above-mean residual (balance avoidance of waste)
    if bin_residual > 0 && bin_residual < bin_capacity {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize small gaps super-linearly (they are nearly unusable).
        if dead < 25.0 {
            score += (25.0 - dead) * 3.0;
        }
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 60.0;
        }
        // Near-perfect fits also rewarded.
        if post_residual <= 5 {
            score -= 20.0;
        }
    } else {
        score -= 60.0;
    }

    // Large leftover space is valuable (flexible): reward keeping big residuals.
    if post_residual >= 50 {
        score -= 15.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but allow opening a new bin when few bins are open (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64 - nx).abs() < 0.5 {
            score -= 40.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate baseline: empty bin gets a moderate default score so it
    // is only chosen when open bins score poorly (bad fits / tiny dead space).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // Early stream: opening new bins is cheap.
        if open_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit with the lookahead item (residual becomes 0 next step)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward if next item fits exactly in the post-residual region broadly (tight 2-step packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 2.0 * (next_item_size as f64) - 0.5 * (slack_after_next as f64);
    }

    // Penalize small dead space that no future item (min size 1) can use efficiently:
    // tiny residuals are wasted capacity; add superlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual - post_residual as f64).abs();
        score += 40.0 + tightness;
        // Open new bin if existing bins are nearly full (mean residual small)
        if mean_residual < 15.0 {
            score -= 60.0;
        }
    }

    // Mild pull toward bins below mean residual (balance / save big-residual bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in stream: be greedier, minimize residual aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        let dead_threshold = 9.0 + 6.0 * progress;
        if (post_residual as f64) < dead_threshold {
            score += 25.0 * (dead_threshold - post_residual as f64);
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly/nicely
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing ones over spreading
    score += 0.35 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: bins far from the mean residual get a nudge toward consolidation
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate: make it attractive only when fits are poor or late in stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score = 55.0 + 40.0 * fit_quality - 20.0 * progress;
        if fitting_bins_count > 2 {
            score += 15.0; // plenty of alternatives, keep new bin unattractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * (0.5 + 0.5 * progress);
    let mut score = pr + 40.0 * poly;

    // Smooth dead-space penalty: quadratic in wasted space
    if x > 0.0 && x < 0.35 {
        score += 25.0 * (0.35 - x) * (0.35 - x) / 0.1225;
    }

    // Last-chance bonus (smooth via fitting count)
    let fc = fitting_bins_count as f64;
    score -= 15.0 * (1.0 / (1.0 + fc * fc)) * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let tight = 1.0 - ((next_item_size as f64 - x * cap).abs() / cap).min(1.0);
        score -= 12.0 * fits * tight * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from mean residual
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize slightly unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln().max(0.0);
        score += 20.0 - 10.0 * crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (large enough to host typical items) get rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // leftovers that are multiples of 10 or >= 20 are more reusable
        if class == 0 {
            score -= 6.0;
        } else if pr >= 20 {
            score -= 3.0;
        } else {
            // dead space 1..19 is nearly useless
            score += (19 - pr) as f64 * 0.8;
        }
    }

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // next item fits, but penalize by leftover after that
            let nxt_post = post_residual - next_item_size;
            score -= 8.0 - (nxt_post as f64) * 0.1;
        } else {
            // next item won't fit here: slight penalty for tight fills
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap;
        // opening a new bin is attractive when few bins fit the item
        // or when open bins have large residuals (bad fragmentation elsewhere)
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score -= 30.0 / scarcity;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin accommodates the pair comfortably
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // reward filling bins that are already relatively full
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= fullness * 10.0;
    }

    // Mild diversity bonus: keep mean residual spread reasonable
    score -= (mean_residual - post).abs() * 0.05;

    // slight tie-break noise via deterministic coupling
    score += ((item_size as f64) * 0.01) - ((open_bins_count as f64) * 0.005);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading items across many bins.
    let pressure = open_bins_count as f64;
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from mean (consolidate slack).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strong reward to use it instead of opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized when open bins are few,
    // rewarded when open bins are many and fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 - 0.5 * pressure;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Early stream: be conservative, keep bins tight; late stream: accept loose fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-chain: next item exactly fills the remainder.
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to how tight the 2-chain is.
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            // Bonus if the two-chain leaves near-zero residue.
            let after2 = post_residual - next_item_size;
            if after2 <= 5 {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap just below next size.
            score += 60.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: prefer bins tightened toward the mean.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when existing bins would create bad dead space
    // and the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let poor_fit_existing = if fitting_bins_count > 0 {
            let min_waste = (0..fitting_bins_count).map(|_| 0.0).fold(f64::INFINITY, f64::min); // neutral placeholder
            min_waste
        } else {
            f64::INFINITY
        };
        let waste_here = (bin_capacity - item_size) as f64;
        let _ = poor_fit_existing;
        // Base penalty so new bins are opened only when justified.
        score += 80.0;
        // Large items early in the stream benefit from a fresh bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
        // If the only alternative bins are much emptier than average, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Penalize opening a bin when the current item would leave a large residue anyway.
        score += 0.3 * waste_here;
        // If next item is huge and would fit alone in a fresh bin, prefer fresh bin
        // when current item leaves big residue here.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 30.0;
        }
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to strongly favor near-perfect packing.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin;
    // if the next item would fit better elsewhere (post_residual too small for it),
    // slight penalty for wasting space the next item could have used.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Dead space relative to the lookahead item.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Penalize opening a new bin when plenty of aggregate space exists in open bins.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let total_free = mean_residual * (open_bins_count as f64);
        if item_size as f64 <= total_free {
            score += 20.0 + 0.5 * (open_bins_count as f64);
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    } else {
        // Prefer bins with residuals close to the item size (relative waste small).
        let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
        score += waste_ratio * 10.0;

        // Slight preference for bins whose residual deviates from the mean
        // (consolidate outliers, keep average-shaped bins flexible).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Mild tie-break: prefer filling bins that are already fairly full.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), smoothed polynomial
    let mut score = pr * pr / cap;

    // Progress coupling: late in the stream, tolerate larger residuals less
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += norm_pr * norm_pr * cap * progress_weight;

    // Reward near-perfect fits with a smooth quadratic bonus
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 30.0;

    // Lookahead: if next item fits in post-residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            let fill = 1.0 - (slack / cap);
            score -= 20.0 * fill * fill;
        } else {
            score += 5.0 * (-slack / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins that are outliers vs mean residual (keep residuals uniform)
    let deviation = pr - mean_residual;
    score += 0.1 * deviation * deviation / cap;

    // Many open bins: prefer filling existing ones over opening new
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Brand-new empty bin candidate: penalize mildly, more so early on
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which residue class mod common item sizes
    let post = post_residual;
    // Reward post-residuals that are "usable" classes: divisible by small sizes
    let usable = if post == 0 { 3.0 }
        else if post % 10 == 0 { 2.5 }
        else if post % 5 == 0 { 1.5 }
        else if post >= 10 { 0.5 }
        else { -2.0 }; // dead space < 10 is unusable
    score -= usable * 4.0;

    // Penalize tiny dead space harder as it wastes capacity
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size < post {
            let slack = (post - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            // harmonic class match: next item leaves usable residue again
            let npost = post - next_item_size;
            if npost % 10 == 0 || npost == 0 { score -= 6.0; }
        } else {
            // next item cannot follow here: mild penalty proportional to overflow
            score += 4.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * (1.0 + 0.3 * progress);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // large next item: fresh bin may be fine
        }
    }

    // Prefer bins tighter than average (best-fit flavor with mean coupling)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(30.0) * 0.3;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Integer-division threshold: post_residual classes by /20 buckets
    let bucket = post / 20;
    score -= match bucket { 0 => 2.0, 1 => 1.0, 2 => 0.5, _ => 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
