    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: with many bins open, prefer packing into existing bins
    // (penalize opening a new bin) unless the fit is very tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate: bin_residual == bin_capacity means empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + pressure * 3.0;
        // If this bin is the last chance and it fits well, discourage new bin.
        if fitting_bins_count == 1 && post_residual < 25 {
            score -= 50.0;
        }
    } else {
        // Reward using a last-chance bin to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins get packed first).
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

