    score += open_bins_count as f64 * 0.5;

    // Early stream: slightly prefer keeping residuals flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Lookahead coupling (k=2): reward placements that leave room shaped for the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let gap = (nr - pr).abs();
        if gap < 0.5 {
            // perfect two-item packing: next item exactly fills the leftover
            score -= 18.0;
        } else if nr <= pr {
            // next item still fits: mild reward, stronger early when stream is long
            score -= 7.0 * (1.0 - 0.5 * progress);
        } else {
            // next item won't fit: this placement risks dead space
            score += 3.0 + 2.0 * progress;
