    // Last-chance bin: if this is the only open bin that fits, using it avoids opening a bin.
    if fitting_bins_count == 1 {
        score -= 9.0;
    }

    // Mild pressure toward bins tighter than the fleet average (best-fit flavor).
    score += (mean_residual - pr) * 0.12;

    // Penalize creating tiny unusable slivers (< 10, minimum item size in classic streams).
    if pr > 0.0 && pr < 10.0 {
        score += 12.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): default to a high score so it is
