    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 8.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 4.0 * tightness * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize residual that wastes space relative to next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 6.0 * gap * gap * (1.0 - progress);
