    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - progress);
    }

    // Slight pull toward mean residual to balance bin loads
    score += 0.05 * (pr - mean_residual).abs();

    // Late-stream: prefer filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 2.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
