    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = mean_residual / (bin_capacity as f64);
        // Prefer new bin when mean residual is low (open bins nearly full)
        score += 120.0 * (1.0 - congestion) - 60.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Slight preference to consolidate into fewer bins
    score += 0.5 * open_bins_count as f64;

    // Tight-fit coupling: reward small waste when item is large
    let waste_ratio = post_residual as f64 / (bin_capacity as f64);
    score += waste_ratio * waste_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that can't fit even the smallest plausible item is pure waste.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (bin_capacity as f64) * 2.0;
    }

    // Non-linear penalty on post_residual relative to item size:
    // small leftovers after large items are worse than after small items.
    if item_size > 0 {
        let waste_ratio = post_residual as f64 / item_size as f64;
        if waste_ratio < 0.25 {
            score -= 5.0 * (0.25 - waste_ratio);
        } else if waste_ratio > 0.5 {
            score += 4.0 * (waste_ratio - 0.5);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + 2.0 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    } else {
        score -= 3.0 + 0.05 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * tightness;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use this gap: mild penalty proportional to gap smallness
        score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins below mean residual (filling emptier bins keeps tight bins tight).
    if bin_residual != bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: post_residual consumed exactly
        } else if post_residual > next_item_size {
            let chain_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect chain
    if bin_residual == bin_capacity {
        let bonus = if next_item_size > 0 && post_residual == next_item_size { 0.0 } else { 20.0 };
        score += bonus;
    }

    // Slight preference for filling bins more fully as stream progresses
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual), but only when the leftover
    // remains potentially usable; otherwise penalize dead space.
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    } else if post_residual < 10 {
        // tiny sliver: likely dead space unless it exactly hosts next item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 8.0 * (10.0 - post_residual as f64);
        }
    } else {
        // moderate leftovers are valuable: reward proportionally
        score -= 6.0 * (1.0 - frac);
    }

    // Lookahead: if this bin's post residual can host the next item,
    // strongly favor it (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 10.0 + 0.15 * chain_quality;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item cannot fit here anyway; neutral
    } else if next_item_size > post_residual {
        // we destroy the ability to host next item: penalty scaled by how close it was
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins (avoid sprawl).
    score += 0.3 * open_bins_count as f64 * frac;

    // Compare against mean residual: bins with above-average residual should
    // absorb items (keep small-residual bins as specialized remnants).
    if bin_residual as f64 > mean_residual {
        score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Time horizon: early in stream, be picky (leave room); late in stream,
    // fill aggressively since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - frac);

    // New-bin candidate handling: empty bin has large post_residual naturally.
    // Penalize opening a new bin unless current item is large or fits are bad.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let bad_alternatives = fitting_bins_count == 0;
        // Base cost of a fresh bin; discounted when item is large or no alternatives.
        let base = 12.0 - 6.0 * big_item - if bad_alternatives { 12.0 } else { 0.0 };
        // Late in the stream, opening new bins is fine (stream is long anyway).
        score += base.max(-2.0) + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, with non-linear (quadratic) penalty on large residuals
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth coupling of residual penalty with stream progress:
    // early on, waste is more forgivable; later, dead space is costly.
    let prog_term = progress * progress;
    score += (pr / cap) * (1.0 + 2.0 * prog_term) * 8.0;

    // Exact fit reward (smooth, non-piecewise)
    let fit_quality = 1.0 - pr / cap;
    score -= 15.0 * fit_quality * fit_quality;

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        let kernel = (-diff * diff / (2.0 * 15.0 * 15.0)).exp();
        score -= 10.0 * kernel;
        // Penalize if post-residual just barely misses the next item (smooth)
        let miss = ((ns - pr) / cap).max(0.0);
        score += 6.0 * miss * miss * cap / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor, smooth)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: neutral-ish baseline with slight aversion that decays
    // as stream progresses (early: prefer filling open bins less strictly).
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    // Mild preference to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    // Dead-space harmonic classes: residual in (0,10] is nearly unusable for items >=10,
    // (10,20] is a "harmonic" slot for small items, etc.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: heavily reward
    } else if post_residual <= 5 {
        score -= 45.0; // near-perfect fit, dead space negligible
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0; // harmonic band: many small items fit later
    } else if post_residual <= 30 {
        score += 4.0;
    } else if post_residual <= 50 {
        score += 10.0;
    } else {
        score += 18.0; // large leftover: wasteful placement
    }

    // Non-linear penalty on wasted capacity fraction.
    score += 20.0 * frac * frac;

    // Lookahead: reward if the next item fits exactly into the post residual (harmonic chaining).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how much of the residual the next item consumes
            score -= 18.0 * (nx / pr.clamp(1.0, cap));
        } else {
            // next item cannot fit here: penalize large residuals slightly less if they
            // could be split into two future items (harmonic divisibility)
            let half = post_residual / 2;
            if next_item_size <= half as u32 * 2 && half >= 10 {
                score += 2.0;
            } else {
                score += 6.0 * (nx / cap);
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Many fitting bins: mild penalty to keep tightness preference dominant.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Progress-based calibration: later in the stream, be stricter about residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * frac;

    // Bin-count pressure: when many bins are open, discourage spreading; prefer filling.
    score += 0.05 * open_bins_count as f64 * frac;

    // Mean-residual coupling: if this bin's residual is far below the mean (tight bin),
    // prefer finishing it off; if far above mean, it's a loose bin, slightly deprioritize.
    let diff = mean_residual - pr;
    score += 0.15 * diff;

    // New-bin candidate handling: empty bin should only win when no open bin offers a
    // good fit. Make the empty bin moderately attractive, but worse than a tight fit.
    if bin_residual == bin_capacity {
        // base attractiveness: competitive with loose placements, worse than tight fits
        score = cap * 0.75;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        } else if next_item_size > 0 && next_item_size as f64 >= cap * 0.6 {
            // big next item: opening fresh capacity can be worthwhile
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize if next item cannot use the post residual (wasted chain potential).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * pressure * fill_ratio;

    // New-bin candidate (empty bin): make it less attractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * pressure;
    }

    // Mean residual coupling: prefer bins with below-average residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, close out bins aggressively (favor tight placements).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-item packing: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this one; reward tight coupling.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here afterwards; penalize by leftover gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Perfect fit now (no dead space) is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual < 10 {
        // Tiny dead space is nearly as good.
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could fit, unless the new bin
    // promises good future use (large item, plenty of stream remaining).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
        // A new bin is more attractive if the next item is large and could pair with it.
        if next_item_size > 0 {
            score -= 0.2 * next_item_size as f64;
        }
    }

    // Mild preference for fuller bins overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        let pr = post_residual as f64;
        // dead-space penalty grows superlinearly for small leftovers
        if pr <= 10.0 {
            score -= 25.0 * (1.0 - pr / 10.0);
        } else if pr < 10.0 {
            // unreachable, kept for safety
        }
        // penalize residuals too small for any plausible future item (sizes >= 1)
        if pr < 5.0 && pr > 0.0 {
            score += 12.0; // nearly-dead space
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 20.0; // chained perfect fit
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; slight penalty so bins that chain well win
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0; // still a decent fit too
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin when many bins are open and fragmented
        let frag = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        score -= 10.0 * (frag / bin_capacity as f64);
        // early in the stream, opening bins is fine (build a pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // if next item is large, a fresh bin is valuable
        if next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Global pressure: when many bins are open, avoid wasting space in them;
    // prefer consolidating into bins with below-average residual (tighter bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev; // prefer bins with residual below mean (tighter packing)
    }

    // Mild penalty scaled by open bin count for wasteful placements
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let coupling = norm_pr * (1.0 + 2.0 * progress_poly);

    // Waste penalty: squared normalized residual, amplified late in stream
    let waste = norm_pr * norm_pr * (0.5 + 1.5 * progress);

    // Tight-fit reward: cubic decay of residual
    let tight = -norm_pr * norm_pr * norm_pr * cap * 0.3;

    // Last-chance bonus when this is the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -5.0 } else { 0.0 };

    // Lookahead: penalize if next item won't fit residual
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            1.5 * (nx - pr) / cap
        } else {
            -0.5 * (1.0 - (pr - nx) / cap)
        }
    } else {
        0.0
    };

    // New-bin candidate: prefer opening fresh bin when residuals are fragmented
    let new_bin_bias = if bin_residual == bin_capacity {
        2.0 + 3.0 * (mean_residual / cap) * progress
    } else {
        0.0
    };

    let mut score = pr + coupling * 2.0 + waste * cap - tight + lookahead - last_chance + new_bin_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

