        score -= 25.0 - gap * 0.3; // prefer exact lookahead fill
        // Harmonic bonus: next item leaves a multiple-of-10 residual too.
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty scaled by mismatch.
        score += ((next_item_size - post_residual) as f64).min(30.0) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: it's the empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if the item fits poorly everywhere.
        // Penalize opening when a decent fit exists among open bins.
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            let _ = best_possible;
            // Compare against mean residual: if some open bin is roomy enough,
            // discourage a new bin; if mean residual is small (tight bins),
            // a new bin becomes attractive.
            let tightness = mean_residual / bin_capacity as f64;
            score += 35.0 * (1.0 - tightness); // harder to open when bins are tight
            if post_residual_of_open(item_size, mean_residual) > 0.0 {
                score += 10.0;
            }
        } else {
            // No alternative: opening is mandatory, make it attractive.
            score -= 100.0;
        }
        // Early in the stream, allow more open bins (future items need homes).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    // Prefer filling bins that are already substantially used (reduce bin count).
    let fill_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_fraction * 12.0;

    // Many open bins: consolidate; few open bins: be pickier about dead space.
    if open_bins_count > 4 {
        score -= 5.0;
    }

    score
}

#[inline]
fn post_residual_of_open(item_size: u32, mean_residual: f64) -> f64 {
    mean_residual - item_size as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest item (1..=10)
    // are unusable waste. Penalize proportionally to wasted fraction of capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    }

    // Small residual that could still fit a typical small item: mild penalty
    // to prefer bins whose remainder stays more versatile.
    if post_residual >= 10 && post_residual <= 30 {
        score += 5.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // avoid opening new bins unnecessarily.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // If next item would NOT fit post-residual, the leftover is dead for the next step.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., current bin is fresh/empty and stream is early or bins are crowded).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a new bin, discounted when open bins are few relative to progress.
        score = 70.0 - 30.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits anywhere: must open
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // next item can also fit here afterwards
            score -= 8.0 * (1.0 - lookahead_gap as f64 / bin_capacity as f64);
        } else {
            // dead space penalty scaled by how badly the next item won't fit
            score += 0.05 * lookahead_gap as f64;
        }
    }

    // Tight fit reward relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize deviations from mean residual (prefer balanced usage unless tight fit)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so open bins with decent fits win,
    // but allow opening a new bin when post_residual would be tiny dead space
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual < 10 {
            score -= 40.0; // opening a fresh bin is fine for near-perfect first fit
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Many open bins: encourage closing them out (prefer tighter fits)
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize small dead space (waste), but less if it can host the next item.
    let dead = post_residual as f64;
    let next_fits = next_item_size > 0 && (next_item_size as f64) <= dead;
    if dead > 0.0 {
        if next_fits {
            score -= 6.0; // keep slot for lookahead item
        } else {
            score += 0.05 * dead; // dead space penalty
        }
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item would fit exactly in post_residual, reward more.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be pickier about tight fits (more items to come);
    // late in the stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins
    // over opening new ones; new-bin candidate (residual == capacity) gets penalized.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 8.0 + 2.0 * pressure;
    } else {
        score -= 0.02 * mean_residual.min(100.0);
    }

    // Mild penalty for very small residual fragments (< 10, unusable for min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - (pr / cap); // fullness after placement, 0..1

    // Smooth polynomial core: prefer tight fits, mildly prefer small residuals
    let mut score = pr - 30.0 * tight * tight;

    // Non-linear coupling of residual with stream progress:
    // later in the stream, waste is more costly -> amplify residual penalty
    let prog_sq = progress * progress;
    score += pr * (0.6 * prog_sq + 0.4 * progress * (1.0 - progress)) * 0.5;

    // Cubic fullness reward, smooth in tightness
    score -= 20.0 * tight * tight * tight;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item can fit into the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_ratio = 1.0 - (pr - nxt) / cap;
            score -= 8.0 * slack_ratio * slack_ratio;
        } else {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mild pressure against proliferating bins with large residuals
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 12.0 - 0.1 * item_size as f64 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit (small post_residual wins)
    // Harmonic class of the post-residual: residual mod capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class the post-residual into harmonic bins: dead space is worse
    // when it is small but unusable (below the minimum plausible item size).
    let min_item = 1u32;
    if pr > 0 && pr < min_item {
        score += 1000.0; // unusable sliver
    }

    // Reward residuals that are exact divisors / nice fractions of capacity:
    // e.g. 50, 25, 20, 10 are highly reusable "harmonic" targets.
    let harmonic_targets: [u32; 8] = [0, 10, 20, 25, 30, 40, 50, 100];
    let mut best_match: u32 = 0;
    for &t in harmonic_targets.iter() {
        if t == pr { best_match = t; break; }
    }
    if best_match > 0 && best_match != bin_capacity {
        score -= 12.0; // perfectly harmonic residual
    }

    // Modulo-class coupling: post_residual divisible by common item sizes
    // (10, 20, 25) means future items can tile it perfectly.
    if pr % 10 == 0 { score -= 4.0; }
    if pr % 25 == 0 { score -= 2.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (perfect pair tiling).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits: penalize by leftover after next placement,
            // harmonic-classed.
            let after_next = pr - next_item_size;
            score += (after_next as f64) * 0.5;
            if after_next % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot use this residual: penalize large stranded space
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a scarce resource; prefer
    // using existing bins unless this fit is terrible.
    if bin_residual == bin_capacity {
        // New bin: neutral base = full capacity residual, but add pressure
        // that grows with stream progress and number of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * progress + 0.5 * (open_bins_count as f64).sqrt();
        // But if existing fits are all bad (large post_residual elsewhere),
        // the raw residual comparison already favors the fresh bin.
        if item_size >= 50 {
            score -= 5.0; // big items start fresh bins more readily
        }
    } else {
        // Existing bin: mild reward scaled by tightness relative to mean residual
        let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        if (post_residual as f64) < mean {
            score -= 2.0; // tighter than average: good
        }
    }

    // Prefer filling bins that are already partially committed (reduce bin count)
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= 6.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted space.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny unusable gap
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (waste ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score -= pressure;

    // New-bin candidate: penalize mildly, but less when no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 5.0 * pressure;
        let lookahead_bonus = if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 {
            15.0 // next item can't use the leftover here anyway
        } else {
            0.0
        };
        score += base_penalty - lookahead_bonus;
    }

    // Lookahead synergy: if the next item exactly fills the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    // Slight preference for bins tighter than the mean residual.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (small dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chaining
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasting space that could be matched
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post residual to mean residual: prefer bins that become below-average residual
    // (tight bins), penalize bins that end up far above average (loose, fragmented)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // (opening fresh bin is good for big items that would fragment small bins)
    if bin_residual == bin_capacity {
        let base_penalty = 250.0;
        let large_item_bonus = (item_size as f64 - 50.0) * 4.0;
        score = base_penalty - large_item_bonus + (bin_capacity - post_residual) as f64;
        // if lookahead chains well into a fresh bin, soften penalty
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild preference for tighter bins overall
    score += 0.2 * bin_residual as f64 / bin_capacity as f64 * 100.0;

    // Avoid spreading across too many bins
    score += 0.5 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item, the better.
    let tight = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 * (1.0 - tight.min(1.0));

    // Penalize post-residuals that are small-but-unusable for typical next items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // wasted space relative to lookahead
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-mean residual (fill the emptiest-but-fitting bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Time horizon: early on, be picky (penalize loose fits); late, pack anything.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.2 * (bin_residual as f64 - post_residual as f64);

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 15.0;
        // If nothing else fits well (post_residual of this new bin is large by definition,
        // so rely on global state): few open bins or high mean residual -> favor opening.
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            score -= 0.15 * mean_residual;
            if fitting_bins_count == 0 {
                score -= 50.0;
            }
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        score -= 10.0 * t;
    }

    // Mild penalty for accumulating many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let r = post_residual as f64 / bin_capacity as f64;
    let poly = r * r * (1.0 - progress) + r * r * r * progress;
    score += 40.0 * poly;

    // Reward tight fits, more strongly as the stream progresses.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * (0.5 + progress);

    // Penalize dead space close to typical item sizes (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - progress);
    }

    // Last-chance bin bonus: strongly prefer when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward residual that still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 8.0 * progress;
        }
    }

    // New-bin candidate: prefer it only when open bins are nearly full on average
    // and few bins can fit the item.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        score = 55.0 + 45.0 * crowded * (1.0 - progress) - 20.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover space: how it divides into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining

    // Small post_residual = tight fit -> reward strongly (dead space minimized).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes (10s)
    // are more reusable by future items.
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Integer-division threshold: residual splittable into two halves >= typical
    // item size is valuable (can host two more items).
    if post_residual / 2 >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next fits: penalize proportional leftover after the lookahead item
            let after_next = post_residual - next_item_size;
            score -= 10.0 - (after_next as f64) * 0.15;
        } else {
            // next item does NOT fit here: penalize more if gap is small
            // (near-miss wastes the bin's usefulness for the known future item)
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest (already via post_residual);
        // slight penalty to spread competition fairly.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a good fit (high mean residual
    // or many open bins with poor fits).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap and useful (keeps flexibility);
        // later, prefer filling existing bins.
        score = score * 0.6 + (1.0 - progress) * 10.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // big next item benefits from a fresh bin
        }
        if mean_residual < 25.0 && fitting_bins_count >= 1 {
            score += 20.0; // open bins are tight; avoid opening unnecessarily
        }
    }

    // Mild coupling with mean residual: bins far below mean residual are
    // "wasted" capacity holders; using them balances the fleet.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score += dev * 0.1;
    } else {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: punish small unusable gaps (< 10) hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (small wasted fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when fit is poor; otherwise favor consolidating into open bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (1.0 - fit_ratio);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // post_residual too small for next item: penalize if gap is dead space
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Prefer bins with below-mean residual (tighter bins fill first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral baseline, slightly attractive early in stream,
    // unattractive when many bins are already open and fit elsewhere exists.
    if bin_residual == bin_capacity {
        score = 45.0 + 2.0 * pressure - 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 1 {
            score += 50.0; // never abandon the only fitting bin for a fresh one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step match: strong reward
        } else if post_residual > next_item_size {
            // next item fits but leaves another residual; penalize by leftover
            score += (post_residual - next_item_size) as f64 * 0.3;
        }
        // dead space: next item can't fit here
        if next_item_size > post_residual {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is already tight relative to mean residual.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Avoid wasting large residual bins on small items.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Slight preference to fill older/more crowded bin pools.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Penalize zero residual slightly less than small-but-unusable residuals.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize small unusable leftovers, but not when leftover could fit the lookahead item.
    if post_residual > 0 {
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 3.0; // leftover is useful for the next item
        } else {
            score += 8.0; // dead space
        }
    }

    // Last-chance bin: strong reward to use it, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have large residuals relative to the item, or many bins are open.
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin if existing bins would leave big waste or too many bins open.
        score = 45.0 + avg_waste * 0.5 + open_bins_count as f64 * 0.8 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // keep fresh bins for bigger upcoming items
        }
        if avg_waste < 5.0 && open_bins_count < 4 {
            score += 20.0; // existing bins fit well; don't open new ones
        }
    }

    // Mild preference for bins below mean residual (balancing load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference to fill bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Lookahead synergy: if the next item fits exactly after this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);

    // Base: wasted space after placement, scaled by tightness non-linearity
    let mut score = post;

    // Quadratic/cubic waste penalty: small residuals are disproportionately bad
    let post_frac = post / cap;
    score += 60.0 * post_frac * post_frac;
    score -= 40.0 * post_frac.powi(3);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - post_frac;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Interaction: post_residual with normalized stream progress — later items
    // should pack tighter into existing bins
    score += 25.0 * post_frac * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 45.0 + 20.0 * tightness;
    }

    // Prefer bins whose residual deviates favorably from mean residual
    score -= 8.0 * ((bin_residual as f64) - mean_residual) / cap;

    // Lookahead: if next item fits the post residual exactly well, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty on opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 12.0 * (1.0 - scarcity) * (0.5 + post_frac);
        // Opening new bin is better late if open bins are fragmented
        score -= 15.0 * progress * (mean_residual / cap).min(1.0);
    }

    // Small diversity term coupling open bins count and post residual
    score += 3.0 * post_frac * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo small divisors
    let mod4 = post_residual % 4;
    let mod5 = post_residual % 5;
    let mod10 = post_residual % 10;
    let class = (mod4 + mod5 + mod10) as f64;

    // Reward residuals that are "clean" multiples (harmonically divisible space)
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else if post_residual % 2 == 0 {
        score -= 1.5;
    }
    score += class * 0.15;

    // Dead-space penalty: small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.2;
    }

    // Lookahead: does next item fit the post-residual exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 || nxt_post == 0 {
                score -= 6.0;
            }
            score += (nxt_post % 5) as f64 * 0.5;
        } else {
            // next item cannot use leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Tight fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin if no open bin is decent
    if bin_residual == bin_capacity {
        // new bin: neutral-ish base, penalize when open bins exist with room
        score += 20.0 + (open_bins_count as f64).sqrt() * 3.0;
        if fitting_bins_count == 0 {
            score -= 25.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin attractive
        }
    }

    // Prefer filling bins that deviate below mean residual (consolidate)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.4;

    // Stream progression: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Harmonic threshold on integer division of residual
    let q = post_residual / 25;
    score -= q as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward very tight fits (small absolute waste).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but slightly discourage opening yet another bin.
    score += 0.6 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins)
    // to keep looser bins available for future items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Stream progression: early on, be a bit more willing to open bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this is a two-item perfect fill -> strongly favor.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits inside the remaining space: partial match,
            // reward proportional to how much it consumes.
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * consumed;
            // Two-step fill leaving tiny dead space is nearly perfect.
            let two_step_dead = post_residual as f64 - next_item_size as f64;
            if two_step_dead < 10.0 {
                score -= 150.0 * (1.0 - two_step_dead / 10.0);
            }
        } else {
            // Next item will NOT fit here: this residual becomes dead space
            // unless another item later fills it. Penalize large leftovers
            // relative to the typical next-item demand.
            let waste = post_residual as f64 - (post_residual as f64).min(next_item_size as f64);
            score += 0.5 * waste;
            // If next item is bigger than residual, leftover is likely stranded.
            if next_item_size > post_residual {
                score += 30.0;
            }
        }
    }

    // Compare post-residual against mean residual across open bins:
    // leaving a residual well below average means we consumed scarce space
    // in an already-tight bin -> mild penalty; leaving residual near/above
    // average suggests a balanced packing -> mild reward.
    let pr = post_residual as f64;
    let diff = pr - mean_residual;
    score += 0.3 * diff;

    // Penalize creating awkward small residuals that fit almost nothing
    // (items are 1..100; residual < 10 is hard to reuse).
    if pr > 0.0 && pr < 10.0 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // placing here avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidate bins, prefer the tightest fit implicitly
        // via post_residual; add slight pressure to keep big-residual bins
        // available for larger future items.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Early in the stream, keep bins flexible (prefer spreading items),
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 20.0 * (pr / bin_capacity as f64);
    score += progress * 10.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is attractive only when no open bin fits well
    // (handled by fitting_bins_count) or when this is early in the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        } else if progress < 0.5 && next_item_size > 0 && next_item_size as f64 > mean_residual {
            // Next item is large relative to current residuals; keep a
            // fresh bin available for it.
            score -= 40.0;
        } else {
            score += 150.0; // prefer using an existing open bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract proportional to how full the bin becomes.
    let fill_ratio = (item_size as f64) / (bin_capacity as f64);
    score -= 30.0 * fill_ratio;

    // Penalize wasted residual relative to the smallest plausible future item,
    // but only if the leftover is "dead space" (too small for anything useful).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0; // unusable sliver
    } else {
        // Slight reward for residual that could still host mid-size items
        score -= 0.05 * post_residual as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement: mild penalty, worse if gap small
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Many open bins with high mean residual: encourage consolidating into
    // existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > 20.0 {
        score -= 0.1 * mean_residual.min(50.0);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so a new bin is only chosen when fits are poor.
        score += 15.0;
        // Penalize more when open bins already exist and item is small
        // (small items should fill leftovers).
        if open_bins_count > 0 {
            score += 10.0 * (1.0 - fill_ratio);
        }
        // Early in stream: slightly cheaper to open bins (building inventory).
        score -= 10.0 * (1.0 - progress);
        // If next item is large and won't fit anywhere typical, a fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 8.0;
        }
    } else {
        // Reward using bins whose residual is close to the item (good match).
        let match_quality = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64);
        score -= 10.0 * match_quality;
    }

    // Mild stochastic-free tie-breaker: prefer bins with lower index-like
    // ordering via residual, to keep deterministic compactness.
    score += 0.001 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize key quantities
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = 1.0 - (post_residual as f64 / cap);          // how full the bin becomes
    let post_norm = post_residual as f64 / cap;                    // dead space after placement
    let item_norm = item_size as f64 / cap;

    // Smooth non-linear reward for tight packing: quadratic coupling of fill with progress.
    // Later in the stream, tight fits matter more (fewer chances to fix waste).
    score -= 12.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Penalize dead space super-linearly; amplified when few fitting bins remain.
    let scarcity = 1.0 + (fitting_bins_count as f64).recip();
    score += 8.0 * post_norm * post_norm * scarcity;

    // Smooth interaction: small residuals that can't host the next item are waste.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        // Smooth "mismatch" term: how far post_residual is below next item, normalized.
        let gap = (nx - post_norm).max(0.0);
        score += 6.0 * gap * gap * (1.0 - progress);
        // Reward if the leftover still fits the lookahead item (chain packing).
        let fits_next = (post_norm - nx).max(0.0);
        score -= 4.0 * fits_next * (1.0 - fits_next) * 4.0; // concave bump, peaks at exact fit
    }

    // Coupling with mean residual: prefer bins below mean residual (consolidate large holes).
    let mean_norm = mean_residual / cap;
    let rel = post_norm - mean_norm;
    score += 5.0 * rel * rel.abs().sqrt() * (rel.signum());

    // New-bin candidate handling: empty bin. Prefer opening a new bin only when
    // the item is large relative to mean residual or progress is early.
    if bin_residual == bin_capacity {
        let pressure = (item_norm - mean_norm).max(0.0);
        // Base penalty for opening a bin, softened by pressure and scarcity.
        score += 10.0 - 14.0 * pressure * (1.0 + progress) - 3.0 * (fitting_bins_count == 1) as i32 as f64;
        // Late stream: discourage new bins more strongly.
        score += 6.0 * progress * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit style, but tuned against capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Harmonic class of post_residual: classify leftover space into usable slots.
    // Small leftovers (< 10, the minimum item) are dead space -> heavy penalty.
    if post_residual == 0 {
        score -= 45.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 60.0; // dead space: nothing can ever fill it
    } else {
        // Usable leftover: reward proportionally to how "class-aligned" it is.
        // Modulo arithmetic: leftovers divisible by common item sizes (10,20,25,50)
        // are more likely to be exactly filled by future items.
        let mut bonus = 0.0f64;
        if post_residual % 10 == 0 { bonus += 8.0; }
        if post_residual % 25 == 0 { bonus += 6.0; }
        if post_residual % 20 == 0 { bonus += 4.0; }
        if post_residual == 50 { bonus += 10.0; }
        score -= bonus;
    }

    // Lookahead coupling: does the next item fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward closeness of fit for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here regardless; slight penalty scaled by waste
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer a fresh bin only when current placement
    // would create large dead space and the item is big relative to capacity.
    if bin_residual == bin_capacity {
        // fresh bin: score = capacity residual; adjust by item size and stream state
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // opening a bin is attractive for large items early, less so late
        score -= 20.0 * item_frac * (1.0 - progress);
        // if mean residual across open bins is already large, opening is fine
        score -= (mean_residual / cap).min(1.0) * 5.0;
    } else {
        // placing into an existing bin: reward consolidation when many bins are open
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mild non-linear penalty for medium-quality leftovers (hard to fill later).
    if post_residual >= 10 && post_residual <= 19 {
        score += 12.0; // awkward 10-19 zone
    }
    if post_residual >= 21 && post_residual <= 24 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // Medium-small gaps are risky but partially usable.
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += mean_residual * 0.05 * progress;

    // New-bin candidate handling: only attractive when it enables a much
    // better packing (e.g. large item, poor fits elsewhere).
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when they truly win.
        score += 25.0;
        // If the item is large and would leave a bad gap elsewhere, a fresh
        // bin becomes competitive.
        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();

        if nxt <= post {
            // Next item can follow in this bin: reward match quality.
            let match_bonus = 30.0 * (1.0 - gap / bin_capacity as f64);
            score -= match_bonus;
            // Perfect chain (post_residual == next_item_size) is gold.
            if gap < 1.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here; penalize wasted residual relative to gap.
            score += 0.10 * (nxt - post);
            // But if post_residual is small anyway, it's fine (near-tight fit).
            if post < 10.0 {
                score -= 8.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose";
    // placing here is fine only if it tightens them toward mean.
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    score += 0.05 * dev.abs();

    // Penalize leaving awkward mid-range dead space (hard to fill later,
    // since items are >= 1 but small residuals invite fragmentation).
    if post_f > 0.0 && post_f < 5.0 {
        score -= 5.0; // very tight residual is good
    } else if post_f >= 5.0 && post_f < 15.0 && (next_item_size as f64) > post_f {
        score += 6.0; // awkward dead space nothing can use next step
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Make the empty bin moderately attractive by default
    // but reject it when a good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline for a fresh bin.
        score = bin_capacity as f64 * 0.9; // ~90: worse than any tight fit
        if next_item_size > 0 {
            // A fresh bin is great if the item is large and lookahead is large too.
            let item_f = item_size as f64;
            let nxt = next_item_size as f64;
            if item_f + nxt <= bin_capacity as f64 {
                score -= 15.0; // pairable chain in a fresh bin
            }
        }
        // Late in the stream, opening new bins wastes capacity; discourage.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // Many open bins already: discourage opening more.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Mild encouragement to keep using open bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Prefer filling bins that are already mostly full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Base reluctance to open a new bin; grows slightly over the stream
        score += 45.0 + 25.0 * t;

        // If no other open bin fits, opening a bin is necessary
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // If the next item is larger than the mean residual of open bins,
        // fresh capacity is valuable
        if next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        score += 20.0 * t;
    } else {
        // Perfect fill is ideal
        if post_residual == 0 {
            score -= 30.0;
        } else if next_item_size > 0 {
            if (next_item_size as u32) > post_residual {
                // Dead space: next item cannot use the leftover
                score += 12.0 + 0.25 * post_residual as f64;
            } else {
                // Leftover remains usable by lookahead item
                score -= 10.0;
            }
        }

        // Last-chance bin before opening a new one: strong reward
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Favor placing larger items into fuller bins (heavier items first)
        score -= (item_size as f64 / bin_capacity as f64) * 8.0;

        // Mild coupling to global state: keep residuals balanced
        score += 0.08 * (mean_residual - post_residual as f64).abs();

        // With many open bins, encourage tight packing to close bins out
        if open_bins_count > 3 {
            score += 0.05 * post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight fit reward: strongly favor small post_residual (quadratic coupling).
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // scaled smoothly by stream progress.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let nx = next_item_size as f64;
        let snug = 1.0 - (post - nx) / cap;
        score -= (10.0 + 20.0 * prog) * snug;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty growing with progress.
        score += 4.0 + 6.0 * prog;
    }

    // Penalize creating dead space relative to the mean residual of open bins.
    score += 0.15 * (post - mean_residual).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin, especially early in the
    // stream or when other bins fit; relax slightly late in the stream.
    if bin_residual == bin_capacity {
        let congestion = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 20.0 + 15.0 * (1.0 - prog) + 5.0 * (congestion.min(5.0) / 5.0);
    }

    // Mild dispersion pressure: many open bins with slack -> prefer filling them.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class A: near-perfect fit (post_residual in {0,1,2}) -> strong reward.
    if post_residual <= 2 {
        score -= 60.0 + (2 - post_residual) as f64 * 10.0;
    }
    // Class B: small dead space (3..=9) -> mildly penalize, worse if next item can't use it.
    else if post_residual <= 9 {
        score += 8.0;
    }
    // Class C: mid-range dead space (10..=19) -> penalize unless next item fits.
    else if post_residual <= 19 {
        score += 15.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0;
        }
    }
    // Class D: large leftover (20..=49) -> moderate penalty; reward if next item nests.
    else if post_residual <= 49 {
        score += 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }
    // Class E: roomy bin (>=50) -> neutral-ish; slight reward to keep filling big spaces.
    else {
        score -= 4.0;
    }

    // --- Integer division thresholds on post_residual ---
    // Quantize leftover into fifths of capacity; prefer bins whose leftover
    // belongs to "usable" classes (multiples of common item granularity).
    let quant = (post_residual / 10) * 10;
    match quant {
        0 => score -= 25.0,          // essentially exact fit
        10 => score += 6.0,          // awkward sliver
        20 => score += 2.0,
        30 => score -= 3.0,
        40 => score -= 6.0,
        50 => score -= 8.0,
        60 => score -= 10.0,
        70 => score -= 12.0,
        80 => score -= 14.0,
        _ => score -= 15.0,          // 90+: nearly empty bin
    }

    // Modulo-5 harmonic: leftovers divisible by 5 are more reusable.
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            // Next item exactly fills this bin afterwards: excellent chain.
            score -= 40.0;
        } else if gap > 0 && gap <= 5 {
            score -= 20.0;
        } else if gap > 0 {
            score -= (gap as f64).ln() * 4.0;
        }
        // Next item too large for this bin's leftover: leftover is dead space
        // unless another bin takes it; penalize proportionally.
        if gap < 0 {
            score += (-(gap) as f64).min(30.0) * 0.3;
        }
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 {
        // This is the only bin that can fit the item: avoid opening a new bin.
        score -= 50.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early when few bins open, or when item is large
        // and would leave awkward residue in open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        let large_item_bonus = if item_size >= 60 { 20.0 } else { 0.0 };
        // Base cost of opening a bin; low openness (few bins) makes it cheap.
        score += 30.0 - 25.0 * openness - large_item_bonus + 10.0 * progress;
        // If no open bin fits well (this call reached with empty bin anyway),
        // a fresh bin is fine; slight extra discount when mean residual is high
        // (open bins are already fragmented).
        if mean_residual < 15.0 {
            score += 10.0;
        }
    } else {
        // Existing bin: reward tightness relative to mean residual.
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // --- Fit tightness core (best-fit flavor) ---
    score -= (bin_residual - item_size) as f64 * 0.1;

    // --- Stream progression: as stream ends, prefer consolidating into
    // existing bins to avoid trailing near-empty bins. ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 5.0 * (progress - 0.8) * 5.0; // penalize new-bin usage late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are "dead space" -> heavy penalty.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward: emptying a bin entirely is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving a gap that the lookahead item cannot use
    // (lookahead 0 means last item -> residual waste matters less).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else if post_residual >= next_item_size {
            score -= 5.0; // gap is reusable by next item
        }
    } else {
        score += post_residual as f64 * 0.5; // end of stream: waste weighs more
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist (early stream).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: apply pressure so it is only
        // chosen when no decent fit exists among open bins.
        score += new_bin_penalty;
        // But if this is the last-chance situation (only one fitting bin and
        // its fit is poor), a fresh bin is attractive: handled implicitly by
        // the dead-space penalties on poor fits.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 4.0; // reserve fresh capacity for large upcoming items
        }
    } else {
        // Existing-bin bonus, scaled by scarcity of alternatives.
        if fitting_bins_count == 1 {
            score -= 12.0; // last chance: strongly prefer using this bin
        }
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact match between post_residual and next item ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills this bin -> huge reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this one; reward closeness (tight packing chain)
            score -= 20.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
            // If next item would leave another perfect residual, extra reward
            if post_residual - next_item_size <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here after this placement: penalize by gap size
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 30.0;
    }

    // --- Last-chance bin: strong bonus to use it rather than open a new bin ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- Penalize creating small, hard-to-use residuals (dead space) ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are wasteful
    }

    // --- Compare against mean residual of open bins ---
    // Placing into bins with residual above mean leaves smaller bins intact
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: attractive only when nothing fits well or many bins open
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else {
            // Prefer using existing bins unless their residuals are all large/fragmented
            score += 40.0 + 2.0 * open_bins_count as f64;
            // Early in stream, opening a fresh bin is cheaper (more future items to fill it)
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 20.0 * (1.0 - progress);
        }
    }

    // --- Slight preference for compact bin populations ---
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream, prefer tighter packing (dead space costs more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // Lookahead: if the next item fits exactly-ish into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot fit here, mildly penalize (wasted potential chain).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last chance: only this open bin can fit the item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual of others.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when open bins exist with usable residual.
        if open_bins_count > 0 {
            score += 15.0 + 0.3 * mean_residual;
        }
        // More open bins => stronger preference to consolidate into existing ones.
        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward using existing bins, more so when they are well-filled already.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize leaving residuals that no plausible item (1..100) can use well
    // if the leftover is tiny but nonzero and no lookahead match.
    if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals; late, penalize them quadratically
    let progress_coupling = 1.0 + 2.5 * progress * progress + 1.5 * progress;
    score += pr * progress_coupling * 0.5;

    // Reward filling bins well relative to mean residual state
    let mean_norm = mean_residual / cap;
    score -= (norm_pr - mean_norm).abs() * cap * 0.3;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        let decent_fit_bonus = if next_item_size > 0 && (next_item_size as f64) <= pr {
            1.0
        } else {
            0.0
        };
        score += 12.0 + 10.0 * (1.0 - progress) - 8.0 * decent_fit_bonus * progress;
    }

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score += diff * 0.4;
        // perfect lookahead fit reward
        if diff < 1.0 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate many open bins
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small dead space" classes (mod thresholds) are penalized.
    let pr = post_residual;
    let class = pr / 10; // integer division: residual decade class
    score += (class as f64) * 3.0;

    // Harmonic bonus: residual exactly divisible by common item granularities
    // (e.g. 10, 20, 25, 50) is reusable by future items -> reward.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 5.0; }
    } else {
        // Perfect fill is the best outcome.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly (or nearly) into the
    // post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 15.0 - (waste as f64) * 0.5;
            // Harmonic check on the double-fill leftover
            if waste % 10 == 0 { score -= 3.0; }
        } else {
            // Next item cannot use this residual: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64) * 0.08;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity):
    // only attractive when the item leaves a nicely harmonized residual
    // (e.g. exact multiples of 25/50) or no open bin fits well.
    if bin_residual == bin_capacity {
        if pr % 25 == 0 || pr % 50 == 0 {
            score -= 5.0;
        }
        // Opening a new bin while many bins sit with slack is wasteful.
        score += mean_residual * 0.15 + (open_bins_count as f64) * 2.0;
    } else {
        // Filling existing bins conserves bins: small global reward.
        score -= 2.0;
        // Prefer bins tighter than the mean (best-fit flavor).
        score += ((mean_residual - bin_residual as f64) * 0.1).max(0.0);
    }

    // Late-stream pressure: as the stream progresses, be more aggressive
    // about closing bins perfectly rather than hoarding slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + item_size / 2 {
        score += 25.0 * (1.0 - post_residual as f64 / (item_size as f64 + 1.0));
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Penalize leaving residual that no typical next item can use well.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score -= 10.0 * usable;
        score += 5.0 * (1.0 - usable);
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - fill_ratio));

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = 1.0 - fill_ratio;
        score -= 20.0 * poor_fit - 10.0;
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // 2-step lookahead: perfect chain fit (item + next item exactly fills bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        let two_step_residual = post_residual - next_item_size;
        if two_step_residual == 0 {
            score -= 60.0;
        } else {
            score -= 25.0 * (1.0 - two_step_residual as f64 / 50.0);
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportionally.
        score += (next_item_size.min(post_residual.max(1)) as f64) * 0.05;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a large residual on a small item when other bins exist.
    let waste = post_residual as f64 - mean_residual;
    if waste > 0.0 {
        score += waste * 0.15;
    } else {
        score += waste * 0.05; // small bonus for leaving below-average residual
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are relatively full (mean residual small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 12.0; // base cost of opening a new bin
        score -= 20.0 * fullness; // more attractive when existing bins are full
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can chain the next item too
        }
        if progress < 0.1 {
            score -= 5.0; // cheap to open bins early
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    if open_bins_count > 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fit tightness: reward filling a large fraction of the bin's current space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio;

    // New-bin candidate: penalize opening a fresh bin so we only do it when
    // no open bin offers a decent fit (post_residual already favors tight fits,
    // but an empty bin has large post_residual, so an extra push keeps it closed).
    if bin_residual == bin_capacity {
        score += 22.0;
        // If the item is huge relative to capacity, a fresh bin is more acceptable.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }
    // Many alternatives: mild penalty so we keep the best bins flexible.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead (k=2): reward leaving exactly enough room for the next item,
    // penalize leaving room that neither fits the next item nor is near zero.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 9.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the lookahead item.
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    }

    // Near-perfect closure bonus: tiny post_residual means the bin is essentially sealed.
    if post_residual <= 3 {
        score -= 6.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.35 * (open_bins_count as f64).sqrt();

    // Divergence from mean residual: prefer bins whose residual is already low
    // (concentrate waste in few bins rather than spreading it).
    score += 0.06 * (mean_residual - post_residual as f64).max(0.0);
    score -= 0.03 * (post_residual as f64 - mean_residual).max(0.0);

    // Time horizon: late in the stream, be greedier (favor tight fits, avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fit_ratio;
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fits)
    let mut score = pr;

    // Non-linear polynomial coupling: squared term punishes mid-range waste,
    // cubic term rewards very tight fits even more.
    score += 60.0 * norm_pr * (1.0 - norm_pr) * (0.5 - norm_pr);

    // Stream progress interaction: as stream advances, tolerate less waste
    // (early on, keep flexibility; later, pack tight).
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Reward bins whose residual after placement matches the next item
    // (smooth coupling, no hard threshold).
    if next_item_size > 0 {
        let gap = (norm_pr * cap - next_item_size as f64).abs();
        let match_bonus = 25.0 * (-gap / 40.0) * (-gap / 40.0);
        score -= match_bonus * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Mild pressure to fill bins when many are open
    score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - norm_pr);

    // Slight preference toward bins below mean residual (balance spreading)
    score += 3.0 * (norm_pr - mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small but nonzero post_residual is nearly useless
    // (harmonic classes: residual < 10 can hold almost nothing).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class of post_residual: usable-space tiers via integer division.
    // post_residual / 10 gives the largest "class size" item that still fits.
    let class = post_residual / 10;
    score -= (class as f64) * 3.0; // reward bins whose leftover stays useful

    // If next item fits exactly into the resulting residual, big reward (lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Perfect chaining: next item exactly fills the bin after this one.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slightly penalize wasting the chain.
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would leave terrible residuals. Penalize the fresh bin by the mean
    // residual we are abandoning, plus a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.5;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // But if item is large, a fresh bin is more acceptable.
        score -= (item_size as f64) * 0.15;
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += (bin_residual as f64) * 0.1;

    // Slight penalty when many bins are open: encourage consolidation.
    score += (open_bins_count as f64) * 0.3;

    // Coupling with mean residual: bins far below mean residual are
    // "ragged"; filling them is fine, but bins above mean should be
    // prioritized to balance toward closure.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10, or below next item's size) are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) < (next_item_size as f64).max(1.0);
        if dead {
            score += 25.0 + 0.5 * (post_residual as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual usefulness.
        score += 15.0 + 2.0 * (open_bins_count as f64);
        if mean_residual >= item_size as f64 {
            score += 10.0; // an open bin already has room; don't open a new one
        }
        // Slight relaxation late in the stream (fewer future consolidation chances).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Lookahead: prefer leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap too small for the known next item
    }

    // Mild preference for bins with below-mean residual (fill the emptier bins first).
    if bin_residual != bin_capacity {
        score += 0.1 * ((bin_residual as f64) - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fit (dead space zero)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Bonus if next item fills the bin exactly after this placement
        if diff == 0.0 {
            score -= 200.0;
        }
        // Penalize leaving residual just below next item (unusable wedge)
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins with small residuals relative to mean (tighter bins first)
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when residual would be large waste elsewhere
    if bin_residual == bin_capacity {
        // Opening a new bin is neutral-good baseline; penalize slightly so tight fits win
        score += 120.0;
        // But if no good fit exists (post_residual in open bins would be tiny/awkward),
        // new bin becomes attractive: handled by lookahead penalties above.
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Slight time decay: late in stream, prefer compacting into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scaled by fill fraction of the bin.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 - (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.2;
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // If many bins are open with large mean residual, discourage new bin.
        score += (open_bins_count as f64).sqrt() * 2.0;
        score += mean_residual * 0.1;
    }

    // Prefer bins with residual below mean (consolidate emptier space).
    score += ((mean_residual - post_residual as f64) * 0.15).max(-10.0);

    // Slight time pressure: as stream progresses, avoid waste more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 0.8 * progress) - 1.4 * pr_norm * pr_norm + 0.6 * pr_norm * pr_norm * pr_norm;
    let mut score = 2.0 * pr + 60.0 * poly * cap * 0.01;

    // Tight fits rewarded, smoothly scaled by progress
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_tightness * fit_tightness * (0.5 + progress);

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack) * (1.0 + 0.5 * progress);
        } else {
            score += 14.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize opening new bins when open bins have capacity; smooth in progress
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        let mean_waste = (mean_residual - pr) / cap;
        score += 12.0 * open_pressure * (1.0 - 0.6 * progress) + 20.0 * mean_waste.max(0.0);
    }

    // Small global shaping: prefer filling bins deeper as stream advances
    score -= (item_size as f64 / cap) * 10.0 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
