        let class = (post_residual * 8) / bin_capacity; // 0..=7
        // Penalize small-but-unusable residuals (dead space classes 0..3),
        // reward larger, more reusable residuals (classes 4..7).
        match class {
            0 => score += 60.0,                    // 1..12 : nearly dead
            1 => score += 35.0,                    // 13..24
            2 => score += 20.0,                    // 25..36
            3 => score += 8.0,                     // 37..49
            4 => score -= 5.0,                     // 50..61 : half-bin reusable
            5 => score -= 10.0,                    // 62..74
            6 => score -= 15.0,                    // 75..87
            _ => score -= 20.0,                    // 88..99 : large residual
        }

        // Coupling: does next item fit into the post-residual? Big reward if yes.
        if next_item_size > 0 && next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits (harmonic match).
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 25.0 + 30.0 * snug;
        } else if next_item_size > 0 {
            // Next item won't fit: penalize proportionally to wasted potential.
            score += 10.0 * (frac);
        }

        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 40.0;
        }

        // New-bin candidate handling: opening a fresh bin is only attractive when
        // open bins are nearly full on average and many bins are open.
        if bin_residual == bin_capacity {
            // Base cost of a new bin, discounted when stream is early / bins crowded.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let crowding = (open_bins_count as f64 / 8.0).min(3.0);
            score += 55.0 - 20.0 * progress - 8.0 * crowding;
            if mean_residual < 15.0 {
                score -= 15.0; // open bins nearly exhausted -> new bin fine
            }
        } else {
            // Slight bonus for filling existing bins when they're above mean residual.
            if (bin_residual as f64) > mean_residual {
                score -= 6.0;
            }
        }

        // Modulo arithmetic on post_residual vs common item-size residues:
        // residuals congruent to typical sizes (multiples of 10) are more reusable.
        let r = post_residual % 10;
        if r == 0 {
            score -= 12.0;
        } else {
            score += (r as f64) * 0.8; // off-grid residuals slightly penalized
        }
    }

    // Mild preference for tight bins early (best-fit flavor) scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1)
    // can reasonably use are pure waste; penalize hard, especially tiny gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 40.0 * (10.0 - gap) / 10.0; // tiny unusable slivers
        } else if gap < 25.0 {
            score += 8.0 * (25.0 - gap) / 15.0;  // awkward small gaps
        }
    }

    // Reward very tight fits (near-perfect packing).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.9 {
        score -= 15.0 * (tightness - 0.9) / 0.1;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: attractive when open bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        let poor_fit = (bin_residual - item_size.min(bin_residual)) as f64 / bin_capacity as f64;
        score -= 5.0 + 6.0 * crowding + 20.0 * (1.0 - poor_fit);
        // If next item is small, keep current bins flexible; discourage new bin mildly.
        if next_item_size > 0 && next_item_size < 20 {
            score += 10.0;
        }
        // Early in the stream, opening bins is cheap and keeps options open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    } else {
        // Open-bin pressure: penalize spreading across many bins.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Two-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 2.5 * (post_residual - next_item_size) as f64;
        } else {
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items as f64;
    score += 0.5 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are great: reward small post_residual relative to item size.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        let tightness = post_residual as f64 / bin_residual as f64;
        score -= (1.0 - tightness) * 30.0;
    }

    // Penalize dead space: residuals too small for typical future items.
    let small_item = 1u32;
    if post_residual < small_item {
        score += 500.0;
    } else if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead coupling: if the next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            // wasted capacity if next item can't chain here
            score += 8.0;
        }
        // If next item fits EXACTLY, near-perfect chain
        if next_item_size == post_residual {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave a lot of unusable space.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = bin_capacity as f64 * 0.5;
        let pressure = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early in the stream, opening bins is cheap; later, prefer filling
        score -= (1.0 - progress) * 40.0;
        score += pressure * 2.0;
        // if current placement would leave a big awkward residual, new bin looks better
        if post_residual > 0 && post_residual < 20 {
            score -= 15.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size > bin_residual.saturating_sub(item_size) && next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: prefer bins with residual below the mean
    // (consolidate the fuller bins, keep loose bins for big future items).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Slight preference to fill bins with more items already (fewer touched bins).
    score += open_bins_count as f64 * 0.05;

    // Late-stream urgency: as the stream ends, waste matters less; tighten focus
    // on minimizing post_residual even harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_capacity as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: post residual, with non-linear shrink of the value of leftover space
    // as residual becomes small (dead space penalty grows super-linearly).
    let mut score = pr - 18.0 * (1.0 - fit_frac).powi(3) * cap * 0.01;

    // Smooth coupling of post_residual with stream progress:
    // early on, keep bins roomy; later, tolerate tighter fits.
    let progress_coupling = (1.0 - progress) * (fit_frac * (1.0 - fit_frac)).powi(2);
    score -= 12.0 * progress_coupling;

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-ish term).
    let tight = (item_size as f64 / cap).powi(2);
    score -= 8.0 * tight * (0.3 + 0.7 * progress);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving room for the next item (smooth kernel around next size).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        let kernel = (-6.0 * diff * diff).exp();
        score -= 9.0 * kernel * (1.0 - progress * 0.5);
    }

    // Mild pressure from mean residual: prefer bins deviating below mean residual
    // (use up the emptier bins first), smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * (1.0 - 0.5 * progress);

    // Penalize excessive open bins smoothly as stream progresses.
    score += 1.5 * (open_bins_count as f64).sqrt() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: reward residuals in "useful" classes.
    // Residuals that are multiples of common small item sizes stay usable.
    let pr = post_residual;
    let usable = (pr >= 10 && pr % 10 == 0)
        || (pr >= 20 && pr % 20 == 0)
        || (pr >= 25 && pr % 25 == 0)
        || (pr >= 50 && pr % 50 == 0);
    if usable {
        score -= 8.0;
    }

    // Dead space: small unusable residual (1..10) is wasted capacity.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mild bonus proportional to leftover after it
            let after_next = post_residual - next_item_size;
            score -= 4.0 + (after_next as f64) * 0.05;
        } else {
            // next item won't fit here; penalize leaving residual just below next size
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer an existing bin unless the new bin
    // offers a meaningfully better structural fit. Penalize the empty-bin
    // candidate mildly so it only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if mean residual across open bins is small (bins nearly full),
        // opening a new bin is good.
        if mean_residual < 20.0 {
            score -= 25.0;
        }
        // Late in the stream, consolidating matters less; slight new-bin boost.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 2.0;
    }

    // Prefer filling bins that are already low on space (tight fit preference
    // beyond raw post_residual): best-fit-like sharpening.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 5.0;

    // Many open bins: encourage closing them out (use existing space).
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // dead space that is too small for the smallest plausible item (<= 9)
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr);
        } else if pr < 20.0 {
            score += 25.0 * (20.0 - pr) / 10.0;
        }
        // reward near-perfect fits
        if pr <= 5.0 {
            score -= 40.0 * (6.0 - pr);
        }
    } else {
        // perfect fill
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff <= 10 {
            score -= 30.0 - diff as f64;
        } else {
            score -= 5.0;
        }
    }
    // Penalize if next item cannot use the leftover (dead space locked in)
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless fit is poor.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure; allow only when
        // existing fit would waste a lot.
        score += 25.0 + pressure;
        if post_residual == 0 { score -= 100.0; } // item fills a fresh bin exactly
    } else {
        score -= pressure.min(15.0);
    }

    // Progression: later in the stream, waste matters more (less chance to fix gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.3 * progress;

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (tight packing signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward near-perfect match of post_residual to next item ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is a jackpot: next item fills this bin perfectly.
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if gap <= 10.0 {
            score -= 30.0 * (1.0 - gap / 10.0);
        } else {
            // Penalize dead space that next item cannot use
            score += gap * 0.15;
        }
        // If next item could still fit here afterwards, mild bonus (keeps bin usable)
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: strongly prefer tightest fit (smallest post_residual)
        score *= 2.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- Compare residual against mean residual: prefer bins that are already well-filled ---
    let mean_diff = post_residual as f64 - mean_residual;
    score += mean_diff * 0.3;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, expensive late in the stream or when
        // a decent existing fit exists (many fitting bins).
        let open_penalty = 10.0 + 40.0 * progress;
        let crowding = if fitting_bins_count > 0 { (fitting_bins_count as f64).min(6.0) } else { 0.0 };
        score += open_penalty + crowding * 2.0;
        // A fresh bin is attractive if the item is large (would leave big dead space elsewhere)
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // --- Reward near-perfect fills generally ---
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Mild penalty for leaving awkward mid-range dead space
    if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squared post-residual penalty scaled by capacity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 2.5 * tight * tight * (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, heavily favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize leaving a residual that perfectly (or nearly) fits the next item
    // only if this bin is NOT the unique fit — otherwise that space is wasted anyway.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            // Leaving exactly the next item's size is good (chain packing).
            score -= 12.0 - 2.0 * gap;
        } else {
            // Leaving awkward medium-sized gap: mild penalty proportional to gap.
            score += 0.3 * gap;
        }
    }

    // Reward using bins whose residual deviates below the mean (consolidate small holes),
    // penalize dipping into bins with large residuals that could host bigger future items.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.5 * dev.min(20.0);
        } else {
            score += 0.25 * (-dev).min(30.0);
        }
    }

    // New-bin candidate logic: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin, relaxing as the stream fills with open bins.
        let reluctance = 15.0 + 0.8 * (open_bins_count as f64).sqrt() * 10.0;
        score += reluctance;
        // If item is large relative to typical residual, opening fresh is more attractive.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score -= 30.0 * large_item * large_item;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If next item is large too, a fresh bin pairs well with it later.
        if next_item_size > 0 {
            let nxt = (next_item_size as f64) / (bin_capacity as f64);
            score -= 15.0 * nxt * nxt;
        }
    }

    // Early stream: slight preference to spread items to build diverse residual pool.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual < bin_capacity {
        score += 5.0 * (1.0 - progress / 0.2);
    }

    // Encourage exact fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate slack.
    let poly = post_norm * post_norm * (1.0 - progress) * 8.0
             + post_norm * progress * 2.0;
    score += poly * cap;

    // Reward near-perfect fits smoothly via a gaussian-like term on post_residual.
    let tightness = (-post_norm * post_norm * 20.0).exp();
    score -= tightness * 12.0;

    // Penalize wasted potential relative to mean residual across open bins.
    score += 0.5 * (post - mean_residual).abs();

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let diff = (post as u32 as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (-(diff / cap) * (-(diff / cap))).exp();
        score -= match_bonus * 10.0;
    }

    // Slight penalty for proliferating open bins early in the stream.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "wasted" is the leftover space
    // in terms of the smallest useful item class (assume granularity ~10).
    let pr = post_residual as u32;
    let class = pr / 10; // integer-division threshold class 0..10
    // Dead-space penalty grows super-linearly for tiny unusable classes.
    score += match class {
        0 => 0.0,                      // perfect fit
        1 => 2.0,                      // only items <=10 fit
        2 => 1.0,
        3 => 0.5,
        4 => 0.2,
        _ => 0.0,
    };

    // Modulo-structure bonus: leftover that is a multiple of common item
    // sizes (10, 20, 25, 50) is reusable; reward it.
    if pr > 0 {
        if pr % 10 == 0 { score -= 1.5; }
        if pr % 20 == 0 { score -= 0.5; }
        if pr % 25 == 0 { score -= 0.5; }
        if pr % 50 == 0 { score -= 0.5; }
    }

    // Lookahead coupling: does the residual exactly or nearly fit next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as f64) >= nx {
            let slack = pr as f64 - nx;
            // Reward bins whose leftover can host the next item, especially
            // when slack is small (tight co-fit).
            score -= 3.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 4.0; } // perfect two-item pairing
            // Harmonic match: residual divisible by next item size
            if nx > 0.0 && (pr as u32) % (next_item_size) == 0 { score -= 2.0; }
        } else {
            // Next item cannot use this residual: mild penalty scaled by
            // how much space is stranded relative to next item.
            score += 1.0 + (nx - pr as f64) / cap;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: consumes future capacity.
        score = cap as f64 * 0.9 + post_residual as f64;
        // Early in stream, opening bins is cheap (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins are open and residuals are large, discourage new bin.
        score += open_bins_count as f64 * 0.8;
        // If next item would fit the new bin's leftover exactly, slight bonus.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 3.0;
        }
        // If existing fitting bins are scarce, new bin is more acceptable.
        if fitting_bins_count == 0 { score -= 10.0; }
    }

    // Prefer bins with residual below the mean (tighten crowded bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small but nonzero) are heavily penalized, since nothing in a
    // typical stream will ever fill them.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny gap = pure waste
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 100.0;
    }

    // Reward tight fits relative to the residual before placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Open-bin pressure: many open bins -> discourage spreading,
    // favor filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 2.0);
    score += 0.05 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly
    // prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fine fallback for
    // large items or when this bin would leave a bad gap, but should
    // lose against good fits in existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if post_residual > 0 && post_residual < 20 {
            // opening a fresh bin beats leaving a tiny dead gap
            score -= 45.0;
        }
        if item_size >= 60 {
            score -= 15.0; // big items start fresh bins happily
        }
        // mild penalty so decent existing fits still win
        score += 12.0;
        if open_bins_count < 3 {
            score -= 10.0; // early on, opening bins is cheap
        }
    }

    // Lookahead: if the next item fits the post-residual well, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = next_item_size as f64 / pr.max(1.0);
        score -= 15.0 * lookahead_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // gap won't serve the next item
    }

    // Slight preference for bins below mean residual (fill emptier ones
    // less; prefer tighter bins) — encourages consolidation.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the new residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover after that placement
            score -= 0.3 * next_item_size as f64;
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize bins whose residual is just below next size
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 0.8 * gap;
            }
        }
    }

    // Compare against mean residual: favor bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new one: strong bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist and lookahead suggests reuse
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 30.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Slight bias toward large item sizes filling large residuals
    score -= 0.1 * item_size as f64;

    // Late-stream tightening: prefer compact residuals as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize more when waste is large.
            score += 8.0 * (1.0 - fit_ratio);
        }
    }

    // Prefer bins below mean residual (more crowded bins get priority).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in stream, be picky (favor tight fits more);
    // late in stream, conserve bins (favor existing bins over new ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * fit_ratio;
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (1.0 - fit_ratio);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;

    // Base: normalized post residual, with non-linear penalty on dead space.
    let mut score = pr / cap;

    // Smooth quadratic/quartic coupling of post residual with stream progress:
    // early on tolerate slack, late in stream punish it strongly.
    let slack_penalty = (pr / cap).powi(2) * (0.5 + 2.0 * progress) + (pr / cap).powi(4) * progress;
    score += slack_penalty * cap * 0.05;

    // Reward tight fits (small post residual) more than linearly via inverse term.
    if post_residual > 0 {
        score -= 0.3 * (cap / pr).min(10.0) / cap;
    } else {
        score -= 2.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.5 + progress;
    } else {
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // New empty bin candidate: penalize opening a new bin, more so early and
    // when existing bins have plenty of usable residual space.
    if bin_residual == bin_capacity {
        score += 2.0 + 1.0 * (1.0 - progress) + 0.5 * (mean_residual / cap).min(2.0);
        // But if next item would also fit nicely in a fresh bin, soften slightly.
        if next_item_size as f64 >= cap * 0.5 {
            score -= 0.4;
        }
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 0.6 * (1.0 - (next_item_size as f64 / cap)) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot fit next item: mild penalty growing with progress.
        score += 0.3 * progress;
    }

    // Mild preference for consolidating among many open bins.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: bins whose residual lands on "usable" classes
    // (multiples of common item sizes) are more valuable to keep clean.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill: strongly reward
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr <= 9 {
        25.0 // tiny dead space: penalize heavily
    } else {
        0.0
    };
    score += class_bonus;

    // Tightness coupling: reward near-perfect fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item
            if post_residual < next_item_size && post_residual > 0 {
                score += 0.35 * post_residual as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large relative to capacity or existing fits are poor.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0 + 25.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += base_penalty * scarcity;
        // late in the stream, prefer consolidation into open bins
        score += 20.0 * progress;
    }

    // Mild pressure against proliferating many open bins with slack.
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Harmonic modulo threshold on item_size classes: prefer placing large items early.
    let size_class = item_size / 20;
    score -= 2.0 * size_class as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are pure waste.
    // Treat residual gaps below the smallest realistic item threshold as doubly costly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Non-linear penalty on moderately small gaps (hard to fill later).
    if post_residual > 0 && post_residual <= 30 {
        score += (30.0 - post_residual as f64) * 0.6;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // Gap becomes dead space for the known next item.
            score += (post_residual as f64) * 0.8;
        } else {
            // Partially usable gap: mild reward proportional to how well next item fills it.
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= fill * 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.35 * (1.0 - progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (post_residual as f64).min(20.0);
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only
    // when the placement here would create large dead space relative to mean residual.
    if bin_residual == bin_capacity {
        // Baseline neutral score: slightly above a good fit, below a bad fit.
        score = bin_capacity as f64 * 0.5;
        // If mean residual across open bins is large, prefer reusing open bins.
        score += mean_residual * 0.5;
        // If this bin would be the last chance and fit is decent, opening new bin is bad.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // Late in the stream, avoid opening new bins.
        score += progress * 15.0;
        // If next item is large, a fresh bin may still be valuable.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with residual close to item (best-fit core).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect two-step closure: item exactly fills bin after next item.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: reward closeness, penalize leftover dead space beyond it.
            let post2 = post_residual - next_item_size;
            score -= 20.0 + (post2 as f64).min(40.0);
            if post2 == 0 {
                score -= 25.0; // exact two-item closure
            }
        } else {
            // Next item would NOT fit in the residual: penalize if we leave a large unusable gap.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.6;
        }
        // Reward residuals that are close to next_item_size in general (soft matching).
        score -= 10.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
    }

    // Compare residual against mean residual of open bins.
    let dev = post_residual as f64 - mean_residual;
    // Prefer bins whose post residual deviates from mean in a way that reduces fragmentation:
    // low post residual (tight fit) is good; high post residual (loose fit) is bad.
    score += 0.35 * dev;

    // Tightness reward: minimal dead space after placement.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Discourage opening a new bin when existing bins can still take the item well,
    // but encourage a new bin when the fit would create large dead space.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        score += 12.0;
        // If item is large relative to capacity, a new bin is fine (keeps big items paired).
        if item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 8.0;
        }
        // If many bins are open with slack, prefer filling them instead.
        score += 0.5 * open_bins_count as f64;
    }

    // Early in the stream, be slightly more willing to open bins (build diverse residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * (1.0 - progress);

    // Keep score bounded sensibly.
    score.max(0.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // General tightness reward: bigger items into bins is good (less fragmentation)
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    if !is_new_bin {
        // Favor reusing existing bins over opening new ones
        score -= 4.0 + 0.4 * open_bins_count as f64;

        // Perfect / near-perfect fits are gold
        if post_residual == 0 {
            score -= 15.0;
        } else if post_residual < 10 {
            score -= 5.0;
        }

        // Last-chance bin: if this is the only bin that fits, use it
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Lookahead coupling: reward leaving a gap the next item can fill
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 3.0;
            } else {
                score += (next_item_size as f64 - post_residual as f64) * 0.05;
            }
        }

        // Dead-space penalty scaled by stream progress: late in the stream,
        // unusable slivers are more costly
        score += (post_residual as f64 / bin_capacity as f64) * t * 6.0;
    } else {
        // New-bin candidate: penalize when existing bins already have room
        score += 6.0;
        if fitting_bins_count > 0 {
            score += (mean_residual - item_size as f64).max(0.0) * 0.3;
        }
        // Slightly favor opening fresh bins for large items (they need space)
        score -= item_size as f64 * 0.05;
        // Late in the stream, opening a new bin is cheaper than fragmentation
        score -= t * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;
    let mean_r = mean_residual.max(0.0);
    let nxt = next_item_size as f64;

    // Base: prefer small post-residual, with quadratic sharpening of tight fits.
    let mut score = pr * (1.0 + 1.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, tolerate larger residuals less (tighten packing).
    let progress_coupling = pr_norm * (0.6 + 2.4 * progress * progress);
    score += progress_coupling * cap * 0.35;

    // Smooth penalty for leaving a residual that next item cannot use
    // (smooth logistic-like coupling instead of hard threshold).
    if nxt > 0.0 {
        let usable = (nxt / (pr + 1.0)).min(1.0);
        let unusable = 1.0 - usable;
        score += unusable * unusable * nxt * 0.5;
        // Reward when this bin's post-residual matches next item nicely.
        score -= (1.0 - ((nxt - pr).abs() / cap)) * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else {
        // Mild scarcity pressure as fitting bins dwindle (smooth inverse).
        score -= 2.0 / (fit * fit);
    }

    // Prefer filling bins whose residual deviates from mean (consolidate slack),
    // smoothly weighted by number of open bins.
    let dev = (bin_residual as f64 - mean_r) / cap;
    score += dev * dev * (1.0 + open * 0.05) * 1.5;

    // Slight preference for keeping bin count low early (spread items),
    // stronger preference for consolidation late.
    score += (1.0 - progress) * 0.8 - progress * (pr_norm * 3.0);

    // New-bin candidate: make empty bin attractive only when residuals are bad.
    if bin_residual == bin_capacity {
        let slack_pressure = (mean_r / cap).max(0.0);
        score = cap * (0.55 + 0.45 * slack_pressure) + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover decomposes into
    // useful residue classes of typical item sizes (small items 1..20 common).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity utilization: reward tight fills.
    let fill = 1.0 - pr / cap;
    score -= 40.0 * fill * fill;

    // Harmonic class: post_residual mod small divisors -> dead-space detection.
    let h3 = post_residual % 3;
    let h5 = post_residual % 5;
    let h10 = post_residual % 10;
    let harmonic_bonus = ((h3 == 0) as i32 as f64) * 4.0
        + ((h5 == 0) as i32 as f64) * 6.0
        + ((h10 == 0) as i32 as f64) * 5.0;
    score -= harmonic_bonus;

    // Integer-division threshold: leftover divisible into chunks of common sizes.
    for chunk in [10u32, 15, 20, 25, 30, 40, 50] {
        if post_residual >= chunk && post_residual % chunk == 0 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: does post_residual exactly host next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            // harmonic class of slack after next item
            if slack as u32 % 10 == 0 { score -= 6.0; }
        } else {
            // next item cannot fit here: penalize wasting large residual
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is
    // very small (tight fit) or many bins are open and this is a big item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = item_size as f64; // dead space left in fresh bin
        score += 55.0 - 20.0 * progress - 0.25 * item_size as f64
            + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual across open bins is large, opening new bin is wasteful
        score += 0.3 * mean_residual;
        let _ = waste;
    }

    // Prefer bins whose residual is close to the item (perfect harmonic match).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 30.0 * gap * gap;

    // Slight preference for bins below mean residual (consolidating fuller bins).
    score += 0.1 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to be useful for
    // typical upcoming items are heavily penalized (nonlinearly).
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward when the NEXT item exactly fills the post residual (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    }
    // Penalize if next item cannot fit into post residual but would fit elsewhere
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    // Tightness coupling: prefer bins where the item consumes a large share
    // of the residual (best-fit style, amplified).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets a large base score,
    // so add pressure that scales with open bins to keep it suppressed.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64).sqrt() * 15.0;
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (i.e., tighter bins) to consolidate space.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late-stream consolidation: as the stream progresses, avoid new bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    let perfect_bonus = if post_residual == 0 {
        -1000.0
    } else if post_residual <= 5 {
        -300.0
    } else if post_residual <= 15 {
        -80.0
    } else {
        0.0
    };
    score += perfect_bonus;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chaining
        } else if next_item_size < post_residual {
            // next item fits too: penalize proportional to leftover slack created
            let slack = post_residual - next_item_size;
            score -= 120.0 - (slack as f64).min(120.0);
            if slack <= 5 {
                score -= 150.0;
            }
        } else {
            // next item does NOT fit: post_residual is a trap for the lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 60.0 + 0.5 * gap;
        }
    }

    // Penalize large residual relative to mean residual (wasting a roomy bin on a poor fit).
    score += 0.6 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit = (bin_residual - item_size) as f64;
        // Default penalty so open bins win; relax when few bins fit the item.
        let mut new_bin_penalty = 180.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = -50.0;
        } else if fitting_bins_count == 1 {
            new_bin_penalty = 60.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 100.0 * progress;
        score += new_bin_penalty - 0.1 * decent_fit;
    }

    // Mild pressure against accumulating many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            score -= 6.0; // lookahead item can also use this bin later
        }
        // Perfect pair: item + next fill bin almost exactly
        let pair_waste = (bin_residual as i64 - item_size as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 10.0 * (-pair_waste / 8.0).exp();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when few fit.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Prefer bins below mean residual (keep some bins fat for future items).
    score += 0.08 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * desperation + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // big item + big next item -> fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer small post-residual (tight fit), non-linearly shaped.
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Smooth stream-progress coupling: later in stream, punish waste harder.
    let progress = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 25.0 * progress * (pr / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + 0.5 * t);
    } else {
        // mild penalty proportional to number of alternatives
        score += 3.0 * (fit - 1.0).ln_1p();
    }

    // Dead-space term: residuals too small for typical items are wasted.
    let dead = if next_item_size > 0 {
        (post_residual < next_item_size) as f64
    } else {
        0.0
    };
    score += 18.0 * dead * (1.0 + 0.6 * t);

    // Lookahead synergy: reward leaving room close to next item size.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 20.0).exp() * (1.0 - t * 0.5);
    }

    // Congestion: many open bins with high mean residual -> prefer tightening them.
    let congestion = (open / (open + 5.0)) * (mean_residual / cap);
    score -= 15.0 * congestion * (pr / cap);

    // New-bin candidate: empty bin gets a moderate penalty unless residuals are bad.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        score += 30.0 - 25.0 * pressure * (1.0 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity fractions.
    let post = post_residual;
    let q10 = (post / 10) as f64;                 // coarse class
    let r10 = (post % 10) as f64;                // fine remainder
    let r25 = (post % 25) as f64;                // quarter-class remainder
    let r50 = (post % 50) as f64;                // half-class remainder

    // Reward residuals near "useful" sizes (small or perfectly fillable later).
    // Dead space penalty: mid residuals are bad, but residuals that are multiples
    // of common item sizes are more likely to be filled exactly later.
    let fillable = (post % 10 == 0) as f64 * 4.0
        + (post % 20 == 0) as f64 * 3.0
        + (post % 25 == 0) as f64 * 2.0
        + (post % 50 == 0) as f64 * 2.0;
    score -= fillable;

    // Non-linear dead-space curve: penalize residuals in 20..=45 most.
    let frac = post as f64 / cap;
    let dead = (frac * std::f64::consts::PI).sin().abs(); // peaks mid-range
    score += dead * 12.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let leftover = post - next_item_size;
            // reward only if leftover is small or harmonically fillable
            if leftover <= 10 {
                score -= 12.0 - leftover as f64;
            } else if leftover % 10 == 0 {
                score -= 6.0;
            } else {
                score += 4.0; // poor two-step fit
            }
        } else {
            // next item cannot use this residual at all
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Tight fit reward: very small post residual is excellent.
    if post <= 5 {
        score -= 15.0;
    }

    // Prefer keeping mean residual low: placing into a below-mean bin
    // balances the open-bin pool, but only mildly.
    let dev = mean_residual - post as f64;
    score += 0.15 * dev;

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: acceptable early, expensive late
        score -= 8.0 * (1.0 - progress);
        score += 25.0 * progress;
        // but if nothing else fits well (high mean residual), a fresh bin is fine
        if mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Mild penalty for scattering across many open bins with big residuals.
    score += 0.05 * open_bins_count as f64 * q10 * 0.1;

    // Fine-class tiebreaker on remainder to break ties deterministically.
    score -= 0.01 * r10 + 0.005 * r25 + 0.002 * r50;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    // Penalize post_residual that is too small to ever be useful again.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            // Unusable sliver: hard dead space.
            score += 25.0 * (10.0 - pr);
        } else if pr < 20.0 {
            // Marginal gap: only fits the smallest items.
            score += 6.0 * (20.0 - pr);
        }
        // Reward near-perfect fits nonlinearly.
        if pr <= 5.0 {
            score -= 40.0;
        } else if pr <= 12.0 {
            score -= 15.0;
        }
    } else {
        // Perfect fill: best possible outcome.
        score -= 60.0;
    }

    // Reward residual tightness relative to item size (waste ratio view).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits the post-residual exactly or well,
    // chaining here is valuable; if not, prefer bins that keep flexibility.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && pr - nxt <= 5.0 {
            score -= 18.0; // perfect chain
        } else if pr >= nxt {
            score -= 6.0;  // next item still fits
        } else if pr > 0.0 && pr < nxt && pr < 10.0 {
            score += 10.0; // chain impossible, gap becomes dead
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if pr > 40.0 {
            score += 20.0; // terrible fit, soften the preference
        }
    }

    // Open-bins pressure: discourage fragmenting across many open bins;
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    // New-bin candidate has bin_residual == bin_capacity: penalize it more
    // as open bin count and stream progress grow.
    if bin_residual == bin_capacity {
        score += 35.0 + 8.0 * bin_pressure + 20.0 * progress;
        // Exception: if open bins can't absorb the item well, allow a new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Slight bonus for using existing bins when many are open.
        score -= 2.0 * bin_pressure;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (drain the tightest bins first, keep roomy bins flexible).
    let res = bin_residual as f64;
    if mean_residual > 0.0 && res < mean_residual {
        score -= 5.0 * (1.0 - res / mean_residual);
    } else if mean_residual > 0.0 {
        score += 3.0 * (res / mean_residual - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits with small slack -> moderate reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in the leftover -> penalize dead space, scaled by how close it was.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 40.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Mild pressure against opening new bins when many bins are already open.
    score += 2.0 * open_bins_count as f64;

    // Slight time-based tightening: later in the stream, prefer compacting.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalize post-residual and item size
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = post_norm * post_norm;
    let cubic = quad * post_norm;
    let progress_term = progress * progress * (1.0 - progress);

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = post
        - 18.0 * cubic * (1.0 + progress)
        + 12.0 * quad * progress_term * 4.0;

    // Penalize dead space relative to mean residual across open bins
    score += 0.35 * (post_norm - mean_residual / cap).abs() * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Lookahead: reward if next item fits well into the post-residual
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let gap = post_norm - next_norm;
        if gap >= 0.0 {
            score -= 10.0 * gap * (1.0 - gap);
        } else {
            score += 6.0 * (-gap);
        }
    }

    // Slight penalty for opening new bins when many bins are open late in stream
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) - 0.5 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: reward residuals that form "nice" fractions
    // of capacity (dead space in good classes is more reusable later).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class the residual into capacity-fraction bands.
    // Exact-zero residual is perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Small residuals (< 10) are dead space for items >= 10: penalize.
        if post_residual < 10 {
            score += 25.0;
        } else {
            // Reward residuals in "usable" bands: 10..=33 (can host small items),
            // 34..=50 (half-bin class), 51..=100 (large class).
            if post_residual <= 33 {
                score -= 8.0;
            } else if post_residual <= 50 {
                score -= 14.0;
            }
            // Modulo classes: residuals divisible by common item sizes are
            // more likely to be exactly filled later.
            let m = post_residual % 10;
            if m == 0 {
                score -= 6.0;
            } else if m >= 7 {
                score += 4.0;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: slight penalty proportional
            // to how "wasted" the leftover class is.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer tighter bins generally: closeness of fit reward.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 10.0 * tightness;

    // Slight preference for existing bins over opening new ones as stream
    // progresses (packing consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, and when
        // many bins are already open.
        score += 15.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "dying" bin; prefer filling it.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 5.0 * (dev / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item (min size 1,
    // but treat gaps < 12 as near-dead since items are typically >= 10).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64) / 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual (best-fit flavor).
    if bin_residual > 0 {
        score -= 15.0 * (item_size as f64 / bin_residual as f64);
    }

    // Lookahead: if next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // gap blocks the known next item
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight packs;
    // few open bins -> slightly favor new-bin usage when fits are poor.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when current fit is bad (large post_residual
    // relative to item) or mean residual is low.
    if bin_residual == bin_capacity {
        score += 5.0; // mild default penalty to prefer existing bins
        score -= 20.0 * (1.0 - (item_size as f64 / bin_capacity as f64));
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further slack; penalize proportional slack
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use remaining space; penalize dead space
            score += post_residual as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 150.0;
        // If lookahead matches perfectly in a fresh bin, still allow it
        if next_item_size == bin_capacity - item_size {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 + progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that can never be used by the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still host the next item after this placement.
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit would be very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / (bin_capacity as f64);
        // Open a new bin when existing residuals are small (crowded) and fit is loose.
        let open_bonus = 30.0 * crowding + 20.0 * (1.0 - progress);
        score = (post_residual as f64) + open_bonus - 10.0 * tightness;
        // If many bins fit, discourage opening a new one.
        score += 8.0 * fitting_bins_count as f64;
    } else {
        // Mild preference for filling bins that are already mostly full.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 15.0 * fill;
        // Slight penalty for spreading across too many bins.
        score += 0.3 * open_bins_count as f64;
    }

    // Time horizon: late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly compressed by smooth polynomial coupling with progress
    let mut score = pr;

    // Smooth polynomial interaction: post-residual weighted by progress
    let poly = 1.0 + 0.8 * progress - 0.6 * progress * progress;
    score += poly * 30.0 * norm_pr * norm_pr * cap * 0.01;

    // Tight fits rewarded more as stream progresses (smooth quadratic in norm_pr)
    score -= 25.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post residual fits next item, scaled by progress
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (0.5 + progress);
    }

    // Last-chance bin: penalize skipping it smoothly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins near mean residual (smooth quadratic)
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * diff * diff * cap * 0.1;

    // New-bin candidate: penalize opening new bins early, less late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "usable" leftover classes.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Class by integer division thresholds on post_residual.
        let pr = post_residual;
        if pr <= 10 {
            score -= 40.0; // near-perfect fit, small dead space
        } else if pr <= 25 {
            score -= 15.0; // still usable for typical small items
        } else if pr <= 50 {
            score += 5.0; // mediocre leftover
        } else {
            score += 20.0; // large leftover: wasteful placement
        }
        // Harmonic (modulo) refinement: leftover that is a multiple of 10
        // tends to match item granularity of common distributions.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportional to tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - tight * 0.3;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // We broke a slot that could have served the next item.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish, penalized late in the stream
    // or when few bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 20.0 * (1.0 - progress);
        if open_bins_count <= 2 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // reserve fresh bin for big next item
        }
    }

    // Slight preference for tighter bins overall (best-fit bias).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
