pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward bins whose post_residual
    // exactly fits the next item (chain two items perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item fits too: penalize leftover after the pair placement.
            let pair_leftover = (post_residual - next_item_size) as f64;
            score -= 0.5 * pair_leftover;
            if pair_leftover < 10.0 {
                score -= 50.0;
            }
        } else {
            // Next item won't fit here: penalize small unusable dead space.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 30.0 + gap as f64;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 0.3 * post_residual as f64;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when many bins are open,
    // unless the stream is early and consolidation is hopeless.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 50.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin can chain with next item if item is small.
            if item_size + next_item_size as u32 <= bin_capacity {
                score -= 70.0;
            }
        }
    }

    // Late in the stream, push toward closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness: reward placements that leave small but usable residue
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 120.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to smallest plausible item (1..100 unknown dist)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable slivers
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 80.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 40.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Many open bins: prefer filling existing ones over spreading
    let openness = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += 15.0 * openness.min(50.0);

    // Global residual pressure: if mean residual is low, conserve big-residual bins
    let big_bin = bin_residual as f64 > mean_residual * 1.3;
    if big_bin {
        score += 30.0;
    } else {
        score -= 10.0;
    }

    // Time horizon: early in stream, be flexible (penalize extreme fills slightly less late)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 100.0 * fit_ratio * progress;

    // New-bin candidate: make it only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 150.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post-residual, damped by a smooth polynomial in progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear coupling: quadratic post-residual term that grows with progress,
    // penalizing large dead space late in the stream.
    score += 0.004 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 8.0 * (1.0 - pr / cap) * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64) / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item.
        score += 4.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: make it mildly unattractive unless residuals are poor,
    // with smooth dependence on mean residual and progress.
    if bin_residual == bin_capacity {
        let mean_ratio = mean_residual / cap;
        score += 6.0 - 10.0 * mean_ratio * (1.0 - progress);
        score += 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes partition dead space quality
    let pr = post_residual;
    let class = pr % 10;
    // Penalize awkward classes that rarely admit items (items 1..100, but residual
    // fragments in 1..10 are the least reusable).
    if pr > 0 {
        match class {
            0 => score -= 6.0,               // perfectly aligned decade, very reusable
            5 => score -= 2.0,               // half-decade, moderately reusable
            1 | 2 | 3 => score += 8.0,       // sliver dead space
            4 | 6 => score += 3.0,
            _ => {}
        }
    }

    // Integer-division threshold: post_residual in the "danger zone" below the
    // smallest useful chunk is nearly dead space.
    if pr < 10 && pr > 0 {
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Great: chain placement possible; reward proportional to tightness
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 0.1 * slack;
            // Harmonic bonus when next item exactly fills a class boundary
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit: this residual becomes dead space for lookahead
            score += 6.0 + 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only good when the item is large relative to
        // capacity or open bins are already fragmented (high mean residual is fine,
        // low mean residual means open bins are full-ish).
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        if fill_fraction > 0.6 || mean_residual < 15.0 {
            score -= 8.0;
        } else {
            // discourage opening bins for small items when fragmentation is low
            score += 10.0 + 20.0 * (0.6 - fill_fraction);
        }
    }

    // Progression coupling: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins tighter than the mean (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Perfect fit for the lookahead item: strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // lookahead item cannot use this bin's remainder
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: more open bins => prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it costly unless current bin would leave big waste.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * -1.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild tie-break: prefer bins with low residual relative to mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) — already base term.

    // 2-step lookahead: strongly reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 0.5 {
            score -= 25.0; // perfect 2-chain: next item exactly fills remainder
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else {
            // next item cannot use the remainder: penalize dead space proportionally
            let waste = post_residual as f64 - (bin_capacity as f64 - next).min(post_residual as f64);
            score += 0.5 * waste;
        }
    } else {
        // last item: only tightness matters
        score -= 5.0;
    }

    // Compare against mean residual: prefer bins whose post-residual tracks the mean
    // (keeps open bins homogeneous and combinable for future items).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fitting bins exist and item is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).sqrt();
        score += 8.0 + 3.0 * pressure + 5.0 * (1.0 - progress);
        // but if item is huge relative to capacity, new bin is fine
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Mild reward for large fills (using more of the bin now).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good, but dead space
    // that can't fit typical items (<= post_residual) is wasted.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 60.0;

    // Penalize bins whose post-residual is awkwardly small (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the
    // current fit is very loose or lookahead demands it.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;

        // If the item fits perfectly, opening a new bin is great.
        if post_residual == 0 {
            score -= 120.0;
        }

        // If many bins already fit the item, prefer using one of them.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0);
        }

        // Lookahead: if the next item would combine with the leftover space,
        // opening a new bin with a large residual is attractive.
        if next_item_size > 0 {
            let combo = next_item_size as f64 + item_size as f64;
            if combo <= bin_capacity as f64 {
                score -= 35.0;
            }
            // If next item is huge and current fit is loose, prefer a fresh bin.
            if next_item_size > post_residual && post_residual > 0 {
                score -= 10.0;
            }
        }

        // Early in the stream, opening bins builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins below the mean residual (keeps residuals balanced, saves
    // larger residuals for larger future items).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // Lookahead pairing: reward placements leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving a gap too small for the next item.
        score += 12.0;
    }

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Mild penalty for many open bins (encourages consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth non-linear coupling: waste penalty grows superlinearly for tiny residuals,
    // but tapers as stream progresses (late dead space matters less than early).
    let norm_post = post / cap;
    let dead_penalty = (norm_post * norm_post) * (1.0 - norm_post) * 60.0;
    score -= dead_penalty * (1.0 - 0.5 * progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * tightness * 25.0;

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic match).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64) / cap;
        score += gap * gap * 40.0;
        if post >= next_item_size as f64 {
            score -= 8.0;
        }
    }

    // Prefer fuller bins relative to the fleet average (smooth interaction).
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 15.0 - dev * 10.0;

    // Mild new-bin aversion that decays with progress and crowding.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
        score += 30.0 * (1.0 - progress) * (1.0 - crowd) + 10.0 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny post-residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class: residual mod 10 — residuals that are "friendly"
    // (multiples of 10) are easier to fill with common item sizes.
    let rmod = post_residual % 10;
    if rmod == 0 {
        score -= 15.0;
    } else if rmod <= 2 {
        score += 10.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer tighter bins when many bins are open.
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin fits well (post_residual small means good fit elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing potential in fresh bin
        }
    }

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap too small for any item (min size 1..100 assumption: gap < 10 rarely reusable)
        score += (10.0 - pr) * 8.0;
    } else if pr == 0.0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits generally (small post_residual relative to capacity)
    score -= (1.0 - pr / bin_capacity as f64) * 20.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins already open
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to open bins count
        score += open_bins_count as f64 * 6.0;
        // still allow opening if existing bins would waste a lot (dead space elsewhere)
        if pr == 0.0 {
            score -= 30.0;
        }
    } else {
        // using an existing bin relieves pressure slightly
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as i64) == (next_item_size as i64) {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins first)
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 15.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit: reward tight fits (low post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: perfect bonus if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64;
        let slack = (post_residual as f64 - next_fit) / bin_capacity as f64;
        score -= 6.0 * (1.0 - slack); // strong reward for exact/chained fits
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item could have fit here anyway; mild penalty for wasting the chance
        score += 1.0;
    }

    // Penalize dead space below the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Compare against mean residual across open bins
    let mean = mean_residual;
    if (bin_residual as f64) < mean {
        score -= 1.5; // prefer fuller-than-average bins
    } else {
        score += 1.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 12.0;
        // allow new bin if the item would leave a large hole in an existing bin
        if post_residual > 40 && fitting_bins_count > 0 {
            score -= 15.0;
        }
        // early stream: allow spreading out
        if (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: post residual that is too small to hold even a
    // typical small item is wasted, unless it is exactly zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // fits poorly everywhere else or the open bins are already crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 30.0 - 12.0 * progress - 2.0 * crowd;
        // If the next item is large, an empty bin gives flexibility.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Prefer filling bins that are already relatively full compared to the mean.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
    if fullness > mean_fullness {
        score -= 8.0 * (fullness - mean_fullness);
    } else {
        score += 4.0 * (mean_fullness - fullness);
    }

    // Late in the stream, consolidate aggressively to avoid opening extra bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty on large residuals, modulated by stream progress:
    // early on, waste matters less; late, tight packing is rewarded.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr.powi(3) * (1.0 - progress);
    score += 2.0 * cap * poly;

    // Lookahead coupling: bonus if next item fits into the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // dead space that cannot host the next item, worse later in the stream
        score += 3.0 * progress * (1.0 - (pr / cap));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean residual coupling: bins with residual far below mean are tighter fits.
    score -= 1.5 * (mean_residual - pr).tanh();

    // New-bin candidate: make empty bins mildly unattractive unless residuals are bad.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 4.0 - 3.0 * pressure * pressure + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of 10 are "usable"
    let r = post_residual % 10;
    let harmonic_bonus = if r == 0 { 12.0 } else if r <= 2 { 6.0 } else if r >= 8 { 2.0 } else { 0.0 };
    score -= harmonic_bonus;

    // Dead-space penalty: small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: reward if next item can fit in the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64) * 0.1;
        } else {
            // penalize leaving residual that neither fits next item nor is tiny
            if post_residual >= 10 {
                score += 3.0;
            }
        }
        // Harmonic coupling: next item size class vs post residual class
        if post_residual % 20 == next_item_size % 20 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (mean_residual as u32) as f64).abs();
        if fitting_bins_count == 0 || mean_residual < 15.0 {
            score -= 20.0; // open new bin when open bins are nearly full
        } else {
            score += 8.0 + fragmentation * 2.0;
        }
    }

    // Progression-aware tightness: later in stream, prefer tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.05;

    // Prefer bins already below mean residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill, ideal
    } else if post_residual <= 10 {
        // gap too small for any realistic item -> dead space penalty
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 30 {
        // moderately risky gap
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual relative to bin capacity)
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 3.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new empty bin candidate has post_residual = capacity, so it naturally
    // scores high; add extra pressure proportional to open bins).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.5 + 15.0;
    } else {
        score -= 5.0; // prefer using existing bins
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next <= 5 {
            score -= 12.0; // chains a near-perfect follow-up
        } else {
            score -= 4.0;
        }
    }

    // Stream progression: early on, be more willing to open bins for good fits;
    // late in the stream, close out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5; // tighten at the end
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item fits perfectly after this placement
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space
            score += 5.0 + gap * 0.3;
        }
        // Perfect chain: post_residual == next_item_size exactly
        if gap < 0.5 {
            score -= 25.0;
        }
    } else {
        // Last item: minimize waste directly
        score += 10.0;
    }

    // Compare against mean residual: prefer bins already fragmented below average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * progress;
        // allow new bin if lookahead suggests large next item
        if next_item_size > item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for large leftover dead space that can't hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: small but nonzero post_residual that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot follow here; mild penalty proportional to how far off.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins that are already more filled than average (best-fit-like consolidation).
    if bin_residual < bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
        score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // New-bin candidate handling: an empty bin is a fresh resource; penalize opening it
    // unless the item is large or the stream is early and few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 30.0
            - 25.0 * progress
            - 0.05 * open_bins_count as f64
            - 0.2 * item_size as f64;
        score += new_bin_penalty.max(-10.0);
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (0..1)
    let progress = (step_index as f64) / (total_items as f64).max(1.0);

    // Normalized post-residual and item size
    let pr = (post_residual as f64) / (bin_capacity as f64);
    let it = (item_size as f64) / (bin_capacity as f64);

    // Smooth non-linear coupling: quadratic in post-residual modulated by progress.
    // Early in the stream, tight fits matter less; later, minimizing post_residual dominates.
    score += pr * pr * (0.5 + 2.0 * progress) * (bin_capacity as f64);

    // Cubic interaction between item size and progress: big items early are fine,
    // big items late should prefer tight bins more strongly.
    score -= it * it * it * (10.0 + 40.0 * progress);

    // Reward near-perfect fits smoothly (post_residual close to 0).
    let tightness = 1.0 - pr;
    score -= tightness * tightness * (5.0 + 15.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 20.0 * progress;
    } else {
        // Smooth penalty when many bins compete: prefer bins with smaller residual.
        let fc = fitting_bins_count as f64;
        score += 2.0 * (1.0 - 1.0 / (1.0 + fc));
    }

    // Penalize bins whose residual is far above the mean (fragmented bins),
    // with a smooth saturating term.
    let dev = ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    score += dev * dev * 8.0 * (1.0 - progress);

    // Lookahead: if next item could exactly fill post_residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = ((post_residual as i64) - (next_item_size as i64)).abs() as f64;
        score -= (1.0 - gap / (bin_capacity as f64)) * 6.0 * nx / (bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin smoothly, unless item is huge
    // (would leave very little residual anyway) or late in the stream.
    if bin_residual == bin_capacity {
        let huge = it > 0.8;
        let urgency = progress * progress;
        let penalty = 15.0 * (1.0 - urgency) * (1.0 - if huge { 1.0 } else { 0.0 });
        score += penalty;
        // New bin has perfect future flexibility: small smooth discount.
        score -= 3.0 * (1.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small post_residual that nothing can use (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic class of post_residual: bins whose residual falls in
    // "reusable" classes (multiples of 10, 20, 25, 50) are attractive.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 25 == 0 {
        score -= 8.0;
    }
    if pr % 50 == 0 {
        score -= 8.0;
    }
    // Odd/awkward classes are mildly penalized.
    if pr % 2 == 1 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this is a chaining opportunity - reward it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item can't use this residual: residual becomes dead weight
            score += pr as f64 * 0.15;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): prefer it only when post_residual would
    // be large (i.e., item is small relative to capacity) or no good fits exist.
    if bin_residual == bin_capacity {
        // Base bias so a new bin is usually worse than a decent fit...
        score += 25.0;
        // ...but a fresh bin gives full flexibility for future items.
        score -= open_bins_count as f64 * 0.5;
        // If the item leaves a very large residual, new bin is fine.
        if post_residual >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Prefer fuller bins overall: compare residual to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Prefer bins with smaller pre-residual (tighter fits) slightly.
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let min_item = 1u32;
    let dead_threshold = 10u32; // below typical minimum item size, residual is near-dead
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Penalize residuals too small for the lookahead item (wasted for next step)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward perfect or tight fits
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio;
    }

    // Open-bin pressure: discourage spreading into many bins when few fit options remain
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0; // last-chance bin: strongly prefer using it
    }
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make empty bin moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Mild progression scaling: later in stream, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 120.0 - (slack as f64) * 6.0;
        } else {
            // Next item fits but leaves moderate waste; small reward.
            score -= 30.0 - (slack as f64) * 0.5;
        }
    }
    // Next item will NOT fit in the resulting residual: penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        score += (gap as f64) * 0.8;
        // Dead space: residual too small to ever be useful for typical items.
        if post_residual < 10 {
            score += 60.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins with residual close to the item (tight fits) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Prefer bins below mean residual (fill emptier bins less, keep large residuals flexible).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Early in stream: keep flexibility by penalizing very low post_residual slightly less
    // late in stream: consolidate, reward tight packing more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    // New bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 80.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits into the post residual (chained packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < 10 {
            score -= 10.0; // small dead space is tolerable
        } else {
            // dead space that likely can't fit typical future items
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // mild penalty when many alternatives exist, push toward tightest fit
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins whose residual deviates favorably from mean (tighter bins first)
    score += 0.2 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64);

    // Early in stream: encourage opening/spreading bins slightly less aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: only attractive if it would leave a large usable residual
        // relative to typical item sizes, or late in the stream with many open bins
        let new_bin_bonus = 30.0
            - 0.15 * post_residual as f64      // fresh bin has big residual; slight penalty keeps it from dominating
            + 40.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        score += new_bin_bonus;
        // If next item is huge, a fresh bin is fine to absorb it later
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Encourage keeping residual above common small-item thresholds
    for threshold in [10u32, 20, 25, 30, 40, 50] {
        if post_residual >= threshold && post_residual < threshold + 5 {
            score -= 8.0; // residual lands in a "usable zone"
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling: quadratic in normalized post residual, modulated by progress
    score -= 30.0 * norm_pr * norm_pr * (1.0 - progress);
    score += 20.0 * norm_pr * norm_pr * progress;
    // lookahead: reward if next item fits post residual (smooth)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 15.0 * (1.0 - fits).min(1.0) * (1.0 - 0.5 * progress);
    }
    // last-chance penalty
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }
    // dead space penalty grows late in stream
    score += 8.0 * norm_pr * progress;
    // new-bin candidate: penalize slightly unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic dead-space penalty
    let dead = post_residual as f64;
    score += 0.02 * dead * dead / bin_capacity as f64;

    // Harmonic class of post_residual: residues mod 8 / mod 16
    let r16 = post_residual % 16;
    if r16 == 0 {
        score -= 6.0; // perfectly aligned residual, very reusable
    } else if r16 <= 4 {
        score -= 2.0;
    } else if r16 >= 12 {
        score += 3.0; // awkward sliver
    }

    // Integer-division thresholds: post_residual bucket
    let bucket = post_residual / 10;
    score -= match bucket {
        0 => 8.0,          // nearly full bin -> great placement
        1 => 4.0,
        2 => 1.0,
        _ => 0.0,
    };

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0; // chains nicely
            // harmonic alignment of chained residual
            if (post_residual - next_item_size) % 8 == 0 {
                score -= 2.0;
            }
        } else {
            score += 1.5 * (next_item_size - post_residual) as f64 / 10.0;
        }
    } else {
        // last item: prefer fullest bin, ignore future
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
    } else {
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual context: prefer bins below mean residual (fill emptier ones less)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize unless residuals are all tight or item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = open_bins_count as f64 * 1.2;
        let mut nb = 12.0 + open_penalty;
        if item_size > 60 {
            nb -= 4.0; // big items may warrant fresh bins
        }
        if mean_residual < 15.0 {
            nb -= 8.0; // all open bins nearly full
        }
        nb -= 4.0 * progress; // later in stream, cheaper to open
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are dead space.
    // Non-linear penalty that spikes when post_residual falls into the "unusable gap"
    // band (1..=12) which almost nothing can fill.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += 30.0 * (13.0 - pr); // harsh penalty for tiny unusable gaps
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strong reward
    } else if pr > 12.0 && pr <= 25.0 {
        score += 8.0; // moderately awkward gap
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; if gap is small it's truly dead
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open,
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += 18.0 + 0.6 * open_bins_count as f64 + 15.0 * progress;
        // But if mean residual across open bins is tiny (all bins nearly full),
        // opening a new bin is reasonable: soften the penalty.
        if mean_residual < 15.0 {
            score -= 22.0;
        }
    } else {
        // Existing bin: slight reward to consolidate, stronger when many bins open.
        score -= 0.15 * open_bins_count as f64;
        // Prefer bins whose residual is close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 800.0; // perfect chain
        } else {
            score -= 400.0 / (1.0 + next_fit_gap as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space for the next item: penalize proportionally to how close we were
        let miss = (next_item_size - post_residual) as f64;
        score += 2.0 * miss;
    }

    // Penalize small unusable leftovers (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare residual against mean residual: prefer tighter-than-average bins
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless current bin fits poorly or lookahead is bad
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 60.0;
        let no_chain = next_item_size == 0 || post_residual < next_item_size;
        if !(poor_fit && no_chain) {
            score += 250.0;
        }
    }

    // Late in the stream, be more conservative about leaving big residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never be used again by typical items (<=80).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large gaps.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state: when many bins are open, prefer filling existing ones
    // (consolidation); when few bins are open, opening new ones is cheaper.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += 3.0 * openness * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (they are "fuller" than average), pushing toward balanced closure.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (residual_f - mean_residual) / mean_residual;
        score += 5.0 * rel.clamp(-1.0, 1.0);
    }

    // New-bin candidate handling: an empty bin is attractive early or when
    // the item fits poorly everywhere else; penalize it when good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_fraction = item_size as f64 / bin_capacity as f64;
        // Large items relative to capacity benefit from fresh bins.
        let new_bin_bonus = 12.0 * item_fraction - 10.0 * (1.0 - progress);
        score += 20.0 - new_bin_bonus;
        // If several bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Slight preference for bins that are already quite full (close them out).
    let fill_ratio = 1.0 - residual_f / bin_capacity as f64;
    score -= 7.0 * fill_ratio * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: post_residual scaled by a progress-driven polynomial.
    // Early in the stream, waste matters less; later, tight fits (low post_residual) are rewarded.
    let progress_weight = 0.5 + 0.9 * progress * progress + 0.6 * progress * progress * progress;
    score += progress_weight * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap * 0.1;

    // Reward tight fits with a smooth saturating term on normalized fill ratio.
    let fill = 1.0 - (post_residual as f64 / cap);
    score -= 2.0 * fill * fill * fill;

    // Penalize bins whose residual deviates from the mean residual (smooth quadratic coupling),
    // scaled by progress so late-stage divergence is punished more.
    let dev = post_residual as f64 - mean_residual;
    score += (0.05 + 0.15 * progress) * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // (avoid opening a new bin), with smooth escalation as stream progresses.
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack_after_next = post_residual as f64 - nxt;
            score -= 3.0 * (1.0 - slack_after_next / cap);
        } else {
            // Smooth penalty when the lookahead item cannot follow into this bin,
            // weighted by how badly it misses.
            let miss = (nxt - post_residual as f64) / cap;
            score += 2.0 * miss * (1.0 + progress);
        }
    }

    // Mild penalty on many open bins to discourage bin proliferation,
    // smoothly increasing with progress.
    score += (0.02 + 0.06 * progress) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity-fraction slot does it land in?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining after placement

    // Integer-division thresholds: post_residual in {0..9, 10..19, ...} decades.
    let decade = post_residual / 10;
    // Penalize residuals in "dead" decades (small unusable slivers), reward exact closes.
    match decade {
        0 => score += 12.0,                 // 0..9: nearly dead space, but exact fit is great
        1 => score += 6.0,                  // 10..19: only small items fit
        2 => score += 1.0,                  // 20..29: moderate
        3 | 4 => score -= 3.0,              // 30..49: versatile residual
        _ => score -= 5.0,                  // >=50: large residual still very usable
    }

    // Exact fit bonus: modulo arithmetic on capacity
    if post_residual == 0 {
        score -= 40.0;
    }
    // Harmonic residuals (capacity divisible nicely): 50, 25, 20, 10
    if post_residual == 50 || post_residual == 25 || post_residual == 20 || post_residual == 10 {
        score -= 8.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward if next item leaves a harmonic residual again
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 6.0;
            }
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize leaving big residual wasted
            score += 4.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so open bins with decent fit win
        score += 30.0;
        // but if mean residual across open bins is small (all bins tight),
        // opening fresh is fine
        score -= 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits, must open new bin
        }
    }

    // Tightness coupling: prefer bins where item fills a large share of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill;

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= 5.0;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (post_residual as f64) * 0.2;
    }

    // Late-stream tightening: penalize waste more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * (0.1 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-match: lookahead item nearly fills the bin afterwards.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 20.0 - 1.5 * gap;
        }
    }
    // Penalize leaving residual smaller than the minimum possible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: make it costly unless item is huge or fit is bad.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 {
            score += 60.0; // discourage opening a bin for small items
        } else {
            score -= 10.0 * fill_ratio; // large items may justify a fresh bin
        }
        // If no open bin fits well, allow new bin more readily late in stream.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference to consolidate into fewer bins early on.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize tiny dead space that nothing (min size 1) can use is mild,
    // but penalize mid-range dead space that blocks future items.
    if post_residual > 0 && post_residual < item_size {
        score -= 4.0; // perfect fill achieved
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: penalize if this placement leaves no room for the next item,
    // unless the leftover is exactly usable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
        // Bonus: leave exactly enough room for next item (chain packing).
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate: keep it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by how bad current fits are.
        let avg_fit = mean_residual / bin_capacity as f64;
        let openness = 30.0 * (1.0 - fit_ratio) * (1.0 - avg_fit);
        score += 8.0 + openness;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Too many open bins: discourage spreading thin.
        score += 0.4 * open_bins_count as f64;
    } else {
        // Prefer fuller bins generally (best-fit bias via residual dispersion).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Large items: prefer them in emptier bins to avoid fragmentation.
    if item_size > bin_capacity / 2 {
        score += 0.15 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (minimize post_residual);
    // later, tolerate larger residuals to avoid opening new bins.
    let tightness = 1.0 + 1.5 * progress - 0.5 * progress * progress;
    score += 12.0 * (pr / cap).powi(2) * tightness;

    // Penalize dead space relative to mean residual of open bins.
    let dead = (pr - mean_residual) / cap;
    score += 8.0 * dead * dead * (1.0 + progress);

    // Reward last-chance bins that can still fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - pr / cap);
    }

    // Slight penalty for proliferation of open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: keep it neutral-to-slightly-unattractive
    // unless no open bin is a good fit.
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * progress * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: dead space that cannot fit a
    // typical next item is wasted. Classify residual into capacity
    // fractions via integer division thresholds.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > 0 {
        if post_residual < quarter {
            // Tiny dead space: unusable, strongly penalize.
            score += 25.0;
        } else if post_residual < half {
            // Medium residual: mildly useful.
            score += 5.0;
        } else {
            // Large residual: bin still flexible, reward.
            score -= 10.0;
        }
    }

    // If next item fits into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the gap.
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when the current
    // placement would leave a very awkward residual or no bin fits well.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score, prefer keeping it closed
        // unless existing placements are bad.
        score = 60.0 + 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin good for pairing big items
        }
    }

    // Stream progression: later in stream, be more frugal with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mean residual coupling: when open bins are on average full-ish,
    // discourage spreading; when loose, discourage cramming.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space: gap too small for the smallest plausible item (1..100 range).
        // A residual below ~10 is nearly unusable; scale penalty sharply.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 25 {
            score += 25.0;
        } else if post_residual < 50 {
            score += 8.0;
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Coupling: penalize leaving gaps that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // (avoid bin proliferation); subtract reward for using existing bins.
    let pressure = (open_bins_count as f64) * 2.0;
    if bin_residual < bin_capacity {
        // This is an existing bin: reward using it proportionally to pressure.
        score -= pressure * 0.5;
    } else {
        // Brand-new empty bin candidate: penalize slightly under pressure.
        score += pressure * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Progress-aware tightening: later in stream, be more conservative
    // with dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    // Mean-residual coupling: if mean residual across open bins is low,
    // prefer packing tight here (this bin's post_residual matters more).
    if (mean_residual as u32 as f64) == mean_residual && mean_residual < 30.0 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 150.0;
        } else {
            // dead space for the next item: penalize small leftovers
            score += 50.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize leaving tiny unusable gaps (below minimum item size 1..100 heuristic)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are bad fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // if no open bin leaves room for the next item, new bin becomes attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space below the minimum plausible item size (1) is moot,
    // but penalize residuals too small for the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Waste that the next item cannot use.
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that still accommodate the lookahead item.
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation
    // when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling bins below the mean residual (already "fuller") is good.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in the stream, be conservative (favor tight fits,
    // discourage new bins); late in the stream, slightly favor quick fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // New-bin candidate handling: only attractive when no decent fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 22.0;
        // If this bin is the only option that fits, opening is acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If the current item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate moderate residuals; late, punish any leftover space hard.
    let progress_coupling = pr * pr / cap * (0.4 + 1.6 * progress * progress);
    score += progress_coupling;

    // Reward near-perfect fills (small post_residual) super-linearly.
    let tightness = 1.0 - pr / cap;
    score -= tightness.powi(6) * cap * (0.5 + 0.5 * progress);

    // Dead-space penalty: residuals that no plausible item (1..100) can use well.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (2.0 + 3.0 * progress);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt).abs() / cap;
            score -= fit_quality * fit_quality * 15.0;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (pr - cap * 0.5).max(0.0) * 0.3 * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pr * 0.2 * open_pressure;

    // Mean-residual coupling: if this bin's residual is far below average (it's tight),
    // prefer it; a residual above mean is a candidate for future items.
    let this_residual = bin_residual as f64;
    let rel = (this_residual - mean_residual) / cap;
    score += rel * rel * 20.0 - rel * 10.0;

    // New-bin candidate handling: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_existing = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        // Baseline cost of a fresh bin; escalates as stream progresses (waste matters more).
        score = cap * (0.9 + 0.6 * progress) - best_existing * 0.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / cap) * 30.0;
        // Last-chance existing bin beats a new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: class 0 (perfect fit) is best.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = post_residual % 10;
    match class {
        0 => score -= 25.0,               // exact decade residual: ideal
        1 | 2 => score -= 8.0,            // near-perfect
        3 | 4 | 6 | 7 => score += 6.0,    // awkward middle gaps
        8 | 9 => score += 12.0,           // almost-dead slivers
        _ => {}
    }

    // Fractional fill level: reward bins that become "harmonically full".
    let fill = (bin_residual as f64) / cap;
    let item_frac = (item_size as f64) / cap;
    if item_frac > 0.5 && fill >= item_frac {
        score -= 15.0 * item_frac;        // big item into tight bin: great
    }
    if item_frac < 0.3 && fill > 0.7 {
        score += 10.0;                    // tiny item wasting a big gap
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;                    // unusable sliver
    }

    // Lookahead coupling: does post_residual harmonically fit next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // reward if residual is a near-exact multiple/harmonic of next item
            let ratio = post / nxt;
            let frac = ratio - ratio.floor();
            if frac < 0.15 || frac > 0.85 {
                score -= 12.0;
            } else {
                score += 4.0 * frac;
            }
        } else {
            score += 8.0;                 // next item won't fit here
        }
    }

    // Last-chance bonus: sole fitting bin — strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless item is large
    // or no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_big = item_frac > 0.6;
        let mut new_bin_score = cap - post as f64; // = item_size baseline
        if item_big {
            new_bin_score -= 20.0;
        }
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            new_bin_score -= 10.0;        // fresh bin can host next item too
        }
        new_bin_score += 15.0 * (1.0 - progress); // early stream: fresh bins cheap-ish
        new_bin_score += pressure * 2.0;          // many open bins: discourage sprawl
        if fitting_bins_count > 0 {
            new_bin_score += 25.0;        // an existing bin fits; new bin must win big
        }
        score = new_bin_score;
    }

    // Mild tie-break: prefer bins with residuals harmonically aligned to capacity.
    let r = bin_residual % 25;
    if r == 0 {
        score -= 3.0;
    } else if r >= 20 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Fit tightness: prefer bins where item occupies a large fraction of residual
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize adding to bins when many are open
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residual close to item size (tight fit)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Lookahead: if next item could use the post residual, reward leaving it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: allow opening a fresh bin only when it's
    // genuinely better than a poor fit (empty bin has large post_residual,
    // which is naturally attractive, but add pressure to reuse bins early)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + progress * 10.0 - open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward if next item also fits well after this placement
            let second_post = post_residual - next_item_size;
            score -= 20.0 * (1.0 - second_post as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: minimize wasted space
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize new empty bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin good for pairing current+next
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Lookahead: if the next item can fit into the post-residual, reward this bin;
    // if not, penalize creating residual smaller than the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            // Waste proportional to unusable gap for the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
        // If next item fits better in a fuller bin, prefer keeping slack here.
        if next_item_size <= post_residual && post_residual - next_item_size < item_size {
            score -= 2.0;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize new-bin candidate mildly, unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if opening a new bin leaves it perfectly sized for the next item too, soften.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Time horizon: early in the stream, be more open to new bins (future flexibility);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is below the mean (fill the emptier-trending bins less,
    // keep balanced residuals for future items).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Slight preference for using already-open bins as open bin count grows.
    if bin_residual != bin_capacity {
        score -= 0.5 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual weighted by a polynomial of progress.
    // Early in the stream, tight fits matter less; late, waste is penalized more.
    let progress_poly = 1.0 + 2.0 * progress * progress + 3.0 * progress * progress * progress;
    score *= progress_poly;

    // Reward tight fits: quadratic bonus when post_residual is small
    let pr = post_residual as f64;
    let tightness = (bin_capacity as f64 - pr) / bin_capacity as f64;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space that is too small to be useful for typical items
    if pr > 0.0 && pr < 10.0 {
        score += 12.0 * (10.0 - pr) / 10.0;
    }

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 5.0 * (n / bin_capacity as f64);
        } else if pr > 0.0 {
            score += 4.0 * (1.0 - pr / n.max(1.0));
        }
    }

    // Discourage fragmenting many open bins when mean residual is already low
    let mean_r = mean_residual;
    if mean_r < 20.0 {
        score += 3.0 * (20.0 - mean_r) / 20.0;
    }

    // Mild penalty for opening a new bin when plenty of open bins fit the item
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 * progress + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo common item sizes
    let r = post_residual as i64;
    let class = r % 10; // decade harmonic class
    // Penalize residues that are awkward (1..9 small dead space)
    if r > 0 && r < 10 {
        score += 25.0; // tiny dead space is worst
    } else if class == 0 {
        score -= 8.0; // perfect decade fit leaves reusable space
    } else if class <= 5 {
        score += 3.0;
    }

    // Integer-division thresholds: post_residual bucketed by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 6.0; // near-full bin, fine but little future value
    } else if frac > 0.5 {
        score -= 5.0; // keeps a half-capacity bin alive
    }

    // Lookahead harmony: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match rewards
            let diff = post_residual - next_item_size;
            score -= 10.0 - (diff as f64).min(10.0) * 0.5;
        } else {
            score += 4.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize opening unless current bins are tight
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score += 12.0 * (1.0 - tightness); // open new bin only when mean residual is low
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: later in stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // Mild tie-break toward bins with small residual gap to item
    score += (bin_residual - item_size) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be used again
    // (smaller than the minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Non-linear penalty on dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        score -= 20.0; // still attractive gap, likely fillable by small items
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // fit would be terrible or open-bin pressure is high.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        let pressure = open_bins_count as f64 / 20.0;
        score += 150.0 - pressure * 30.0;
        if bad_fit { score -= 0.0; } else { score += 40.0; }
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 20.0; // new bin could serve the next item too
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0; // next item won't fit here anyway
    }

    // Open-bin pressure: mild penalty for spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Slight preference for bins below mean residual (balance residuals).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let mean = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        post
    };

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let has_next = next_item_size > 0;
    let is_new_bin = bin_residual == bin_capacity;
    let open_pressure = (open_bins_count.min(64) as f64).sqrt();

    let mut effective_residual = post;
    let mut score;

    if has_next {
        let gap = post - next;

        if gap >= 0.0 {
            effective_residual = gap;
            score = 0.30 * post + 0.70 * gap;

            let sigma = 0.28 * cap + 1.0;
            let match_quality = (-(gap / sigma).powi(2)).exp();
            let size_weight = 0.25 + 0.75 * (next / cap).clamp(0.0, 1.0).sqrt();

            score -= (0.55 * cap + 0.20 * item) * match_quality * size_weight;
        } else {
            score = post * 1.06;
        }
    } else {
        score = post;
    }

    let mean_weight = if is_new_bin {
        0.06 + 0.04 * progress
    } else {
        0.15 + 0.10 * progress + 0.03 * open_pressure
    };

    score += mean_weight * (effective_residual - mean);

    if !is_new_bin && fitting_bins_count == 1 {
        let quality = 1.0 - (effective_residual / cap).clamp(0.0, 1.0);
        score -= cap * (0.15 + 0.25 * quality) * (0.8 + 0.4 * progress);
    }

    if is_new_bin {
        let alt_pressure = 1.0 + (fitting_bins_count.min(16) as f64) * 0.035;
        score += cap * (0.52 * alt_pressure + 0.08 * progress)
            + 0.15 * mean
            + 2.5 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize dead space quadratically (small post-residuals are good)
    score += (post / cap) * (post / cap) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0;
            if (post - nxt).abs() < 5.0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += (nxt - post) / cap * 20.0;
        }
    } else {
        // Last item: just minimize post residual
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: this bin is not scarce; slight penalty to prefer tightest fit
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins tighter than average when mean residual is large
    let res_diff = (bin_residual as f64) - mean_residual;
    score += res_diff * 0.15;

    // Time horizon: early in stream, favor opening new bins for large items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, less so late
        score -= 20.0 * (1.0 - progress);
        // Penalize new bin if item is small relative to capacity
        score += (item_size as f64 / cap) * 25.0;
    } else {
        // Late in stream: reuse existing bins more aggressively
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 40.0 * poly * (1.0 + progress);

    // Penalize large post-residual more strongly late in the stream
    score += 0.5 * norm_pr * norm_pr * progress * cap;

    // Reward tight fits (small post_residual) with smooth falloff
    let tight = (1.0 - norm_pr).powi(3);
    score -= 25.0 * tight;

    // Lookahead coupling: prefer bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: smooth quadratic coupling
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: penalize mildly unless post_residual is attractive
    if bin_residual == bin_capacity {
        score += 6.0 - 20.0 * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Small post_residual = tight fit (good). Penalize awkward leftovers.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic classes via integer division: leftover in [1..=25] is prime real estate
    // (fits any small item); [26..=50] second class; larger leftovers are wasteful.
    let class = post_residual / 25; // 0,1,2,3
    score += class as f64 * 8.0;

    // Modulo coupling: post_residual divisible by common small item sizes (10,20,25,50)
    // is harmonically reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Harmonic bonus: next item exactly consumes a harmonic chunk
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Dead-space penalty scaled by waste fraction.
    score += (post / cap) * 10.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize new bin mildly; escalate if many open bins exist (prefer packing them).
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if current bin would leave a bad harmonic leftover, new bin is better.
        if post_residual > 0 && post_residual < item_size.min(20) {
            score -= 15.0;
        }
        // Late in stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good closer.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Gaps that cannot hold the lookahead item but are not tiny are semi-waste
    // only if the next item would have fit otherwise.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual <= item_size / 4 {
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: mildly discourage proliferation of open bins,
    // but not for the new-bin candidate itself.
    if bin_residual != bin_capacity {
        score += 0.35 * open_bins_count as f64;
        // Prefer bins below mean residual (fresher bins) for large items.
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.08 * diff;
    } else {
        // New-bin candidate: make it attractive only when existing fits are bad
        // (large dead space or nothing fits well). Add a mild baseline cost so
        // decent existing bins still win.
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if post_residual_of_best_unavailable(item_size, bin_residual, bin_capacity) {
            score -= 20.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly in post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

fn post_residual_of_best_unavailable(_item_size: u32, _bin_residual: u32, _bin_capacity: u32) -> bool {
    false
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: prefer keeping items in open bins unless fit is bad
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; slightly worse than a decent fit
        score += 25.0;
        // Early in the stream, opening bins is cheaper (build a pool)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If next item is huge, a fresh bin gives flexibility
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Reward perfect / near-perfect fits
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 5 {
            score -= 40.0;
        } else if post_residual <= 10 {
            score -= 25.0;
        }

        // 2-step lookahead: reward when next item exactly fits post_residual
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 70.0; // chain fit: perfect pairing
            } else if next_item_size < post_residual {
                let slack = (post_residual - next_item_size) as f64;
                // next item fits: penalize leftover after that hypothetical placement
                score -= 30.0 * (1.0 - slack / bin_capacity as f64);
                if slack <= 10 {
                    score -= 20.0;
                }
            } else {
                // next item won't fit here: penalize dead space that blocks it
                let overflow = (next_item_size - post_residual) as f64;
                score += 0.15 * overflow;
            }
        }

        // Relative to mean residual: bins with residual close to mean are "normal",
        // extreme residuals (very small) are precious — don't waste on big items
        let res_f = post_residual as f64;
        if res_f < mean_residual * 0.4 {
            score += 10.0; // using a nearly-full bin for a poor fit is wasteful
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 35.0;
        }

        // Penalize leaving dead space that no future item (10..80) can use well
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0; // tiny dead space is fine, it's essentially full
        } else if post_residual >= 80 {
            score += 5.0; // leaving a huge residual means poor packing choice
        }

        // Many open bins: encourage consolidation into emptier bins
        if open_bins_count > 8 && post_residual as f64 > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (low post-residual), with a non-linear bias.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;  // narrow usable window
    }

    // Lookahead (k=2): reward bins where the next item also fits.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            // Chain fit: subtract proportionally to how well next item nests.
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 12.0 - chain_waste.min(12.0);
        } else {
            // Next item won't fit here; mildly penalize leaving medium gaps.
            if post_residual >= (next_item_size as f64 * 0.5) as u32 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or the global state is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        // Reward new bins early or when existing residuals are large/fragmented;
        // penalize new bins when existing bins are nearly full (waste of capacity).
        let new_bin_bonus = 20.0 * (1.0 - fragmentation) - 10.0 * fragmentation
            + 8.0 * (1.0 - progress);
        score += new_bin_bonus;
        // Large items justify fresh bins more than small ones.
        score += 0.15 * (item_size as f64 - 50.0);
    } else {
        // Prefer bins whose residual deviates below the mean (consolidating waste).
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    // Time-horizon modulation: late in the stream, tighten up (favor exact fits more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + progress * 2.0);
    let mut score = pr - 30.0 * poly;
    // Penalize residual that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += gap * (0.5 + progress);
        } else {
            score -= 2.0;
        }
    }
    // Reward tight fits (small post residual) more strongly late in stream
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Mild penalty for spreading across many bins vs mean residual
    score += (open_bins_count as f64).ln() * 0.5 + (mean_residual - pr) * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is
    // for common small item sizes. Residuals that are multiples of small
    // harmonics (10, 20, 25, 50) are more reusable, so reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit: best possible outcome
    } else {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // Dead space: residual below the minimum item size is pure waste
        if pr < 10 {
            score += 25.0;
        }
        // Small awkward residuals that few items can use
        if pr < 20 && pr >= 10 {
            score += 8.0;
        }
    }

    // Harmonic class of the item itself relative to capacity
    let cap_frac = (item_size as f64) / (bin_capacity as f64);
    if cap_frac > 0.5 {
        // Large items: prefer tightest fit, penalize spreading
        score -= 5.0;
    } else if cap_frac > 0.25 {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can follow into this bin: reward, more if exact harmonic
            score -= 8.0;
            if pr % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; if this bin was the only option, penalize
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    // Only prefer it when the item is large and no open bin is a good fit,
    // or when open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Opening a new bin is attractive for large items or when existing
        // residuals are small/fragmented; otherwise penalize opening new bins.
        if cap_frac > 0.5 || fragmentation < 0.25 {
            score -= 4.0;
        } else {
            score += 10.0 + 5.0 * fragmentation;
        }
    }

    // Prefer bins with residuals close to the item (tight fit) via
    // integer-division threshold on bin_residual / item_size ratio class.
    if item_size > 0 {
        let div = bin_residual / item_size;
        match div {
            1 => score -= 5.0,   // bin is barely bigger than item: very tight
            2 => score -= 2.0,
            _ => score += 1.0,   // very roomy bin: save it for larger items
        }
    }

    // Mild stream-progress adaptation: later in the stream, be greedier
    // about filling bins tightly (avoid leaving many near-empty bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Slight preference for bins already below mean residual (consolidation)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Pressure from many open bins: favor filling existing bins over opening new ones.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate should only win when open bins are very full (small mean residual).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * mean_residual;
    }

    // Progress scaling: later in stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 25.0; // exact chain match
        }
    } else if next_item_size == 0 {
        // Last item: prefer tightest fill.
        score -= 10.0;
    }

    // Penalize post-residuals that are dead space (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer bins with larger residuals relative to mean (keep small holes for small items).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, be more willing to open new bins (keep flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        score -= 15.0 * (1.0 - progress);
        score += 10.0 * progress;
    }

    // Too many open bins: discourage spreading.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) especially when many bins compete.
    if fitting_bins_count > 1 {
        score -= (bin_capacity as f64 - post_residual as f64) * 0.35;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual as u32 {
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; penalize wasting space
            // that could have hosted the next item.
            if next_item_size <= bin_residual {
                score += 10.0;
            }
        }
    }

    // Penalize creating very small dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Time horizon: early in stream, be conservative (avoid fragmentation);
    // late in stream, prefer filling existing bins aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer
    // bins below the mean residual (consolidate).
    if open_bins_count > 2 {
        let dev = mean_residual - post_residual as f64;
        score -= 0.10 * dev;
    }

    // New-bin candidate: only attractive when nothing fits well anywhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 20.0 + 3.0 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * (1.0 - progress) * 0.5;

    let mut score = poly * cap;

    // Reward tight fits smoothly
    score -= 8.0 * fill * fill * fit_ratio;

    // Penalize dead space more as stream progresses (fewer chances to reuse)
    score += 6.0 * pr_norm * pr_norm * progress;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score += 4.0 * gap_norm * gap_norm;
        if next_item_size as f64 <= pr {
            score -= 3.0 * (next_item_size as f64 / cap);
        }
    }

    // Mild preference toward consolidating into existing bins vs opening new
    if bin_residual == bin_capacity {
        score += 5.0 + 5.0 * progress;
    } else {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by small classes
    // are more reusable by future items; odd/prime-ish residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0; // highly reusable residual class
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else if pr % 2 == 0 {
            score -= 2.0;
        } else {
            score += 3.0; // odd residual: harder to fill exactly
        }
        // Very small residuals are near-dead space unless next item fits.
        if pr < 10 {
            score += 12.0;
            if next_item_size > 0 && next_item_size <= pr {
                score -= 20.0; // lookahead exactly consumes dead space
            }
        }
        // Lookahead harmony: post_residual modulo-comparable to next item.
        if next_item_size > 0 {
            if pr >= next_item_size {
                let rem2 = pr - next_item_size;
                if rem2 == 0 {
                    score -= 300.0; // two-step perfect chain
                } else if rem2 % 10 == 0 {
                    score -= 15.0;
                } else if rem2 < 10 {
                    score += 10.0; // chain leaves sliver
                }
            } else {
                score += 6.0; // next item can't use this bin's leftover
            }
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening fresh bins when open bins fit,
    // but allow it when fit would be terrible elsewhere.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is correct
        } else if post_residual > 60 {
            score -= 20.0; // item small relative to bin: fresh bin keeps flexibility
        }
    }

    // Mild pressure toward consolidating into few bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - progress);
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small unusable gaps (< 10, minimum item size): dead space.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual <= 20 {
            // Small gaps that only tiny items can use: mild penalty.
            score += 10.0;
        }
        // Reward leaving space that can still fit typical items.
        score -= 0.15 * post_residual as f64;
    }

    // If lookahead item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 8.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; prefer new bin when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but reward when open bins are already fragmented.
        score += 15.0 + 2.0 * open_bins_count as f64;
        if mean_residual < item_size as f64 * 1.5 {
            score -= 20.0; // existing bins are tight; new bin is fine
        }
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Slight late-stream tightening: less willing to open new bins near the end.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: perfect-fit lookahead — if next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post_residual that is too small for the next item (dead space risk).
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Reward tight fits relative to current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize deviations from mean residual (prefer balanced / well-matched bins).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is a fallback: penalize unless lookahead suggests big item next.
        let early = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 20.0 * early;
        if next_item_size > 60 {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate: discourage new bins further.
    if step_index as f64 / (total_items.max(1) as f64) > 0.8 && bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Penalize small unusable dead space (post_residual too small for typical future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave this bin useless anyway, slight penalty for wasting a good bin.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size.min(20) {
        score += 10.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize old bins less? no —
    // early on, prefer conserving tight fits, so add mild penalty to nearly-full bins early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Many open bins: encourage filling existing ones (penalize new-bin candidate implicitly via residual).
    score += open_bins_count as f64 * 0.3;

    // Global residual state: if mean residual is high, prefer bins below mean (avoid fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
