        score += 3.0;
    }

    // New-bin candidate: make it unattractive unless item is large relative to capacity
    // or no bin fits well (post_residual of new bin = capacity - item_size).
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 15.0 } else { 0.0 };
        score += 30.0 - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with non-linear growth (dead space quadratic)
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals acceptable (room for future items);
    // late in the stream, tight fills are much more valuable.
    let coupling = 1.0 + 2.0 * progress * progress + 3.0 * progress * norm_pr;
    score *= coupling;

    // Reward tight fits smoothly (small post residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 10.0;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize leaving residual that cannot host the next item late in stream
        score += 4.0 * progress;
    }

    // Mild penalty for spreading across many bins (favor consolidation)
    score += (open_bins_count as f64) * 0.05;

    // New-bin candidate handling: prefer opening a new bin only when
    // existing residuals are large relative to capacity
    if bin_residual == bin_capacity {
        let threshold = 0.35 + 0.25 * progress;
        if norm_pr > threshold || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0 + 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize by 16th of capacity
    let q = (bin_capacity as f64 / 16.0).max(1.0);
    let post_class = (post_residual as f64 / q).floor() as i64;

    // Reward tight fits (low post class), with extra bonus for exact fit
    score -= (16 - post_class.max(0)) as f64 * 2.0;
    if post_residual == 0 {
        score -= 50.0;
    }

    // Modulo arithmetic on post_residual: small residues near multiples of 8
    // are "harmonically compatible" with common small items (1..=8 classes)
    let m = post_residual % 8;
    if m <= 2 {
        score -= 4.0;
    } else if m >= 6 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra reward if next item also lands in a harmonic class (leaves clean residue)
        let next_post = post_residual - next_item_size;
        if next_post % 8 <= 2 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize wasted potential
        score += 5.0;
        // penalize more if leftover is large dead space
        if post_residual > bin_capacity / 4 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer new bin only when current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // baseline penalty so new bins are chosen only for poor fits
        score += 20.0;
        // late in the stream, opening fresh bins is cheaper (more bins amortized)
        score -= progress * 6.0;
        // if many bins are open with low mean residual, discourage another bin
        if mean_residual < 15.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance load)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Integer division threshold: bins whose residual >= item_size + 10 keep future utility
    if bin_residual >= item_size + 10 && post_residual >= 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // barely usable dead space
        } else {
            // non-linear coupling: gaps in the "awkward middle" range are risky
            score += 0.15 * ((post_residual as f64) - 20.0).powi(2) / 10.0;
        }
    } else {
        score -= 40.0; // perfect fill: strongly reward
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage creating new ones
    // (new-bin candidate has bin_residual == bin_capacity, so this also
    //  penalizes opening a new bin when open_bins_count is high).
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is already below average (consolidate waste)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Lookahead: if the next item fits exactly in the post_residual, reward this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for flexibility
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred (small post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64) * 0.5;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64 / 100.0) * 6.0;
        } else {
            // Dead space relative to next item: penalize wasted remainder.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    // far below mean (unbalanced, hard-to-fill leftovers).
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so it's only chosen when no open bin
    // offers a reasonable fit (very poor fits get large penalties above).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Early in stream, be slightly more willing to open bins (better spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Penalize creating dead space: post_residual too small for typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; slight penalty if we leave large awkward residual.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless open bins are crowded/mean residual small.
        score += 10.0 + open_bins_count as f64 * 2.0;
        if mean_residual < item_size as f64 * 1.5 {
            score -= 12.0;
        }
    } else {
        // Reward using existing bins, more when many are open.
        score -= 3.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Time horizon: early in stream, be pickier (prefer near-perfect fits);
    // late in stream, just pack anything to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += tightness * 20.0 * (1.0 - progress);
    score -= 10.0 * progress;

    // Global residual balance: prefer bins whose residual is above the mean
    // (drain fuller bins first, keep emptier bins flexible).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
    let _ = total_items;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = post_residual;
    let _ = fitting_bins_count;
    0.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group dead space into coarse classes
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,             // near-perfect fit (0..10 residual)
        1 => score -= 10.0,             // good fit
        2 | 3 => score += 2.0,          // mediocre
        4 | 5 => score += 8.0,          // half-bin dead space, still reusable
        _ => score += 15.0,             // large leftover but bin nearly empty anyway
    }

    // Modulo-10 harmony: residuals that are multiples of 10 pair well with
    // typical item sizes (multiples of 5/10 dominate many streams)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain two items into this bin -> strong reward
            score -= 12.0;
            // bonus if the double placement leaves a tiny remainder again
            let after2 = post_residual - next_item_size;
            if after2 < 10 {
                score -= 8.0;
            }
        } else if next_item_size > 0 && post_residual < 10 && post_residual > 0 {
            // creates unusable sliver that blocks the next item -> penalty
            score += 10.0;
        }
    } else {
        // last item: maximize fill, dead space is worthless
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has perfect modularity but no fill;
    // only prefer it when nothing else fits well.
    if bin_residual == bin_capacity {
        score += 30.0; // discourage new bins by default
        if fitting_bins_count == 0 || (next_item_size > 0 && item_size + next_item_size > bin_capacity) {
            score -= 45.0; // but allow when stream forces it or big pair coming
        }
    }

    // Stream progression: early on, prefer spreading items to build flexible bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.25 {
        score += post_residual as f64 * 0.15; // keep bins roomy early
    } else if progress > 0.75 {
        score -= post_residual as f64 * 0.10; // pack tightly late
    }

    // Mean-residual coupling: if open bins are already tight, prefer using them
    if (mean_residual - post_residual as f64).abs() < 15.0 {
        score -= 4.0;
    }

    // Open-bin pressure: many open bins -> consolidate
    if open_bins_count > 8 {
        score += 1.0 + 0.05 * open_bins_count as f64 * (post_residual as f64 / 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small gap: usable only by tiny items; moderate penalty scaled by gap smallness.
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward snug fits: post_residual close to 0 relative to item size.
    let snugness = 1.0 - (post_residual as f64 / (item_size as f64 + 1.0));
    score -= 15.0 * snugness * snugness;

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item is larger than post_residual but this bin was the only
    // fitting option, penalize blocking.
    if next_item_size > 0 {
        if (next_item_size as f64 - post_residual as f64).abs() < 3.0 {
            score -= 20.0; // chain fit
        } else if next_item_size as u32 > post_residual && next_item_size as u32 <= bin_residual {
            score += 12.0; // we consumed space the next item could have used
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 20.0 + 4.0 * open_bins_count as f64 + 0.3 * mean_residual * (1.0 - progress);
    } else {
        // Mild reward for filling existing bins as stream progresses.
        score -= 2.0 + 1.5 * progress;
    }

    // Prefer bins below mean residual (more filled than average).
    if bin_residual != bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 20.0;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            // Perfect 2-step match: huge reward
            score -= 100.0;
        } else if diff > 0.0 {
            // Next item fits in the leftover space: proportional reward
            score -= (next_item_size as f64 / post_residual as f64) * 40.0;
        } else {
            // Next item won't fit here; penalize large wasted residuals relative to next item
            score += (-diff / bin_capacity as f64) * 15.0;
        }
    } else {
        // Last item: just minimize post_residual
        score -= 10.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += rel * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += fitting_bins_count as f64 * 2.0;
    }

    // New-bin candidate: penalize mildly, unless current bin is a very poor fit
    if bin_residual == bin_capacity {
        // New bin is attractive when the item is large and nothing fits well
        let poor_fit = (post_residual as f64) > 0.6 * (bin_capacity as f64);
        if poor_fit && fitting_bins_count <= 1 {
            score -= 30.0; // open a fresh bin for large items with bad fits
        } else {
            score += 35.0; // default: prefer reusing existing bins
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early phase favors consolidation, late phase tolerates spread.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: very small post-residuals are waste unless exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // post-residual too small for lookahead: penalize leaving stranded space
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is justified only when the item
    // fits poorly everywhere or the residual left here is awkward.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream grows.
        let mut new_bin_score = bin_capacity as f64 - 45.0 + 20.0 * progress;
        // If this bin is a last resort, opening new is unattractive.
        if fitting_bins_count == 1 {
            new_bin_score += 35.0;
        }
        // If the item leaves a clean residual in an existing bin, avoid new bin.
        if post_residual as f64 <= mean_residual * 0.5 {
            new_bin_score += 15.0;
        }
        // Lookahead that pairs well with a fresh bin.
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 10.0;
        }
        // Many open bins already: discourage proliferation.
        new_bin_score += open_bins_count as f64 * 1.5;
        score = new_bin_score;
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_norm = item_size as f64 / cap;

    // Smooth polynomial base on post_residual with progress coupling
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * pr * pr / cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tight = 1.0 - pr / cap;
    score -= 12.0 * tight * tight * fit_norm * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 0.6 * progress);
        } else {
            score -= 0.25 * (1.0 - (pr - nxt) / cap).max(0.0);
        }
    }

    // Last-chance bonus: only one bin fits the item
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - fit_norm);
    }

    // Mild pressure to spread load when many bins are open
    score += 0.15 * (open_bins_count as f64).sqrt() * (1.0 - fit_norm);

    // Favor bins whose residual is near the mean residual (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // Slight new-bin penalty so empty bins are only chosen when truly better
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "reusable" classes
    // (multiples of common item sizes: 10, 20, 25, 50) that later items can fill.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if pr % 50 == 0 {
        score -= 35.0;
    } else if pr % 25 == 0 {
        score -= 22.0;
    } else if pr % 20 == 0 {
        score -= 18.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += 8.0; // awkward residual, dead space risk
    }

    // Dead-space penalty: tiny residuals are nearly unusable (items >= 1 though,
    // so weight by how small relative to typical item scale).
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the slack after the lookahead placement
            let s2 = pr - next_item_size;
            let class_bonus = if s2 == 0 { 40.0 }
                else if s2 % 50 == 0 { 25.0 }
                else if s2 % 25 == 0 || s2 % 20 == 0 { 15.0 }
                else if s2 % 10 == 0 { 8.0 }
                else { -6.0 };
            score -= class_bonus + 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize more if this was the only fitting bin
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Fractional fill level: prefer bins that end up well-filled.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 15.0 * fill * fill;

    // Prefer tight bins over loose ones when mean residual is low (packing pressure).
    let pr_frac = post_residual as f64 / cap;
    if pr_frac < mean_residual / cap {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that grows
    // with how many bins are already open; but it's attractive if no bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let stream_pos = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 2.5 * pressure + 10.0 * stream_pos;
        // if next item is large, a fresh bin is more valuable
        if next_item_size as f64 > 0.6 * cap {
            score -= 12.0;
        }
    }

    // Slight preference for fewer open bins when this bin would be emptied.
    if post_residual == 0 && open_bins_count > 1 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps (< 10,
    // and more generally gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Dead space measured relative to capacity: penalize leaving large fractions
    // wasted only when the gap is "unusable-looking" (not matching next item).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can still host the lookahead item: reward keeping it viable.
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Gap won't fit the next item: penalize proportionally to wasted space.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 2.0;
    } else {
        // New-bin candidate: penalize more heavily when many bins already open.
        score += open_bins_count as f64 * 3.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight progression term: early in stream, be more conservative about
    // opening bins; later, allow tighter fits to dominate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space, more so when it cannot fit a typical next item.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = post_residual as f64;
        score += 0.5 * dead * (0.5 + progress);

        // Aggressive 2-step lookahead: reward if next item fits the post-residual.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Exact 2-step match: post residual equals next item size -> perfect chain.
                if post_residual == next_item_size {
                    score -= 500.0;
                } else {
                    // Reward proportional to how snugly the next item fits.
                    let slack = (post_residual - next_item_size) as f64;
                    score -= 100.0 - slack.min(100.0);
                }
            } else {
                // Next item cannot use the leftover space: penalize the dead gap.
                let gap = (next_item_size - post_residual) as f64;
                score += 0.8 * gap;
            }
        }

        // Compare against mean residual: prefer tighter-than-average bins.
        score -= (mean_residual - post_residual as f64) * 0.3;

        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (poor fits in tight residual bins are expensive).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 80.0 * large_item;
    }

    // Mild preference for keeping the number of open bins low.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the minimum plausible item size is pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 25.0;
    }

    // Penalize large post-residuals that can't fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 6.0 + 0.10 * nxt; // can chain the next item too
        } else {
            score += 0.05 * (nxt - post_residual as f64); // wasted for lookahead
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Time horizon: early in the stream, favor compacting into fewer bins;
    // late in the stream, be more tolerant of opening fresh bins since
    // future compaction opportunities are limited anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later.
        score += 18.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // A new bin is attractive if no open bin fits well (large item).
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
    } else {
        // Reward filling existing bins more aggressively as stream progresses.
        score -= 4.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Global pressure: when mean residual across open bins is low, opening
    // new bins is cheaper; when high, prefer consolidating into this bin.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.08 * mean_gap;

    // Nonlinear coupling: penalize leaving awkward residuals
    // (residuals in [1, 15] are hard to fill with items >= 1 but statistically larger).
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 15.0 {
        score += 8.0 * (1.0 - pr / 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    // Early on, prefer tight fits mildly; late, waste is costlier.
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Polynomial coupling: dead space that is too small to be useful is penalized super-linearly.
    let dead_threshold = 10.0;
    if pr < dead_threshold {
        score += (dead_threshold - pr) * (dead_threshold - pr) * (0.5 + progress);
    }

    // Smooth interaction: small post residual relative to mean residual is attractive.
    let mr = mean_residual.max(1.0);
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - (norm_pr * cap / mr).min(1.0));

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits in post residual (smooth decay).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tightness = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 6.0 * tightness;
    } else if next_item_size > 0 {
        // Penalize leaving residual that just misses the next item.
        let miss = (next_item_size as f64 - pr) / cap;
        score += 4.0 * miss * miss * cap * 0.1;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    // Mild congestion pressure: many open bins favor consolidation.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality by modulo classes.
    let pr = post_residual;
    let class = pr / 10; // decade class of leftover space
    // Small leftovers (<10) are near-useless dead space -> penalize strongly.
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score += 25.0 - (pr as f64) * 2.0;
    } else {
        // Reward leftovers that match the "harmonic" granularity of typical items.
        // Leftovers that are multiples of 5 or 10 are more reusable.
        let harmonic = if pr % 10 == 0 {
            8.0
        } else if pr % 5 == 0 {
            4.0
        } else {
            0.0
        };
        score -= harmonic;
        // Larger leftovers are inherently better; already in base score.
        // Penalize mid-range awkward classes (pr in 11..=20) mildly.
        if class == 1 {
            score += 4.0;
        }
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly or nearly: strong reward.
            let tight = (pr as i32 - next_item_size as i32).abs();
            if tight == 0 {
                score -= 45.0;
            } else if tight <= 5 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how much
            // dead space is stranded relative to the next item.
            let stranded = (next_item_size - pr) as f64;
            score += 0.15 * stranded;
        }
    } else {
        // Last item: only the perfect fit matters.
        if pr == 0 {
            score -= 80.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // opening a new bin wastes this residual entirely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): prefer it only when this bin's usage
    // would leave a poor fit or when many bins are open with slack.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheap items or poor fits make a new bin more attractive.
        if item_size <= 30 {
            score -= 25.0;
        }
        if pr >= 60 {
            // Item is small relative to capacity; new bin wastes less.
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size + next_item_size > bin_capacity {
            // Current + next cannot share a bin anyway: pairing logic.
            score -= 10.0;
        }
        // If many bins are open with high mean residual, avoid proliferation.
        score += 0.35 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        // Reward filling existing bins more when many are open.
        score -= 0.05 * open_bins_count as f64;
        // Slight preference for tighter fits as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // typical future items (<= 10) are essentially dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Non-linear penalty on unusable small-to-medium gaps relative to capacity.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if gap_ratio > 0.0 && gap_ratio < 0.2 {
        score += 40.0 * (0.2 - gap_ratio) * 5.0;
    }

    // Perfect fit reward: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Penalize leaving a gap that is *almost* but not quite the next item.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening new bins is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0 * (0.5 + progress);
    score += bin_pressure;

    // New-bin candidate: empty bin has full residual. Only attractive when
    // mean residual across open bins is small (existing bins are crowded) or
    // the item fits poorly everywhere. Otherwise penalize so we reuse bins.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual / bin_capacity as f64;
        if mean_gap > 0.25 {
            score += 120.0; // plenty of room in open bins: don't open new one
        } else {
            score += 15.0; // bins crowded: new bin is reasonable fallback
        }
        // If no open bin fits well, opening a new bin is better.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (they are the "tight" ones that should be filled first).
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (small dead space).
    if post_residual <= 2 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // this is an ideal chain placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 60.0; // perfect two-item chain
        } else if next_fit_gap <= 10 {
            score -= 30.0;
        } else {
            score -= 10.0; // next item still fits, mild reward
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot use this bin's leftover; penalize proportionally
        // to how much dead space is stranded relative to next item size.
        let stranded = post_residual as f64;
        if stranded < next_item_size as f64 * 0.5 {
            score += 5.0 + stranded * 0.3; // small unusable gap
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with above-average residual consumption (tight packing).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0; // this bin is already tighter than average: finish it off
    } else {
        score += 3.0; // looser than average: deprioritize
    }

    // Last-chance bin: only bin that can fit the item. Avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably,
    // especially early/mid stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 20.0 * progress;
    }

    // Mild penalty for leaving large post_residual that nothing may fill later.
    if post_residual > 40 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            let slack_after_next = post_residual - next_item_size;
            // Reward leaving a well-shaped remainder for the item after next.
            if slack_after_next >= 10 && slack_after_next <= 40 {
                score -= 5.0;
            }
        } else {
            // Penalize leaving residue that cannot host the next item.
            score += 4.0;
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // no open bin offers a decent fit or open-bin count is high.
    if bin_residual == bin_capacity {
        let decent_fit_exists = (bin_capacity - item_size) as f64 <= mean_residual + 15.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count > 0 && decent_fit_exists {
            score += 20.0; // keep using open bins
        }
        // Late in the stream, opening fresh bins is more acceptable to avoid
        // fragmenting many partially-filled bins.
        if progress > 0.7 {
            score -= 6.0 * progress;
        }
        if open_bins_count > 8 {
            score += 3.0 * (open_bins_count as f64 - 8.0).min(10.0);
        }
    }

    // Global state: many open bins with high mean residual -> prefer bins
    // below the mean residual (consolidation), i.e. tighter bins.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Time-horizon modulation: early in the stream, be more selective about
    // tight fits; late, prioritize just closing out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: penalize large residuals more as stream progresses
    score += 30.0 * norm_pr * norm_pr * progress;

    // Tight fits reward: quadratic in item size fraction
    let fit_frac = item_size as f64 / cap;
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + fit_frac);

    // Dead space penalty: residuals too small for typical items
    if pr > 0 {
        score += 15.0 * (1.0 - pr / (item_size.max(1) as f64)).max(0.0);
    }

    // Last-chance bonus (smooth, not piecewise)
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 8.0 * last_chance * (1.0 + progress);

    // Lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.25 * diff;
        let perfect = 1.0 - (diff / cap).min(1.0);
        score -= 10.0 * perfect * perfect;
    }

    // Mild pressure toward consolidating into fewer bins
    score -= 2.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0)));

    // Mean residual deviation coupling
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: empty bin gets a mild opening cost that shrinks with progress
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class: post_residual bucketed by capacity fractions.
    // Residuals <= 10 are "dead space" (items are 1..100, but small residuals
    // are hard to fill); penalize them unless they're near-perfect.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction classes: e.g. post_residual <= cap/8, <= cap/4, <= cap/2 ...
    if post_residual <= bin_capacity / 8 {
        // small but nonzero residual: mild dead space penalty
        score += 30.0;
    } else if post_residual <= bin_capacity / 4 {
        score += 12.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 6.0; // sweet spot: room for medium items
    } else {
        score -= 10.0; // large residual kept: bin still flexible
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes are more likely to be exactly filled later.
    let common = [10u32, 20, 25, 50];
    let mut hit = 0u32;
    for &m in &common {
        if post_residual % m == 0 { hit += 1; }
    }
    score -= 8.0 * hit as f64;

    // Lookahead coupling: if next item fits exactly in post_residual,
    // reward this placement strongly (sets up a perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // next item fits: good, but leaves another residual
            score -= 15.0;
        } else {
            // next item won't fit here: if this bin is the only option,
            // opening a new bin for the next item is fine; slight penalty
            score += 5.0;
        }
        // Harmonic class of next item vs post_residual divisibility
        if next_item_size % 10 == 0 && post_residual % next_item_size == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item is large and all existing residuals are too small/fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral-ish base for a new bin; penalize mildly so we prefer
        // existing bins with decent fits, but allow it to win when
        // existing residuals are tiny.
        score += 20.0;
        // if item is huge relative to capacity, a fresh bin is attractive
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // many open bins with small mean residual: new bin is fine
        if mean_residual < 30.0 && open_bins_count > 3 {
            score -= 10.0;
        }
    }

    // Fragmentation guard: penalize placements leaving residual that no
    // typical item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0;
    }

    // Mild tie-break toward bins with residual close to item size
    // (tight fit), scaled by harmonic class.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 40.0 * tightness;

    // Slight preference for bins whose residual is in the same decade
    // class as the item (modulo-10 harmonic alignment).
    if bin_residual % 10 == item_size % 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    let min_item = 1.0f64;
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        // Dead space zone: the smaller (and thus more useless) the gap, the worse.
        score += (10.0 - gap) * 6.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but usable).
    if gap == 0.0 {
        score -= 40.0; // perfect closure of the bin
    } else if gap >= 10.0 {
        // Usable leftover: mild reward proportional to how much was consumed.
        let tightness = 1.0 - gap / bin_capacity as f64;
        score -= 8.0 * tightness;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin;
    // the empty-bin candidate has bin_residual == bin_capacity and gets penalized
    // so it only wins when fits are truly terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64 - gap).abs() < 0.5 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual < 10 {
        // gap can't serve the next item and is dead space anyway: extra penalty
        score += 10.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier fragment; closing it out is good.
    let dev = mean_residual - gap;
    if dev > 0.0 {
        score -= 0.5 * dev.min(50.0);
    }

    // Slight stream-progression bias: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that no typical item can use
        if post_residual < 10 {
            score += 60.0;
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item can chain into this bin: reward tight match
            score -= 80.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit: mild penalty proportional to mismatch
            score += 15.0 * (diff / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0 && next_item_size == 0;
        score += if poor_fit { 500.0 } else { 120.0 };
        // Early in stream, slightly discourage hoarding bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
    }

    // Prefer reusing bins among many open bins (reduce fragmentation)
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: tighter packing gets a strong discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    // (large post_residual) or when many bins are already open.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual >= 0 {
            // base new-bin score is post_residual = capacity; make it
            // unattractive unless current fits would leave big waste
            score += 0.0;
        }
    }

    // Prefer filling bins whose residual is close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more conservative (favor new bins
    // less); late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty (non-linear in post_residual)
    let mut score = 1.7 * pr + 2.4 * pr * norm_pr;

    // Smooth coupling of waste penalty with stream progress:
    // later in the stream, waste matters more (less chance to fill gaps)
    score *= 1.0 + 0.9 * progress * norm_pr;

    // Reward tight fits, scaled smoothly by remaining slack fraction
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 + 8.0 * progress;
    }

    // If next item fits exactly in post_residual, big reward (perfect chaining)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward for reusable residual
        let reusability = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * reusability * (1.0 - progress);
    }

    // Penalize bins far from mean residual (prefer homogeneity), smooth term
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: residual == capacity. Make it attractive only when
    // this placement would leave a large unusable gap elsewhere.
    if bin_residual == bin_capacity {
        // neutral baseline; slight cost grows with open bins to encourage consolidation
        score = 0.55 * cap + 2.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo buckets.
    let pr = post_residual;
    let class = pr % 10;

    // Penalize leftovers that are awkward for typical items (1..100): residuals
    // that are small-but-nonzero waste space; large residuals are reusable.
    if pr > 0 {
        // dead-space penalty grows for tiny leftovers
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // harmonic class bonus: residuals divisible by 10 align with capacity fractions
        if class == 0 {
            score -= 6.0;
        } else if class == 5 {
            score -= 2.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Integer-division thresholds: how well next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward proportionally to tightness
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 + (1.0 - slack / bin_capacity as f64) * 10.0;
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            score += ((next_item_size - pr) as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer filling bins when many are open (reduce fragmentation)
    let fill_frac = (bin_residual as f64) / (bin_capacity as f64);
    score += fill_frac * 5.0;

    // New-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let base = 55.0;
        // open a new bin if all existing fits would leave tiny dead space
        let bad_fit = pr > 0 && pr < 10;
        if bad_fit {
            score = base - 5.0;
        } else {
            score = base + (item_size as f64) * 0.2;
        }
    }

    // slight stream-progression drift: become more conservative late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that cannot fit
    // typical future items are wasted space -> heavy penalty.
    if post_residual > 0 {
        // A gap is "unusable" if it's below the minimum plausible item size
        // or cannot fit the lookahead item.
        if post_residual < 10 {
            score += 40.0; // tiny dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // cannot fit the next item
        } else {
            // usable gap: mild reward scaled by how reusable it is
            score -= 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Exact-fit lookahead bonus: placing here lets next item fill perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidates and spread).
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure
        score += 12.0 + 20.0 * pressure;
        // But if no open bin fits well, new bin is attractive
        if fitting_bins_count <= 1 && post_residual < 30 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, more so when bins are plentiful
        score -= 4.0 * pressure;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Late in the stream: consolidate into tightest fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins below mean residual (tighter than average) slightly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill leaves no dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly matches post_residual,
    // penalize when the next item cannot fit into the post-residual (dead space).
    if next_item_size > 0 {
        let post = post_residual as u32;
        if next_item_size == post {
            score -= 400.0;
        } else if next_item_size <= post {
            // next item fits: residual gets consumed, mildly good
            score -= 0.5 * (post - next_item_size) as f64;
        } else {
            // next item cannot fit: dead space of `post` remains
            score += 0.8 * post as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we pay for a fresh bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize opening a new bin when good fitting bins exist, especially
    // late in the stream when consolidation matters.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * progress;
    }

    // Slight preference for bins with less residual overall (tighter packing).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) already handled by score init.

    // Reward near-perfect fills strongly.
    if post_residual <= 2 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Penalize dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.1 * next_item_size as f64;
    }
    // If next item is large and this bin can't hold it afterward, mild penalty.
    if next_item_size > post_residual && next_item_size > 50 {
        score += 5.0;
    }

    // Time horizon: early in stream, be more liberal about opening new bins
    // (many items remain, fragmentation matters more); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax late.
        score += 40.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        // But if existing bins are very fragmented (high mean residual spread), allow new bin.
        if mean_residual > 40.0 {
            score -= 15.0;
        }
        // If next item is huge and won't fit with current item anywhere, new bin fine.
        if next_item_size > 60 && next_item_size + item_size > bin_capacity {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward using bins below mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Many open bins: discourage scattering; prefer filling existing bins.
    score += 0.05 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = pr;

    // Normalized post-residual (0 = perfect fill, 1 = empty bin).
    let x = pr / cap;

    // Non-linear polynomial coupling with stream progress:
    // late in the stream, dead space matters more -> amplify convex penalty.
    let w = 1.0 + 2.0 * progress * progress;
    score += w * (x * x * cap) * 0.5;

    // Reward tight fits super-linearly when the item nearly fills the bin.
    if pr < 10.0 {
        score -= (10.0 - pr) * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: make it attractive only when the item is large relative
    // to capacity or no good fit exists; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = cap * (1.0 - fill) + 5.0;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        if fill > 0.5 {
            score -= 8.0 * fill;
        }
    }

    // Lookahead: penalize placing here if it leaves a gap the next item
    // cannot use (next item > post_residual), reward if it fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 4.0 + 6.0 * progress;
        } else {
            score -= 2.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Mild penalty for scattering across many open bins relative to mean residual.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        let dev = (r - mean_residual) / cap;
        score += 2.0 * dev * dev * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 buckets.
    // Residuals that are "nice" multiples of 10 (or small) are more reusable.
    let pr = post_residual;
    let nice = pr % 10 == 0;
    let tiny = pr < 10;
    if tiny {
        score -= 60.0; // perfect fill, dead space minimal
    } else if nice {
        score -= 25.0; // reusable round residual
    } else {
        // penalize awkward leftovers proportionally to distance from a multiple of 10
        let d = (pr % 10) as f64;
        score += 3.0 * d;
    }

    // Integer-division thresholds: classify post_residual into harmonic thirds of capacity.
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;
    if pr < third {
        score += 12.0; // likely dead space
    } else if pr < half {
        score += 2.0;
    } else {
        score -= 8.0; // large residual stays usable
    }

    // Lookahead: if next item fits the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 30.0 + 0.5 * (pr - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize more if gap is small (wasted potential)
            let gap = (next_item_size - pr) as f64;
            score += 0.6 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // mean residual across open bins is low (open bins nearly full).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 20.0 * (0.25 - pressure);
        } else {
            score += 35.0 + 10.0 * pressure;
        }
    } else {
        // prefer tighter bins: closeness of item to residual
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio;
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio_fallback(bin_residual, bin_capacity));

    // Slight preference to keep number of open bins small.
    score += 0.5 * open_bins_count as f64;

    score
}

fn fit_ratio_fallback(bin_residual: u32, bin_capacity: u32) -> f64 {
    bin_residual as f64 / bin_capacity as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible item are pure waste; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual was already small (tight packing).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins early on.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: if the next item fits the post-residual well, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover: mild penalty proportional to waste.
        score += post_residual as f64 * 0.15;
    }

    // Mean-residual coupling: if this bin is far below average residual
    // (already dense), it is a good home for the item.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: make it unattractive unless current bins are
    // genuinely poor fits (handled above by dead-space / last-chance logic).
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 1.5;
        // Late in the stream, opening a fresh bin is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills post_residual -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits inside post_residual: mild reward scaled by how snugly it fits.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 15.0 - snug * 0.15;
    }
    // Next item would not fit here: penalize wasting space the next item could use.
    else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 12.0;
    }

    // Small dead space is bad (unusable sliver): penalize residuals 1..10.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize opening a new bin, unless current bin
    // would leave a large unusable residual and next item is large.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post-residual is good, but dead space below
    // the smallest plausible item is worse than exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post
    // residual, strongly reward; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            score += 2.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 0.05 * item_size as f64;
    }

    // Penalize spreading across many open bins when mean residual is low
    // (bins nearly full already): prefer consolidating into fuller bins.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * (1.0 + open_bins_count as f64 / 20.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (explore); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later.
        score -= 12.0 * (1.0 - progress);
        score += 15.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Global state coupling: high mean residual means bins are loose;
    // prefer reusing them over opening new ones.
    score += 0.03 * mean_residual * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with non-linear polynomial shaping
    let mut score = pr as f64;

    // Polynomial coupling of post residual with stream progress:
    // early on, prefer tight fills (low post residual); later, tolerate slack
    // to keep bins open for future items.
    let poly = x * x * (1.0 - progress) + x * (0.5 + 0.5 * progress);
    score += 12.0 * poly;

    // Reward tight fits super-linearly (dead-space avoidance)
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (1.0 - progress);

    // Penalize leaving residuals that are slightly larger than typical item sizes
    // (smooth dead-zone penalty around small-but-unusable gaps)
    let gap = pr as f64;
    let small_gap_penalty = (gap / cap) * (1.0 - (gap / cap)).max(0.0);
    score += 10.0 * small_gap_penalty * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 10.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // penalize creating a residual too small for the lookahead item
        score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
    }

    // Mild penalty for spreading across many open bins (encourage consolidation)
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: prefer opening a new bin early (plenty of stream left),
    // penalize it late unless residual of open bins is very poor.
    if bin_residual == bin_capacity {
        score = cap - 20.0 * (1.0 - progress) + 25.0 * progress
            - 5.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are "usable" classes; odd fragments are dead space.
    let mut class_bonus = 0.0f64;
    if post_residual == 0 {
        class_bonus -= 40.0; // perfect fill
    } else {
        if post_residual % 50 == 0 { class_bonus -= 18.0; }
        else if post_residual % 25 == 0 { class_bonus -= 12.0; }
        else if post_residual % 20 == 0 { class_bonus -= 10.0; }
        else if post_residual % 10 == 0 { class_bonus -= 7.0; }
        else if post_residual % 5 == 0 { class_bonus -= 3.0; }
        else { class_bonus += 6.0; } // awkward fragment

        // Small unusable dead-space pockets are penalized (too small for min item 1..100 range).
        if post_residual < 10 {
            class_bonus += 15.0;
        }
    }
    score += class_bonus;

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or in a good harmonic class.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 8.0; }
            score -= (slack as f64).min(20.0) * 0.2;
        } else {
            score += 10.0; // next item won't fit here; deprioritize slightly
        }
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a large item with poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let new_bin_score = 55.0
            - item_size as f64 * 0.3
            - crowd * 2.0
            - progress * 10.0
            + if next_item_size > 0 && next_item_size >= bin_capacity { 0.0 } else { 5.0 };
        return new_bin_score.max(1.0);
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Penalize bins far below mean residual (fragmented fleet).
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pre_residual = bin_residual as f64;
    let residual = post_residual as f64;
    let size = item_size as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mean_res = if mean_residual.is_finite() { mean_residual.max(0.0) } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = residual;

    // Prefer bins whose remaining space is below the current open-bin average.
    score += 0.025 * (residual - mean_res);

    // Reward tight placements, slightly more as the stream advances.
    score -= 18.0 * (size / pre_residual.max(1.0)) * (0.8 + 0.4 * progress);

    if residual < 0.5 {
        // Exact fill is highly desirable, especially when many bins are open.
        score -= 32.0 + 20.0 * (1.0 - progress) + 0.05 * open;
    } else {
        // Penalize tiny unusable gaps.
        let dead_floor = 10.0;
        if residual < dead_floor {
            let severity = 1.0 - residual / dead_floor;
            score += (30.0 + 60.0 * severity) * (0.45 + 0.55 * (1.0 - progress))
                + 0.5 * open * severity;
        }

        // Lookahead: penalize placements that strand the bin below the next item,
        // but mildly reward bins that can still accommodate it.
        if next > 0.0 {
            if residual < next {
                let miss = (next - residual) / capacity;
                score += 6.0 + 30.0 * miss + 12.0 * progress * miss;
            } else {
                score -= 3.0 + 0.08 * next;
            }
        }
    }

    if is_new_bin {
        let mut new_penalty = 16.0 + 1.3 * open + 20.0 * progress + 0.04 * mean_res;

        if fitting > 0.0 {
            // Opening a new bin while existing bins fit is usually costly.
            new_penalty += 16.0 + 4.0 * fitting.min(6.0);
            if fitting <= 1.0 {
                new_penalty += 18.0;
            }
        } else {
            // No open bin can fit, so a new bin is necessary.
            new_penalty -= 60.0;
        }

        if next > 0.0 {
            if residual + 0.5 >= next {
                // A new bin that can also host the next item is more acceptable.
                new_penalty -= 14.0;
            } else {
                new_penalty += 6.0;
            }
        } else {
            // Last item: strongly avoid opening another bin unnecessarily.
            new_penalty += 12.0;
        }

        score += new_penalty;
    } else {
        // Pressure toward using already-open bins, stronger late in the stream.
        score -= 1.5 + 0.45 * open + 3.0 * (1.0 - progress);

        // Last-chance fitting bin gets an extra bonus over opening a new bin.
        if fitting <= 1.0 {
            score -= 7.0 + 7.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: penalize small post_residual strongly.
    if post_residual > 0 {
        score -= 40.0 / post_residual as f64;
    } else {
        // Perfect fill.
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: match post_residual against next item size.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        let gap = post_residual as f64 - next_item_size as f64;
        // Reward exact chain match (post_residual == next_item_size).
        score -= 35.0 * (-gap / 15.0).exp();
    } else if next_item_size > 0 {
        // Chain broken: next item cannot use this bin's leftover.
        let miss = next_item_size as f64 - post_residual as f64;
        score += 12.0 * (miss / 20.0).min(3.0);
    }

    // Compare leftover against mean residual across open bins.
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty so we don't burn the best-fitting bin on a sloppy fit.
        score += 2.0 * fitting_bins_count as f64;
    }

    // Penalize leaving dead space (unusable slivers relative to smallest items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave a bad leftover; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Chain fits perfectly in a fresh bin: encourage.
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Late in the stream, prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Few open bins: keep them tight to limit total bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize small dead space that is hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // prefer bins where item fits more snugly among many options
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: if mean residual is high, prefer filling existing bins
    if mean_residual > 30.0 {
        score -= 0.05 * mean_residual;
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: make empty bin moderately attractive only when current
    // bin would leave very wasteful residue
    if bin_residual == bin_capacity {
        if post_residual < 20 {
            score -= 25.0; // item nearly fills a fresh bin alone
        } else {
            score += 10.0 + 0.2 * post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Early on, waste is cheaper; late, dead space is costly.
    let mut score = pr * (1.0 + 2.5 * progress * x) + 30.0 * x * x * (0.4 + progress);

    // Reward tight fits: post_residual near zero gets a bonus.
    let tight = 1.0 - x;
    score -= 25.0 * tight * tight * tight * (0.5 + progress);

    // Penalize residuals that are too small for the lookahead item (wasted for next item).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 12.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            // Reward bins that can also fit the next item.
            score -= 8.0 * (pr - nx) / cap * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // Many open bins: discourage spreading; few open bins: encourage consolidation.
    let ob = open_bins_count as f64;
    score += 1.5 * ob * x * (1.0 - progress);

    // Deviation from mean residual: prefer bins that keep residual distribution tight.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: baseline cost so it's chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + 20.0 * progress + 5.0 * (1.0 - tight);
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx <= cap - item_size as f64 {
                score -= 6.0; // new bin pairs well with next item too
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10-integer-wide classes.
    let leftover_class = post_residual / 10;
    // Reward placements that land the leftover into a "useful" class.
    // Classes divisible by 4 (0, 40, 80 residual) are highly reusable for mid-size items.
    if leftover_class % 4 == 0 {
        score -= 6.0;
    } else if leftover_class % 2 == 0 {
        score -= 2.0;
    } else {
        // Odd classes (residuals like 11..19, 31..39) are dead-space prone: penalize.
        score += 3.0;
    }

    // Perfect fit or tiny remainder is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Leftover below the minimum item size is pure dead space unless bin is nearly full.
        score += 8.0;
    }

    // Harmonic check on next_item_size: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: strong reward, scaled by how "classy" the fit is.
            let next_fit_class = (post_residual - next_item_size) / 10;
            score -= 10.0 + (next_fit_class as f64) * 0.5;
            // Bonus if next item exactly matches a harmonic division of capacity.
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: mild penalty, encouraging reserving space.
            score += 4.0;
        }
    } else {
        // Last item: just fill tightest bin.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Brand-new empty bin candidate: neutral-ish baseline; open only when
    // no open bin offers a decent fit (residual after placement would be small).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 15.0;
        // But if current open bins would all leave large awkward leftovers, opening is fine.
        if mean_residual < (item_size as f64) * 1.2 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer tighter existing bins: subtract proportional fill.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Penalize bins whose residual is far from the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Many open bins: prefer consolidation.
    if open_bins_count > 8 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still host the lookahead item (or nothing useful otherwise).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (8.0 + 12.0 * progress);
    score += pressure * (mean_residual / bin_capacity as f64) * 10.0;

    // New-bin candidate: discourage unless current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        score += 55.0 - 45.0 * crowd;
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if the NEXT item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-step match: post residual exactly consumed by next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.35;
        } else {
            // Next item won't fit after this placement: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.5;
        }
    }

    // Penalize dead space below the minimum item size (unusable residual).
    if post_residual < 1 {
        score += 100.0;
    }

    // Relative-to-mean coupling: prefer bins with residual near or below the mean
    // (tighter bins first keeps large residuals available for large items).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - res) * 0.10;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit
    // or the stream is early / many bins already open with fragmented residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a new bin is penalized mildly; it becomes attractive only when
        // open bins are highly fragmented (high mean residual) late in the stream.
        let new_bin_penalty = 40.0 + 55.0 * (1.0 - fragmentation) * (1.0 - 0.5 * progress);
        score += new_bin_penalty;
        // If the next item is large and current fragmentation is high, ease the penalty.
        if next_item_size > 0 && (next_item_size as f64) > fragmentation * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Small exact-fit reward: leaving a tiny residual is bad unless it's zero.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later on, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 + progress);
    }

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 6.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Next item can't use this residual: penalize proportionally to leftover gap.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        score += 30.0 + 0.5 * avg_waste - 10.0 * progress;
        // Opening a bin is cheap when many items remain to fill it.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score -= 5.0 * (remaining / (total_items.max(1) as f64));
    }

    // Crowd control: when many bins are open, prefer filling existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is close to item needs.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr + 8.0 * poly * cap.sqrt();

    // Penalize near-empty placements that waste large residuals
    let waste = if pr > 0 { (pr as f64).ln() } else { 0.0 };
    score += 3.0 * waste * (1.0 - progress);

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: prefer bins whose leftover matches the next item
    if next_item_size > 0 {
        let diff = (pr as i64 - next_item_size as i64).abs() as f64;
        score += 0.15 * diff * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: smooth quadratic coupling
    let dev = norm_pr - mean_residual / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // --- Harmonic / modulo classes on post_residual ---
    // Residuals that are dead space (cannot hold even the smallest plausible item)
    if pr > 0 && pr < 10 {
        score += 60.0;
    }
    // Modulo-20 class: residuals near multiples of common item sizes pack better later
    let m = (pr % 20) as f64;
    score += m * 0.6;

    // --- Exact-fit reward (perfect packing) ---
    if pr == 0 {
        score -= 50.0;
    }

    // --- Lookahead coupling: does the next item fit here? ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 18.0;
            // chain fit: next item also lands in a good modulo class
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // this placement strands the next item
            score += 12.0;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // baseline penalty: prefer filling existing bins
        score += 25.0;
        // but if current bin would leave bad dead space, opening fresh is fine
        if pr > 0 && pr < 10 {
            score -= 70.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // --- Relative tightness vs mean residual ---
    score += (mean_residual - bin_residual as f64) * 0.15;

    // --- Capacity fraction thresholds ---
    let frac = post_residual as f64 / cap;
    if frac < 0.05 {
        score -= 20.0; // nearly full bin is excellent
    } else if frac > 0.7 {
        score += 8.0;  // wasteful large leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that can never be filled by even the smallest item (1..=100 range)
    // is pure waste. Penalize gaps below the typical minimum item size heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // impossible gap
    }
    // Small unusable-ish gaps (below ~10, the classic minimum) get graded penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (low post_residual) super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Open-bins pressure: with many open bins, prefer filling existing bins
    // over opening new ones; add pressure to the new-bin candidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and
        // when this bin is not the only fitting option.
        score += 25.0 + bin_pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: opening a new bin is fine
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it.
        score -= 30.0 + bin_pressure;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this placement (perfect two-item packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we leave a gap
        // smaller than next_item_size (dead space for the lookahead item).
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mild preference for bins below mean residual (keeps residual spread tight).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly or nearly accommodate the next item (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: post_residual consumed entirely by next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward closeness of the fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 35.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize wasted potential,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.3 * miss;
        }
    } else {
        // Last item: just prefer tightest fit (small post_residual).
        score += 0.0;
    }

    // Prefer bins whose residual is below the mean residual (tight bins used
    // first, loose bins kept for large future items).
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when item is huge relative
    // to typical residuals; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        // Baseline competition value ~ a mediocre fit.
        score = 55.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0; // never prefer new bin if an open bin is last chance
        }
    }

    // Mild stream-progression pressure: early on, be more open to new bins
    // (cheap), late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward small post-residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (score new-bin candidate relatively better); later, consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus penalty growing with time and open bins.
        score += 15.0 + 40.0 * t + 2.0 * open_bins_count as f64;
    } else {
        // Existing bin: mild consolidation reward later in the stream.
        score -= 8.0 * t;
    }

    // Global residual dispersion: if this bin is much tighter than average,
    // prefer filling it now to avoid stranding small residuals.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Prefer bins with less residual overall (best-fit flavor), scaled by openness.
    score += 0.05 * bin_residual as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fits are good: penalize residual quadratically relative to capacity.
    score += 0.8 * (pr / cap).powi(2) * cap;

    // Stream-progress coupling: later in the stream, prefer bins with small post_residual
    // even more strongly (smooth non-linear interaction).
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * (pr / cap) * 10.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * t;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 15.0 - 0.1 * slack;
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 0.05 * (nxt - pr).min(cap);
        }
    }

    // Prefer bins with below-average residual (concentrate fullness).
    let mr = mean_residual;
    if pr < mr {
        score -= 0.3 * (mr - pr);
    } else {
        score += 0.3 * (pr - mr);
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.15 * (open_bins_count as f64) * (pr / cap);

    // New-bin candidate: make empty bins moderately attractive only early or when
    // nothing fits well; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score += 12.0 + 18.0 * t + 2.0 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create dead-space classes.
    let post = post_residual as i64;
    let residue = (post % 10) as f64;
    // Penalize awkward residues (small but nonzero waste is worst: 1..9 unusable for small items).
    if post > 0 {
        score += (residue - 5.0).abs() * 0.8; // residue 0 or 10 multiples are good, 5 is neutral
        // Perfect fills heavily rewarded.
        if post == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post as u32 {
            score -= 45.0;
        } else if next_item_size <= post as u32 {
            let nxt_res = post - next_item_size as i64;
            // Harmonic check: does the pair leave a clean residue?
            if nxt_res % 10 == 0 {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: penalize slightly, more if post_residual is tiny.
            if post < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // More attractive early in the stream or when open bins are congested.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Reward using bins with low residual (tight packing), scaled by congestion.
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * (open_bins_count.min(20) as f64 / 20.0);
    }

    // Prefer bins whose residual is below mean (well-utilized).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Item-size harmonic class: large items should prefer emptier bins.
    if item_size > 50 && bin_residual != bin_capacity {
        score += (100 - bin_residual.min(100)) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1..~15) can use it.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0; // up to +120 for 1-unit slivers
    }

    // Reward near-perfect fills (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual >= 11 && post_residual <= 30 {
        score -= 8.0; // still a very usable window
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 15.0;

    // Pressure from number of open bins: discourage scattering across many bins.
    score += (open_bins_count as f64).powf(0.9) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 10.0; // next item just misses: gap likely wasted
        }
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer new bin
    // when all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        score = 55.0 - tightness * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin anyway
        }
    }

    // Slight drift with stream progression: later in stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can't hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
        } else {
            score -= 3.0; // next item can reuse this bin's leftover
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.15 * item_size as f64;
    }

    // When many bins are open, consolidate; when few, allow spreading.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.5 * pressure * (post_residual as f64 / 100.0);

    // Deviation from mean residual: prefer bins that are either very full
    // or very empty relative to the fleet average.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: later in the stream, be more conservative (favor tight fits),
    // early on allow more exploration of fresh bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 2.0 * (1.0 - fit_ratio);
    score -= t * 5.0 * (1.0 - fit_ratio);

    // New empty bin candidate: only attractive when the item is large relative
    // to capacity or no bin fits well.
    if bin_residual == bin_capacity {
        score += 6.0 - 0.05 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: squared post-residual (dead space penalized super-linearly)
    let mut score = fit_frac * fit_frac * 100.0;

    // Smooth polynomial coupling with stream progress:
    // late in the stream, residual waste matters more; early, consolidation matters
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = fit_frac * (1.0 + 2.0 * p2 + 3.0 * p3);
    score += coupling * 40.0;

    // Reward tight fits smoothly: subtract when post_residual is small relative to item
    let tightness = 1.0 - fit_frac;
    score -= tightness * tightness * 30.0;

    // Last-chance bonus: only one fitting bin -> reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize crowding when many bins are open and mean residual is high
    let openness = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).clamp(0.0, 1.0);
    score += openness * (mean_residual / cap).clamp(0.0, 2.0) * 8.0;

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth bump)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        let bump = (-diff * diff / (2.0 * 30.0 * 30.0)).exp();
        score -= bump * 35.0;
        // penalize leaving residual that next item barely misses
        let near_miss = (-(pr - nxt).abs() / 15.0).exp();
        score += near_miss * 10.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly higher so good fits win
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left after placement

    // Reward placements that leave post_residual in "harmonic" classes:
    // classes 0 (perfect fit), 1/4, 1/2, 3/4 are reusable by typical items.
    let quarter = cap / 4.0;
    let class_targets = [0.0, quarter, 2.0 * quarter, 3.0 * quarter];
    let mut min_class_dist = f64::MAX;
    for t in class_targets.iter() {
        let d = (post_f - t).abs();
        if d < min_class_dist {
            min_class_dist = d;
        }
    }
    score += 0.8 * min_class_dist;

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Integer-division harmonic classes on post_residual (buckets of 10).
    let bucket = post_residual / 10;
    let bucket_bonus = match bucket {
        0 => -6.0,
        1 => -3.0,
        2 => -1.5,
        3 => 0.0,
        4 => 1.0,
        5 => 2.0,
        6 => 3.0,
        7 => 4.5,
        8 => 6.0,
        9 => 8.0,
        _ => 10.0,
    };
    score += bucket_bonus;

    // Lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 8.0;
        } else if gap <= 10 {
            score -= 5.0;
        } else if gap <= 25 {
            score -= 2.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use: penalize proportionally
        score += 0.15 * post_f;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-high so it is
    // chosen only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * (open_bins_count as f64);
        // If the current item is large and would leave a bad residual anyway,
        // a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // Prefer fuller bins (low residual before placement) mildly.
    score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0) / cap;

    // Late in stream: consolidate, avoid spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.3 * progress * (open_bins_count as f64).max(1.0) * 0.1;

    // Deviation from mean residual: bins far from mean get slight penalty
    // to keep residual distribution tidy.
    score += 0.05 * (post_f - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing can use are heavily penalized.
    // Any residual below the minimum possible item size (1) is impossible, but
    // small gaps (<= 10) are practically unusable for typical items; penalize hard.
    let dead = if post_residual == 0 {
        -30.0 // perfect fit: strongly reward
    } else if post_residual < 10 {
        60.0 // tiny unusable sliver
    } else if post_residual < 20 {
        25.0
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits relative to bin fill.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize wasting a large residual on a small item (poor utilization).
    if post_residual > bin_residual / 2 && bin_residual < bin_capacity {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized as bins accumulate.
        score += 10.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
        // If a new bin enables the lookahead item to fit perfectly, soften.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        }
    } else {
        // Existing bin that also accommodates the lookahead item is valuable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0;
        }
        // Mild pressure to consolidate into fewer bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer bins with residual below the mean (consolidate small remainders).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
