pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }

    // Lookahead: penalize if next item cannot fit in post_residual but could
    // fit elsewhere, mild penalty; reward if it fits.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            score += 2.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // New-bin candidate handling: prefer opening a new bin only when the
    // current item is large relative to capacity or open bins are congested.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 18.0
            - 8.0 * (item_size as f64 / bin_capacity as f64)
            - 4.0 * congestion
            - 6.0 * progress;
        // If next item is large, a fresh bin may serve both better.
        if next_item_size >= 50 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is close to item_size (best-fit bias).
        let waste = (bin_residual - item_size) as f64;
        score += 0.02 * waste;
        // Slight preference for bins below mean residual (filling emptier bins
        // of the population keeps spread balanced).
        score -= 0.01 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth non-linear penalty on waste
    let mut score = pr as f64;
    score += 18.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth coupling of post-residual with stream progress: tolerate slack early,
    // penalize it late (bins get locked in as stream ends)
    score += 25.0 * norm_pr * progress * progress;

    // Interaction with mean residual: penalize bins that deviate from the pack norm
    let dev = (mean_residual - pr).abs() / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    } else {
        score += 6.0 / fitting_bins_count.max(1) as f64;
    }

    // Lookahead: reward leaving room for the next item (smooth hinge)
    let n = next_item_size as f64;
    if n > 0.0 {
        let slack_fit = (pr - n) / cap;
        if slack_fit > 0.0 {
            score -= 12.0 * slack_fit * (1.0 - slack_fit).max(0.0);
        } else {
            score += 8.0 * (-slack_fit);
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make empty bins attractive only when residuals are poor
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score = cap - 30.0 * avg_waste * (1.0 - progress) + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: modulo-10 class determines dead-space quality.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals whose harmonic class is a "usable" small remainder are rewarded.
    match class {
        0 => score -= 12.0,               // perfectly divisible residual
        1 | 2 | 3 => score -= 6.0,        // near-perfect, tiny waste
        4 | 5 | 6 => score -= 2.0,        // mid-class
        7 | 8 => score += 4.0,            // awkward gap
        _ => score += 8.0,                // class 9: worst dead space
    }

    // Integer-division thresholds: residuals below 10 are nearly dead weight.
    if pr < 10 {
        score += 15.0;
    } else if pr < 20 {
        score += 5.0;
    } else if pr >= 50 {
        score -= 5.0; // large residual still flexible
    }

    // Lookahead coupling: if next item exactly fills post_residual (harmonic match), reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next fits: reward proportional to how well it divides the residual
            let ratio = next_item_size as f64 / pr as f64;
            score -= 6.0 * ratio;
            // modulo harmony between next item and post-residual
            if pr % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: penalize tight residuals more
            score += 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer it only when current residuals are poor.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // base new-bin cost, discounted as open bins get crowded
        score = 55.0 - 30.0 * pressure;
        // late in the stream, closing out is cheaper than opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size >= 40 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Crowd penalty: many open bins with high mean residual suggests fragmentation.
    if open_bins_count > 4 && mean_residual > 40.0 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: post_residual in (0, 10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using bins that would otherwise be "wasted" space relative to mean.
    if (bin_residual as f64) > mean_residual {
        score -= 8.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // (new bin candidate has bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 4.0;
        // But if this bin is the last chance, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= open_bins_count as f64 * 4.5;
        }
    }

    // Last-chance fitting bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post_residual exactly, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual, mild penalty for stranding it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Early stream: be more tolerant of tight fits to build good bins;
    // late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base term).
    // Strongly penalize dead space that is too small for typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0; // unusable sliver
        } else {
            // usable leftover: mild reward scaled by how well it matches mean residual
            score -= (bin_capacity as f64 / dead).tanh() * 5.0;
        }
    } else {
        score -= 60.0; // perfect fill
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of that fit
            let second_fit = post_residual - next_item_size;
            score -= (second_fit as f64).recip() * 20.0;
        } else {
            // next item won't fit here: penalize proportionally to overflow
            let over = (next_item_size - post_residual) as f64;
            score += over.min(40.0) * 0.5;
        }
    }

    // Compare residual to mean residual across open bins.
    // Prefer placing into bins with residual above the mean (keep tight bins for tight fits).
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // item is large relative to capacity or few fitting bins exist.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 25.0; // prefer existing bins for small/medium items
        }
    }

    // Early in stream: slightly favor consolidating (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space that no realistic item can fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual > 80 {
        score += 5.0; // large residual is fine, mild penalty to prefer fuller bins
    }

    // Lookahead: if the next item can still fit after this placement, reward;
    // if this placement blocks the next item while another bin could host both, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // blocking penalty scaled by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // If many bins fit the item, mild penalty for using scarce large residual space.
    if fitting_bins_count > 1 && post_residual > item_size as f64 as u32 {
        score += 3.0;
    }

    // Global state: prefer filling bins when many are open with high mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= mean_residual * 0.05 * progress;
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (residual == capacity means fresh bin). Penalize opening new bins early,
    // reward late in the stream to consolidate.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score += 15.0 * early + open_bins_count as f64 * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin keeps full flexibility
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + t);
    score -= 18.0 * norm_pr * t * (1.0 - t);

    // Penalize dead space that cannot fit the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let gap_norm = gap / cap;
        score += 25.0 * gap_norm * gap_norm;
        // Reward post-residual that exactly or nearly fits the lookahead item
        let fit_gap = (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * (1.0 - fit_gap) * (1.0 - t);
    }

    // Last-chance bonus: strongly favor filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual across bins (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Encourage closing out nearly full bins as stream progresses
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets
    let post_class = post_residual % 10;
    // Dead-space penalty: post residuals that are tiny but nonzero are the worst
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    } else {
        // Reward residuals likely to host future items (multiples of 10)
        if post_class == 0 {
            score -= 12.0;
        } else {
            score += post_class as f64 * 0.8;
        }
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item cannot fit here: penalize proportionally to wasted residual
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer division threshold on post_residual / item_size ratio
    let ratio = post_residual as f64 / (item_size.max(1) as f64);
    if ratio >= 1.0 {
        score -= 8.0; // bin could hold another item of this size
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Fractional capacity coupling: tightness of fit
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Stream progression: later in stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    if open_bins_count > 8 {
        score -= 3.0; // discourage opening yet more bins when many are open
    }

    // Mean residual context: if this bin's residual is far below mean, it is already fragmented
    let dev = mean_residual - post_residual as f64;
    score += dev.abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 80.0;
    } else {
        // Reward leaving a gap that can plausibly host typical small items.
        if post_residual >= 10 {
            score -= 8.0;
        }
        // Penalize very large leftover less than tiny leftover but still mildly.
        score += (post_residual as f64) * 0.05;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for a near-exact lookahead fit.
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: dead space penalty.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced packing).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.1;

    // Early stream: slightly prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // New-bin candidate: make empty bin attractive only when existing fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted residual quadratically (dead space is bad).
    score += 0.15 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if next <= post {
            // Next item fits here: strong reward for tight two-item packing.
            score -= 20.0 * (1.0 - diff / (bin_capacity as f64));
            if diff < 1.0 {
                score -= 30.0; // perfect 2-item chain
            }
        } else {
            // Next item won't fit here; penalize leaving residual close-but-below next size.
            let gap = next - post;
            if gap <= 10.0 {
                score += 12.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Reward tight fits relative to bin residual (first-fit-decreasing spirit).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness * tightness;

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if the item is large and no tight fit exists, new bin is fine.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in the stream, avoid spreading into new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Slight penalty per number of open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0 * (1.0 - gap as f64 / cap);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty for wasting capacity.
        score += 4.0;
    }

    // Prefer bins with below-mean residual (keep big holes for big items).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (new-bin candidate gets a discount); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus early-stream discount.
        score = cap * 0.9 - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pair large items together in fresh bin
        }
    } else {
        // Existing bin: late-stream consolidation bonus.
        score -= 10.0 * progress;
        // Prefer bins that are relatively full already.
        score -= 8.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping
    let mut score = pr;

    // Polynomial coupling: post_residual interacts with stream progress.
    // Early in stream: quadratic term dominates (keep bins flexible).
    // Late in stream: cubic term rewards near-zero residuals more aggressively.
    let quad = norm_pr * norm_pr * (1.0 - progress) * cap * 0.5;
    let cubic = norm_pr.powi(3) * progress * cap * 0.3;
    score += quad + cubic;

    // Lookahead: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // Dead space for the next item; penalize proportionally to gap,
            // softened as stream progresses.
            score += (nxt - pr) * (1.0 + 0.5 * (1.0 - progress));
        } else {
            // Reward residuals that leave room for the next item,
            // stronger reward the tighter the leftover after next placement.
            let after_next = pr - nxt;
            score -= (cap - after_next) * 0.1 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.75;
    }

    // Mild penalty when this bin is far below mean residual (fragmentation avoidance),
    // scaled by open bins count.
    if open_bins_count > 1 {
        let dev = (mean_residual - pr) / cap;
        score += dev.abs() * cap * 0.05;
    }

    // New-bin candidate bias: slightly discourage opening a new bin unless
    // residuals across open bins are large.
    if bin_residual == bin_capacity {
        score += cap * (0.1 + 0.2 * (1.0 - progress)) - mean_residual * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: capacity fractions that are
    // "usable" (>= smallest plausible item) are rewarded; tiny dead space
    // classes are penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // Dead space: unusable sliver.
        score += 120.0;
    } else if pr <= 25 {
        // Small but plausibly fillable residue.
        score -= 15.0;
    } else if pr <= 50 {
        // Mid residue: half-bin class.
        score -= 5.0;
    }

    // Modulo-class structure on post_residual: residues divisible by
    // common item granularities (5, 10) are more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly prefer this bin (chains two perfect fits).
    if next_item_size > 0 && next_item_size == pr {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item still fits after this placement.
        score -= 25.0;
        // Integer-division threshold: if post-residual can hold the next
        // item more than once (large residue), extra reward.
        if pr / next_item_size.max(1) >= 2 {
            score -= 20.0;
        }
    } else if next_item_size > pr && next_item_size > 0 && pr > 0 {
        // This bin will be dead for the next item: penalize mildly,
        // unless it was a perfect fit now.
        score += 18.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // If many bins are open with slack, discourage new bins.
        score += mean_residual * 0.3;
        // Late in the stream, opening new bins is riskier (less time to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // But if the current item is huge and would leave a bad residue
        // anywhere, a fresh bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0;
        }
    }

    // Mild global pressure: prefer tighter bins when many bins are open.
    score += (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable dead space -> heavy penalty.
            score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
        } else if post_residual < item_size {
            // Gap smaller than the current item: likely dead space too.
            score += 25.0;
            // But if it can still host the lookahead item, soften.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 15.0;
            }
        } else {
            // Usable gap: mild reward proportional to tightness of fit.
            let tightness = item_size as f64 / bin_residual as f64;
            score -= 20.0 * tightness;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0
            + 0.3 * open_bins_count as f64
            - (mean_residual - item_size as f64).abs() * 0.2;
        // Prefer new bin if the lookahead item is large (fresh capacity helps).
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // Reward matching residual to item (harmonic fit).
        score += 0.15 * (bin_residual as f64 - item_size as f64);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item almost fills the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 30.0).max(0.0);
    }

    // Penalize post residual that cannot fit the next item (dead space risk),
    // scaled by how close it came.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.35 * gap;
    }

    // Reward tight fits overall (small post residual).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize bins far below mean residual when many bins are open
    // (keeps residual profile balanced).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * (open_bins_count as f64).sqrt().min(3.0);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            100.0
        } else if next_item_size > 0 && next_item_size > bin_residual - item_size {
            0.0
        } else {
            15.0
        };
        score += 30.0 - desperation + (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    // Late-stream consolidation: favor filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

