    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Chain fit: post residual fits next item with room to spare.
        let chain_room = post_residual as f64 - next_item_size as f64;
        if chain_room >= 0.0 {
            score -= 4.0 * (chain_room / bin_capacity as f64);
        }
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // but allow it late in the stream or when mean residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 20.0 - 15.0 * progress + 10.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (consolidating emptier bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, but with a non-linear (quadratic) coupling
    // so that small residuals are punished super-linearly (dead space is bad),
    // while large residuals are relatively acceptable.
    let mut score = norm_pr * (1.0 + 1.7 * norm_pr * (1.0 - progress));

    // Smooth interaction: waste penalty grows as stream progresses
    // (early on, flexibility matters more than tightness).
    score += 0.9 * norm_pr * norm_pr * progress;

    // Tight fit reward: subtract when post_residual is small relative to item.
    let tightness = 1.0 - norm_pr;
    score -= 1.4 * tightness * tightness * (item_size as f64 / cap);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.5;
    } else {
        // Mild reward when few alternatives exist (smooth decay).
        let alt = (fitting_bins_count as f64).ln() + 1.0;
        score += 0.35 * (alt - 1.0);
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward this placement (chain-friendliness); smooth in size ratio.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr.max(1.0);
            score -= 1.1 * fit_ratio * (1.0 - fit_ratio) * 4.0 * fit_ratio.max(0.0);
        } else {
