    // Context terms: penalize bins far from the mean residual (non-linear),
    // encouraging residual homogenization across open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.6 * dev * dev;

    // Mild pressure against bin proliferation early in the stream,
    // decaying smoothly with progress.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) / (1.0 + progress);

    // New-bin candidate handling: an empty bin has norm_pr = 1.0; add a
    // smooth surcharge so it only wins when open bins are genuinely bad.
    if bin_residual == bin_capacity {
        score += 1.6 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Reward post-residuals near a quarter boundary (clean packing targets)
    let dist_to_boundary = class.min(quarter - class) as f64;
    score += dist_to_boundary * 0.35;

    // Integer-division threshold: dead space tiers
    if post_residual < bin_capacity / 10 {
        score -= 40.0; // nearly full bin is excellent
    } else if post_residual < bin_capacity / 4 {
        score -= 12.0;
    } else if post_residual > bin_capacity / 2 {
        score += 25.0; // leaving more than half empty is wasteful
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward proportional fit quality
        let frac = next_item_size as f64 / post_residual as f64;
        if frac > 0.8 {
            score -= 20.0 * frac;
        } else if frac < 0.25 {
            score += 8.0; // next item leaves awkward residue
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; penalize tiny leftovers less if residual is a common class
        let common = post_residual % 10 == 0;
        if common {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer it only when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of a new bin, discounted early in the stream
        let base = 55.0 - 20.0 * progress;
        score = base + item_size as f64 * 0.2;
        if mean_residual > (bin_capacity as f64) * 0.35 {
            score -= 15.0; // open bins are fragmented; fresh bin attractive
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 10.0; // big next item pairs well with a fresh bin
        }
    }

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64) * 0.05;

    // Mean residual context: when mean is high, prioritize consuming large residuals
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it's too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual >= 12 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bins pressure: prefer filling existing bins over opening new ones,
    // but relax pressure when many bins are open (avoid hoarding tiny residuals).
    let pressure = 18.0 - (open_bins_count.min(12) as f64) * 0.8;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += pressure + 6.0;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement; otherwise penalize leaving a gap next_item almost fills.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && (next_item_size - post_residual) < 12 {
            score += 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight stream progression term: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimal post_residual is best.
    score -= 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // 2-step lookahead: if the next item exactly fills the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here later; mild reward proportional to how well it fits
            let leftover = post_residual - next_item_size;
            score -= 15.0 * (1.0 - leftover as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit in this residual: penalize leaving awkward space
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap.min(40.0);
        }
    }

    // Compare post_residual against mean residual: avoid making bin much emptier than average
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, especially early/mid stream
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_f = open_bins_count as f64;
        score += 30.0 + 10.0 * (1.0 - progress) + 2.0 * open_f;
        // but if next item is large and no bin fits well, new bin is okay
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space, normalized.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Penalize very small post-residuals that become unusable dead space
    // (residuals below the smallest plausible item are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward for near-perfect two-item packing.
            let combined = post_residual - next_item_size;
            if combined < 10 {
                score -= 10.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits more aggressively.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Dynamic time horizon: early in the stream, keep bins flexible
    // (penalize low residuals); late in the stream, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if open bins have lots of slack on average,
    // discourage this bin from becoming another slack bin.
    if mean_residual > (post_residual as f64 + 1.0) {
        score += 1.5 * (mean_residual - post_residual as f64).min(50.0);
    }

    // Many open bins: encourage consolidating into existing bins rather
    // than leaving many partially filled bins.
    if open_bins_count > 4 {
        score -= 1.0 * open_bins_count.min(20) as f64 * (1.0 - waste_frac);
    }

    // New-bin candidate evaluation: only open a new bin if the item is large
    // and no bin fits well (score computed for empty bin = capacity residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Large items are fine in fresh bins; small items should use leftovers.
        score -= 0.5 * item_size as f64;
        // Late in the stream, opening bins is more acceptable.
        score -= 20.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 35.0;
        }
        // If next item is small, a fresh bin has flexible future use.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let tight = 1.0 - fit;

    // Base: prefer small post residual, with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early in the stream, small residuals are less valuable; later, tighten more.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.35 * progress_coupling;

    // Quadratic penalty on very small residuals (dead space), smoothly gated by progress.
    let dead = (1.0 - pr / cap).powi(2);
    score -= 12.0 * dead * (0.3 + 0.7 * progress);

    // Smooth interaction: reward tight fits more as stream progresses.
    score -= 8.0 * tight * tight * (0.2 + 0.8 * progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 6.0 * (1.0 - slack / cap) * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: smooth penalty proportional to mismatch.
        let mismatch = (next_item_size as f64 - pr) / cap;
        score += 4.0 * mismatch.min(1.0);
    }

    // Last-chance bonus (smooth, not hard threshold).
    if fitting_bins_count <= 1 {
        score -= 5.0;
    }

    // Mild penalty when bin residual deviates from mean residual (smooth dispersion term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Encourage consolidation when many bins are open.
    score -= 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // more likely to be fillable by future items (sizes 10..80), so reward
    // post_residuals that fall into "harmonic" classes.
    let pr = post_residual;
    let cls = pr % 10;
    let harmonic_bonus: f64 = match cls {
        0 => 6.0,
        1 | 9 => 3.0,
        2 | 8 => 1.5,
        3 | 7 => 0.5,
        4 | 6 => -0.5,
        _ => -1.5, // cls == 5 : worst dead-space class
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: small post_residual is tight packing,
    // but too small (< next item) is dead space unless next item fits.
    if pr == 0 {
        score -= 12.0; // perfect fill
    } else if pr < 10 {
        score -= 4.0; // small unusable gap, but bin nearly full
    }

    // Lookahead coupling: strongly reward when next_item_size fits exactly
    // or at least fits into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect two-step chain
        } else if next_item_size <= pr {
            score -= 5.0 * (next_item_size as f64 / (pr as f64 + 1.0));
        } else {
            // next item won't fit: penalize proportionally to wasted lookahead
            score += 2.0 * ((next_item_size - pr) as f64 / 10.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize a brand-new empty bin candidate unless current bins are crowded
    // or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.5;
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if !(crowded || big_item) {
            score += 25.0 * (1.0 - 0.3 * progress);
        } else {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced depletion),
    // with a mild coupling to open bin count.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 + open_bins_count as f64 / 20.0);

    // Tight-fit reward: residual barely above item size is excellent.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 10.0 * (1.0 - tightness).min(1.0) * tightness.max(0.0) * 2.0;

    // Harmonic class of item size vs bin residual: reward when both share
    // the same decade class (integer division match).
    if (item_size / 10) == (bin_residual / 10) && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can ever use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Small unusable-ish gaps (10..=20) are risky since min item is 10; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 60.0 * tightness;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }
    // Many fitting bins: slight pressure to keep flexibility, prefer tighter bins anyway.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: when many bins are open, discourage spreading into loose fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Lookahead coupling: if next item fits the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // If next item would be blocked by a wasteful small gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Mean-residual coupling: prefer bins whose post-residual sits near the mean
    // (keeps residual distribution homogeneous and packable).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: attractive early or when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && post_residual < 10 { 250.0 } else { 0.0 };
        score -= 40.0 + 30.0 * (1.0 - progress) + poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly into the resulting gap -> strong reward
        let exact = (post_residual as f64 - next_item_size as f64).abs();
        score -= 45.0 / (1.0 + exact);
        // bonus if next item fills bin almost perfectly
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this gap -> penalize wasted space, worse for small gaps
        let waste = post_residual as f64;
        score += waste * 0.5;
    }

    // Penalize leaving dead space that nothing (sizes 1..100) can reasonably use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0;
        // more attractive to open new bin late in stream for large items
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > bin_capacity / 2 {
            score -= 10.0 * progress;
        }
    }

    // Prefer filling larger residuals with larger items (tight packing)
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, amplified by fit scarcity.
    let tight_bonus = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= tight_bonus * 20.0;

    // Penalize dead space: post_residual that is too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting this bin's future.
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, keep flexibility (favor bins with larger residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;
    score -= (1.0 - progress) * 5.0;

    // Global state: many open bins with high mean residual -> discourage opening new bins.
    if bin_residual == bin_capacity {
        // Candidate is a brand-new bin.
        let new_bin_penalty = 15.0 + 0.3 * open_bins_count as f64 + 0.05 * mean_residual;
        score += new_bin_penalty;
        // But if item is huge and fits nowhere well, new bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins when many are open.
        score -= 0.1 * open_bins_count as f64;
    }

    // Alignment with mean residual: prefer bins whose residual is near the mean
    // (keeps residuals balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, with smooth non-linear decay
    let mut score = pr * (1.0 + 0.35 * progress) + 0.018 * pr * pr / cap;

    // Reward tight fits more aggressively as stream progresses (smooth coupling)
    let tightness = 1.0 - (pr / cap);
    score -= 22.0 * tightness.powf(3.0) * (0.5 + progress);

    // Lookahead: bonus if next item can reuse the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let reuse = 1.0 - (pr - nx) / cap;
            score -= 14.0 * reuse * (1.0 - progress * 0.5);
        } else {
            // penalize residuals that strand the next item
            score += 6.0 * (1.0 - (pr / cap).powf(2.0)) * (1.0 - progress);
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize spreading across many open bins when mean residual is large
    score += 0.25 * (open_bins_count as f64).ln1p() * (mean_residual / cap).max(0.0);

    // New-bin candidate: penalize opening a bin unless it enables a good future fit
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) * (mean_residual / cap);
        score += 16.0 + 8.0 * open_pressure - 12.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual.max(0.0) {
            score -= 10.0; // open bin when existing bins are too full for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into coarse buckets
    // via integer division thresholds on post_residual.
    let dead_class = post_residual / 10; // 0..=10 classes; 0 = perfect fit
    score += match dead_class {
        0 => -40.0,                 // perfect fill, heavily reward
        1 => -10.0,                 // small gap (<=10) still reusable for tiny items
        2 => 5.0,
        3 => 10.0,
        4 => 18.0,
        5 => 26.0,
        6 => 34.0,
        _ => 42.0,                  // large dead space, strongly penalize
    };

    // Modulo arithmetic on post_residual: gaps that are multiples of common small
    // item sizes (5,10) remain "harmonic" and reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward proportionally to how well next item uses the gap
        score -= 15.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // gap too small for next item: penalize proportionally
        score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the bin is already nearly full and next item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = dead_class >= 4 && post_residual > 0;
        if !bad_fit {
            score += 60.0 + 20.0 * progress;
        } else {
            score += 5.0;
        }
    }

    // Prefer fuller bins: coupling with mean residual.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Capacity-fraction coupling: reward placements leaving residual in the
    // "harmonic" band [0, 20) or exactly matching capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.2 {
        score -= 8.0 * (1.0 - frac * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 18.0;
    } else if post_residual <= 35 {
        score += 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tight fit relative to bin: reward filling most of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes progressively more expensive.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += 12.0 + 2.5 * obp;
    } else {
        // Favor existing bins slightly as pressure builds.
        score -= 1.5 * obp.min(10.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: mild penalty (dead space).
        score += 4.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a good consolidation target.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically: small post_residual is good.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // 2-step lookahead: strongly reward when the next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // Exact-ish match gets the biggest bonus.
            let slack = pr - nxt;
            let match_quality = 1.0 - (slack / bin_capacity as f64);
            score -= 60.0 * match_quality;
            // Extra reward for a near-perfect two-item chain fill.
            if slack <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Next item does NOT fit here: penalize proportionally to wasted lookahead.
            let gap = nxt - pr;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: bins tighter than the mean are better targets.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mildly discourage spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score += 2.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-averse unless the item is large
    // relative to residual (poor fits in tight bins then justify a fresh bin).
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus: residual becomes 0.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0; // this bin becomes dead space after placement
        }
        // If the next item would fit exactly in post_residual, big bonus.
        if post_residual == next_item_size {
            score -= 18.0;
        }
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // or the item leaves a very awkward remainder everywhere.
    if bin_residual == bin_capacity {
        let good_fit = (post_residual as f64 / bin_capacity as f64) < 0.25;
        if fitting_bins_count == 0 || (!good_fit && mean_residual < item_size as f64) {
            score -= 20.0;
        } else {
            score += 25.0; // prefer existing bins otherwise
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 3.0 * mean_residual / (open_bins_count as f64);
    }

    // Slight preference for filling older bins early in the stream.
    score -= 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late in the stream, weight dead space quadratically.
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += progress_weight * 40.0 * norm_post * norm_post;

    // Smooth interaction: penalize waste relative to mean residual across open bins.
    score += 0.15 * (post - mean_residual).abs() * (0.5 + progress);

    // Reward near-perfect fits with a smooth exponential-style term (no piecewise cutoffs).
    let fit_quality = 1.0 - norm_post;
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus, smoothly scaled by how much space would remain.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Lookahead coupling: if the next item fits the post residual, reward leaving that space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack_fit = if post >= nxt { 1.0 - (post - nxt) / cap } else { 0.0 };
        score -= 6.0 * slack_fit * slack_fit;
        // Penalize post residuals that are too small to ever be useful again.
        let min_useful = 10.0f64.min(nxt);
        if post < min_useful {
            score += 5.0 * (min_useful - post);
        }
    }

    // Mild dispersion pressure: many open bins with high mean residual -> consolidate.
    score += 0.02 * (open_bins_count as f64) * mean_residual * 0.01;

    // Slight bias against opening new bins when others fit, smooth in progress.
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (multiples of 10 and large residuals), penalize awkward dead space.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -30.0,                      // perfect fit
        p if p % 10 == 0 => -12.0,       // clean class
        p if p < 10 => 25.0,             // unusable sliver
        p if p >= 50 => -6.0,            // still versatile
        p if p % 5 == 0 => 0.0,
        _ => 8.0,                        // awkward class
    };
    score += class_penalty;

    // Integer-division thresholds: pair post_residual with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, scaled by tightness of the pair.
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
            if pr % next_item_size.max(1) == 0 && pr > 0 {
                score -= 8.0; // harmonic divisibility bonus
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            let waste = (next_item_size - pr) as f64;
            score += waste * 0.4;
        }
    } else {
        // Last item: prefer tightest packing anywhere.
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a needless new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize mildly, but allow it when current bin
    // would leave bad dead space relative to the item's harmonic class.
    if bin_residual == bin_capacity {
        let base = 14.0 + 0.05 * (open_bins_count as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Later in the stream, slightly prefer reusing bins.
        score = score + base * (1.0 - 0.3 * progress);
        if class_penalty < 0.0 {
            score += 6.0; // an existing bin would pack well; don't open new
        }
    }

    // Coupling with mean residual: prefer bins below mean residual
    // (tighter bins first), above-mean bins get penalized.
    let res_f = bin_residual as f64;
    score += (res_f - mean_residual) * 0.15;

    // Fraction-of-capacity harmonic tier of the item.
    let frac = item_size as f64 / cap;
    if frac > 0.5 {
        score -= 5.0; // big items should go in early
    } else if frac < 0.2 {
        score += 3.0; // tiny items are flexible, less urgency
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (1),
    // but practically: gaps too small for typical items (<= 10) are wasted.
    if post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 2.0; // heavily penalize tiny gaps
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling: penalize post_residual that cannot host the next item's size.
    if next_item_size > 0 {
        if post_residual < next_item_size as f64 {
            // gap unusable for the lookahead item -> dead space risk
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        } else {
            // gap can host the next item -> reward
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage scattering into many bins,
    // but give a bonus when this bin is the last chance (fitting_bins_count == 1).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    if fitting_bins_count == 1 {
        score -= 35.0; // last-chance bin: strongly favor using it
    }

    // Mild preference for bins tighter than the mean residual (good packing).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Prefer placing larger items into tighter bins (best-fit style coupling).
    score += (item_size as f64 / 100.0) * (bin_residual as f64 - post_residual as f64) * 0.05;

    // New-bin candidate handling: empty bin gets a moderate penalty so that
    // only clearly bad fits trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 12.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward when the leftover space
    // after this placement exactly matches the next item's size.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strongly subtract to prioritize this bin.
        if lookahead_gap == 0.0 {
            score -= 45.0;
        } else {
            // Penalize mismatch scaled by how far off the leftover is.
            score += 0.35 * lookahead_gap;
        }
        // If next item fits exactly into residual BEFORE this item, mildly reward
        // deferring this bin (keep big space for the big next item).
        if next_item_size == bin_residual {
            score += 12.0;
        }
    } else {
        // Last item: prefer minimal waste directly.
        score += 0.1 * post_residual as f64;
    }

    // Compare post_residual against mean residual: creating a much smaller
    // leftover than average is good (denser packing).
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item is
    // large relative to capacity or few bins are open.
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 25.0 * load_ratio - 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Slight penalty for leaving tiny unusable dead space (1..=5 units).
    if post_residual > 0 && post_residual <= 5 {
        score += 8.0;
    }

    // Mild preference for tighter fits overall (waste-relative term).
    score += 0.05 * (bin_residual - item_size) as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / cap;
    score += tightness * tightness * 40.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last chance: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's
    // genuinely useful (item large relative to residual, or no good fits)
    if bin_residual == bin_capacity {
        // baseline penalty for new bin
        score += 35.0;
        // If item is large, a fresh bin is more attractive
        let frac = item_size as f64 / cap;
        score -= frac * 30.0;
        // If few bins can fit, new bin is reasonable
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // Early in stream: new bins are cheap to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // even better if next item nearly fills the bin afterward
            let nxt_post = post_residual as f64 - next_item_size as f64;
            score -= (1.0 - nxt_post / cap) * 15.0;
        } else if next_item_size <= post_residual + 20 {
            score += 8.0; // near-miss: dead space risk for the next item
        }
    }

    // Prefer bins whose residual deviates below mean (consolidate fullness)
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Penalize leaving large awkward gaps (>50% residual) in mature stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > 0.5 * cap && progress > 0.5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * 20.0;
    // Reward tight fits, more strongly later in the stream
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (5.0 + 15.0 * progress);
    // Penalize dead space relative to mean residual
    score += (pr - mean_residual).abs() * (0.3 + 0.7 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }
    // Lookahead: reward leaving space close to next item size
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += diff * 0.4;
        if pr >= next_item_size as f64 && diff < 5.0 {
            score -= 3.0;
        }
    }
    // Mild penalty for opening a new bin when many bins fit
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + fitting_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quarters
    let q = bin_capacity / 4;
    let class = (post_residual % q) as f64;
    score += 0.6 * class;

    // Reward near-perfect fills (post_residual in lowest harmonic band)
    if post_residual <= q / 2 {
        score -= 18.0;
    }

    // Dead space penalty: residual too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a
    // much better pairing with the lookahead item
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // new bin can also host next item: mild bonus
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // lookahead won't fit with item in a fresh bin -> opening is wasteful
            score += 20.0;
        }
    }

    // Lookahead coupling: reward if next item exactly fills post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= q / 2 {
        score -= 8.0;
    }

    // Progress-scaled tightness bonus
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_residual as f64) * 0.15;

    // Prefer filling bins with larger residual when many bins are open
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Integer-division threshold: bins whose residual is at least half-capacity
    // are more flexible; slight penalty to keep them for larger future items
    if bin_residual >= bin_capacity / 2 && item_size < bin_capacity / 4 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space: heavy penalty, scaled by how tiny the gap is.
            score += (10 - post_residual) as f64 * 12.0;
        } else {
            // Usable gap: mild reward for larger leftover space, decaying.
            score -= ((post_residual as f64).ln() * 4.0).min(8.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (consolidate space into few bins).
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.05;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score += 6.0; // next item would leave dead space here
        } else {
            score -= 5.0;
        }
    }

    // Late in the stream, tighten up: penalize leaving any slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate bias: prefer reusing an existing bin unless it is
    // a very poor fit; make the empty bin slightly less attractive overall.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if opening a new bin avoids dead space in a nearly-full bin, relax.
        if bin_residual - item_size < 10 && post_residual >= 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight non-linear bonus.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: subtract proportional to how snugly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0) * 0.5;
        } else {
            // Chain break: penalize leaving post_residual that wastes the next item.
            score += 25.0;
        }
    }

    // Perfect closure bonus: exact fill.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize new-bin opening when mean residual across open bins is large
    // (fragmentation avoidance): make the empty-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3 + (open_bins_count as f64) * 1.5;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Slight preference toward bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 {
        let unusable = if next_item_size > 0 {
            (post_residual as f64) < (next_item_size as f64)
        } else {
            true
        };
        if unusable {
            score += 8.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // open bins are fragmented or the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 4.0 + 6.0 * progress - fragmentation * 0.05;
        // Avoid opening new bins when many bins are already open and loose.
        score += 0.15 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is close to the mean residual (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for fuller bins overall.
    score -= 0.02 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic in normalized post-residual, modulated by progress
    let mut score = pr * (1.0 + progress * norm_pr);

    // Smooth interaction: small post-residuals are increasingly valuable late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space, especially early (keep bins flexible)
    score += 4.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward exact-ish fits
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead coupling: smooth term favoring bins whose post-residual fits next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        let fit_next = ((pr - ni) / cap).max(0.0);
        score += 3.0 * fit_next;
        score -= 2.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild dispersion penalty: prefer bins near mean residual (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate handling: penalize slightly so it only wins on poor fits,
    // with the penalty easing as the stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: harmonic class 0 (post_residual divisible by 10)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual % 10 == 0 {
        score -= 25.0;
    }

    // Dead-space penalty for tiny unusable residuals (harmonic class 1..5)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward residuals that could fit a "typical" future item (harmonic bands)
    if post_residual >= 10 && post_residual <= 40 {
        score -= 10.0;
    } else if post_residual > 80 {
        score += 15.0; // wasteful large leftover
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 0.3 * (next_item_size as f64 - post_residual as f64).abs();
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 120.0
            - 10.0 * (open_bins_count as f64).ln().max(0.0)
            - 0.2 * mean_residual;
    }

    // Mild preference for filling larger gaps as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Modular threshold on item size: big items prefer tight fits
    if item_size > bin_capacity / 2 {
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1..10 range assumption -> use 10 as safe floor)
    // are almost certainly wasted; make them very expensive.
    let min_item = 10u32;
    if post_residual < min_item && post_residual > 0 {
        score += 60.0; // dead space penalty
    }

    // Perfect fit reward: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: quadratic bonus for small post residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize leaving a gap that just barely fails to fit the next item
    // (lookahead: if next item could have fit but won't after placement).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
            score += 25.0;
        }
        // Reward if the next item fits exactly in the post residual.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer tighter fits (already handled) but add
        // slight penalty to spread awareness of open-bin pressure.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Open-bins pressure: when many bins are open, discourage adding residual
    // fragmentation; when few bins are open, encourage consolidation.
    let open_pressure = (open_bins_count as f64).sqrt();
    score += 1.5 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual deviates strongly below the mean
    // (i.e., we're closing it out), that's good; if it stays far above mean, slight penalty.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res_f - mean_residual) / mean_residual;
        score += 3.0 * dev * (post_residual as f64 / bin_capacity as f64);
    }

    // Stream progression: late in the stream, be more conservative about residual waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
