pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual > 0 {
        score -= 8.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);
    } else {
        score -= 15.0; // perfect fill
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: favor bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Extra reward if next item fits exactly-ish
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 4.0;
        }
    }

    // Last-chance bonus: only fitting bin; strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate handling: generally penalize opening new bins,
    // but relax penalty when current bin fits are poor or many bins exist.
    if is_new_bin {
        let mut penalty = 12.0;
        // Poor fits among open bins (mean residual small relative to item) -> opening is OK
        if mean_residual < item_size as f64 {
            penalty -= 6.0;
        }
        // Late in the stream, consolidating is more valuable
        penalty += 6.0 * (1.0 - t);
        // Many open bins: prefer filling existing ones
        penalty += 0.5 * open_bins_count as f64;
        // Large item nearly filling a fresh bin is fine
        if item_size >= bin_capacity * 9 / 10 {
            penalty -= 8.0;
        }
        score += penalty.max(0.0);
    }

    // Mild preference for bins with larger residual when in doubt (keep small residuals for small items)
    score += 0.02 * bin_residual as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap; // 0..1 residual fraction after placement

    // Base: penalize leftover space, but with diminishing (quadratic) dead-space cost
    let mut score = post * (1.0 + fit_ratio * fit_ratio);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers; late in the stream, tighten packing.
    let tightness = 0.5 + 0.5 * progress; // smooth ramp 0.5 -> 1.0
    score += (post * post / cap) * (1.0 - tightness) * 2.0;
    score -= (post * post / cap) * tightness * 0.5;

    // Reward tight fits (small post_residual relative to item size)
    let fit_quality = 1.0 - fit_ratio;
    score -= fit_quality * fit_quality * item * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * fit_quality;
    } else if fitting_bins_count > 1 {
        // mild penalty for competing with many fitting bins unless very tight fit
        score += (fitting_bins_count as f64).ln() * 2.0 * (1.0 - fit_quality);
    }

    // Lookahead: if next item fits exactly into post_residual, reward; if it nearly fits, penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            if slack < 10.0 {
                score -= 8.0 * (1.0 - slack / 10.0); // perfect chain bonus
            } else {
                score += slack * 0.05; // wasteful leftover for next item
            }
        } else {
            // next item won't fit: mildly penalize leaving unusable gap
            score += (nxt - post).min(30.0) * 0.08;
        }
    }

    // Context: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 1 {
        let consolidation = (mean_residual / cap).clamp(0.0, 1.0);
        score -= fit_quality * consolidation * 6.0;
        score += (open_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate handling: empty bin gets a smooth penalty unless current fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 12.0 - 10.0 * poor_fit - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual in {0} -> perfect fit, huge reward.
    // Class 1: small usable leftovers (1..=10) -> mildly penalize (dead space).
    // Class 2: mid leftovers that fit small items (11..=30) -> slight reward.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else if post_residual <= 10 {
        score += 6.0; // dead space penalty
    } else if post_residual <= 30 {
        score -= 4.0;
    } else if post_residual <= 50 {
        score += 2.0;
    }

    // Modulo-10 harmonic: leftover divisible by 10 is more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // fraction of leftover consumed by next item
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * frac;
        } else {
            // next item won't fit here: leftover likely becomes dead space
            let gap = (post_residual - next_item_size.min(post_residual)) as f64;
            score += 2.0 * (gap / 10.0).min(3.0);
        }
    } else {
        // last item: prefer exact fill
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // early in stream, opening bins is cheaper; late, avoid waste
        score -= 20.0 * (1.0 - progress);
        // if many open bins with slack, discourage new bin
        score += (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill_ratio;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large leftover gaps only if they are too small for typical items,
    // otherwise mildly reward leaving room.
    if post_residual >= 10 {
        score -= 4.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits (gap within 10), slight penalty for stranding space.
    if next_item_size > 0 && post_residual >= 1 && next_item_size > post_residual && (next_item_size - post_residual) <= 10 {
        score += 8.0;
    }

    // Late in the stream, tighten packing: penalize residual more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Mild alignment with mean residual: prefer bins below-average residual (fuller bins).
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-5.0).min(5.0);

    // New-bin candidate: only attractive when no open bin leaves a good gap.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count >= 1 {
            score += 20.0; // extra penalty since existing bins could fit
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for a large upcoming pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize small leftover dead space (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Compare against mean residual: prefer bins with less residual than average
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the item is large relative to a fresh bin
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64) * 10.0;
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small post-residuals are dead space unless they can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // The leftover can accommodate the lookahead item: reward coupling.
        score -= (next_item_size as f64) * 0.6;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space too small for the next item: penalize proportionally.
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin when fits exist,
    // unless current bins would leave very fragmented space.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else {
            // Opening a new bin is acceptable if all fits are terrible (large dead space).
            let min_possible_dead = bin_residual.saturating_sub(item_size) as f64;
            if min_possible_dead > 25.0 {
                score -= 15.0;
            }
        }
    }

    // Prefer packing into bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Prefer bins with residual below mean residual (consolidating fuller bins).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Early in the stream, be more willing to open bins for large items;
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Many open bins: encourage closing them out by filling fullest bins first.
    if open_bins_count > 3 {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Large items deserve priority placement in roomy bins.
    if item_size >= 60 {
        score -= (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr.powf(1.35) * (1.0 + 0.35 * progress);

    // Smooth penalty for dead space near mid-range residuals (awkward gaps).
    let mid_gap = norm_pr * (1.0 - norm_pr);
    let awkward = 12.0 * (mid_gap - 0.25).abs() * (1.0 + progress);

    // Reward tight fits (small post_residual) with a smooth decay.
    let tight_reward = -18.0 * (-pr / 8.0).exp();

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            -6.0 * (-((pr - nxt).abs()) / 15.0).exp()
        } else {
            4.0 * ((pr - nxt) / cap).abs()
        }
    } else {
        0.0
    };

    // Mild penalty for leaving residual far from mean residual (fragmentation).
    let frag = 0.05 * (pr - mean_residual).abs();

    // Slight preference to fill existing bins over opening new ones late in stream.
    let open_bias = if bin_residual == bin_capacity {
        6.0 + 10.0 * progress
    } else {
        0.0
    };

    base + awkward + tight_reward + last_chance + lookahead + frag + open_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: dead-space classification
    let post = post_residual;
    let cls = post / 10; // integer division: class 0..10
    match cls {
        0 => score -= 25.0,             // near-perfect fit
        1 => score -= 15.0,
        2 => score -= 8.0,
        3 => score -= 3.0,
        4 => score += 1.0,
        5 => score += 3.0,
        6 => score += 5.0,
        7 => score += 7.0,
        8 => score += 9.0,
        _ => score += 11.0,
    }

    // Tightness reward: post_residual < 10 is a "sealed" bin
    if post < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item could exactly fill post_residual, big reward
    if next_item_size > 0 {
        if post >= next_item_size {
            let gap = post - next_item_size;
            if gap < 10 { score -= 22.0; }
            else if gap < 25 { score -= 8.0; }
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot
            score += ((next_item_size - post) as f64).min(15.0) * 0.5;
        }
    }

    // New-bin candidate handling: penalize opening a new bin, but allow it
    // when item is large relative to capacity or few bins fit it.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0; // base cost of opening a new bin
        if large_item > 0.6 { score -= 20.0; }       // big items deserve fresh bin
        if fitting_bins_count == 0 { score -= 35.0; } // no alternative anyway
        if mean_residual < 15.0 { score -= 10.0; }    // existing bins nearly full
        if post_residual < 20 { score -= 12.0; }      // fresh bin keeps usable space
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    if progress > 0.7 {
        score -= (post_residual as f64) * 0.1;
    }

    // Small global tie-breaker on mean residual alignment
    score += (mean_residual - post as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item can use
    // are pure waste. Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 8.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit: eliminate residual entirely — strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 25.0 * (fill_ratio - 0.7) / 0.3;
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // Extra pressure when many bins are already open.
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // New-bin candidate: only attractive when open bins are nearly full
    // (mean residual low) or the item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        score -= 20.0;
        // Penalize opening new bins when open bins have plenty of room.
        score += 0.9 * mean_residual.max(0.0);
        // But if the item is large and would leave a big gap elsewhere,
        // a fresh bin is fine.
        if item_size > 60 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 35.0;
        } else {
            score -= 15.0 * (1.0 - slack as f64 / post_residual.max(1) as f64);
        }
    }

    // Open-bins pressure: mildly discourage spreading across many bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            score -= 60.0 * (1.0 - gap / cap);
        } else {
            score += 25.0 + 40.0 * (gap / cap);
        }
    }

    // Penalize small dead space (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins with less residual (tighter bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: strong bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Slight preference to keep new bins closed early in the stream
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer filling nearly-full bins
    score -= 20.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less dead space is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 25.0;

    // Penalize dead space that becomes unusable (below the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item can fit in the post-residual, reward this placement;
    // otherwise penalize leaving space that blocks the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > bin_residual {
            // Next item won't fit here anyway; residual value is lower.
            score += 5.0;
        } else {
            // Next item fits now but not after placement: penalize blocking.
            score += 20.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Global state coupling: when many bins are open and mean residual is high,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln_1p();
    score -= consolidation * 10.0 * (0.5 + progress);

    // New-bin candidate: make an empty bin moderately attractive only when the item
    // leaves a "clean" residual (e.g. exactly divisible space) or fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let clean = if post_residual == 0 { 1.0 } else { 0.0 };
        score += 12.0 - clean * 20.0;
    }

    // Mild time-horizon adaptation: later in the stream, be more conservative
    // about leaving small residuals.
    score += tightness * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tight = (post_residual as f64 / cap).powi(3);
    score -= 40.0 * (1.0 - tight);

    // If the lookahead item fits into the post residual, reward keeping this bin
    // (chained packing), with a smooth coupling to stream progress.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = (next_item_size as f64 / cap) * (1.0 + 0.5 * progress);
        score -= 15.0 * chain;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving a sliver of dead space the next item can't use,
        // especially late in the stream when consolidation matters.
        let sliver = (post_residual as f64 / cap).powi(2);
        score += 12.0 * sliver * (0.5 + progress);
    }

    // Reward filling bins that are relatively empty vs the mean residual
    // (balance: avoid many half-empty bins), smooth polynomial coupling.
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * rel * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins
    // fit the item and early/mid stream.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
        score += 30.0 + 25.0 * open_pressure * (1.0 - 0.5 * progress);
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small dead space classes are penalized.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward tight fits: near-zero post residual is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize "awkward" residual classes that few item sizes (1..100) can fill:
    // residual in (50,60) or (10,20) mod ranges tends to be dead space.
    let r = post_residual;
    let cls = r % 25;
    if r > 0 && r < 10 {
        score -= 15.0; // small but usable leftovers are fine
    }
    if cls == 24 || cls == 23 {
        score += 8.0; // just-shy-of-a-quarter classes are awkward
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            score -= (10.0 * (1.0 - npost as f64 / 25.0)).max(0.0);
        } else {
            // next item cannot follow here; residual becomes dead space
            score += 6.0 + frac * 10.0;
        }
    } else {
        // Last item: any residual is final waste; prefer filling maximally.
        score += frac * 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 40.0 - pressure * 45.0 + frac * 0.0;
        // If some existing bin fits and mean residual is large, discourage new bin.
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 25.0;
        }
        // Late in stream, prefer consolidating.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for bins with low residual relative to the mean (fill fullest first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Progress-aware scaling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible future item are worthless. Penalize them super-linearly.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: strongly prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward heavily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading and
    // prefer tight fills; when few bins are open, allow opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 2.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // to consolidate packing.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // anywhere else (large post_residual elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let baseline = 15.0 + pressure * 2.0;
        score = score.min(baseline) - 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
