pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual dead space with a non-linear squashing.
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / (bin_capacity as f64);

    // Reward tight fits (small post-residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's genuinely useful.
    if bin_residual == bin_capacity {
        // Opening a new bin is worse when existing bins fit reasonably well.
        let fit_quality = (bin_residual - item_size) as f64; // 0 for the new-bin call itself
        let _ = fit_quality;
        // Cost grows with number of open bins (fragmentation pressure).
        score += 10.0 + 1.5 * open_bins_count as f64;
        // But if the next item is large and this bin would be nearly empty anyway,
        // opening is mildly attractive (reserve fresh capacity).
        if next_item_size > 0 && next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Lookahead synergy: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr <= post_residual as f64 {
            let gap = post_residual as f64 - nr;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward mid-size residue.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: high mean residual means open bins are loose;
    // prefer packing into loose bins (low score) when mean_residual is high.
    score -= 0.05 * mean_residual;

    // Slight preference for bins with residual close to item size (best-fit flavor)
    // combined with time horizon: early stream favors consolidation, late stream favors tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 12.0 * pr_norm * (1.0 - pr_norm) * (1.0 + progress);

    // Reward tight fits more strongly as stream advances
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + progress);

    // Penalize dead space: small nonzero residuals become less attractive late
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 15.0 * dead * (0.3 + progress);

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 25.0) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild dispersion pressure: prefer bins below mean residual (balance)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: make it appealing only for large items / poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space class: penalize residuals that are hard to fill later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic classes on post_residual (mod 10 buckets).
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -8.0,                       // perfectly reusable slot
        1 | 2 => 6.0,                    // awkward slivers
        3 | 4 | 6 | 7 => 2.0,            // mildly awkward
        5 => -3.0,                       // half-slot, reusable
        8 | 9 => 4.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Small residuals are dead space; large residuals are wasteful.
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fill
    }

    // Prefer tight fits: reward small post_residual relative to item size.
    score -= 5.0 * (1.0 - (item_size as f64) / cap) * (1.0 - pr / cap);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (npr as f64) / cap);
        } else {
            // next item won't fit here; penalize leaving large gaps
            score += 3.0 * pr / cap;
        }
    }

    // New-bin candidate handling: only open a new bin when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset by how bad the alternatives likely are.
        score += 30.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress; // slightly more willing to open bins early? keep conservative
        if next_item_size > 0 && next_item_size as f64 >= bin_residual as f64 * 0.9 {
            score -= 15.0; // next item is large; fresh bin useful
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    if open_bins_count > 2 && (mean_residual as u32) > bin_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals too small for the smallest item (1) are fine,
    // but residuals that are small relative to typical items are wasteful if the item is large.
    // Penalize leaving a "dead" gap that likely cannot be filled by upcoming items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space zone: post_residual in [1, 15] is usually unusable dead space.
    if post_residual >= 1 && post_residual <= 15 {
        score += 40.0 * (1.0 - progress);
    }

    // Reward tight fits: small post_residual (but nonzero) means near-perfect packing.
    if post_residual > 0 && post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins when few are needed,
    // encourage using existing bins as open_bins_count grows.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Next item won't fit here after placement; slight penalty if it creates dead space.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // leaving larger-residual bins for future large items.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: make empty bins slightly less attractive unless current bin
    // would leave bad dead space or the fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits exactly or well into this bin afterwards
            score -= 60.0 * (1.0 - diff / 100.0);
            if diff == 0.0 {
                score -= 400.0;
            }
        } else {
            // dead space relative to lookahead item: penalize small unusable gaps
            score += 0.8 * (nxt - post_residual as f64);
        }
    }

    // Penalize leaving residual that nothing (10..80) can use
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Prefer tighter bins relative to mean residual
    score += 1.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        let poor_fit = item_size as f64 > mean_residual + 10.0;
        if poor_fit || mean_residual < item_size as f64 {
            score -= 150.0 + 50.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        } else {
            score += 200.0 + 100.0 * crowded;
        }
    }

    // Mild pressure to consolidate late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) especially when it nearly fills the bin.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that can never hold the next item (or typical small item).
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) > post_residual {
            score += 8.0 + 0.5 * (post_residual as f64);
        } else {
            score -= 6.0; // bin remains useful for the lookahead item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is huge/wasteful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when good fits exist
    // and bins are already open with usable residual.
    if bin_residual == bin_capacity {
        score += 15.0;
        if open_bins_count > 0 {
            score += 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // new bin pairs well with upcoming large item
        }
    }

    // Prefer bins whose residual is close to the mean residual (keeps residuals balanced),
    // scaled by stream progression (later steps: consolidate more aggressively).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();
    score += 20.0 * progress * dev;

    // Late in the stream, favor filling bins completely to avoid trailing waste.
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for larger item into bin with larger residual (natural fit).
    score += 0.05 * (item_size as f64) * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Polynomial penalty on small post-residuals (dead space), stronger late in stream
    let dead = (norm_pr.max(0.0)).powi(3);
    score += 40.0 * dead * (0.5 + progress);

    // Reward tight fits (very small post_residual) with smooth quadratic bonus
    let tight = (1.0 - norm_pr).powi(2);
    score -= 15.0 * tight;

    // Prefer bins whose residual is close to item size (smooth quadratic term)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * diff * diff;

    // Lookahead: reward leaving space for next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= 12.0 * (1.0 - (gap / cap).min(1.0));
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty for many open bins, encouraging consolidation early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual alignment: prefer bins near the mean residual (smooth)
    let mres = (mean_residual - pr) / cap;
    score += 5.0 * mres * mres;

    // New-bin candidate: penalize mildly so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity quantized into eighths) ---
    let eighth = bin_capacity / 8;
    let class = (post_residual / eighth) as f64; // 0..8 harmonic class
    score += class * 1.5;

    // Dead-space penalty: tiny post_residual that nothing can use is fine (perfect fit),
    // but mid-range residuals (unusable slivers) are penalized.
    let mod_class = post_residual % eighth;
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fit, strongly reward
    } else if mod_class != 0 && post_residual < 30 {
        score += 12.0; // small unusable sliver
    }

    // --- Lookahead coupling: can next item fit into the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains into this bin: strong reward, scaled by how tightly it fits
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 + (1.0 - chain_waste / bin_capacity as f64) * 8.0;
        } else {
            // Next item won't fit here: penalize if it would have fit the pre-residual
            if next_item_size <= bin_residual {
                score += 6.0;
            }
        }
        // Harmonic threshold: next item in a "large" class (>50) prefers bins with big room
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 {
        score -= 15.0; // only this bin can fit: force usage to avoid opening a bin
    } else if fitting_bins_count > 1 {
        // Prefer the bin among several that leaves the most structured residual
        score -= (fitting_bins_count as f64).ln() * 0.5;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New empty bin: full residual. Reward when current open bins are crowded or mean residual is small,
        // penalize when an existing bin clearly suffices.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // open bins are tight; new bin is good
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers
        if progress > 0.7 && mean_residual > 40.0 {
            score += 25.0;
        }
        return score;
    }

    // --- Tightness reward: exact fill is ideal ---
    if post_residual == 0 {
        score -= 20.0;
    }

    // Mild preference for fuller bins overall (residual relative to mean)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any future item (min item size 1, but practically < ~10 are weak)
    // are heavily penalized; mid-range residuals are mildly rewarded.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable dead space: strong penalty.
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual < 25 {
        // Marginal space: light penalty.
        score += (25 - post_residual) as f64 * 0.5;
    } else if post_residual >= 40 && post_residual <= 80 {
        // Comfortable residual that can host a typical item: reward.
        score -= 6.0;
    }

    // Pressure on number of open bins: when many bins are open, prefer
    // filling existing ones (penalize new-bin candidates implicitly via
    // their large residual getting less reward).
    let open_pressure = open_bins_count as f64 * 0.4;
    score += open_pressure * (pr / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Next item would create dead space here: discourage.
            score += 8.0;
        }
    }

    // Late in the stream, tighten packing: penalize wasted space more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * pr * 0.3;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    // Mean residual alignment: bins far below mean residual are "hard" to fill;
    // slightly prefer placing into bins keeping residuals balanced.
    score += (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: perfect match of post_residual with next_item_size is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += gap * 0.8;

        // Exact match: strong reward.
        if post_residual == next_item_size {
            score -= 35.0;
        }
        // post_residual leaves room for next item: good chaining.
        else if post_residual >= next_item_size {
            score -= 8.0;
        }
        // post_residual too small for next item: dead space penalty scaled by waste.
        else {
            score += 6.0 + (post_residual as f64) * 0.3;
        }
    } else {
        // Last item: minimize waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bin (only fitting bin): avoid forcing a new bin; strong reward.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream, having many open bins is costly; but if few bins fit, allow opening.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large relative to current item, a fresh bin may be wise.
        if next_item_size > item_size && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Slight preference to fill older/more-filled bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    // Prefer bins among many candidates only if they're good fits (reduce thrash).
    if fitting_bins_count > 2 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest possible item (~1) is worthless. Penalize unusable slivers.
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 6.0 * tightness;
        // Dead-space penalty: residual that no future item can plausibly use
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 1.5;
        }
    } else {
        // Perfect fill: strong reward
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item cannot fit post-residual but fits elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // chain fill
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here; less bad if this bin was near-full anyway
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity when
    // decent fits exist. Make the empty bin attractive only when the current
    // item is large and residuals are all small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_gap = mean_residual - item_size as f64;
        // penalize new bin when existing bins fit reasonably well
        if avg_fit_gap >= 0.0 {
            score += 8.0 + avg_fit_gap * 0.3;
        } else {
            score -= 3.0; // poor fits everywhere: fresh bin is fine
        }
        // late in stream, prefer closing out existing bins
        score += 10.0 * (1.0 - progress);
        // many open bins: discourage opening yet another
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for fuller bins overall (best-fit flavor) scaled by
    // how many alternatives exist.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Global balance: penalize bins far from mean residual to keep spread low,
    // unless it's a tight fit (already rewarded).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, non-linearly
    let mut score = norm_pr * norm_pr * 120.0 + norm_pr * 40.0;

    // Smooth polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * (p * p - 2.0 * p * (1.0 - p) - p * p * p) * 60.0;
    score += coupling;

    // Perfect-fit reward, stronger later in the stream
    if pr == 0 {
        score -= 200.0 + 300.0 * p;
    }

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (30.0 + 90.0 * p);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 120.0 * p;
    }

    // Lookahead: reward if next item fits the post residual (smooth affinity)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs() / cap;
        score += fit_gap * fit_gap * 100.0;
        if nxt <= pr {
            score -= 25.0 + 50.0 * p;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln().max(0.0) * 5.0 * (1.0 - p);

    // New-bin candidate: make it moderately unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 60.0 + 80.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo arithmetic on capacity) ---
    let pr = post_residual;
    let class = pr % 10; // decade residue class
    // Residues that are "dead space" classes: very small but non-zero residuals
    // (1..=9) are almost unusable for items >= 10 in classic streams, but items
    // can be as small as 1 here, so weight by how many classes exist.
    let dead_penalty = match class {
        0 => -6.0,                      // perfectly aligned residual: excellent
        1..=4 => 4.0,                   // tiny sliver: likely dead space
        5 => 1.0,                       // half-class: marginal
        _ => -1.0,                      // 6..=9: can host small items
    };
    score += dead_penalty;

    // Integer-division thresholds: how many "half bins" of space remain
    let halves = pr / (bin_capacity / 2).max(1);
    score -= 3.0 * halves as f64; // keeping a bin half-full-or-more is valuable

    // --- Fit tightness: reward small post_residual relative to item size ---
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score -= 8.0 / (1.0 + tightness); // tight fits get big discount

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly in a harmonic class -> strong reward
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap_f);
        } else {
            // next item won't fit: this residual becomes dead for lookahead
            let waste = (next_item_size - pr) as f64;
            score += 6.0 * (waste / cap_f).min(1.0);
        }
        // exact harmonic match bonus: post_residual == next_item_size
        if pr == next_item_size {
            score -= 12.0;
        }
    } else {
        // last item: just minimize residual directly
        score += 0.0;
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0; // avoid opening a new bin if this is the only fit
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral baseline, slightly penalized so we only
        // open when existing bins look bad. Penalize more when many bins fit.
        score = cap_f * 0.45 + 5.0 * (fitting_bins_count as f64);
        // Early in stream, fresh bins are cheaper to open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is attractive
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // --- Mean residual coupling: prefer bins far from the mean (diversity) ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= 2.0 * (dev / cap_f);

    // --- Open bins pressure: many open bins -> prefer filling existing ones ---
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // --- Capacity-fraction penalty for leaving exactly awkward fractions ---
    let frac = post_residual as f64 / cap_f;
    if (frac * 4.0).round() / 4.0 == frac && pr > 0 {
        score -= 2.0; // quarter-aligned residuals pair well with class sizes
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward, never pass this up.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are likely unusable.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 8.0; // up to ~80 penalty for a 1-unit gap
    }

    // Lookahead coupling (k=2): does the next item fit into the leftover space?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0; // leftover remains useful
        } else {
            // leftover becomes dead space for the next item
            score += 3.0 + (next_item_size as f64 - dead) * 0.5;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, favor consolidation into existing bins.
    score += open_bins_count as f64 * 0.3;

    // Mild penalty if this bin's residual is far from the item size (poor match).
    score += (mean_residual - item_size as f64).abs() * 0.1;

    // New-bin candidate: only attractive when all fits are poor/dead-space heavy.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + open_bins_count as f64 * 0.5;
        // If the next item is huge, keeping residual intact is valuable.
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score += 50.0;
        }
        // Early in the stream, a fresh bin is cheaper than fragmentation.
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 50.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits here: reward tighter match
            let slack = post_residual as f64 - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize leftover that is too small to be useful
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0 * (10.0 - dead);
            } else {
                score += 5.0;
            }
        }
    } else {
        // last item: prefer fullest packing
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (denser bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are very tight
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Penalize very small unusable post residuals (dead space) unless near zero
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 5.0 {
        score += 10.0;
    }

    // Progression factor: late in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits (small post_residual) with a saturating bonus.
    score -= 12.0 * (-pr / 15.0).exp();

    // Lookahead (k=2): reward bins whose leftover can still host the next item,
    // especially early in the stream when future flexibility matters more.
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 6.0 + 4.0 * (1.0 - progress);
        } else {
            // Leftover is dead space relative to the next item; penalize
            // proportionally to how much it "wastes" the gap.
            score += 0.15 * (next_item_size as f64 - pr);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Brand-new empty bin candidate: give it a moderate baseline so it only
    // wins when all open bins are genuinely poor fits. Slightly cheaper late
    // in the stream and when many bins are already open (consolidation).
    if bin_residual == bin_capacity {
        score = 40.0 + 10.0 * progress - 0.2 * open_bins_count as f64;
        // Favor a fresh bin if the next item is bigger than this one
        // (keeps large-item capacity available).
        if next_item_size > item_size {
            score -= 3.0;
        }
    }

    // Mild global-fragmentation coupling: penalize bins deviating far from
    // the mean residual, encouraging balanced residual distribution.
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Smooth non-linear coupling: post_residual penalized more strongly early
    // (dead space is costly while many items remain), less so near the end.
    let dead_space_weight = 0.5 + 1.5 * (1.0 - p3);
    score += dead_space_weight * post_residual as f64;

    // Polynomial coupling of post_residual with progress:
    // large residuals left over are penalized quadratically as stream advances.
    let r = post_residual as f64 / bin_capacity as f64;
    score += (r * r) * (1.0 + 2.0 * progress) * 30.0;
    score -= (r * (1.0 - r)) * (1.0 - progress) * 20.0;

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let fit_bonus = (1.0 - gap / bin_capacity as f64).max(-1.0);
        score -= fit_bonus * (25.0 + 25.0 * progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Mild penalty when many bins are open (consolidation pressure).
    score += (open_bins_count as f64).sqrt() * 1.5 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balance).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / bin_capacity as f64) < 0.35;
        score += if tight { 25.0 } else { 60.0 + 40.0 * (1.0 - progress) };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in classes of 10
    let class = post_residual / 10;
    // Penalize dead space quadratically per class, except tiny residuals (class 0 = perfect fit)
    score += class as f64 * class as f64 * 2.5;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // If next item fits into the post residual, reward (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic reward: how much of post residual the next item consumes
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 30.0 * fill;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize leftover proportionally
        score += (post_residual as f64) * 0.6;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; more when many bins already open
        score += 40.0 + (open_bins_count as f64).sqrt() * 5.0;
        // But if the current item is large, a fresh bin is fine
        if item_size >= 50 {
            score -= 25.0;
        }
    }

    // Prefer filling bins below mean residual (balance-aware)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, tighten up: prefer tight fits more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful for future items.
    let dead_zone_low = 1.0;
    let dead_zone_high = 9.0;
    if post_residual > 0 && (post_residual as f64) <= dead_zone_high && (post_residual as f64) >= dead_zone_low {
        score += (dead_zone_high - post_residual as f64 + 1.0) * 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: residual barely larger than item.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tight) * 15.0;

    // Open bins pressure: prefer filling existing bins over opening new ones.
    if bin_residual != bin_capacity {
        score -= 10.0 + open_bins_count as f64 * 2.0;
    } else {
        score += 5.0 + open_bins_count as f64 * 1.5;
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot fit into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u64) > (post_residual as u64) {
            score += 8.0;
        } else {
            score -= 6.0;
        }
    }

    // Mean residual coupling: avoid leaving this bin far below the mean residual.
    score += (mean_residual - post_residual as f64).abs() * 0.5;

    // Slight progression scaling to adapt pressure over the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step match
        } else if post_residual > next_item_size {
            score -= 8.0; // next item still fits
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3; // dead space for next item
        }
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fill
    }

    // Penalize large wasted residual relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mildly discourage opening new bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress; // new-bin penalty grows over time
    }

    // Encourage tight bins when many bins are open
    score += (post_residual as f64) * (open_bins_count as f64 / 50.0).min(0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, scaled by capacity.
    let waste = post_residual as f64;
    score += 0.5 * (waste / bin_capacity as f64) * (waste / bin_capacity as f64) * bin_capacity as f64;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: penalize residuals too small for the next item (dead space),
    // reward residuals that can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * (next_item_size as f64);
        } else {
            score += 8.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: when many bins are open with slack, prefer filling existing bins
    // over opening new ones.
    if bin_residual != bin_capacity {
        score -= 10.0;
        score -= 0.05 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize more when existing bins are roomy,
        // less when open bins are nearly full (consolidation phase).
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 5.0 + 20.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Time horizon: later in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward smaller values (keep big holes for big future items).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted fraction of the bin
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // Reward near-perfect fits (small post_residual) extra aggressively
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * fit_quality * (1.0 - 0.5 * progress);
        } else {
            // Penalize dead space that the next item cannot use
            score += 6.0 * progress * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Late stream: consolidate into fewer bins, prefer filling existing bins
    score -= 8.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Mild penalty for opening a new bin when open bins exist and stream is late
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 15.0 * progress;
    }
    // Early stream: a fresh bin is cheap, slightly favor flexibility
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Nudge toward bins with residuals near the mean (keeps residual spread tight)
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues are grouped into
    // "harmonics" of the capacity (C/4, C/2, C/8 bands) so that dead space
    // is judged by how likely a future item can still exploit it.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the post residual into harmonic buckets: 0, (0,C/8], (C/8,C/4],
    // (C/4,C/2], (C/2,C]. Deeper (smaller) classes are penalized less.
    let eighth = c / 8.0;
    let quarter = c / 4.0;
    let half = c / 2.0;
    if pr > 0.0 && pr <= eighth {
        score += 6.0;          // tiny sliver: nearly dead space
    } else if pr <= quarter {
        score -= 2.0;          // useful for small items (10..25)
    } else if pr <= half {
        score -= 8.0;          // sweet spot: fits half-capacity items
    } else {
        score -= 4.0;          // large leftover, bin still very usable
    }

    // Integer-division threshold coupling: leftover divisible into common
    // item sizes (10/20/25/50 harmonics) is more valuable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 2.0; }
    if post_residual % 50 == 0 { score -= 2.0; }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item leaves a further residue; judge its class too
            let nr = post_residual - next_item_size;
            if nr <= eighth { score += 4.0; } else { score -= 3.0; }
        } else {
            // next item cannot use this residue: penalize small leftovers
            if pr <= quarter { score += 8.0; }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are crowded or the fit here would be terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // fit ratio: how well the item uses this (already open) bin
        let fit_ratio = item_size as f64 / c;
        let crowd = open_bins_count as f64;
        let mean_gap = (mean_residual - item_size as f64).max(0.0);

        // Base cost of a fresh bin, softened as the stream progresses
        // (late in the stream, closing bins cleanly matters more).
        score += 30.0 - 15.0 * progress;

        // If many bins are open and residuals are fragmented, new bin OK.
        score -= (crowd / 8.0).min(10.0);
        // If this bin would leave a tiny dead sliver, prefer a new bin.
        if pr > 0.0 && pr <= eighth { score -= 12.0; }
        // If the item fits this new bin well, mild bonus.
        score -= 10.0 * fit_ratio;
        // If other bins have plenty of room, discourage new bin.
        score += mean_gap * 0.15;
    } else {
        // Slight preference for fuller bins among open ones (best-fit flavor).
        score -= (bin_residual as f64 / c) * 5.0;
        // If many bins can fit the item, prefer the tightest one:
        // penalize bins with much more room than needed.
        if fitting_bins_count > 2 {
            score += (pr / c) * 4.0;
        }
    }

    // Mild global pressure: with many open bins, compress into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1) —
    // but practically, gaps below ~10 units are nearly unusable, and gaps that
    // cannot fit the lookahead item are wasted opportunities.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny slivers are almost worthless
    } else if post_residual >= 10 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // gap can't fit the next known item
    }

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins
    // (penalize the fresh-bin candidate and mildly reward reusing existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 2.0 * open_bins_count as f64 * (0.5 + progress);
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins),
    // keeping emptier bins available for larger future items.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead synergy: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            // next item barely misses this bin; penalize mildly since it
            // will need another bin anyway.
            score += 20.0;
        }
    }

    // Penalize residuals that are too small to fit the smallest possible
    // future item (dead space), scaled by how early we are in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (1.0 - progress) * 80.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins:
    // putting the item in a below-average-residual bin consolidates waste.
    if (post_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += ((post_residual as f64) - mean_residual) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Opening a new bin is neutral-to-bad; make open bins with decent
        // fits win instead.
        score += 50.0;
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect or near-perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small slivers are wasteful
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover gap.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
        if fit_ratio > 0.5 {
            score -= 25.0;
        }
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    if open_bins_count > 3 {
        score -= 3.0 * (open_bins_count as f64).ln();
    }

    // Mean residual coupling: if the average open bin has lots of room, encourage
    // packing into the emptiest-feeling bins (low residual relative to mean).
    let resid_gap = mean_residual - bin_residual as f64;
    score += 0.1 * resid_gap;

    // New-bin candidate logic: opening a fresh bin is attractive only when the item
    // is large relative to capacity and no bin fits well, or late in the stream when
    // open bins are all nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin, reduced for large items.
        score += 60.0 - 40.0 * big_item;
        // Late in the stream, opening a fresh bin is less costly (future items fewer).
        score -= 20.0 * progress;
        // If several bins already fit, opening a new one is wasteful.
        score += 10.0 * fitting_bins_count as f64;
        // If mean residual is high, existing bins have room — discourage new bin.
        score += 0.3 * mean_residual;
        // If the next item is small, a fresh bin wastes its large space on small items.
        if next_item_size > 0 && next_item_size < item_size / 2 {
            score += 15.0;
        }
    }

    // Mild time-horizon shaping: early on, be slightly greedy for tight fits;
    // later, be more conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: quadratic in normalized post_residual with progress modulation
    let norm_post = post_residual as f64 / cap;
    score += 18.0 * norm_post * norm_post * (0.5 + 0.5 * progress) * cap;

    // Reward tight fits (near-perfect packing) with smooth exponential term
    let fit_quality = 1.0 - norm_post;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Penalize dead space that cannot fit the next item (smooth logistic gate)
    if next_item_size > 0 && post_residual > 0 {
        let fits_next = post_residual >= next_item_size;
        let gap = (post_residual as f64 - next_item_size as f64).abs() / cap;
        let gate = 1.0 / (1.0 + (-gap * 30.0).exp());
        if fits_next {
            score -= 6.0 * (1.0 - gate);
        } else {
            score += 10.0 * (1.0 - gate) * (1.0 + progress);
        }
    }

    // Last-chance bin bonus (only fitting bin): strong smooth reward
    if fitting_bins_count == 1 {
        score -= 14.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize opening a bin when others fit, modulated by stream progress
    if bin_residual == bin_capacity {
        let others_fit = fitting_bins_count > 0;
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 50.0)).ln();
        if others_fit {
            score += 22.0 + 15.0 * (1.0 - progress) + 4.0 * pressure;
        } else {
            score -= 5.0 * progress;
        }
    }

    // Mild preference for bins below mean residual (balance load) with smooth coupling
    score += 0.05 * (post_residual as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual shrinks.
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 15.0;
    } else if post_residual <= 40 {
        score -= 5.0;
    }

    // Harmonic class logic: bucket post_residual into capacity fractions.
    // Residuals in "useful" classes (multiples of common small sizes) are less dead.
    let class = post_residual / 10; // 0..10 harmonic class
    score -= match class {
        0 => 20.0,
        1 => 8.0,
        2 => 4.0,
        3 => 2.0,
        4 => 0.0,
        5 => -1.0, // half-full bin: very reusable
        _ => 1.0,
    };

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial credit scaled by how much would remain after next item
            let rem2 = post_residual - next_item_size;
            score -= 10.0 * (1.0 - rem2 as f64 / 50.0);
        } else {
            // next item cannot use this residual: penalize leaving large dead space
            score += 0.15 * (post_residual as f64 - (post_residual % next_item_size.max(1)) as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless open bins are very fragmented
    // or this is a perfect-size item for a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - (bin_capacity as f64 / 2.0)).abs();
        if item_size >= 60 || (open_bins_count > 0 && fragmentation < 10.0) {
            score += 50.0; // prefer existing bins
        } else if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        } else {
            score += 10.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for very low fill ratio relative to capacity (wasteful early packing).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score += 5.0 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are wasted forever.
    if post_residual == 0 {
        score -= 200.0; // perfect fit is gold
    } else if post_residual < 10 {
        score += 150.0; // unusable dead gap: heavy penalty
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        // leftover can't host the lookahead item: mildly wasted
        score += 40.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 60.0; // sets up a perfect fit for the next item
    }

    // Reward tight fits relative to the gap being consumed
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 80.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins slightly
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residual above the mean (keeps big bins for big items)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Late in the stream, close bins out: penalize leaving medium gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.4 * post_residual as f64;

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score = 400.0 - 100.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score = -50.0; // nothing else fits: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

