    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist, unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin if this bin would otherwise leave a large dead zone.
        if post_residual as f64 > mean_residual * 1.5 {
            score -= 100.0;
        }
    }

    // Late in the stream, prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 / 10.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable leftovers (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
