        score += 30.0 + 80.0 * progress + 2.0 * open_bins_count as f64;
        // but allow a fresh bin if current fit is terrible
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 90.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Tie-break: slight pull toward bins with larger residual (keep small residuals tight)
    score += post_residual as f64 * 0.05;

