}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight packing (high fill), stronger early in the stream
    let fill = (item_size as f64) / cap;
    score -= 12.0 * fill * (1.0 - progress);

    // Smooth non-linear coupling: quadratic post_residual term growing with progress
    let prn = pr / cap;
    score += 3.0 * prn * prn * progress;

    // Dead-space penalty: if next item cannot fit into the post residual
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size as f64 - pr) / cap;
            score += 20.0 * waste * waste;
        } else if post_residual == next_item_size {
            // Perfect reservation for the lookahead item
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
    } else {
        // Tie-break: prefer bins whose post residual is close to the mean residual
        score += 0.05 * (pr - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Residues 1..9 (non-zero, small) are awkward dead space; 0 is clean
    if pr > 0 {
        score += match class {
            0 => -8.0,                       // perfectly divisible class: reusable
            1 | 9 => 6.0,                    // worst dead space
            2 | 8 => 4.0,
            3 | 7 => 2.5,
            4 | 6 => 1.0,
            5 => 0.0,                        // half-class: still usable for mid items
            _ => 0.0,
        };
    } else {
        score -= 15.0; // perfect fill
    }

    // Integer-division thresholds: how many size-10 slots remain
    let slots = pr / 10;
    score -= slots as f64 * 2.0;

    // Lookahead coupling: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            score -= 10.0 - (leftover % 10) as f64; // reward fit, penalize its residue
        } else {
            score += 3.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, discouraged unless
    // current fit is terrible (large awkward post_residual)
    if bin_residual == bin_capacity {
        score = 30.0 + (post_residual as f64) - (mean_residual.min(50.0));
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin attractive
        }
    }

    // Progress term: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer filling bins below mean residual (tight packing)
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (<= ~10)
