    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0; // perfect fit for the next item
    } else if post_residual == 0 {
        score -= 80.0; // perfectly closed bin
    }

    // Reward tight fits relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize opening new bins), but when few bins are open, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += 20.0 + pressure;
    } else {
        score -= pressure.min(15.0);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Deviation from mean residual: prefer bins below mean residual (fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space) with a non-linear bonus.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score -= 18.0;
    }

    // 2-step lookahead: strongly reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward tight chain fits.
            if gap <= 2.0 {
                score -= 35.0;
            } else if gap <= 10.0 {
                score -= 20.0 * (1.0 - gap / 10.0);
            }
        } else {
            // Next item does NOT fit in leftover: penalize large unusable leftovers,
            // scaled by how badly it misses (dead space that likely never gets used).
            let miss = (next_item_size as f64 - post_residual as f64).min(30.0);
            score += 0.6 * miss;
        }
    }

    // Compare post_residual against mean residual: penalize leaving this bin far
    // above average residual (fragmentation), reward consolidating space.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.15 * dev;

    // Last chance bin: if this is the only bin that can fit the item, prefer using it
    // over opening a new bin (which would waste this residual entirely).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild preference for filling existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress;

    // Slight penalty when many bins are open: discourage excessive bin creation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Reward tight fits: scale post_residual penalty down when fit is snug
    let tightness = (item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
    score -= tightness * 8.0;

    // Penalize dead space that no plausible future item can use.
    // Small residuals are only useful if the next item can fill them.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits into this residual: strong reward
            score -= 12.0 + 6.0 * (post_residual as f64 - next_item_size as f64).recip().min(1.0);
        } else {
            // Dead space relative to lookahead: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 3.0 + 0.35 * waste;
        }
        // Perfect two-item pairing: residual exactly equals next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we prefer
    // reusing open bins, unless the fit is poor (high post_residual).
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
        // If many open bins already, opening new bins is worse
        score += 0.5 * open_bins_count as f64;
    }

    // Global fragmentation pressure: if mean residual is low, conserve space
    // by preferring bins whose post_residual is close to the mean (balanced).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, be greedier: minimize waste more aggressively
    score *= 1.0 + 0.4 * progress;

    // Prefer filling bins that are already fairly full (small bin_residual)
    score += 0.05 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (future items may fill them);
    // late, residuals become dead space -> amplify penalty quadratically.
    let progress_coupling = (post / cap) * (post / cap) * (0.5 + 2.5 * progress);
    score += progress_coupling;

    // Reward tight fits (post_residual near zero) smoothly via cosine-like term
    let tightness = 1.0 - (post / cap);
    score -= 1.5 * tightness * tightness * tightness;

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = post - nxt;
        if slack >= 0.0 {
            // smooth reward peaked when next item fills residual exactly
            let fill = 1.0 - (slack / cap);
            score -= 2.0 * fill * fill;
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            let miss = (-slack) / cap;
            score += 1.2 * miss * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * progress;
    }

    // New-bin candidate handling: opening a bin is costly; make it attractive
    // only when no good fit exists (post_residual == capacity here means empty bin)
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, decaying with progress (late items less likely
        // to fill leftovers, so fresh bins relatively better late)
        score = 0.9 - 0.4 * progress;
        // If the item is large relative to capacity, fresh bin is fine
        score -= 0.3 * (item / cap);
        // If many open bins already, slight preference to consolidate instead
        score += 0.05 * (open_bins_count as f64).sqrt();
        // If next item also fits comfortably in a fresh bin after this item, bonus
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 0.15;
        }
        return score;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (below mean) to keep bin profile balanced
    let dev = (post - mean_residual) / cap;
    score += 0.4 * dev * dev.abs();

    // Mild penalty for many open bins to encourage consolidation
    score += 0.01 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: penalize larger post_residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.08;
    } else {
        score -= 25.0; // perfect fit
    }

    // Fraction-of-capacity waste penalty, harmonic classes by residual bucket.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual / (bin_capacity / 8)) as u32; // 0..8 harmonic class
    score += match class {
        0 => -5.0,
        1 => 2.0,
        2 => 6.0,
        3 => 10.0,
        4 => 14.0,
        5 => 18.0,
        6 => 22.0,
        7 => 26.0,
        _ => 30.0,
    };

    // Lookahead: reward if next item fits the post residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.05; // good chaining
        } else {
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let mean_fit = mean_residual - item_size as f64;
        if mean_fit < 0.0 {
            score -= 15.0 + pressure * 0.5;
        } else {
            score += 25.0 + mean_fit * 0.3;
        }
        // Early stream: opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with low residual relative to mean (compact bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) but awkwardly small relative to typical items
    // are near-wasted space. Penalize the "unusable gap" band hard.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // Dead space: too small for anything meaningful (<= 5) -> heavy penalty
        if gap <= 5.0 {
            score += 120.0;
        } else if gap < 15.0 {
            // Small awkward gap: penalize proportionally to its uselessness
            score += (15.0 - gap) * 4.0;
        }
    }

    // Reward tight fits: post_residual close to zero is excellent.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    }

    // Reward leaving space exactly fitting the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // this bin will be perfectly filled by next item
        } else if post_residual >= next_item_size {
            // gentle reward: next item can still fit here
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this residual: penalize small leftovers
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins (penalize new-bin candidate).
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins.
        score += 60.0 + open_bins_count as f64 * 15.0;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
    } else {
        // Existing bin: mild reward scaled by how full it already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 20.0;
    }

    // Prefer bins whose residual deviates below the mean residual
    // (i.e., already-tighter bins) to consolidate fragmentation.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post-residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: this bin will be exactly filled next step
        } else if next_item_size <= post_residual {
            score -= 8.0; // next item still fits here, keeps option alive
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3; // dead space vs lookahead
        }
    }

    // Compare post-residual against mean residual: avoid leaving more slack than average
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize tiny unusable remnants (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 30.0;
    }

    // Early in the stream, keep bins tight and balanced to preserve flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when current bin would be badly wasted
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 60.0 + waste - (mean_residual * 0.3);
        if fitting_bins_count == 0 {
            score -= 40.0; // no existing bin fits, new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to item size.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is worthless
    } else if post_residual >= 10 && post_residual < 40 {
        score += (40.0 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here anyway; slight penalty if we leave large gap
            score += (post_residual as f64) * 0.05;
        }
    }

    // Time horizon: early in stream, be choosy (prefer perfect fits); later, just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * tightness;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 4.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > cap * 0.6 && next_item_size as u32 <= post_residual;
        if poor_fit {
            score -= 6.0; // large item into empty bin is fine, keep
        } else {
            score += 20.0; // discourage spreading load
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post-residual: smooth polynomial coupling with stream progress.
    let x = pr / cap; // in [0,1]
    // Early stream: prefer filling bins tightly (small post-residual). Later: allow slack.
    let slack_bias = 0.5 + 0.5 * progress;
    score += (x * x * (1.0 - x)) * 40.0 * slack_bias; // penalize mid-range waste smoothly
    score -= (1.0 - x) * (1.0 - x) * 12.0; // reward near-perfect fits

    // Coupling with mean residual: prefer bins whose residual is below mean (tighter bins).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 15.0;
    score += dev * 10.0 * (1.0 - progress);

    // Lookahead: if next item fits exactly in post-residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= (1.0 - gap) * 20.0;
            score -= gap * gap * 10.0; // still mildly reward close matches
        } else {
            // next item cannot use this residual: penalize proportionally to dead space
            score += (nx - pr) / cap * 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
        score -= 15.0;
    }

    // Mild pressure toward consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate (empty bin): post_residual = cap - item; penalize opening new bins
    // unless the item is huge (little waste would remain).
    if bin_residual == bin_capacity {
        score += 25.0 + (1.0 - it / cap) * 35.0;
        if fitting_bins_count == 1 {
            score += 40.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals that are "hard" to fill later
    // (small, awkward slivers) should be penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < quarter / 2 {
        // Tiny sliver: nearly dead space, penalize.
        score += 25.0;
    } else if post_residual < quarter {
        // Small leftover, mildly awkward.
        score += 10.0;
    } else if post_residual < half {
        // Mid-range leftover: usable, mild reward.
        score -= 5.0;
    } else {
        // Large leftover: very flexible.
        score -= 12.0;
    }

    // Integer-division harmonic classes: post_residual / 10 bucket.
    let class = post_residual / 10;
    score -= (class as f64) * 2.0;

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: reward proportionally to how snugly next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.3 * snug;
        } else {
            // Next item won't fit here: penalize more if leftover is small.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer filling existing bins fully.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when current
    // bins have poor fits (high mean residual) or few bins can fit the item.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        score = 45.0 + mean_r * 0.4 - (fitting_bins_count as f64) * 8.0;
        // Late in the stream, slightly prefer consolidating.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Tie-breaker: prefer bins with tighter current residual (better fit quality).
    score += (bin_residual as f64) * 0.05;

    // Prefer fewer open bins when residuals are similar (consolidation pressure).
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
