        score += (10 - post_residual) as f64 * 40.0;
    } else if post_residual <= 20 {
        // Marginal gap: moderate penalty, scaled by how close to unusable.
        score += (20 - post_residual) as f64 * 8.0;
    }

    // Reward filling a large fraction of the bin (tight packing).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        // Extra reward if the next item could also use the post residual.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 50.0;
        }
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer the bin where the next item also fits
        // (chained fit), otherwise slight penalty to diversify.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 25.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Cheaper to open a new bin early in the stream (future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
        // If many bins are open already, opening another is worse.
        score += open_bins_count as f64 * 3.0;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= fill_ratio * 50.0;
        // If no open bin leaves a good post-fit for the next item, new bin
        // becomes more attractive (handled implicitly via comparison).
        if next_item_size > 0 && item_size >= 70 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward when its residual is close to the item
        // (minimizing leftover), i.e., penalize large leftover relative to mean.
        if (bin_residual as f64) > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, reward heavily.
    if post_residual == 0 {
