    // 2-step lookahead: if next item exactly fills the post residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits too: mild reward proportional to how snug it is.
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize small dead space more.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 250.0;
            } else {
                score += 0.3 * waste;
            }
        }
    }

    // Penalize creating dead space relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive if item barely fits open bins or no good fit exists.
    if bin_residual == bin_capacity {
