    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding: many open bins -> encourage consolidation into existing bins.
    let crowd = (open_bins_count as f64 / (1.0 + step_index as f64)).min(1.0);
    score += 10.0 * crowd * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is below mean residual (tighter),
    // filling it first is good; if far above mean, slight penalty.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev;

    // Time horizon: early in stream, be picky (penalize loose fits);
    // late in stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * progress * tightness;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_residual == bin_capacity;
    if is_new_bin {
        let perfect_exists = fitting_bins_count > 0 && post_residual == 0;
        let _ = perfect_exists;
