        let mut nb = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            nb -= 100.0; // no alternative, must open
        } else if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            nb -= 10.0; // fresh bin guarantees room for next item
        } else {
            nb += 15.0 + 20.0 * (1.0 - progress); // prefer existing bins early
        }
