    } else {
        score += 10.0 * waste_frac; // end of stream: just minimize waste
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Slight preference to fill bins below mean residual (tighter bins first)
    score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

