    // Residuals that are "harmonically useful" (divisible into common item
    // sizes 10..80, e.g. multiples of 10 or 20) are less penalized.
    let pr = post_residual;
    let harmonic_useful = (pr % 10 == 0) as f64 + (pr % 20 == 0) as f64 + (pr % 25 == 0) as f64;
    score -= 6.0 * harmonic_useful;

    // Integer-division thresholds: residual bucket = pr / 20 (0..5).
    let bucket = (pr / 20) as f64;
    score += 2.5 * bucket * bucket * 0.1; // mild super-linear penalty for large leftovers

    // Dead space: post residual too small for the smallest plausible item (1..100 range, use 10 as safe floor)
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable dead space
    }

    // Tight fit reward: post_residual small relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we
    // prefer reusing open bins unless the fit there is poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.15 * open_bins_count as f64;
        // If next item is huge, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let exact = (next_item_size == pr) as f64;
        score -= 8.0 + 20.0 * exact;
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for leaving awkward gap
        score += 3.0;
    }

    // Late in the stream: consolidate more aggressively, avoid opening bins
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 6.0 * progress;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
