pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "usable" classes.
    let class = post_residual % 10;
    // Small remainders (0..3) mean near-perfect packing: reward strongly.
    if class == 0 {
        score -= 12.0;
    } else if class <= 3 {
        score -= 6.0;
    } else if class >= 7 {
        score += 5.0; // large dead-space remainder
    }

    // Integer-division thresholds: post_residual in (0..10) is nearly full — great.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 10;
            if nxt_class == 0 {
