            } else if nxt_class <= 3 {
                score -= 3.0;
            } else {
                score += 2.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize wasted exact fits
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): make it attractive only if current fit is bad
    // (large post_residual means poor fit into an existing bin).
    if bin_residual == bin_capacity {
        // New bin has post_residual = capacity - item_size; judge by how "clean" it is.
        let new_class = post_residual % 10;
        if new_class == 0 {
            score -= 9.0;
        } else if new_class <= 3 {
            score -= 4.0;
        } else {
            score += 2.0;
        }
        // Early in stream, prefer filling existing bins less aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 3.0;
    }

    // Prefer bins with residuals below the mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
