    }

    // Prefer tighter bins (best-fit flavor)
    score += (bin_residual as f64 - post_residual as f64) * 0.1;
    score += (bin_residual as f64 / bin_capacity as f64) * 30.0;

    // Global state coupling: many open bins with low mean residual -> consolidate
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += consolidation * 0.3;
        score += open_bins_count as f64 * 2.0;
    }

    // Time horizon: early in stream, opening new bins is cheap; later, prefer filling
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate
        let new_bin_penalty = 50.0 + 200.0 * progress + open_bins_count as f64 * 10.0;
        score += new_bin_penalty;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin keeps flexibility
        }
    } else {
        // favor existing bins more as stream progresses
        score -= 30.0 * progress;
    }

    // Mild preference for bins below mean residual (balancing)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, dead space is cheap (bins will fill later); late, it's costly.
    let progress_term = 0.6 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += norm_pr * norm_pr * cap * (1.0 - progress) * 0.8;
    score -= progress_term * (cap - pr) * 0.15;

    // Smooth interaction: exact fit (post_residual near 0) heavily rewarded
    let fit_quality = 1.0 - (norm_pr * 2.0 - 1.0) * (norm_pr * 2.0 - 1.0); // 1 at pr=0 and pr=cap
    let usable_fit = 1.0 - norm_pr * norm_pr;
    score -= fit_quality * usable_fit * item_size as f64 * 0.5;

    // Lookahead coupling: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = (pr - nx) / cap;
        let room_sig = 1.0 / (1.0 + (-room * 12.0).exp()); // smooth sigmoid
        score -= room_sig * nx * 0.35;
        // Penalize blocking: post-residual just below next item size
        let block = ((nx - pr) / cap).max(0.0);
        score += block * block * cap * 0.9 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Many open bins: prefer consolidating into existing capacity
    let density = open_bins_count as f64;
    score += (density / (density + 3.0)) * mean_residual * 0.1;

    // New-bin candidate penalty: opening a bin should only win when current fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 60.0 * (1.0 - norm_pr * 0.0) + item_size as f64 * 0.2;
        score -= 20.0 * progress; // later in stream, new bins are more acceptable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and mod 25.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: residuals that no typical item (1..100) can use well.
    if post_residual > 0 {
        // Small unusable slivers are very bad.
        if post_residual < 10 {
            score += 40.0;
        } else {
            // Residues that are awkward (not multiples of 5/10) get a penalty.
            if r10 != 0 {
                score += 3.0 + (r10 as f64) * 0.5;
            }
            if r25 != 0 && r25 % 5 != 0 {
                score += 2.0;
            }
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward residuals that exactly match the next item size (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Prefer leaving room for the next item; penalize blocking it.
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score += 8.0 + gap * 0.3;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot fit in this residual: mild penalty scaled by gap.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Open new bin only when mean residual is small (bins nearly full) or late stream.
        score += 55.0 - 40.0 * tightness - 10.0 * progress;
        if post_residual == bin_capacity {
            // Fresh bin has huge residual; harmonic classes of full capacity are fine.
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is already small (consolidate waste).
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Slight preference to spread across many bins early, consolidate late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Integer-division threshold: residuals in [50,100) are "half-class" — mildly favored.
    if post_residual >= 50 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 60.0 * (1.0 - dead); // tiny gap = pure waste
        } else if post_residual < 20 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty if gap is awkwardly small.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 12.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Mild pull toward bins with low residual (tighter packing).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Early stream: be conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if new_bin && progress < 0.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 20 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 + 25.0
        };
        score -= 2.5 * (100.0 - gap.min(100.0) as f64) / 10.0;

        // Perfect chain: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Chain feasibility: next item fits, leaving small remainder.
        if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 80.0;
        }
    }

    // Relative-to-mean residual adjustment: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.4 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize new-bin opening unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin can chain the next item
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 40.0; // open bins already accommodate well
        }
    }

    // Late-stream pressure: consolidate to reduce open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit gets a strong extra reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are wasted space
    }

    // Lookahead: reward if the next item fits exactly in the post-residual,
    // penalize if next item cannot fit in post-residual (forces future new bin).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        } else {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 + 15.0 * fit_quality;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with usable residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0
            - 25.0 * progress
            + 2.0 * open_bins_count as f64
            + (mean_residual / 10.0).min(20.0);
        // Exception: large items relative to capacity benefit from fresh bins.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mild preference for filling bins with larger residuals when many bins open.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Time-horizon coupling: late in the stream, prioritize consolidation.
    if total_items > 0 {
        let horizon = step_index as f64 / total_items as f64;
        score -= 10.0 * horizon * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = norm_post * (1.0 + 0.8 * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, tighten packing aggressively
    let tightness = 0.5 + 1.5 * progress * progress;
    score *= tightness;

    // Reward tight fits (small post_residual) with a smooth exponential bonus
    let tight_fit = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 3.0 * tight_fit * tight_fit;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let ratio = nxt / post.max(1.0);
            score -= 2.0 * ratio * ratio;
        } else {
            // penalize dead space that next item cannot use (smooth)
            let waste = (nxt - post) / cap;
            score += 1.5 * waste * waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // New-bin candidate handling: only attractive when current bin would be
    // badly fragmented and mean residual is large
    if bin_residual == bin_capacity {
        let fragmentation = norm_post * norm_post;
        let mean_gap = (mean_residual / cap - 0.5).max(0.0);
        score = 4.0 + 2.0 * mean_gap - 3.0 * (1.0 - fragmentation);
        if fitting_bins_count == 0 {
            score -= 5.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 {
            score += 3.0; // keep last-chance bin alive
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it lands in.
    // Dead space classes (post_residual small but unusable) are penalized hard.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -8.0 // perfect fit: strong reward
    } else if pr <= 10 {
        2.5 // tiny sliver, nearly dead
    } else if pr <= 20 {
        0.5 // fits only smallest items
    } else if pr <= 34 {
        -1.2 // useful band
    } else if pr <= 50 {
        -2.0 // half-bin band: very reusable
    } else if pr <= 67 {
        -1.5
    } else {
        -0.5
    };
    score += class * (cap / 100.0);

    // Nonlinear exact-fit curvature: reward residual close to multiples of common item sizes.
    let harmonic = ((pr % 10) as f64);
    score += 0.35 * harmonic * (1.0 - harmonic / 10.0); // peak at pr%10==5, zero at multiples of 10

    // Integer-division threshold: bins whose residual divides evenly into expected item chunks
    let chunk = 20u32;
    if pr >= chunk && (pr % chunk) == 0 {
        score -= 3.0;
    } else if pr < chunk {
        score += (chunk - pr) as f64 * 0.15; // penalty proportional to unusable depth
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 6.0 * (1.0 - (pr as f64 - next_item_size as f64) / cap);
        } else {
            score += 1.5; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: keep it competitive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - cap / (open_bins_count.max(1) as f64)).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: opening bins is cheap; late stream: prefer filling existing bins
        score = cap * (0.55 - 0.25 * progress) + 0.2 * fragmentation + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: a fresh bin is attractive
        }
    } else {
        // Prefer tighter bins slightly (best-fit flavor) modulated by mean residual gap
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Progress-dependent waste aversion: later in the stream, dead space costs more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead space avoidance: penalize small unusable gaps.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 12.0;
        }

        // If the lookahead item cannot fit in the leftover gap, the residual
        // is likely wasted; penalize proportionally to how far off it is.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
        // If the next item fits snugly into the residual, reward it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening yet another one.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure from open bins.
        score += 6.0 + open_bins_count as f64 * 1.5;
        // But if this item is huge relative to capacity, a fresh bin is fine.
        score -= item_size as f64 * 0.05;
    } else {
        // Reward placing into existing bins, more so with many open bins.
        score -= open_bins_count as f64 * 0.5;
    }

    // Coupling with mean residual: bins already tighter than average are
    // good consolidation targets.
    let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
    if avg > 0.0 && (post_residual as f64) < avg {
        score -= (avg - post_residual as f64).min(30.0) * 0.4;
    }

    // Mild late-stream tightening: near the end, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // to the next item's size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            // reward placing next item here too; penalize leftover dead space
            score -= 20.0;
            if leftover < 10 && leftover > 0 {
                score += 15.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Compare against mean residual: prefer bins whose post-residual is close
    // to (or below) the mean residual, keeping large residuals for large items.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let diff = pr - mean_residual;
        score += diff * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bin mildly attractive only when the fit in
    // open bins would leave a very tight residual (bad packing) or when many
    // bins are already open and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if post_residual < 10 { 20.0 } else { 0.0 };
        score = 100.0 - bad_fit - 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 40.0; // fresh bin can host a nice 2-chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Exact fit bonus (post_residual == 0).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item nests perfectly: bonus proportional to how well it fills.
            score -= 10.0 + 0.5 * (next_item_size as f64);
        } else {
            // Dead space for the known next item: penalize.
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 40.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If many bins are open, discourage spreading further.
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If mean residual across open bins is large, a new bin is less wasteful.
        score -= 0.2 * mean_residual;
        // If this bin is the only fitting option, opening new bin is relatively OK.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (use up slack bins).
    let deviation = mean_residual - bin_residual as f64;
    score += 0.1 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Non-linear waste penalty: squared normalized residual
    let r = pr / cap;
    score += 30.0 * r * r;

    // Perfect-fit reward (smooth): strongly subtract when residual nearly consumed
    let tightness = 1.0 - r;
    score -= 25.0 * tightness * tightness * tightness;

    // Polynomial coupling of post_residual with stream progress:
    // late in stream, prefer filling bins tightly; early, keep flexibility
    let coupling = pr * (0.5 + progress * progress - 0.5 * progress);
    score += 0.15 * coupling;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Penalize opening new bins when many bins already open and mean residual large
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 + 0.05 * mean_residual;
    }

    // Mild spread penalty relative to mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls into.
    // Classes: 0 (tiny leftover, near-perfect fit), 1 (small), 2 (medium), 3 (large).
    let post_class = if post_residual == 0 { 0 }
        else if post_residual <= bin_capacity / 10 { 1 }
        else if post_residual <= bin_capacity / 3 { 2 }
        else { 3 };

    // Reward tight fits strongly; dead space penalty grows super-linearly per class.
    match post_class {
        0 => score -= 40.0,
        1 => score -= 12.0,
        2 => score -= 3.0,
        _ => {}
    }

    // Modulo arithmetic: leftover congruent to common item sizes (10..80 multiples)
    // means the residual is reusable by a future item. Reward residuals that are
    // divisible by small harmonics (5, 10) and lie in the reachable item range.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 4.0;
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        }
        if (10..=80).contains(&post_residual) {
            score -= 5.0; // residual itself could host a whole future item
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how much would remain after next item
            let after_next = post - next_item_size as f64;
            score -= 10.0 * (1.0 - after_next / cap);
        } else {
            // next item cannot use this bin's leftover; mildly penalize large waste
            score += 0.05 * post;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // early in the stream / when open bins are already crowded with small residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_crowding = mean_residual / cap;
        // Prefer new bin when existing residuals are small (crowded) or many bins open.
        score = 20.0 + 60.0 * (1.0 - progress) - 30.0 * avg_crowding + 2.0 * open_bins_count as f64;
        // If the item would leave a nicely harmonized residual class elsewhere, discourage new bin.
        if post_class <= 1 && fitting_bins_count >= 1 {
            score += 25.0;
        }
        // Exact-fit potential for the next item in a fresh bin.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.01 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100, so gap==0 is perfect).
    if post_residual > 0 {
        score += 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);
    }
    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward perfect fit for the lookahead item too.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size as u32 {
        // Dead space unusable by next item.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure against opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    } else {
        // Slight preference for tighter bins (small residual before placement).
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste after placement.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Perfect match for next item => strong reward.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Reward closeness of post_residual to next_item_size.
                let rel = gap / nxt;
                score -= 40.0 * (-rel * 2.0).exp();
            }
            // Penalize if next item would still leave a large stranded residual.
            let stranded = gap;
            score += stranded * 0.25;
        } else {
            // Next item cannot fit into post_residual: mild penalty proportional to overshoot.
            let over = nxt - pr;
            score += over * 0.15;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = pr - mean_residual;
        // Prefer bins whose post-residual stays near/below the mean (balanced packing).
        score += dev * 0.10;
        // Strongly penalize creating large residuals far above the mean (dead space).
        if dev > 0.0 {
            score += dev * dev * 0.02;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, prefer closing bins tightly (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.30;

    // Penalize very small residuals (unusable slivers) superlinearly.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 45.0 - bad_fit * 100.0;
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space below the minimum plausible item size
    let dead_zone = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += 50.0 * (dead_zone - post_residual as f64);
    }

    // Lookahead: strongly reward leaving exactly room for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // next item cannot use the leftover; penalize proportionally
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        let baseline = 25.0 + 5.0 * open_bins_count as f64;
        // early in the stream, opening bins is cheap; later, expensive
        score += baseline * (0.5 + progress);
        // if the next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Global residual pressure: if mean residual is high, prefer bins below average
    // (keeps large residuals available for large future items)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1)
    let p = progress;
    let coupling = prn * prn * (0.5 + 2.5 * p) + prn * (1.0 - p) * 0.5;
    score += coupling * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - prn) * (1.0 - prn) * (10.0 + 40.0 * p);

    // Dead-space penalty: residuals too small for typical future items
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 25.0 * (ns / cap) * (1.0 + p);
        } else {
            score += 8.0 * (1.0 - prn) * (0.5 + p);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 + p);
    }

    // Penalize bins that deviate from mean residual (keep residual profile balanced)
    score += ((pr - mean_residual) / cap).abs() * 10.0;

    // Mild preference for consolidating into fewer bins
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: prefer it only when open bins would leave large waste
    if bin_residual == bin_capacity {
        score = pr + 5.0 - 20.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a super-linear bonus.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - frac) * (1.0 - frac);

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in low classes is worse.
    // Residuals < 10 are unusable (min item size 1..100, but small dead space wastes capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills post_residual too.
        let npost = post_residual - next_item_size;
        if npost < 10 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would have fit if we placed differently elsewhere; mild penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or no good fit exists; penalize opening new bins generally.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        if load_frac > 0.5 {
            score -= 10.0;
        } else {
            score += 30.0 * (1.0 - load_frac);
        }
        // If many bins are open and one fits, discourage a new bin.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - frac);

    // Modulo-class tiebreaker on post_residual: prefer residuals divisible
    // into useful chunks (multiples of common item sizes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Small unusable-ish gaps (below typical small item sizes) get graded penalties.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bins pressure: penalize spreading across many open bins,
    // encouraging consolidation; stronger late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in the dead space created, penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.5;
    }

    // Prefer bins tighter than the mean residual (filling fullest bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make it moderately attractive only when fits are bad.
    if bin_residual == bin_capacity {
        score -= 15.0;
        // But if the current bin would leave a good gap, discourage the new bin.
        if post_residual <= 30 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 + item_size as f64 * 0.3;
    }
    // Near-match: next item still fits snugly in the leftover space
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.25;
        if slack < 10.0 {
            score -= 8.0; // tight secondary fit is very desirable
        }
    }
    // Next item cannot use the leftover: dead space risk, penalize proportionally
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average waste is good, more than average is bad
    score -= (mean_residual - post_residual as f64) * 0.10;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // but allow it when open bins would leave large unusable residuals
    if bin_residual == bin_capacity {
        let worst_open_waste = if open_bins_count > 0 {
            (post_residual as f64).max(mean_residual)
        } else {
            post_residual as f64
        };
        let pressure = open_bins_count as f64 * 0.5;
        let waste_pressure = if post_residual as f64 > mean_residual + 15.0 { 0.0 } else { 12.0 + pressure };
        score += 10.0 + pressure - waste_pressure;
    }

    // Slight preference for filling bins tighter as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: bonus if next item fits exactly in post_residual (perfect chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leftover after it matters
            let post2 = post_residual - next_item_size;
            score -= 12.0 * (1.0 - post2 as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize bins that leave awkward gaps
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than new ones
    let crowding = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= 4.0 * (crowding / (crowding + 5.0));
    } else {
        // new-bin candidate: penalize when many bins are open or mean residual is large
        score += 6.0 * (crowding / (crowding + 3.0));
        score += 0.15 * mean_residual;
    }

    // Time horizon: early in stream, be more selective (penalize waste more);
    // late in stream, just fill bins up
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    // Mean residual coupling: if average residual is small, avoid leaving big gaps
    if (post_residual as f64) > mean_residual + 15.0 {
        score += 5.0;
    } else if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = r + 40.0 * rn * rn * (1.0 - progress);

    // Tight fits are good: reward small post_residual via quadratic term
    score -= 25.0 * (1.0 - rn) * (1.0 - rn) * (item_size as f64 / cap);

    // Stream progress coupling: later in stream, prefer filling bins tighter
    score += 30.0 * progress * rn * rn;

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= r {
            score -= 20.0 * (1.0 - ns / cap) * (0.5 + progress);
        }
        // penalize if next item would only fit an almost-empty residual
        score += 10.0 * progress * (ns / cap) * (1.0 - rn);
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // Many open bins: penalize spreading; prefer reusing
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * rn;

    // Mean residual coupling: bins with residual far from mean get mild penalty
    score += 0.15 * (r - mean_residual).abs();

    // New-bin candidate: make it attractive only when nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) + 10.0 * rn * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post-residual: residual buckets by fraction of capacity.
    // Dead space that is too small to hold typical items is penalized.
    if post_residual > 0 {
        let class = post_residual / 10; // integer division threshold class
        match class {
            0 => score += 30.0,                     // 1..9 : almost dead space
            1 => score += 12.0,                     // 10..19: unusable for most
            2 => score += 4.0,                      // 20..29
            3 => score -= 3.0,                      // 30..39: useful pocket
            4 => score -= 6.0,                      // 40..49
            5 => score -= 8.0,                      // 50..59
            _ => score -= 10.0,                     // large residual: flexible bin
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead: reward if next item fits exactly or well in post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 15.0 + 0.25 * leftover;
        if leftover == 0.0 {
            score -= 20.0; // chained perfect fit
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty proportional to gap.
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is poor (large post residual relative to capacity) and
    // many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit = pr / cap; // 1.0 for new bin call
        let pressure = (open_bins_count as f64) / (1.0 + step_index as f64).ln().max(1.0);
        // Prefer new bin when item is large (leaves little waste) and stream is long.
        let item_frac = item_size as f64 / cap;
        score -= 5.0 + 10.0 * item_frac;
        // But discourage excessive new bins late in stream when mean residual is high.
        score += 0.3 * mean_residual.max(0.0);
        if pressure > 5.0 && mean_residual > 25.0 {
            score += 20.0;
        }
    }

    // Modulo harmonic coupling: residuals near multiples of 10 pair well with
    // typical item classes; nudge score by (post_residual % 10) smallness.
    let rem = post_residual % 10;
    if rem == 0 && post_residual > 0 {
        score -= 5.0;
    } else if rem >= 8 {
        score += 2.0;
    }

    // Slight preference to fill tighter bins first overall.
    score += 0.02 * (cap - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small but nonzero are "dead"
    // because future items (>=1) rarely fit well. Penalize unusable gaps.
    if post_residual > 0 {
        // gap too small for the lookahead item -> likely dead space
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
        // absolute dead zone: residual below the minimum plausible item size
        if post_residual < 10 {
            score += 15.0;
        }
        // near-perfect fill reward
        if post_residual <= 2 {
            score -= 20.0;
        }
    } else {
        // perfect fill
        score -= 25.0;
    }

    // Reward tight fits: item dominating the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // discourage opening new bins (new-bin candidate has bin_residual == capacity).
    if bin_residual == bin_capacity {
        // new bin candidate: penalize proportionally to how many bins are open
        score += 8.0 + 2.5 * open_bins_count as f64;
        // but if no existing bin fits well (this call would be chosen anyway),
        // soften so a new bin is acceptable when open bins are nearly full
        score -= mean_residual * 0.05;
    } else {
        // existing bin: mild reward scaled by open bins count
        score -= 0.4 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item exactly matches the post residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 22.0;
    }
    // if next item fits comfortably in post residual, mild reward
    if next_item_size > 0 && post_residual >= next_item_size + 10 {
        score -= 4.0;
    }

    // Slight preference early in the stream to keep bins tight (build dense bins),
    // less aggressive later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that matches next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match bonus (post_residual == next_item_size means the next item fills this bin exactly)
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // If the next item can still fit in the remaining space, mild reward
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Dead space relative to the next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: prefer tightest fit overall
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins with residual far above the mean (wasteful large residuals)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Reward bins that are already relatively full (small residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Slight penalty for creating very small unusable residuals (< 10 dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, be more liberal about opening bins; late, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: attractive early, less so late
        score -= 20.0 * (1.0 - progress) - 5.0;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 100.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize tight fits that leave small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Prefer filling bins with small residuals relative to the mean
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Many open bins: encourage closing out partially-filled bins
    if open_bins_count > 4 {
        score -= 0.3 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 60.0 + 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in post_residual, amplified by stream progress.
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: cubic decay of bonus as post_residual shrinks.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 6.0 * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 4.0 * (1.0 - gap * gap);
        } else {
            // Post-residual too small for next item: mild penalty scaled by excess.
            let excess = (nx - pr) / cap;
            score += 3.0 * excess * excess;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize leaving it unusable.
    if fitting_bins_count == 1 {
        score += 2.0 * norm_pr * (1.0 - progress);
    }

    // Prefer bins with residuals above the mean (consolidate space).
    score += 0.5 * (pr - mean_residual) / cap;

    // New-bin candidate: only attractive early in the stream or when nothing fits well.
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).powi(2);
        score = cap * (1.0 - 0.3 * early) + 10.0 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo classes on residual capacity
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction remaining

    // Small post_residual = tight fit = good (less wasted space)
    score -= 120.0 * (1.0 - frac) * (1.0 - frac);

    // Dead-space penalty: residuals that no typical item (1..100) can use well
    // Residuals in awkward classes (e.g. 1..=9) are nearly dead
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Harmonic class: residual mod 10 — small residue classes are more reusable
    let rmod = (post_residual % 10) as f64;
    score -= 8.0 * rmod;

    // Integer-division thresholds: how many "average small items" fit
    let slots = post_residual / 10;
    if slots == 0 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely — reward, scaled by how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - snug / cap);
        } else {
            // next item won't fit here; penalize if this bin was the only fitting one
            score += 20.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitter
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin gets moderate default,
    // made less attractive when good fits exist elsewhere
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted early in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 150.0 - 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 15.0;
        }
        // more open bins -> prefer reusing them
        score += 6.0 * open_bins_count as f64;
    }

    // Mean residual context: if open bins are already roomy on average,
    // slightly favor filling this one
    score -= 10.0 * (bin_residual as f64 - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size 1
    // is impossible, but gaps too small to be useful relative to item scale)
    // are heavily penalized.
    if post_residual > 0 {
        // A gap is "dead" if it cannot fit the next item (when known) or is
        // very small in absolute terms.
        let dead_gap = if next_item_size > 0 {
            (post_residual as u64) < (next_item_size as u64)
        } else {
            post_residual <= 10
        };
        if dead_gap {
            score += 25.0 + 0.5 * post_residual as f64;
        } else {
            // Reward gaps that exactly match the next item (perfect lookahead fit).
            if next_item_size > 0 && post_residual as u64 == next_item_size as u64 {
                score -= 30.0;
            }
        }
    } else {
        // Perfect fill: strongly favored.
        score -= 40.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over spreading; penalize placements that leave lots of residual.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: placing into a bin far below the mean residual
    // (large bin) is good; placing into already-small-residual bins wastes
    // the remaining space.
    let res_gap = mean_residual - post_residual as f64;
    score -= 0.1 * res_gap;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * open_bins_count as f64;
        // Allow new bin early in stream or when item is huge (poor fit likely).
        if item_size > 70 {
            score -= 25.0;
        }
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.05 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item can't fit in post_residual, this bin's remaining
    // space is likely wasted; add mild penalty.
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect match for next item -> strong reward.
        if diff == 0.0 {
            score -= 45.0;
        } else if post_residual as f64 >= next {
            // Next item still fits: reward proportional to closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize tight leftover dead space.
            score += 8.0 * (1.0 - post_residual as f64 / next);
        }

        // Two-step chain: after placing next item, residual would be...
        let two_step = post_residual as f64 - next;
        if two_step >= 0.0 {
            // Prefer leaving residuals that are either ~0 or large enough to be reusable.
            if two_step < 10.0 {
                score -= 15.0; // near-perfect packing
            } else if two_step < 30.0 {
                score += 6.0; // awkward mid-size dead space
            }
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 20.0;
    }

    // Relative-to-mean-residual coupling: prefer bins already tighter than average
    // so loose bins stay available for larger future items.
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred for decent fits.
        score += 55.0;
        // But if no open bin fits well (large item, few options), relax the penalty.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Late in the stream with many open bins, opening a new bin is cheaper
        // than fragmenting residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 3 && item_size >= 60 {
            score -= 20.0 * progress;
        }
    } else {
        // Penalize wasting a large residual on a small item.
        let waste = (bin_residual - item_size) as f64;
        if waste > 50.0 && item_size < 30 {
            score += 10.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += 0.10 * (bin_capacity as f64 - bin_residual as f64).recip() * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual more than linearly
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if next item fits in post_residual, reward this placement strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.5 * (next_item_size as f64);
        } else {
            // Penalize leaving residual just above/below awkward zone relative to next item
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits
        score += 12.0;
        // Late in the stream, opening new bins is more wasteful
        score += 20.0 * progress;
        // If many bins are open, discourage adding more
        score += 1.5 * open_bins_count as f64;
        // But if no existing bin fits well (high post_residual would remain elsewhere),
        // a fresh bin becomes attractive: handled implicitly since existing bins keep raw score.
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Slight preference for filling larger residual bins when few fitting bins exist
    if fitting_bins_count <= 2 {
        score -= 0.1 * (bin_residual as f64);
    }

    // Mild time-decay on residual penalty: early on, waste matters less
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, quadratically (dead space is worse than linear).
    let mut score = pr + (pr / cap) * pr * 0.35;

    // Smooth reward for tight fits: interaction of post_residual with bin fill ratio.
    let fill = (bin_residual as f64) / cap;
    score -= fill * fill * 12.0 * (1.0 - pr / cap);

    // Stream-progress coupling: as the stream advances, prefer tighter packing more aggressively.
    let tight_bias = 0.5 + 1.5 * progress;
    score *= 1.0 + tight_bias * (pr / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving residual that fits the next item (smooth, not piecewise).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let fit_next = 1.0 / (1.0 + (gap / 10.0).powi(2));
        score -= 10.0 * fit_next;
    }

    // Mean-residual coupling: if this bin's post-residual deviates badly from the fleet mean,
    // penalize (keeps residuals homogeneous for future items).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make it attractive only when open bins are nearly full on average
    // or the item is large relative to typical residuals; otherwise slightly discourage.
    if bin_residual == bin_capacity {
        let openness = mean_residual / cap;
        let urgency = 1.0 / (1.0 + (-6.0 * (openness - 0.35)).exp());
        score = 0.45 * cap + 30.0 * urgency - 15.0 * progress;
        // Large items prefer a fresh bin more.
        score -= (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fits / tiny remnants are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 5 {
        score -= 25.0;
    } else if pr < 10 {
        score -= 10.0;
    } else {
        // dead-space classes by modulo on capacity fractions
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        if pr >= half {
            score -= 15.0; // residual still large => bin remains reusable
        } else if pr >= quarter {
            score += 5.0; // mid-range remnant: mediocre
        } else {
            score += 20.0; // small dead space below quarter
        }
        // penalty grows when remnant is "awkward": pr % 5 != 0 style classes
        if pr % 5 != 0 {
            score += (pr % 5) as f64 * 2.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 20.0 - slack as f64;
            } else {
                score += slack as f64 * 0.3;
            }
        } else {
            // next item won't fit here regardless; slight bonus for tight fit now
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // opening new bin is only good if we'd otherwise leave big dead space
        let dead = post_residual; // == capacity - item_size
        score += 55.0; // default: prefer reusing open bins
        if dead > bin_capacity as f64 * 0.6 {
            score -= 40.0; // large item into fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Progression coupling: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Mean residual coupling: if bin is far below average residual, it's a good dump target.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize a gap that cannot fit the next item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (0.5 + progress);
    score += pressure * 0.8;

    // Prefer bins tighter than the mean residual (better packing density).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight penalty for opening a brand-new bin unless residual after placement is large.
    if bin_residual == bin_capacity {
        score += 5.0 - (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize if leftover cannot fit the next item (dead space),
    // reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 6.0 + 0.10 * post_residual as f64;
        }
    }

    // Last-chance bin: this is the only bin that fits; strongly favor using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 0.2 * item_size as f64;
    }

    // Penalize using a bin when many bins fit the item (keep flexibility),
    // scaled by how much slack this bin would leave versus the mean.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
        if (post_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    // Early in the stream: be more willing to open new bins / keep bins clean.
    // Late in the stream: consolidate aggressively.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 10.0 * progress;

    // When few open bins, mild preference for filling them; when many open,
    // penalize spreading thin.
    score += 0.5 * open_bins_count as f64 * tightness;

    // New-bin candidate: choose a fresh bin only if the best possible use of it
    // is plausible — i.e., penalize opening a new bin mildly, more so when
    // other bins fit well (low mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 15.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            // Pairing a big item into a fresh bin is decent.
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more.
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * progress_weight * pr_norm * pr_norm;

    // Reward tight fits non-linearly (quadratic in fill fraction)
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 - progress_weight * 0.5);

    // Penalize bins whose residual is far from the mean residual (imbalance)
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving a residual that barely fits or misses next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: make it mildly unattractive unless residuals are mostly tiny
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress - 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual into capacity-fraction classes.
    // Residuals that are "harmonically useful" (multiples of common item sizes)
    // are penalized less; awkward dead space is penalized more.
    let cap = bin_capacity as f64;

    // Fraction of bin wasted by this placement.
    let waste_frac = post_residual as f64 / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Class of post_residual via integer division thresholds (harmonic bands).
    let class = post_residual / 10; // band 0..=10
    match class {
        0 => score -= 25.0,             // near-perfect fit (0-9)
        1 => score -= 12.0,             // excellent (10-19)
        2 => score -= 5.0,              // good (20-29)
        3 => score -= 0.0,              // neutral (30-39)
        4 => score += 4.0,              // awkward (40-49)
        5 => score += 8.0,              // half-empty (50-59)
        6 => score += 10.0,             // (60-69)
        7 => score += 11.0,             // (70-79)
        8 => score += 12.0,             // (80-89)
        _ => score += 13.0,             // nearly untouched bin (90-100)
    }

    // Modulo arithmetic: residuals that are multiples of 10 are "harmonic"
    // (many items sizes align with them), reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0; // perfect chaining
        } else if gap <= 10 {
            score -= 18.0;
        } else if gap <= 20 {
            score -= 8.0;
        }
        // Penalize if next item would leave a tiny dead sliver.
        if gap > 0 && gap < 5 {
            score += 5.0;
        }
    }
    // If next item cannot fit here, this bin's residual is dead space for the horizon.
    if next_item_size > post_residual {
        score += 6.0;
    }

    // Last-chance logic: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress and open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 25.0 * progress + 3.0 * open_bins_count as f64;
        // If open bins are crowded (low mean residual), a new bin is more attractive.
        score -= 0.5 * mean_residual;
        // If no bin fits, new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to fill already-open bins when many are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Small tie-breaker toward tighter fits.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 100.0; // perfect fit: strongly reward
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        }
        // Penalize if the gap is too small for the next item but nonzero.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; slightly reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 - 10.0 * progress;
        // If item fills a large chunk of a fresh bin, opening is more attractive.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            // leftover after two placements; penalize small dead space
            let left = post_residual - next_item_size;
            if left < 10 {
                score += (10 - left) as f64 * 2.0;
            }
        } else {
            // next item can't reuse the residual; small residual is still fine
            score -= (post_residual as f64).sqrt() * 2.0;
        }
    }

    // Compare against mean residual: prefer bins that become tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last fitting bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residual is large (wasteful to split) or no good fit
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Penalize creating tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit shaping: reward tight fits (small post_residual) non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that is too small to ever host a plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but imperfectly: mild reward scaled by how much is left after both
            let after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize proportional to wasted potential
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> consolidate, prefer filling bins.
    if open_bins_count > 1 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score -= 4.0 * consolidation;
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep residuals clean);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    // New-bin candidate handling: opening a fresh bin is attractive early or when this item
    // would leave a large awkward residual in an existing bin; otherwise discourage it.
    if bin_residual == bin_capacity {
        let awkward = if post_residual > 0 && post_residual < item_size { 1.0 } else { 0.0 };
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        score += 20.0 - 15.0 * progress + 10.0 * awkward - 3.0 * pressure;
        // If the item fits an existing bin perfectly, opening a new bin is wasteful.
        if post_residual == 0 {
            score += 50.0;
        }
        // If no existing bin fits (this call is the only option), new bin must look good.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Small penalty for leaving residual close to but below the minimum item size band.
    if post_residual > 0 && post_residual < 20 {
        score += 0.3 * (20 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Smoothly increasing penalty on large residuals as stream progresses.
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 25.0 * tight * (1.0 - progress);

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 12.0 * (gap / cap) * (0.3 + 0.7 * progress);
        } else {
            // Next item fits exactly-ish: reward.
            score -= 8.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 3.0 * (open_bins_count as f64 / (1.0 + progress * 10.0)) * norm_pr;

    // Prefer bins below the mean residual slightly (keeps residuals balanced).
    score += 5.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact / near-exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic classes: bucket post_residual by modulo classes of capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    // Dead-space penalty grows super-linearly once residual exceeds half capacity.
    if pr > c * 0.5 {
        score += (pr - c * 0.5) * 1.5;
    }
    // Quarter-class modulation: residuals near multiples of capacity/4 are more usable.
    let quarter = c / 4.0;
    let class = (pr % quarter) / quarter; // in [0,1)
    score += class * 8.0;

    // Integer-division threshold on post_residual: can it host the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains nicely: reward proportional to tightness of that fit.
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 30.0 - chain_fit.min(25.0);
        } else {
            // Leftover dead space relative to next item: penalize.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // Harmonic pairing: item + next exactly fills a bin class.
        if item_size + next_item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        // Opening a new bin is penalized mildly, but drops if all open bins would waste a lot.
        score += 45.0 - avg_waste.min(45.0);
        // Early in the stream, opening bins is cheap (need parallel capacity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer fuller bins overall: tie-break by how bin compares to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for likely future
    // items (min size 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidating into
    // existing bins (penalize opening new ones) by boosting new-bin score.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the next item fits perfectly in this fresh bin, allow opening.
        if next_item_size == item_size || next_item_size == post_residual {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item exactly fills the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size < post_residual && post_residual - next_item_size < 10 {
        // Next item would leave a dead gap; slightly penalize.
        score += 8.0;
    }

    // Mild mean-residual coupling: prefer bins with residual close to mean
    // to keep the bin population balanced.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step packing: heavily reward.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how tightly it fills.
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * tight;
        } else {
            // Next item won't fit here: penalize creating dead space that blocks it.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(40.0);
        }
    }

    // Compare post_residual against mean residual: prefer bins left with small residuals
    // (well-packed) relative to the fleet average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so that only
    // genuinely good fits on open bins beat it.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Slight preference to fill older/more open bins when many bins are open.
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early in stream, be slightly more willing to open new bins (exploration of packing).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero.
    if post_residual > 0 {
        score += 12.0 * (post_residual as f64 / bin_capacity as f64).powf(0.35);
    } else {
        // Perfect fill is excellent.
        score -= 25.0;
    }

    // Penalize dead space that no future item can plausibly use.
    // Smallest plausible item is ~1; but practical minimum granularity ~5.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty for blocking it
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate logic: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is good for large items or when no open bin fits well.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items, or when open bins are crowded (low mean residual).
        score += 45.0 * (1.0 - item_frac); // base penalty for opening a bin
        score -= 30.0 * item_frac * item_frac; // reward for large items
        if mean_residual < item_size as f64 {
            score -= 25.0; // existing bins are tight; new bin attractive
        }
        // Late in the stream, avoid proliferating bins.
        score += 20.0 * progress;
        // If many bins already open and none fit, still prefer reusing when possible.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins with residual close to item (best-fit core).
    score += 0.05 * (bin_residual - item_size) as f64;

    // Encourage balancing residuals across bins: prefer bins near mean residual.
    score += 0.03 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = norm_pr * norm_pr * 120.0 + norm_pr * 20.0;

    // Smooth polynomial coupling with stream progress:
    // early on, mildly tolerate slack; late, penalize dead space more strongly
    let progress_weight = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score *= progress_weight;

    // Non-linear interaction: post_residual vs mean residual of open bins.
    // Creating residual far below mean wastes capacity; far above mean is also bad.
    let mean_norm = mean_residual / cap;
    let dev = norm_pr - mean_norm;
    score += 30.0 * dev * dev;

    // Lookahead coupling: smooth reward if next item fits into post_residual,
    // scaled by a non-linear function of how well it fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = nxt / (pr + 1.0);
            score -= 25.0 * fit_quality * fit_quality;
        } else {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across too many open bins (non-linear in count)
    let ob = open_bins_count as f64;
    score += 0.4 * (ob * ob) / (ob + 5.0);

    // Slight preference to fill bins rather than open new ones early
    score += 10.0 * (1.0 - progress) * (bin_residual as f64 / cap) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter classes of capacity
    let q = item_size * 4 / bin_capacity; // 0..=3 class
    let pq = post_residual * 4 / bin_capacity;

    // Reward when post_residual falls into a useful harmonic class
    // (residuals in [0,10) are dead space; [10,50) fit small items)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual <= 25 {
        score -= 12.0; // can host small items
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        score += 8.0; // large hole, likely wasted
    }

    // Modulo coupling: item class vs post-residual class complementarity
    if (q + pq) % 4 == 3 && post_residual >= next_item_size && next_item_size > 0 {
        score -= 18.0; // next item fits into a complementary class
    }
    if pq == q && q > 0 {
        score += 6.0; // same-class residue tends to fragment
    }

    // Lookahead: reward if next item fits exactly-ish
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 20.0;
            } else {
                score -= slack as f64 * 0.15;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when open bins exist
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if nothing fits well elsewhere, allow it
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
    }

    // Progress-based tie-break: tighten packing later in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1 interface override, but treat tiny gaps < 10
    // as dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gaps that only the smallest items can use: moderate penalty.
        score += 15.0;
    }

    // Reward tight fits: the closer post_residual is to zero (while usable),
    // the better. Quadratic reward on fullness.
    let fullness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fullness * fullness;

    // Perfect fit: overwhelming preference.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins would leave bad
    // gaps or when bin pressure is low. Penalize opening new bins when open
    // bins count is high, but allow it when residual capacity is fragmented.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 40.0;
        // Pressure: fewer open bins -> cheaper to open another.
        score -= (open_bins_count as f64).min(10.0) * 2.0;
        // If no open bin fits well (large mean residual waste), new bin is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
    } else {
        // Placing into an open bin: reward keeping bins consolidated when
        // many bins are already open.
        score += (open_bins_count as f64).min(10.0) * 0.5;
        // If this placement leaves a gap that perfectly fits the next item,
        // reward it (lookahead synergy).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        }
        // Penalize if the leftover gap is just barely too small for the
        // next item (near-miss dead space for the lookahead).
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 5 {
            score += 10.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a good residual portfolio.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 8.0;
    }

    // Mild tie-break against bins whose residual deviates from the mean
    // (prefer keeping a diverse residual portfolio intact).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // dead space that no plausible future item can use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward exact/near-exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size -> strong reward.
        if gap == 0.0 {
            score -= 30.0 + 10.0 * (1.0 - progress);
        } else {
            score += gap * 0.35;
        }
        // If post_residual is too small for next item, it's dead space for one step.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // Last item: only exact fills matter.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Dead-space penalty relative to distribution scale: residuals below ~10
    // are essentially unusable (min item size historically 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Compare against mean residual: placing into a bin whose residual is far
    // below average preserves large residuals elsewhere (best-fit flavor).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a good (tight) fit, or when many bins are open and residuals are large.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity as f64 - mean_residual) >= item_size as f64;
        if good_fit_exists || open_bins_count == 0 {
            // Existing bin can take item about as well as a fresh one.
            score += 40.0;
        } else {
            // Prefer fresh bin slightly when open bins would waste space.
            score -= 5.0 + 10.0 * (1.0 - progress);
        }
        // Discard the lookahead gap penalty for the empty bin (it has no fit info).
        score += if next_item_size > 0 {
            ((post_residual as i64 - next_item_size as i64).abs() as f64) * 0.35
        } else {
            0.0
        };
    }

    // Mild pressure to consolidate when many bins are open.
    score -= open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tightness = post_residual as f64 / cap;
    score += tightness * 20.0;

    // Penalize leaving dead space that nothing small can use later.
    // Dead space = residual too small for typical next item.
    if post_residual > 0 {
        let dead = (post_residual as f64) < 10.0;
        if dead {
            score -= 15.0; // nearly-full bin is great (item almost fills it)
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            score -= (1.0 - gap / cap) * 25.0; // next item fits well here too
        } else {
            score += 8.0; // next item won't fit; this bin becomes dead-ish
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation (prefer fuller bins).
    let load_frac = 1.0 - (bin_residual as f64) / cap;
    score -= load_frac * (open_bins_count as f64).min(20.0) * 2.0;

    // Time horizon: early in stream, be more liberal opening bins (worse score for open bins
    // relative to new bin); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * (1.0 - load_frac);

    // New-bin candidate calibration: empty bin should get a mid-range score so
    // it beats only truly poor fits (large post_residual, no lookahead match).
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin costs roughly half a bin of expected waste.
        score = 55.0 + (1.0 - progress) * 10.0;
        // If no open bin fits at all, opening is fine (fitting_bins_count==0 handled upstream,
        // but guard anyway).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If current item is large relative to capacity, a fresh bin is attractive.
        if (item_size as f64) / cap > 0.5 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if average residual across bins is small, bins are
    // nearly full — prefer packing into them rather than opening new ones.
    score += (mean_residual / cap) * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, moderate residual waste is tolerable; late, waste is heavily penalized.
    let norm_post = post / cap; // 0..1
    let base = post;

    // Smooth cubic growth: waste penalty amplifies as stream progresses.
    let progress_coupling = base * (0.5 + 1.5 * progress * progress);

    // Non-linear dead-space term: residuals that are too small to be useful
    // (quadratic in normalized residual, smoothed) get extra penalty.
    let dead_space = 8.0 * norm_post * norm_post * (1.0 - progress);

    // Reward tight fits: if post_residual is small relative to item size.
    let tightness = -12.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bonus: this is the only bin that fits, strongly favor it
    // (penalize alternatives by making this score low).
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    let lookahead = if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            -20.0
        } else if next_item_size as f64 <= post {
            -6.0 * (next_item_size as f64 / cap)
        } else {
            4.0 * (1.0 - next_item_size as f64 / cap)
        }
    } else {
        0.0
    };

    // Coupling with mean residual: prefer bins whose residual deviates
    // smoothly (non-linearly) from the mean, favoring larger residuals.
    let mean_coupling = -3.0 * ((bin_residual as f64 - mean_residual) / cap).tanh();

    // New-bin candidate handling: an empty bin has high base residual, but
    // when few bins fit the item, opening a new bin can be attractive.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    let new_bin_adjust = if is_new_bin {
        if fitting_bins_count == 0 {
            -50.0
        } else {
            // Slight preference to reuse open bins early; allow new bins late
            // when many bins are open (load spreading) via smooth term.
            6.0 * (1.0 - progress) - 4.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0))
        }
    } else {
        0.0
    };

    base + progress_coupling + dead_space + tightness + last_chance + lookahead + mean_coupling + new_bin_adjust
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are less penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr > 0 {
        // residue divisible by common sizes => likely reusable
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                class_bonus += 4.0;
            }
        }
        if pr <= 10 {
            class_bonus += 6.0; // near-perfect fill
        }
    } else {
        class_bonus += 12.0; // exact fit is ideal
    }
    score -= class_bonus;

    // Fractional fill of the bin: reward high occupancy ratio nonlinearly.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 20.0 * fill * fill;

    // Lookahead: penalize if post_residual cannot host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // harmonic coupling: post_residual exactly matches next item class
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else {
            score += 6.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Tight-fit reward: item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.8 {
        score -= 10.0 * (tightness - 0.8);
    }

    // Dead-space penalty: small post_residual that is not zero and not reusable.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.1 * (mean_residual - post_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any realistic
    // future item (1..=10 range floor, but treat < 15 as near-dead) are heavily penalized.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 10 {
        // Tiny gap that likely becomes dead space unless next item is tiny.
        score += 25.0;
    }

    // Reward post_residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // This placement strands the next item: penalize proportionally.
            score += 18.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (deeper fill => lower post_residual already helps; add coupling).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Prefer bins whose residual is close to the mean (keeps residuals homogeneous,
    // leaving large gaps concentrated for big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, be more willing to open bins (keep flexibility);
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, resist late unless residual is truly bad.
        score += 20.0 + 60.0 * progress;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus (strong subtraction)
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how close the next item is to fitting later
            score += diff * 0.35;
            // If next item would NOT fit in the residual, penalize proportionally
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Compare residual to mean residual across open bins: leaving residual near mean is fine,
    // creating much larger residual than mean wastes capacity.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space that nothing can use (items >= 1, but small gaps under ~10 are near-useless)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when current bins would leave very poor fits
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduce if many open bins already exist and fit is bad
        score = bin_capacity as f64 - 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin guarantees next item fits
            score -= 10.0;
        }
        // As stream progresses, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Tight fit reward: leaving almost nothing behind
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize creating small, hard-to-use post residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting a good bin.
            score += 5.0;
        }
    }

    // Last-chance bin: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: opening a new bin should be costly unless
    // the item is large relative to capacity or fits are scarce.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 45.0 * large_item - 70.0 * scarcity - 10.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    if !is_new_bin {
        let consolidation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= 20.0 * consolidation.max(0.0);
        if open_bins_count > 4 {
            score -= 3.0;
        }
    }

    // Mild late-stream bonus for filling bins more completely.
    score -= progress * (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - post / cap;

    // Non-linear coupling of post_residual with stream progress
    let progress_coupling = post * (1.0 + 0.8 * progress * progress);

    // Quartic dead-space penalty: strongly punish small unusable residuals
    let dead_space = (post / cap).powi(4) * 60.0;

    // Reward tight fits (large item fraction) smoothly
    let fit_reward = -40.0 * tightness * tightness;

    // Last-chance bonus when this is the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -25.0 * (1.0 - progress) } else { 0.0 };

    // Lookahead: prefer bins whose post residual still fits the next item
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx { -12.0 * (nx / cap) } else { 10.0 * (1.0 - post / nx.max(1.0)) }
    } else { 0.0 };

    // Slight preference to spread across bins early, consolidate late
    let spread = 3.0 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual, smooth quadratic
    let mean_dev = ((post - mean_residual) / cap).powi(2) * 15.0;

    let mut score = progress_coupling + dead_space + fit_reward + last_chance + lookahead + spread + mean_dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo-10 dead-space class: residuals divisible by 10 remain reusable
        // by a wider range of future items; penalize odd/prime-ish slivers.
        let class = post_residual % 10;
        score += (class as f64) * 2.0;
        if post_residual < 10 {
            score += 50.0; // dead space sliver
        }
    }

    // Integer-division thresholds: how many items of the lookahead size fit in post_residual.
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            score -= 30.0 + (next_item_size as f64) * 0.2;
            // Bonus if next item exactly fills remaining space (harmonic pairing).
            if post_residual == next_item_size {
                score -= 200.0;
            }
            // Bonus if post_residual is an integer multiple of next_item_size.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 40.0;
            }
        } else {
            score += 15.0; // lookahead cannot use this bin's remainder
        }
    }

    // Capacity fraction coupling: prefer bins whose residual is a large fraction of capacity.
    let frac = (bin_residual as f64) / cap;
    score -= frac * 10.0;

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score = 250.0 - pressure * 100.0
            + (open_bins_count as f64) * 5.0
            + (step_index as f64 / total_items.max(1) as f64) * 50.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0; // roomy bin helps the larger upcoming item
        }
    }

    // Mean-residual coupling: when mean residual is high, tighten packing (favor small post_residual).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * (11.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / (post_residual as f64 + item_size as f64)) * 8.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a gap too small for it.
        score += (post_residual as f64 / bin_capacity as f64) * 4.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        score -= 2.0 + mean_residual * 0.05;
    }

    // Slight preference for using bins with below-mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.03;
    score
