pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize creating small unusable dead space (< next item size).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 15.0 + 0.3 * (nxt - post_residual as f64);
        }
        // Reward bins whose post-residual matches the next item exactly.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Slight preference for fuller bins when many bins are open (consolidation).
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Time-horizon coupling: early in the stream, be conservative about dead space;
    // late in the stream, exploit tight fits more aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tight;

    // Compare against mean residual: bins with residual far below mean are precious;
    // bins with residual above mean can absorb loose fits.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate handling: empty bin should only win if item is large
    // relative to typical open-bin residuals, or no good fit exists.
    if bin_residual == bin_capacity {
        let big = (item_size as f64) / (bin_capacity as f64);
        score += 20.0;
        if big > 0.6 {
            score -= 25.0 * (big - 0.6);
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) * (1.0 - fill * fill);

    // Dead-space penalty: small post residuals that waste capacity
    if pr > 0.0 {
        score -= (pr / cap).powi(2) * 30.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 12.0 * (1.0 - (nxt / cap - 0.5).powi(2));
        } else {
            score += 6.0 * (nxt / cap);
        }
    }

    // Prefer bins tighter than the mean residual (smooth quadratic divergence)
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Mild preference for opening new bins late in the stream when item is large
    score += 8.0 * fit_ratio * progress * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 5 residue classes.
    let fifth = bin_capacity / 5; // 20
    let class = post_residual / fifth; // 0..=5
    // Reward tight fits: lower class (smaller leftover) gets a discount.
    score -= (5 - class as i32) as f64 * 12.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 5 {
        score -= 200.0;
    }

    // Dead-space penalty: leftover too small for the smallest item (1..100, min 1).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable: reward proportionally, with extra if exact match.
            score -= 30.0 + 0.5 * next_item_size as f64;
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Leftover can't serve the next item: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Modulo-harmonic bonus on item size classes (favor pairing items whose
    // sizes sum to harmonic fractions of capacity).
    let sum_class = (item_size + post_residual) % 10;
    if sum_class == 0 {
        score -= 25.0;
    } else if sum_class == 5 {
        score -= 10.0;
    }

    // Penalize spreading across many open bins early; encourage consolidation
    // when few bins remain relative to stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    // Align with mean residual: bins far below mean residual (more filled)
    // are preferred; bins above mean get penalized.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
    score -= (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    // New-bin candidate: only attractive when nothing fits well or stream is late.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual + 30.0;
        if poor_fit || fitting_bins_count == 0 || progress > 0.8 {
            score -= 100.0;
        } else {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.06;
    score
