pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainable bin: reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack.min(15.0);
        } else {
            // next item cannot chain here; penalize large dead space
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.3;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to residual
    if bin_residual == bin_capacity {
        score += 25.0;
        // but allow new bin if next item is large and current item leaves big residual
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Early stream: be slightly more conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted space quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Penalize leaving dead space that likely cannot be reused.
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // perfect fill
    } else if post_residual > 0 && post_residual < item_size {
        // small leftover, mildly good
        score -= 5.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for next item: penalize proportionally
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 2.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins) early.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * (10.0 + 20.0 * (1.0 - t));

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_fits_next = next_item_size > 0 && next_item_size <= bin_capacity - item_size;
        let mut new_bin_score = 55.0;
        if poor_alternatives > 0.0 {
            new_bin_score -= 45.0;
        }
        if item_fits_next {
            new_bin_score -= 10.0;
        }
        if post_residual < 20 {
            new_bin_score += 15.0; // avoid opening bin for near-full fill
        }
        score += new_bin_score - 55.0; // baseline so empty bin is not auto-preferred
        // Time horizon: early stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - t);
    }

    // Slight preference for larger items going into larger-residual bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual with smooth polynomial shaping of dead space.
    let x = post / cap;
    let dead_space = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes mid-range waste, tolerates near-full

    // Stream-progress coupling: later in stream, waste matters more.
    let urgency = 1.0 + 1.5 * progress * progress;

    // Tight-fit reward: item filling most of residual is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tight_bonus = -2.0 * fill_ratio * fill_ratio;

    // Lookahead: prefer leaving residual that can host the next item.
    let lookahead = if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        -0.5 * (post_residual as f64 / cap)
    } else if next_item_size > 0 {
        0.4
    } else {
        0.0
    };

    // Last-chance pressure: strongly favor the only bin that fits.
    let last_chance = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // New-bin candidate: penalize mildly unless current bins are all tight.
    let new_bin_bias = if bin_residual == bin_capacity {
        0.8 + 2.0 * (1.0 - progress) + mean_residual * 0.02
    } else {
        0.0
    };

    let mut score = post + dead_space * 20.0 * urgency + tight_bonus + lookahead + last_chance + new_bin_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod small divisors
    // captures "dead space" classes that are hard to fill later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals in awkward classes (e.g. mod 10 in {1..9})
    // are hard to fill; residual 0 is perfect; residual >= 50 is still usable.
    let mod10 = post_residual % 10;
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else if post_residual > 50 {
        score -= 8.0; // still roomy
    } else {
        // small awkward residual: penalize by how far from a class boundary
        score += (10 - mod10) as f64 * 1.5;
    }

    // Harmonic class of next item vs post residual: does the lookahead fit?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 12.0 - tight * 0.15;
        } else {
            // lookahead won't fit here: penalize bins that strand the next item
            score += 6.0;
            // worse if this bin would be nearly closed anyway
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many options: prefer tighter fits, mild scaling
        score += (fitting_bins_count as f64 - 2.0) * 0.5;
    }

    // Capacity fraction classes: prefer bins whose residual is a nice fraction
    let frac = pr / cap;
    if (frac - (frac * 4.0).round() / 4.0).abs() < 0.02 {
        score -= 3.0; // residual near 0, 25%, 50%, 75% boundaries: reusable class
    }

    // Stream progression: early on, be picky; late, accept good-enough fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // Prefer spreading across bins when mean residual is high (avoid clustering)
    if (mean_residual - pr) > 20.0 {
        score += 2.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 10.0 + open_bins_count as f64 * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        // Dead space is unusable if it cannot hold the smallest possible item (1..=100 range, assume min ~10)
        let min_item = 10u32;
        if post_residual < min_item {
            score += 60.0; // fully dead space penalty
        } else {
            // Gradual penalty as residual shrinks toward unusable sizes
            let shrink = (min_item as f64) / (post_residual as f64);
            score += 25.0 * shrink * shrink;
        }
    } else {
        score -= 30.0; // perfect fit is strongly rewarded
    }

    // Reward tight fits relative to item size
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        // next item cannot use the leftover: penalize creating stranded space
        score += 8.0 * ((post_residual as f64) / 100.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when many bins are open
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Slight preference for new bins early vs late in the stream is neutral; keep mild late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual is already base score).
    // Penalize large dead space quadratically.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills the leftover
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize wasted capacity relative to next item
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening new bin, more when many bins are open or fit is available.
        score += 30.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // sometimes better to open fresh bin for large items
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fit reward: strongly favor placements leaving little dead space.
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 40.0 * fit_ratio * fit_ratio;

    // Reward high fill fraction of the bin.
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small post-residual is nearly dead space anyway; slight bonus.
        score -= 10.0;
    } else if post_residual < 20 {
        // Mid-range dead space: mildly penalize awkward leftovers.
        score += 8.0;
    }

    // Lookahead: if the next item fits into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward if next item then leaves a tight fit too.
            let nr = post_residual - next_item_size;
            if nr == 0 {
                score -= 20.0;
            }
        } else {
            // Post-residual too small for the next item: penalize dead space.
            score += 12.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
        if post_residual as f64 > 0.5 * (bin_capacity as f64) {
            // Poor fit but only option: still favored, but less.
            score += 20.0;
        }
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = (open_bins_count as f64) / ((total_items.max(1) as f64).sqrt() + 1.0);
    if !is_new_bin {
        score -= 5.0 * open_pressure;
    } else {
        // Opening a new bin becomes more costly as open bins accumulate.
        score += 10.0 + 8.0 * open_pressure;
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier future packing).
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += 40.0 * progress;
    } else {
        score -= 15.0 * progress;
    }

    // Large items: prefer them in emptier bins to avoid fragmentation.
    if item_size >= 70 {
        score += 0.2 * (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits, but heavily penalize near-zero residuals (dead space)
    let mut score = pr;
    let dead = (1.0 - pr / cap).max(0.0); // 1 when residual ~ 0
    score += 18.0 * dead * dead * pr / cap; // quadratic dead-space penalty scaled by residual

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer leaving room (larger residuals OK); late, pack tightly.
    let tight = (pr / cap).powf(1.0 + 2.0 * progress);
    score += 6.0 * tight * (1.0 - progress);

    // Penalize using a big-residual bin for a small item (waste), smooth polynomial
    let waste = (it / cap) * (bin_residual as f64 / cap);
    score += 8.0 * waste * (1.0 - it / cap);

    // Reward last-chance bins (only fitting bin) with smooth urgency term
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr / cap);
    }

    // Lookahead: if next item would fit the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 7.0 * fit_quality;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mean residual coupling: avoid draining the bin far below the fleet mean
    score += 3.0 * ((pr - mean_residual) / cap).powi(2);

    // New-bin candidate: baseline that competes with poor fits; more attractive early
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space in small-residue classes is worse.
    let residue_class = post_residual % 10;
    score -= 12.0 * (1.0 - residue_class as f64 / 9.0);

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 35.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Integer-division threshold: leftover that can host "typical" next items.
    let usable = post_residual / 10; // how many 10-blocks remain
    score -= 4.0 * usable as f64;

    // Lookahead coupling: harmonic class of next item vs post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here: reward, more if fit is tight (harmonic match)
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if gap < 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot follow here: penalize proportionally to how much it misses
        let miss = next_item_size - post_residual;
        score += 0.3 * miss as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if no open bin leaves a workable residue, allow opening
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (pack big first into full bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver (min item size ~1-10 zone)
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        score -= 25.0; // perfect fit: eliminate dead space entirely
    }

    // Reward tight fits generally (small waste relative to capacity).
    score -= (bin_capacity - post_residual - item_size) as f64 * 0.0; // item_size already implied
    score -= (item_size as f64 / bin_capacity as f64) * 10.0; // favor filling big chunks into this bin

    // Pressure on number of open bins: discourage opening new bins when many exist.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate (empty bin): penalize so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item leaves a nice residual for the lookahead item, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheap; late, it's costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead synergy: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.5 * slack; // penalty grows with leftover after hypothetical next placement
        } else {
            let deficit = (next_item_size - post_residual) as f64;
            // next item won't fit here; penalize proportionally to how much dead space remains
            score += 0.8 * deficit;
        }
    } else {
        // last item: just minimize post_residual
        score += 10.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are less attractive
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin unless nothing decent fits
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && (post_residual as f64) < 0.5 * bin_capacity as f64;
        score += if decent_fit_exists { 150.0 } else { 30.0 };
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly prefer tight fits: small post_residual rewarded.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item can't use leftover; mild penalty proportional to wasted potential.
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is generally costly,
    // but attractive when existing bins have small residuals relative to item.
    if is_new_bin {
        let crowding = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Open new bin if existing bins are quite full (low mean residual)
        // or item is large relative to mean residual.
        let waste = bin_capacity as f64 - item_size as f64;
        score += 25.0 + waste * 0.6;
        // Early in stream, opening bins is cheaper (many items to come).
        score -= (1.0 - progress) * 30.0;
        // If mean residual barely fits the item, new bin is better.
        if mean_residual >= item_size as f64 && mean_residual < item_size as f64 + 8.0 {
            score -= 35.0;
        }
        // Many open bins with slack: reuse instead.
        score += crowding * 40.0;
    } else {
        // Mild preference for filling fuller bins among open ones.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 15.0;
    }

    // Late in stream: consolidate aggressively, avoid new bins.
    if progress > 0.8 && is_new_bin {
        score += 50.0 * progress;
    }

    // Tie-break: prefer bins with residual close to item (smooth tightness).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer low post_residual, with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth progress coupling: tighten packing as stream advances
    score -= 25.0 * progress * (1.0 - norm_post) * (1.0 - norm_post);
    score += 15.0 * progress * norm_post * norm_post;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_post);
    }

    // Dead-space penalty for small unusable leftovers
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (post - nxt).abs();
        let fit_quality = 1.0 - (fit_gap / cap).clamp(0.0, 1.0);
        score -= 12.0 * fit_quality * fit_quality * (1.0 - progress * 0.5);
    }

    // Mild pressure from many open bins with high mean residual: discourage new fragmentation
    let norm_open = (open_bins_count as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    score += 10.0 * norm_open * (mean_residual / cap).clamp(0.0, 1.0) * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by small units are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else {
        // modularity bonus: residual divisible by 10 or 25 is a "harmonic" class
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // dead space penalty: small unusable residuals
        if pr < 10 {
            score += 40.0 * (10 - pr) as f64;
        }
        // harmonic ladder: penalize residuals in awkward middle classes
        let cls = pr / 10; // integer division threshold class
        match cls {
            1 => score += 8.0,   // 10-19: nearly dead
            2 => score += 3.0,   // 20-29
            3 | 4 => score -= 2.0, // 30-49: sweet spot for mid items
            5 | 6 => score -= 1.0,
            _ => {}
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 5.0 + (next_item_size as f64) * 0.05;
            // harmonic bonus if next item exactly exhausts residual
            if next_item_size == pr { score -= 15.0; }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins unless residual is tiny.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 { score -= 100.0; }
        if item_size >= 50 { score -= 15.0; } // big items fine in fresh bins
    }

    // Prefer packing into fuller bins (small residual before placement).
    score += 0.15 * (bin_capacity - bin_residual) as f64 * -0.0;
    score -= 0.1 * (bin_capacity.saturating_sub(bin_residual)) as f64;

    // Spread-aware: if mean residual is high, favor bins below mean (balance toward fullness).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are pure waste; penalize proportionally to how "dead" they are.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; if it just barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else if next_item_size - post_residual <= 10 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins when mean
    // residual is already tight; encourage filling existing bins.
    score += open_bins_count as f64 * 0.4;
    score -= mean_residual * 0.15;

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave badly dead space.
    if bin_residual == bin_capacity {
        let waste_if_forced = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 || waste_if_forced > 55.0 {
            score -= 70.0;
        } else {
            score += 30.0;
        }
    }

    // Late-stream tightening: be more conservative as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Exact match gets a strong bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item must fit in leftover, else penalize.
        if next_item_size > post_residual {
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Penalize leaving dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mildly discourage opening new bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    // Prefer filling tighter bins (smaller residual before placement).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing else can use (waste), but reward exact fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score += 25.0; // tiny sliver is likely dead space
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * next_fit;
        } else {
            // next item won't fit here; mildly penalize leaving a large unusable gap
            if post_residual < next_item_size {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large and current residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (mean_residual - item_size as f64).abs() > 20.0;
        if poor_fits && item_size >= 50 {
            score -= 30.0 * (1.0 - progress);
        } else {
            score += 120.0; // prefer existing bins by default
        }
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    if bin_residual != bin_capacity {
        score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.5;
    }

    // Late in the stream, consolidate: favor bins that stay usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = post * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling: tight fits become more valuable as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * tightness * progress;

    // Penalize creating dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 18.0 * gap * (1.0 + progress);
        } else {
            let use_frac = (post - nxt) / cap;
            score -= 6.0 * use_frac * use_frac * (0.5 + 0.5 * progress);
        }
    } else {
        // Last item: strongly favor filling existing bins completely
        score -= 20.0 * tightness * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mild penalty when many bins are open and this placement wastes space
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 8.0 * pr_norm * pr_norm * open_pressure * progress;

    // Pull toward mean residual: discourage extreme fragmentation outliers
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity quantized into 8 classes
    let item_class = item_size / 13; // 0..7 harmonic class
    let post_class = post_residual / 13;

    // Reward tight fits: small post_residual
    score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Penalize dead space that is too small to fit the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic matching: if next item can fit into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Extra reward when next item lands in a compatible harmonic class
        let next_class = next_item_size / 13;
        if next_class + item_class == post_class || post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use leftover space: penalize proportionally
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when current bins have poor fits
    if bin_residual == bin_capacity {
        // Base mild penalty so open bins are usually preferred
        score += 15.0;
        // But if the item is large and few fitting bins exist, new bin is fine
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Spread-aware: penalize placing into bins whose residual deviates from mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold: bins whose post_residual falls in a "usable band"
    // (residual divisible-ish by small item classes) get a bonus
    if post_residual % 13 == 0 || post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Prefer filling bins with many open bins (consolidation)
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    if post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins that can also host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 8.0 * open_bins_count as f64;
        if fitting_bins_count >= 2 {
            score += 30.0;
        }
        // Allow new bin late in stream when residuals are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && mean_residual < item_size as f64 {
            score -= 55.0;
        }
    }

    // Open-bins pressure: prefer bins in less crowded sets slightly.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize proportional leftover after hypothetical placement.
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
        } else {
            // Next item won't fit in the residual: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize new-bin candidate when open bins exist with decent fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 250.0;
    }

    // Penalize small unusable fragments (dead space < min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Late-stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect / near-perfect fits get a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Dead space: if the lookahead item cannot use the post-residual,
    // penalize proportionally (lookahead-aware waste).
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        let waste = next_item_size as f64 - post_residual as f64;
        score += 0.6 * waste;
    }
    // If the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and no decent fit exists.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0 + 2.0 * (open_bins_count as f64);
        // Large items relative to residual of others: opening may be fine.
        if item_size > 60 {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, keep bins tight, discourage new bins mildly less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty -= 5.0 * progress;
        // If many bins fit the item, definitely use an existing one.
        if fitting_bins_count > 2 {
            new_bin_penalty += 15.0;
        }
        // If mean residual is large, existing bins have room.
        if mean_residual > item_size as f64 {
            new_bin_penalty += 8.0;
        }
        score += new_bin_penalty;
    }

    // Penalize placing small items into large-residual bins (save space for big items).
    if item_size < 30 && bin_residual > 70 {
        score += 6.0;
    }
    // Favor placing large items into large-residual bins.
    if item_size >= 50 && bin_residual >= item_size + 30 {
        score -= 4.0;
    }

    // Mild regularization toward bins near the mean residual (balanced packing).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - x)) + 12.0 * x * x * (1.0 + progress);

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize residual that can't fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 5.0 * (1.0 - (nx / cap));
        } else {
            score += 6.0 * (nx / cap);
        }
    }

    // Mild penalty for scattering across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Nudge toward bins below mean residual (filling emptier bins)
    score += 0.3 * (pr - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (eighths). Small classes are "dead space" -> penalize.
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..8
    let dead_penalty = match post_class {
        0 => 60.0,               // near-perfect fill, reward strongly
        1 => -20.0,              // tiny leftover: excellent
        2 => 5.0,                // quarter-ish leftover
        3 => 15.0,               // awkward 3/8 gap: hard to reuse
        4 => 2.0,                // half bin: very reusable
        5 => 12.0,
        6 => 0.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Modulo harmony: does next item divide into post_residual evenly?
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size.max(1) == 0 && next_item_size <= post_residual {
            score -= 25.0; // next item exactly fills the leftover
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 8.0; // next item cannot use this leftover
        }
    }

    // Last-chance bonus: only one bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer opening a new bin only when current fits are bad
    // and the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fits = mean_residual < item_size as f64 * 0.6;
        if bad_fits && frac > 0.5 {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 35.0; // keep filling open bins by default
        }
    }

    // Integer-division threshold: reward placements leaving residual in the
    // "small item friendly" band (10..=30 for classic streams).
    let band = post_residual / 10; // 0..10
    if band >= 1 && band <= 3 {
        score -= 10.0;
    }

    // Slight penalty for very fragmented bin state (high mean residual spread).
    score += ((mean_residual - post_residual as f64).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: raw leftover space (lower is better).
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small nonzero leftovers are nearly unusable
    // since items are >= 1 and often larger; penalize gaps below the
    // minimum viable item size more than proportionally.
    if post_residual > 0 {
        let dead_zone = 12.0;
        if (post_residual as f64) < dead_zone {
            // quadratic dead-space penalty, worst near post_residual = 1..5
            let d = dead_zone - post_residual as f64;
            score += 3.0 * d * d / dead_zone;
        }
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading
    // into new/loose bins; reward consolidating into already-crowded sets.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == capacity.
    // Prefer it only if the item is large relative to capacity (poor fit
    // elsewhere likely) or very few bins are open.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill < 0.5 && open_bins_count > 0 {
            score += 15.0 * (1.0 - fill); // penalize opening bins for small items
        }
        if fill >= 0.8 {
            score -= 10.0; // large items justify fresh bins
        }
    }

    // Mild normalization: prefer bins whose residual is close to the mean
    // (keeps residuals balanced, avoids many near-full + one loose bin).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream tightening: as the stream progresses, be greedier about
    // filling bins tightly (less slack tolerated).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - leftover / bin_capacity as f64);
            score += 0.8 * leftover; // penalize leftover after chained fit
        } else {
            // next item won't fit here; dead space risk
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize tiny unusable residuals (dead space) unless unavoidable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fit relative to fleet).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for reusing bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale advantage by how small the post residual is relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 2.5 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Next item cannot use leftover space: penalize creating dead space.
        score += 1.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Penalize dumping small items into bins with large residuals when many alternatives exist.
    if item_size < 40 && post_residual > 50 && fitting_bins_count > 2 {
        score += 2.0;
    }

    // New-bin candidate: keep it slightly expensive so it only wins when open-bin fits are bad.
    if bin_residual == bin_capacity {
        score += 4.0;
        // Late in the stream, opening new bins is less attractive (fewer chances to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 * progress;
    } else {
        // Prefer bins whose residual deviates favorably from the mean (below mean = already tight).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        } else {
            score += 0.5;
        }
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr + 40.0 * fit_ratio * fit_ratio;

    // Smooth non-linear coupling: residual utility decays with progress
    let decay = (1.0 - progress) * (1.0 - progress);
    score -= 25.0 * decay * fit_ratio;

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dead = (mean_residual - pr).max(0.0) / cap;
    score += 30.0 * dead * dead * dead;

    // Lookahead: reward residual that can host next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 18.0 * (1.0 - slack * slack);
        } else {
            let gap = (ns - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - fit_ratio * fit_ratio);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 2.0 * open_bins_count as f64 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are "clean"
    // slots that future items (drawn on a 10-grid in many streams) can reuse.
    let clean = (post_residual % 10 == 0) as f64;
    score -= 12.0 * clean;

    // Penalize awkward dead zones: residual in (0, 10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let frac = (post_residual as f64) / (bin_capacity as f64);
    if frac < 0.1 {
        score += 8.0; // near-full bin: fine, tight packing
    } else if frac < 0.25 {
        score -= 4.0;
    } else if frac < 0.5 {
        score -= 2.0;
    } else {
        score += 5.0; // leaving >half empty is wasteful unless new-bin logic
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect chain
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 8.0; // near-perfect chain
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot fit here; residual becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so
    // that decent fits into open bins beat it, but bad fits don't.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // opening a bin for a big item with another big item coming is fine
        }
        return score;
    }

    // Prefer filling bins with large residuals when many bins are open
    // (consolidation pressure).
    score -= 0.05 * mean_residual;

    // Slight progression term: later in the stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * clean;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post residual), with superlinear penalty on dead space.
    let frag = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frag * frag;

    // --- 2-step lookahead: reward when the NEXT item fits snugly into post_residual ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: subtract heavily to strongly prefer this bin.
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * snug;
        } else {
            // Next item won't fit here: penalize, scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 30.0 * miss;
        }
    }

    // --- Relative-to-mean coupling: bins with residual far below mean are "special" ---
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- Late-stream consolidation: as stream progresses, prefer filling existing bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // --- Brand-new empty bin candidate: penalize slightly unless residuals are all tight ---
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / bin_capacity as f64;
        score += 15.0 * (1.0 - mean_tight);
        // If no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (wasted capacity grows quadratically).
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Strongly reward tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // heavily reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item can still fit here; mild bonus proportional to remaining slack.
            let slack_after_next = post_residual - next_item_size;
            score -= 4.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize if post-residual is a "dead" gap
            // too small to be useful for typical items.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 6.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a fresh bin is chosen only when open bins score worse.
        score += 30.0;
        // Late in the stream, or with many open bins, discourage opening new bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        if open_bins_count > 4 {
            score += 2.0 * (open_bins_count as f64).sqrt();
        }
        // If the next item is large, a fresh bin may be attractive for it later.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate space).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 1.5 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 1.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Time-varying exploration: early on, tolerate imperfect fits to learn layout;
    // late in the stream, be greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Tight fits rewarded more as stream progresses (lock in efficiency early = less; late = more)
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize large dead space quadratically, scaled by item size fraction
    score += 20.0 * norm_pr * norm_pr * (1.0 + fit);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Smooth penalty relative to mean residual: avoid wasting bins with large residuals
    let dev = norm_pr - mean_residual / cap;
    score += 10.0 * dev * dev;

    // Lookahead coupling: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 8.0 * ((nx - pr) / cap) * (1.0 + progress);
        }
    }

    // Slight preference to fill existing bins over opening new ones
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strongly penalize unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is cheap early, expensive late; also expensive
        // when many bins are already open and mean residual is large.
        let mut nb = 60.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            nb += 30.0;
        }
        // If this bin is the last chance, opening new bin is worse.
        if fitting_bins_count == 1 {
            nb += 50.0;
        }
        // If next item would fit perfectly in a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            nb -= 10.0;
        }
        return nb;
    }

    // Reward near-perfect fits: post_residual in small harmonic classes.
    match post_residual {
        0 => score -= 200.0,
        1..=5 => score -= 100.0,
        6..=10 => score -= 50.0,
        _ => {}
    }

    // Harmonic class penalty via integer division of post_residual.
    let class = post_residual / 10; // dead-space magnitude class
    score += class as f64 * class as f64 * 1.5;

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 150.0;
        } else if gap <= 10 {
            score -= 60.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover; penalize proportionally.
        score += 10.0 + (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (better packing direction).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Prefer keeping very small residuals out of large bins: modulo tiebreak.
    let m = post_residual % 10;
    if m >= 1 && m <= 3 {
        score -= 8.0; // near-round leftovers are more reusable
    } else if m >= 7 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 {
        // Reward leaving a gap that can plausibly host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // Non-linear reward for small-but-usable residuals.
        score -= 12.0 * (1.0 - (post_residual as f64 / 40.0).min(1.0));
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 90.0 + 8.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 + 8.0 {
            score -= 70.0; // an open bin already has comfortable room
        }
        if post_residual < 10 {
            score += 0.0; // empty bin never creates dead space itself
        }
    }

    // Pressure from too many open bins: favor consolidating into existing bins.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (good fits get priority).
    score -= (mean_residual - bin_residual as f64) * 0.35;

    // Early stream: be slightly conservative about wasting space for future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) — already the base term.

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leftover dead space
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.35;
        }
    }

    // Penalize creating very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: only bin that fits — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild penalty for opening a new bin when decent fits exist.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

