    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early in stream: favor keeping residuals balanced / opening new bins cheaply.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late (bins scarcer value later).
        score += 15.0 * (1.0 - t) + 8.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        // But if current bins fit poorly, allow new bin.
        if fit_ratio < 0.5 && fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Penalize bins far from mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Base: prefer tight fits, but weight residual non-linearly
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling of residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them harder.
    let progress_coupling = pr * (0.5 + 2.0 * progress * progress);
    score += progress_coupling;

    // Cubic penalty for awkward residual zones (smooth via sin-free polynomial)
    let x = pr / cap; // normalized post residual in [0,1)
    score += 8.0 * x * x * (1.0 - x) * (1.0 - x) * cap * 0.1;

    // Reward using a nearly full bin (small post residual)
    if pr <= 5.0 {
        score -= 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if nxt <= pr {
            score -= 6.0 * (1.0 - diff / cap);
        } else {
            score += 3.0 * (1.0 - diff / cap);
        }
    }

    // Penalize bins that deviate from mean residual (keep bin pool balanced),
    // scaled smoothly with number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (1.0 + (open_bins_count as f64).ln().max(0.0)) * 0.05;

    // Mild reward for filling existing bins vs opening new ones as stream matures
    score -= (1.0 - progress) * 2.0;

    // New-bin candidate: make empty bin attractive only when it's genuinely better
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (harmonic classes)
    // Items 1..100: residual < 10 is nearly dead; residual in [1..=5] worst.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill, strongly prefer
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use the leftover: mild penalty scaled by waste
            score += 5.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 45.0;
        // But if many bins are open with large mean residual, opening fresh is fine
        // when current item is large (would leave big unusable gap elsewhere).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size as f64 > 0.5 * cap && mean_residual < item_size as f64 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream, slight preference to consolidate into open bins
        score += 10.0 * progress;
    }

    // Prefer bins whose residual is far from the mean (keeps diversity of sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Harmonic class bonus: bins whose residual lies in the same decade class as the item
    let item_class = item_size / 10;
    let res_class = bin_residual / 10;
    if item_class == res_class && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Encourage filling bins that can also host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 0.3;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for bins with lower residuals relative to the mean.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for unusable dead space: residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it uses the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item will NOT fit in the leftover: penalize wasted space
            score += 15.0;
        }
    }

    // Reward tight fits relative to the current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize bins whose residual deviates far above mean (prefer balanced fills),
    // but allow exploiting larger-than-mean residuals for big items.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // slight bonus for below-mean residual (tighter bin)
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when existing fits are bad,
    // but relax the penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (1.0 - 0.5 * progress);
        // opening a new bin is fine if the next item is huge and wouldn't fit leftovers anyway
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Slight preference for fewer open bins when residuals are similar.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize dead space that is too small for the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, pushing selection toward best fit.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fit_pressure = if post_residual < item_size { 0.0 } else { 0.0 };
        let _ = poor_fit_pressure;
        // Base cost of opening a new bin, discounted when open bins are fragmented.
        let mut new_bin_cost = 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin can host the next item too.
            new_bin_cost -= 20.0;
        }
        // Late in the stream, avoid opening bins for small remaining demand.
        new_bin_cost += 30.0 * progress;
        // Fragmentation: many open bins with low mean residual -> prefer new bin.
        if mean_residual < (item_size as f64) && open_bins_count > 0 {
            new_bin_cost -= 15.0;
        }
        score += new_bin_cost;
    } else {
        // Slight preference for reusing bins with smaller residuals among open bins.
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Time-horizon modulation: early stream favors consolidation, late favors filling.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= (1.0 - progress) * 5.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Core: quadratic waste penalty on post residual (dead space grows super-linearly in cost)
    let mut score = pr * (1.0 + 1.7 * norm_pr);

    // Smooth stream-progress coupling: later in the stream, waste is more costly
    score *= 1.0 + 0.9 * progress * norm_pr;

    // Non-linear interaction: post residual vs mean residual of open bins.
    // Bin with residual close to the mean is "typical"; deviating bins get smoothed penalty.
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (1.0 + progress);

    // Lookahead coupling: reward bins whose post residual harmonizes with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 14.0 * (1.0 - gap) * (1.0 - gap); // exact next-fit harmony rewarded
        // Penalize post residuals that are unusable slivers relative to the next item
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Congestion term: many open bins -> prefer consolidating into existing bins
    score += 2.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: it has bin_residual == bin_capacity; make it lose unless
    // the item is large enough that its post residual is genuinely competitive,
    // via a smooth sigmoid-like barrier on normalized post residual.
    if bin_residual == bin_capacity {
        let barrier = 1.0 / (1.0 + (-18.0 * (norm_pr - 0.35)).exp());
        score += 35.0 + 55.0 * barrier;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual near zero is excellent
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class of post_residual modulo capacity fractions:
    // classify leftover space into usable size classes (>= 20 can host
    // most items, 11..19 marginal, < 11 is dead space).
    let class = post_residual / 10; // 0..10 integer division class
    score += match class {
        0 => -8.0,
        1 => 6.0,          // 10..19: awkward dead zone
        2 => 2.0,          // 20..29: still risky
        3 => 0.0,
        4 => -1.0,
        _ => -2.0,         // large residual: flexible
    };

    // Dead-space penalty: post_residual too small for ANY item (min size 1)
    if post_residual > 0 && post_residual < 3 {
        score += 15.0;
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: reward proportionally, but keep some slack incentive
            score -= 3.0 + 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't chain here: penalize if leftover is dead-ish
            let waste = post_residual as f64;
            if waste < next_item_size as f64 * 0.5 {
                score += 5.0;
            }
        }
    }

    // Last chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with below-mean residual (fill emptier bins first,
    // keeping tight bins for tight items)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild pressure to close bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // default: slightly worse than a decent existing fit
        score = bin_capacity as f64 - 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if post_residual >= item_size && (bin_residual as f64) < mean_residual + 5.0 {
            score += 10.0; // existing bins are fine, keep them
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score += 5.0; // big next item: fresh bin is valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item are worthless.
    let min_gap = 10u32;
    if post_residual < min_gap {
        score -= 60.0; // perfect fill, great
    } else if post_residual < next_item_size && next_item_size > 0 {
        // gap can't hold the lookahead item: it's likely dead space
        let deadness = 1.0 - (post_residual as f64) / (next_item_size as f64);
        score += 25.0 * deadness;
    }

    // Reward tight fits relative to item size.
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);

    // Prefer bins whose residual is below average (fill the emptier-tail bins).
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: make it attractive only when the fit into open bins is poor
    // or the item is large (keeps large items in fresh bins).
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * poor_fit + 15.0 * big_item;
        score += 8.0; // base cost of opening a new bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits into post_residual: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: dead-space penalty proportional to wasted gap.
        let waste = post_residual as f64;
        score += 0.5 * waste;
        // Especially bad if the next item is small and could have fit elsewhere.
        if next_item_size < item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: bins tighter than average are preferred targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize leaving very small unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Early in the stream, prefer opening fresh bins less aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
    }

    // Many open bins: encourage consolidating into existing bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating dead space that no plausible item (>=1) can use well:
    // small but nonzero post_residual is wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty if we leave a very small residual
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer existing bins unless the fit there is poor. Penalize new bin,
        // but reduce penalty late in the stream or when open bins are fragmented.
        let mut new_bin_penalty = 55.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty *= 1.0 - 0.4 * progress;
        // If mean residual across open bins is small, opening a new bin is more attractive.
        new_bin_penalty -= (mean_residual / 10.0).min(20.0);
        // If few bins can fit the item, new bin less costly.
        if fitting_bins_count <= 2 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Mild reward for keeping bins consolidated when many bins are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer filling bins with larger residual earlier (keep small residuals for small items).
    score += (bin_residual as f64) * 0.05;

    // Small time-based jitter-free modulation: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // post residual normalized to [0,1]

    // Smooth non-linear coupling: post_residual polynomial in progress
    // Early in stream: prefer tight fits (penalize mid residuals, reward zero)
    // Later: dead space matters more, keep convex pressure
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 12.0 * poly;

    // Reward exact fits smoothly
    score -= 8.0 * (-pr / 10.0).exp();

    // Reward filling bins tightly relative to mean residual
    let mr = mean_residual.max(0.0);
    score -= 3.0 * (norm_pr - mr / cap) * (1.0 - 2.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 6.0 * fit_quality.max(0.0);
    } else if next_item_size > 0 {
        // smooth penalty when next item cannot use the leftover space
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 4.0 * gap * (0.5 + progress);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: make empty bin attractive only when residuals are poor
    if bin_residual == bin_capacity {
        let bad_fit = (norm_pr * 0.0 + mean_residual / cap).min(1.0);
        score += 5.0 - 10.0 * bad_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward very tight fits (small post_residual) non-linearly.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class logic: dead space that cannot fit any future item class
    // (items >= 10 typically, but interface allows 1..100) is pure waste.
    // Penalize post_residual in "unusable" ranges via modulo classes on 10.
    let unusable = post_residual < 10 && post_residual > 0;
    if unusable {
        score += 30.0;
    }

    // Reward post_residual that exactly accommodates the lookahead item (harmonic pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial credit scaled by how well the leftover divides into future classes.
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving post_residual that is a poor modulo class: waste when
    // post_residual % 10 is small but nonzero (hard to fill exactly).
    let r10 = post_residual % 10;
    if post_residual > 0 && r10 > 0 && r10 <= 3 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: score it against mean residual of open bins.
    // Prefer opening a new bin only when existing bins fit poorly
    // (post_residual would be large waste) or open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; cheaper when many open bins are fragmented.
        score = bin_capacity as f64 * 0.6
            + 0.3 * mean_residual
            - 5.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // New bin allows pairing current + next item: attractive.
            score -= 15.0;
        }
    }

    // Slight time drift: early in stream, keep bins tighter; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Penalize gaps too small for the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Reward exact fits.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 5.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless open bins are very fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
    }

    // Progression: later in stream, tighter packing matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize large dead space that next item can't use
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize post-residuals that are likely unusable (small dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    let mean_res = mean_residual;
    if bin_residual < mean_res {
        score -= (mean_res - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_res) * 0.3;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if lookahead item is large and no tight fit exists, new bin is more attractive
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, avoid spreading across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // blocks the next item
        }
        // Bonus if next item fits exactly into remaining space.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Prefer filling bins with larger residual (avoid fragmenting many bins)
    // when mean residual across open bins is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.10 * residual_gap * (1.0 - progress);

    // Mild penalty for placing into a nearly empty existing bin early on
    // (keeps flexibility), stronger late when consolidation matters.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += (1.0 - fill_ratio) * 5.0 * (1.0 - 0.5 * progress);

    // Many open bins: encourage consolidating into existing bins.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64).min(50.0)
        };
        // Opening a new bin is penalized by how many existing bins fit the item,
        // but rewarded when the current item is large and would leave a good gap.
        score += 20.0 + 8.0 * fitting_bins_count as f64;
        score -= desperation * 0.3;
        if item_size >= 60 {
            score -= 10.0; // large items start fresh bins happily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual
    score -= 45.0 * fit_ratio * fit_ratio;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = pr * pr / (c * c); // normalized squared residual
    score += 8.0 * poly * (0.5 + t);
    score -= 6.0 * poly * (1.0 - t) * (1.0 - t);

    // Penalize leaving residuals that are hard to reuse (small but nonzero)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (0.4 + 0.6 * t);
    }

    // Last-chance bin bonus: only one bin fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / c);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (next_item_size as f64 / c));
    }

    // Prefer filling bins when many bins are open; new-bin penalty grows with progress
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (15.0 + 20.0 * t + 2.0 * open_bins_count as f64);

    // Mild preference toward bins below mean residual (consolidate fuller bins)
    score += 0.15 * (mean_residual - bin_residual as f64).abs() * (1.0 - fit_ratio);

    // Small smooth regularization against very empty placements early on
    score += 2.0 * (pr / c) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue bands
    let quarter = bin_capacity / 4;      // 25
    let eighth = bin_capacity / 8;       // 12
    let post = post_residual as f64;

    // Exact-fit reward: zero waste is always best
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic band bonus: leftovers in {0, C/4, C/2, 3C/4} are reusable classes
    let r = post_residual % quarter;
    if r == 0 {
        score -= 30.0;
    } else if r <= eighth {
        score -= 10.0; // small residue, still "harmonic"
    } else {
        score += 8.0;  // dead-space penalty for non-harmonic leftover
    }

    // Penalize tiny unusable slivers (cannot host min-size items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to gap
        score += 0.2 * (next_item_size as f64 - post);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Crowding pressure: when many bins are open, prefer tightening existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins near the mean residual (keeps spread tight)
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    // A post_residual that cannot fit even the smallest plausible item (<= ~10)
    // is pure waste; scale the penalty non-linearly as the gap shrinks.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus: strongly reward near-exact packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space relative to capacity: quadratic penalty on wasted fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead: if the next item fits exactly in the post_residual, reward;
    // if it cannot fit, this bin's leftover is likely dead space, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (subtracted reward grows with open_bins_count) to avoid bin sprawl.
    score -= (open_bins_count as f64).ln().max(0.0) * 6.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 30.0 - poor_fit * 10.0 + mean_residual * 0.15;
    }

    // Mild progression coupling: late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 8.0 - (gap as f64).min(8.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize leaving stranded space.
        score += (post_residual as f64) * 0.3;
    }

    // Penalize bins whose residual deviates above mean (fragmentation).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for opening a new bin when plenty of bins are open.
    if bin_residual == bin_capacity {
        score += 4.0;
    }

    // Late in stream: prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize relative slack nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
        // Next item won't fit anywhere useful here; waste penalty small.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer consolidation (favor open bins);
    // late in the stream, be more permissive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress);

    // Prefer bins with residual below the mean (fill the emptiest-relevant bins first
    // keeps others flexible): slight bonus when bin_residual < mean_residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Many open bins: encourage closing them out (filling small residuals).
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // or no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 && (fitting_bins_count == 0 || post_residual < 15) {
            score -= 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * norm_pr * norm_pr);

    // Penalize large dead space more as the stream advances (quadratic in progress).
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: subtract bonus when post_residual is small.
    score -= 8.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Prefer bins with residual below mean (denser bins) via smooth interaction.
    score += 2.0 * ((pr as f64 - mean_residual) / cap) * (1.0 + progress);

    // Mild penalty for spreading across many open bins early.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // New-bin candidate: baseline cost so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice" residue
    // classes (multiples of 10, and small values) are more reusable later.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit, always reward strongly
    } else if pr % 10 == 0 {
        -8.0 * (pr as f64 / 10.0).min(3.0)
    } else if pr % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward residue class, penalize
    };
    score += harmonic_bonus;

    // Integer-division thresholds: classify leftover into coarse bands.
    let band = pr / 25; // 0..4
    score -= band as f64 * 5.0; // larger leftover space is generally better

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match: next item exactly consumes leftover class
            if pr % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 7.0;
            }
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // last item: minimize waste directly
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins
    // would create heavy fragmentation.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        score += 30.0 - fragmentation.min(30.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is fine for the lookahead too
        }
    }

    // Mild exploration pressure across the stream phase.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.05 * phase;

    // Penalize bins far from the mean residual (outliers are harder to fill later).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Tie-breaker: prefer bins with more competition (keeps scarce bins open).
    if fitting_bins_count > 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: fill bins tightly (lower post_residual = better).

    // Strict dead-space avoidance: post_residual in a small unusable gap
    // (0 < post_residual < 10, since min item is 1) is heavily penalized
    // because nothing can ever use it.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small post_residual that can still fit the smallest item is mildly good.
    if post_residual >= 10 && post_residual < 30 {
        score -= 5.0;
    }

    // Dead space relative to capacity: penalize leaving a large-but-not-huge
    // residual that fragments capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.05 && frac < 0.25 {
        score += 8.0 * frac;
    }

    // Last chance: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: a fresh bin (residual == capacity) should
    // only win when no existing bin offers a decent fit. Make the empty bin
    // unattractive unless the item is large and fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 60.0 - 35.0 * scarcity - 0.2 * item_size as f64;
    }

    // Lookahead: if the next item fits into the post_residual exactly or well,
    // reward preserving that pairing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 6.0; // post_residual likely wasted for next item
        }
    }

    // Stream progression: late in the stream, avoid opening new bins harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    // Mild attraction toward bins with below-average residual (emptier bins
    // keep flexibility), i.e., penalize dipping into already-full-ish bins
    // unless the fit is tight.
    if (bin_residual as f64) < mean_residual && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leave nothing usable behind.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small for the smallest plausible item.
        if post_residual < 10 {
            score += 20.0;
        }
        // Reward leaving residuals that likely fit future items.
        score -= (post_residual as f64).ln().max(0.0) * 5.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportional closeness of the fit for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after this placement: mild penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 * (over / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins tighter than average are better to fill.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless the current
    // placement would create severe fragmentation.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the item exactly fills the new bin, opening is fine.
        if item_size == bin_capacity {
            score -= 60.0;
        }
        // Late in the stream, prefer compacting into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild pressure when many bins are open: encourage consolidation.
    score -= 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.1 * next_item_size as f64;
        } else if !is_new_bin {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mildly discourage opening extra bins when many are already open.
    if is_new_bin {
        score += 20.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // But if the item fits poorly everywhere else, new bin becomes attractive.
        let waste = bin_residual - item_size;
        if waste == 0 {
            score -= 60.0; // perfect fit in fresh bin
        }
        if fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) > mean_residual {
            score += 15.0;
        }
    }

    // Prefer bins with residual below the current mean (consolidate waste).
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Late stream: tighten packing, avoid new bins.
    if progress > 0.8 {
        score *= 1.0 + 0.5 * progress;
        if is_new_bin {
            score += 25.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), but with non-linear decay
    // so extra dead space is increasingly penalized (quadratic coupling).
    let mut score = post + 0.008 * post * post / cap;

    // Smooth non-linear interaction: residual waste matters more as the stream progresses.
    let prog_term = 0.5 * progress * (1.0 - progress).powi(2); // peaks mid-stream, fades at end
    score += 12.0 * prog_term * post / cap;

    // Reward near-perfect fits smoothly (bell-like in post_residual).
    score -= 6.0 * (-(post * post) / (2.0 * 9.0f64.powi(2))).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item (smooth margin shaping).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (-(gap * gap) / (2.0 * 12.0f64.powi(2))).exp();
        // Penalize leaving residual just barely too small for the next item (dead space).
        if post < next_item_size as f64 {
            score += 4.0 * (1.0 - post / cap) * progress;
        }
    }

    // Penalize bins far below the mean residual (fragmentation risk), smoothly scaled.
    score += 1.5 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild preference for using existing bins over opening new ones early in the stream.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modulo arithmetic on capacity ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;

    // Dead-space class: residual below the smallest item (1) is impossible,
    // but tiny residuals relative to typical item sizes are wasted.
    // Penalize residuals that fall into "unusable" harmonic windows.
    if pr > 0.0 && pr < eighth {
        // residual in (0, 12.5): nearly dead space
        score += 3.0 * (eighth - pr) / eighth * 8.0;
    } else if pr < quarter {
        // residual in [12.5, 25): usable only by small items
        score += 1.0 * (quarter - pr) / quarter * 4.0;
    }

    // Perfect fit reward: post_residual exactly divisible by capacity fractions
    if post_residual % 50 == 0 || post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 12.0; // exact fill is ideal
    }

    // Harmonic pairing: does post_residual exactly accommodate the next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr - nx).abs() < f64::EPSILON {
            score -= 10.0; // next item fills this bin exactly
        } else if nx <= pr {
            // next item fits: reward proportional to how little slack remains
            score -= 4.0 * (1.0 - (pr - nx) / c);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 2.0 * (nx - pr) / c * 10.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
        if pr <= quarter {
            score += 2.0; // but only a poor fit remains — soften
        }
    }

    // New-bin candidate handling: empty bin gets a mild fixed cost so we
    // prefer existing bins with decent fits, but beat very poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.02 * open_bins_count as f64;
    }

    // Tightness reward: reward small post_residual generally (non-linear)
    score += (pr * pr) / c * 0.05;

    // Stream progression: late in the stream, be more conservative about
    // opening bins (weight existing-bin usage higher).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= 4.0 * progress;
        }
    }

    // Mean residual coupling: prefer bins close to the mean residual
    // (balanced packing), penalize outliers.
    let dev = (pr - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min size 1, but practically tiny gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize leaving a gap that next item exactly wastes vs. fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0; // gap still usable by lookahead
        } else if post_residual > 0 {
            score += 10.0; // gap unusable by lookahead
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // i.e. favor using existing bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if mean residual across open bins is tiny, a new bin is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: leave nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly,
    // or can still hold it well.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Exact match for next item: chain placement is ideal.
        if diff == 0.0 {
            score -= 40.0;
        } else if pr >= nxt {
            // Next item fits; reward proportional to how tight the fit is.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space that blocks the chain,
            // worse when post_residual is small (unusable sliver).
            let sliver = pr / bin_capacity as f64;
            score += 15.0 * (1.0 - sliver);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating small unusable residuals relative to the minimum item size (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is below average
    // (concentrate filling) but not so low that the item barely fits.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.05 * mean_gap;

    // Early in the stream, be more willing to open new bins (spread items);
    // later, tighten packing by penalizing new-bin usage slightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progress-dependent penalty.
        score = bin_capacity as f64 + 10.0 * progress;
        // Opening a new bin is attractive if no open bin gives a decent fit
        // (large post_residual elsewhere) or if item is large.
        if item_size > 70 {
            score -= 15.0;
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty scaled by capacity.
    let waste = post_residual as f64;
    score += 0.6 * (waste / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot fit in the post residual,
    // reward if it fits snugly.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            let leftover = post_residual - next_item_size;
            score -= 12.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more willing to spread across bins;
    // late in the stream, pack tightly to avoid waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // Candidate new bin: penalize more when open bins are underfilled.
        score += 20.0 + 0.3 * mean_residual + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin anyway
        }
    } else {
        // Reward bins that are below mean residual (relatively empty, useful).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += 30.0 * quad * (0.5 + 0.5 * progress);
    score -= 25.0 * cube * (1.0 - progress);

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.3 + 0.7 * progress);
    }

    // Penalize deviating from mean residual (fragmentation control)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild new-bin penalty growing with open bins and progress
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // integer-division buckets of capacity/10.
    let bucket = post_residual / 10;
    let bucket_center = bucket * 10 + 5;
    let deviation = (post_residual as i64 - bucket_center as i64).abs() as f64;
    score += 0.35 * deviation;

    // Reward exact/near-exact fits (dead space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score -= 18.0;
    }

    // Harmonic penalty: residuals that fall into "useless" classes.
    // Residuals < 10 can only host items of size 1..9; penalize hard.
    if post_residual < 10 {
        score += 55.0;
    }

    // Modulo-10 class of post_residual: odd/prime-ish leftovers pair poorly
    // with typical item sizes; multiples of 10 pair well.
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,
        5 => score += 4.0,
        1 | 9 => score += 6.0,
        _ => {}
    }

    // Lookahead coupling: does this bin's post-residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: post-residual exactly matches next item size.
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; leftover becomes likely dead space.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual
    // is genuinely unusable (small) or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Open new bins more readily early in the stream (diversity of residuals).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = 1.0 - 0.5 * progress;
        score += 30.0 * openness - 20.0 * (1.0 - pressure);
        if item_size > 70 {
            score -= 15.0; // huge items: fresh bin is attractive
        }
        if post_residual > 20 && fitting_bins_count > 1 {
            score += 25.0; // good existing fit exists; don't open a bin
        }
    }

    // Mild preference for tighter (already partially filled) bins.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Keep scores in a sane band.
    if score < -100.0 { score = -100.0; }
    if score > 500.0 { score = 500.0; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize residual gaps that cannot fit the next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward gaps that exactly or comfortably fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Mild preference for tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late-stream tightness: pack more greedily as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize dead space: residuals too small for any plausible item (1..100)
    if post_residual < 10 {
        score += 25.0; // nearly full bin is fine, but tiny residual is dead
    } else if post_residual <= item_size {
        // residual could still fit a similar item — mildly good
        score -= 4.0;
    } else {
        // large leftover: penalize proportionally to how "unusable" it is
        let unusable = (post_residual as f64) / 100.0;
        score += 6.0 * unusable * unusable;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty if this bin was a good candidate
        score += 3.0;
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so new bins are used only when open bins fit poorly
        score += 18.0;
        // if mean residual is small (fragmented), opening a new bin is less bad
        score -= 10.0 * (1.0 - fragmentation);
        // early in stream, prefer filling existing bins less aggressively? mild
        score -= 5.0 * progress;
        // if item is large and next item is also large, new bin may be wise
        if item_size >= 50 && next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Prefer bins with residual close to item size (best-fit flavor)
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    // Global state: many open bins -> encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 1.5 * ((open_bins_count as f64).ln());
    }

    // Penalize leaving residual that matches neither current nor next item
    if post_residual > 0 && post_residual < next_item_size && post_residual < item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let p = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Core: prefer small post_residual, with a smooth polynomial shaping
    // that penalizes both large waste and razor-thin residuals.
    let mut score = post * (1.0 + 0.35 * p * p);

    // Dead-space penalty: residuals too small to fit typical future items
    // (smooth quadratic bowl around unusability).
    let unusable = (norm_post * 10.0 - 1.0).max(0.0);
    score += 4.0 * unusable * unusable * (0.5 + p);

    // Non-linear coupling with stream progress: later in the stream,
    // consolidation matters more; reward tight fits progressively.
    let tightness = 1.0 - norm_post;
    score -= 6.0 * tightness * tightness * (0.4 + 0.6 * p);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin unless it's genuinely needed (few fitting bins).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        let openness = 1.0 / (1.0 + pressure * pressure);
        // Early stream: new bins are cheap; late stream: penalize more.
        score += 8.0 * openness + 10.0 * p;
        // If no existing bin fits, new bin is the only option: soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Lookahead: reward bins whose post_residual accommodates the next item,
    // penalize leaving a gap just smaller than the next item (bad pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 3.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - post) / cap;
            score += 5.0 * gap * gap * (1.0 + p);
        }
    }

    // Mild preference for bins deviating from mean residual (diversity of sizes
    // keeps flexibility), stronger late in the stream.
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev.abs() * (0.3 + 0.7 * p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fill (perfect packing).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: leftovers that are "nice"
    // (multiples of small harmonics) are more reusable later.
    let pr = post_residual;
    let harmonic = if pr == 0 { 0.0 }
        else if pr % 50 == 0 { 0.0 }
        else if pr % 25 == 0 { 2.0 }
        else if pr % 10 == 0 { 3.0 }
        else if pr % 5 == 0 { 5.0 }
        else { 8.0 };
    score += harmonic;

    // Penalize small unusable dead space (classic best-fit trap):
    // leftover 1..=9 is nearly worthless for items >= 10 (interface: sizes 1..100 though).
    if pr > 0 && pr < 10 {
        score += 40.0;
    } else if pr >= 10 && pr < 25 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // heavily favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after next placement matters
            let pr2 = pr - next_item_size;
            if pr2 < 10 {
                score += 15.0; // creates fresh dead space
            } else {
                score -= 20.0; // keeps stream flowing in this bin
            }
        } else {
            // next item won't fit here: mild penalty unless this is a last-chance bin
            score += 12.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin early in the stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many bins are open and none fit well, new bin is attractive.
        if open_bins_count > 3 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Mild preference for filling existing bins when mean residual is high.
        score -= 0.1 * mean_residual;
    }

    // Slight tie-break toward tighter fits relative to capacity fraction.
    score += 0.05 * (pr as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    let min_useful = 10u32;
    if post_residual < min_useful {
        score += 60.0 * (min_useful - post_residual) as f64;
    } else {
        // Smoothly penalize small-but-nonzero gaps (hard to fill later)
        let gap = post_residual as f64;
        score += 8.0 * (min_useful as f64 / gap.max(1.0)).powi(2);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chains well).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            let npost = post_residual - next_item_size;
            if npost < min_useful {
                score += 25.0; // next item would create dead space here
            } else {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // tight existing bins rather than spreading; when few bins are open,
    // slightly tolerate new-bin openings.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // New-bin candidate handling: make the empty bin attractive only when the
    // current bin fit is poor (large post residual) or dead space would result.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual < min_useful { 1.0 } else { 0.0 };
        let large_gap = (post_residual as f64 / bin_capacity as f64).min(1.0);
        // Base cost of a fresh bin, discounted when the fit elsewhere is bad.
        score += 55.0 - 90.0 * bad_fit - 40.0 * large_gap.max(0.6);
        // When no open bins fit at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for bins whose residual is near the item (tight fits)
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it is becoming an outlier of dead space — penalize mildly.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.5 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when next item fits exactly into post_residual (2-step lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 1.2 * slack;
    }

    // Penalize post_residual too small for next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin early in the stream; allow it late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
    }

    // Discourage large leftover fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that are hard to reuse.
    if post_residual > 0 {
        let dead = 1.0 - (post_residual as f64 / bin_capacity as f64).sqrt();
        score += 6.0 * dead * (1.0 - fit_ratio);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose post-residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Wasted residual that cannot host the next item.
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / next_item_size.max(1) as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins balanced);
    // late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * fit_ratio;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Bin-count pressure: many open bins -> prefer filling existing ones.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins near/below the mean residual (tighter bins).
    score += 2.0 * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 10.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let mut score = r;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = r * r * (1.0 - progress) + r * progress * (1.0 - r);
    score += 2.5 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - r) * (1.0 - r) * (0.5 + progress);

    // Penalize dead space relative to mean residual
    if r * bin_capacity as f64 > mean_residual {
        score += 0.3 * (r * bin_capacity as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 1.0;
    }

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 0.4 * (1.0 - progress);
    }

    // Mild penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 0.8 * (1.0 - progress) + 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "dead" (too small
    // for typical items) are penalized; leftovers divisible into useful
    // classes are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space class: leftover below the smallest plausible item (1..=10)
    // is nearly worthless.
    if post_residual == 0 {
        score -= 50.0; // perfect fit — heavily reward
    } else if post_residual <= 5 {
        score -= 12.0; // near-perfect, tiny waste
    } else if post_residual <= 10 {
        score -= 4.0;
    } else {
        // modulo classes on post_residual: leftovers that are multiples of
        // common item sizes remain reusable.
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        } else {
            score += 3.0; // awkward leftover
        }
        // harmonic fraction: leftover as fraction of capacity
        score += (post / cap) * 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item).
    if bin_residual == bin_capacity {
        // new bin: score = post_residual = capacity - item_size, already
        // the natural waste; add a mild inertia penalty so we prefer existing
        // bins unless their fit is clearly worse.
        score += 10.0 + 0.1 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins tighter than average (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space that can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.5 * pressure;

    // Mild late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current item is large relative to
    // mean residual (poor fits everywhere) — otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && item_size as f64 > mean_residual * 0.9 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 200.0 / (post_residual as f64);
    }

    // 2-step lookahead: reward when next item fits the post residual exactly,
    // penalize when post residual is too small to be useful.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= 100.0 / (post_residual - next_item_size).max(1) as f64;
        } else {
            // post residual too small for next item: dead-space penalty
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: avoid making residuals
    // wildly below the mean (fragmentation), but small residuals are good if used.
    let mr = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let ratio = post_residual as f64 / mr;
    score += 20.0 * (ratio - 1.0) * (ratio - 1.0);

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize mildly, but allow it when this bin would leave
    // a large awkward gap relative to capacity.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 0.5 * item_size as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 30.0; // pairing large item now, next smaller into leftovers
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 60.0; // fresh bin can host the next item too
        }
    }

    // Late in the stream: prefer closing bins tightly (less future value of slack).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

