    let mut score = post;

    // Non-linear coupling: penalize large residuals more as the stream progresses
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (low post residual) with a smooth quadratic bonus
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bin: strongly favor using it (smooth exponential decay term)
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward if next item fits into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_frac = nxt / cap;
            score -= 18.0 * fit_frac * (1.0 - progress);
        } else {
            score += 10.0 * ((nxt - post) / cap);
        }
    }

    // Mean residual deviation: penalize bins deviating from the fleet mean (smooth)
    let dev = (post - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Slight preference for fewer open bins when residuals are similar
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

