    let frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual small relative to capacity
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Harmonic classes on post_residual: dead space that nothing (min item 1) can use
    if post_residual == 0 {
