    } else if post_residual < 10 {
        score -= 20.0; // nearly dead space, good
    } else {
        // penalize residuals in awkward modulo classes (e.g. prime-ish gaps)
        let class = post_residual % 7;
        if class == 1 || class == 5 {
            score += 6.0;
        }
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 20; // 0..5 classes
    score += q as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
