        } else if next_item_size < post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 8.0 * frac;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins mildly, unless current fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if item is huge, opening fresh bin can be good
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Progress-based modulation: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Many open bins: encourage closing them out
    score -= 0.5 * open_bins_count as f64 * (post_residual == 0) as u32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
