    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt && post - nxt < 10.0 {
            score -= 20.0; // perfect two-item chain
        } else if post < nxt && post > 0.0 {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // later, be more open to new bins to avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are fragmented.
        let fragmentation = (mean_residual - post).abs() / cap;
        score -= 15.0 * (1.0 - progress) - 10.0 * fragmentation;
        if fitting_bins_count == 0 {
