    // early on, tolerate slack slightly; late in the stream, punish residual waste more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr / cap) * (1.0 - pr / cap) * 10.0;

    // Reward using a bin whose residual closely matches the item (good coupling term).
    let fit_quality = 1.0 - ((bin_residual as f64 - item) / cap).abs();
    score -= 8.0 * fit_quality * fit_quality;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 10.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 3.0 * (1.0 - gap / cap);
        }
    }

    // Penalize bins far from mean residual (keeps residual distribution tight).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * (1.0 + progress);

    // Mild penalty for many open bins, encouraging consolidation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
