    }

    // Lookahead: penalize if next item cannot fit in post_residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Dead bin unless it's near-empty anyway.
            if post_residual > next_item_size / 2 {
                score += next_item_size as f64 * 0.8;
            }
        } else {
            // Next item fits: reward proportional to how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= snug * 0.3;
            // Harmonic class coupling of next item size.
            let nclass = (next_item_size as f64 / cap * 10.0).floor() as i64;
            score -= nclass as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: prefer reusing open bins when mean residual is large.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.4 + open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Stream progression: later in stream, tighten packing (avoid waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Mean residual coupling: many open bins with slack -> fill them.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // unless post_residual is exactly 0 (perfect fit).
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strong reward
    } else if post_residual <= 10 {
        score += 45.0; // tiny dead gap: very bad
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward filling the bin tightly relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress * 0.5);

    // Penalize bins whose residual deviates badly from mean residual (fragmentation control)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in post-residual but could fit elsewhere, mild penalty
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad existing options are
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the last-chance bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0; // slight extra caution
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins with small post_residual.
    score -= 40.0 * (-post_residual as f64 / 20.0).exp();

    // 2-step lookahead: if next item exactly fits post_residual, big bonus.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step match
        } else if diff > 0.0 && diff <= 15.0 {
            score -= 25.0 * (1.0 - diff / 15.0); // close 2-step match
        } else if diff < 0.0 {
            // next item won't fit here; penalize wasting residual
            score += 8.0;
        }
        // Penalize large post_residual that next item can't exploit
        if post_residual as f64 > next_item_size as f64 + 20.0 {
            score += (post_residual as f64 - next_item_size as f64 - 20.0) * 0.4;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin if lookahead match is perfect elsewhere handled; also
        // slight discount early in stream when few bins open.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Discourage leaving tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // dead space is fine — bin is effectively full
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progression through the stream
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Reward tight fits: small post_residual is good, but avoid creating
    // dead space too small for any realistic item (min size 1).
    let dead_penalty = if post_residual > 0 && post_residual < 4 {
        25.0 * (4 - post_residual) as f64
    } else {
        0.0
    };
    score += dead_penalty;

    // Strong reward for perfect fill
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 5.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it less
    // attractive than decent fits, but attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Fragmentation pressure: many open bins with low mean residual => prefer new bin
        let frag = mean_residual / bin_capacity as f64;
        score += 30.0 - 25.0 * (1.0 - frag);
        // Early in stream, opening bins is cheap; later, prefer consolidation
        score += 15.0 * progress;
        // If item is large relative to capacity, keep new-bin option competitive
        score -= 0.1 * item_size as f64;
    }

    // Global balance: penalize bins whose residual deviates far from mean residual
    // (prefer uniform packing landscape), scaled by stream maturity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (0.5 + 0.5 * progress);

    // Slight preference for filling fuller bins as stream progresses
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild penalty per open bin to discourage bin proliferation
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize large residuals more strongly as stream progresses
    score += progress * 30.0 * norm_pr * norm_pr;

    // Reward tight fits (small post_residual relative to item) with a smooth term
    score -= 25.0 * fit_ratio * (1.0 - norm_pr) * (1.0 - progress);

    // Dead-space penalty: quadratic in unusable residual if next item cannot fit
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 40.0 * gap * gap;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Pull toward mean residual to keep bins balanced smoothly
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate: keep it attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        score -= 10.0 + 20.0 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    // Residuals in "harmonic" classes (multiples of 10, 20, 25, 50) are more
    // reusable by future items, so reward them (subtract); odd/prime-ish
    // residuals are dead space, penalize (add).
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit, best possible outcome
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -7.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward residual, likely dead space
    };
    score += class_bonus;

    // Integer-division thresholds: small post_residuals (< 10) are unusable
    // for any item (min size 1), heavily penalize relative to larger ones.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            // reward proportional to how tightly next item nests
            let slack = (pr - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 6.0;
            }
            // penalize if next item won't fit here anyway and residual is large
        } else {
            // next item cannot use this residual; large residuals get wasted
            if pr > 40 {
                score += (pr - 40) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, opening a
    // new bin is costly, so strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to capacity or all open bins are crowded; otherwise the
    // empty-bin option should lose to reusing open bins.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let crowd = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // base penalty so empty bins usually lose
        score += 18.0;
        // reward opening a new bin for big items or crowded streams
        score -= fill_frac * 25.0 + crowd * 15.0 + progress * 5.0;
        // harmonic class of the item itself: sizes near nice fractions of
        // capacity (25, 33, 50, 66) pack well in fresh bins
        if item_size % 50 == 0 || item_size % 25 == 0 {
            score -= 6.0;
        }
    } else {
        // Mild preference for tighter existing bins: normalize post_residual
        // by capacity and couple with mean residual to spread load evenly.
        let tight = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        score += tight * 10.0;
    }

    // Modulo coupling between item and residual: residual that is a multiple
    // of the item size class packs repeatedly.
    if pr > 0 && item_size > 0 && pr % item_size == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (1..100 interface => threshold calibrated at 12) are pure waste.
    if post_residual < 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 12.0);
    }
    // "Sweet spot": post_residual that can still host a mid-size item is valuable.
    if post_residual >= 12 && post_residual <= 40 {
        score -= 18.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: default cost, reduced only when the current bin's post
    // residual would be dead space AND the next item needs real room.
    if bin_residual == bin_capacity {
        score = 50.0;
        if post_residual < 12 && next_item_size > 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // This bin can't host the next item; slight penalty so a bin that chains
        // both items wins when otherwise equal.
        score += 8.0;
    } else if next_item_size > 0 {
        score -= 6.0;
    }

    // Mild bonus for bins below mean residual (rebalancing fragmentation).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 250.0;
        }
        // Penalize leftovers too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: prefer bins tightened toward the mean or below.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent existing fits exist (early in stream keep bins tight).
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count > 0 && post_residual >= next_item_size {
            score += 120.0;
        }
    }

    // Late in the stream, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if next_item_size == 0 {
            score -= 4.0; // last item: just fill anything
        }
    }

    // Exact fit is excellent
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits perfectly in post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 5.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }

    // Time horizon: early in stream, be pickier about waste; late, just pack
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 0 {
        score -= 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
        // open a new bin early if existing residuals are all small
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.5 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth normalized post-residual and its polynomial couplings
    let x = post / cap; // 0..1
    let x2 = x * x;
    let x3 = x2 * x;

    let mut score = 100.0 * x3 + 40.0 * x2 + 10.0 * x;

    // Tight fits rewarded strongly (smooth reward as post -> 0)
    score -= 60.0 * (1.0 - x) * (1.0 - x) * (residual / cap);

    // Stream progress coupling: later in stream, penalize waste more (smooth)
    let prog_term = progress * progress;
    score += prog_term * 80.0 * x2;

    // Mean residual interaction: prefer bins whose post residual is near mean
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_margin = x - nx;
        if fit_margin >= 0.0 {
            score -= 25.0 * (1.0 - fit_margin) * (1.0 - x);
        } else {
            score += 30.0 * (-fit_margin) * (1.0 + x);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - x2);
    }

    // Crowding: mild penalty scaled by open bins (smooth)
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate: baseline cost so it's only chosen when it beats all open bins
    if bin_residual == bin_capacity {
        score += 120.0 - 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

