    let pr = post_residual;
    let class = (pr % 10) as f64;
    let bucket = (pr / 10) as f64;
    // Residuals that are exact small remainders are dead space; penalize tiny nonzero classes
    if pr > 0 && pr < 10 {
        score += 30.0; // nearly unusable sliver
    } else if pr == 0 {
