    } else {
        // Reward residuals that are reusable "harmonic" sizes (multiples of 10/20/25/50)
        if pr % 50 == 0 { score -= 15.0; }
        else if pr % 25 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 7.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else { score += 3.0 + class * 0.3; } // awkward remainder class
        // Larger coarse buckets are safer targets
        score -= bucket * 0.8;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            score -= 10.0 + 0.15 * nx; // chain placement possible
            // Bonus if next item exactly consumes residual (harmonic match)
            if next_item_size == pr { score -= 20.0; }
            // Class match: next item shares divisibility structure with residual
            if pr % next_item_size == 0 { score -= 8.0; }
        } else {
            score += 6.0; // next item won't fit here; dead end risk
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.2 * (item_size as f64);
    }

    // New-bin candidate handling: keep it neutral-ish, open only when open bins are bad
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        // Early stream: prefer filling open bins; late stream: new bins cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap as f64 * 0.55 + 20.0 * pressure - 15.0 * progress;
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Slight penalty for bin proliferation; reward consolidation
    score += 0.05 * open_bins_count as f64;
    // Nudge toward bins below mean residual (use up emptier space first)
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to hold the smallest plausible
    // item are pure waste; penalize them super-linearly.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item if it would fit afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit in the remainder: mild penalty proportional to gap.
        score += (next_item_size as f64 - post_residual as f64).min(10.0) * 0.5;
    }

    // Tightness reward: fraction of residual consumed by this item.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 10.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits, or the current bin would be left with unusable scraps.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            // Mild early-stream preference to open bins, stronger later penalty.
            score += 15.0 + 20.0 * progress;
        }
    }

    // Mean-residual coupling: when mean residual is large, avoid spreading waste.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect two-step match: bin residual == next item size -> strong bonus.
        if diff < 0.5 {
            score -= 60.0;
        } else if post >= nxt {
            // Next item still fits here: mild bonus proportional to tightness of match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space growth.
            score += 10.0 + 0.5 * diff;
        }
        // Extra reward if this bin becomes exactly empty after both steps.
        if post + nxt as u32 == bin_capacity {
            score -= 40.0;
        }
    } else {
        // Last item: prefer leaving zero residual.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Compare against mean residual: placing in a bin with residual far below mean
    // concentrates waste; prefer bins whose residual is above/at mean (bigger holes).
    let res = bin_residual as f64;
    if res < mean_residual {
        score += 1.5 * (mean_residual - res);
    } else {
        score -= 0.5 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current
    // fit would leave a large, unusable residual (waste factor high).
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // Small residual left = good packing; big residual = wasteful placement, so
        // a fresh bin becomes competitive only if existing placements are very tight.
        score = 55.0 + 45.0 * waste_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If next item is large and this fresh bin could take both, favor opening.
        if next_item_size > 0 && next_item_size as u32 <= post_residual {
            score -= 15.0;
        }
    }

    // Mild penalty for fragmenting many small residuals across too many open bins.
    if open_bins_count > 8 {
        score += 0.05 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use the leftover: mild penalty for fragmenting.
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative
    // to capacity or all open bins are nearly full (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // prefer new bin when item is big or open bins are mostly full
        score += 20.0;
        score -= 30.0 * big_item;
        score -= 25.0 * (1.0 - crowded);
        // late in the stream, consolidation matters more; discourage new bins
        score += 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins with residuals below the mean (consolidate emptier space usage).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear waste penalty: squared normalized dead space
    let norm_post = pr / cap;
    score += 30.0 * norm_post * norm_post;

    // Tight-fit reward (couple post_residual with item size)
    let it = item_size as f64;
    let tight = (it / cap) * (1.0 - norm_post);
    score -= 20.0 * tight * tight;

    // Stream-progress coupling: early on prefer filling, late prefer tight fits even more
    score -= 15.0 * progress * (1.0 - norm_post) * (it / cap);
    score += 10.0 * progress * norm_post * norm_post;

    // Last-chance bin reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - norm_post);
    }

    // Lookahead: bonus if next item fits post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (nx / cap) * (1.0 - norm_post);
        } else {
            score += 6.0 * ((nx - pr) / cap);
        }
    }

    // Mean residual deviation penalty (prefer bins near mean to keep balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: mildly penalize so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual in units of 10.
    let cls = post_residual / 10;
    score -= (10 - cls.min(10)) as f64 * 6.0;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space in awkward harmonic classes (1..9 residual is hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible; reward closeness.
            let gap = post_residual - next_item_size;
            score -= 15.0 - gap as f64 * 0.2;
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into bins with large residual already used well.
    if open_bins_count > 2 {
        let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_frac * 8.0;
    }

    // Prefer bins below mean residual slightly (balance exploitation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when residuals everywhere are fragmented
    // and item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let frac_used = item_size as f64 / bin_capacity as f64;
        score += 18.0 - frac_used * 30.0;
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= mean_residual {
            score += 10.0; // an open bin likely serves the future too
        }
        if item_size > 70 {
            score -= 15.0; // big item deserves a fresh bin
        }
    }

    // Progress-based mild annealing: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let smallest_item = 1u32;
        if post_residual < smallest_item * 5 {
            score += 40.0 * (1.0 - (post_residual as f64) / 5.0);
        }
    }

    // Reward tight fits: the smaller the post_residual relative to item, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Reward near-perfect packing (post_residual very small but nonzero).
    if post_residual > 0 && post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    let ob_pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += 10.0 + ob_pressure * 6.0 + (step_index as f64 / total_items.max(1) as f64) * 8.0;
        // But if no existing bin fits well, allow new bin occasionally.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        score -= ob_pressure * 2.0;
    }

    // Lookahead: if next item fits the post_residual well, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack <= 10.0 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }

    // Penalize bins whose residual is far above mean (fragmented bins) mildly,
    // unless this placement fixes it.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score += 0.02 * dev; // slightly reward below-mean residual (tighter bin)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills or fits well.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_waste / (bin_capacity as f64));
            if post_residual == next_item_size {
                score -= 25.0; // exact fill bonus
            }
        } else {
            // Next item won't fit here: penalize proportional to unusable dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
            // Strong penalty if the dead space is small enough that any bin would waste it.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: strongly prefer filling a bin as much as possible.
        score -= 30.0 * tightness;
    }

    // Compare against mean residual: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / (1.0 + progress);
        // New bin attractive only if post_residual chains with next item or fits are scarce.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can host the chain
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        } else {
            score += 8.0 + 0.5 * pressure;
        }
        // Late in stream, discourage spreading across new bins.
        score += 10.0 * progress;
    }

    // Mild penalty for very large residual waste overall.
    if post_residual > bin_capacity / 2 {
        score += 0.1 * ((post_residual - bin_capacity / 2) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream: early on, be conservative; later, be greedy.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimizing post_residual (tight fits), scaled.
    score = post_residual as f64 * (0.9 + 0.4 * progress);

    // Dead-space penalty: residuals too small for typical future items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 6.0; // creates a sliver that likely won't be used
        }
        // If next item exactly fills the leftover, strongly favor this bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or this item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default cost of opening a new bin.
        score += 30.0;
        // Large items or crowded state justify new bins.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 35.0 * size_frac;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If open bins have little room on average, new bin is fine.
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 25.0;
        }
        // Late in stream with many open bins, prefer filling existing bins.
        if progress > 0.6 && open_bins_count > 2 {
            score += 15.0 * progress;
        }
        // If no open bin can fit and next item is small, still slightly discourage.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // Reward using bins that are already partially filled (consolidation).
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill;
        // Prefer bins whose residual is close to the item (best-fit sharpening).
        let slack = (bin_residual - item_size) as f64;
        score += 0.15 * (slack as f64).abs().min(50.0) * (1.0 - progress);
    }

    // Global pressure: many open bins relative to items seen -> consolidate.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (1.0 - progress) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with quadratic sharpening.
    let mut score = post + 40.0 * norm_post * norm_post * cap;

    // Smooth non-linear coupling: as stream progresses, tighten tolerance on waste.
    let progress_shaping = 1.0 + 2.0 * progress * progress;
    score *= progress_shaping;

    // Dead-space penalty: post_residual too small to be useful later.
    let min_future = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    if post < min_future {
        score += (min_future - post) * (0.5 + progress);
    }

    // Reward exact-ish fits strongly, smoothly via exp on normalized post.
    score -= 25.0 * (-norm_post * 6.0).exp();

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score = cap as f64 + 60.0 * waste * waste;
        // Early in stream, new bins are cheaper; late, discourage strongly.
        score -= 30.0 * (1.0 - progress) * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (balance loads).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "useful" bands (multiples of common small sizes) via integer division.
    let class = post_residual / 10;
    let rem = post_residual % 10;
    // Exact harmonic residuals (0 mod 10) are tight fits -> strong reward.
    if rem == 0 {
        score -= 18.0;
    } else if rem <= 2 {
        score -= 6.0;
    } else {
        // ragged remainder: penalize proportionally
        score += rem as f64 * 1.5;
    }

    // Deep harmonic classes: post_residual divisible by next_item_size means
    // the lookahead item fits perfectly -> big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 25.0;
        } else {
            let leftover = post_residual % next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else {
                score += leftover as f64 * 0.8;
            }
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // lookahead item cannot use this bin's residual: penalize dead space
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Capacity-fraction thresholds: bins closed near full are excellent.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill > 0.9 {
        score -= 15.0;
    } else if fill > 0.75 {
        score -= 7.0;
    } else if fill < 0.4 {
        score += 10.0; // barely used bin: discourage
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless residual would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If current item is huge relative to capacity and mean residual is low,
        // opening a fresh bin is reasonable.
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < 0.3 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Late-stream tightening: prefer tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Coupling with mean residual: prefer bins below mean residual (tighter).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // small gaps are risky too
        score += 25.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (post_residual near zero but not a dead gap).
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect closure is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 35.0;
        } else {
            score -= 15.0 * (1.0 - gap_after_next as f64 / post_residual.max(1) as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here: this bin may become dead space; mild penalty
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight reuse;
    // few open bins -> tolerate opening/using fresh space.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residuals below the mean (consolidate the emptier space).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: choose it only when no open bin looks decent.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; shrinks late in stream or when many bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 - 20.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        // but if the next item is huge and current residuals are small, fresh bin is fine
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // Next item cannot fit in this bin after placement: penalize proportionally
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Penalize large unusable residual (dead space) nonlinearly
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are hard to use
    }
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Prefer tighter fits relative to the mean residual of open bins
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it unattractive unless this bin would leave bad dead space
    if bin_residual == bin_capacity {
        // attractive only if current bin fit is poor (large post_residual) or no real alternative
        let bad_fit = (post_residual as f64) > 0.45 * bin_capacity as f64;
        if bad_fit || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 45.0;
        }
    }

    // Mild preference for filling existing bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tight * tight;

    // Penalize large dead space after placement, especially tiny slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    score += 0.05 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty if we waste lots of space
            score += 0.03 * post_residual as f64;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        score = 55.0 - 30.0 * crowded * mean_tight - 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // If some bin fits tightly, discourage new bin.
        if tight > 0.85 && fitting_bins_count >= 1 {
            score += 40.0;
        }
        return score;
    }

    // Late in stream: consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (fill emptier-but-usable bins) mildly.
    score += 0.04 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post = post_residual as f64;

    // Base: prefer small post-residual, with quadratic smoothing.
    let mut score = post * (1.0 + 0.6 * post / cap);

    // Tight-fit reward: strong non-linear bonus as post_residual -> 0.
    score -= 30.0 * (1.0 - post / cap).powf(4.0);

    // Stream progress coupling: waste matters more late in the stream;
    // polynomial interaction between progress and residual.
    score += 12.0 * progress * (post / cap) * (2.0 - progress);

    // Lookahead: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let snug = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 18.0 * snug;
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to leftover.
        score += 6.0 * (post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mean-residual coupling: placing into a bin with residual near the mean
    // keeps balance; extreme residuals get a mild penalty.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * (1.0 - dev);

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with stream progress and open-bin count, so it only wins when no open
    // bin offers a reasonable fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 30.0 * progress + 2.5 * open_bins_count as f64;
        // But if the item is large and the next item likely needs fresh space,
        // opening a new bin is less costly.
        if fit_ratio > 0.6 {
            score -= 20.0 * (fit_ratio - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "usable classes".
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.8; // penalize off-class dead space

    // Integer-division thresholds: post_residual in [0..100]
    let q = post_residual / 10; // 0..10
    match q {
        0 => score -= 60.0,          // perfect fit
        1 => score -= 45.0,          // excellent
        2 => score -= 30.0,
        3 => score -= 15.0,
        4 => score -= 5.0,
        _ => {}                       // large leftover: neutral
    }

    // Reward tight fits strongly (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let frac = (next_item_size as f64) / (post_residual as f64);
            if frac > 0.7 {
                score -= 25.0 * frac;
            } else {
                score += 10.0 * (1.0 - frac); // wasteful small fill
            }
        } else {
            // next item won't fit here: prefer leaving harmonic-friendly leftover
            let nm = next_item_size % 10;
            if (post_residual % 10) == 0 && post_residual >= nm {
                score -= 8.0;
            }
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = (post_residual as f64) / (bin_capacity as f64);
        if fitting_bins_count > 0 {
            // only attractive if best existing fit would waste a lot
            score += 30.0 + 50.0 * (1.0 - fit_quality);
        } else {
            score -= 100.0; // must open a bin
        }
        // early stream: opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual context: if this bin's residual is far below mean, it's a good closer
    let diff = mean_residual - bin_residual as f64;
    score += diff.clamp(-50.0, 50.0) * 0.15;

    // Mild penalty for too many open bins (encourage closing out)
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: small nonzero gaps are hard to reuse.
    let pr = post_residual as f64;
    if pr < 10.0 {
        score += 60.0 * (10.0 - pr);
    } else if pr < 20.0 {
        score += 15.0 * (20.0 - pr);
    }

    // Reward leaving space exactly matching the next item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins tighter than the mean residual (good fit relative to fleet).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when the current bin would leave
    // a really awkward gap; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if pr < 10.0 && fitting_bins_count >= 1 {
            score -= 5.0; // slight edge when we'd otherwise create dead space
        } else {
            score += 40.0;
        }
    }

    // Slight late-stream conservatism: keep bins reusable as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins that end (nearly) full.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits the post-residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Next item can also be placed here: excellent chaining.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.3 * chain_waste;
        } else {
            // Next item won't fit here after this placement: penalize
            // proportionally to how much it misses the fit.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss.min(40.0);
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter"
    // and should be preferred to close them out.
    let tightness = mean_residual - post_residual as f64;
    score += 0.4 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        // Opening a new bin is more attractive later in the stream when many
        // open bins are fragmented (high mean residual).
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = base_penalty + post_residual as f64 - 10.0 * fragmentation;
        // If next item is large, a fresh bin is useful.
        if next_item_size > 60 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight stream-progression pressure: early on, be conservative with
    // bin usage; late, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Mild penalty proportional to item size to prefer placing big items
    // into tight bins (best-fit bias).
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space (dead space is doubly bad).
    score += 0.8 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: reward leaving post_residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is highly valuable.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize proportionally to wasted potential.
            score += 4.0 * (next_item_size as f64 / post_residual.max(1) as f64).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer fuller bins relative to the fleet average.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Congestion control: many open bins -> discourage new bins implicitly via residual logic;
    // few open bins -> allow spreading.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open or when a fitting bin exists.
        score += 6.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Early in stream, new bins are cheap; late, they are expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Small residual bins are precious; discourage dumping big items into them
    // unless it nearly empties the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 6.0;
    } else if fill_ratio < 0.3 && bin_residual < bin_capacity {
        score += 3.0 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let base = pr
        + 60.0 * norm_pr * norm_pr * (1.0 + progress)
        + 40.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling of post residual with stream progress: waste penalized more later.
    let progress_coupling = 25.0 * norm_pr * progress * (1.0 - progress + 0.5);

    // Lookahead: reward if next item fits into post residual (smooth soft-min form).
    let next_fits = if next_item_size > 0 {
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        -30.0 * (1.0 - slack * slack)
    } else {
        0.0
    };

    // Last-chance bin: strong reward to use it rather than open a new bin.
    let last_chance = if fitting_bins_count == 1 { -35.0 } else { 0.0 };

    // Mild preference toward bins with residuals near the mean (smooth quadratic).
    let mean_pull = -8.0 * (1.0 - ((pr - mean_residual) / cap).powi(2));

    // Slight preference to fill emptier bins when many bins are open (quadratic in count).
    let spread = if open_bins_count > 1 {
        -6.0 * (open_bins_count as f64).ln() * norm_pr
    } else {
        0.0
    };

    let score = base + progress_coupling + next_fits + last_chance + mean_pull + spread;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact divisions of capacity
    // are "harmonic" residuals (50, 33/34, 25, 20, 10 ...) that pair well
    // with many item sizes; reward them strongly.
    let harmonic_divs: [u32; 6] = [2, 3, 4, 5, 6, 10];
    let mut harmonic_bonus = 0.0f64;
    for &d in harmonic_divs.iter() {
        if post_residual > 0 && (bin_capacity / d) == post_residual {
            harmonic_bonus = 18.0;
        }
        if post_residual > 0 && post_residual % d == 0 && post_residual <= bin_capacity / d {
            harmonic_bonus += 4.0;
        }
    }
    score -= harmonic_bonus;

    // Dead space penalty: tiny unusable remainders are worse than they look.
    if post_residual > 0 && post_residual < 10 {
        score += (12.0 - post_residual as f64) * 2.5;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a chain completion — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_class = next_item_size % 10;
            let post_class = post_residual % 10;
            if nxt_class == post_class {
                score -= 8.0; // same harmonic decade, likely good reuse
            }
            score -= 5.0;
        } else {
            // next item cannot use this bin's remainder anyway
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
        if post_residual < 10 {
            score += 8.0; // but not if it creates dead space
        }
    }

    // New empty bin candidate: prefer it only when open bins are crowded
    // or the fit into any existing bin would leave large waste.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0
            + (mean_residual / bin_capacity as f64) * 30.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        score = bin_capacity as f64 * 0.9 + pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Mild tightness reward: smaller relative leftover fraction is better.
    score -= (post_residual as f64 / bin_capacity as f64).powi(2) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits, or open-bin pressure is low.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: open new bin
        } else {
            score += 25.0 + 4.0 * open_bins_count as f64; // discourage wasting open capacity
        }
    }

    // Open-bins pressure: many open bins -> favor consolidating into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Lookahead coupling: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference toward bins with below-average residual (larger free space bins
    // keep flexibility; prefer filling tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: tighter packing matters more as stream advances.
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // 2-step lookahead: strongly reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0 + 40.0 * progress; // perfect chain: keep this pair together
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a further residual: reward proportionally.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - chain_waste / bin_capacity as f64) * (0.5 + 0.5 * progress);
        } else {
            // Next item cannot follow in this bin: penalize, worse for large overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.5 * overshoot * (0.5 + 0.5 * progress);
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are "tight" fits;
    // filling them is good (removes awkward bins), so reward closing the gap.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        let gap = residual_f - mean_residual;
        if gap < 0.0 {
            // Post residual below mean: bin is nearly exhausted -> good placement.
            score += 0.6 * gap; // gap negative, subtracts from score
        } else {
            // Post residual above mean: leaves loose space -> mild penalty.
            score += 0.25 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless post_residual is huge, i.e. wasteful).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 0.3 * (bin_residual as f64);
    }

    // New-bin candidate handling: an empty bin should only win when all fitting bins
    // are poor. Penalize the fresh bin moderately; the lookahead/last-chance bonuses
    // on real bins can override it.
    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * (1.0 - progress);
    }

    // Small penalty per open bin: discourage bin proliferation slightly.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good, but avoid exact
    // tiny leftovers that nothing can use anyway (dead space weighting).
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).sqrt() * 10.0;

    // Penalize leaving residual that is too small for the minimum item size (1),
    // but strongly penalize residuals in the awkward 1..=15 "dead zone".
    if pr > 0.0 && pr < 16.0 {
        score += 12.0 * (16.0 - pr);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving
    // that much space; if post-residual is just barely too small for next item,
    // penalize slightly (wasted potential).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 0.5 * nx;
        } else if pr >= nx * 0.7 {
            score += 4.0;
        }
        // If next item fits exactly in this bin's residual now, mild penalty for
        // consuming space the next item could have used when we have alternatives.
        if bin_residual >= item_size + next_item_size && fitting_bins_count > 1 {
            score += 0.15 * nx;
        }
    }

    // New-bin candidate handling: empty bin (residual == capacity). Opening a new
    // bin is only attractive when existing bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64;
        // Base cost of a fresh bin; grows with number of open bins and progress.
        score += 30.0 + 2.5 * crowding + 20.0 * progress;
        // If no open bin other than this candidate fits, opening is more acceptable.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // Large items relative to capacity favor fresh bins.
        score -= 0.1 * item_size as f64;
    }

    // Global state: when mean residual across open bins is high, we can afford
    // looser fits; when low, tighten up (penalize waste more).
    score += 0.2 * (mean_residual - pr) * (1.0 + 0.01 * open_bins_count as f64);

    // Late in the stream, closing bins out tightly matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with stronger penalty late in the stream
    let mut score = pr * (0.9 + 0.6 * progress);

    // Non-linear polynomial coupling: quadratic & cubic shaping of residual vs progress
    let coupling = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + progress);
    score += 30.0 * coupling;

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= 12.0 * (-norm_pr * 6.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / cap;
        } else {
            score -= 6.0 * (pr - ns) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.15 * open_bins_count as f64 * progress;

    // Deviation from mean residual: prefer bins near the mean to balance
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make it moderately attractive only when residual is very tight
    if bin_residual == bin_capacity {
        score = pr * (0.9 + 0.6 * progress) + 5.0 - 15.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a "nice" divisor class
    // of the capacity are more reusable. Classes via modulo on small divisors.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    for d in [10u32, 20, 25, 50].iter() {
        if pr >= *d && pr % d == 0 {
            harmony_bonus += 6.0;
        }
    }
    // Perfect residual classes: multiples of common item sizes are highly reusable
    if pr > 0 {
        for m in [10u32, 20, 30, 40, 50, 60, 70, 80].iter() {
            if pr % m == 0 {
                harmony_bonus += 3.0;
                break;
            }
        }
    }
    score -= harmony_bonus;

    // Penalize small dead space (waste) superlinearly
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 4.0;
    }

    // Tight fit reward: post_residual small but not wasteful
    let tight = (pr as f64) / cap;
    if tight < 0.05 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let frac = (next_item_size as f64) / (post_residual as f64);
        if frac > 0.85 {
            score -= 15.0;
        } else if frac > 0.5 {
            score -= 6.0 * frac;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // bin becomes unusable for the lookahead; penalize leftover
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins fit badly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0 + open_bins_count as f64 * 0.5;
        // but if many items remain, fresh bin amortizes; slight discount late in stream
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
        // if next item is large and current residual can't host both, new bin less bad
        if next_item_size > 0 && item_size + next_item_size > bin_residual && bin_residual < bin_capacity {
            score -= 5.0;
        }
        // empty-bin harmony: keep score from being lowest when a decent fit exists
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible < 20.0 {
                score += 15.0; // an open bin fits tightly; don't open new
            }
        }
    }

    // Mild preference to balance residuals toward mean
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Integer-division threshold: bins where residual >= half capacity are flexible
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // item (1..=10) are pure waste; penalize them extra hard.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual < 20 {
        // Small gaps usable only by tiny items: moderate penalty.
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: this gap may become dead space; penalize.
        score += 10.0;
    }

    // Open-bin pressure: discourage proliferating bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 3.0 * (1.0 - progress));

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // are crowded (low mean residual) or many bins already open.
    if bin_residual == bin_capacity {
        score -= 10.0 + mean_residual * 0.2;
        score += 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 60.0;
            } else {
                // penalize leftover that won't fit next item well
                score += 0.3 * slack as f64;
            }
        } else {
            // next item cannot fit here: penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size > 60 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0; // pairing opportunity justifies a fresh bin
        }
    }

    // Late in the stream, prefer closing bins out (consolidation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (post_residual == 0) as i32 as f64;

    // Many open bins: encourage filling existing bins rather than spreading.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low; boost non-linearily.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 6.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make it unattractive unless current fits are bad.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 20.0);
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so real bins are preferred; relax when many bins are open
        // with large residuals (fragmentation) or late in the stream.
        score = bin_capacity as f64 * 0.6 + 20.0 - 15.0 * pressure.min(3.0) - 25.0 * late;
        // If next item is huge and post_residual tiny, new bin looks better.
        if next_item_size > post_residual && next_item_size > bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Time-horizon modulation: early on, be conservative (keep space); late, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Smooth cubic coupling: waste hurts more mid-stream.
    let waste = (bin_residual as f64 - item_size as f64) / cap;
    score += 0.5 * waste * waste * (1.0 - progress) * progress;

    // Reward tight fits with a smooth saturating term.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= (fit_ratio * fit_ratio) * (1.0 + progress);

    // Lookahead coupling: penalize leaving post residual that barely
    // accommodates the next item poorly; reward when it fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = nxt / pr.max(1.0);
            score -= 0.8 * snug * (1.0 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 1.5 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 + progress);
    }

    // Mild pressure against opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.02 * open_bins_count as f64;
    }

    // Mean residual interaction: deviating far from mean residual is penalized smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" multiples
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows super-linearly for small residuals
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post) / 10.0;
    }

    // Reward residuals divisible into common harmonic classes (5, 10, 20, 25)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // harmonic match: next item leaves another clean residual
            let nr = post_residual - next_item_size as f64;
            if (nr as u32) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // residual too small for lookahead: penalize proportionally
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when mean residual suggests
    // existing bins can still absorb items
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * mean_residual / cap;
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
    }

    // Late in stream: prefer tighter packing (low residual) more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress * (post / cap);

    // Slight preference for bins with residuals close to mean (avoid fragmentation)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill: strongly reward closing the bin.
        score -= 25.0;
    } else {
        // Usable leftover: mild reward scaled by how large/usable it is.
        score -= 0.10 * post_residual as f64;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac * fill_frac;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chain packing). If it cannot fit anywhere after
    // this placement, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; the empty new-bin candidate gets penalized progressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure; only attractive when
        // existing fits are terrible (handled implicitly by their scores).
        score += 20.0 + bin_pressure;
    } else {
        score -= 2.0 * bin_pressure / (open_bins_count as f64 + 1.0);
    }

    // Last-chance bin: if this is the only bin that fits, use it rather than
    // opening a new bin, unless the fit is extremely wasteful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; // still penalize creating dead space heavily
        }
    }

    // Deviation from mean residual: prefer bins whose residual is near the
    // average (keeps bin states homogeneous, easing future consolidation).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward when post_residual exactly matches next item,
    // penalize when next item nearly fits but leaves tiny unusable residue.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 1.0 {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual as f64 >= nxt {
            score -= 15.0 / diff.max(1.0); // next item fits: good chaining
            score += (post_residual as f64 - nxt) * 0.3;
        } else {
            // next item does NOT fit: dead space risk grows as gap shrinks
            let gap = nxt - post_residual as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce space.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score += (mean_residual - resid_f) * 0.25; // using a tighter-than-average bin is costly
    } else {
        score -= (resid_f - mean_residual) * 0.1; // prefer roomier-than-average bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // current item is large relative to capacity (poor fit elsewhere likely).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * progress - 25.0 * large_item;
        // A fresh bin wastes nothing now; mild bonus if lookahead chains well.
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual non-linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus (zero waste).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residual after placement is only good if it's usable by the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead: reward residual that can host the next item,
            // scaled by how snugly the next item would then fit.
            let next_tightness = (post_residual - next_item_size) as f64;
            score -= 0.5 * next_tightness.max(0.0).min(20.0);
            score -= 25.0;
        } else {
            // Dead space: residual too small for the next item.
            score += 18.0 + 0.4 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // Penalize spreading across many open bins; encourage consolidation
    // especially early in the stream.
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Pull score toward mean residual: prefer bins with residuals
    // close to average (balanced packing), penalize outliers.
    score += 0.25 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item_size relative to residuals) or stream is nearly done.
    if bin_residual == bin_capacity {
        let crowding = fitting_bins_count as f64;
        let item_pressure = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is penalized heavily unless item is big and
        // fitting options are scarce.
        score += 55.0
            - 35.0 * item_pressure
            - 12.0 * (1.0 - crowding.min(3.0) / 3.0)
            - 30.0 * progress * (1.0 - item_pressure);
        // Avoid hoarding a fresh bin for tiny items.
        if item_size < 30 {
            score += 25.0;
        }
    }

    // Mild reward for bins that keep residual in "flexible" mid-range
    // (usable by most item sizes 10..80).
    if post_residual >= 10 && post_residual <= 80 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * p2) + norm_pr * (1.0 - p3);
    score += 20.0 * coupling;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - snug) * (1.0 - snug);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // Penalize bins far below mean residual (fragmentation pressure)
    score += 5.0 * (mean_residual - pr).max(0.0) / cap * (0.5 + p2);

    // Mildly discourage opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - 0.5 * progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quarter-capacity bands
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter) as f64;
    score += class * 3.0;

    // Perfect / near-perfect fits get strong reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space: post_residual cannot host the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Bonus when the leftover exactly accommodates the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening fresh bins is more acceptable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Prefer filling bins that deviate below the mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Modulo harmonic: residuals that are multiples of 10 pair well with typical sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // item (1..=9) are pure waste; penalize them super-linearly.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    }
    // Gaps of 10..=19 are only usable by small items; moderate penalty.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 12.0 + 0.5 * (19 - post_residual) as f64;
    }
    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: discourage proliferating bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Pull toward bins whose residual is close to what we consume
    // (favor bins that will end up "just right").
    let gap_to_mean = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * gap_to_mean;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // chaining here is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 3 { score -= 25.0; }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
        // Reserve space for a large next item when this bin would be nearly full.
        if next_item_size >= 50 && post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit
    // (i.e., this empty-bin call has perfect residual but we bias against
    // opening bins unless the existing fit is bad).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual) with a nonlinear bonus.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 12.0;
    } else if post_residual <= 25 {
        score -= 5.0;
    }

    // 2-step lookahead: strongly reward when next item fits the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item won't fit here; penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / 40.0).min(1.5);
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving very large residuals when many bins are open (fragmentation).
    if post_residual > 50 && open_bins_count > 3 {
        score += 6.0;
    }

    // Late in the stream, be more aggressive about filling bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize tiny dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * (item_size as f64);
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let mean_tight = 1.0 - mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 14.0 * mean_tight - 6.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 5.0; // item can't fit a fresh bin? shouldn't happen, guard anyway
        }
    }

    // Prefer consolidating into existing bins when many bins are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(10.0) * 0.3;
    }

    // Mild time-horizon modulation: early on, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.85 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score -= 12.0 * (1.0 - norm_pr).powi(3) * (1.0 + p2);
    // Reward tight fits more strongly as stream progresses
    score -= 8.0 * norm_pr * (1.0 - norm_pr) * (0.5 + p2);
    // Penalize post-residuals that no small item could reuse: cubic in normalized residual
    score += 6.0 * norm_pr.powi(3) * (1.0 + p3);
    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (1.0 + progress);
    }
    // Lookahead coupling: reward if next item fits in post residual, smoothly scaled
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).unsigned_abs()) as f64 / cap;
        score += 5.0 * fits_next * gap * gap;      // penalize sloppy lookahead fit
        score -= 6.0 * fits_next * (1.0 - gap) * (1.0 + p2);
    }
    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.02 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are heavily rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    } else if pr <= 20 {
        score -= 4.0;
    }

    // Modulo structure: residuals in "dead zones" (just above common item sizes)
    // are less likely to be filled later; penalize them.
    let dead = |r: u32| -> f64 {
        let mut p = 0.0;
        for k in 1..=10u32 {
            let t = k * 10;
            if r > t && r <= t + 5 {
                p += 6.0;
            }
        }
        // residual just above small item sizes 1..=9
        if r > 1 && r <= 3 { p += 3.0; }
        p
    };
    score += dead(pr);

    // Fractional capacity logic: how much of the bin the item consumes.
    let frac = item_size as f64 / cap;
    score -= frac * 20.0; // reward large fills

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot follow here; mild penalty scaled by waste
            score += (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // last item: pure tightness
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // crowded choice: prefer tighter residuals via base term already
        score += 2.0;
    }

    // Mean residual coupling: penalize placing into bins whose residual
    // deviates wildly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate handling: empty bin gets baseline so it is chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.3;
        // If nothing else fits, force new bin.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Stream progression: late in stream, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0 * (pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Strict dead-space avoidance: residuals too small for likely future items are wasted.
    // Treat post_residual in (0, 10] as near-dead; in (10, 20] as risky.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 25.0; // pure dead space
        } else if post_residual <= 20 {
            score += 12.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item cannot use this leftover -> mild dead-space penalty
        if post_residual > 0 && post_residual < 25 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of bins; more open bins -> favor reusing this one.
    score -= (open_bins_count as f64).ln().max(0.0) * 4.0;

    // New-bin candidate: empty bin has residual == capacity. Prefer keeping it closed unless
    // item is large (good utilization of fresh capacity) or all fits are poor.
    if bin_residual == bin_capacity {
        let utilization = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 20.0 * utilization; // large items open bins cheaply
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin serves the next item well
        }
    }

    // Mild phase pressure: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (below-mean residual = tighter bin).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0;
        } else {
            score += 0.5 * diff as f64;
        }
        // Penalize leaving a residual smaller than any plausible next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 20.0;
        }
    }

    // Reward tight fits relative to bin residual (small waste fraction)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fit_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Contextual adjustment via mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin, unless existing fits are very poor
    if bin_residual == bin_capacity {
        let mut base = 120.0;
        if post_residual == 0 { base -= 1000.0; }
        if next_item_size > 0 && post_residual as i64 == next_item_size as i64 { base -= 500.0; }
        if next_item_size > 0 && post_residual >= next_item_size { base += 0.5 * (post_residual as f64 - next_item_size as f64); }
        // Late in stream, discourage new bins more strongly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        base += 60.0 * progress;
        score = base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize small dead space that is hard to reuse (below min item size)
    let min_size = 1.0;
    if (post_residual as f64) < min_size {
        score -= 20.0;
    } else if post_residual < 10 {
        score += 15.0; // awkward sliver
    }

    // Tight fit reward: fraction of bin used by this placement
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra reward for near-exact chain fit
        let chain_slack = post_residual as f64 - next_item_size as f64;
        score -= 8.0 * (1.0 - chain_slack / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post_residual may become dead space relative to next item
        if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, costly late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = post_residual as f64 + 20.0 + 40.0 * progress;
        // If many bins are open with large residuals, prefer reusing them
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_score += 15.0;
        }
        // If no other bin fits, opening a new bin is natural
        if fitting_bins_count == 0 {
            new_bin_score -= 45.0;
        }
        score = new_bin_score;
    }

    // Mild penalty for scattering across too many open bins
    if bin_residual < bin_capacity && open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    // Prefer bins with residual close to item size (best-fit coupling)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 20.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: post-residual (tighter fit => lower score)
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight packing matters more (penalize waste harder).
    let tightness = 1.0 + 2.0 * progress * progress;
    score += tightness * norm_post * norm_post * cap * 0.25;

    // Non-linear dead-space penalty: residuals too small for typical future items
    let dead = (norm_post * (1.0 - norm_post)).max(0.0); // peaks mid-range
    score -= 6.0 * dead * (1.0 - progress);

    // Lookahead: reward leaving room for the next item (smooth bump)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        score += 4.0 * diff * diff * cap * 0.1 - 3.0 * (1.0 - (diff.abs() * 4.0).min(1.0));
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when many bins are open and this placement is wasteful
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 1.5;

    // Encourage balancing residuals toward the mean early on
    score += (post - mean_residual).abs() * (1.0 - progress) * 0.05;

    // Slight bias against opening new bins (new-bin candidate has full residual)
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Harmonic class: post_residual buckets via integer division thresholds
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 60.0,                 // perfect/near-perfect fit
        1 => score -= 35.0,                 // leaves <= 19, still highly usable
        2 => score -= 15.0,                 // leaves <= 29
        3 | 4 => score -= 5.0,              // mid-range residual
        5 | 6 => score += 8.0,              // awkward zone (30..69)
        _ => score += 15.0,                 // large waste
    }

    // Modulo coupling: post_residual divisible by capacity fractions
    if post_residual > 0 && (bin_capacity % post_residual.max(1)) == 0 {
        score -= 10.0; // residual divides capacity evenly (50, 25, 20, 10...)
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here; penalize leaving large unusable remainder
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 80.0;
        // allow new bin early in stream when many bins will follow anyway
        score -= (open_bins_count as f64) * 2.0;
        if post_residual > 50 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with low mean residual (well-packed bins)
    score += (mean_residual - post_residual as f64) * 0.2;

    // Slight preference for keeping fewer open bins
    score += open_bins_count as f64 * 0.5;

    // Progress-based mild pressure to consolidate as stream ends
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize tiny unusable gaps (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward leaving residuals that can still accommodate typical future items.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    if next_item_size > post_residual && post_residual > 0 {
        // dead space relative to the known next item
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above typical residual so only
        // chosen when open bins would create dead space.
        score += 20.0 + open_bins_count as f64 * 3.0;
    } else {
        // Prefer tighter bins (small residual before placement) via mean comparison.
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    }

    // Mild stream-progression tie-breaker: later in stream, favor consolidation.
    if total_items > 0 {
        score += (step_index as f64 / total_items as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward when post_residual exactly matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // chain leaves a small tail: mild penalty for tail size
            score += 0.2 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize proportionally to waste
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are "valuable space"
    let rel = (post_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 30.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // opening a new bin is cheap early, expensive late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9 + 50.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // pairing big item in fresh bin with next big item
        }
        if fitting_bins_count <= 1 {
            score -= 55.0; // no real alternative, allow new bin
        }
    }

    // Slight preference to fill nearly-full bins to close them out
    if post_residual < 10 {
        score -= 15.0;
    }

    // Tie-break: fewer open bins is better (compaction)
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness: fraction of bin used by this placement
    let used_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * used_frac;

    // Penalize small dead space (waste), reward larger post residual mildly
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // unusable sliver for typical items
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: bonus if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // dead space relative to known next item
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 8.0 * crowd * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is above mean residual, it's emptier -> less priority
    score += 0.3 * (bin_residual as f64 - mean_residual).clamp(-50.0, 50.0);

    // New-bin candidate handling: empty bin gets neutral-ish score; only win when fits are poor
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 5.0
            - 20.0 * (fitting_bins_count == 0) as i32 as f64
            + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Late-stream urgency to close bins
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Base: prefer placements that leave small residuals (tight fits).
    let mut score = post_residual as f64;

    // Smooth non-linear quadratic penalty on large leftover space,
    // strongest early in the stream when bin economy matters most.
    score += 12.0 * norm_post * norm_post * (1.0 - progress);

    // Cubic interaction: dead space is increasingly tolerated as the
    // stream progresses (smooth decay, no piecewise cutoffs).
    score += 6.0 * norm_post * norm_post * norm_post * (1.0 - progress) * (1.0 - progress);

    // Last-chance bin: strongly reward using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a fresh bin, more so late
    // in the stream; early on a new bin is less costly.
    if bin_residual == bin_capacity {
        score += 5.0 + 12.0 * progress;
        // But if no open bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Lookahead reward: if the next item can fit into the post residual,
    // this placement preserves future packing ability.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - norm_post) * (1.0 - progress);
    }

    // Slight preference toward bins whose residual is below the mean
    // (concentrate filling), scaled by stream progress.
    score += 0.02 * (mean_residual - post_residual as f64) * (0.5 + progress);

    // Mild reward for using already-open bins (bin count economy).
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual (dead space classes)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Reward near-full bins strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class: post_residual divisible classes (small dead space classes are reusable)
    let post_mod = post_residual % 10;
    if post_mod == 0 {
        score -= 15.0; // clean multiples of 10 likely reusable
    } else if post_mod <= 3 {
        score += 5.0; // tiny slivers are dead space
    }

    // Integer-division threshold on post_residual: buckets of capacity fractions
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 10.0; // less than quarter left: mostly dead
    } else if post_residual >= 3 * quarter {
        score -= 10.0; // still roomy, fine
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // chain placement possible
            // extra reward if next item exactly fills remaining
            if post_residual == next_item_size {
                score -= 50.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: prefer filling any bin as much as possible
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if no open bin fits well, new bin is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // if mean residual is large, prefer reusing open bins
        if mean_residual > item * 1.5 {
            score += 30.0;
        }
    }

    // Progress coupling: later in stream, be greedier about filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;

    // Fraction of capacity filled by this item: reward big fills
    score -= (item / cap) * 20.0;

    // Mean residual alignment: prefer bins whose residual is near mean (balanced packing)
    let bin_res = bin_residual as f64;
    let dev = (bin_res - mean_residual).abs();
    score += dev * 0.1;

    // Too many open bins: encourage consolidation
    if open_bins_count > 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 12.0; // steep penalty for tiny gaps
    } else if pr == 0.0 {
        score -= 30.0; // perfect fit strongly rewarded
    } else {
        // Reward leaving gaps that can still fit future items
        score -= (pr / bin_capacity as f64) * 8.0;
    }

    // Reward tight fits (item fills most of the residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: discourage scattering across many bins
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual deviates usefully
    score += (pr - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // and no bin offers a decent fit (post_residual would be small anyway).
    if bin_residual == bin_capacity {
        // baseline for a fresh bin
        score += 25.0;
        // opening a new bin is attractive if the leftover gap after placement
        // is large and usable (big item into empty bin)
        if pr >= 20.0 {
            score -= 20.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: strongly reward exact match of next item into the residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward closeness of the resulting two-step residual.
            let two_step = post_residual - next_item_size;
            score -= 25.0 * (1.0 - two_step as f64 / 20.0).max(0.0);
        } else {
            // Next item does NOT fit this bin after placement: penalize small dead residuals.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(50.0);
        }
    }

    // Compare against mean residual across open bins: prefer bins with less residual than average
    // (tighter bins) to keep loose bins available for future awkward items.
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when good fitting bins exist; reward it when item barely fits anywhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score += 55.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight early-stream tolerance for opening bins, tightening later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver given min item size 1..? keep mild
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: bonus if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).min(1.0);
        }
    }

    // New-bin candidate handling: only attractive when open bins are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_pressure = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize new bin when plenty of usable space remains across open bins.
        score += 20.0 + 10.0 * (1.0 - avg_pressure);
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 8.0;
        }
        // Later in the stream, opening fresh bins is more costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Prefer bins with residuals close below the mean (avoid fragmenting large gaps).
        let gap = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * gap;
    }

    // Mild preference to spread across many open bins when few exist (load balancing early).
    if open_bins_count < 4 && !is_new_bin {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: residual value decays with stream progress
    let decay = 1.0 - 0.5 * progress * progress;
    score -= decay * pr * (pr / cap);

    // Penalize large post-residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr / nxt).min(1.0);
        score -= 12.0 * usable * (pr / cap);
        if pr > 0.0 && pr < nxt {
            score += 8.0 * (1.0 - pr / nxt) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Smooth penalty when bin residual is far above mean residual (fragmentation pressure)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild penalty for opening many bins late
    score += 0.3 * (open_bins_count as f64) * progress;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // New-bin candidate: prefer it only when post-residual is huge or stream is early
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - pr / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity in classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let post_frac = pr / cap; // fraction of capacity left after placement

    // Class boundaries via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..=10 harmonic classes of dead space
    match class {
        0 => score -= 60.0,             // near-perfect fit
        1 => score -= 40.0,             // excellent fit
        2 => score -= 25.0,             // good fit
        3 => score -= 12.0,
        4 => score += 5.0,
        5 => score += 15.0,             // half-full bin: mediocre
        6 => score += 22.0,
        7 => score += 30.0,
        8 => score += 38.0,
        9 => score += 45.0,
        _ => score += 50.0,             // nearly empty bin placement: wasteful
    }

    // Exact fill bonus: post_residual divisible into clean classes
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0; // residual is a "harmonic" multiple of 10, likely reusable
    } else {
        score += (post_residual % 10) as f64 * 0.8; // odd remainder = dead space
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra reward if next item fills residual to a clean class
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter bins; post_residual term already does this
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: empty bin gets neutral-ish base but penalty
    // so it only wins when all real placements are bad (large post_residual).
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3 - 25.0 * (open_bins_count as f64 / (1.0 + step_index as f64));
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // opening fresh bin helps large upcoming items
        }
    }

    // Slight pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * post_frac;

    // Progress-based tiebreak: later in stream, prefer tighter fills more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively than large residuals.
    if post_residual > 0 {
        let too_small_for_min = post_residual < 10;
        let too_small_for_next = next_item_size > 0 && post_residual < next_item_size;
        if too_small_for_min || too_small_for_next {
            let gap_penalty = if too_small_for_min { 40.0 } else { 18.0 };
            // Tighter fits into near-full bins get a bonus to counteract base residual term.
            score = score + gap_penalty - (item_size as f64 / bin_capacity as f64) * 25.0;
        }
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already tight (good prior packing).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Open-bin pressure: with many open bins, avoid spreading; with few bins,
    // opening a new bin is cheap so the empty-bin candidate is less penalized.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the lookahead fit is near-tight.
        if post_residual - next_item_size <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Deviation from mean residual: prefer bins below-average residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild preference for placing into an existing bin vs. opening a new one,
    // scaled by how well the item fits (best-fit bias).
    if bin_residual != bin_capacity {
        score -= 5.0;
    } else {
        // Empty-bin candidate: penalize slightly more when many bins are open.
        score += (open_bins_count as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    score -= 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Exact fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches next_item_size well.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 80.0 * (-diff / 25.0).exp(); // close match => big bonus
        // Perfect chain: next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 30.0 + 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 200.0;
    }

    // Compare against mean residual across open bins.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 0.4 * (post_residual as f64 - mean_residual); // wasteful vs average
    } else {
        score -= 0.2 * mean_residual.abs().max(1.0).min(50.0); // better than average
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when existing bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < 25.0 && open_bins_count > 2;
        if fragmented {
            score -= 120.0; // open fresh bin when open bins are nearly full
        } else {
            score += 250.0 + 0.3 * open_bins_count as f64; // discourage new bins otherwise
        }
        // If lookahead item is large and current item nearly fills a bin, new bin is fine.
        if next_item_size > 60 && item_size > 60 {
            score -= 60.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Slight time decay: later in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual weighted super-linearly).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are large (item would waste space) or few bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_residual - item_size) as f64;
        // Opening a bin wastes a full empty residual for future items; penalize
        // proportionally to how well the item would fit elsewhere.
        let avg_fit = if fitting_bins_count > 0 { (open_bins_count as f64) / (fitting_bins_count as f64) } else { 1.0 };
        score += 55.0 - 0.35 * waste + 8.0 * avg_fit;
        // Early in stream, new bins are cheap; late, they are expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 0.15 * next_item_size as f64;
        } else {
            // Next item cannot follow here; slight penalty unless residual is near zero.
            score += 0.10 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // consolidate into existing bins rather than spreading.
    let spread = mean_residual - post_residual as f64;
    score += 0.05 * spread.max(0.0);

    // Mild penalty for leaving residual in a bin that equals a common item size band,
    // encouraging exact-fill patterns for medium items.
    let r = post_residual;
    if r == 20 || r == 30 || r == 40 || r == 50 {
        score -= 6.0;
    }

    // Encourage filling bins completely as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); late, tolerate larger residuals.
    let progress_weight = 0.6 * progress * progress;
    score = score * (1.0 - 0.35 * (1.0 - progress) * (1.0 - progress));

    // Smooth quadratic penalty on dead space relative to next item's fit potential.
    let next = next_item_size as f64;
    if next > 0.0 {
        let fit_gap = (pr - next).max(0.0);
        score += 0.25 * fit_gap * fit_gap / cap;
        // Reward when next item exactly fits the residual (perfect lookahead chain).
        let exact = 1.0 - (pr - next).abs() / cap;
        score -= 4.0 * exact.max(0.0) * exact.max(0.0);
    }

    // Penalize bins whose residual deviates strongly from mean residual (imbalance).
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress_weight);
    }

    // Mildly discourage scattering across too many open bins late in stream.
    score += progress_weight * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for fuller placements overall (low post_residual wins).
    score -= 1.5 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual in harmonic classes near 0 are best.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Modulo arithmetic: dead space classes. Residuals that are "awkward"
    // (not multiples of common small item sizes) are penalized.
    let awkward = (post_residual % 10 != 0) as f64 * 6.0
        + (post_residual % 5 != 0) as f64 * 3.0;
    score += awkward;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 25.0;
            } else if next_post <= 25 {
                score -= 10.0;
            }
            score += (next_post % 10 != 0) as f64 * 3.0;
        } else {
            // next item cannot use this bin's remainder; penalize large leftovers
            score += frac * 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual <= 30 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: neutral base score so open bins with decent
    // fits beat it; empty bin gets slight penalty scaled by open bins count.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 5.0;
        }
    }

    // Stream progression: early in stream, keep bins more open (prefer spreading);
    // late in stream, prefer consolidation (tight fits dominate already).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * frac * 5.0;

    // Mean residual coupling: if this bin is far below mean residual, it is a
    // "garbage" bin; placing here keeps clean bins clean.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
