    // Open-bin pressure: discourage opening new bins when few bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + (open_bins_count as f64) * 0.5;
        // But if this bin would be a poor fit elsewhere (large post residual relative to mean), opening is fine.
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild progression term: later in the stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
