        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (many fitting bins => keep item in existing bins).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 14.0 } else if fitting_bins_count == 1 { 4.0 } else { 0.0 };
        score += 15.0 - pressure - (mean_residual / bin_capacity as f64) * 6.0;
    }

    // Prefer filling bins with large residual relative to the fleet mean.
    score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    // Mild penalty for proliferating bins when residual is abundant.
    if open_bins_count > 4 && bin_residual as f64 > mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, mildly non-linear in post_residual
    let mut score = pr * (1.0 + 0.5 * fill * fill);

    // Smooth progress coupling: as stream advances, tighten the fit preference
    let tighten = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= tighten;

    // Penalize residual that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score -= 2.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bonus: avoid opening new bins when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Slight penalty for opening a new bin when many bins are already open and mean residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64 + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division thresholds on capacity fractions
    let post = post_residual as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..4 harmonic band
    match class {
        0 => score -= 40.0,             // near-perfect fill (residual < 25% cap)
        1 => score -= 12.0,             // good fill
        2 => score += 0.0,              // neutral
        3 => score += 15.0,             // wasteful
        _ => score += 30.0,             // mostly empty bin used for this item
    }

    // Dead space penalty: residual too small for the smallest plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap); // tighter next-fit is better
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins with below-average residual (concentrate filling)
    let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
    score += 0.5 * (post - avg);

    // New-bin candidate (empty bin): keep it neutral-to-slightly-high so it only
    // wins when all open bins are bad fits; escalate late in stream pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.6 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // item (<= 10) are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += (11 - post_residual as i32) as f64 * 40.0;
    }
    // "Awkward zone": residual just above a typical small item but below 20
    // makes future packing hard; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly prefer this bin (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0);
    }
    // If next item would leave a dead gap here, discourage.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: many open bins -> prefer consolidating
    // into existing bins, penalize the fresh-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: it always has post_residual == 100,
        // so subtract to keep it competitive, but add pressure that grows
        // with open bins and stream progress.
        score -= 20.0;
        score += open_bins_count as f64 * 3.0;
        score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
    } else {
        // Existing bins get a small consolidation bonus when many are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is below the mean residual (i.e., fuller bins),
    // keeping large residuals available for large future items.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // chain perfectly
        } else if post_residual > next_item_size {
            // next item fits: penalize proportionally to leftover after chain
            let chain_left = post_residual - next_item_size;
            score += 0.3 * chain_left as f64;
        } else {
            // next item does NOT fit here: penalize leaving a gap that blocks it
            let gap = next_item_size - post_residual;
            score += 0.5 * gap as f64;
        }
    }

    // Compare against mean residual: prefer bins that absorb slack
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no tight fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can serve the next item too
        }
    }

    // Late in the stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64).sqrt() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a slight super-linear penalty
    // on wasted space to discourage leaving unusable fragments.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Lookahead coupling: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra reward if the next item fits snugly afterwards too.
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 10.0;
            }
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 15.0; // perfect closer
        }
    }

    // New-bin candidate handling: an empty bin is attractive early or when many
    // bins are already open and this fit would be poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64) < 0.55 * bin_capacity as f64;
        if poor_fit && (open_bins_count > 2 || progress < 0.25) {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Global state: when mean residual across open bins is high, opening new bins
    // is cheap and spreading load is fine; when low, conserve bins (tight fits).
    if mean_residual > 40.0 {
        score += 0.15 * (mean_residual - 40.0);
    } else {
        score -= 0.10 * (40.0 - mean_residual);
    }

    // Mild pressure to close nearly-full bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, quadratically amplified
    let mut score = pr as f64 * (1.0 + 2.0 * x * x);

    // Smooth non-linear coupling of post residual with stream progress:
    // late in the stream, dead space is more costly (fewer chances to fill it)
    let progress_coupling = 1.0 + 1.5 * progress * (x * (1.0 - x)).sqrt();
    score *= progress_coupling;

    // Cubic interaction: very tight fits (small x) are rewarded more as stream advances
    score -= 40.0 * (1.0 - x).powi(3) * (0.5 + progress);

    // Lookahead: reward if next item fits into the post residual (smooth kernel)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let fit_margin = x - nx;
        if fit_margin >= 0.0 {
            score -= 25.0 * (1.0 - fit_margin) * (1.0 - fit_margin);
        } else {
            score += 10.0 * (-fit_margin) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.02 * open_bins_count as f64 * x;

    // Deviation from mean residual: prefer bins whose leftover stays near average
    score += 0.1 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize slightly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual ----
    // Class post_residual into capacity-fraction buckets (C=100):
    // dead zones are residuals that few item sizes can still use.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_frac = post / cap; // 0..1

    // Harmonic bucket id via integer division on post_residual (thresholds at
    // capacity fractions 1/8, 1/4, 3/8, 1/2, 5/8, 3/4, 7/8).
    let bucket = (post_residual * 8) / bin_capacity; // 0..=8
    // Penalize small-but-not-tiny residuals: items are >=1, but useful chunks
    // cluster near multiples of common sizes; a residual in (0, 10) is near-dead.
    let harmonic_penalty: f64 = match bucket {
        0 => 40.0,                       // post_residual == 0 -> perfect fit
        1 => 18.0,                       // tiny unusable sliver
        2 => 26.0,                       // 12.5%..25%: only small items fit
        3 => 12.0,
        4 => 6.0,                        // ~half full: very reusable
        5 => 8.0,
        6 => 4.0,
        7 => 2.0,
        _ => 0.0,                        // nearly empty bin: maximally flexible
    };
    score += harmonic_penalty;

    // ---- Modulo arithmetic on residual vs common item-size classes ----
    // Items often cluster in classes of 5 and 10; a residual that is a multiple
    // of 5 (or 10) is more likely to be exactly consumed later.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    } else if r % 5 == 0 && r > 0 {
        score -= 3.0;
    }
    // Reward residuals that can host the lookahead item exactly.
    if next_item_size > 0 {
        if r >= next_item_size {
            if r == next_item_size {
                score -= 10.0; // lookahead will close this bin perfectly
            } else if (r - next_item_size) % 5 == 0 {
                score -= 4.0;
            }
        } else {
            // Lookahead cannot use this bin's residual at all: mild penalty,
            // stronger when residual is small (dead space risk).
            score += 3.0 + (10.0 - residual_frac.min(10.0)) * 0.5;
        }
    }

    // ---- Tightness reward: filling a bin deeply is good ----
    let tightness = 1.0 - residual_frac; // fraction of capacity used after placement
    score -= 15.0 * tightness * tightness;

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; avoiding a new bin is valuable,
        // unless the fit would be terrible (huge dead space).
        let waste = post as f64;
        score -= 12.0 - (waste / cap) * 10.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh empty bin: extremely flexible. Give a strong baseline discount
        // so it wins only when all existing fits are poor, but add a cost that
        // grows with how many bins are already open (bin proliferation).
        score = 30.0 + 2.5 * open_bins_count as f64;
        // If the current item fits a decent existing bin, opening new is worse;
        // if it would leave a tiny residual elsewhere, new bin looks better.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 1.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // ---- Mean-residual coupling ----
    // If open bins are on average spacious, spreading load is cheap; if they are
    // tight, waste in any one bin hurts more.
    score += 0.05 * (mean_residual - post).abs();

    // ---- Stream progression: early stream, keep bins flexible ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * residual_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless
    // (items are >= 1, but gaps below ~10 rarely usable). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (exact or near-exact).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 5.0 * (item_size as f64 / bin_capacity as f64);

    // If the leftover can still fit the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If leftover cannot fit the next item, penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste = post_residual as f64;
        let penalty = if waste < 10.0 { 0.0 } else { waste * 0.5 };
        score -= 25.0 - penalty;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets
    // high post_residual but we counteract via this term applying to it too).
    if bin_residual == bin_capacity {
        // New bin candidate: base cost of opening a bin, scaled by open bins count.
        score += 15.0 + open_bins_count as f64 * 2.5;
        // But if no open bin fits well, allow opening: the last-chance bonus above
        // already lowered fitting bins; keep new-bin score moderate.
        if next_item_size > 0 {
            score -= 3.0;
        }
    }

    // Mild preference for bins below mean residual (balancing load).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Slight early-stream conservatism: keep bins openable later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: favor minimal post residual, with a slight superlinear penalty on dead space.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Lookahead: if next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Partially usable residual is better than fully wasted residual.
            score -= 18.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this residual: penalize proportional to wasted capacity.
            score += 10.0 * (post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist: keep flexibility, prefer tighter bins.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin is good.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default.
        score += 55.0;
        // But if open bins are badly fragmented (high mean residual wasted), allow it.
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.45 {
            score -= 40.0 * (fragmentation - 0.45);
        }
        // Early in the stream, opening bins is cheap (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Few open bins relative to stream length: opening is more acceptable.
        score -= 3.0 * (open_bins_count as f64).sqrt().min(8.0);
    } else {
        // Reward using existing bins, more when many are open (avoid bin proliferation).
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to the item (perfect-fit tendency),
    // coupling item size with bin residual.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Late in the stream, be greedy: minimize waste now since fewer items remain to fill gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * progress * frac;

    // Mean residual coupling: if this bin's residual is far below average, it's a good
    // candidate to close out (small residual bins should be filled first).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity used by this item (smooth fit quality)
    let fill = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: non-linear bonus for small post_residual
    score -= (1.0 - post_frac).powf(2.0) * 30.0 * (0.5 + fill);

    // Penalize dead space quadratically, scaled by progress (late dead space is worse)
    score += post_frac.powf(2.0) * 40.0 * (0.5 + progress);

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post_residual smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_frac = next_item_size as f64 / bin_capacity as f64;
        score -= 15.0 * next_frac * (1.0 - post_frac);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to leftover waste
        score += post_frac * 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a last resort
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 45.0; // no open bin fits -> new bin is fine
        }
        // late in stream, prefer consolidation into open bins
        score += progress * 10.0;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean-residual coupling: prefer bins whose residual is below average (tighter bins)
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.15;

    // Smooth progress interaction on base residual
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post_residual too small to ever hold another item (min size 1..=100 unknown, use small thresholds)
    if post_residual > 0 && post_residual < 5 {
        score += 60.0; // tiny slivers are dead space
    }

    // Harmonic classes: classify post_residual by capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let half = c / 2.0;
    if pr <= quarter {
        // near-full bin: good to fill it, mild reward
        score -= 10.0;
    } else if pr <= half {
        // mid residual: neutral-ish
        score += 5.0;
    } else {
        // large residual: keep big bins for big items
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here regardless; slight penalty if we waste a tight bin now
            let gap = next_item_size - post_residual;
            if gap < 10 {
                score += gap as f64 * 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 2.0;
        // but if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Modulo arithmetic harmonic classes on post_residual
    let m = post_residual % 10;
    score -= match m {
        0 => 8.0,          // round residual: likely reusable
        5 => 4.0,          // half-decade
        _ => 0.0,
    };

    // Integer-division thresholds: residual in [1..=10] band is prime filler
    if post_residual / 10 == 0 && post_residual > 0 {
        score += 25.0; // very small residual wastes a slot
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (mean_residual.min(100.0)) * 0.3;

    // Prefer bins with below-mean residual (fill the emptiest-fitting last)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // future item (<= ~10) are near-wasted capacity. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize gaps that cannot fit the lookahead item: the residual is
    // unusable for the next arrival, so it is likely dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }

    // Reward tight fits: post_residual close to 0 means near-perfect packing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // Prefer bins whose residual is below the current mean residual
    // (fill the emptiest-feeling bins that still fit, keep large residuals
    // available for large future items).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin is a fresh resource. Only
    // attractive when existing bins would leave large dead space or the
    // item is large relative to available residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 30.0 + 2.0 * (open_bins_count as f64);
        // If the item is large, a fresh bin is more appealing.
        new_bin_score -= 0.2 * item_size as f64;
        // If the fit in this empty bin would be tight (item near capacity),
        // opening is clearly good.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            new_bin_score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        new_bin_score += 10.0 * progress;
        score = score.max(new_bin_score);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is wasted forever.
        score += 15.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (-diff / 12.0).exp();
        // Perfect 2-chain: this item leaves exactly room for the next.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual the next item can't use at all.
        if post_residual > 0 && next_item_size > post_residual {
            score += 6.0;
        }
    } else {
        // Last item: prefer filling a bin as completely as possible.
        score -= 10.0 * tightness;
    }

    // Relative to mean residual: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        score += 8.0 * (rel - 1.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize the new-bin candidate unless nothing fits well.
    if bin_residual == bin_capacity {
        let best_possible_waste = (bin_residual as f64) - (item_size as f64);
        // A fresh bin starts with a full-capacity score; only attractive when
        // current bins would leave large dead space.
        score += 45.0;
        if next_item_size > 0 && best_possible_waste < next_item_size as f64 {
            score -= 10.0; // fresh bin still chains with next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild late-stream consolidation: prefer existing bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 6.0 * progress * tightness;
    }

    // Tie-break: prefer bins with fewer peers competing (keeps bin count low).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (low post_residual) with a non-linear boost
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Reward near-perfect packing (post_residual < 10) strongly
    if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 25 {
        score -= 6.0;
    }

    // Dead-space penalty: residuals that are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // awkward sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item can't use the leftover, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 2.0;
        let mean_pressure = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        let worth = 20.0 * mean_pressure + progress * 10.0 - crowded;
        score += 25.0 - worth; // low score (open new bin) when worth is high
        // Early in stream with plenty of space around, discourage new bins
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 1 {
            score += 30.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    // Late-stream tightening: penalize waste more as stream ends
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of fill ratio with stream progress
    let fill = item / cap;
    score -= 30.0 * fill * fill * (0.5 + progress);

    // Reward near-perfect fits smoothly (residual close to 0)
    let tight = (1.0 - post / cap).clamp(0.0, 1.0);
    score -= 20.0 * tight * tight * tight;

    // Lookahead: penalize if next item could have fit in current residual but not post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= bin_residual as f64 && nxt > post {
            score += 8.0 + 12.0 * (nxt / cap);
        }
        // Smooth bonus if next item fits exactly in post residual
        let gap = (post - nxt).abs();
        if nxt <= post {
            score -= 10.0 * (1.0 - gap / cap).max(0.0);
        }
    }

    // Last-chance bin: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Penalize new empty bin candidate unless it's genuinely better than poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        // Early stream: opening bins is cheaper
        score -= 20.0 * (1.0 - progress);
        // If no open bin fits, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for leaving residuals that are awkwardly small relative to mean
    if post > 0.0 && post < mean_residual * 0.3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" classes.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space classes: residuals that most item sizes (1..100) can still use
    // are rewarded; tiny unusable slivers are penalized.
    match class {
        0 => score -= 18.0,               // perfectly round residual, highly reusable
        5 => score -= 10.0,               // half-class, decent reusability
        2 | 8 => score -= 6.0,
        1 | 3 | 7 | 9 => score -= 3.0,
        4 | 6 => score -= 5.0,
        _ => {}
    }

    // Integer-division thresholds: how many items of the lookahead size fit.
    if next_item_size > 0 && next_item_size <= pr {
        let fits = pr / next_item_size;
        score -= 8.0 + 4.0 * fits as f64;
        // exact fill of residual by lookahead: excellent
        if pr % next_item_size == 0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // lookahead cannot use this residual -> dead space likely
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins tighter than average (good fits).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Progress coupling: late in stream, prefer closing bins tight (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (pr as f64 / bin_capacity as f64);

    // Penalize leaving residual in the awkward 1..=9 sliver band entirely.
    if pr >= 1 && pr <= 9 {
        score += 14.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        if pr == bin_capacity {
            score += 5.0; // neutral baseline for brand-new bin
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0;
        }
        score += 0.3 * open_bins_count as f64;
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    let pressure = open_bins_count as f64 / 20.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 6.0;
    }

    // New-bin candidate: slightly penalize so it's only chosen when open bins are truly poor
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    // Mild preference for bins tighter than the mean residual (compact packing)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead reward: if the next item fits exactly into post_residual,
    // this is a perfect pairing -> heavily favored.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Slack after hypothetically placing the next item too.
            let double_left = post_residual - next_item_size;
            score -= 20.0 - double_left as f64 * 0.25;
        } else {
            // Next item cannot follow here; penalize leftover dead space
            // more when the leftover is small (hard to reuse).
            let left = post_residual as f64;
            if left > 0.0 && left < next_item_size as f64 {
                score += (next_item_size as f64 - left) * 0.5;
            }
        }
    }

    // Tight fit reward relative to current residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Compare post_residual against mean residual across open bins:
    // leaving less than average is good (denser packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: mildly penalize opening a new bin early in the stream,
    // but allow it late or when open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 8.0 + progress * 10.0 - avg_fill * 15.0;
        // A fresh bin is attractive if the next item pairs perfectly with it.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 25.0;
        }
    }

    // Penalize tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    let tight_fit = (post_residual as f64) / bin_capacity as f64;
    score += tight_fit * tight_fit * 60.0;

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer reusing bins unless residual is very fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 45.0 - 20.0 * progress;
        // If existing bins are highly fragmented (low mean residual), opening fresh is fine.
        if mean_residual < item_size as f64 {
            new_bin_cost -= 20.0;
        }
        // If many bins fit the item, opening a new bin is rarely needed.
        if fitting_bins_count > 2 {
            new_bin_cost += 15.0;
        }
        // Lookahead synergy: an empty bin perfectly fits the next item too.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_cost -= 10.0 * (1.0 - (next_item_size as f64) / bin_capacity as f64);
        }
        score += new_bin_cost.max(-10.0);
    }

    // Mild penalty for over-fragmenting when many bins are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residual close to mean (balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post residual, normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, dead space matters more (no time to fill it).
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + 3.0 * norm_post * progress * progress;
    score += poly;

    // Perfect fit reward (smooth): strongest when post_residual near 0
    score -= (1.0 - norm_post).powi(3) * (1.0 + progress);

    // Last-chance bin: strongly reward using it, else item forces a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * progress;
    }

    // Penalize opening a new bin when open bins can fit the item
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin only attractive if no fitting bins exist or item barely fits elsewhere
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 2.0 * scarcity + 0.5 * progress;
        // If lookahead item fits into the residual of this new bin placement, soften penalty
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 0.8;
        }
    }

    // Lookahead synergy: reward bins whose post residual accommodates next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 0.3 / (1.0 + gap / cap);
        if post_residual as f64 >= next_item_size as f64 {
            score -= 0.4 * (1.0 - progress);
        }
    }

    // Mild preference for bins tighter than average
    score += 0.2 * ((mean_residual - bin_residual as f64) / cap).max(-1.0).min(1.0);

    // Discourage proliferation of open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity fractions
    let class = (post_residual * 4 / bin_capacity) as f64; // 0..=3 quartile class
    let residue_mod = (post_residual % (bin_capacity / 4)) as f64;

    let mut score = post;

    // Reward tight fits: small post_residual and fine-grained residue
    score -= (1.0 - post / cap) * 30.0;
    score -= residue_mod * 0.15;

    // Quartile-class shaping: class 0 (near-empty leftover) is dead space, penalize;
    // classes 1-2 (usable chunks) are fine.
    score += match class as u32 {
        0 => 25.0,
        1 => 0.0,
        2 => 5.0,
        _ => 12.0,
    };

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonically compatible: reward, stronger when next item fills it well
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 10.0 + 15.0 * fill;
        } else {
            // next item won't fit here: penalize leftover dead space, scaled by stream progress
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 + 12.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin may serve future large items
        }
    }

    // Prefer bins already below mean residual (consolidating emptier bins)
    score -= (mean_residual - post) * 0.1;

    // Slight preference for keeping number of open bins from exploding
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gap too small for the smallest plausible item -> dead space.
        let dead_threshold = 10.0;
        if pr < dead_threshold {
            score += 60.0 * (dead_threshold - pr) / dead_threshold;
        } else {
            // Smoothly reward larger usable residuals slightly.
            score += 0.05 * (pr - dead_threshold);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Tight fit bonus: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (would leave a big dead gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if pr > 0.0 && pr < dead_threshold {
            score -= 20.0; // last chance AND tight -> very good
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: open new bin
        } else {
            // Penalize opening a new bin when existing bins can fit.
            score += 25.0 + 2.0 * open_bins_count as f64;
            // If the item would fit tightly somewhere, really discourage new bin.
            if fill_ratio > 0.7 {
                score += 40.0;
            }
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        score -= 0.2 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // This bin's leftover can't host the next item anyway -> mild penalty.
        score += 5.0;
    } else if next_item_size > 0 && next_item_size == post_residual {
        // Sets up a perfect fit for next item.
        score -= 25.0;
    }

    // Early in the stream, be slightly more willing to open bins (hedging).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        // Perfect 2-step match is highly desirable.
        if slack_after_next == 0 {
            score -= 60.0;
        } else {
            // Reward proportional to how tightly the next item nests.
            let tightness = 1.0 - (slack_after_next as f64 / post_residual as f64);
            score -= 30.0 * tightness;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving residual close to but below next size (dead space).
        let gap = (next_item_size - post_residual) as f64;
        score += 15.0 * (1.0 - gap / 100.0).max(0.0);
    }

    // Compare post_residual against mean residual across open bins.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let deviation = post_residual as f64 - mean_r;
    // Prefer bins that end up below-average residual (tighter packing).
    score += 0.3 * deviation;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate (empty bin) mildly, unless residual waste would be severe.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Opening a new bin is acceptable late in stream or when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Small nudge toward bins with larger residual before placement (less fragmented choice).
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(1.5) * 20.0;
    } else {
        score -= 50.0; // perfect fill
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leftover dead space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize placing into bins with residual far from mean (fragmentation control).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    // New-bin candidate logic: empty bin gets a baseline penalty so it's chosen
    // only when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in stream or many open bins -> less eager to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
        if open_bins_count > 3 {
            score += (open_bins_count as f64).ln() * 5.0;
        }
        // If next item is large and this item is small, opening fresh may be good.
        if next_item_size > item_size && next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual, mildly convex so tiny dead space is strongly preferred.
    let mut score = pr + 0.35 * (pr / cap) * (pr / cap) * cap;

    // Smooth non-linear coupling with stream progress: early on tolerate slack,
    // later tighten preference for small post_residual.
    let tight = 1.0 + 1.2 * progress * (1.0 - progress * 0.5);
    score *= tight;

    // Reward tight fits (small post_residual relative to item size) smoothly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Lookahead: reward bins whose residual can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - slack) * (0.5 + 0.5 * (1.0 - progress));
        } else {
            let gap = (nx - pr) / cap;
            score += 3.0 * gap * gap;
        }
    }

    // Penalize spreading across many open bins mildly (encourage consolidation).
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Deviation from mean residual: prefer bins whose residual differs smoothly.
    score += 0.25 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only bin that fits (avoid new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_base = cap * (0.55 + 0.45 * progress);
        let crowd = (fitting_bins_count as f64).ln().max(0.0);
        score = new_bin_base + 2.0 * crowd - 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let residual_fraction = post_f / cap;

    // Integer-division thresholds on post_residual: which harmonic band does the leftover fall in?
    let band = post_residual / (bin_capacity / 4); // 4 harmonic bands: 0..=3
    match band {
        0 => {
            // post_residual < 25: tight fit, nearly perfect packing -> strong reward
            score -= 30.0 + (25.0 - post_f) * 1.5;
        }
        1 => {
            // 25..49: leftover could fit a small future item -> mild reward
            score -= 10.0;
            // penalize if next item cannot use this leftover
            if (next_item_size as u32) > post_residual && next_item_size > 0 {
                score += 12.0;
            }
        }
        2 => {
            // 50..74: half-empty bin, mediocre
            score += 5.0;
        }
        _ => {
            // 75..100: mostly empty bin used for a small item -> wasteful
            score += 20.0;
        }
    }

    // Perfect fit bonus (harmonic class 0 exact)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to how much space we are committing.
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            // No alternative: new bin is mandatory
            score -= 100.0;
        } else if post_residual > 0 && item_size <= bin_capacity / 2 && fitting_bins_count <= 2 {
            // small item, few options: allow new bin occasionally
            score -= 20.0;
        }
    }

    // Lookahead coupling: if next item exactly fits the post residual (harmonic match), reward heavily.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 40.0;
    }
    // Modulo arithmetic: next item divisible classes matching residual divisibility
    if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Progress-dependent pressure: later in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins whose residual deviates favorably from the mean residual (fill below-average-space bins first)
    score += (mean_residual - post_f) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (min size 1,
    // but practically below next_item_size) are wasted. Penalize heavily.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Very small leftover gaps (< ~15% capacity) are near-dead space.
        if post_residual < (bin_capacity as f64 * 0.15) as u32 {
            score += 25.0 * (1.0 - post_residual as f64 / (bin_capacity as f64 * 0.15));
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (low post_residual relative to bin capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another one.
    if bin_residual == bin_capacity {
        score += 20.0 + 4.0 * open_bins_count as f64;
        // But if no open bin fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        }
    }

    // Slight preference for bins already below mean residual (consolidating slack).
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 80.0;
            // Bonus proportional to how snugly the next item fits after this one.
            let second_leftover = post_residual - next_item_size;
            score -= (30.0 * (1.0 - second_leftover as f64 / bin_capacity as f64)).max(0.0);
        } else {
            // Penalize leaving a gap the next item cannot use.
            let gap = post_residual as f64;
            score += gap * 0.5;
            // Extra penalty if next item is small (wasted small gap).
            if next_item_size < gap {
                score += 10.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when many bins are already open and could fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of starting a fresh bin.
        score += 120.0;
        // If other bins fit, discourage new bin unless current fit is terrible.
        if fitting_bins_count > 0 {
            let best_possible = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
            score += 60.0 * best_possible;
        }
        // Early in stream, slightly more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference to consolidate into fewer bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tight fit)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits nonlinearly
    score -= 0.6 * cap * fit_ratio * fit_ratio;

    // Penalize small unusable dead space (post residual that likely can't host future items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 3.0;
        }
    } else {
        // Last item: finishing a bin exactly is ideal
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (high fragmentation) or few bins fit the item
    if bin_residual == bin_capacity {
        // new bin baseline: post_residual = cap - item_size
        let openness = (step_index as f64) / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).recip()
        };
        // penalize opening new bins early / when many bins fit
        score += 15.0 * (1.0 - openness) + 35.0 * pressure;
        // reward new bin when open bins are highly fragmented (mean residual large)
        score -= (mean_residual / cap).min(1.0) * 10.0;
        // exact-perfect new-bin start for large items
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Mild preference to consolidate: fewer open bins relative to progress
    score += 0.05 * open_bins_count as f64;

    // Global residual balancing: prefer bins whose residual deviates from mean
    // (drive outliers toward closure)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in stream, closure matters more (avoid stranded residuals)
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += 10.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr;
    let coupling = norm_pr * (1.0 + 2.0 * progress * progress) * (1.0 - norm_pr * norm_pr);

    let mut score = base + 30.0 * coupling;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 40.0 * progress);

    // Penalize bins that cannot fit the next item (dead space creation)
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > pr {
        score += 8.0 + 20.0 * progress;
    } else if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 25.0; // perfect next-item fill
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // Prefer bins whose residual deviates favorably from mean residual
    score -= (mean_residual - pr) * 0.05;

    // New-bin candidate: neutral baseline, penalize opening new bins early
    if bin_residual == bin_capacity {
        score += 5.0 + 40.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r5 = (pr % 5) as f64;
    let r20 = (pr % 20) as f64;

    // Penalize post-residuals that are "awkward" (not multiples of 5/10).
    score += r10 * 0.35 + r5 * 0.25 + r20 * 0.10;

    // Reward post-residuals in useful harmonic classes: 0 (perfect), 10, 20.
    if pr == 0 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 20 == 0 {
        score -= 3.0;
    }

    // Dead-space penalty: small unusable leftovers.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.30;
            // Harmonic bonus if next item leaves another multiple-of-10 residue
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing as stream progresses (fewer future chances to amortize).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + 20.0 * (1.0 - progress);
        // If many open bins already fit the item, opening new is worse.
        score += fitting_bins_count as f64 * 3.0;
        // Large items relative to capacity favor a fresh bin slightly.
        let frac = item_size as f64 / cap;
        if frac > 0.6 {
            score -= 8.0 * (frac - 0.6);
        }
    } else {
        // Prefer tighter existing bins: scale by fullness fraction.
        let used_frac = 1.0 - bin_residual as f64 / cap;
        score -= used_frac * 15.0;
        // Prefer bins whose residual deviates from mean in the tighter direction.
        score -= (mean_residual - bin_residual as f64) * 0.15;
        // Mild crowding penalty: too many open bins favors consolidation.
        if open_bins_count > 8 {
            score -= (open_bins_count as f64 - 8.0) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Items 1..=100: gaps smaller than the minimum plausible item are dead space.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit: ideal closure
    } else if post_residual <= 10 {
        // small unusable gap: strongly penalize (waste nearly the whole gap)
        score += (11 - post_residual) as f64 * 12.0;
    } else if post_residual <= 20 {
        // medium-small gap: moderate penalty, still hard to fill
        score += (21 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits relative to capacity
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine if the current item fills it well,
        // or if no existing bin fits decently.
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else {
            // Only prefer a new bin when every fitting bin would leave a bad gap.
            score += 40.0 + post_residual as f64 * 0.1;
        }
    }

    // --- Last-chance bin: avoid opening new bins unnecessarily ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- Open-bin pressure: discourage bin sprawl ---
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is above the mean (keeps big gaps spread out)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // --- Lookahead: if next item fits exactly in the post-residual, reward ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chainable perfect fit
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Slight late-stream tightening: fewer wasted gaps as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fills (small post_residual) superlinearly.
    score -= 40.0 * (-post / 12.0).exp();

    // Aggressive 2-step lookahead: exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap < 1.0 {
            score -= 25.0; // next item fills this bin exactly
        } else if post >= nxt {
            score -= 15.0 * (-gap / 20.0).exp(); // next item fits well here
        } else {
            score += 6.0 * (1.0 - post / cap); // next item won't fit: mild penalty scaled by dead space
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += 0.5 * (mean_residual - post);

    // Penalize creating unusable slivers (dead space nothing can fill).
    if next_item_size > 0 && post > 0.0 && post < next_item_size as f64 {
        score += 8.0 * (post / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many fitting bins: mild penalty to keep choices competitive but avoid waste.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate: only attractive if it beats a poor fit
    // (large residual left everywhere means current bins are roomy).
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / cap;
        let poor_fit_elsewhere = if next_item_size > 0 && post < next_item_size as f64 { 1.0 } else { 0.0 };
        score = 55.0 - 30.0 * avg_tightness - 20.0 * poor_fit_elsewhere;
        if fitting_bins_count <= 1 {
            score -= 15.0; // no real alternative: opening new bin is fine
        }
        if next_item_size > 0 && next_item_size as f64 > cap * 0.5 && item_size as f64 > cap * 0.5 {
            score -= 10.0; // big items pair badly: fresh bin helps
        }
    }

    // Slight stream-position drift: earlier, be a bit more conservative (keep bins open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that no plausible item can use
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // unusable sliver
        } else {
            let usable = (post_residual as f64 / 10.0).floor() * 10.0;
            score += (post_residual as f64 - usable) * 1.5;
        }
    }

    // Lookahead: reward bins whose leftover can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0).min(4.0);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins with high mean residual: prefer consolidation into fuller bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        let fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score -= fullness * 10.0 * (open_bins_count as f64).ln();
    }

    // Late in stream: be conservative, avoid fragmenting space
    score += progress * (post_residual as f64 * 0.3);

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = score * 0.6 + 12.0 + pressure * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Normalized post-residual in [0,1]
    let r = (post / cap).clamp(0.0, 1.0);

    // Base: prefer low post_residual (tight fits) via non-linear decay
    let mut score = r * r * cap;

    // Smooth penalty for medium dead space (unusable gaps): peaks around r ~ 0.35
    let gap = (r - 0.35) * (r - 0.35);
    score += 12.0 * gap * cap * r * (1.0 - r);

    // Reward tight fits more strongly as stream progresses (consolidation pressure)
    score -= (1.0 - r) * (1.0 - r) * (1.0 + 3.0 * progress) * 10.0;

    // Lookahead coupling: penalize if post_residual can't hold next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let deficit = ((nxt - post) / cap).max(0.0);
        let deficit = deficit.min(1.0);
        // Penalty grows smoothly with deficit and with stream progress
        score += deficit * deficit * (6.0 + 10.0 * progress) * (1.0 - r);

        // Bonus if post_residual exactly/nearly accommodates next item (chaining)
        let slack = (post - nxt).abs() / cap;
        score -= (1.0 - slack.min(1.0)) * (1.0 - r) * 4.0 * progress;
    }

    // New-bin candidate: empty bin. Penalize opening unless item is large relative to capacity
    let is_new_bin = (bin_residual == bin_capacity) && (post_residual == bin_capacity);
    if is_new_bin {
        let size_frac = (item / cap).clamp(0.0, 1.0);
        // Penalize opening a new bin; relief grows for big items or late stream
        score += 25.0 * (1.0 - size_frac * size_frac) * (1.0 - 0.5 * progress);
        // If no other bin fits, this is the only option — soften penalty
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Last-chance bin bonus: avoid wasting this bin's usability
        if fitting_bins_count == 1 {
            score -= 8.0 * (1.0 - r);
        }
        // Mild preference for bins below mean residual (balance load smoothly)
        score += 0.05 * (post - mean_residual).abs();
    }

    // Small smooth jitter-free regularization with open bins count
    score += (open_bins_count as f64).ln().max(0.0) * 0.1 * r;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-band classification (capacity fractions)
    let item_class = (item_size * 4) / bin_capacity; // 0..4 integer division threshold
    let next_class = (next_item_size * 4) / bin_capacity;

    // Reward tight fits: exact or near-exact fill
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 25.0;
    }

    // Penalize dead space in small residue classes: post_residual in (0,10) excluded,
    // but mid-band dead zones (post_residual just above half) are hard to fill
    let half = bin_capacity / 2;
    if post_residual > half && post_residual < (3 * bin_capacity) / 4 {
        score += 8.0;
    }

    // Modulo arithmetic on post_residual: residues that pair well with common item bands
    let r = post_residual % 10;
    if r == 0 {
        score -= 5.0; // round residue, easy to fill exactly later
    } else if r >= 7 {
        score += 3.0; // awkward residue
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= bin_capacity / 10 {
        score -= 15.0;
    }
    // Penalize if next item is large and this placement leaves a residue class mismatch
    if next_item_size > 0 && next_item_size > post_residual && post_residual > bin_capacity / 4 {
        score += 6.0;
    }
    // Harmonic class match: same quarter-band item tends to stack
    if next_item_size > 0 && item_class == next_class && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor or many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual > bin_capacity as u32 / 2 && item_size < bin_capacity / 4;
        if poor_fit || (open_bins_count as f64) > 4.0 + 6.0 * progress {
            score -= 12.0; // prefer fresh bin
        } else {
            score += 30.0; // prefer existing bins
        }
    }

    // Mild pressure toward consolidating into few bins
    score += (open_bins_count as f64) * 0.05;
    // Slight deviation from mean residual: prefer bins near the mean (balance)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than large residuals (dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Large residuals are reusable; slight reward relative to raw value.
        score -= 2.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // next item would not fit here -> dead space risk
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when existing residuals are small and fragmented.
    let open_pressure = open_bins_count as f64 * 0.6;
    score += open_pressure;

    // New-bin candidate: make it attractive only when open bins are fragmented
    // (mean residual small) or when the current fit is bad.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual < 25.0 {
            score -= 20.0;
        } else if fragmentation > 30.0 {
            score -= 5.0;
        } else {
            score += 25.0; // prefer filling existing bins when they are roomy
        }
    }

    // Mild stream-progression adjustment: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Slight nudge toward bins with residual close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual and next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        // perfect chain match strongly rewarded
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement: reward proportionally to tightness
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item would NOT fit: penalize dead space left behind
            score += gap * 0.35;
        }
        // bonus if next item fits exactly into post_residual region scaled by progress
        score -= 6.0 * (1.0 - progress) * (1.0 - gap / (bin_capacity as f64));
    } else {
        // last item: prefer tightest fit
        score += post_residual as f64 * 0.5;
    }

    // Prefer bins whose residual is below mean (dense bins), penalize sparse ones
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let default_penalty = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs().min(80.0)
        } else {
            0.0
        };
        score += 18.0 + progress * 10.0 + default_penalty * 0.2;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Mild reward for very tight fits overall
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / cap;
    score += 18.0 * tightness * tightness;

    // Penalize exact-perfect fits less: zero post residual is great.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 20.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 6.0;
        } else {
            // dead space for next item: penalize proportionally
            score += 0.25 * (nxt - post_residual as f64).min(40.0);
        }
    }

    // Penalize opening a new bin mildly; escalate with number of open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    // Compare bin residual to mean residual: favor bins with above-average fill
    // (below-average residual), keeping emptier bins available for big items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Early in the stream, be more liberal with new bins (exploration);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Small preference for bins whose residual is a "nice" multiple region
    // (residuals <= 10 are nearly dead; avoid creating them unless exact fit).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual
    let t = progress;
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks at mid-residuals
    score -= 40.0 * poly * (0.5 + t); // reward keeping mid-size residuals early->late

    // Penalize large dead residuals more strongly as stream progresses.
    score += t * prn * prn * 30.0;

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - slack * slack);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins relative to mean residual.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev;

    // New-bin candidate: mild penalty so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: 8 equal capacity fractions.
    let frac = post / cap;
    let class = (frac * 8.0).floor() as i32;

    // Reward tight fits; dead space under 20 is nearly unusable.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 20 {
        score += 40.0;
    } else {
        score -= (class as f64) * 6.0;
    }

    // Reward residual exactly matching next item (perfect lookahead fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // Modulo-10 harmony: residuals that are multiples of 10 are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Prefer filling bins when many are open (reduce bin count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64) * (2.0 + 4.0 * progress);

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 60.0 - 30.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" — heavily penalize them.
    let min_future = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_future {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is ideal
    } else {
        // Non-linear reward for small-but-usable residuals (tight fits).
        let frac = post_residual as f64 / bin_capacity as f64;
        score -= (1.0 - frac) * 18.0;
    }

    // If the next item fits exactly into the would-be post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 14.0 + 10.0 * chain_tightness;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: mild penalty for stranding space.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 30.0 + 0.5 * (post_residual as f64);
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.15;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — finishing it off is good.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.4;
    } else {
        score += (-dev) * 0.1;
    }

    // New-bin candidate: keep it moderately attractive only when the fit
    // into open bins would be very loose (large leftover dead space).
    if bin_residual == bin_capacity {
        score += 12.0
            - if post_residual > 40.0 { 15.0 } else { 0.0 }
            + open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack * 0.05);
        } else {
            // next item can't fit here; penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-mean residual is good (tight packing), above-mean is wasteful
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus expected future utility
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 1000.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 50.0;
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Mild preference for filling fuller bins (small residual before placement)
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight penalty per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tight * tight;

    // Penalize large wasted capacity fraction of this bin.
    let fill = (item_size as f64) / (bin_residual as f64);
    score -= 6.0 * fill * fill;

    // Last-chance bin: strongly favor using it if it fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: reward leaving residual that can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.15 * gap;
            if gap < 5.0 {
                score -= 3.0; // near-perfect chain
            }
        } else {
            score += 2.5; // next item won't fit here
        }
    } else {
        score -= 4.0; // last item: just minimize bins, prefer any open bin
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into open bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize late, penalize less early.
        score += 12.0 * t + 0.3 * (open_bins_count as f64);
        if item_size >= 60 { score -= 5.0; } // big items fine in fresh bins
    } else {
        score -= 4.0 * t;
    }

    // Global residual pressure: if mean residual is large, prefer filling existing slack.
    score -= 0.05 * mean_residual * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: squared residual (non-linear penalty on dead space)
    let mut score = (pr * pr) / cap;

    // Smooth coupling: residual penalty grows with stream progress
    score *= 1.0 + progress * fit_frac * 2.0;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - fit_frac;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Lookahead: penalize if post_residual cannot host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // reward leaving room exactly usable by next item
            let gap = pr - ni;
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist, more so late in stream
    if bin_residual == bin_capacity {
        let mean_fit = if mean_residual >= item_size as f64 { 1.0 } else { 0.0 };
        score += 12.0 + 10.0 * progress - 6.0 * mean_fit;
        // new bin attractive only if mean residual is small (bins nearly full)
        score += mean_residual * 0.3;
    }

    // Mild congestion penalty to balance bin count growth
    score += (open_bins_count as f64).ln() * fit_frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "dead space" classes (small, hard-to-fill remainders) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: perfect fit — huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Integer-division thresholds on post_residual: leftover buckets.
    let bucket = post_residual / 10; // 0..=10 classes
    match bucket {
        0 => score += 30.0,            // 1..9: nearly dead space
        1 => score += 18.0,            // 10..19
        2 => score += 10.0,            // 20..29
        3 | 4 => score += 2.0,         // 30..49 usable
        5 | 6 => score -= 4.0,         // 50..69 sweet spot
        7 | 8 => score -= 2.0,         // 70..89
        _ => {}                        // near-empty bin
    }

    // Modulo arithmetic: remainders that pair well with common item sizes.
    // Items in 1..100; leftovers divisible by small granularities are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can follow: strong reward, scaled by how snugly it fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 10.0 + 15.0 * snug;
            // Harmonic bonus when next item exactly fills the leftover.
            if next_item_size == post_residual {
                score -= 40.0;
            }
            // Modulo harmony: next item leaves another round leftover.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: penalize by the gap size class.
            let gap = next_item_size - post_residual;
            score += (gap / 10) as f64 * 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // open bins have bad fits. Empty-bin residual equals capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as stream progresses
        // (late in the stream, consolidation matters more).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.5 * cap + 20.0 * (1.0 - progress);
        // If next item is huge, an empty bin is attractive for it.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> favor
    // consolidating into existing bins.
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);
    }

    // Tie-break: prefer tighter residual among equals.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // nearly dead space, wasted
        } else if post_residual < 25 {
            score += 25.0; // risky small gap
        } else if post_residual < 40 {
            score += 5.0;
        }
    } else {
        score -= 30.0; // perfect fit, zero waste
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin pressure: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin count pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins or huge item.
        score += 10.0 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 20.0;
        }
        // If next item is small, a fresh bin is more useful.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    } else {
        // Favor bins whose residual is close to mean residual (balanced load),
        // but only mildly, since dead-space rule dominates.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead: if the resulting residual exactly fits the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If post_residual is smaller than the minimum plausible item (1), it's dead.
    if post_residual > 0 && post_residual < 3 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base normalization: prefer bins whose residual is small relative to capacity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward when the next item fits into post_residual (chain placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match is ideal: post_residual == next_item_size leaves zero dead space after step k+1.
            let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 30.0 * (1.0 - gap); // stronger reward for tighter chained fit
            score -= 10.0 * gap.min(1.0); // still reward any chainable fit mildly
        } else {
            // Next item cannot chain here; penalize proportionally to wasted lookahead potential,
            // but less if post_residual is tiny (nearly full bin is still good).
            let leftover = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * leftover;
        }
    } else {
        // Last item: just minimize post_residual.
        score += 0.0;
    }

    // Reward filling a bin close to capacity (small post_residual already does this via base score).

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin unless current bins are poor fits.
    // New-bin candidate: bin_residual == bin_capacity and item_size <= capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: discourage unless open bins have large residuals anyway.
        score += 25.0;
        // If mean residual across open bins is small (bins are well-filled), opening a new
        // bin is more acceptable; reduce the penalty.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 20.0;
        // Late in the stream, avoid proliferating bins with tiny leftover demand.
        if progress > 0.85 {
            score += 10.0 * (progress - 0.85) / 0.15;
        }
        // If many bins fit the item, definitely prefer an existing bin.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    } else {
        // Existing bin: mild preference when its residual is below mean (it's "tighter").
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Slight penalty for dead space that is too small for typical future items
    // (unusable slivers below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Tie-break with a tiny deterministic jitter based on bin_residual to break ties stably.
    score += (bin_residual as f64 % 7.0) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor minimal post_residual (best-fit core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 4.0 * (1.0 - leftover as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual becomes dead space for the lookahead item: penalize small useless slivers.
        if post_residual < next_item_size {
            score += 0.08 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.5;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fitting
    // bins exist and mean residual is large.
    if bin_residual == bin_capacity {
        let mut penalty = 5.0;
        if fitting_bins_count > 0 {
            penalty += 2.0 + mean_residual / bin_capacity as f64 * 3.0;
        }
        // Early in stream, allow more bins; late in stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty *= 1.0 + 0.5 * progress;
        // If item is huge, a fresh bin is natural.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            penalty *= 0.4;
        }
        score += penalty;
    } else {
        // Prefer bins whose residual is close to item (avoid fragmenting large residuals
        // when a smaller residual bin suffices).
        let waste = bin_residual as f64 - item_size as f64;
        score += 0.05 * waste;
        // Slight preference to fill bins with below-mean residual (balance load).
        if (bin_residual as f64) < mean_residual {
            score -= 0.3;
        }
    }

    // Mild consolidation pressure as many bins accumulate.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nxt = next_item_size as f64 / cap;

    // Smooth waste penalty: strongly penalize large leftover space, mildly reward tight fits.
    let mut score = 2.0 * x + 3.0 * x * x;

    // Tight-fit reward: cubic coupling that dips near zero post-residual.
    score -= 1.5 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Stream-progress coupling: as stream progresses, tolerate larger residuals less
    // (prefer compacting into few bins), via smooth polynomial interaction.
    score += (0.5 + 1.5 * t) * x * (1.0 - t);

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize residuals slightly below next item size (dead space).
    if nxt > 0.0 {
        let fits_next = if x >= nxt { 1.0 } else { 0.0 };
        score -= 0.8 * fits_next * (x - nxt).min(0.5);
        score += 0.6 * (1.0 - fits_next) * (nxt - x).max(0.0) / cap.max(1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins fit.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.15 * fitting_bins_count as f64;
    } else {
        // Slight preference for bins already below mean residual (balance loads).
        score += 0.3 * (post - mean_residual) / cap;
    }

    // Smooth open-bin pressure: more open bins -> prefer packing into existing ones.
    score -= 0.02 * open_bins_count as f64 * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: leftovers in [1..10] are near-perfect,
    // mid-range leftovers (30..50) are the most reusable, large leftovers are wasteful.
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => 0.0,
        1..=10 => 120.0,
        11..=20 => 40.0,
        21..=30 => 10.0,
        31..=50 => 55.0,
        51..=70 => 0.0,
        _ => -25.0,
    };
    score -= class_bonus;

    // Modulo-arithmetic coupling: leftover that is a multiple of common item sizes
    // (10, 20, 25, 50) remains splittable later -> reward.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize burning residual on this item.
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0 + 0.5 * (bin_capacity - pr) as f64;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all open
    // bins; make the empty-bin score sit above decent fits but below bad fits.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.15 * open_bins_count as f64 + 0.1 * mean_residual;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - pr as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean residual (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - pr * 4.0; // tiny gaps are worst
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else if post_residual < 20 {
        score += 20.0 - pr * 0.5;
    }

    // Reward filling a bin almost completely.
    if post_residual <= 15 {
        score -= 12.0;
    }

    // Pressure from number of open bins: discourage opening/spreading when many bins open.
    let bin_pressure = open_bins_count as f64;
    score += bin_pressure * 0.35;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + bin_pressure * 0.5;
        // If lookahead item is large, opening fresh bin may be OK.
        if next_item_size > 60 && post_residual as u32 == bin_capacity {
            score -= 15.0;
        }
    }

    // Lookahead coupling: reward leaving a gap that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr - nx).abs() < 1.0 {
            score -= 18.0; // next item fits exactly
        } else if pr >= nx && pr - nx < 10.0 {
            score -= 8.0;
        } else if pr > 0.0 && pr < nx {
            score += 10.0; // next item won't fit here; gap likely dead
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - pr) * 0.4;

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 - progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item size (perfect 2-item fill), scaled by lookahead availability.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong bonus; near match: proportional small bonus.
        let match_bonus = if gap == 0.0 {
            60.0
        } else {
            (30.0 / gap).min(30.0)
        };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= match_bonus * (0.7 + 0.3 * progress);

        // Penalize residual that neither fits the next item nor is small:
        // dead space that the lookahead cannot use.
        if (post_residual as i64 - next_item_size as i64) < 0 && post_residual > 0 {
            score += 12.0;
        }
    }

    // Relative-to-mean term: prefer bins whose post residual sits near the
    // open-bin mean residual (keeps the fleet balanced and predictable).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded (high mean residual => few good fits) or no
    // bin fits. Make the empty-bin score track the fleet's tightness.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 * 0.9 - tightness * 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin perfectly accommodates the next item too.
            score -= 8.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 + (10 - post_residual) as f64 * 10.0;
    } else {
        // Penalize residual relative to mean residual across open bins.
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    } else {
        // Mild penalty when many bins compete, encouraging spread.
        score += fitting_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 60.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Time horizon: early in stream, prefer opening new bins when fit is poor
    // (keep flexibility); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = (1.0 - progress) * 40.0 - progress * 20.0;

    // New empty bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by stream progress and current load.
        score = 100.0 + new_bin_bias + open_bins_count as f64 * 3.0;
        // If no open bin fits well, opening a new bin is more attractive.
        if post_residual == 0 {
            score -= 400.0; // item exactly fills a fresh bin
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 30.0;
        }
    } else {
        // Slight preference to keep number of open bins bounded.
        score += open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress) - 20.0 * progress * x * (1.0 - x);

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * progress * (1.0 - x) * (1.0 - x);

    // Penalize dead space (small unusable residuals) with smooth cubic term
    if pr > 0.0 {
        let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
        score += 25.0 * dead * dead * dead;
    }

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let fit_margin = pr - next_item_size as f64;
        if fit_margin >= 0.0 {
            let tightness = 1.0 - fit_margin / cap;
            score -= 18.0 * progress * tightness * tightness;
        } else {
            score += 8.0 * (-fit_margin / cap);
        }
    }

    // Last-chance bonus: smooth reward when few fitting bins exist
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight aversion unless residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 10.0 * (mean_residual / cap - 0.5).abs().min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let class = pr / 10; // integer-division threshold class (0..10)
    // Dead-space penalty grows superlinearly for small unusable residuals.
    if pr < 10 {
        score += 60.0 - (pr as f64) * 5.0;
    } else if pr < 20 {
        score += 15.0;
    } else if pr < 30 {
        score += 5.0;
    }

    // Reward residuals that are harmonic with common item sizes (multiples of 10/25).
    let harmonic = (pr % 10 == 0) as f64 * 6.0 + (pr % 25 == 0) as f64 * 4.0;
    score -= harmonic;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.2;
        } else {
            // next item cannot use this residual; penalize large wasted space mildly
            score += (pr as f64) * 0.05;
        }
    }

    // Prefer filling already-open bins over opening new ones, more so late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, less when few bins are open or item is large.
        score += 25.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
    } else {
        score -= 8.0;
    }

    // Tightness reward: closer fit (small post_residual relative to capacity) favored.
    score += (pr as f64 / cap) * 20.0;

    // Mean-residual coupling: avoid bins deviating wildly from mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that could still host a typical item (usable gap).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Last-chance pressure: strongly prefer the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: penalize mildly so it is only chosen when fits are terrible,
    // but relax penalty late in the stream when consolidation is less useful.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        // If no existing bin fits well (large dead space elsewhere), opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else {
        // Penalize residual squared: dead space grows quadratically bad.
        score += (post_residual as f64) * (post_residual as f64) / 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post residual, this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward tight chain, penalize leftover slack.
            let slack_after_next = post_residual - next_item_size;
            score -= 80.0;
            score += slack_after_next as f64 * 0.8;
        } else {
            // Next item won't fit here: penalize slightly, scaled by overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.5;
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // "tight" bins; using them consolidates waste.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.6;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin mildly by default.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But late in the stream, keeping bins closed is fine; relax penalty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    // Slight preference to fill older/denser bin populations.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits: fraction of capacity used by this placement
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill * fill;
    }

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // reward leaving room for the lookahead item
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Penalize tiny residuals (wasted slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, prefer filling existing ones over opening new
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins already open or late in stream
        score += 20.0 * openness + 25.0 * t;
        // but if mean residual is small (existing bins nearly full), new bin is fine
        score -= 0.15 * mean_residual;
    } else {
        score -= 10.0 * openness;
    }

    // Prefer bins whose residual deviates below mean (consolidate emptier space)
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Early in stream: be conservative, keep bins balanced
    score += 10.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);
    score += poly * cap * 0.5;

    // Penalize dead space more as stream progresses
    score += (norm_pr - 0.2).abs() * 10.0 * (0.5 + progress);

    // Reward tight fits
    score -= (item_size as f64 / cap) * 8.0 * (1.0 - progress * 0.5);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr).max(0.0) * 0.1;
    }

    // New-bin candidate: penalize opening new bins mildly, more early on
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0;
    }

    // Mean residual coupling
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // coarse buckets (perfect fit / small / medium / large dead space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fits are gold: reward heavily.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty grows super-linearly for unusable leftovers.
        // Anything <= 10 is still "usable" for the smallest items (size 1..100 range).
        if post_residual <= 10 {
            score -= 8.0;
        } else if post_residual > bin_capacity / 2 {
            // Huge leftover is fine (bin stays flexible) — mild reward.
            score -= 4.0;
        } else {
            // Mid-range leftovers are the classic waste zone.
            let mid = (post_residual as f64 / cap).powi(2);
            score += 10.0 * mid;
        }
    }

    // Harmonic class via integer division thresholds on post_residual:
    // leftover in [1..k] classes; k = item_size gives modular coupling.
    let class = post_residual / item_size.max(1);
    score += match class {
        0 => -6.0,           // leftover smaller than the item: tight packing
        1 => 0.0,            // exactly one more copy could fit: neutral
        2 => 3.0,            // room for 2 more: mildly wasteful
        _ => 6.0,            // very loose bin: deprioritize filling it now
    };

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chaining: next item can slot in here.
            let chain_fit = (next_item_size as f64) / (post_residual as f64);
            score -= 12.0 * chain_fit;
        } else {
            // Post-residual becomes dead space relative to the known next item.
            score += 5.0;
        }
        // Harmonic pairing: next item complements this one to near capacity.
        let pair_sum = item_size + next_item_size;
        if pair_sum == bin_capacity {
            score -= 15.0;
        } else if pair_sum > bin_capacity {
            score += 2.0;
        }
    } else {
        // Last item: prefer closing bins cleanly.
        score += pr * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // or the item cannot snugly fit anywhere.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            0.0
        };
        // If mean residual is large, open bins are roomy: penalize new bin.
        score += 30.0 * fragmentation;
        // But if the item is huge and would leave a tiny awkward leftover in
        // every bin, a fresh bin may win: compare with what a snug fit gives.
        let snug = (item_size as f64) / cap;
        if snug > 0.8 {
            score -= 10.0;
        }
        // Early in the stream, having few bins is fine; later, avoid sprawl.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild preference to keep bin count low: reward bins that are already open
    // proportionally to how full they are.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * fill;

    // Small tie-breaker noise via deterministic harmonic of step index.
    let tie = ((step_index % 7) as f64) * 0.01;
    score += tie;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Heavy penalty for small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward placements that still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Pressure from many open bins: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.8;
    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // New-bin candidate: penalize unless all open bins would leave bad fits.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }
    // Prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * lookahead_gap;
        // Perfect two-item fit: post_residual == next_item_size is ideal
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits tightly after this placement
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 15.0; // dead space for the lookahead item
        }
    }

    // Tight fit reward relative to capacity
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Penalize residual relative to mean residual (fragmentation)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening a bin that will pair with the next item
        }
    }

    // Early in stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.83;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic waste penalty on post-residual, amplified over stream progress.
    let mut score = post * (1.0 + 1.5 * progress) + 0.006 * post * post;

    // Reward tight fits (small post_residual relative to item size).
    let item = item_size as f64;
    score -= 2.0 * (item / cap) * (1.0 - post / cap) * cap * 0.5;

    // Dead-space trap: post_residual too small for the smallest plausible item.
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Lookahead: bonus if next item can use the post-residual, penalty otherwise.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        if nxt <= post {
            score -= 0.35 * (post - nxt);
        } else {
            score += 0.25 * (nxt - post).min(cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 0.02 * (open_bins_count as f64) * ((post - mean_residual).abs() / cap);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits / divisible residuals are valuable
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect, dead space small
    } else if post_residual % 10 == 0 {
        score -= 12.0; // harmonic class: residual aligns with capacity fraction
    } else if post_residual < item_size {
        score -= 4.0; // residual too small for typical items anyway
    } else {
        score += 8.0; // mid-size residual is awkward
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / (bin_capacity / 4);
    score -= q as f64 * 3.0;

    // Lookahead coupling: does this placement leave room for next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0; // chains two items
            if post_residual == next_item_size {
                score -= 20.0; // perfect lookahead fit
            }
        } else if post_residual > 0 && post_residual < next_item_size / 2 {
            score += 5.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 10.0 + open_f * 2.0;
        if fitting_bins_count > 0 && post_residual >= bin_capacity - item_size {
            // only penalize more if an open bin fits well
            score += 15.0;
        }
        // early stream: allow more bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 8.0;
        }
    }

    // Spread pressure: prefer bins below mean residual (fill emptier bins first)
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum possible
    // future item size (1..100 unknown, assume small threshold) are dead.
    // Penalize gaps that are small but nonzero much more heavily than
    // near-zero gaps (perfect fit) or large gaps (still usable).
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 10.0 {
            // tiny sliver: unusable dead space
            score += 60.0 * (11.0 - pr);
        } else if pr < 25.0 {
            // awkward gap: most items (10..80 typical) won't fit
            score += 25.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Reward bins whose residual tightly matches the item (wasted-space ratio)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, spreading is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    score += pressure * pr * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a decent fit (high mean
    // wasted potential) or when the item would leave a bad gap everywhere.
    if bin_residual == bin_capacity {
        let best_possible_gap = mean_residual - item_size as f64;
        let open_bins_attractive = if best_possible_gap > 0.0 && best_possible_gap <= 10.0 { 1.0 } else { 0.0 };
        // base score for a fresh bin: post_residual = capacity - item
        // subtract enough to beat ugly placements, add to lose to good ones
        score += 20.0 * open_bins_attractive;
        score -= 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open new bin
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (fill the
    // emptier-relative bins less, keep balanced residuals usable).
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // penalize leaving a residual just below next item size (wasted sliver)
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 6.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to keep spread of load balanced
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Encourage filling bins with high residual relative to mean (balance)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: baseline near capacity residual
    if bin_residual == bin_capacity {
        // Prefer new bin when few good options; cheaper early, costlier late
        let openness = (open_bins_count as f64 + 1.0).ln();
        score = (bin_capacity as f64) * (0.85 + 0.15 * t) - 10.0 / openness;
        // If current item nearly fills a fresh bin, favor opening it
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
        // If no open bin fits, new bin is the only real option
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: squared post-residual penalizes dead space
    // increasingly as the stream progresses.
    let dead = pr / cap;
    score += dead * dead * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / cap;
    score -= tightness * (1.0 - dead) * cap * 0.6;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.8;
    }

    // Lookahead coupling: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - pr / cap) * nxt * 0.4;
        } else {
            score += (nxt - pr) * 0.5 * (0.5 + progress);
        }
    }

    // Prefer filling bins when many bins are open; penalize spreading when mean residual is high.
    score += 0.3 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are messy.
    if bin_residual == bin_capacity {
        score += cap * 0.15 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // harmonic divisors are more reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit is ideal
    } else {
        // reward residuals that fall into "usable" harmonic classes
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr <= 10 { score += 8.0; }          // tiny dead space
        else if pr <= 20 { score += 4.0; }
        // dead-space penalty grows quadratically for unusable slivers
        if pr < 10 { score += (10 - pr) as f64 * 1.5; }
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 12.0;
        } else if next_item_size > pr {
            // next item cannot go here anyway; slight penalty for wasting large residual
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer tightest bins: reward small bin_residual relative to item.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate: make it moderately unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
        // many open bins with slack -> prefer reusing
        score += (open_bins_count as f64).min(10.0) * 0.8;
    }

    // Slight preference for bins below mean residual (keeps balance).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let fit_ratio = item_size as f64 / bin_residual as f64; // 1.0 = perfect fill
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small unusable residuals (dead space below minimum item size).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Aggressive 2-step lookahead: strongly reward a bin whose post_residual
    // exactly matches the next item's size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // perfect chaining: bin fully consumed next step
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how much of post_residual it consumes
            let chain_ratio = next_item_size as f64 / post_residual as f64;
            score -= 35.0 * chain_ratio * chain_ratio;
        } else {
            // next item won't fit here: penalize if post_residual is awkwardly large
            // relative to mean residual (bin keeps hoarding space that fits nothing next)
            score += 8.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        }
    } else {
        // Last item: just minimize waste, reward full consumption.
        score -= 20.0 * fit_ratio;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average behind is good (compact packing).
    score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is large
    // or no good compact fit exists; discourage wasteful opening otherwise.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened for large items.
        score += 18.0 - 0.15 * item_size as f64;
        // If next item is small, a fresh bin is flexible.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
    }

    // Slight late-stream preference for filling existing bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if the bin was actually used well.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving a large awkward remainder.
            score += 0.15 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64)).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (fill the emptier bins first
    // when residuals are large, keep tight bins tight).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more conservative about fragmenting bins;
    // late in the stream, just fill anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fit_ratio;

    // Many open bins: encourage consolidating into existing bins rather than spreading out.
    if open_bins_count > 4 {
        score += 0.8 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: make opening a new bin costly unless this is a poor fit everywhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the item is huge relative to capacity, a fresh bin may be fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // Late in the stream, avoid opening bins for small items.
        if progress > 0.8 && item_size < 40 {
            score += 30.0;
        }
    }

    // Mild preference for bins that are already more than half full.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smoothly coupled with post_residual.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness of the fit: fraction of the bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity.max(1) as f64;

    // Post-residual normalized; small residuals are valuable (tight fits).
    let pr_norm = post_residual as f64 / bin_capacity.max(1) as f64;

    // Reward tight fits more strongly as the stream progresses (smooth coupling).
    score -= tightness * (1.0 + 3.0 * progress) * 20.0;

    // Penalize small-but-unusable residuals with a smooth quadratic bowl
    // centered where residual could still fit a mid-size future item.
    let dead = pr_norm * (1.0 - pr_norm);
    score -= 10.0 * dead;

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // smooth quadratic overlap term instead of a hard threshold.
    if next_item_size > 0 {
        let fits = (post_residual as i64 - next_item_size as i64).max(0) as f64
            / bin_capacity.max(1) as f64;
        score -= 15.0 * (1.0 - fits) * (1.0 - fits) * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty smoothly as the item gets large and progress advances.
    if bin_residual == bin_capacity {
        let relax = tightness * (0.5 + 0.5 * progress);
        score += 40.0 - 35.0 * relax;
    } else {
        // Slight preference for already-open bins, scaled by open count
        // to encourage consolidation when many bins are open.
        score -= 2.0 + (open_bins_count as f64).ln().max(0.0);
    }

    // Mild pull toward bins whose residual is close to the mean residual
    // (keeps residual distribution balanced, smooth quadratic coupling).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity.max(1) as f64;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual 0) heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space classes: residuals that are hard to fill (small odd leftovers)
        // penalized via modulo structure on capacity.
        let r = post_residual;
        let class = r % 10; // decade residue class
        if r < 10 {
            score += 12.0 + class as f64; // tiny dead space is worst
        } else if r < 20 {
            score += 6.0 + (class as f64) * 0.4;
        } else if r < 40 {
            score += 2.0;
        } else {
            score -= 1.0; // large residual still reusable
        }

        // Reward residuals that are exact integer-division thresholds of capacity
        // (e.g., 100/2=50, 100/4=25, 100/5=20, 100/10=10) — these are "harmonic" slots.
        if r == 50 || r == 25 || r == 20 || r == 10 || r == 40 || r == 33 {
            score -= 5.0;
        }

        // Lookahead coupling: if next item exactly fits the post residual, big reward.
        if next_item_size > 0 {
            if next_item_size == r {
                score -= 30.0;
            } else if next_item_size < r {
                // next fits: reward proportional to tightness
                let tight = 1.0 - (r - next_item_size) as f64 / cap;
                score -= 8.0 * tight;
            } else {
                // next item won't fit here: mild penalty scaled by how much it misses
                score += ((next_item_size - r) as f64) * 0.05;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    // or when the stream is late (wasted capacity at the end matters less, but
    // spreading items early is good).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 8.0 + 10.0 * (1.0 - progress);
        // If the item is small, a fresh bin wastes capacity; if huge, less so.
        score += base + (item_size as f64) * 0.1;
        // Many open bins with low mean residual -> avoid adding another.
        score += (open_bins_count as f64).min(20.0) * 0.5 * (1.0 - mean_residual / cap);
    } else {
        // Prefer bins with tighter residuals (best-fit flavor) among open bins.
        score += (mean_residual - bin_residual as f64) * 0.05;
        // Mild preference to consolidate into fewer bins when many are open.
        score -= (open_bins_count as f64) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100, assume >=10-ish).
    let min_item = 10u32.min(item_size.max(1));
    if post_residual > 0 && post_residual < min_item {
        score += 60.0 + (min_item - post_residual) as f64 * 4.0;
    }
    // Non-linear penalty on tiny-but-not-zero gaps (wasted capacity).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / (pr + 1.0)).min(40.0) * 0.5;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Lookahead coupling: reward if next item can use the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual as f64 - next_item_size as f64).min(30.0) * 0.3;
        } else if post_residual > 0 {
            score += 12.0; // gap likely dead for next item
        }
    }

    // Last-chance bin pressure: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    // If multiple bins fit, penalize slightly to prefer consolidation elsewhere.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to open bins count and mean residual.
        score += 30.0 + open_bins_count as f64 * 6.0 + mean_residual * 0.4;
        // Early stream: new bins are cheap; late stream: expensive.
        score += progress * 40.0;
    } else {
        // Reward using existing bins more when many are open.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // Favor bins below mean residual (poorer bins absorb waste).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual that is too small to be useful later
    // (items are 1..100, but small leftovers < next item are wasteful).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.15 * (post_residual - next_item_size).min(30) as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize spreading across many open bins when plenty of alternatives exist.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when
    // the item fits poorly everywhere else or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let tight_fit = (bin_capacity - item_size) <= 10;
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count == 1 && mean_residual < item_size as f64 * 1.2);
        if tight_fit || poor_alternatives || open_bins_count == 0 {
            score -= 15.0;
        } else {
            // Prefer reusing an existing bin with decent fit.
            score += 12.0 + 0.1 * item_size as f64;
        }
    }

    // Global fragmentation pressure: many open bins with large mean residual
    // -> prefer consolidating into bins with residual close to mean.
    let mean_diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_diff;

    // Time horizon: early in the stream, be more conservative with new bins;
    // late in the stream, allow slight relaxation since bins won't amortize.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score += 0.5;
    }

    // Mild preference for filling larger-residual bins when item is large.
    if item_size > 50 && bin_residual > item_size {
        score -= 0.05 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear penalty on residual waste, amplified by stream progress.
    let x = pr / cap;
    score += 6.0 * x * x * (0.5 + progress) * cap * 0.1;

    // Reward tight fits: cubic decay of waste.
    score -= 4.0 * (1.0 - x).powi(3);

    // Penalize residual that is too small for the lookahead item (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap * cap;
        } else {
            // Reward leaving room exactly for the next item (smooth bump).
            let fit = (pr - nx) / cap;
            score -= 3.0 * (-fit * 10.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * x;

    // New-bin candidate: neutral baseline; only chosen if open bins score worse.
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress;
    }

    // Coupling with mean residual: prefer bins near the mean (balanced packing).
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (multiples of common item sizes 10..80).
    let usable: [u32; 8] = [10, 20, 25, 40, 50, 60, 75, 80];
    let mut class_bonus = 0.0;
    for &u in &usable {
        if post_residual >= u {
            // residual is at least this class size -> still usable
            class_bonus += (u as f64) * 0.05;
        }
        if post_residual % u == 0 && post_residual > 0 {
            // exact harmonic match: residual can be perfectly consumed
            class_bonus -= 6.0;
        }
    }
    score -= class_bonus;

    // Dead-space penalty: tiny unusable remainders
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Tight fit reward: item occupies most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.75 {
        score -= 20.0 * (fill_ratio - 0.75);
    }

    // Lookahead coupling: penalize if next item no longer fits post_residual
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0;
        } else if post_residual == next_item_size {
            score -= 30.0; // chain of perfect fits
        } else {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fill_ratio < 0.4;
        if poor_fit && open_bins_count > 0 {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Mild pressure toward consolidating into few bins
    score += 0.05 * open_bins_count as f64;
    // Prefer bins whose residual deviates favorably from mean residual
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small gaps that few future items can fill) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post residual,
    // this placement is ideal — reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item cannot fit in the resulting gap but could fit elsewhere,
    // mild penalty for blocking useful space.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Open-bin pressure: discourage spawning many bins; when many bins are
    // open, favor consolidating into existing ones (penalize the new-bin call
    // which has bin_residual == bin_capacity and large post_residual anyway).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mild normalization: prefer bins whose residual is close to the mean
    // (keeps the pool balanced and flexible).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Late in the stream, tighten up: waste matters more as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect match for next item: strong reward
            if slack == 0.0 {
                score -= 60.0;
            } else if slack <= 10.0 {
                score -= 30.0;
            } else {
                // partial reward scaled by how well next item uses leftover
                score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // next item cannot fit: penalize proportional to wasted lookahead opportunity
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins whose post_residual is below average
    // (concentrate fullness, keep other bins roomier)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Avoid leaving tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize fresh bin mildly, more
    // when many bins are already open (fragmentation cost).
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // but if next item is large and current item is small, a fresh bin
        // preserves space: reduce penalty
        if next_item_size >= 50 && item_size <= 30 {
            score -= 25.0;
        }
    }

    // Slight late-stream consolidation bias
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving residuals that are too small to be useful for typical items,
    // but perfect fits (post_residual == 0) are great.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 8.0; // dead space: too small for any item (min size 1..10 range safety)
        } else {
            // residual usable if next item fits
            if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
                score -= 10.0; // lookahead: this bin can serve the next item too
            } else if next_item_size > 0 {
                // residual wasted relative to next item: penalize proportionally
                let waste = 1.0 - (post_residual as f64 / next_item_size as f64);
                score += 4.0 * waste.max(0.0);
            }
        }
    } else {
        score -= 6.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with decent fits.
        score += 20.0;
        // If many bins can fit, opening a new one is wasteful.
        score += 6.0 * (fitting_bins_count as f64).min(5.0);
        // If mean residual across open bins is large, existing bins have room: penalize new bin.
        score += 0.15 * mean_residual;
        // Early in stream, opening bins is cheap-ish; late in stream prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // Large item nearly filling a fresh bin: allow new bin more readily.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 25.0;
        }
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 5.0;
        }
    } else {
        // Prefer bins with less residual among fitting bins (best-fit bias).
        score += 0.05 * bin_residual as f64;
        // Slight preference to fill bins with many siblings already open (reduce spread).
        score += 0.3 * (open_bins_count as f64).sqrt();
    }

    // Global packing pressure: when many bins are open, discourage fragmentation.
    if open_bins_count > 8 {
        score += 0.02 * (open_bins_count as f64 - 8.0);
    }

    // Coupling: reward when post_residual aligns with mean residual (harmonious residuals).
    let diff = (post_residual as f64 - mean_residual).abs();
    score -= 2.0 * (-diff / 25.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer small post residual (tight fit), with non-linear sharpening.
    let mut score = pr as f64;

    // Smooth polynomial coupling: dead space near mid-range is penalized extra,
    // very small residuals are rewarded super-linearly.
    let mid = (x - 0.5) * (x - 0.5); // distance from half-full squared
    score += 30.0 * mid * x;

    // Tight-fit reward, stronger as stream progresses.
    let tight = (1.0 - x) * (1.0 - x) * (1.0 - x);
    score -= 20.0 * tight * (0.5 + progress);

    // Lookahead coupling: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compat = (x - nx) * (x - nx);
        score += 15.0 * compat; // penalize post-residual far from next item size
        score -= 10.0 * (1.0 - compat) * nx * (0.3 + progress);
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (0.5 + 0.5 * progress);
    }

    // Many open bins: mild penalty to consolidate into fuller bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * x;

    // Prefer bins whose residual deviates from mean residual (fill outliers first).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * dev * (1.0 - x);

    // New-bin candidate: make it unattractive unless residual truly unusable.
    if bin_residual == bin_capacity {
        score += 25.0 + 50.0 * progress - 30.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small integers
    // classify "good" leftover spaces that commonly pair with future items.
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Reward residuals that fall into "harmonic" classes: multiples of 5, 10, 20, 25
    // (common item-size alignment classes). Penalize awkward residues.
    let class_bonus = |r: u32| -> f64 {
        if r == 0 { return 12.0; }                 // perfect fit
        if r % 10 == 0 { return 6.0; }
        if r % 20 == 0 { return 4.5; }
        if r % 25 == 0 { return 4.0; }
        if r % 5 == 0 { return 2.5; }
        -1.5                                       // awkward residue
    };
    score -= class_bonus(post_residual);

    // Integer-division thresholds: post_residual / item_size ratio classes
    let ratio = post_residual as f64 / (item_size as f64).max(1.0);
    if ratio >= 1.0 {
        score -= 3.0; // leftover can host another item of same size
    } else if ratio >= 0.5 {
        score -= 1.0;
    } else if post_residual > 0 {
        score += 2.0; // tiny dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            // fractional fit quality: how much of post_residual the next item uses
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * fill;
            // harmonic alignment between next item and residual
            if post_residual % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // next item cannot use this bin
        }
    } else {
        // last item: prefer zero residual strongly
        score -= 8.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor (fragmented). Compare against mean residual.
    if bin_residual == bin_capacity {
        // base cost of opening a fresh bin
        score += 45.0;
        // if existing bins are fragmented (high mean residual but none fit well),
        // opening new bin becomes relatively attractive
        let frag = mean_residual / cap;
        score -= 30.0 * frag * frag;
        // late in stream, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // many open bins already: discourage spreading
        score += 2.0 * open_bins_count as f64;
    } else {
        // reward tightening residual toward mean (keeps bins balanced)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // prefer filling fuller bins (small residual) when many bins open
        score += 0.1 * open_bins_count as f64 * (bin_residual as f64 / cap);
    }

    // Modulo-3/7 harmonic texture on post_residual for fine-grained tie-breaking
    let h = (pr % 3) as f64 + (pr % 7) as f64;
    score += 0.3 * h - 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum item
    // (size 1..10) are wasted capacity -> heavy penalty scaled by how dead they are.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement
    // (keeps chains of feasible fills), penalize when it cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into fresh
    // capacity; a brand-new empty bin candidate gets a penalty that grows with
    // open_bins_count, unless the fit into existing bins is terrible.
    if bin_residual == bin_capacity {
        let pressure = 10.0 + open_bins_count as f64 * 4.0;
        let poor_fit = if post_residual < 10 { 0.0 } else { 1.0 };
        score += pressure * (0.5 + 0.5 * poor_fit);
    }

    // Mild tightness bonus: closer fill ratio is better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Late in the stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chains that leave little usable-but-fragmenting slack.
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leaving slack that no typical item (>=10) can use.
            if slack > 0.0 && slack < 10.0 {
                score += 15.0;
            }
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by
            // how much usable space is stranded.
            score += 0.15 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins that are already relatively
    // full (below-mean residual) to consolidate waste.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: encourage closing them out by filling tight fits.
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Early in the stream, allow spreading items across bins (keeps residual
    // flexibility); later, force consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * post_residual as f64 / bin_capacity as f64;

    // New-bin candidate: only attractive when current item creates a nearly
    // exact fill or nothing fits well elsewhere; otherwise penalize opening.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residual that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    } else {
        // Last item: only tightness matters, close bins greedily.
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * fit_ratio;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early in the stream or when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // If mean residual across open bins is high, opening a new bin is fine.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins that are already small-residual (consolidation).
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Global balance: penalize placing into bins far above the mean residual
    // to keep residual distribution balanced unless it's a tight fit.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev.signum() * (dev.abs() / bin_capacity as f64);

    // Time horizon: later in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Non-linear penalty on residual relative to capacity, amplified by stream progress
    let pr_norm = pr / cap;
    score += pr_norm * pr_norm * cap * (0.3 + 0.7 * progress);

    // Reward tight fits: subtract for small post_residual
    score -= (1.0 - pr_norm).powi(2) * item_size as f64 * 0.5;

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            score -= (pr - next) * 0.4 + 2.0;
        } else {
            score += (next - pr) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Penalize placements far below mean residual (poor relative fit)
    score += ((pr - mean_residual) / cap).abs() * 4.0 * progress;

    // Mild pressure against spreading across many bins early
    score += open_bins_count as f64 * 0.15 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers
    let post = post_residual;
    let tier = post / 10;              // integer division tier (0..10)
    let residue = post % 10;           // harmonic residue class

    // Reward small residues (tight fit) within a tier: dead space is residue + tier slack
    score += residue as f64 * 0.7;

    // Non-linear tier penalty: mid tiers (wasted half-empty bins) are worst
    let t = tier as f64;
    score += (t - 5.0) * (t - 5.0) * 0.9;

    // Perfect fits (post_residual == 0) get strong reward
    if post == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size < post {
            let nxt_post = post - next_item_size;
            // harmonic class match: next placement leaves small residue too
            score += (nxt_post % 10) as f64 * 0.4;
            score -= 10.0;
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += (next_item_size - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 0.0 } else { 40.0 };
        score += desperation + mean_residual * 0.1;
        // opening fresh bins early in the stream is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
    }

    // Slight preference for denser packing when many bins are open
    score += (open_bins_count as f64).ln() * (post as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than moderate leftovers.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Pressure from number of open bins: prefer consolidation when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward when next item nearly fills the leftover.
        if post_residual - next_item_size <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Leftover too small for the next item: penalize more as dead space.
        score += 6.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0;
        let min_gap = (bin_capacity - item_size) as f64;
        // Opening a new bin is cheap when it would leave a small residual itself
        // or when many bins are open; otherwise discourage.
        score += 30.0 + pressure - (min_gap / 10.0).min(8.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: overwhelmingly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // residual big enough to host next item: mild reward, tighter is better
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize small unusable leftovers
            let waste = post_residual as f64;
            score += 30.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is tight relative to the mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = poor_fit * 0.5 + 150.0 * (1.0 - scarcity) - 250.0 * scarcity;
        // early in stream, opening fresh bins is cheap; later, avoid bin proliferation
        score += 100.0 * progress;
    }

    // Mild preference for filling already-open bins as the stream progresses.
    score += 0.1 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chained packing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // penalize creating residual that nothing can use soon
            let dead = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.15 * dead;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with below-mean residual (keeps larger residuals for harder items)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream: keep flexibility, penalize committing large bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer filling existing ones rather than spreading
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: base cost so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // open a new bin early if the item is huge and would leave a tiny awkward residual
        if item_size >= 90 && post_residual > 0 {
            score -= 20.0;
        }
        // near end of stream, opening new bins is cheaper
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: tight fit reward (small post_residual strongly preferred, non-linear)
    let mut score = pr * pr / cap + pr * 0.35;

    // Reward high fill ratio with smooth coupling
    score -= (fit_ratio * fit_ratio) * 30.0 * (1.0 - progress * 0.3);

    // Penalize post_residual that no future small item (next_item_size) can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item could fit into this residual: reward proportional to reuse
            score -= (nx / (nx + 20.0)) * 25.0;
        } else {
            // dead space relative to lookahead item
            score += ((nx - pr) / cap) * 40.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly early, more strongly if decent fits exist
    if bin_residual == bin_capacity {
        let avg_fit_quality = 1.0 - (pr / cap);
        score += 35.0 + 45.0 * (1.0 - progress) + 20.0 * (fitting_bins_count as f64).min(5.0) / 5.0;
        // but if mean residual of open bins is small (fragmented), opening new bin is fine
        score -= (mean_residual / cap).min(1.0) * 30.0;
        let _ = avg_fit_quality;
    }

    // Late stream: consolidate more aggressively, penalize spreading residual
    score += progress * (pr / cap) * 25.0;

    // Coupling: large open_bins_count favors filling existing bins tightly
    score -= (open_bins_count as f64).ln().max(0.0) * (fit_ratio * 8.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets and reward leftovers that form "harmonic"
    // classes (common item sizes likely to fill them later).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Harmonic class via integer division thresholds on post_residual.
    // Classes: (0..=10], (10..=20], (20..=35], (35..=60], (60..=100]
    let class_bonus: f64 = if post_residual == 0 {
        -40.0 // perfect fit, best possible
    } else if post_residual <= 10 {
        -25.0 // near-perfect: dead space is tiny
    } else if post_residual <= 20 {
        -10.0 // still good
    } else if post_residual <= 35 {
        0.0
    } else if post_residual <= 60 {
        8.0 // half-empty bin, moderate waste
    } else {
        15.0 // mostly empty bin, wasteful placement
    };
    score += class_bonus;

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes are more likely to be filled exactly later.
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut harmonic_hits = 0u32;
    for &h in harmonics.iter() {
        if post_residual >= h && post_residual % h == 0 {
            harmonic_hits += 1;
        }
    }
    score -= 4.0 * harmonic_hits as f64;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual; penalize proportionally
            // to how much of the residual is wasted for the lookahead.
            let waste = (next_item_size - post_residual).min(bin_capacity) as f64;
            score += 5.0 * (waste / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the tightest fit (already encoded
        // via post_residual), but add a small diversity penalty to break
        // ties toward bins with below-average residual (fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to capacity or open bins are numerous and fragmented.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = open_bins_count as f64 * mean_residual / (open_bins_count.max(1) as f64 * cap);
        // Prefer new bin when item is big and existing bins are fragmented.
        let new_bin_bias = 30.0 * item_frac + 20.0 * fragmentation - 15.0 * (1.0 - progress);
        // Base cost of opening a new bin, offset by the bias.
        score += 45.0 - new_bin_bias;
    }

    // Mild global pressure: as the stream progresses, tighten fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to hold the smallest item (1) are pure waste.
    // Penalize small but nonzero post_residuals that are unlikely to be usable by
    // typical future items (heuristic threshold around 10, the historical min size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets penalized here
    // relative to existing bins via post_residual already; add explicit pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // But allow opening when no bin fits well (post_residual of new bin = capacity - item)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Mild reward for filling existing bins, scaled by mean residual imbalance.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (waste minimization, superlinear).
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 60.0 * tight * tight;

    // Penalize residual that is too small to be useful for future items
    // (dead space below the minimum plausible item size).
    let dead = (post_residual as f64).min(20.0);
    score += 1.5 * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: slight penalty to preserve choice diversity,
    // prefer placing into bins where alternatives are scarce.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: reward bins whose post-residual pairs with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = (post_residual as f64 - nxt).abs();
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // post-residual can't hold next item; mild penalty scaled by closeness
            let miss = nxt - post_residual as f64;
            score += 0.4 * miss;
        }
    }

    // Global state: if mean residual across open bins is large, encourage
    // consolidating into existing bins rather than opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // New bin baseline: its post_residual is cap - item_size, already high.
        // Penalize opening new bins when existing capacity is abundant.
        let abundance = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 18.0 * abundance;
        // Early in stream, new bins are cheap; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Reward using bins with residual close to the mean (balance load).
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 6.0 * dev;
    }

    // Slight preference for filling nearly-full bins to close them out.
    if post_residual <= 10 && !new_bin {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: quadratic dead-space penalty on post-residual
    let mut score = post * (1.0 + post_norm * post_norm);

    // Non-linear stream-progress coupling: late in stream, tighten packing more
    let tighten = 1.0 + 2.0 * progress * progress;
    score *= tighten;

    // Reward tight fits (small post_residual relative to item) with smooth term
    score -= 3.0 * item_norm * (1.0 - post_norm).powi(2);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev.abs();

    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead: reward if next item fits post-residual, penalize near-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 2.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 1.0 * ((nxt - post) / cap);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a bin unless item is large
    if bin_residual == bin_capacity {
        score += 4.0 - 3.0 * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor(); // 0..8 harmonic class

    // Reward near-perfect fits: small post_residual heavily discounted.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Dead-space penalty: leftover that cannot plausibly hold the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Modulo coupling: post_residual and next_item_size sharing a common divisor
    // (harmonic resonance) means the next item can tile the leftover well.
    if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
        score -= 80.0;
    }
    if next_item_size > 0 && post_residual > 0 {
        let g = gcd(post_residual, next_item_size);
        if g > 1 {
            score -= 10.0 * g as f64;
        }
    }

    // Integer-division threshold on residual class: mid-range leftovers (class 3-5)
    // are the most reusable; very small classes are already tight, large classes are empty-like.
    match class as u32 {
        0 => score -= 150.0,
        1 => score -= 90.0,
        2 => score -= 40.0,
        3 | 4 => score -= 15.0,
        5 => score += 10.0,
        6 => score += 30.0,
        _ => {}
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: prefer keeping it closed early (many open bins with slack),
    // prefer opening it when current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 * mean_residual < item_size as f64 * 2.0;
        let poor_fit = post_residual > 0 && next_item_size > 0 && post_residual < next_item_size;
        if crowded || poor_fit || fitting_bins_count == 0 {
            score -= 120.0 + 200.0 * progress;
        } else {
            score += 150.0 + 50.0 * mean_residual * 0.1;
        }
    }

    // Slight pressure toward filling bins with high residual when many bins are open.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Time-varying tightness: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.2;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical items
    // (1..=9) are almost unusable; punish them super-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += (10.0 - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (small but nonzero residual is great,
    // zero residual is a perfect close).
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated
    // by how bad the alternatives look (high mean residual => open bins
    // are fragmented, opening new bin is more acceptable).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5 - mean_residual * 0.2;
        // If the next item fits exactly in the fresh bin's leftover after
        // this placement, opening a new bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    } else {
        // Penalize using an open bin when the leftover would be unusable
        // for the lookahead item while a fresh bin could serve it.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
        // Open-bin pressure: with many open bins, prefer consolidating.
        score += open_bins_count as f64 * 0.3;
    }

    // Slight early-stream preference for keeping bins tight so structure
    // forms early; relax as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact match of post_residual with next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect match: next item exactly fills the residual -> big reward.
        if diff < 0.5 {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if nxt <= post {
            // Next item fits: reward proportionally to how snugly it fits.
            let snug = 1.0 - diff / bin_capacity as f64;
            score -= 25.0 * snug * snug;
        } else {
            // Next item cannot use this residual: penalize dead space that
            // the lookahead item cannot consume.
            score += 8.0 + 0.15 * (nxt - post).min(100.0);
        }
        // Coupling: if the residual left is small but nonzero and unusable next,
        // extra penalty scaled by how "wasted" it is relative to capacity.
        if nxt > post && post > 0 && post < 10 {
            score += 12.0 * (10.0 - post as f64);
        }
    } else {
        // Last item: just prefer minimal leftover.
        score += 0.5 * post_residual as f64;
    }

    // --- Relative-to-mean residual shaping ---
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = post_f / mean_residual;
        // Post-residual far below the mean => tight fit => reward.
        if rel < 1.0 {
            score -= 15.0 * (1.0 - rel);
        } else {
            // Post-residual above the mean => loose fit => penalty.
            score += 10.0 * (rel - 1.0).min(2.0);
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling: brand-new empty bin ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive early (many items remain to fill it),
        // cheap late. Penalize new bin when open bins give a decent fit.
        let scarcity = 1.0 - progress;
        score += 30.0 * scarcity + 0.3 * open_bins_count as f64;
        // But if the item is huge relative to capacity, a fresh bin is fine.
        score -= 0.2 * item_size as f64;
        // If no other bin truly fits well (post_residual large everywhere),
        // mean_residual check: if mean residual is small, open bins are cramped,
        // so a new bin is attractive -> reduce the penalty.
        if mean_residual > 0.0 && mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
    }

    // --- Tight-fit bonus: reward placements that nearly fill the bin ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * (fill_ratio - 0.8) / 0.2;
    }

    // --- Discourage creating tiny unusable slivers (< 10) ---
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual nonlinearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize large post_residual that is unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // small leftover nearly full bin is great
    }
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // awkward mid-range dead space
    }

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
    }
    // If next item is large and would need almost a fresh bin, prefer keeping
    // residual large in open bins
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.1 * (next_item_size as f64 - post_residual as f64);
    }

    // Global state: many open bins -> discourage spreading, favor filling
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 4.0 * crowding.ln().max(0.0);

    // Time horizon: early in stream, opening bins is cheap; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * (1.0 - tightness);

    // New-bin candidate handling: neutral-ish default, penalize slightly so
    // only genuinely bad fits in existing bins trigger opening a new bin
    if bin_residual == bin_capacity {
        score += 55.0 + 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 50.0; // nothing else fits well, allow opening
        }
    }

    // Mild penalty when this bin's residual is far from mean residual (outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit), with non-linear squashing
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are tolerated; late, waste is penalized quadratically.
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * (0.5 + progress);
    score -= 20.0 * norm_post * (1.0 - progress) * (1.0 - progress);

    // Reward using bins that are already open (avoid bin proliferation)
    if bin_residual != bin_capacity {
        score -= 15.0 + 0.05 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize, more so when many bins already fit the item
        score += 10.0 + 8.0 * (fitting_bins_count as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving residual compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.3 * gap * (1.0 - progress);
        if post >= nxt {
            score -= 5.0 * (1.0 - post / cap);
        }
    }

    // Mean-residual coupling: penalize deviating strongly from average fill state
    score += 0.2 * (post - mean_residual).abs();

    // Small smooth tie-breaker based on fill fraction
    score += 3.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward small, "usable" leftovers
    // (divisible into common item sizes), penalize awkward dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else {
        // modulo arithmetic: residuals matching common item classes (10,20,25,50)
        let m = pr % 10;
        if m == 0 {
            score -= 12.0;
        } else if m == 5 {
            score -= 6.0;
        } else {
            score += m as f64; // awkward leftover penalty
        }
        if pr % 25 == 0 {
            score -= 8.0;
        }
        if pr % 20 == 0 {
            score -= 5.0;
        }
    }

    // Tightness of the current fit: fraction of bin consumed
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else {
            // next item would leave another awkward remainder
            let nm = (pr as u32).min(next_item_size);
            score += 0.05 * (next_item_size - nm) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (score already reflects that)
        score += 2.0 * (fitting_bins_count as f64).min(10.0);
    }

    // New-bin candidate: only attractive when open bins are very full on average
    // or the item is huge relative to the mean residual.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        if pressure > 0.8 || open_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 35.0 + 10.0 * (1.0 - pressure);
        }
    }

    // Slight drift: later in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps more harshly (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins are open
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the post residual, penalize slightly
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // New-bin candidate: neutral baseline with mild penalty so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if item is large relative to capacity, opening fresh may be fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Progression: slightly more open to new bins early, tighter late
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress;
    }

    // Prefer bins with residuals close to the mean (keeps bin pool homogeneous)
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // 2-step lookahead: reward residuals that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.5 * slack;
        if slack == 0.0 {
            score -= 50.0; // exact 2-item chain
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to wasted lookahead potential
        let miss = (next_item_size - post_residual) as f64;
        score += 0.4 * miss.min(50.0);
    }

    // Penalize leaving dead space relative to mean residual
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - pr);
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when it enables a clean pair with the next item
    if bin_residual == bin_capacity {
        score = cap * 0.9;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        if fitting_bins_count == 1 {
            score += 100.0; // strongly discourage abandoning the sole fitting bin
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for filling fuller bins
    score -= 0.1 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that no future item can plausibly fill
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // wasted sliver below the next item's size
        } else if post_residual >= next_item_size {
            score -= 3.0; // bin stays usable for the lookahead item
        }
    } else {
        // Last item: prefer minimal leftover
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when
    // open bins exist and mean residual could still absorb the item
    if bin_residual == bin_capacity {
        score += 15.0;
        if open_bins_count > 0 {
            let mean_fit = mean_residual - item_size as f64;
            if mean_fit >= 0.0 {
                score += 6.0 + mean_fit * 0.05;
            }
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Slight reward for filling bins that are already mostly full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 2.0 * fill_ratio;

    // Mild penalty for leaving residual close to typical small-item sizes
    // (encourages exact-feeling pairings)
    if post_residual >= 1 && post_residual <= 20 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64 / cap); // fill fraction after placement

    // Reward high fill ratio with smooth non-linear coupling to stream progress:
    // later in the stream, tight packing matters more.
    score -= fill * fill * (1.0 + 2.0 * progress) * 40.0;

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    let dead = (post_residual as f64 / cap).powi(3);
    score += dead * 60.0;

    // Lookahead coupling: reward if the next item fits the post residual,
    // penalize otherwise (smoothly scaled by how far off it is).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post_residual as f64;
        if gap <= 0.0 {
            score -= 25.0 * (1.0 - progress);
        } else {
            score += (gap / cap) * 45.0 * (1.0 - gap / cap);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Mild penalty when many bins are open already; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 8.0;

    // Pull toward bins with below-average residual (denser bins) via smooth term.
    score += (post_residual as f64 - mean_residual).abs().sqrt() * 3.0;

    // New-bin candidate: neutral-ish base but penalize slightly so it only wins
    // when all open bins score badly (poor fits).
    if bin_residual == bin_capacity {
        score += 35.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: classify by integer division into capacity fractions.
    // Classes: [0..12], [13..25], [26..50], [51..75], [76..100] — small residuals are "good dead space".
    let class = post_residual / 13; // integer division harmonic bucket 0..7
    let class_penalty = match class {
        0 => -30.0,                    // near-perfect fit
        1 => -12.0,                    // still very usable
        2 => 0.0,
        3 => 10.0,
        _ => 22.0,                     // large unusable gap
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals that are "harmonic" with common
    // item sizes (multiples of 5 and 10) are more likely to be filled later.
    let m10 = post_residual % 10;
    let m5 = post_residual % 5;
    if post_residual > 0 {
        if m10 == 0 {
            score -= 8.0;              // divisible by 10: matches many item sizes
        } else if m5 == 0 {
            score -= 4.0;
        } else {
            score += (m5 as f64) * 0.8; // awkward remainder, penalize
        }
    }

    // Lookahead coupling: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - nxt as u32) as f64;
            // Perfect or near match with next item is very desirable.
            if slack == 0.0 {
                score -= 25.0;
            } else if slack <= 10.0 {
                score -= 12.0;
            } else {
                score -= 5.0 * (1.0 - slack / cap);
            }
            // Harmonic bonus: next item divides residual evenly (residual % next == 0)
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: the dead space is riskier.
            score += 6.0 + 10.0 * (1.0 - nxt / cap);
        }
    } else {
        // Last item: just minimize waste directly.
        score += post * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (avoid opening a new bin) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual across open bins.
    if bin_residual == bin_capacity {
        // New bin starts with post_residual = cap - item_size; judge by stream position
        // and how much capacity is stranded in existing open bins.
        let stranded = mean_residual * open_bins_count as f64;
        let stranded_frac = stranded / (cap * (open_bins_count.max(1) as f64));
        // Early in stream or with little stranded capacity, new bins are cheap.
        score += 14.0 * (1.0 - progress) - 20.0 * stranded_frac;
        // If the item is small relative to capacity, a fresh bin is fine.
        score += 0.2 * (item_size as f64);
        // But never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 {
            score += 40.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Tie-break: slightly prefer bins whose residual is closest to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        score += 1.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit would be terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 60.0 + pressure - (post_residual as f64);
        if fitting_bins_count == 1 {
            score += 50.0; // never open when a last-chance bin exists
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
        score += 8.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Late-stream tightening: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins below mean residual (consolidating emptier bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: small post_residual is good, super-linear reward.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect-ish fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let nr = post_residual - next_item_size;
            if nr <= 10 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - nr as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit here after placement: penalize wasted space
            // relative to next item size (dead space trap).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual close to
    // item_size (minimal leftover) versus the average open bin.
    let diff = mean_residual - bin_residual as f64;
    score += 0.08 * diff; // favor bins with residual below mean (already well-packed)

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of the
    // bin we skip. Penalize new bins mildly, unless current fit is terrible.
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64; // residual left behind by not using open bins
        score += 30.0 - 0.05 * waste;
        // If no existing bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer compacting into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (bin_capacity as f64) * 0.5;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 {
        let usable = (post_residual >= 10) as f64;
        score -= usable * 20.0;
        if post_residual < 10 {
            score += 30.0; // tiny unusable sliver
        }
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + (next_item_size as f64) * 0.3;
        } else {
            // penalize wasted capacity if next item is close but doesn't fit
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += gap * 1.5;
            }
        }
        // reward bins whose residual matches next item exactly (complementary fit)
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // opening bins is cheaper early, costlier late (consolidation phase)
        let open_cost = 120.0 + 150.0 * progress;
        // if this bin would be a very tight fit for the item, allow opening
        let self_tight = (bin_capacity - item_size) as f64;
        score = open_cost + self_tight * 0.3;
        // if many bins already open, discourage fragmentation
        score += open_bins_count as f64 * 4.0;
        // if mean residual across open bins is large, discourage new bin
        score += mean_residual * 0.5;
        // if next item also fits nicely in a fresh bin alongside this one, mild relief
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Mild preference for filling fuller bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * (10.0 + 30.0 * progress);

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is below mean (fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;
    // smooth non-linear coupling of post_residual with stream progress
    score += 30.0 * pr_norm * pr_norm * (progress * (1.0 - progress) * 4.0);
    score -= 20.0 * (1.0 - pr_norm) * pr_norm * progress;
    // lookahead synergy: reward residual matching next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 25.0 * (-diff * diff * 40.0).exp();
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // penalize opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 20.0 * (1.0 - progress);
    }
    score += 0.05 * (mean_residual - pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25 create
    // "usable size classes" for typical item sizes (1..100).
    let r = post_residual;
    let res10 = (r % 10) as f64;
    let res25 = (r % 25) as f64;

    // Penalize residual that is not a "clean" class: near multiples of 10/25 are good.
    score += (5.0 - res10).abs() * 0.4;
    score += (12.5 - res25).abs() * 0.3;

    // Integer-division thresholds: residual in [0..=5] is perfect waste,
    // residual in [1..=9] is dead space unless next item is tiny.
    if r > 0 && r <= 9 {
        if next_item_size > 0 && next_item_size <= r {
            score -= 6.0; // next item exactly fills the dead space
        } else {
            score += 12.0; // dead space penalty
        }
    }

    // Large leftover (>= half capacity) is flexible; reward mildly.
    if r >= bin_capacity / 2 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= r {
        score -= 8.0 + (r - next_item_size) as f64 * 0.15;
    } else if next_item_size > r {
        // next item won't fit here: small penalty proportional to overflow
        score += ((next_item_size - r).min(20)) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling nearly-full bins (tight fit reward).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 6.0;

    // Early in the stream, allow opening bins more freely; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // If this bin is far below mean residual, it's a poor consolidation target.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += dev * 0.25;
        }
    } else {
        // New empty bin candidate: penalize unless nothing else fits well.
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Opening a new bin early is cheap; late is expensive.
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= ~10) are "dead space" -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward: subtract proportional to how tightly the item fills the bin.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // If next item fits exactly in the post residual, reward strongly (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize the brand-new empty bin implicitly via count).
    let progress = step_index as f64 / (total_items.max(1)) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin gets a baseline penalty that grows
    // with open bins count, so it only wins when all fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Slight pull toward bins near the mean residual (balance usage).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() <= 5.0 {
            score -= 300.0;
        } else if post_residual as u32 >= next_item_size {
            // leftover can host next item: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare residual against mean residual of open bins
    if open_bins_count > 0 {
        let diff = post_residual as f64 - mean_residual;
        score += 0.5 * diff;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bin is very tight or no good fit exists
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count <= 1 {
            score -= 250.0;
        }
    }

    // Slight preference to fill fuller bins early vs late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 40.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: heavily discourage opening a new bin unless existing
    // fits are very poor (large dead space) or this is a last-chance situation.
    if bin_residual == bin_capacity {
        let dead_space_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Base penalty: strong, but relaxable when open bins are all nearly full
        let mut penalty = 60.0 - 45.0 * dead_space_pressure;
        // Late in the stream, waste matters more; keep new bins costly
        penalty += 10.0 * progress;
        // If this bin is the only fitting option, opening a new bin is cheap
        if fitting_bins_count == 1 {
            penalty -= 30.0;
        }
        // Lookahead: if next item also fits a fresh bin, opening is slightly better
        if next_item_size > 0 && next_item_size <= bin_capacity {
            penalty -= 5.0;
        }
        score += penalty;
        return score;
    }

    // Tight fit reward: quadratic bonus for small post_residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect / near-perfect fills are gold
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize bins that would strand a large next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Waste created relative to what the next item needs
            let waste = post_residual as f64;
            score += 0.3 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Bin-count pressure: with many open bins, prefer consolidating into
    // existing ones; with few open bins, be pickier about which gets used.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count.min(20) as f64 - 4.0).sqrt();
    }

    // Global residual coupling: prefer bins whose residual is below the mean
    // (close them out) when the mean is high; prefer above-mean bins when mean is low.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev * (1.0 - progress);

    // Slight preference for larger residual bins early (keep flexibility),
    // reversed late (close bins down).
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - 2.0 * progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tightness: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= tight * tight * 40.0;

    // Exact fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space that fits next item,
    // penalize leaving dead space that doesn't.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            let waste = pr - nx;
            let w = waste / cap;
            score -= 15.0 * (1.0 - w * w);
        } else {
            let gap = (nx - pr) / cap;
            score += 20.0 * gap * gap;
        }
    }

    // Stream-progress coupling: later in stream, be greedier about tight fits
    // and more reluctant to leave large residuals.
    let progress_boost = t * t * 20.0;
    score -= progress_boost * tight;
    score += (1.0 - t) * (post_residual as f64 / cap) * 10.0;

    // Penalize bins far below mean residual (fragmenting), reward near-mean consolidation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 8.0;

    // Mild penalty when many bins are open: prefer consolidating into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 5.0;

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + (fitting_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes.
    // Perfect fits (class 0) heavily rewarded; tiny dead space (unusable) heavily penalized.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // class = ceil(100 / post_residual)-ish harmonic banding via integer division thresholds
        let class = (bin_capacity / post_residual.max(1)) as f64; // 1 = tiny residual, 5 = large residual
        // Tiny residuals (< smallest plausible next item) are dead space -> penalty grows
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 60.0;
        // Harmonic reward: residual that is a clean divisor class of capacity is more reusable
        score -= class * 8.0;
        // Nonlinear: penalize residuals in awkward band (just below common item sizes)
        let awkward = |r: u32| -> f64 {
            let mut pen = 0.0;
            for k in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
                if r > 0 && r < k && r >= k.saturating_sub(4) {
                    pen += 12.0;
                }
            }
            pen
        };
        score += awkward(post_residual);
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus scaled by how well next item uses the leftover
            let chain_fill = next_item_size as f64 / pr.max(1.0);
            score -= 40.0 + 30.0 * chain_fill;
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere in this bin anyway; residual quality matters less
            score -= 5.0;
        } else {
            // next item fits bin now but not after this placement: mild penalty unless perfect fit
            if post_residual > 0 {
                score += 10.0;
            }
        }
    }

    // Last chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Prefer bins tighter than average (best-fit style) with harmonic scaling
    let tightness = (bin_residual as f64 - item_size as f64) / c;
    score += tightness * 25.0;

    // Mild preference to fill existing bins when many are open
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when current fit is bad (large awkward residual)
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: residual after placement is large
        let fresh_penalty = 35.0 + (mean_residual / c) * 20.0;
        // discount if opening a bin is clearly better (poor fit elsewhere)
        let poor_fit = if post_residual > 0 && post_residual < 15 { 1.0 } else { 0.0 };
        score = score.max(0.0) + fresh_penalty - poor_fit * 30.0;
    }

    // Progress-based micro-tuning: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual - item_size) as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100 unknown distribution) are pure waste.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else {
        // Reward tight fits that keep residual usable.
        score -= 25.0 * (1.0 - (post_residual as f64) / dead_threshold.max(bin_capacity as f64 * 0.25)).clamp(0.0, 1.0);
    }

    // Penalize residuals that cannot fit the lookahead item but could have.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few,
    // opening a new bin is cheap so penalize it mildly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        score += 30.0 + 15.0 * pressure * (1.0 - progress);
    } else {
        score -= 8.0 * pressure.min(4.0);
    }

    // Prefer bins with residual close to mean (balance load) mildly.
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize large dead space.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize bins whose post-residual is small but nonzero (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins tighter than the mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, prefer tighter packing overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.5 * progress);

    // New-bin candidate: mildly penalize so open bins are preferred unless poor fit.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 12.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize leaving residual too small for any plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits into post-residual (chained fit),
    // penalize if post-residual is just barely too small for next item (near-miss waste).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - nr) / bin_capacity as f64);
        } else if post_residual >= nr * 0.7 {
            score += 5.0; // wasted residual that nearly fit the next item
        }
    }

    // Global state coupling: when many bins are open with large mean residual,
    // prefer filling existing bins over opening new ones.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        if bin_residual == bin_capacity {
            // New-bin candidate: penalize more when existing bins are underfilled.
            score += 8.0 * pressure + 2.0 * (open_bins_count as f64).ln().max(0.0);
        } else {
            score -= 3.0 * pressure;
        }
    }

    // Time horizon: early in the stream, be conservative (favor tight packing);
    // late in the stream, slightly favor reusing bins to avoid stragglers.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Mild preference for bins with residual close to item size (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual near zero strongly rewarded via smooth polynomial decay.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * cap * 0.01;

    // Penalize small-but-nonzero dead space quadratically (unusable slivers).
    if post > 0.0 {
        let dead = post / cap;
        score += 8.0 * dead * (1.0 - dead) * cap * 0.05 * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when other bins fit reasonably well.
    if bin_residual == bin_capacity {
        let base_penalty = 6.0 + 10.0 * (1.0 - progress);
        let fit_pressure = if fitting_bins_count > 0 { 0.5 / fitting_bins_count as f64 } else { 0.0 };
        score += base_penalty + 20.0 * fit_pressure;
        // If the next item would fit exactly in a fresh bin, soften penalty.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            score -= 2.0;
        }
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - snug) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving a residual the next item cannot use.
        score += 3.0 * (next_item_size as f64 - post) / cap;
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    score -= 0.05 * (mean_residual - post);

    // Late-stream smoothing: favor filling existing bins as stream ends.
    score *= 1.0 + 0.3 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 8 as "waste classes"
    let r = post_residual % 8;
    let harmonic_penalty = match r {
        0 => -6.0,          // perfectly divisible residual -> very reusable
        1 | 2 => -1.5,      // small usable residues
        3 | 5 | 7 => 2.5,   // prime-ish awkward residues
        4 => 0.0,
        6 => 1.0,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division threshold: tiny unusable post_residual is dead space
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Reward tight fits (post_residual small fraction of capacity)
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - frac) * 8.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize opening new bins normally; discount late in stream or many open bins
        let mut nb = 55.0 - pressure * 30.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += progress * 10.0;
        if open_bins_count == 0 {
            nb = -100.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            nb = -100.0; // no alternative
        }
        score += nb;
    }

    // Mild preference for bins with residual close to item (best-fit flavor)
    let gap = (bin_residual - item_size) as f64;
    score += gap * 0.05;

    // Coupling with mean residual: prefer bins below mean (fill emptier-of-space bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that likely can't fit
    // future items are wasted. Penalize hard if post_residual is a "dead zone".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap unusable by the next item: dead space penalty scales with
            // how small the gap is relative to the next demand.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.5 * dead;
        } else {
            // Gap still usable by next item: reward tight-but-viable fit.
            score -= 1.5 * (next_item_size as f64 - post_residual as f64).abs().min(20.0);
        }
    }

    // Non-linear dead-space cliff: residuals in (0, 10) are nearly unusable
    // for any item (sizes >= 1 but typically >= 10 in classic streams).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a bin should only win when the item fits
    // poorly everywhere else. Make the empty-bin baseline moderately high,
    // relaxed only when the item is large relative to residual capacity.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 0.55 * bin_capacity as f64
            - 20.0 * tightness
            + (fitting_bins_count as f64) * 4.0;
        // Late in the stream, consolidating matters more; new bins cost more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open, discourage further proliferation.
        score += 0.5 * open_bins_count as f64;
        // But if nothing fits well (this bin is the only "fit" being the new one),
        // allow opening when the item would leave a big unusable gap elsewhere.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: mildly prefer filling existing bins when many are open,
    // to avoid leaving many half-empty bins.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer bins whose residual is close to the item (tight fit) with a
    // smooth coupling.
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item packing
        } else if post_residual >= next_item_size {
            let leftover_after_next = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + leftover_after_next / 10.0);
        } else {
            // next item cannot fit in this bin afterwards: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Prefer bins whose residual is tight relative to the mean residual
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mildly discourage opening new bins as the stream progresses
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if no open bin fits well, a new bin is fine
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Penalize large unusable leftovers (waste below smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

