    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
    score += 3.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far from the mean residual get a nudge toward balance.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: early in the stream, be picky (penalize loose fits); late, accept more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (1.0 - fit_ratio);
    score -= progress * 5.0 * fit_ratio;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * desperation + 5.0 * pressure;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // pair-friendly fresh bin
        }
    }

    score
}

