pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of 10 (classic 1D packing classes)
    let post_class = post_residual % 10;
    // Residuals in classes 1..9 (non-multiples of 10) are less reusable; multiples of 10 align
    // with typical item granularities and are worth rewarding.
    if post_residual > 0 {
        if post_class == 0 {
            score -= 6.0; // perfectly harmonic residual
        } else if post_class <= 3 {
            score += 4.0; // small awkward remainder
        } else if post_class >= 7 {
            score += 7.0; // large-but-not-harmonic remainder, hard to fill
        } else {
            score += 2.0;
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Integer-division threshold: can next item exactly fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: lookahead fills exactly
        } else if next_item_size <= post_residual {
            // Fractional coupling: how well does lookahead fit?
            let fit_frac = next_item_size as f64 / post_residual as f64;
            if fit_frac > 0.75 {
                score -= 18.0;
            } else if fit_frac > 0.5 {
                score -= 8.0;
            } else {
                score += 3.0; // lookahead leaves another awkward remainder
            }
        } else {
            // next item cannot fit here; residual is dead unless a later item fits.
            score += 5.0;
            // harmonic check: dead space that is a multiple of 10 is partially recoverable
            if post_class == 0 && post_residual >= 10 {
                score -= 4.0;
            }
        }
    }

    // Penalize wasting a nearly-full bin's tight fit if other bins exist,
    // unless this is the last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0; // last chance: strongly prefer using this bin
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly.
        // Base penalty keeps open-bin usage preferred.
        score += 45.0;
        // If many open bins are cluttered with small residuals, a fresh bin may be better.
        if mean_residual < (item_size as f64) * 0.9 && open_bins_count > 2 {
            score -= 30.0;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large items start fresh bins more willingly (harmonic size classes).
        if item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close in size to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += 10.0 * tightness;
        // Reward bins that are already partly filled (consolidation).
        score -= 5.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Mean-residual coupling: keep open-bin residual distribution balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< smallest plausible item) are heavily penalized.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }

    // Reward tight fits (small but usable post_residual).
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
