    }

    // Prefer bins whose residual is close to the item (minimal waste ratio).
    if bin_residual > 0 {
        let waste_ratio = item_size as f64 / bin_residual as f64;
        score -= waste_ratio * 6.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins;
    // the new-bin candidate (bin_residual == bin_capacity) gets a rising penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + 18.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 2.0 * open_bins_count as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving a gap too small for the next item (dead space for the near future)
        score += 6.0;
    }

    // Bias toward bins with residuals below the mean residual (denser bins first).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
