    // Many fitting bins: mild penalty to keep flexibility, prefer best-fit among them.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            (item_size as f64 / bin_residual.max(1) as f64).min(1.0)
        } else {
