        };
        // Base cost of opening a new bin, discounted late in the stream or when nothing fits well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 * open_pressure * (1.0 - 0.5 * poor_fit_elsewhere);
        new_bin_score += 10.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            new_bin_score -= 8.0;
        }
        score += new_bin_score;
    }

    // Global residual balance: penalize bins far from mean residual to keep bin profile homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Waste-fraction coupling: penalize leaving a large fraction of the bin unused.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_frac * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
