            if nr < 10.0 && nr > 0.0 {
                score += 8.0; // would create a sliver
            }
        } else {
            score += 5.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer tight fits relative to mean residual state.
    score -= 0.5 * (mean_residual - frac * cap).max(0.0);

