    score += 10.0 * progress * frac;

    // New-bin candidate: neutral-ish baseline; only attractive when open bins would waste space.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
