    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item is large relative to capacity or existing bins are too full.
    if bin_residual == bin_capacity {
