        score += 30.0;
        // But if the item is huge or the mean residual is too small to be
        // useful, opening a fresh bin is justified.
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score -= size_pressure * 40.0;
        score += mean_residual * 0.2;
        // Late in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
