        score += 15.0 - pressure * 10.0 + progress * 10.0;
    }

    // deviation from mean residual: prefer bins with residual close to item (avoid fragmentation)
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += dev * 0.15 * (0.5 + progress);

