    // Lookahead coupling: prefer residual that exactly hosts next item.
    if next_item_size > 0 {
        if r == next_item_size { score -= 12.0; }
        else if r >= next_item_size && r - next_item_size < 10 {
            score += 8.0; // would leave dead space for next item
        } else if r >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_item = (bin_capacity as f64) - mean_residual.max(0.0);
        let waste_if_open = (bin_capacity as f64) - item_size as f64;
        score += 15.0 + waste_if_open * 0.3;
        if item_size as f64 > 0.9 * bin_capacity as f64 {
            score -= 18.0; // big item: fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        let _ = progress;
        let _ = avg_item;
    }

    // Mild global pressure: more open bins -> prefer filling existing ones.
    score += 0.2 * open_bins_count as f64;
    // Alignment of item size with capacity fractions.
    if item_size % 25 == 0 { score -= 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below the minimum item size 1,
    // practically: gaps too small for typical items) are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (post_residual near zero but usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize wasted capacity relative to item size: large item filling a bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual likely becomes dead space for the known next item.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open,
    // but allow it when few bins are open (early stream flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and stream progress.
        score += 6.0 + 4.0 * open_bins_count as f64 * (0.5 + progress);
        // If a new bin would keep the item with plenty of room and mean residual is low, mild bonus.
        if mean_residual < 20.0 && fill_ratio < 0.5 {
            score -= 5.0;
        }
    } else {
        // Slight penalty for using a bin whose residual deviates far above mean (fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportional to how tight the chain is.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item does not fit after this placement: penalize dead space left behind,
            // scaled by how badly it misses.
            let miss = nxt - post_residual as f64;
            score += 0.35 * miss;
        }
        // Bonus if this bin's residual could fit both current and next item in sequence.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Tightness reward: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize creating residual far below typical small-item size (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    // or this is a very large item better isolated.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - (bin_residual as f64 - item_size as f64);
        // Default: slightly worse than a decent existing fit.
        score += 12.0;
        // If mean residual of open bins is small (bins are nearly full), opening is fine.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 20.0;
        }
        // Large items: isolate them to avoid fragmenting bins.
        if item_size >= 60 {
            score -= 10.0;
        }
        // If next item is large and would fit better in a fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size > 50 {
            score -= 6.0;
        }
        let _ = mean_gap;
    } else {
        // Favor bins whose residual is below the mean (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        }
    }

    // Early in the stream, allow more bins to open for future flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity && progress < 0.2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 1.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual reusable by next item: mild reward proportional to reusability
            score -= 0.5 * (post_residual as f64 / next_item_size as f64).min(3.0);
        } else {
            // dead space: penalize proportionally to wasted fraction
            let waste = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += 6.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes all current residual capacity
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_resid = mean_residual;
        // penalize opening new bins more when many open bins hold slack
        score += 8.0 + 0.05 * (open_bins_count as f64) + 0.3 * avg_open_resid * (1.0 - progress);
        // but if the item is huge relative to typical residual, opening may be fine
        if item_size as f64 > avg_open_resid {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residuals early (keep small residuals for small items)
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * residual_gap;

    // Mild pressure to consolidate as stream progresses
    score += 0.02 * (open_bins_count as f64) * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0, 1)
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Normalized post residual
    let r = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize mid-range residuals more as stream progresses
    let poly = r * r * (1.0 - r);
    score += 20.0 * poly * (0.5 + progress);

    // Reward tight fits (small post residual) increasingly over time
    score -= (1.0 - r) * (1.0 - r) * 5.0 * (0.5 + progress);

    // Coupling with mean residual: prefer bins close to mean state
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev.abs() * 3.0;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward; else penalize
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in the "usable" band (>= ~1/4 of
    // capacity) can host future items; tiny residuals are dead space.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual < eighth {
        // Dead space: penalize quadratically as residual shrinks.
        let dead = (eighth - post_residual) as f64;
        score += 12.0 + dead * dead / (eighth as f64);
    } else if post_residual <= quarter {
        // Sweet-spot residual: a future item of size 10..=quarter fits well.
        score -= 8.0;
    }

    // Perfect fit classes via modular arithmetic on post_residual.
    if post_residual == 0 {
        score -= 20.0; // exact fill is ideal
    } else if post_residual % 10 == 0 {
        score -= 5.0; // aligns with the coarsest item granularity class
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Lookahead coupling: does this bin's post residual still serve the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can land here: reward tightness of the two-step packing.
            let slack = (post_residual - next_item_size) as f64;
            if slack < eighth as f64 {
                score -= 10.0; // near-perfect two-item chain
            } else {
                score -= 4.0;
            }
        } else if next_item_size > bin_residual {
            // Next item won't fit anywhere like this; residual is final. Penalize
            // proportionally to wasted fraction of capacity.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has no sunk cost; only prefer it
    // when the item is large relative to capacity (few future pairing options)
    // or the stream is early (many items remain to fill fresh bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 6.0                          // base cost of opening a bin
               - 10.0 * size_frac             // large items justify fresh bins
               - 5.0 * (1.0 - progress);      // early stream => future capacity valuable
        if post_residual >= quarter {
            score -= 3.0; // fresh bin keeps a healthy residual for the future
        }
    }

    // Mild pressure against bin sprawl when many bins are already open.
    score += 0.3 * open_bins_count as f64;

    // Slight preference toward bins tighter than the current mean residual
    // (best-fit flavor with mean anchoring).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size 1, but typical items larger)
    // are heavily penalized. Dead space in (0, 10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot use the residual: penalize leftover gap
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: with many open bins, prefer
    // consolidating into existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    score -= open_pressure;

    // New-bin candidate handling: only attractive if no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, reduced when existing bins are crowded
        // (low mean residual) or this bin is the only fitting option.
        let mut new_bin_cost = 55.0;
        if mean_residual < 25.0 {
            new_bin_cost -= 20.0;
        }
        if fitting_bins_count == 0 {
            new_bin_cost -= 60.0;
        }
        // Early in the stream, opening bins is cheaper (more items to come
        // to fill them); later, prefer packing tightly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_cost += progress * 25.0;
        score += new_bin_cost;
    } else {
        // Favor bins whose residual is close to item size (tight fit),
        // scaled by relative tightness.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 15.0;
    }

    // Slight penalty for wasting a large bin on a small item.
    if (item_size as f64) < 0.3 * (bin_residual as f64) && !is_new_bin {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left after hosting the next item too; smaller slack is better.
            let after_next = post_residual - next_item_size;
            score -= 12.0 + 0.6 * (after_next as f64);
        } else {
            // Post residual cannot host next item: penalize unusable dead space,
            // worse when the leftover is tiny and wasted.
            let waste = post_residual as f64;
            score += 6.0 + 0.25 * waste;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score += 0.0;
    }

    // Prefer bins already below mean residual (filling emptier bins first keeps
    // larger residuals available for big future items).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin mildly unless the fit is perfect or lookahead is great.
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size == bin_capacity {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Early in the stream, allow more bins to stay open (flexibility); late in the
    // stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Penalize wasted residual that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement; otherwise penalize leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / 100.0);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it costly unless open bins are very fragmented
    // or this is a poor fit situation.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0
            - 0.5 * open_bins_count as f64
            + 0.2 * fragmentation;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance the pool).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer bins that are already fairly full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tight fits (small post_residual) are strongly preferred;
    // later, we tolerate larger residuals since absolute waste matters less.
    let prn = pr / cap;
    let tightness = 1.0 - prn; // 1.0 = perfect fit
    let coupling = 1.0 + 2.0 * progress * (1.0 - progress); // smooth bump peaking mid-stream
    score -= 30.0 * tightness * tightness * coupling;

    // Penalize residuals too small to be useful for typical items (dead space).
    let dead = if pr < 10.0 { (10.0 - pr) * (10.0 - pr) * 0.05 } else { 0.0 };
    score += dead;

    // Reward bins whose residual after placement still pairs well with lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // Lookahead cannot fit here; mild penalty, stronger late in stream.
        score += 8.0 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * prn;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division thresholds (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual_class = (post_residual * 4) / bin_capacity; // 0..=3 harmonic bucket

    // Reward tight fits strongly: less post residual is better.
    score -= (cap - pr) * 0.35;

    // Penalize dead space that no plausible item (1..=100) can use:
    // post_residual in (0, 10) is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic coupling: reward residuals that are "harmonic" — divisible
    // by common item sizes, i.e. likely to be filled by future items.
    let harmonic_bonus: f64 = if post_residual >= 10 {
        let mut h = 0.0;
        for d in [10u32, 20, 25, 40, 50] {
            if post_residual % d == 0 {
                h += 6.0;
            }
        }
        h
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // partial credit scaled by how well it fits
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty for hoarding space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when all
    // open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // Default: penalize opening a new bin.
        score += 25.0 + 10.0 * (1.0 - fragmentation);
        // But if open bins' mean residual is small (fragmented), allow new bin.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 45.0;
        }
        // Early stream: opening bins is cheap and useful.
        if step_index as f64 / (total_items.max(1) as f64) < 0.15 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // packing into below-average-residual bins consolidates fullness.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Integer-division threshold on post_residual: residuals in the top
    // harmonic class (>75% empty) are wasteful unless bin is new.
    if residual_class >= 3 && bin_residual != bin_capacity {
        score += 8.0;
    }

    // Mild penalty per open bin to encourage closing bins out.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than large ones (dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Pressure from many open bins: discourage spreading items thinly.
    score += open_bins_count as f64 * 1.5;

    // Lookahead coupling: if the next item fits in the resulting residual,
    // reward this placement (keeps bins usable for the future).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how poorly the item would fit into existing bins.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0 + open_bins_count as f64 * 1.0;
        if fitting_bins_count == 1 {
            score += 80.0; // don't open new bin when a last-chance bin exists
        }
        if post_residual == bin_capacity {
            // empty bin always has full residual; make it a true fallback
            score += 10.0;
        }
    }

    // Slight time-based tightening: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space after placement).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness).powi(3);

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or closely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize.
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Prefer bins whose residual is near the mean (keeps bin pool homogeneous).
    score += 0.35 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Discourage opening a new bin when a reasonable fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        if post_residual < 20.0 {
            score += 15.0; // new bin would immediately become near-dead space
        }
    }

    // Late in the stream, favor closing out bins (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 25.0;
    score += coupling;

    // Reward tight fits, more so late in the stream
    score -= item_size as f64 * (0.5 + progress) * 0.5;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Penalize opening new bins when open bins exist with slack
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + mean_residual * 0.3 + 20.0 * (1.0 - progress);
    }

    // Lookahead: favor residual that can host next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 15.0 + next_item_size as f64 * 0.2;
    }

    // Prefer bins with low residual relative to mean (compact usage)
    score += (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean" fractions
    // of capacity (0, 25, 50, 75) since they are re-usable by common item sizes.
    let frac = post_residual % bin_capacity;
    let clean = match frac {
        0 => 40.0,
        25 => 30.0,
        50 => 25.0,
        75 => 20.0,
        _ => {
            // Integer-division threshold: small dead space (<10) is nearly perfect,
            // mid dead space is penalized.
            if post_residual < 10 { 15.0 } else { 0.0 }
        }
    };
    score -= clean;

    // Dead-space penalty: residual too small for the smallest plausible item (1)
    // is fine, but residual below typical item sizes wastes space.
    if post_residual > 0 && post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here regardless; slight penalty for tight fit.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is terrible (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = (bin_capacity as f64) * 0.9;
        // If no existing bin fits well (large mean residual mismatch), allow opening.
        let tight = (mean_residual - item_size as f64).abs();
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if tight > 30.0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins: discourage further opening.
        score += open_bins_count as f64 * 2.0;
    }

    // Tight-fit reward: filling a bin nearly exactly is excellent.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mild preference for bins with residual close to item size (good fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1..=9) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as f64) * 6.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residuals that still allow typical future items (>=10).
    if post_residual >= 10 {
        // Mild bonus for larger usable residual, but not too large (waste).
        score -= 0.05 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when this bin's fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0; // default cost of opening a new bin
        if post_residual as f64 > mean_residual * 0.5 {
            score -= 20.0; // item is small relative to typical leftovers -> new bin ok
        }
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_capacity) {
            score -= 10.0; // next item won't fit here anyway
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual && post_residual < bin_capacity {
        score -= 5.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual is far below mean (already fragmented).
    if (bin_residual as f64) < mean_residual {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: strongly reward minimal post_residual (perfect fit ~ 0).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // 2-step lookahead matching: reward when the next item fits exactly
    // into the post_residual (chains nicely), penalize near-misses.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportionally to how close next item comes to filling bin.
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item does NOT fit: penalize by how much it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss.min(50.0);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual far below the mean wastes usable space.
    if mean_residual > 0.0 {
        let dev = (post_residual as f64 - mean_residual) / mean_residual;
        if dev < 0.0 {
            score += 4.0 * (-dev); // below-average residual = dead space
        } else {
            score -= 2.0 * dev.min(2.0); // above-average residual is fine
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): should only win when no open bin fits
    // well. Penalize it so tight fits into existing bins win, but allow it
    // when post_residual would be very large (poor fit) in existing bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (future items can use them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins are open, discourage opening yet another.
        score += 1.5 * open_bins_count as f64;
    }

    // Slight reward for filling large items into bins (keeps small residual).
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += (1.0 - fit_ratio) * (1.0 - fit_ratio) * 12.0;

    // Penalize dead space: post_residual too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item could use this bin's post_residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score: penalize opening new bins, more so early.
        score += 35.0 + (1.0 - progress) * 30.0;
        // But if open bins are crowded (low mean residual), a new bin is fine.
        score -= (100.0 - mean_residual).max(0.0) * 0.4;
        // Late in stream, opening a new bin is cheaper than fragmenting.
        score -= progress * 20.0;
    }

    // Global congestion: many open bins with large mean residual -> favor
    // filling the emptier bins to reduce bin count.
    if open_bins_count > 2 {
        let spread = bin_residual as f64 - mean_residual;
        score += spread * 0.15;
    }

    // Mild reward for using bins with larger residual (best-fit orientation
    // is already via post_residual, this counterbalances pathological ties).
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let fit = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows superlinearly for large leftover space.
    let mut score = post + 40.0 * norm_post * norm_post;

    // Reward tight fits (fill ratio), smoothed by stream progress so early on
    // we are slightly more tolerant of imperfect fits.
    score -= 60.0 * fit * fit * (0.6 + 0.4 * progress);

    // Non-linear coupling: a large post-residual is more acceptable early in
    // the stream (bins can be topped up later), but heavily penalized late.
    let progress_coupling = norm_post * (1.0 - progress) * (1.0 - progress);
    score -= 35.0 * progress_coupling;

    // Penalize post-residuals that are small-but-unusable relative to the
    // typical item scale (dead space). Smooth via mean residual reference.
    let mean_ref = mean_residual.max(1.0);
    let dead = (mean_ref - post).max(0.0) / mean_ref;
    score += 25.0 * dead * dead;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let nx_fit = nx / post.max(1.0);
            score -= 45.0 * nx_fit * nx_fit;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 10.0 * ((nx - post) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): give it a moderate baseline so it wins
    // only when open bins would leave substantial unusable residue.
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - progress) + 25.0 * norm_post;
        // Late in the stream, opening new bins is relatively cheap since
        // remaining items are few; ease the penalty smoothly.
        score -= 30.0 * progress * progress;
    }

    // Mild pressure against accumulating many open bins early.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod capacity fractions
    let pr = post_residual;
    let q10 = (pr / 10) as i64;      // coarse class
    let q25 = (pr / 25) as i64;      // quarter class
    let r10 = (pr % 10) as i64;      // fine residue
    let r25 = (pr % 25) as i64;

    // Penalize dead space in awkward residue classes (non-reusable slivers)
    if pr > 0 && pr < 10 {
        score += 18.0 - pr as f64; // tiny slivers are nearly dead
    }
    // Reward residuals that land on "harmonic" grid points (multiples of 10/25)
    if r10 == 0 { score -= 6.0; }
    if r25 == 0 { score -= 4.0; }
    // Odd quarter classes slightly penalized (hard to pair with typical sizes)
    if q25 % 2 == 1 { score += 2.5; }

    // Perfect fit strongly rewarded
    if pr == 0 { score -= 30.0; }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        let fit_frac = next_item_size as f64 / pr.max(1) as f64;
        // reward tight follow-up fits
        score -= 14.0 * (1.0 - fit_frac);
        if pr % next_item_size.max(1) == 0 { score -= 8.0; } // clean division
    } else if next_item_size > pr {
        // next item won't fit here: mild penalty proportional to wasted opportunity
        score += 4.0 + (next_item_size as f64 - pr as f64) * 0.15;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current fit is bad or stream early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64 / cap;
        // open new bin if placing here would leave large mean residual divergence
        score = 55.0 - 30.0 * (1.0 - fit_quality) - 10.0 * progress
              + 0.5 * (mean_residual - post_residual as f64).abs()
              + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin keeps room for next item too
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Late-stream tightening: penalize waste more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // even the smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Non-linear penalty on unusable gap: the smaller the leftover relative
    // to capacity, the more it hurts (quadratic coupling).
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    if dead_ratio > 0.0 && dead_ratio < 0.25 {
        score += (0.25 - dead_ratio) * 150.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: leftover likely becomes dead space.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize spreading across many open bins slightly,
    // but reward using existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, reduced when the
        // item is large relative to capacity (better to start fresh for big items).
        score = 100.0 - (item_size as f64) * 0.5;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 5.0;
        }
    } else {
        score += open_bins_count as f64 * 0.2;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter than average).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Stream progression: later in the stream, be slightly more conservative
    // about leaving dead space.
    let progress = step_index as f64 / total_items as f64;
    score += dead_ratio * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits strongly (non-linear decay of post_residual).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly/tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit in the leftover: penalize relative to how wasteful it is.
            let wasted = nxt.min(post_residual as f64);
            score += 10.0 + 0.5 * (nxt - wasted);
        }
    }

    // Compare residual against mean residual across open bins: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins only win on large items / perfect future stacking.
        score += 20.0;
        score -= 30.0 * fill * fill;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // New bin can host this item plus the next one: make it attractive.
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late in the stream, consolidate: mildly favor bins with smaller residuals overall.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item fits only in this bin's current residual — placing item elsewhere wastes chance
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it mildly unattractive by default, but attractive
    // when fit is poor and open bins are plentiful / residuals are high.
    if bin_residual == bin_capacity {
        score += 4.0;
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fit_quality > 0.6 {
            score -= 12.0 * (fit_quality - 0.6) * 5.0; // great fit in fresh bin
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += (mean_residual - item_size as f64) * 0.15; // many bins already roomy
        }
    }

    // Global load balancing: prefer bins with residual near mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, be more willing to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0).min(3.0);

    // Slight preference to fill bins that are already fairly full.
    score -= 0.02 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post_norm = post / cap;

    // Base: penalize leftover space, smoothly amplified by stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: post_residual vs normalized progress (quartic-ish smooth term).
    score += 12.0 * post_norm * post_norm * (1.0 - post_norm) * (1.0 + progress);

    // Reward tight fits (small post_residual) with smooth saturation.
    let tightness = 1.0 - post_norm;
    score -= 6.0 * tightness * tightness * tightness;

    // Dead-space penalty: post_residual too small for any plausible future item.
    let dead = ((20.0 - post) / 20.0).max(0.0);
    score += 15.0 * dead * dead * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits the post residual (smooth interaction).
    if next_item_size > 0 {
        let fits = (post - next_item_size as f64).max(0.0);
        let fit_frac = fits / cap;
        score -= 8.0 * (1.0 - fit_frac) * (1.0 - post_norm).max(0.0);
        // Penalize wasting space when next item cannot fit here.
        let miss = (next_item_size as f64 - post).max(0.0) / cap;
        score += 10.0 * miss * miss;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress * post_norm;

    // New-bin candidate: prefer opening a new bin only when residual is large/unused.
    if bin_residual == bin_capacity {
        score = post + 30.0 * progress + 0.3 * open_bins_count as f64;
        // Discourage opening new bins when a tight fit exists elsewhere.
        if fitting_bins_count > 0 && item_size as f64 / cap > 0.7 {
            score += 40.0;
        }
    }

    // Mean-residual coupling: penalize bins deviating from mean residual (balance).
    score += 2.0 * (post - mean_residual).abs() / cap * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (large enough to plausibly host future items), penalize dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect closure
    } else if pr <= 10 {
        score += 40.0; // tiny unusable sliver = dead space
    } else {
        // modulo classes: residuals congruent to common item sizes are reusable
        let class = pr % 10;
        score -= match class {
            0 => 15.0,
            1 | 2 => 8.0,
            5 => 10.0,
            _ => 0.0,
        };
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0 + 0.5 * next_item_size as f64;
        // harmonic pairing: next item leaves another clean class
        if (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        score += 5.0; // lookahead stranded
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // opening a new bin is penalized early; late stream with fragmented
        // residuals (high mean residual, many bins) may justify it
        score += 60.0 - 40.0 * progress + 20.0 * pressure;
        // if item is huge, a fresh bin is natural
        if item_size >= 80 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to item size (fragmentation avoidance)
    score += 0.3 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 45.0 - 2.5 * post_residual as f64;
    }
    // Medium gaps that only fit tiny items are mildly penalized.
    if post_residual > 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward very tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Perfect-fill bonus for new empty bin handling: prefer existing bins that nearly fill.
    if post_residual as f64 <= (bin_capacity as f64 * 0.05) {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; keep score of new bins higher.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot use the leftover, penalize leaving a mid-size gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 12.0;
    }

    // New-bin candidate calibration: empty bin should look average; adjust with mean residual.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + mean_residual * 0.2 + open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: strongly reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: reward proportionally to how well next item matches.
            score -= (next_item_size as f64) * 0.9;
        } else {
            // Dead space: post_residual can't host next item; penalize more when
            // post_residual is small and unusable (below the typical item range).
            let waste = post_residual as f64;
            score += waste * 0.6;
            if post_residual < 10 {
                score += 25.0; // near-total dead space penalty
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already below-average residual (more filled bins first).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last chance: if this is the ONLY bin that can fit, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins when plenty of bins exist;
    // encourage consolidating items into fewer bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.4;
    }

    // New-bin candidate: empty bin gets a mild handicap so we prefer existing
    // bins unless the fit elsewhere is bad (its base score = capacity, already
    // high; add a small extra penalty but allow lookahead reward to apply).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is reasonable early in the stream or when no good
        // fit exists; soften penalty as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Penalize very small post-residuals that are still > 0 (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Reward perfect fits
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            // penalize leaving residue that next item can't use
            score += 3.0;
            if post_residual < next_item_size && next_item_size - post_residual > post_residual {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin should be penalized unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if no existing bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if many open bins with small residuals, prefer new bin
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
    }

    // Prefer bins with residual close to mean (balance load) mildly
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Prefer larger-residual bins when fit is loose (keep tight bins for tight items)
    if fit_ratio < 0.5 {
        score += 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Time horizon: early on, be slightly more willing to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 3.0;
    }

    // Many open bins: discourage fragmentation into more bins
    score += 0.5 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize large post residual, but with non-linear (quadratic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: late in stream, tighten packing (penalize waste more)
    score += 25.0 * pr * progress * (1.0 - progress) * 0.0; // keep base; add interaction below
    score += 30.0 * progress * norm_pr * norm_pr * cap * 0.1;

    // Reward tight fits: small post residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // More competing bins -> slight penalty for spreading
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
