    }

    // Deviation from mean residual: prefer bins that reduce dispersion
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Mild penalty for opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is small are rewarded strongly.
    let post = post_residual;
    let small_bonus = match post {
        0 => 40.0,          // perfect fill
        1..=5 => 30.0,
        6..=10 => 20.0,
        11..=20 => 12.0,
        21..=30 => 5.0,
        _ => 0.0,
    };
    score -= small_bonus;

    // Modulo-10 harmonic: leftovers divisible by 10 pair well with future items.
    if post > 0 && post % 10 == 0 {
        score -= 6.0;
    }
    // Penalize awkward dead space classes (residuals in 31..=40 rarely match).
    if post >= 31 && post <= 40 {
        score += 8.0;
    }
    if post >= 61 && post <= 70 {
        score += 5.0;
    }

    // Integer-division thresholds: how many items of the current size class could still fit.
    let fits_again = if item_size > 0 { post / item_size } else { 0 };
    score -= (fits_again as f64) * 4.0;

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size < post {
            let slack = post - next_item_size;
            score -= match slack {
                0..=5 => 15.0,
                6..=10 => 10.0,
                11..=20 => 4.0,
                _ => 0.0,
            };
            // Harmonic pairing: next item leaves a multiple-of-10 remainder too.
            let npost = slack;
            if npost % 10 == 0 { score -= 4.0; }
        } else {
            // next item won't fit here: mild penalty if it would fit in a fresh bin
            if next_item_size <= bin_capacity {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tightest (post_residual already does this)
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is justified only if item is large or no good fit exists.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Base cost of a new bin grows with open bins and mean residual waste.
        let waste_pressure = (mean_residual / cap).clamp(0.0, 1.0);
        let new_cost = 45.0 + 10.0 * (open_bins_count as f64).sqrt() + 20.0 * waste_pressure - 15.0 * item_frac;
        score += new_cost;
        // Late in stream, prefer consolidating into open bins.
        score += 10.0 * progress;
    } else {
        // Mild reward for using an existing bin, scaled by its fullness.
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= 5.0 * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
