        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 500.0; // exact 2-step chain match
        } else if post_residual as u32 >= next_item_size {
            // next item fits after this placement: reward tightness of chain
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted residual relative to its size
            score += 0.5 * diff;
        }
    }

    // Tight fit relative to capacity
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Compare post_residual against mean residual: prefer bins left near mean (balanced)
    let pr = post_residual as f64;
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bins would waste a lot
    if bin_residual == bin_capacity {
        let waste_open = fitting_bins_count.max(1);
        let best_case = if next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size { 500.0 } else { 0.0 };
        score = 100.0 + item_size as f64 * 0.5 - best_case
            + if fitting_bins_count > 0 && (bin_residual - item_size) < next_item_size { -50.0 } else { 0.0 };
        // discourage opening new bins early in the stream
        score += 50.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 1000.0; // must open
        }
    }

    // Slight preference for filling nearly-full bins
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual -> 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    } else {
        // Last item: prefer fullest packing, no need to preserve space.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or existing residuals are all small.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins by default, more so early in the stream.
        score += 18.0 + 10.0 * (1.0 - progress);
        // But relax the penalty when the item is big or mean residual is tiny.
        score -= 22.0 * fill_ratio;
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
        // If no open bin can fit at all, opening is necessary: cancel penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global state coupling: if many open bins with large mean residual,
    // discourage spreading into fresh space; encourage using fuller bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.08 * residual_gap;

    // Mild preference for keeping the count of open bins low.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual with smooth polynomial coupling to progress
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 15.0 * (nxt - pr) / cap;
        } else {
            // smooth reward when next item could still fit here
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // Discourage opening a new bin when existing mean residual is generous
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (mean_residual / cap) * (0.5 + progress);
    } else {
        // Reward bins whose residual is below mean (already fragmented, use them up)
        let diff = mean_residual - bin_residual as f64;
        score -= 5.0 * (diff / cap).clamp(-1.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: quantize post_residual into capacity-fraction classes.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    score += class as f64 * 3.0;

    // Reward tight fits (post_residual small) especially below a quarter.
    if post_residual < quarter {
        score -= 8.0;
    }

    // Perfect-fit style reward: post_residual divisible by small units.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
        // Extra reward if next item exactly fills post_residual (harmonic pairing).
        if next_item_size == post_residual {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Dead-space penalty: leftover too small for next item.
        score += 3.0;
        if post_residual < 10 {
            score += 4.0; // tiny dead space is nearly worthless
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: neutral-ish score so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // prefer fresh bin for large upcoming items
        }
    }

    // Encourage consolidation when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Slight late-stream tightening.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but treat tiny unusable gaps harshly.
    // Dead space: residual too small to plausibly accept any future item.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.15);
    if (post_residual as f64) < dead_threshold {
        // Unusable sliver: heavy penalty proportional to its uselessness.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when post_residual can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if lookahead fits snugly (small leftover after lookahead).
        let after_next = post_residual as f64 - next_item_size as f64;
        score -= 10.0 * (1.0 - after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize if lookahead cannot follow into this bin (fragmentation risk).
        score += 6.0;
    }

    // Tightness coupling: reward small post_residual relative to mean residual.
    score -= 3.0 * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // the empty new-bin candidate should look unattractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus growing pressure.
        score += 15.0 + pressure * 2.0;
        // But allow opening a new bin if no open bin fits well
        // (large item, all residuals small).
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Slight reward for consolidating into existing bins.
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= (slack_after_next as f64).min(20.0) * 0.8;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit in the leftover: dead space penalty.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Tight fit reward: small post_residual is valuable.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Penalize bins far from mean residual (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: default neutral score with slight penalty so we only
    // open new bins when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Too many open bins: discourage spreading items thinly.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize large dead space, especially unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver is dead space
    }

    // Tight fit bonus: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: reward leaving room exactly for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (post_residual as f64 / next_item_size as f64).ln().abs().min(2.0);
        } else {
            // leftover too small for next item: mild penalty scaled by waste
            let waste = next_item_size - post_residual;
            score += 0.5 * waste as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer new bin only when fits are bad
    if bin_residual == bin_capacity {
        // opening a new bin costs; make it attractive only if existing fit is loose
        score = bin_capacity as f64 * 0.9 + 20.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 40.0; // big next item pairs well with fresh bin
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 0.3 * mean_residual * (1.0 - progress);
    }

    // Time horizon: early stream, be picky about tight fits; late stream, just fill
    score -= 25.0 * fill_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + progress) + norm_post * (1.0 - progress) * 0.3;
    score += poly * 10.0;

    // Reward tight fits more aggressively as stream progresses
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + progress) * 5.0;

    // Penalize waste relative to mean residual (smooth quadratic)
    let drift = post_residual as f64 - mean_residual;
    score += 0.02 * drift * drift / (1.0 + progress);

    // Lookahead coupling: reward residual that fits next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / bin_capacity as f64;
        let fit_next = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fit_next * nxt * (1.0 + progress) * 4.0;
        // Penalize residuals slightly larger than next item (near-miss dead space)
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        if gap > 0.0 && gap < 0.2 {
            score += gap * gap * 20.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Discourage opening new bins when many bins are open and fit is decent
    let open_f = open_bins_count as f64;
    score += open_f * 0.05 * (1.0 - norm_item);

    // New-bin candidate: mildly penalize so it's chosen only on poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets capture
    // "compatibility classes" of future items (sizes 1..100).
    let class = post_residual % 10;
    let div = post_residual / 10; // coarse capacity fraction

    // Reward residuals that form "nice" harmonic classes:
    // post_residual in {0} is perfect; small classes 1..5 are decent;
    // classes 6..9 are awkward dead space.
    match class {
        0 => score -= 25.0,
        1 | 2 | 3 | 4 | 5 => score -= 6.0,
        _ => score += 4.0 + 2.0 * (class as f64 - 5.0),
    }

    // Tight fill reward: fraction of bin used by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (harmonic chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // prefer leaving residuals that are multiples of common sizes
            if post_residual % 10 == 0 && post_residual > 0 {
                score -= 8.0;
            }
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 5.0 {
                score -= 5.0;
            } else {
                score += gap * 0.05;
            }
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += (post_residual as f64) * 0.10;
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or bins are nearly full. An empty bin has huge residual; make it
    // unattractive unless mean residual is very low (all bins nearly full).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.15 {
            score -= 20.0; // everything nearly full -> open fresh bin
        } else {
            score += 18.0 + 10.0 * pressure;
        }
    }

    // Mild preference to spread load when many bins are open with slack
    // (avoid fragmenting one bin while others idle).
    if open_bins_count > 1 && bin_residual as f64 > mean_residual + 20.0 {
        score += 5.0;
    }

    // Progress term: later in the stream, squeeze tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

