    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderate dead space: penalize proportionally to how "stranded" it is
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual) relative to item size.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 25.0;

    // Open bins pressure: discourage spreading across many bins when a
    // good fit exists; encourage using existing bins.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + next_item_size as f64 * 0.2;
        } else if post_residual > 0 {
            // Dead space that cannot host the next item is worse.
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Mild progression pressure: later in stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New-bin candidate: keep neutral baseline; only chosen if no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

