    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // post_residual too small for next item: penalize proportionally to wasted space
            score += (post_residual as f64) * 0.3;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when other
    // bins fit and mean residual is large (wasteful fragmentation).
    if bin_residual == bin_capacity {
        let base_penalty = 40.0;
        let fragmentation = (mean_residual / bin_capacity as f64) * 30.0;
        let pressure = if open_bins_count > 0 { (open_bins_count as f64).ln() * 5.0 } else { 0.0 };
        score += base_penalty + fragmentation + pressure;
        // If nothing else fits (fitting_bins_count counts only open bins; new bin is
        // called separately), the penalty stands and this becomes the fallback.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit coupling).
    let waste_gap = (bin_residual as f64 - item_size as f64).abs();
    score += waste_gap * 0.15;

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins.
    if open_bins_count > 4 && mean_residual > item_size as f64 * 2.0 {
        score -= 6.0;
    }

    // Time horizon: early in the stream, be slightly more liberal with new bins
    // (long horizon to fill them); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fills (low post_residual) mildly.
    // Late: penalize larger residuals more strongly to consolidate.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr * (0.5 + 1.5 * p2 + 1.0 * p3);
    score += 0.8 * coupling;

    // Reward near-perfect fits with a smooth quadratic discount.
    let fit_frac = 1.0 - (pr / cap);
    score -= 6.0 * fit_frac * fit_frac;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 4.0 * gap * gap * cap * 0.01;
        // Reward residual that exactly accommodates the lookahead item.
        let match_term = 1.0 - (pr - nx).abs() / cap;
        score -= 3.0 * match_term.max(0.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Slight preference for bins with residual below mean (compact consolidation).
    score += 0.3 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize mildly unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Small penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse bands.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: post_residual in low harmonic classes gets bonus.
    if post_residual == 0 {
        score -= 200.0; // perfect fill, ideal
    } else if post_residual < eighth {
        score -= 60.0;
    } else if post_residual < quarter {
        score -= 25.0;
    } else if post_residual < 2 * quarter {
        score += 5.0;
    } else {
        score += 30.0; // large dead space penalty
    }

    // Modulo-class logic: residuals that are multiples of common item sizes
    // are more reusable. Check divisibility by small harmonic steps.
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if m <= r && r % m == 0 {
                bonus += 8.0;
            }
        }
        bonus
    };
    score -= reusable(post_residual);

    // Lookahead: does post_residual exactly fit next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / c).max(0.0);
        } else {
            score += 15.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor fits (high mean residual spread) or the item
    // is large relative to residual.
    if bin_residual == bin_capacity {
        // brand-new empty bin: base score = full capacity worth of dead space
        // penalize opening unless item is big and fits poorly elsewhere.
        score = c - item_size as f64;
        if item_size >= 3 * quarter as u32 {
            score -= 40.0; // big items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // room for lookahead pair
        }
        score += 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - pr / c);

    // Mild penalty proportional to residual above mean (avoid outlier waste).
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (items >= 10 in the classic setting, but sizes 1..100 => treat gaps < 6 as dead).
    if post_residual >= 1 && post_residual <= 5 {
        score += 40.0; // unusable sliver penalty
    } else if post_residual <= 12 {
        score += 12.0; // marginal gap penalty
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill reward
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (penalize new-bin candidate more as open_bins_count grows).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        } else if next_item_size as u32 > post_residual && next_item_size as u32 <= bin_residual {
            // next item fits this bin now but not after placement: mild penalty
            score += 5.0;
        }
    }

    // Mean-residual coupling: placing into a bin below mean residual
    // balances load across bins; small reward.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 0.2 * (mean_residual - bin_res_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Perfect match: huge reward (subtract).
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus for an exact fill (dead space = 0 after next placement).
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall.
            score += 10.0 * (nxt - post) / bin_capacity as f64;
        }
    }

    // Penalize leaving large unusable residual relative to mean residual.
    let post = post_residual as f64;
    if post < mean_residual {
        score += 0.5 * (mean_residual - post);
    } else {
        score -= 0.2 * (post - mean_residual);
    }

    // Small residual after placement is good (tight fit now).
    score -= 0.3 * (1.0 - post / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        let mut penalty = 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is large, a fresh bin may be valuable.
            penalty -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
        if fitting_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
    }

    // Mild preference early in the stream to consolidate bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or the current fit is terrible.
    let is_new_bin = bin_residual == bin_capacity && bin_residual == bin_capacity;
    if is_new_bin {
        let crowded = open_bins_count as f64 * 0.5;
        let poor_fit = (bin_capacity as f64 - fit_ratio * bin_capacity as f64) * 0.3;
        score += 15.0 + crowded - poor_fit * 0.0;
        // Lookahead: if next item pairs perfectly with this item in a fresh bin
        // and current fit is bad, encourage new bin.
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair <= bin_capacity && fit_ratio < 0.6 {
                score -= 20.0;
            }
        }
        // Late in the stream, avoid opening new bins (waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead synergy: if next item exactly fills post_residual, big reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial synergy proportional to how much of the leftover it uses
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover becomes dead space for the known next item
        score += 5.0;
    }

    // Global balance: prefer bins whose residual is close to the mean residual
    // (keeps the pool homogeneous and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild preference for filling fuller bins when many bins are open.
    score -= 0.05 * open_bins_count as f64 * fit_ratio;

    // Time-horizon term: early in stream, be conservative (keep space flexible);
    // late in stream, prioritize immediate tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (1.0 - fit_ratio);
    score -= progress * 4.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via non-linear decay on post residual
    let mut score = pr * (1.0 + 0.8 * progress);

    // Smooth polynomial coupling: penalize mid-range residuals more as stream progresses
    let poly = norm_pr * (1.0 - norm_pr);
    score -= 12.0 * poly * poly * (1.0 + progress);

    // Reward near-perfect fits with a smooth exponential bonus
    score -= 20.0 * (-norm_pr * 8.0).exp();

    // Penalize leaving residual close to typical small items (dead space) smoothly
    score += 6.0 * (-((norm_pr - 0.3).abs() * 10.0)).exp() * progress;

    // Lookahead coupling: reward residuals that fit the next item smoothly
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let closeness = (-((pr - next_item_size as f64).abs() / cap * 4.0)).exp();
        score -= 10.0 * fits_next * closeness * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    // New-bin candidate: neutral-to-slightly-high baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are
    // "likely fillable" by common item sizes (multiples of small classes).
    let pr = post_residual;
    if pr > 0 {
        // Perfect fill classes: residual exactly matches a likely item size
        if pr == 0 {
            score -= 100.0;
        }
        // Reward residuals in dense harmonic classes (10,20,...,50)
        if pr % 10 == 0 && pr <= 50 {
            score -= 12.0;
        }
        // Penalize awkward residuals (prime-ish / odd small gaps)
        if pr < 10 {
            score += 25.0;
        } else if pr % 10 != 0 {
            score += (pr % 10) as f64 * 0.8;
        }
        // Integer-division threshold: residual usable by half-capacity chunks
        if pr / 25 >= 1 {
            score -= (pr / 25) as f64 * 5.0;
        }
    } else {
        // Perfectly closed bin: strongly favored
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect completion.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin ~ average waste we'd otherwise create.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + mean_residual * 0.15 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin necessary
        }
    } else {
        // Tight fits are great: reward small post residuals relative to item
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 20.0;

        // Prefer bins whose residual is below mean (concentrating fill),
        // penalize spreading fill thinly across many bins.
        score += ((bin_residual as f64 - mean_residual) * 0.2).max(0.0);
        if open_bins_count > 4 {
            score += 2.0;
        }
    }

    // Mild phase term: early in stream, be slightly greedy for tight fits;
    // late in stream, prioritize closing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are heavily penalized; perfect fit (0) is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 30.0;
    } else {
        // Larger residual: mildly penalize waste beyond the item's own size.
        score += 0.15 * (post_residual as f64 - 10.0);
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // packing into existing bins when several are open.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score -= 15.0; // opening a bin is fine if it's the only option anyway
        }
    }

    // Lookahead: reward leaving residual that fits the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // residual too small for lookahead item: dead space risk
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a tight bin — favor using it up.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream pressure: tighten up as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect 2-chain: next item exactly fills the bin
        if diff < 0.5 {
