        } else if pr >= nxt {
            // Next item fits with some slack left; reward tight matches
            let tightness = 1.0 - diff / pr.max(1.0);
            score -= 40.0 * tightness;
            // Bonus if the chain continues (residual after next item still usable)
            let post2 = pr - nxt;
            if post2 >= 1.0 {
                score -= 5.0 * (1.0 - post2 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to waste
            score += 15.0 * (nxt - pr) / bin_capacity as f64;
        }
    }

    // Penalize residuals too small for any future item (dead space)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (1.0 - pr / 10.0);
    }

    // Relative to mean residual: prefer bins that reduce variance / use large residuals
    score -= 8.0 * (bin_residual as f64 - mean_residual).max(0.0) / bin_capacity as f64;
    score += 4.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early in the stream: keep bins compact, allow more bins later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    // Slight preference for placing into existing bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
