    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * (1.0 - next_tight);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer bins with below-mean residual (conserving larger residuals for future items)
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 5.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Early in the stream: prefer opening new bins over fragmenting many bins
    // Late in the stream: pack tightly into existing bins
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late
        score -= 45.0 * (1.0 - progress);
        score += 55.0 * progress;
        // Fewer open bins makes new bins cheaper
        score += 3.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 12.0;
        }
    } else {
        // Existing bin: mildly penalize when few bins are open early (encourage spreading)
        score += 6.0 * (1.0 - progress) / (open_bins_count.max(1) as f64);
    }

    // Global pressure: many open bins -> discourage new bins, encourage consolidation
    if open_bins_count > 4 {
        if bin_residual == bin_capacity {
            score += 10.0 * (open_bins_count as f64 - 4.0);
        } else {
            score -= 4.0 * (open_bins_count as f64 - 4.0).min(10.0);
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: prefer tight fits; non-linear penalty on wasted space.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, punish large residuals harder.
    score += 30.0 * progress * norm_pr * norm_pr;

    // Dead-space coupling with mean residual across open bins.
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm).abs();

    // Lookahead: reward leaving a residual that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Penalize residuals that cannot host the next item.
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more when other bins fit.
    if bin_residual == bin_capacity {
        score += 40.0 + 15.0 * (fitting_bins_count as f64);
        // Opening is more tolerable early in the stream.
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference to fill already-open bins when many are open.
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i32; // 0..3 harmonic quartiles

    // Reward tight fits strongly
    score -= 25.0 * (1.0 - frac);

    // Dead-space penalty: tiny leftovers are wasteful
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // penalize leaving residue that no plausible next item can use
            score += 8.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish score so only clearly bad fits trigger it
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 - 10.0 * (1.0 - frac);
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 100.0;
        }
    }

    // Modulo arithmetic on post_residual: residues near multiples of common item sizes
    let mod_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50] {
            if m > 0 && r % m == 0 && r > 0 {
                b -= 5.0; // residue aligns with a harmonic class -> reusable
            }
        }
        b
    };
    score += mod_bonus(post_residual);

    // Integer-division threshold: penalize residuals in awkward mid-range classes
    if class == 1 {
        score += 6.0; // ~25-50% leftover: hard to fill
    } else if class == 2 {
        score += 2.0;
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Many open bins: prefer filling existing ones over opening more
    score += 0.5 * open_bins_count as f64 * (1.0 - frac);

    // Mean residual coupling: if this bin is far below mean residual, it is a good filler
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to
    // ever be useful (below the plausible minimum item footprint).
    let min_item: f64 = 1.0;
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fit_ratio * 18.0;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) <= min_item {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 12.0;
        // Extra reward if next item nearly fills the post residual.
        let next_tightness = (next_item_size as f64) / (post_residual as f64).max(1.0);
        score -= next_tightness * 8.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to wasted space.
        let waste = post_residual as f64 - 0.0;
        score += waste * 0.05;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new
    // bins; when few bins are open, allow new bins more freely.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 - progress * 0.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it when residuals
        // across open bins are already small (mean_residual low).
        score = 55.0 + pressure * 8.0 - (mean_residual.min(60.0)) * 0.6;
        // If this is the only option (no fitting bins), make it cheap.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Placing into an existing bin slightly relieves open-bin pressure.
        score -= pressure * 2.0;
        // Prefer bins with larger residuals when mean residual is high (keeps
        // the bin population balanced).
        score -= (bin_residual as f64 - mean_residual).clamp(-30.0, 30.0) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 - (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // Next item does not fit: penalize dead space that is too small to be useful.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 15.0 * (10.0 - waste);
            }
        }
    }

    // Prefer bins whose residual is below mean (tighter packing).
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless residual would otherwise be wasted.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no other bin fits well and item is large, opening a new bin is fine.
        if fitting_bins_count == 0 || item_size > 70 {
            score -= 55.0;
        }
    }

    // Small post residuals are good (tight fit), large ones slightly penalized.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Early in stream: be slightly more willing to open bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && item_size > 60 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared residual dominates, heavily penalizing waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 0.5);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward; if
    // post residual is too small for the next item, penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if (post_residual as f64) >= nxt && (post_residual as f64) < 2.0 * nxt {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space the next item can't use
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Prefer bins whose residual deviates from the mean (fill lopsided bins first).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // When many bins are open, encourage consolidation into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + t * 10.0);
    if bin_residual != bin_capacity {
        score -= crowding.min(8.0) * 2.0;
    } else {
        // New-bin candidate: penalize more when bins are few or early in stream;
        // allow opening late when residuals are fragmented.
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).abs();
        score += 25.0 + 30.0 * (1.0 - t) - fragmentation * 20.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
    }

    // Slight preference for bins with larger residual (best-fit baseline).
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, large residuals are fine; late, we penalize wasted space quadratically.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) * cap;
    score += coupling * 0.35;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + 2.0 * progress) * 8.0;

    // Lookahead: if the next item fits into the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack) * 6.0 * (1.0 + progress);
        } else {
            let gap = (nx - pr) / cap;
            score += gap * gap * 14.0 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize bins far below mean residual (encourages balancing load).
    score += (mean_residual - pr).abs() * 0.25;

    // Mild preference for fewer open bins when many bins exist.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive early or when post-residual would be tiny.
    if bin_residual == bin_capacity {
        let new_bin_cost = 30.0 - 20.0 * (1.0 - progress) - 25.0 * (1.0 - pr_norm);
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which modulo bucket it falls into.
    let post = post_residual;
    let class = post % 10; // coarse harmonic class
    // Dead-space classes: residuals that few future items can use are penalized.
    match post {
        0 => score -= 60.0,                 // perfect fit
        1..=9 => score += 25.0,             // nearly unusable dead space
        10..=19 => score += 8.0,            // only tiny items fit
        20..=39 => score -= 5.0,            // decent small-item slot
        40..=59 => score -= 12.0,           // good medium slot
        _ => score -= 3.0,                  // large residual: keep flexible
    }

    // Fine-grained modulo coupling with next item size (lookahead harmony).
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= post {
            // Next item fits here too: strong reward, scaled by tightness.
            let slack_after_next = (post - nxt) as f64;
            score -= 20.0 - slack_after_next.min(20.0) * 0.4;
            if (post - nxt) % 10 == 0 {
                score -= 10.0; // harmonic chain: both fits leave class-0 residual
            }
        } else {
            // Next item won't fit: penalize mildly, worse if residual is odd-class.
            score += 6.0 + (class as f64) * 0.5;
        }
    } else {
        // Last item: prefer exact closure.
        if post == 0 { score -= 40.0; }
    }

    // Last-chance bin bonus: only one bin fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residual is genuinely poor relative to item and mean residual.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // post_residual of new bin
        // Reward opening when existing residuals are all too fragmented
        // for the next item as well.
        if next_item_size > 0 {
            let waste_now = (post as f64) - (next_item_size as f64);
            if waste_now < 0.0 { score += 15.0; }
        }
        // As stream matures, discourage needless new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0 + open_bins_count as f64 * 0.5;
        if mean_residual > item_size as f64 {
            score += 20.0; // existing bins are roomy enough; don't open new
        }
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 range).
    // Penalize gaps in the critical small band (1..=15) super-linearly.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 12.0;
    }

    // Perfect fits (zero waste) get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling: if the next item could fit into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item cannot fit, penalize proportionally to how close the gap was.
    else if next_item_size > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / 8.0) * (0.5 + progress);
    score += pressure * 6.0;

    // Slight preference toward bins with below-mean residual (tighter bins used first),
    // keeping large-residual bins flexible for future large items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline, penalized when open-bin pressure is high,
    // rewarded slightly when item is large (poor fits likely elsewhere).
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 6.0 - (item_size as f64 * 0.15);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap;
    }

    // Penalize residuals that are too small to ever be useful (dead space)
    if post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins with below-mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New bin candidate: penalize slightly unless current bins are nearly full / crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0
            - 10.0 * progress
            - 2.0 * open_bins_count as f64;
        // If next item is large and no open bin fits it well, opening new bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidation bias, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits non-linearly: small post_residual is disproportionately valuable.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).powf(1.35) * 0.15;

    // Penalize dead space that no future item can plausibly use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > 0.0 && pr < next_item_size as f64 && next_item_size > 0 {
        score += 12.0 * (1.0 - pr / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(3.0);
    }

    // Prefer bins with below-average residual (consolidate emptier space usage).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: opening a bin is penalized, but less so when
    // this bin would waste a lot of space or few bins fit the item.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        score += 15.0 + waste * 0.25 * open_pressure;
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening is better than a forced bad fit elsewhere
        }
        if next_item_size > 0 && next_item_size >= item_size && waste < next_item_size as f64 {
            score -= 10.0; // new bin can chain with the upcoming item
        }
    }

    // Early in the stream, be slightly more willing to open bins (exploration).
    score -= (1.0 - progress) * 4.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Mild penalty for very small leftovers that fragment capacity.
    if pr > 0 && pr < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * t) - norm_pr * t * 0.8;
    score += 12.0 * poly;

    // Penalize residual that can't fit the next item (smoothly)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 2.5 * (gap / cap) * (1.0 + t);
        } else {
            score -= 1.5 * (-gap / cap) * (1.0 - t);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Mild reward for tightening residual relative to mean residual of open bins
    score -= 0.5 * (mean_residual - pr) / cap;

    // Late-stream: prefer fuller bins more aggressively
    score -= 6.0 * t * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - t) + 2.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let post_frac = post_residual as f64 / cap;
    let harmonic_class = (post_frac * 8.0).floor() as i32; // 0..7 classes

    // Reward tight fits: perfect or near-perfect packing
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else {
        // Penalize residuals that fall in "useless" harmonic classes
        // (too small for typical items but not zero)
        if post_residual < 10 {
            score += 15.0;
        }
        // Modulo logic: residuals divisible by common item sizes are reusable
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
    }

    // Coupling with lookahead item: reward residuals that exactly or nearly fit next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space for the next item: mild penalty scaled by class
            score += (harmonic_class as f64) * 1.5;
        }
    }

    // Last-chance bin logic: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no decent fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // cheaper to open new bin when current bin would leave big awkward residue
        let waste = post_residual as f64;
        if waste > 40.0 {
            score -= (waste - 40.0) * 0.6;
        }
        // early in stream, opening bins is fine; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // many open bins with low mean residual: avoid opening more
        if mean_residual < 25.0 && open_bins_count > 2 {
            score += 15.0;
        }
    } else {
        // Favor bins with residual close to item (best-fit flavor)
        let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
        score += gap * 0.15;
        // favor bins below mean residual (concentrate fill)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Integer-division threshold on item size: large items prefer roomy bins
    if item_size / 20 >= 3 {
        score += post_frac * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item are pure waste — penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small but still usable residuals).
    if post_residual > 0 && post_residual <= 20 {
        score -= 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones,
    // making the new-bin candidate less attractive.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate baseline: only attractive when item barely fits anywhere
    // (handled above) or mean residual across bins is very low.
    if bin_residual == bin_capacity {
        score = 30.0 + mean_residual * 0.3 - open_bins_count as f64;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would NOT fit the post residual but would fit this bin after a
    // different placement choice, mild penalty for fragmenting.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (build a diverse pool).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fits: minimize post_residual nonlinearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 30.0 * (1.0 - post / 10.0);
    }

    // 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap == 0.0 {
            score -= 60.0;
        } else if post >= nxt {
            score -= 25.0 / (1.0 + gap / 10.0);
        } else {
            // next item cannot fit here; penalize leaving residual that wastes space
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Compare post_residual to mean residual across open bins:
    // prefer bins whose post residual is below average (tight packing).
    score += 0.5 * (post - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current fit is terrible.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - post / cap;
        score += 15.0 - 40.0 * (1.0 - tightness);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream: consolidate aggressively, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Many open bins: favor filling existing ones rather than spreading.
    score += 0.2 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Global state: many open bins with large mean residual -> discourage opening new bins
    // and favor consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are crowded, relax late in stream.
        score += 12.0 + 6.0 * (1.0 - progress) + 0.05 * crowding;
        // Opening a fresh bin is attractive when no bin fits well and residual is wasted.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Existing-bin bonus grows with crowding and stream progress.
        score -= 2.0 + 0.02 * crowding + 3.0 * progress;
    }

    // Prefer bins whose residual is close to item_size (perfect-ish fit shaping).
    let slack = (bin_residual - item_size) as f64;
    score += 0.15 * (slack - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear penalty on wasted residual, amplified by stream progress
    score += 6.0 * prn * prn * (0.5 + progress) * cap;

    // Reward tight fits with smooth exponential-ish polynomial coupling
    let tightness = 1.0 - prn;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Lookahead: favor leaving space exactly usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        let dn = diff / cap;
        score += 3.0 * dn * dn * cap;
        if pr >= nx {
            score -= 4.0 * (nx / cap) * (1.0 - dn * dn);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when open bins fit decently
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let base = 25.0 + 20.0 * progress;
        score += base;
        // Allow new bin if item is large relative to capacity or mean residual is poor
        score -= 15.0 * (item_size as f64 / cap);
        score -= (mean_residual / cap).min(1.0) * 10.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Smooth quadratic coupling of post_residual with mean residual alignment
    let mr = mean_residual / cap;
    score += 4.0 * (prn - mr) * (prn - mr) * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left

    // Harmonic penalty: dead space is worse when it's a small, awkward leftover.
    // Classes: (0,10] terrible, (10,30] bad, (30,50] ok, >50 fine.
    let class_penalty: f64 = if post_residual == 0 {
        -50.0 // perfect fit
    } else if post_residual <= 10 {
        40.0
    } else if post_residual <= 30 {
        15.0
    } else if post_residual <= 50 {
        0.0
    } else {
        -10.0
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: leftovers divisible by small units (5,10)
    // are more likely reusable by future items.
    let reusable = if post_residual % 10 == 0 {
        -8.0
    } else if post_residual % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += reusable;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / pr;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here: leftover likely becomes dead space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large and existing leftovers are small/fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let pressure = (item_size as f64) / cap;
        // prefer new bin when item is big and open bins are fragmented
        score += 30.0 - 40.0 * pressure - 30.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild reward for choosing fuller bins (best-fit bias beyond raw residual).
        score -= 5.0 * (1.0 - frac);
    }

    // Stream progression: early on, be more willing to open bins / keep options;
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps (1..=10) are strongly penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving space usable by the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize near-miss gaps just below next item size.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -(next_item_size as f64) * 0.25 {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference for bins with larger residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact two-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect 2-step fill bonus
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward when post_residual is exactly consumed by next item
        if slack < 1.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space
        score += 15.0 + 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Tightness reward: small post_residual relative to capacity
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to item (good fit) relative to mean residual
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;
    score -= 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin unless current bins are poorly utilized
    if bin_residual == bin_capacity {
        let avg_use = 1.0 - mean_residual / bin_capacity as f64;
        if avg_use > 0.55 {
            score += 45.0;
        } else {
            score += 10.0 * (1.0 - avg_use);
        }
        // Late in the stream, keep consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual non-linearly
    let tight_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize large dead space with a convex penalty
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * dead * dead;
    }

    // Perfect fits are highly desirable
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: penalize opening a new bin, more so early in the stream
    // and when other bins can fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If item is large relative to capacity, a fresh bin is more acceptable
        score -= 0.3 * item_size as f64;
    } else {
        // Reward using existing bins, especially when many bins are open (consolidation)
        score -= 2.0 * (open_bins_count as f64).min(10.0) / 10.0;
    }

    // Lookahead: if next item would fit nicely in the post-residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - next_tight);
        } else {
            // If next item won't fit here, mildly penalize leaving a residual close to it
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 8.0 * (10.0 - gap) / 10.0;
            }
        }
    }

    // Global residual pressure: if mean residual is high, prefer bins that reduce spread
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late-stream consolidation: as stream ends, avoid opening bins even more
    score += 15.0 * progress * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress2 = progress * progress;

    // Tightness of fit: normalized post residual
    let post_norm = post_residual as f64 / cap;
    let item_norm = item_size as f64 / cap;

    // Smooth non-linear coupling: reward tight fits with a saturating polynomial
    let tightness = (1.0 - post_norm).powi(3);
    score -= 12.0 * tightness * (0.6 + 0.8 * progress);

    // Penalize large dead space non-linearly (quartic waste penalty)
    score += 4.0 * post_norm * post_norm * post_norm * post_norm * cap;

    // Penalize when post-residual is unusable: small but nonzero leftover
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + 20.0 * progress2;
    }
    // Perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: favor bins whose leftover can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let slack = (post_residual as f64 - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: only attractive when open bins fit poorly or stream is early
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        let penalty = 20.0 + 40.0 * progress + 10.0 * open_bins_count as f64 * 0.1;
        score += penalty - 15.0 * avg_fit_gap * (1.0 - progress);
    }

    // Mild reward for balancing residuals toward the mean (smooth coupling)
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into capacity octants.
    let cap = bin_capacity as f64;
    let octant = post_residual / (bin_capacity / 8).max(1);
    match octant {
        0 => score -= 25.0,               // near-perfect fit: strongly reward
        1 => score -= 15.0,               // small residue still pairs with tiny items
        2 => score -= 6.0,
        3 => score -= 1.0,
        4 => score += 2.0,
        5 => score += 6.0,
        6 => score += 10.0,
        _ => score += 14.0,               // large residue = wasted opportunity
    }

    // Modulo-10 harmonic class: residues divisible by 10 pair with more item sizes.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 + 6.0 * (1.0 - slack as f64 / cap);
        } else {
            // penalize residues that just barely fail to host the next item
            let miss = next_item_size - post_residual;
            score += 3.0 * (1.0 - miss as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin late in stream when many bins open (parallel packing helps)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must place somewhere
        }
    }

    // Prefer bins below mean residual (keep big holes for big future items).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for tighter fits overall.
    score += 0.1 * (item_size as f64 / bin_residual.max(1) as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized,
    // scaled by how deep into the stream we are (dead space hurts more later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 + progress) * (10 - post_residual) as f64;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits generally: fraction of bin consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing bins.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.0 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item cannot use the gap: mild penalty for leaving stranded space.
            score += 6.0;
        }
    }

    // New-bin candidate: base score for an empty bin; attractive only when no open bin
    // offers a good fit (mean residual small relative to item, or many bins already open).
    if bin_residual == bin_capacity {
        let good_fit_exists = (mean_residual >= item_size as f64) && (mean_residual - item_size as f64 >= 10.0);
        if good_fit_exists {
            score += 30.0; // discourage opening a new bin when decent fits exist
        } else {
            score -= 5.0;  // encourage fresh bin for poor-fit situations
        }
        if open_bins_count > 8 {
            score += 15.0 * (open_bins_count as f64 - 8.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (post_residual == 0)
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: reward proportional to how snugly it fits
            let slack_after_next = post_residual - next_item_size;
            score -= 80.0 + (slack_after_next as f64).min(40.0);
            if slack_after_next == 0 {
                score -= 200.0; // perfect 2-item packing
            }
        } else {
            // Next item won't fit here: penalize wasting residual that could have held it
            let wasted = post_residual as f64;
            score += 0.6 * wasted;
        }
    }

    // Penalize post_residual that is too small to ever be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect chain
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / bin_capacity as f64);
    score -= 15.0 * pressure * tightness;

    // New-bin candidate: score it based on item size and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is attractive for large items that would waste small bins,
        // and less attractive late in the stream (prefer closing out).
        score = 20.0 + 0.35 * (item_size as f64) - 25.0 * progress;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // new bin can host pair nicely
        }
        if fitting_bins_count > 0 {
            score += 8.0; // mild penalty: some open bin already fits
        }
        return score;
    }

    // Prefer bins whose residual is close to item size relative to mean residual.
    let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
    score -= 5.0 * (1.0 / (rel + 0.5));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let p2 = progress * progress;

    // Base: waste after placement, weighted increasingly with stream progress
    let mut score = pr * (0.6 + 1.6 * p2);

    // Non-linear coupling: penalize large residuals late, reward tight fits
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Perfect-fit reward (smooth, non-piecewise)
    score -= 25.0 * (-pr as f64 * 0.35).exp();

    // Dead-space penalty: residual too small for typical future items
    let too_small = (1.0 - (pr / 30.0)).max(0.0);
    score += 15.0 * too_small * too_small * (0.5 + progress);

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual
    score -= 6.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction it lands in
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;

    // Dead-space penalty: residuals that no plausible item (1..=100) can use well.
    // Perfect fit is best; residuals just above small item sizes are wasteful.
    if pr == 0 {
        score -= 40.0;
    } else if pr < 10 {
        // nearly unusable sliver unless tiny items exist
        score += 25.0;
    } else {
        // harmonic class penalty: distance of pr from nearest "usable" class
        let classes = [10u32, 20, 25, 33, 40, 50, 60, 66, 75, 80];
        let mut best_d = u32::MAX;
        for c in classes.iter() {
            let d = if pr >= *c { pr - c } else { c - pr };
            if d < best_d { best_d = d; }
        }
        score += 0.6 * best_d as f64;
    }

    // Modulo coupling with next item: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't chain here: penalize proportionally
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Integer-division threshold: residual in (cap/2, cap/2 + eighth] is a sweet spot
    if pr > quarter && pr <= quarter + eighth {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score = cap * 0.9 + 40.0 * crowded - (open_bins_count as f64).ln() * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // future big item may want fresh bin
        }
    }

    // Mild stream progression tilt: early on prefer tight packing of open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - (bin_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage opening/spreading when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare residual against mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Early stream: be more conservative about opening bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly with small slack
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack * 0.15);
    }

    // Penalize post_residual too small to ever be useful (dead space)
    if post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Compare post_residual to mean residual: leaving a residual near mean keeps
    // the fleet homogeneous; extreme outliers penalized
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New empty bin candidate: penalize unless no open bin is a good fit
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && open_bins_count > fitting_bins_count.min(open_bins_count)
            && (post_residual as f64) <= mean_residual + 20.0;
        if good_fit_exists {
            score += 45.0;
        } else {
            score += 5.0;
        }
        // Opening a bin is cheaper when many bins are already open (amortize)
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Early in stream: be slightly more willing to open bins / keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Small bonus for tight fits overall
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits / minimal dead space (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward residuals that exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to lookahead item.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize spreading across many open bins when mean residual is large.
    score += 0.05 * open_bins_count as f64;
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // Time horizon: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * fit_ratio;
    score += 10.0 * progress * post_residual as f64 / bin_capacity as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let threshold = 0.25 * bin_capacity as f64;
        if post_residual as f64 > threshold {
            score += 25.0; // discourage wasteful new bins
        } else {
            score -= 5.0;
        }
        score += 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer low post-residual (tight fit)
    let mut score = pr;

    // Non-linear penalty for residual that is too small to ever be useful
    // (dead space) but also for very large residual (wasteful loose fit).
    let x = pr / c; // normalized post-residual in [0,1]
    score += 6.0 * (x - 0.35) * (x - 0.35) - 1.0 * x * (1.0 - x);

    // Reward tight fits non-linearly: exponential-ish decay of fit quality
    let fit_quality = (1.0 - x).powi(3);
    score -= 4.0 * fit_quality * (it / c);

    // Smooth stream-progress coupling: early on, keep bins flexible (penalize small residuals more);
    // late in the stream, accept tight fits aggressively.
    let flex = (1.0 - progress).powi(2);
    score += 8.0 * flex * (1.0 - fit_quality) * x;

    // Mean-residual coupling: if this bin is far from the fleet mean residual,
    // slight preference to place into it (balance residuals) — smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / c;
    score += 2.5 * dev * dev - 1.5 * dev;

    // Lookahead: penalize if next item could have used this exact residual but not the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr && nx > bin_residual as f64 - it {
            // next fits post-residual: fine, small reward
            score -= 1.0 * (1.0 - (nx / c));
        } else if nx > pr && nx <= bin_residual as f64 {
            // next item would fit current residual but not after placing: strong penalty
            score += 5.0 * (nx / c) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - x) + 2.0;
    }
    // Many alternatives: mild penalty to this bin so best-fit among many is chosen
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: empty bin. Favor it when item is large relative to capacity
    // or when no open bin offers a decent fit; penalize it when open bins exist with good fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let emptiness_bonus = 10.0 * (it / c) * (0.5 + 0.5 * progress);
        score += 8.0 - emptiness_bonus;
        // if item is small, opening a bin is wasteful
        score += 12.0 * (1.0 - it / c) * (1.0 - progress);
    } else if bin_residual == bin_capacity {
        // first bin ever: always accept
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes
    let pr = post_residual as i64;
    let residue = pr % 10;
    // Penalize "awkward" residues that rarely get filled (1,2,3,7,8,9 mod 10)
    match residue {
        0 => score -= 8.0,           // perfectly divisible class, very reusable
        5 => score -= 4.0,           // half-class, decent
        4 | 6 => score -= 2.0,       // moderate
        _ => score += 3.0,           // awkward dead space
    }

    // Integer-division threshold on post_residual: small leftovers are dead space
    if pr > 0 && pr < 10 {
        score += 20.0;               // creating a tiny unusable sliver
    }
    if pr == 0 {
        score -= 30.0;               // perfect fill
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;           // chain two items: excellent
            // bonus if next item exactly fills the remainder
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish but avoid opening new bins when
    // this placement would be harmonically good
    if bin_residual == bin_capacity {
        score += 5.0;               // default slight penalty to prefer existing bins
        // but if all open bins would leave awkward residues, new bin is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Stream progression: late in stream, tighten up and prefer perfect fills
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual == 0) as i32 as f64 * 10.0;
    score += progress * 2.0;        // mild preference to reuse bins late

    // Mean-residual coupling: if this bin is far from mean residual, small penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 4.0; // tiny gaps are pure waste
    } else if pr == 0.0 {
        score -= 25.0; // perfect fit: eliminate the bin
    } else if pr < 20.0 {
        score += (20.0 - pr) * 1.5; // moderately risky gaps
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Last usable bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidation;
    // with few bins open, a new bin is cheaper.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score += bin_pressure * 0.5;

    // New-bin candidate handling: attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let wasted_elsewhere: f64 = mean_residual - pr;
        score -= 8.0 + wasted_elsewhere * 0.2;
        // But late in the stream, avoid spawning bins that can never be filled.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If the next item could also fit in this fresh bin, opening is good.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0;
        }
    }

    // Lookahead: if next item exactly fills this bin's post-residual, big bonus.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 40.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on small dead space.
        let pr = post_residual as f64;
        score += 200.0 / pr;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + gap);
        } else {
            // next item cannot fit here; penalize proportionally to waste
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: avoid forcing a new bin open if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when the item fits very poorly anywhere
    // (large item leaving tiny residual nowhere) — make empty bin mildly costly.
    if bin_residual == bin_capacity {
        score += 80.0 + 0.1 * item_size as f64;
        // But if item exactly halves capacity, a fresh bin is fine.
        if post_residual as f64 == bin_capacity as f64 / 2.0 {
            score -= 150.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty for large post_residual
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize creating dead space unusable by the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // Reward leaving room exactly for the next item
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor filling it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive if item is large and no tight fit exists
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 18.0; // default cost of opening a new bin
        if fill_ratio > 0.7 {
            score -= 20.0 * (fill_ratio - 0.7) / 0.3;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
        // Late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.15;
    }

    // Many open bins: discourage spreading, favor tightest bins
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 1.5;
    }

    // Reward using bins with small residual overall (avoid many tiny leftovers)
    if bin_residual != bin_capacity && post_residual <= 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted residual, but weight waste less as stream progresses
    // (late in stream, tighter packing matters more -> larger waste penalty).
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Non-linear polynomial coupling of normalized residual with progress:
    // mid-range residuals become less attractive as t grows (dead space).
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score += (poly * cap) * (1.5 - 2.0 * t);

    // Reward near-perfect fits with a smooth quadratic bonus.
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead: if next item fits exactly in post residual, reward heavily.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_q = 1.0 - (diff / cap).min(1.0);
        score -= 20.0 * fit_q * fit_q;
    }

    // Slight penalty for very many open bins late in stream (consolidation pressure).
    score += (open_bins_count as f64).ln() * 2.0 * t;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: integer division into capacity fractions.
    // Class 0 = perfect fit (post_residual 0) -> strong reward.
    // Classes group post_residual into bands of 10: [0,10) great, [10,20) ok, etc.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual / 10) as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Tight fits (post_residual < 10) are nearly perfect: reward.
    else if post_residual < 10 {
        score -= 60.0 - post;
    }
    // Awkward small-but-nonzero leftovers (10..=20) are dead space: penalize.
    else if post_residual <= 20 {
        score += 25.0;
    }
    // Harmonic decay reward for larger usable leftovers.
    score -= 40.0 / (1.0 + class);

    // Lookahead coupling: if the next item can exactly fill the post_residual,
    // this placement is ideal (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 {
                score -= 80.0; // chain leads to near-perfect fit
            } else if nxt_post <= 20 {
                score += 20.0; // chain creates dead space
            }
        } else {
            // Next item cannot use this bin's leftover: leftover likely wasted.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when the item is large and would leave
    // a well-shaped residual in a fresh bin, or when existing bins are very full.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // Penalize opening a new bin for small items.
        score += 200.0 * (1.0 - fill_frac);
        // Reward if it creates a harmonic-friendly residual (multiple of 10 bands).
        let new_class = (bin_residual - item_size) / 10;
        if new_class == 0 || new_class >= 2 {
            score -= 30.0;
        }
        // If many bins are open and mean residual is large, discourage new bins.
        score += 0.5 * open_bins_count as f64 + 0.3 * mean_residual;
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= (1.0 - post / cap) * 10.0;

    // Stream progression: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 10.0;
    }

    // Reward tight fits (small waste) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tight * tight;

    // Pressure from number of open bins: prefer reusing existing bins when many are open.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // (otherwise a new bin gets opened anyway).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap; dead space likely -> mild penalty scaled to gap
        if post_residual < 25 {
            score += 8.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it is a good filler.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.1 * dev;

    // Stream progression: early on, be slightly more willing to open bins (exploration),
    // later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin has large post_residual; make it less attractive
    // unless residual is genuinely large (big item leaving useful space).
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 60 {
            score -= 20.0; // big items justify a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when the current fit is poor.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0 && post_residual == bin_capacity - item_size;

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            // Perfect two-item completion: strongly favored.
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportionally, penalize leaving awkward small slack.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            if slack < 10.0 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space.
            let dead = next_item_size - post_residual;
            score += 8.0 * dead as f64 / 10.0;
        }
    }

    // Reward tight fits relative to mean residual.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mean_r {
        score -= 0.5 * (mean_r - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_r);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.4 * open_bins_count as f64;

    // Progress-dependent tightness pressure: later in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    if is_new_bin {
        // New bin baseline: only chosen when open bins score badly.
        score += 20.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let post = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post / resid.max(1.0));
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space that few item sizes can use.
    if post > 0.0 && post < 10.0 {
        score += 12.0; // tiny unusable sliver
    }
    if post >= 10.0 && post < 30.0 {
        score -= 4.0; // usable mid-range gap is fine
    }

    // Lookahead (k=2): reward if the next item fits into the resulting post residual,
    // penalize if the next item would need a fresh bin while this bin could have hosted both.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - post / cap); // chains nicely, keeps residual useful
        } else if nxt <= resid && nxt > post {
            score += 14.0; // placing here blocks an obvious pairing
        }
        // Big next item: keep a large residual bin available for it.
        if nxt > 50.0 && post < nxt && resid >= nxt {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.25 * item;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it moderately
    // unattractive so we only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * item;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins are open with large mean residual, reuse them instead.
        score += 0.05 * open_bins_count as f64 + 0.08 * mean_residual;
        // If the item is huge relative to capacity, a fresh bin gives clean packing.
        if item > 0.7 * cap {
            score -= 12.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor) but
        // break ties toward lower absolute post residual.
        score += 0.02 * (resid - item).abs();
        // Slightly prefer bins below mean residual (consolidate fullness).
        score += 0.05 * (mean_residual - resid).max(0.0);
    }

    // Late-stream pressure: near the end, avoid opening new bins at all costs.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.9 && bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let nitem = next_item_size as f64;

    // Base: penalize leftover space, scaled by stream progress (late leftovers hurt more)
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress);

    // Non-linear polynomial coupling between post_residual and progress
    let coupling = norm_pr * norm_pr * (0.8 + 1.2 * progress) * (1.0 - progress + 0.25);
    score += coupling;

    // Reward tight fits (small post_residual) with smooth cubic term
    score -= (1.0 - norm_pr).powi(3) * 0.6;

    // Lookahead: bonus if next item fits the post residual
    if nitem > 0.0 && nitem <= pr {
        score -= 0.8 * (nitem / cap) * (1.0 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Penalize spreading when many bins open; mild mean-residual alignment
    score += 0.05 * open_bins_count as f64 * norm_pr;
    score += 0.1 * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: prefer it only when it would hold large items well
    if bin_residual == bin_capacity {
        score = norm_pr * (2.5 - 1.5 * progress) - 0.5 * (it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // to common small item sizes (multiples of 10 are ideal dead space).
    let post_u = post_residual;
    if post_u == 0 {
        score -= 30.0; // perfect fill
    } else if post_u % 10 == 0 && post_u <= 30 {
        score -= 12.0; // small friendly residual
    } else if post_u % 10 == 0 {
        score += 4.0; // large leftover still usable, mild penalty
    } else {
        // awkward residual: penalize more the smaller it is
        let awkward = 20.0 * (1.0 - post / (0.35 * cap_f)).max(0.0);
        score += awkward;
    }

    // Modulo-10 harmony between post_residual and next item
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= post_u {
            // next item fits here: strong reward, tighter if exact class match
            score -= 15.0;
            if post_u % 10 == 0 && nx % 10 == 0 && post_u == nx {
                score -= 10.0; // exact harmonic match
            }
        } else {
            // next item cannot use this residual
            score += 6.0 + 0.15 * (nx as f64 - post);
        }
    }

    // Last-chance bin before opening a new one: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 + 0.5 * open_bins_count as f64 };
        let residual_gap = (mean_residual - post).max(0.0);
        score += 8.0 + fit_pressure - 5.0 * (1.0 - progress) + residual_gap;
        // opening a fresh bin is good when the current item is large
        score -= 0.1 * item_size as f64;
    }

    // Prefer bins tighter than the mean residual
    score -= 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small, hard-to-fill gaps: graded penalty
        score += 18.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Reward filling a bin completely or near-completely.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // consolidating into existing bins; few open bins -> new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline so it loses only when existing-bin fits
        // are genuinely good. Penalize more when many bins are already open.
        score += 25.0 + pressure;
        // If the next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 10.0;
        }
        // Late in the stream, opening new bins is less worthwhile.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 20.0;
        }
    } else {
        // Existing bin: slight bonus proportional to how far below the mean
        // residual this bin is (prefer filling emptier bins to balance? No —
        // prefer filling TIGHTER bins to consolidate, so penalize high residual).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Post-residual can't host the next item: mild penalty for stranding.
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: residual zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 150.0 - (slack as f64).min(100.0);
            if slack == 0 {
                score -= 500.0; // exact 2-step match
            }
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: minimize residual as usual
        score -= 50.0;
    }

    // Tight fit bonus: small relative slack in this bin.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 80.0 * (1.0 - tightness);

    // Compare against mean residual: prefer bins already below-average residual
    // (concentrate filling) unless it creates dead space.
    if (post_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 250.0 - 200.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // early stream: opening bins is cheap and useful for future flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    // Mild penalty for very large unusable residual (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny slivers are nearly dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual nonlinearly (dead space is quadratic pain).
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item also fits snugly afterwards.
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - next_fit / bin_capacity as f64);
    }
    // Penalize leaving a gap just below the next item (wasted near-fit).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, favor it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when existing
    // fits are poor or the item is small relative to a fresh capacity.
    if bin_residual == bin_capacity {
        // Mild baseline cost of opening a new bin, decaying as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - 0.5 * progress);
        // If many open bins exist with slack, discourage another bin.
        score += 0.6 * open_bins_count as f64;
        // Small item into a fresh bin wastes capacity.
        score += 0.4 * (bin_capacity - item_size) as f64;
    } else {
        // Reward using bins that already deviate from mean residual (consolidate slack).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 3.0 * (1.0 - dev / bin_capacity as f64);
    }

    // Prefer filling the fullest bins first (best-fit flavor).
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress
    let t = progress;
    score -= 18.0 * (1.0 - t) * fit * fit * cap;         // early: prefer tight fits
    score += 12.0 * t * pr * pr / cap;                  // late: penalize large leftovers
    score += 6.0 * fit * (1.0 - fit) * cap;             // mid-band residual smoothness

    // Dead-space penalty: residual too small for typical future items
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 8.0;
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Open-bin pressure via mean residual interaction
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions and modulo classes to detect "usable" leftovers.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction-of-capacity classes for the post residual.
    let post_frac = post / cap;

    // Dead-space penalty: leftovers that are too small to hold typical
    // items (harmonic class near 0) are heavily penalized.
    if post_frac < 0.05 {
        score += 60.0; // unusable sliver
    } else if post_frac < 0.10 {
        score += 25.0;
    } else if post_frac < 0.20 {
        score += 8.0;
    } else if post_frac >= 0.50 {
        score -= 20.0; // half-empty bin is a great leftover
    } else if post_frac >= 0.35 {
        score -= 10.0;
    }

    // Modulo-10 harmonic class: leftovers divisible into common item
    // granularities are more reusable.
    let pr = post_residual;
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division threshold: how many "medium" units (size 20) fit.
    let units = pr / 20;
    score -= (units as f64) * 4.0;

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; slight penalty if this bin
            // becomes near-full dead space.
            if post_frac < 0.15 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: score an empty bin by its "freshness" --
    // prefer opening a new bin only when all open bins would leave
    // terrible slivers.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted when many bins are open
        // and mean residual is fragmented.
        score = 55.0 + 0.05 * (open_bins_count as f64);
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 25.0; // open bins are nearly full; new bin is good
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins
    // as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_frac.min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward closing the bin exactly.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        // Dead space too small for any future item: strong penalty.
        score += 30.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item can still fit in the leftover space,
    // reward this placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins can fit,
    // with pressure scaling by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is necessary.
            score -= 60.0;
        }
    }

    // Mild global pressure to consolidate into fewer bins.
    score += open_bins_count as f64 * 0.4;

    // Reward placing larger items into this bin (tightness coupling).
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Prefer bins that deviate from the mean residual when they give tight fits.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tiny dead space after placement.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if (post_residual as u32) == next_item_size {
            score -= 55.0; // chain completion: this bin + next item = perfect fill
        } else if post_residual > next_item_size {
            let slack_after_next = post - nxt;
            if slack_after_next < 10.0 {
                score -= 20.0; // next item leaves near-perfect residual
            } else {
                score -= 8.0 * (1.0 - slack_after_next / 100.0); // mild chain reward
            }
        } else {
            // next item does NOT fit here: post residual is likely dead space
            let gap = nxt - post;
            if gap <= 10.0 {
                score += 12.0; // near miss: mildly penalize
            } else {
                score += 6.0 + 0.25 * gap; // stranded dead space penalty
            }
        }
    }

    // Compare post residual against mean residual: avoid making this bin
    // much worse than the fleet average.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual already,
    // but add extra penalty so we only open new bins when fits elsewhere are bad.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Still allow opening a new bin for large items with no fitting bins.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, having fresh bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference to fill nearly-full bins harder.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use:
    // dead space is bad when it is small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is huge
    // relative to capacity or current open bins are badly fragmented.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // Opening a new bin is penalized normally, but rewarded when the
        // item barely fits anywhere and open bins are fragmented.
        let item_ratio = item_size as f64 / bin_capacity as f64;
        let open_bonus = if item_ratio > 0.8 && fragmentation < 0.25 {
            -20.0 * (item_ratio - 0.8) * 5.0
        } else {
            0.0
        };
        score += 15.0 + open_bonus - 10.0 * fragmentation;
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if next_item_size as i64 > (post_residual as i64)
            && next_item_size as i64 > (bin_residual as i64 - post_residual as i64)
        {
            // Next item won't fit here anyway; neutral.
            score += 1.0;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (keep flexibility); late in the stream, consolidate tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score *= 1.0 + 0.3 * progress;

    // Mild penalty for proliferating open bins when mean residual is high
    // (bins are mostly empty -> prefer packing into existing ones).
    if mean_residual > 0.5 * bin_capacity as f64 && !is_new_bin {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fills (small post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Smooth stream-progress coupling: as the stream advances, tolerate
    // slightly larger residuals less (consolidation pressure grows).
    score *= 1.0 + 0.35 * progress * (post / cap);

    // Lookahead reward: smooth bonus if the next item could still fit here.
    if next_item_size > 0 {
        let slack = post - next_item_size as f64;
        if slack >= 0.0 {
            score -= 12.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // Penalize dead space proportionally to unusable gap.
            score += 0.25 * (-slack);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 8.0 * (item_size as f64 / cap);
    }

    // New-bin candidate (empty bin): penalize mildly so it wins only when
    // all open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.15 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins whose post state stays near
    // the fleet average (smooth variance-reduction term).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual ----
    // Class A: perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: post residual in small "reusable" bands (divisible-friendly).
    // Residuals that are multiples of common small sizes (10..=20) stay reusable.
    if post_residual >= 10 && post_residual <= 20 && post_residual % 5 == 0 {
        score -= 12.0;
    }
    // Class C: dead space 1..9 is nearly unusable (items >= 1 but tiny slots waste).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    // Class D: mid-range awkward residual (21..=34) — moderate penalty.
    if post_residual >= 21 && post_residual <= 34 {
        score += 6.0;
    }

    // ---- Lookahead coupling with next_item_size ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportional to tightness of the follow-up.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 20.0 / (1.0 + slack);
        } else {
            // Next item won't fit after placement: penalize more the closer it is to fitting.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 14.0;
            } else {
                score += 4.0;
            }
        }
        // Harmonic divisibility: if next item divides the post residual evenly, bonus.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    } else {
        // Last item: only perfect fit matters; mild reward for any fit.
        score -= 5.0;
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that can take the item; strongly favor it over opening a new bin.
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good placement exists.
        // Base penalty keeps it behind any decent fit.
        score += 30.0;
        // But if the stream is early and bins are fragmented, opening fresh is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        if fitting_bins_count <= 1 {
            score -= 55.0 * (1.0 - progress);
        }
        if fragmentation < 0.15 && open_bins_count > 4 {
            score -= 10.0;
        }
        // Perfect item for a fresh bin (item == capacity) — trivially good.
        if item_size == bin_capacity {
            score -= 500.0;
        }
    }

    // ---- Mild tie-break: prefer filling bins with larger existing load ----
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // ---- Progress-aware micro-adjustment: late in stream, waste hurts more ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftovers (below min item size 1..~20) are unusable.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when open bins exist,
    // stronger as stream progresses.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + 25.0 * (step_index as f64 / total_items.max(1) as f64);
    } else if bin_residual == bin_capacity {
        score += 10.0; // very first bin
    }

    // Prefer bins whose residual deviates from mean (consolidate space).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 20 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: reward when next item fits exactly into post_residual
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 600.0;
            } else if post_residual > next_item_size {
                // next item fits, penalize leftover after chaining
                let chain_left = post_residual - next_item_size;
                score -= 100.0 - (chain_left as f64) * 0.5;
            } else {
                // next item won't fit here: penalize small dead space more
                let dead = post_residual as f64;
                if dead < 10.0 {
                    score += 150.0 - dead * 5.0;
                }
            }
        }

        // Penalize leaving residual below the minimum item size (unusable dead space)
        if post_residual < 1 {
            score += 500.0;
        } else if post_residual <= 10 {
            score += (11.0 - post_residual as f64) * 20.0;
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 300.0;
        }

        // New-bin candidate: penalize opening a new bin unless this bin is a bad fit
        if bin_residual == bin_capacity {
            score += 250.0;
            // but if next item is large and post_residual too small, new bin is attractive
            if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
                score -= 350.0;
            }
        }

        // Coupling with mean residual: prefer bins tighter than average
        score += (mean_residual - bin_residual as f64) * 0.3;

        // Late in the stream: prefer tighter packing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += post_residual as f64 * 0.2 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 0.6 * (bin_capacity as f64 / (1.0 + tightness)) * 0.1;

    // Penalize large dead space: if post_residual is small but nonzero and below typical small item size,
    // it's near-perfect packing.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    // Last chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_fit_quality / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving residual too small for the known next item (dead space trap).
        score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Global state coupling: prefer filling bins when many bins are open (consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln() * 2.0;
    score -= open_pressure * (0.3 + 0.7 * progress) * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates below the mean (fill the emptier-but-usable bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: empty bin gets a mild penalty so we only open when necessary,
    // but a bigger penalty if the stream is near its end.
    if bin_residual == bin_capacity {
        let end_factor = 1.0 + 3.0 * progress;
        score += 25.0 * end_factor;
        // If next item is large and no open bin helps, opening a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with larger residual when post_residual equal (keep flexibility).
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 60.0 * poly * (0.5 + progress);

    // Penalize large dead space more aggressively as stream progresses
    score += 0.5 * (pr * pr) / cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= 20.0 * (-(pr as f64) / 15.0).exp();

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual could host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = if pr >= nx { 1.0 } else { 0.0 };
        let slack = ((pr - nx) as f64).abs();
        score -= 12.0 * fits * (-(slack / 20.0).powi(2)).exp();
        score += 4.0 * (1.0 - fits) * (nx / cap);
    }

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Smooth mean-residual coupling: prefer bins near the mean
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let q = bin_capacity / 4;
    let class = (post_residual % q) as f64;

    // Penalize residuals that fall in "hard-to-fill" low classes
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space
    }

    // Reward tight fits (small post residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Harmonic class bonus: residuals divisible by common item sizes (10,20,25,50)
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 5.0; }
    if post_residual % 50 == 0 { score -= 4.0; }
    score += class * 0.2;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 30.0; // perfect pair
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3; // dead space for next item
    }

    // New-bin candidate handling: only open new bin when current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_gap = mean_residual;
        if avg_gap > 25.0 && fitting_bins_count > 0 {
            score += 40.0; // keep using fragmented open bins
        } else {
            score -= 6.0 + 10.0 * (1.0 - progress);
        }
        // new bin with perfect modulo alignment for typical items
        if item_size % 10 == 0 { score -= 3.0; }
    }

    // Mild penalty for spreading across too many bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10] are nearly unusable
    // for future items (sizes >= 1 but typically chunky). Penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 11.0);
    }
    // Medium awkward gaps (11..25) get a milder penalty.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward near-perfect fits (very small post_residual is fine if it's 0).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // low-fill bins; encourage filling existing bins.
    let ob = open_bins_count as f64;
    score += 0.6 * ob * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean (fill the emptier ones less).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / 40.0);
    }
    // If next item cannot fit here, slight penalty for blocking.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate handling: only open a new bin when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 35.0 - 5.0 * progress;
        // If many bins are open and none fit well, opening is more acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally.
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Penalize dead space below the minimum item size (unusable gap).
    let dead = post_residual as f64 - 1.0;
    if dead > 0.0 {
        score += 0.05 * dead * dead / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit bias).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: mild penalty so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Slight preference for opening fewer bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (fitting_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Dead-space penalty: leftover space too small for the smallest item (size 1..100 range, assume ~10 typical).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward for a near-perfect chained fit.
        let chain_gap = post_residual - next_item_size;
        if chain_gap < 10 {
            score -= 20.0;
        }
    }
    // Penalize if next item does NOT fit the leftover (fragmentation risk), scaled by leftover size.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: this is the only open bin that fits -> strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
        if post_residual > 40 {
            score += 30.0; // wasteful last-chance use: soften the reward
        }
    }

    // New empty bin candidate: penalize so it's chosen only when open bins fit poorly,
    // but reduce penalty when open bins are very full / fragmented.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If mean residual is small (bins nearly full), opening a new bin is more acceptable.
        score -= 0.5 * mean_residual;
        // Early in the stream, opening bins is cheaper (more future items to consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If next item is large and current item fits poorly anywhere, new bin helps.
        if next_item_size > 60 && post_residual < 20 {
            score -= 25.0;
        }
    }

    // Mild preference for filling fuller bins among many open bins.
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64;

    // Penalize spreading across many open bins slightly (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr + 40.0 * pr_norm * pr_norm + 60.0 * pr_norm * pr_norm * pr_norm;

    // Smooth coupling with stream progress: tight fits matter more later in the stream.
    score *= 1.0 + 0.6 * progress;

    // Penalize bins whose residual deviates from mean residual (fragmentation pressure),
    // weighted smoothly by progress.
    let dev = (pr - mean_residual) / cap;
    score += 25.0 * dev * dev * (0.5 + progress);

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            let slack = (pr as f64 - nxt) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nxt - pr as f64) / cap;
            score += 30.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 + 30.0 * progress;
    } else {
        // Mild penalty for spreading across many fitting bins (encourage consolidation).
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: keep it unattractive unless the fit is genuinely poor
    // (large post_residual) or late-stream fragmentation is high.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 55.0 - 35.0 * item_norm - 25.0 * scarcity * progress;
        score += 20.0 * pr_norm * pr_norm;
    }

    // Small smooth penalty on very large open-bin counts (bin proliferation).
    score += 1.5 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste quantized by capacity eighths.
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth;
    score += match class {
        0 => -40.0,                       // near-perfect fit, strongly reward
        1 => -20.0,
        2 => -5.0,
        3 => 0.0,
        4 => 5.0,
        5 => 10.0,
        6 => 15.0,
        _ => 25.0,                        // large dead space penalty
    };

    // Modulo-4 harmony: post_residual divisible by 4 pairs well with small items.
    if post_residual % 4 == 0 {
        score -= 3.0;
    }
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward leaving room for the next item (harmonic pair).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 12.0 - (gap as f64).min(12.0);
            // perfect pair: post_residual == next_item_size exactly
            if gap == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; slight penalty for tight leftover
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should lose unless nothing fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; offset by expected utility
        score += 55.0;
        // late in stream, prefer reusing open bins more strongly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // if many open bins, discourage yet another
        score += (open_bins_count as f64).sqrt() * 4.0;
    }

    // Mean residual context: prefer bins deviating below mean (tighter bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.35 * dev;

    // Fraction-of-capacity harmonic tiers on item size.
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 6.0; // big items: place them, avoid stranding
    } else if frac < 0.2 {
        score += 2.0; // tiny items: keep them for better slots
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    }

    // Perfect fit: strongly reward consuming the bin completely.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 60.0;

    // Penalize leaving a gap that cannot fit the lookahead item (dead space
    // relative to the known future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing ones rather than spawning more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // New-bin candidate (empty bin): make it attractive only when this bin
    // would leave a bad gap or the fit is poor; otherwise keep existing bins.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin grows with how many are already open.
        score = 110.0 + open_bins_count as f64 * 4.0;
        // A new bin is fine if the item fits it almost exactly.
        if post_residual <= 5 {
            score -= 90.0;
        }
        // If no existing bin is a decent fit (large dead space elsewhere),
        // opening fresh is competitive.
        if post_residual >= 0 && item_size as f64 / bin_capacity as f64 > 0.85 {
            score -= 70.0;
        }
    }

    // Mild tie-breaker: prefer bins with below-average residual (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 12.0 - slack;
        } else {
            score -= 2.0 / slack;
        }
    }
    // Penalize creating dead space that neither the next item nor small items can use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Reward using a bin whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 5.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Favor bins with residuals near the mean (balanced packing), lightly.
    score -= 1.0 / (1.0 + (bin_residual as f64 - mean_residual).abs());

    // Late in the stream, prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Slight bias against opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_ratio * waste_ratio * (bin_capacity as f64);

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Exact residual match with next item: reserve this bin's remnant.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 12.0;
        } else {
            score += (gap as f64).ln() * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless
    // the item fits very poorly everywhere else or bins are numerous.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let crowding = (open_bins_count as f64 / 20.0).min(1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for new bin, reduced when many bins are open late in stream.
        score += 35.0 - 20.0 * crowding * progress - 10.0 * pressure;
        // If item is large, a fresh bin is more attractive.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Prefer bins with residuals below mean (consolidate small leftovers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild preference for more-filled bins as the stream progresses.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill * (step_index as f64 / (total_items.max(1) as f64));

    // Penalize leaving residuals in the awkward 20..40 dead zone.
    if post_residual >= 20 && post_residual <= 40 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post = post_residual as f64;

    // Base: prefer small post-residual (tight fit), smooth polynomial coupling with progress.
    let mut score = post * (1.0 + 0.5 * progress * post / cap);

    // Reward tight fits more strongly as stream progresses.
    score -= 20.0 * (1.0 - post / cap).powi(3) * (0.5 + progress);

    // Penalize large unusable dead space (post residual too small for smallest plausible item).
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * 2.0 } else { 0.0 };
    score += dead;

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits in post-residual (chaining), penalize otherwise.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0 + 6.0 * (1.0 - post_residual as f64 / cap);
        } else {
            score += 5.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin mildly, scaled by how many bins fit item
    // and mean residual; allow opening when existing bins have large residuals (poor fits).
    if bin_residual == bin_capacity {
        let base = 25.0 + 10.0 * (1.0 - progress);
        let relief = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).powf(0.7) * 6.0 * (1.0 - mean_residual / cap).max(0.0)
        } else {
            0.0
        };
        score = base - relief + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * 0.5; // fuller bins favored
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 20.0; // near-perfect fit leaves little dead space
    }

    // Harmonic class logic on post_residual: classify dead space by residue mod 10.
    // Residuals in [1..9] are "dead" for typical item sizes; classes mod 10 matter.
    let dead_class = post_residual % 10;
    if post_residual > 0 && dead_class != 0 {
        // penalize unusable slivers, worse when small
        let sliver = (dead_class as f64).min((10 - dead_class) as f64);
        score += 8.0 - sliver * 0.5;
    }
    if dead_class == 0 && post_residual > 0 {
        score -= 6.0; // residual divisible by 10 is reusable by many item sizes
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // harmonic fraction: next item fills a large fraction of the gap
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill_frac * fill_frac;
            // residue coupling: post_residual % next_item_size small => chainable
            let r = post_residual % next_item_size;
            if r == 0 {
                score -= 10.0;
            } else if r <= 3 {
                score -= 5.0;
            } else if r < next_item_size {
                score += 3.0;
            }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is poor
    // or the item would leave a bad harmonic class of dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of consuming a fresh bin
        score += 45.0;
        // but if placing here would leave a very awkward residual in an open bin,
        // opening a new bin becomes attractive
        let frac = item_size as f64 / bin_capacity as f64;
        if post_residual > 0 && post_residual < 10 {
            score -= 40.0; // poor fit in open bin -> prefer fresh bin
        }
        // late in stream with many open bins, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.7 {
            score += 15.0 * progress;
        }
        if frac > 0.9 {
            score -= 5.0;
        }
        let _ = mean_residual;
        let _ = open_bins_count;
    } else {
        // mild preference for bins below mean residual (balance load)
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small to fit typical future items
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // Next item fits this bin now but not after this placement -> penalize
        score += 5.0;
    }

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0 * (1.0 - progress);

    // Coupling with mean residual: penalize bins far from the mean residual
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit (or near-perfect) is extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or closely) matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Bin can host the next item too: reward tight chain fits.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 150.0;
            }
        } else {
            // Leftover space too small for next item: penalize dead space
            // proportional to how unusable it is.
            score += 40.0 * (1.0 - diff / bin_capacity as f64);
        }
    }

    // Prefer filling bins that are already relatively full (low residual
    // relative to mean residual) to consolidate waste.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 25.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 15.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    // Penalize opening new bins unless the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 300.0 - 200.0 * tightness - 50.0 * progress;
        // If the next item is small, a fresh bin wastes capacity.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 30.0;
        }
    }

    // Mild preference for fewer open bins overall (compactness).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize small dead space that no future item can use
    // (items are >= 1, so dead space of 0 is perfect).
    if post_residual > 0 {
        score += 2.0 / (post_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; slightly penalize leaving awkward gaps.
            score += 1.5;
        }
    }

    // Prefer filling bins that are already mostly full (consolidate waste).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 2.0 * fill_ratio;

    // Discourage opening new bins when many bins are open and mean residual
    // is large (spread waste across existing bins instead).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        if mean_residual > (item_size as f64) {
            score += 5.0;
        }
        // Early in the stream, new bins are cheaper; late, very expensive.
        score += 20.0 * progress * progress;
    }

    // Mild preference for bins below mean residual (balance the pool).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, prefer tight fills (penalize large residuals more);
    // later, allow larger residuals since bin count dominates.
    let tightness = (pr / c).powi(2);
    score += tightness * (1.0 - progress) * 8.0;
    score -= (pr / c) * progress * 4.0;

    // Cubic interaction: reward near-perfect fits (small post_residual) more strongly
    // as the stream matures.
    let fit_quality = 1.0 - (pr / c);
    score -= fit_quality.powi(3) * 6.0 * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual would be large.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 5.0 * (1.0 - gap / c);
        } else {
            score += 2.0;
        }
    }

    // Slight penalty when this bin's residual is far above the mean (fragmentation).
    score += ((bin_residual as f64 - mean_residual) / c).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr % 25; // residual harmonic class (C/4 granularity)
    // Dead-space penalty: residuals in awkward classes (1..=9) are hard to fill.
    if pr > 0 && class <= 9 {
        score += (10.0 - class as f64) * 2.5;
    }

    // Perfect fits are golden.
    if pr == 0 {
        score -= 50.0;
    }

    // Small residuals that exactly match a plausible future item are valuable:
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = post_residual - next_item_size;
        score -= 8.0 + (fit_gap as f64).min(10.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // this bin likely useless for the next item
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer tight fills: reward small post_residual relative to capacity fraction.
    let frac = post_residual as f64 / cap;
    score += frac * 10.0;

    // Penalize wasting a nearly-empty (fresh) bin on a small item unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 5.0 + item_size as f64 * 0.05;
    }

    // Late in the stream, consolidation matters more: prefer reusing open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0 * (open_bins_count as f64).ln().max(0.0);

    // Discourage spreading when mean residual is already high and this bin is above mean.
    if post_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space is worse if next item can't use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Pressure to fill open bins rather than proliferate.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly unless current item is large
    // and would leave an awkward gap in existing bins.
    if bin_residual == bin_capacity {
        score += 5.0 - (item_size as f64 / 20.0);
        if item_size >= 60 {
            score -= 6.0;
        }
    }

    // Late in stream, tighten up packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
