pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + progress);

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual close to item size (best-fit style, sharpened).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += gap * 0.3;

    // Global state coupling: when mean residual is high, encourage consolidation
    // into existing bins (penalize new-bin candidate implicitly via its large residual).
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus penalty that shrinks as stream ends.
        score += 20.0 + 15.0 * (1.0 - progress);
        // Opening a new bin is more attractive when many bins are nearly full
        // (mean residual low) and open bins are fragmented.
        score -= (mean_residual.max(0.0)).min(100.0) * 0.2;
        if open_bins_count > 0 && mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight reward when it is below mean residual (fills emptier bins first),
        // counterbalanced when bin is very full (avoid wasting near-full bins on small items).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        if post_residual == 0 {
            score -= 15.0; // perfect fill bonus
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space (dead space minimization).
    let mut score = post;

    // Non-linear tightness reward: strongly reward small post_residual,
    // scaled by stream progress (tight packing matters more later).
    let tight = (1.0 - post / cap).powi(3);
    score -= 25.0 * tight * (0.5 + 0.5 * progress);

    // Smooth polynomial coupling of post_residual with progress:
    // mid-stream, moderately-filled bins are fine; late-stream, big leftovers hurt.
    let norm_post = post / cap;
    score += 12.0 * norm_post * norm_post * (0.3 + 0.7 * progress) * cap / 100.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or many bins already fit the item poorly.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let big_item = item / cap;
        let crowd = (open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0))).min(3.0);
        score += 15.0 - 12.0 * big_item * big_item - 2.0 * crowd - 5.0 * progress;
        // If next item could combine with the leftover, mild penalty stays.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score += 3.0;
        }
    } else {
        // Lookahead: reward if next item fits into the resulting residual (chaining).
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= post {
                score -= 6.0 * (1.0 - (post - nxt) / cap);
            } else {
                score += 2.0 * (nxt - post) / cap;
            }
        }
        // Prefer bins with residual below mean (consolidate fullness).
        score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits (small post_residual) non-linearly.
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // Harmonic class: penalize post_residuals that are "waste-prone" classes.
    // Residuals in (0,10] are nearly dead space; residuals in [50,100) are reusable.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 18.0 * (11.0 - pr as f64); // near-dead space penalty
    } else if pr >= 40 && pr < 60 {
        score -= 6.0; // mid-class residual still usable by mid-size items
    }

    // Modulo logic: residual divisible into useful chunks (multiples of 10/20)
    // pairs well with typical item sizes; reward such "harmonic" residuals.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 25.0; // perfect chain fit
        } else if slack <= 10 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here anyway; mild penalty for stranding capacity.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is poor (large waste)
    // or no open bin is a good harmonic match. Penalize opening new bins when
    // open bins are relatively empty (mean residual high).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size.min(bin_capacity)) as f64;
        let poor_fit = (post_residual as f64) > 30.0;
        score += 20.0; // base cost of a new bin
        if poor_fit {
            score -= 25.0; // worth it if this fit is bad
        }
        if mean_residual < 15.0 {
            score -= 8.0; // existing bins nearly full anyway
        }
        if progress < 0.2 {
            score -= 3.0; // early stream: allow spreading
        }
        let _ = waste;
    }

    // Mild preference for filling bins that are already more filled
    // (reduces bin fragmentation across many partially-filled bins).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Tie-break by open bin count: prefer compacting into fewer bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Items are >= 10, so a post_residual in 1..=9 is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Gaps in 10..20 are only usable by small items; mild penalty scaled by stream progress.
    else if post_residual >= 10 && post_residual < 20 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Open-bin pressure: discourage spreading across many open bins slightly,
    // but reward using an existing bin vs. opening a new one.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor filling the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // every existing fit would create bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 25.0 + open_bins_count as f64 * 0.5;
        // If the next item is large, a fresh bin preserves a big residual for it.
        if next_item_size > 50 && item_size <= 40 {
            score -= 30.0;
        }
        // If only one bin fits and it would leave bad dead space, fresh bin is OK.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if this placement leaves exactly room for the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If post_residual is just barely too small for the next item, penalize slightly.
    else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly-zero post residual is excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Exact match: next item fills this bin perfectly -> strong reward.
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward proportional to tightness of the chain.
            score -= 150.0 * (1.0 - diff / (bin_capacity as f64));
            // Bonus if chained fit leaves a still-usable residual.
            let post2 = post_residual as u32 - next_item_size;
            if post2 <= 10 {
                score -= 100.0;
            }
        } else {
            // Next item cannot follow into this residual: penalize dead-space risk,
            // scaled by how much the residual overshoots the next item.
            score += 0.5 * (post - nxt);
        }
    } else {
        // Last item: just minimize residual.
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    let post = post_residual as f64;
    if post < mean_residual {
        score -= 0.3 * (mean_residual - post);
    } else {
        score += 0.3 * (post - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to capacity (better to pack big items fresh) and many bins are open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 - 100.0 * frac - 20.0 * progress;
        // If many bins are open and none fit well, opening fresh is more acceptable.
        if open_bins_count > 4 {
            score -= 10.0;
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill achieved by placing the item here
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    // Non-linear reward: square the normalized post-residual waste so that
    // small leftovers are strongly favored over moderate ones.
    let waste_norm = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_norm) * (1.0 - waste_norm) * 20.0;

    // Penalize dead space that cannot plausibly hold future items.
    // Future items are >= 1, so any leftover could matter, but leftovers
    // smaller than a typical small item are nearly unusable.
    if post_residual > 0 && post_residual < 12 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly prefer this bin (perfect two-item chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: the tighter, the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will not fit here after this placement: mild penalty
            // proportional to how badly it misses, encouraging bins whose
            // post-residual remains useful.
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 * (miss / bin_capacity as f64);
        }
    } else {
        // Last item of the stream: just minimize post residual hard.
        score -= 30.0 * (1.0 - waste_norm);
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // using it avoids opening a new bin — usually desirable.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Global pressure: when many bins are open relative to stream progress,
    // prefer packing into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + progress * 50.0);
    score += pressure * 0.8;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin; finishing it off is good (releases a nearly full
    // bin). If it is far above the mean, it is roomy — placing here wastes
    // its flexibility.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Early in the stream, keep bins flexible: penalize very tight fits less
    // than later, since future items may need moderate space. Later in the
    // stream, squeeze aggressively.
    score += (1.0 - progress) * waste_norm * 10.0;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Its raw score is bin_capacity (100), which is already high. Add a
    // calibrated penalty so a new bin is chosen only when no open bin offers
    // a decent fit (i.e., when all open-bin scores exceed this threshold).
    if bin_residual == bin_capacity {
        score += 60.0;
        // Slightly cheaper to open a new bin early (fresh capacity useful
        // for the long remaining stream) than late.
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = norm_post * (1.0 + 0.8 * t) - 0.5 * norm_post * norm_post * (1.0 - t) + 0.25 * norm_post * norm_post * norm_post * t;

    let mut score = poly * cap;

    // Reward tight fits smoothly (small post residual is good, scaled by progress).
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (2.0 + 3.0 * t);

    // Penalize creating dead space relative to mean residual of open bins.
    score += 0.4 * (post - mean_residual).abs() / cap;

    // Last-chance bin: strongly favor using it (avoid opening new bin).
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * t;
    }

    // Lookahead: reward bins whose post residual can fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (1.0 - (post - nxt) / cap);
        } else {
            score += 0.8 * (nxt - post) / cap;
        }
    }

    // Mild penalty on many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64 * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: exact-fill classes are golden ---
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Exact fit: huge reward
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Harmonic classes via integer division on post_residual
        // class 0: pr == 0 (exact), class 1: tiny dead space, class 2: half-cap, class 3: large residual
        let class = pr / (bin_capacity / 4); // 0..=4 harmonic bands
        match class {
            0 => score -= 40.0,            // pr < 25: nearly perfect fill
            1 => score += 15.0,            // pr in [25,50): awkward mid band
            2 => score -= 10.0,            // pr in [50,75): half-cap residual is reusable
            _ => score += 5.0,             // large residual: fine but not urgent
        }
        // Dead-space penalty grows superlinearly for unusable slivers
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        }
        // Modulo coupling: residual divisible by common item sizes (10,20,25,50) is reusable
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 20 == 0 && pr % 10 != 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it packs the remainder
            let npr = pr - next_item_size;
            score -= 30.0 * (1.0 - npr as f64 / cap);
            if npr % 10 == 0 { score -= 10.0; }
        } else {
            // next item won't fit here: mild penalty if this residual becomes stranded
            if pr < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // as the stream fills / many bins are open with poor residuals
    if bin_residual == bin_capacity {
        score = 55.0 + 0.25 * open_bins_count as f64;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // but if mean residual across open bins is small (all crowded), new bin is fine
        score -= (mean_residual / cap) * 20.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Mild pressure to keep the number of open bins low
    score += 0.05 * open_bins_count as f64;

    // Tiny tie-break on residual so lower waste always wins among equals
    score += frac * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100) are pure waste.
    if post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 20 {
        // Small gaps may still fit tiny items; mild penalty scaled by gap smallness.
        score += (20 - post_residual) as f64 * 0.8;
    } else if post_residual == 0 {
        // Perfect closure: strongly reward.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin used by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Reward near-exact fill relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // placing here wastes the large residuals elsewhere; slight penalty.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.1;
    } else {
        score += dev * 0.05;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Post-residual unusable by next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // New-bin candidate handling: only attractive when existing bins are full-ish
    // or this item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let avg_needed = mean_residual.max(0.0);
        if item_size as f64 > avg_needed * 0.9 {
            score -= 12.0; // large item: fresh bin is fine
        } else {
            score += 15.0; // small item: prefer squeezing into open bins
        }
        // Early stream: opening bins cheap; late stream: expensive.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
