pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tightness of the fit: fraction of the bin consumed by this item
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let fill_after = 1.0 - (post_residual as f64 / bin_capacity as f64);

    if is_new_bin {
        // Base penalty for opening a new bin; reduce it when the item is large
        // (large items deserve fresh space) or when no open bin fits well.
        score += 35.0 * (1.0 - fit_ratio);

        // If the item leaves a residual that a typical next item could use,
        // a new bin is more attractive.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0;
        }

        // Late in the stream, prefer closing bins tightly: new bins are cheaper
        // to justify when many open bins already exist with scattered residuals.
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 8.0;
        }
    } else {
        // Reward tight fits strongly (small post_residual relative to item size)
        score -= 20.0 * fit_ratio * fill_after;

        // Perfect fit bonus
        if post_residual == 0 {
            score -= 30.0;
        } else if post_residual < 10 {
            score -= 15.0;
        }

        // Penalize creating dead space that the lookahead item cannot use
        if next_item_size > 0 {
            let nxt = next_item_size as u32;
            if post_residual > 0 && nxt > post_residual {
                score += 0.25 * (nxt - post_residual) as f64;
            } else if nxt <= post_residual && nxt > 0 {
                // residual usable by next item: mild reward
                score -= 4.0;
            }
        }

        // Last-chance bin: if this is the only bin that fits, strongly prefer it
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Fragmentation pressure: if mean residual across open bins is small,
        // squeeze this item into existing space rather than wasting it.
        if mean_residual > 0.0 {
            let waste = (post_residual as f64 - mean_residual).abs();
            score += 0.05 * waste;
        }

        // Early in the stream, be slightly conservative (keep bins balanced);
        // late in the stream, pack aggressively.
        score -= 10.0 * progress * fill_after;
        score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear penalty on mid-range waste
    let mut score = pr;
    score += 8.0 * (pr_norm * (1.0 - pr_norm)) * cap * 0.5;

    // Stream progress coupling: penalize waste more early, reward tight fits late
    score += 12.0 * (1.0 - progress) * pr_norm * pr_norm * cap;
    score -= 6.0 * progress * (1.0 - pr_norm) * (1.0 - pr_norm) * cap;

    // Mean residual interaction: prefer bins deviating from mean when mean is high
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * (1.0 + progress) * mean_residual / cap;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Congestion: fewer fitting bins -> discourage leaving many open bins unused
    let fit_frac = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 1.0 };
    score += 4.0 * (1.0 - fit_frac) * pr_norm * cap;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_quality = if nxt <= pr { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= 10.0 * fit_quality * fit_quality;
    }

    // New-bin candidate: mild penalty so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10.
    let pr = post_residual as u32;
    let residue = (pr % 10) as f64;
    // Dead space penalty: small nonzero leftovers (1..=9) are hardest to fill.
    if pr > 0 && pr < 10 {
        score += 40.0 - residue * 2.0;
    } else if pr == 0 {
        // Perfect closure is ideal.
        score -= 25.0;
    } else {
        // Larger leftovers: reward leftovers that are multiples of 10 (likely reusable).
        let harmonic_bonus = (pr / 10) as f64 * 3.0;
        score -= harmonic_bonus;
        // Penalize odd/prime-ish residues slightly.
        score += residue * 0.5;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect chaining
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack / 10.0); // tighter fit favored
        } else {
            // next item cannot use this bin's leftover; penalize proportional to excess
            score += ((next_item_size - pr).min(30)) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has high raw score; adjust so it's chosen
    // only when fits are poor. Reward opening a new bin when many bins are open and
    // current fit is bad.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: leftover capacity 100, well-structured (multiple of 10).
        score = 55.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        // More open bins -> slightly favor consolidation instead of new bin.
        score += (open_bins_count as f64).ln() * 4.0;
    } else {
        // Existing bin: bonus relative to how full it already is (fraction of capacity used).
        let used_frac = 1.0 - (bin_residual as f64) / cap;
        score -= used_frac * 15.0;
        // Penalize spreading across many bins when this fit is loose.
        if post_residual as f64 > mean_residual {
            score += 3.0;
        }
    }

    // Stream progression: late in the stream, prefer tight packing / closure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr == 0 {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residual gaps that are too small to ever be useful
    // (but nonzero) are worse than a perfect fit or a large residual.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: heavy penalty scaled by how close to zero it is.
        score += (10.0 - pr) * 2.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item if it fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that blocks the next item: extra dead-space penalty.
        score += 6.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 12.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.35 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // in existing bins is very poor (large post_residual or blocked lookahead).
    if bin_residual == bin_capacity {
        // Base handicap so open bins are normally preferred.
        score += 30.0;
        // Relax handicap if mean residual across open bins is large
        // (open bins are already full of dead space).
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        // Relax further late in the stream.
        score -= progress * 10.0;
    }

    // Mild attraction toward bins with residuals close to the item (best fit).
    score -= (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term.
    // Add lookahead coupling: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.5;

        // Strong reward if next item fits perfectly into the post residual.
        if next_item_size == post_residual {
            score -= 30.0;
        }
        // Penalize if next item cannot fit in post residual (dead space for next step).
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: penalize bins whose post residual deviates
    // badly from the current mean residual (keeps residual distribution compact).
    let post_f = post_residual as f64;
    let deviation = post_f - mean_residual;
    score += deviation * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // moderately attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Prefer opening a new bin when the item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Late-stream pressure: as the stream progresses, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    // Penalize creating tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight penalty scaling with open bins count to consolidate load.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches 0
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into the post-residual (chained placement)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra reward for small leftover after the hypothetical chain
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use, scaled by dead-space size
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += 3.0 * (dead / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() / 10.0;
    score += pressure * (1.0 + progress);

    // Compare residual to mean residual: bins with below-mean residual are "dying" — fill them first
    if (bin_residual as f64) < mean_residual {
        score -= 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // baseline penalty; tight fits elsewhere will beat this
        score += 20.0;
        // but late in the stream with few bins, opening may be fine
        score -= 10.0 * progress;
        // if next item is large, a fresh bin is valuable
        if next_item_size as f64 >= 0.6 * bin_capacity as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    let mut score = r;

    // Smooth non-linear coupling: penalize small-but-nonzero residuals more as stream progresses
    let tightness = 1.0 - rn;
    score -= (r * r / cap) * (0.5 + 1.5 * progress) * tightness;

    // Reward exact / near-exact fills smoothly
    score -= 40.0 * (-r / 8.0).exp();

    // Lookahead coupling: prefer bins whose post-residual can take the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if r >= nxt {
            score -= 15.0 * (1.0 - (r - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * (1.0 - (nxt - r) / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += (open_bins_count as f64).ln() * (rn * cap - mean_residual).abs() * 0.05;

    // New-bin candidate: make it slightly unattractive unless residuals are badly fragmented
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it occupies
    let item_class = item_size / 17; // 5 harmonic classes over 1..=100
    let post_class = post_residual / 17;

    // Reward placements whose post-residual falls in a "useful" class
    // (small residuals are dead space; mid residuals can host medium items)
    match post_class {
        0 => score -= 12.0,                       // near-perfect fit
        1 => score += 6.0,                        // 17..33 dead-ish zone
        2 => score -= 4.0,                        // 34..50 usable for mid items
        3 => score += 2.0,
        _ => score -= 1.0,                        // large residual, still flexible
    }

    // Coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead-friendly: subtract proportional reward
            score -= 8.0 * (1.0 - (next_item_size as f64 / post_residual as f64).min(1.0));
        } else {
            // post residual cannot host next item -> penalize dead space
            score += 5.0;
        }
    }

    // Modulo threshold on post_residual: residuals near multiples of 10
    // are "clean" slots for typical small items
    let rem = post_residual % 10;
    if rem >= 1 && rem <= 3 {
        score += 4.0; // awkward sliver
    } else if rem >= 7 {
        score -= 3.0; // close to a clean boundary
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tighter bins when many bins are open (limit bin proliferation)
    let tightness = 1.0 - (bin_residual as f64 / cap);
    score -= 6.0 * tightness * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate handling: make an empty bin mildly attractive only
    // when the current item is large or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bias = 18.0 - 14.0 * item_class as f64 / 4.0 + 6.0 * progress;
        score += bias.max(2.0);
    }

    // Mild deviation from mean residual: prefer bins near the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Strongly penalize gaps that cannot fit the next item (lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= 20.0 * (1.0 - post_residual as f64 / item_size as f64).max(0.0);
    }
    // Exact fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }
    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0;
    }
    // Slight preference for bins below mean residual (consolidating waste)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: post_residual can hold next item with little slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable remainder.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize creating tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure
    }

    // Compare against mean residual: bins with more slack than average are better targets.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, be more willing to open new bins (keep residual large);
    // later, consolidate to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when many bins are open or early on.
        score -= 8.0 * progress + 0.2 * open_bins_count as f64;
    } else {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize tight fits less (good packing), reward filling bins nearly full.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would exactly consume post-residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a residual just below the next item (blocking).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let avg_open_residual = mean_residual;
        // If existing bins are mostly empty-ish, discourage a new bin.
        score += 15.0;
        score -= progress * 5.0;
        if avg_open_residual < item_size as f64 {
            score -= 10.0; // no bin really fits well, allow new bin
        }
        // Late in stream, prefer closing out open bins.
        score += (1.0 - progress) * 10.0;
    }

    // Mild preference for bins with residual close to item size (best fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.15;

    // Slight preference for fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and post-fit residual fraction
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_frac = post_residual as f64 / cap;
    let fit_frac = item_size as f64 / cap;

    // Non-linear penalty on dead space: post_residual squared, amplified late in the stream
    score += 0.6 * (post_residual as f64) * post_frac * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 12.0 * (1.0 - post_frac) * (1.0 - post_frac);

    // Penalize bins whose residual is far above the mean (fragmentation)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Coupling: if the next item fits snugly into the post residual, reward it
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap) * (1.0 - progress);
        } else {
            score += 0.15 * (-gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many bins when post residual is wasteful
    score += 0.05 * open_bins_count as f64 * post_frac;

    // Smooth bias favoring larger items into fuller bins
    score -= 5.0 * fit_frac * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: geometric penalty on wasted fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Perfect or near-perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic class logic: classify post_residual by integer division
    // into "usable" vs "dead" classes relative to common item sizes.
    // Small residuals (< 10) are dead space since items >= 1 but large
    // items dominate; class thresholds at multiples of 10.
    let dead_class = post_residual / 10; // 0 => dead space (<10)
    if dead_class == 0 && post_residual > 0 {
        score += 18.0; // residual too small for typical items
    } else if dead_class >= 1 && dead_class <= 3 {
        score -= 6.0; // moderately reusable residual
    }

    // Modulo coupling with next item: if next item fits exactly into
    // post_residual, big bonus (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            // reward small chain waste, harmonic in chain_waste
            score -= 20.0 / (1.0 + chain_waste as f64);
            // modulo class: does next item divide post_residual nicely?
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; this bin is a dead end for lookahead
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.85;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        } else if item_size >= 60 && post_residual == 0 {
            // large item that would perfectly fill... but a fresh bin
            // can't be post_residual==0 unless item==capacity; keep mild
            score -= 5.0;
        }
        // Prefer opening new bins early in the stream when few bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // Discard new-bin option when many bins already open and mean
        // residual is high (fragmentation risk).
        score += open_bins_count as f64 * 1.5 + mean_residual * 0.3;
    } else {
        // Mild preference for filling bins with larger residuals first
        // (best-fit-like), scaled by number of competing bins.
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
        // Slight penalty when many bins fit the item (less urgency),
        // encouraging consolidation into scarcer options.
        if fitting_bins_count > 2 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical future items) is heavily penalized super-linearly.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Zero post_residual is a perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tight fits (small but usable gap) get a mild bonus.
    if post_residual > 0 && (post_residual as f64) < 25.0 {
        score -= 5.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // but when this bin is the last chance, reward using it heavily.
    score += open_bins_count as f64 * 1.5;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // bin's fit is bad (large post_residual) or residual is already tiny.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by wasted-space avoidance.
        score += 12.0 + open_bins_count as f64 * 2.0;
        if item_size >= 50 {
            score -= 8.0; // large items start fresh bins more willingly
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement; if next item cannot fit post-residual but
    // would fit elsewhere, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from mean
    // in the direction of better packing (lower residual than mean is good).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: early on, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact match with the next item is highly desirable.
            let gap = post_residual - next_item_size;
            score -= 30.0 - (gap as f64).min(30.0);
            // Perfect chain (post_residual == next_item_size) gets the biggest bonus.
            if gap == 0 {
                score -= 15.0;
            }
        } else {
            // Leftover cannot host next item: penalize proportionally to wasted potential.
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.5;
        }
    }

    // Penalize small dead space (unusable slivers) relative to smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit of the current item.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin normally...
        score += 35.0;
        // ...unless the item is large (would leave a big, reusable residual anyway)
        // and few bins can fit it.
        if tightness > 0.6 {
            score -= 20.0 * tightness;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average (good packing),
    // penalize dipping far below the mean (creating isolated dead space).
    let dev = mean_residual - post_residual as f64;
    if dev < 0.0 {
        score += (-dev) * 0.3;
    } else {
        score -= dev * 0.1;
    }

    // Late in the stream, prefer closing bins tightly (fewer residual fragments).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a non-linear coupling.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize dead space: post_residual that no future item (min size 1..100) can fill well.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 15.0 * dead * (1.0 - dead); // worst around half-empty leftovers
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = (next_item_size as f64) / (post_residual as f64);
            score -= 25.0 * chain_quality; // good chaining
        } else {
            // next item cannot fit here: mild penalty scaled by how far off we are
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing existing capacity.
    let mean_r = mean_residual / (bin_capacity as f64);
    score -= 10.0 * mean_r;

    // Time horizon: late in the stream, prefer closing bins tightly (less fragmentation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * tightness;

    // New-bin candidate handling: opening a new bin is expensive early, cheap late.
    if bin_residual == bin_capacity {
        let new_bin_cost = 55.0 * (1.0 - 0.5 * progress) - 8.0 * open_bins_count as f64 * 0.1;
        // If no open bin fits well (post_residual large relative to capacity), new bin looks better.
        score += new_bin_cost;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post-residual (tight fit), scaled non-linearly.
    let mut score = post * (1.0 + 0.008 * post);

    // Non-linear coupling: wasted-space penalty grows with stream progress
    // (dead space matters more later), modulated by relative fill.
    let fill = 1.0 - post / cap;
    score += 12.0 * progress * (1.0 - fill).powi(3);

    // Reward near-perfect fits with a smooth quadratic bonus.
    if post <= 5 {
        score -= 8.0 * (1.0 - post as f64 / 6.0).powi(2);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: bonus if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as f64 <= post {
            score -= 5.0 * (1.0 - gap / cap).powi(2);
        } else {
            score += 2.0 * (gap / cap);
        }
    }

    // Penalize bins far from mean residual (fragmentation smoothing), smooth term.
    let dev = (post - mean_residual).abs();
    score += 0.02 * dev * dev / (1.0 + progress);

    // New-bin candidate: neutral-ish baseline that competes with poor fits.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly when many bins are open and
        // the item would leave a tight fit elsewhere; smoothed via progress.
        score = cap * (0.35 + 0.35 * progress) + 0.008 * cap * cap * 0.0;
        score += 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a "good" residue
    // (small, or large enough to fit common small items) are preferred.
    let pr = post_residual;
    let good_residue = (pr % 10) as f64; // modulo-10 class of leftover
    score += 0.6 * (good_residue / 9.0);

    // Integer-division thresholds on post_residual: leftover that cannot fit
    // even the smallest item (1) is fine; leftover that fits only tiny items
    // is dead space.
    if pr > 0 && pr < 10 {
        score += 12.0; // dead-space penalty: unusable sliver
    } else if pr < 20 {
        score += 5.0; // risky zone
    } else if pr >= 50 {
        score -= 3.0; // roomy leftover, still versatile
    }

    // Perfect fit reward (harmonic: post_residual == 0).
    if pr == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: penalize if leftover exactly matches next item
    // (good), or if leftover is just barely too small for next item (bad).
    if next_item_size > 0 {
        if pr >= next_item_size && pr <= next_item_size + 10 {
            score -= 8.0; // leaves room for the known next item
        } else if pr > 0 && pr < next_item_size && pr < 15 {
            score += 6.0; // blocks next item in this bin
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it
    // wins only when open bins are all poor fits.
    if bin_residual == bin_capacity {
        score = 35.0 + 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 5.0; // next item pairs well in a fresh bin
        }
    }

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable sliver: strong penalty proportional to its uselessness.
            score += (10 - post_residual) as f64 * 6.0;
        } else if post_residual < 25 {
            // Small gap: likely dead unless a very small item arrives.
            score += (25 - post_residual) as f64 * 2.5;
        } else if post_residual >= 40 {
            // Large residual remains usable: reward keeping flexible space.
            score -= (post_residual - 40) as f64 * 0.8;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Tight fit reward: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= (fill_ratio - 0.7) * 40.0;
    }

    // Open-bin pressure: discourage proliferating bins; favor consolidating
    // into existing bins when many are already open.
    if bin_residual < bin_capacity {
        // This is an existing (non-new) bin: reward it more when bins are plentiful.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    } else {
        // New-bin candidate: penalize opening bins when existing bins are usable
        // and few bins are open.
        score += 8.0 + (open_bins_count as f64) * 0.5;
        // If this is the only fitting option, opening a new bin is less bad.
        if fitting_bins_count <= 1 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Next item cannot use the leftover: mild penalty for bad sequencing.
            score += 2.0;
        }
    }

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it is becoming an outlier (concentrating waste elsewhere); slight penalty.
    let dev = mean_residual - post_residual as f64;
    if dev > 20.0 {
        score += (dev - 20.0) * 0.3;
    }

    // Late-stream tightening: as the stream progresses, prefer near-exact fits
    // to avoid leftover fragments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize if next item cannot fit into post_residual (dead space risk)
        if post_residual < next_item_size && post_residual > 0 {
            let waste_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += waste_ratio * 40.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin late in stream only for large items creating good residual structure
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            score -= 10.0;
        }
    }

    // Early stream: slightly discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that can never be filled by typical items (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }
    // If next item cannot fit into post_residual, mild penalty for wasting the gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin fits or fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = open_bins_count as f64 * 2.0;
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 + 20.0 * (1.0 - (item_size as f64 / bin_residual as f64)) };
        score += 40.0 + open_penalty + fit_pressure - 10.0 * progress;
    }

    // Mild preference for bins below mean residual (keeps residuals balanced).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Slight time-awareness: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits via smooth non-linear decay of residual
    let mut score = pr as f64;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes costlier (quartic growth)
    score += 40.0 * x * x * (0.5 + progress) * (1.0 - progress * 0.3);

    // Reward near-perfect fits with smooth bump (gaussian-like around x=0)
    score -= 25.0 * (-(x * x) / 0.01).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x);
    }

    // Lookahead: if next item fits exactly in post residual, reward strongly
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-(diff * diff) / 50.0).exp();
        // penalize leaving residual that neither fits next item nor is tiny
        if next_item_size as f64 > pr && pr > 0.0 {
            score += 15.0 * x * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across too many open bins (encourage consolidation)
    score += (open_bins_count as f64) * 0.5 * (0.5 + progress);

    // Prefer bins below mean residual slightly (balance-aware smooth term)
    score += (mean_residual - pr) * 0.1;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 45.0 - 40.0 * x; // empty-bin score tied to item size via post residual
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals that fall into "useless" harmonic classes.
    // Small residuals (< ~10) are nearly dead; mid residuals are usable.
    if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly preferred
    } else if post_residual < 10 {
        score += 12.0; // dead space
    } else if post_residual <= 20 {
        score += 4.0;
    }

    // Modulo-class reward: residuals that are multiples of common small
    // item sizes (5,10) are more likely reusable.
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 6.0;
    } else if post_residual > 0 && (post_residual % 5 == 0) {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += 2.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate logic: empty bin gets a baseline score that keeps it
    // attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; opening fresh is fine when others are tight
        score = 45.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    // Prefer filling bins that are already relatively full (low residual).
    score -= 5.0 * (1.0 - frac);

    // Mean-residual coupling: when mean residual is high, prefer consolidating
    // into bins below the mean (tighter bins).
    if pr < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 15.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to fit any plausible item are wasted.
    if post_residual < 10 {
        score += 120.0; // unusable sliver
    } else if post_residual < next_item_size && next_item_size > 0 {
        score += 35.0 + (next_item_size - post_residual) as f64 * 0.8;
    } else {
        // Reward residual that can still host the lookahead item exactly well
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
            // bonus if the next item would fill the bin almost perfectly
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 12.0;
            }
        }
    }

    // Tight fit reward: penalize proportionally to wasted fraction
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: with many open bins, prefer reusing existing space
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 6.0;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fit_quality > 0.85 {
            // large item: fresh bin is fine (almost full immediately)
            score -= 10.0;
        } else {
            // opening a new bin for a small item wastes capacity
            score += 45.0 + (100.0 - item_size as f64) * 0.5;
        }
        // if existing bins are fragmented (high mean residual spread), new bin less bad
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    }

    // Mild progression bias: early in stream, be conservative with bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for the smallest plausible item (1..100 range, min 1).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // 2-step lookahead: reward if the next item fits exactly or well into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain match is heavily rewarded.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 15.0; // exact fit of the lookahead item
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    }

    // Compare against mean residual: prefer bins that keep residual near/below the mean
    // (consume crowded bins first, keep roomy bins for big future items).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, be slightly more willing to open new bins (keep options open).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly when many bins are open or late in stream,
        // reward when the fit elsewhere is poor (post_residual small => poor fit).
        score += 12.0 * progress + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // a fresh bin perfectly chains the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: if the next item can also fit in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }
    // If next item would leave this bin nearly perfect (post_residual == next_item_size), strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fitting bins exist and residual is small.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are very fragmented or item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Penalize new bin mildly; reduce penalty when open bins can't help (high fragmentation, big item).
        let mut new_bin_score = 45.0;
        if fragmentation > 0.5 && item_size > bin_capacity / 2 {
            new_bin_score -= 30.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 50.0;
        }
        // Late in the stream, prefer closing out existing bins.
        new_bin_score += 10.0 * progress;
        score += new_bin_score;
    } else {
        // Slight preference for bins with less residual relative to the mean (consolidate waste).
        score += 0.1 * ((bin_residual as f64) - mean_residual);
    }

    // Penalize creating tiny unusable slivers unless the next item could use them.
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;

    // Base: prefer tight fills (low post_residual), with non-linear penalty
    let mut score = pr;

    // Smooth dead-space penalty: residuals that are too small to fit future
    // items are wasted; penalize quadratically in the low-residual regime.
    let usable_floor = 10.0_f64.min(cap);
    let dead = (usable_floor - pr).max(0.0);
    score += 2.5 * dead * dead / cap;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, demand tight packing.
    let tightness = 1.0 + 3.0 * progress * progress;
    score *= tightness;

    // Interaction: post_residual relative to mean residual across open bins.
    // Placing into a bin whose post_residual diverges from the mean creates
    // fragmentation; smooth penalty on squared deviation.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward heavily (perfect chain).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
        // If next item cannot fit in post_residual, mild penalty for
        // creating unusable space relative to lookahead.
        if pr < next_item_size as f64 {
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin unless existing fits
    // are poor. A fresh bin has residual == capacity; its raw post_residual
    // is already large, but add a smooth extra cost scaled by how many
    // open bins could have taken the item.
    if (res - cap).abs() < 0.5 {
        score += 30.0 + 5.0 * (fitting_bins_count as f64).max(0.0);
    }

    // Mild reward for consolidating into bins with many open bins present
    // (reduce bin count pressure) — smooth in open_bins_count.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Modulo-based harmonic class: residuals divisible by common item sizes are reusable.
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 && r > 0 {
                bonus += 8.0;
            }
        }
        bonus
    };
    score -= reusable(post_residual);

    // Penalize dead space in the awkward band (1..10) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Next-item lookahead: reward leaving space that fits the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward if next item exactly fills the bin afterward
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // penalize creating a gap the next item cannot use
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual would be huge
    // relative to stream progress and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_vs_mean = (mean_residual - post) / cap;
        score += 30.0
            - 25.0 * progress
            - 0.15 * open_bins_count as f64
            - waste_vs_mean * 20.0;
        // large items justify a fresh bin
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Tightness coupling: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 15.0;

    // Mild preference to spread across many open bins when mean residual is high.
    if mean_residual > cap * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when this bin can also fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from many open bins: discourage opening new bins when crowded.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are fragmented,
        // heavily penalized when many bins are already open.
        score += open_bins_count as f64 * 3.0 + 20.0 * progress;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins below mean residual (fill emptier bins less).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strong reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * usage;
        } else {
            // next item won't fit here: penalize leaving a gap that may become dead space
            let gap = post_residual as f64 - next_item_size as f64;
            score += 50.0 + 0.3 * gap;
        }
    }

    // Penalize small unusable residuals (dead space) relative to mean residual
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }
    score -= (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 300.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 100.0; // pair large items together in fresh bin
        }
    }

    // Slight preference for tighter bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - item_size as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() + 1.0;
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        let fit_penalty = if post_residual < 10 { 0.0 } else { 10.0 };
        score += 35.0 + 10.0 * crowding - 20.0 * (1.0 - waste) + fit_penalty;
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling bins with larger residuals when mean residual is high (fragmentation risk)
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    } else if bin_residual != bin_capacity {
        score += 3.0;
    }

    // Early stream: allow more bins open (keep flexibility); later: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual); Late: tolerate larger residuals
    // since fewer chances remain to fill small gaps.
    let poly = pr * pr / (cap * cap); // normalized quadratic dead-space term
    score += poly * 12.0 * (0.4 + 0.6 * (1.0 - progress));

    // Smooth interaction: residual fraction times progress polynomial.
    let rf = pr / cap;
    let shape = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 8.0 * rf * shape;

    // Penalize bins whose residual is far above the mean (fragmented state),
    // coupled non-linearly with post_residual.
    let mean_gap = (mean_residual - pr) / cap;
    score += 5.0 * mean_gap * mean_gap * mean_gap * cap;

    // Lookahead: reward leaving room exactly for the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let d = (pr - ns) / cap;
        score -= 10.0 * (-8.0 * d * d).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - rf);
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64 * rf;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is the post residual?
    // Class 0: exact fit (post_residual == 0) -> best possible.
    // Class 1: leftover fits small items (<= 20) -> highly reusable.
    // Class 2: leftover in mid band -> moderately reusable.
    // Class 3: large awkward leftover -> penalize.
    let post = post_residual;
    let harmonic_class: u32 = if post == 0 {
        0
    } else if post <= 20 {
        1
    } else if post <= 50 {
        2
    } else {
        3
    };

    // Modulo-style coupling: leftover divisible into common item sizes is good.
    let reusable = (post % 10 == 0) || (post % 25 == 0) || (post >= 10 && post <= 40);

    match harmonic_class {
        0 => score -= 60.0,                 // perfect fit: strongly favored
        1 => score -= 25.0,                 // small leftover still useful
        2 => {
            if reusable { score -= 12.0; } else { score += 10.0; }
        }
        _ => score += 22.0,                 // big dead space penalty
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / cap;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size <= post {
            // next item fits, but how snugly?
            let slack = (post - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty proportional to mismatch
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline offset so we
    // only open a new bin when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If many open bins are nearly full, a fresh bin is more attractive.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than the average residual (good packing pressure).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res).min(30.0);
    } else {
        score += 0.3 * (res - mean_residual).min(30.0);
    }

    // Mild penalty for hoarding too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect or near-perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Favor bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that the next item just barely misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.35 + 0.4 * progress);

    // Prefer bins with residual near the mean (balanced usage) mildly.
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals that become dead space.
    let dead_threshold = 9.0;
    if post_residual > 0 && post_residual < 10 {
        score -= dead_threshold; // small leftovers are fine (near-perfect fit)
    }
    if post_residual >= 10 {
        // waste grows superlinearly with unusable gap
        score += (post_residual as f64).powi(2) * 0.01;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 8.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // extra reward if next item exactly fills the remainder
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize leaving a gap next_item could
            // have used if we placed differently (mild)
            score += 1.5;
        }
    }

    // Time horizon: early in the stream, be more conservative about fragmenting
    // bins (many items remain); late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * tightness;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer using
    // existing capacity rather than opening new bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.2;
    }
    if mean_residual > item_size as f64 * 1.5 {
        score -= 2.0;
    }

    // New-bin candidate: empty bin has full residual. Only attractive when the
    // item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // large items are fine to start fresh
        score -= (item_size as f64 / bin_capacity as f64) * 14.0;
        // if several bins fit, opening a new one is wasteful
        if fitting_bins_count > 1 {
            score += 8.0;
        }
        // late in the stream, avoid opening bins for small items
        score += (1.0 - progress) * 0.0 + progress * (bin_capacity - item_size) as f64 * 0.05;
    }

    // Discourage leaving residuals that no typical item (>=1) can use well:
    // residuals of exactly 0 are perfect.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post residual), with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, waste is cheap (favor filling fresh bins loosely); later, waste is costly.
    let progress_weight = 0.35 + 1.65 * progress * progress;
    score += progress_weight * 40.0 * (x * x * x - x * x);

    // Reward near-perfect fits with a smooth quadratic bonus scaled by progress.
    let tightness = 1.0 - x;
    score -= 12.0 * (1.0 + progress) * tightness * tightness * tightness;

    // Penalize bins whose residual deviates from the mean residual (fragmentation pressure).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead coupling: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx) / cap.max(1.0);
        score -= 10.0 * (1.0 - gap.abs().min(1.0)) * x;
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 25.0 * x * x;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: dead space that no future item (1..=100) can fill
        // is only truly dead if smaller than the minimum item size; otherwise it's a slot.
        let progress = step_index as f64 / total_items.max(1) as f64;

        // Penalize small unusable residuals (dead space)
        if post_residual < 10 {
            score += 500.0 * (10 - post_residual) as f64;
        }

        // Reward residuals in "harmonic" classes that pair well with common item sizes:
        // residuals divisible by common divisors (mod classes) of capacity
        let pr = post_residual;
        if pr % 10 == 0 { score -= 60.0; }        // multiples of 10 pair with decade sizes
        if pr % 25 == 0 { score -= 40.0; }        // quarter-capacity classes
        if pr % 50 == 0 { score -= 30.0; }
        if pr % 3 == 0 { score -= 10.0; }
        if pr % 7 == 0 { score -= 5.0; }

        // Coupling with lookahead: if next item fits exactly into post_residual, big reward
        if next_item_size > 0 && next_item_size == pr {
            score -= 400.0;
        } else if next_item_size > 0 && next_item_size <= pr {
            // reward if next item leaves again a class-friendly residual
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 80.0; }
            if pr2 % 25 == 0 { score -= 50.0; }
            score -= (pr2 as f64) * 0.3;
        } else if next_item_size > 0 {
            // next item cannot follow into this bin; mild penalty scaled by tightness
            score += 30.0 + (pr as f64) * 0.2;
        }

        // Last-chance bin: strongly prefer using it before opening a new bin
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 250.0;
        }

        // Many open bins: discourage spreading residual waste
        score += mean_residual * 0.15 * (open_bins_count as f64).ln().max(1.0);

        // Early in stream: keep bins tight; late: tolerate imperfect fits
        score *= 1.0 + 0.5 * (1.0 - progress);
    }

    // New-bin candidate: neutral-ish baseline, only attractive when alternatives are bad
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: residuals below the minimum item size (1..~20)
    // are pure waste, so add a steep penalty that grows as post_residual shrinks.
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits: if the item nearly fills the bin, strongly subtract.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= fill_ratio * 30.0;
    }

    // Exact / near-exact closure bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open bins pressure: penalize creating new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 8.0;
        // Opening a new bin is more acceptable early in the stream when the stream
        // is short relative to items, but costly later.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // Mild penalty per open bin to encourage consolidation into existing bins.
        score -= 2.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement
    // (chaining placements into the same bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins whose post_residual is close to the mean
    // residual (keeps residual distribution balanced), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Prefer placing into bins with small residuals when the item is large
    // (large items should go into tight bins, leaving big residuals for small items).
    if item_size > 50 && bin_residual < 70 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.01;

    // 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after hypothetical placement
            let slack_after_next = post_residual - next_item_size;
            score -= 5.0;
            score += slack_after_next as f64 * 0.3;
        } else {
            // next item does NOT fit in the leftover: penalize proportionally to mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += mismatch * 0.4;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && next_item_size > 0 {
            score += 25.0;
        } else if open_bins_count > 0 {
            score += 10.0;
        }
    }

    // Late in the stream, consolidate: favor existing bins more strongly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // dead space that no future item can plausibly use.
    let mut score = post;

    // Waste penalty: dead space below the smallest possible item (1) is pure loss,
    // but very small residuals (< ~15) are usually unusable -> extra penalty.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 1.5;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Perfect chain: subtract reward proportional to how snugly next item fits.
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Next item cannot follow here: mild penalty scaled by gap size.
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 20.0;
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> favor consolidating into fuller bins (small residual).
    let frag = (open_bins_count as f64).ln().max(0.0);
    score -= frag * (res / cap) * 3.0;

    // Time horizon: early in the stream, keep bins flexible (mild penalty for
    // very tight fits); late in the stream, pack tightly without mercy.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 5.0 * (1.0 - post / cap);
    score += (1.0 - t) * 2.0 * (post / cap);

    // Mean-residual anchor: bins deviating far below the mean residual are
    // already well-filled; reward pushing them further toward closure.
    score -= ((mean_residual - post).abs() / cap) * 2.0;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It must lose against any reasonable fit, but win when all fits are terrible.
    if bin_residual == bin_capacity {
        score = cap * 0.85 + item * 0.3;
        if fitting_bins_count == 0 {
            score -= cap; // nothing fits anywhere: new bin is mandatory
        } else if post + item as f64 <= cap {
            // only open a new bin if every existing fit leaves bad dead space
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    score -= 40.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.5 + progress);

    // Penalize dead space quadratically (unusable small residuals)
    score += 25.0 * fit_norm * fit_norm * fit_norm;

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 10.0 * fit_norm;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * fit_norm;

    // Mean-residual coupling: bins far below mean residual are less attractive
    score += 0.3 * (mean_residual - pr).max(0.0);

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are wasteful
    if bin_residual == bin_capacity {
        score = pr + 20.0 - 40.0 * (1.0 - fit_norm) * (0.3 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is "harmonious"
    // with common item sizes (multiples of 10 / small divisors) are more useful.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = (pr % 10 == 0) as f64 * 6.0
            + (pr % 5 == 0) as f64 * 3.0
            + (pr % 2 == 0) as f64 * 1.5;
        score -= harmonic;
    }

    // Dead space penalty: residuals too small for the smallest item (1..10)
    // under unknown distributions; penalize residuals in awkward low band.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // fraction of post-residual consumed by next item
            let frac = next_item_size as f64 / pr as f64;
            score -= 15.0 * frac;
        } else {
            // next item cannot fit here; slight penalty scaled by waste
            score += 3.0;
        }
    }

    // Last-chance bin: only fitting bin left, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: empty bin. Prefer opening a new bin only when the
    // item is large relative to capacity or open bins are congested.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_tightness = 1.0 - mean_residual / bin_capacity as f64;
        score = 60.0
            - 30.0 * load_frac
            - 25.0 * congestion
            - 15.0 * mean_tightness
            + if next_item_size > 0 { (next_item_size as f64 / bin_capacity as f64) * 10.0 } else { 0.0 };
    }

    // Mild progression term: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer filling bins tighter than the mean residual (reduce spread).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size 10), so heavily penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps just above 10 are also risky if the next item cannot use them.
    if post_residual >= 10 && post_residual < 20 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 25.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportional to waste.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over spreading; when few bins are open, tolerate new-bin opening.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * pressure * (bin_residual - post_residual) as f64 / cap;

    // Prefer bins tighter than average (small residual relative to mean).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin should only win when the item
    // fits poorly everywhere else. Give it a mild default penalty that tight
    // fits in existing bins will beat, but that poor fits will not.
    if bin_residual == bin_capacity {
        score += 5.0;
        if post_residual as f64 > cap * 0.4 {
            score -= 10.0; // large item: a fresh bin is fine
        }
    }

    // Late in the stream, waste matters more (no time to recover gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but penalize leftover slack after it.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * slack_after_next;
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(80.0);
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when item is huge or
    // the new bin's post-residual perfectly matches the next item.
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size >= 70 {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    }

    // Slight penalty for wasting a very large bin on a small item.
    if item_size * 4 < bin_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.25;
        } else {
            // Reward bins that can still host the next item.
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins have plenty of residual space.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        score += 8.0 + 20.0 * pressure;
    } else {
        // Slight preference for fuller bins as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, non-linearly
    let mut score = pr as f64;

    // Polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (0.5 + progress);
    score += 40.0 * poly;

    // Tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= (item_size as f64 / cap) * tightness * (10.0 + 30.0 * progress);

    // Penalize large unusable residuals (dead space) with smooth quadratic
    let dead = if pr < 10.0 { 0.0 } else { (pr - 10.0) as f64 };
    score += 0.02 * dead * dead / cap;

    // Last-chance bin bonus (only bin that fits)
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose residual matches next item
    if next_item_size > 0 {
        let diff = (pr as f64 - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - diff / cap).max(0.0) * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.1 * open_bins_count as f64 * progress * x;

    // New-bin candidate: penalize unless residuals are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 25.0 * mean_residual / cap * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let cls = (post_residual % 10) as f64; // last-decade class
    score += 0.6 * cls;

    // Integer division thresholds: post_residual bands
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else if post_residual > 50 {
        score += 8.0; // leaving a half-empty bin is wasteful
    }

    // Tightness reward: fraction of capacity consumed by this placement
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Lookahead: does the next item fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // harmonic compatibility: next item lands in a good class too
            let compat = (post_residual % next_item_size.max(1)) as f64;
            score -= 6.0 + 0.15 * compat.recip().min(1.0) * 10.0;
            score -= 0.1 * next_item_size as f64;
        } else {
            score += 4.0; // next item can't follow here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    if fitting_bins_count > 1 {
        // competition: prefer bins with smaller residual among fitters
        score += 0.05 * bin_residual as f64;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + 30.0 * pressure - 10.0 * progress
            + 0.2 * mean_residual - 0.3 * item_size as f64;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild open-bin pressure: prefer packing into existing bins
    score += 0.02 * open_bins_count as f64;

    // Mean residual coupling: if open bins are already tight, reward this bin more
    score -= 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "unusable" if it's too small for the smallest plausible item (1..100 unknown dist,
    // assume items >= ~10 typical) — penalize gaps in the [1, 12] band superlinearly.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 8.0;
    }
    // Mid-range dead space (13..25) mildly penalized.
    if post_residual > 12 && post_residual <= 25 {
        score += (post_residual as f64 - 12.0) * 1.5;
    }

    // Perfect fit bonus: nothing left, or exactly enough for the lookahead item.
    if post_residual == 0 {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If the lookahead item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }
    // Penalize if post_residual is a trap: nonzero but smaller than the next item AND smaller than
    // any typical item — that space is likely wasted.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bins pressure: when many bins are open, prefer tightening fills (low post_residual),
    // when few bins are open, opening/spreading is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the best existing fit is bad.
    // Give the empty bin a moderate baseline so tight fits in open bins beat it.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55;
        // If no other bin really fits, the new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= tightness * 12.0;
        // Prefer bins with residual below the mean residual (they are the "tight" ones).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Post-residual can still fit the next item -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Small leftover after the next item would also fit: bonus for tight chaining.
        let two_left = post_residual as i64 - next_item_size as i64;
        if two_left >= 0 && (two_left as u32) < 10 {
            score -= 5.0;
        }
    }

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when existing bins fit well enough.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, new bins are cheaper; late, prefer filling open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If the next item is large, an empty bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Slight preference for fewer open bins (consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < item_size.max(10) {
        score -= 5.0; // residual could still hold a small item
    }

    // Lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra reward if next item fills bin nearly exactly
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if post_residual
            // becomes stranded waste relative to mean residual
            if (post_residual as f64) < mean_residual * 0.5 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer consolidation.
    if open_bins_count > 3 {
        score += 0.4 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin unless the fit in
    // existing bins is poor (post_residual small) or bins are congested.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = post_residual == bin_capacity - item_size;
        if !poor_fit_elsewhere {
            score += 20.0 + 0.3 * open_bins_count as f64;
        }
        // Opening a new bin is more attractive late in the stream when
        // mean residual is small (existing bins are nearly full).
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild bonus for bins whose residual is above average (use the roomy ones first).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

    // Prefer exact-ish fills: reward when item consumes most of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Core: quadratic coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * pr_norm)
        - 6.0 * (1.0 - progress) * (pr_norm * pr_norm);

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - pr).max(0.0) / cap;
        score += 18.0 * unusable * (1.0 + progress);
        // Reward if post residual exactly accommodates next item
        let fit_next = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score -= 8.0 * fit_next * fit_next * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins vs compacting
    score += 0.6 * (open_bins_count as f64).ln1p() * pr_norm;

    // Prefer bins whose residual is close to mean residual (balance)
    score += 0.15 * (pr - mean_residual).abs() / cap;

    // Slight bonus for tight fits (small post residual relative to capacity)
    score -= 5.0 * (1.0 - pr_norm).powi(3);

    // New-bin candidate: neutral-ish baseline, penalize early opening, allow late
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 10.0 * progress;
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residues that are "nice" fractions
    // of capacity (multiples of 25) are more reusable than odd residues.
    let class = post_residual % 25;
    let class_penalty = match class {
        0 => -8.0,
        1 | 5 | 10 | 15 | 20 => -3.0,
        _ => 2.0 + (class as f64) * 0.1,
    };
    score += class_penalty;

    // Integer-division threshold: tiny unusable residues are dead space,
    // but only penalize if the lookahead item cannot use them either.
    if post_residual < 10 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 15.0 };
        score += dead;
    }

    // Lookahead coupling: reward if next item fits the post residual,
    // penalize otherwise (scaled by how close it is to fitting).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tight = (post_residual - next_item_size) as f64;
            score -= 6.0 + tight * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity when
    // open bins have slack; penalize the empty-bin call accordingly.
    if bin_residual == bin_capacity {
        let slack = mean_residual.max(0.0);
        score += 10.0 + slack * 0.25 + (open_bins_count as f64) * 0.5;
        // Early in the stream, new bins are naturally needed; soften.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
    }

    // Mild preference for tighter fits relative to mean residual state.
    score += (post - mean_residual).max(-50.0).min(50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (typical item range 10..80, but be conservative
    // for unknown distributions with items as small as 1) are wasted.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 4 {
        score -= 25.0;
    }

    // Sweet spot: residual that still fits a mid-sized item is valuable.
    if post_residual >= 10 && post_residual <= 40 {
        score -= 8.0;
    } else if post_residual > 60 {
        // Large leftover is fine (flexible), mild reward.
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid bin proliferation); with few bins, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open new bin
        } else if fitting_bins_count == 1 {
            score += 10.0; // keep existing last-chance bin
        } else {
            score += 12.0; // prefer packing into open bins
        }
    }

    // Slight time-decay: later in stream, be marginally more conservative.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: bins with residual above mean are more "usable" targets.
    let rel = post_residual as f64 - mean_residual;
    score += 0.08 * rel;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item is large and nothing fits well, a fresh bin is attractive.
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual - item_size) {
            score -= 10.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Slight penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fills (post_residual close to 0)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // mild preference among many fitting bins toward tighter ones (already captured),
        // small penalty to diversify when many options exist
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space the next item cannot use: penalize proportionally to waste
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Global state: penalize placements into bins when many bins are already open
    // and mean residual is high (fragmentation pressure)
    score += 0.05 * open_bins_count as f64;
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate handling: opening a fresh bin should only win when it is
    // genuinely better; add a dynamic barrier that shrinks late in the stream
    if bin_residual == bin_capacity {
        let barrier = 25.0 + 20.0 * (1.0 - progress);
        score += barrier;
        // But if no open bin fits and next item is large, soften the barrier
        if fitting_bins_count == 0 && next_item_size > post_residual {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // non-linear coupling of post-residual with stream progress
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);
    // reward tight fits (small post_residual) more strongly late in the stream
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.3 + 0.7 * progress);
    // penalize dead space relative to mean residual of open bins
    score += 0.08 * (pr - mean_residual).abs() * (1.0 + progress);
    // lookahead: reward residual that still fits next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    // new-bin candidate: penalize unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals near multiples of
    // common item sizes are more reusable. Reward residuals that fall in
    // "good" integer-division classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity classes for post residual (harmonic buckets).
    let frac = pr / cap;
    let class = (frac * 10.0).floor(); // 0..9 bucket
    // Buckets near 0 are dead space; buckets near small reusable sizes are fine.
    match class as u32 {
        0 => score += 40.0,                 // nearly full, dead space
        1 | 2 => score -= 25.0,             // small residual: fits tiny items well
        3 | 4 | 5 => score -= 12.0,         // mid residual: flexible
        6 | 7 => score -= 5.0,
        _ => {}                              // large residual: bin mostly empty, neutral
    }

    // Integer-division coupling: does post_residual cleanly divide by
    // next_item_size (perfect lookahead fit)? Strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 30.0;
        } else {
            // Partial fit quality: how much of next item fits.
            let fit_frac = next_item_size as f64 / post_residual;
            score -= 15.0 * fit_frac;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to wasted potential.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize creating residual that no typical item (10..80 multiples of 5)
    // can exploit: residual < 10 is dead space.
    if post_residual < 10 {
        score += 25.0;
    }

    // Harmonic threshold on residual vs mean: bins with residual far below
    // mean are tight; prefer filling tight bins first (best-fit already does
    // via post_residual, add coupling).
    if pr < mean_residual {
        score -= 3.0 * (mean_residual - pr) / cap;
    } else {
        score += 3.0 * (pr - mean_residual) / cap;
    }

    // New-bin candidate: only attractive when nothing fits well or stream early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_alternatives = fitting_bins_count == 0
            || (post_residual as u32 == bin_capacity && item_size > bin_capacity / 2);
        if poor_alternatives {
            score -= 20.0;
        } else {
            // Prefer consolidation as bins accumulate.
            score += 15.0 + 10.0 * (open_bins_count as f64).ln() + 20.0 * progress;
        }
    }

    // Modulo-class bonus: residual that is a multiple of 5 (common size
    // granularity) is more reusable than odd residuals.
    if post_residual % 5 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot hold even the smallest plausible item (1..10)
    // is wasted space; make it quadratic.
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * (10 - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the
    // post_residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0 - gap as f64;
        } else {
            score -= 5.0;
        }
    }
    // Penalize if next item does NOT fit in post_residual and post_residual
    // is small enough to be nearly dead space anyway.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new bins; favor filling existing ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual != bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: penalize proportionally to how many bins
        // are already open and how tight the stream is.
        score += open_pressure * 2.0 + 5.0;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin population balanced and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in the stream, tighten up: prefer tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64) * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // good but imperfect chain
        } else {
            // next item cannot fit here: penalize wasted post_residual
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 20.0 * waste * waste;
        }
    } else {
        // last item: pure tightness fit
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual relative to mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev; // prefer bins whose residual becomes below-average (tight packing)

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless no decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in stream, allow new bins a bit more readily
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 10.0 * (1.0 - progress);
        // if next item is huge and would need a fresh bin anyway
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference to fill nearly-full bins to close them out.
    if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tight fit), non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 + 0.05 * slack;
    } else if next_item_size > post_residual {
        // Penalize leaving a residual that is useless for the next item,
        // scaled by how much dead space is created.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        } else {
            score += 0.03 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Penalize the empty bin moderately, more so when
    // many bins are already open or mean residual is large.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let mean_waste = (mean_residual / bin_capacity as f64).max(0.0);
        score += 10.0 + 2.0 * pressure + 15.0 * mean_waste;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, more so when mean residual is high
        // (consolidation pressure).
        let mean_waste = (mean_residual / bin_capacity as f64).max(0.0);
        score -= 1.5 + 3.0 * mean_waste;
    }

    // Prefer filling bins that are already relatively full (small residual),
    // reducing fragmentation of large residuals.
    let residual_frac = (bin_residual as f64) / (bin_capacity as f64);
    score += 3.0 * residual_frac * residual_frac;

    // Mild time-varying exploration term to break ties differently over the
    // stream horizon (deterministic, grounded in step/total).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * ((progress * std::f64::consts::PI).sin());

    // Exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: quadratic penalty on wasted residual (dead space grows quadratically)
    let mut score = pr + 40.0 * fit_frac * fit_frac;

    // Smooth non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more (less time to reuse slack)
    let tightness = 1.0 - fit_frac;
    score -= 25.0 * progress * tightness * tightness;
    score += 15.0 * (1.0 - progress) * fit_frac;

    // Lookahead: if next item fits the post-residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack_after_next = (pr - nx) / cap;
            score -= 20.0 * (1.0 - slack_after_next) * (1.0 + progress);
        } else {
            // penalize leaving residual that next item cannot use
            score += 8.0 * ((nx - pr) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly when open bins exist and mean residual is healthy
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let mean_frac = mean_residual / cap;
            score += 25.0 + 30.0 * mean_frac * mean_frac - 20.0 * progress;
        } else {
            score -= 10.0;
        }
    } else if bin_residual < item_size {
        score += 1000.0;
    }

    // Mild penalty for many open bins (fragmentation pressure)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity bands.
    // Waste classes: 0 (perfect), 1..=9 (dead zone), 10..=25 (usable small),
    // 26..=50 (medium), >50 (large usable).
    if post_residual == 0 {
        score -= 40.0; // perfect fit, strongly favored
    } else if post_residual <= 9 {
        score += 25.0; // dead space: nearly unusable for items >=10
    } else if post_residual <= 25 {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Modulo-arithmetic harmonic coupling: post_residual close to a multiple
    // of 10 pairs well with common item sizes (10..80 ranges).
    let mod10 = post_residual % 10;
    if mod10 == 0 && post_residual > 0 {
        score -= 8.0; // clean multiple of 10: high chance next item nests
    } else if mod10 >= 1 && mod10 <= 2 {
        score += 10.0; // awkward sliver on top of dead-zone risk
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 / (1.0 + tightness); // nested fit reward
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 9 {
            score -= 12.0; // still better than a fresh bin for a bad fit
        } else {
            score -= 20.0;
        }
    }

    // New-bin candidate: residual == capacity. Only attractive when no open bin
    // gives a decent fit (i.e., all fits would leave big waste) or many bins
    // already open and mean residual is low.
    if bin_residual == bin_capacity {
        let waste_if_forced = if fitting_bins_count >= 1 {
            // best-case waste among open bins is unknown; proxy via mean_residual
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        if fitting_bins_count == 0 {
            score = -50.0; // must open a new bin
        } else if waste_if_forced > 40.0 {
            score = -30.0; // open bins would waste a lot; fresh bin better
        } else {
            score = 120.0 + post_residual as f64; // prefer existing bins
        }
        // Late in stream, slightly prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (size 1) are still usable, but very small gaps
    // (1..=5) are effectively dead weight -> strong penalty.
    if post_residual > 0 && post_residual <= 5 {
        score += 40.0;
    } else if post_residual > 5 && post_residual <= 10 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Tightness ratio: favor bins where the item fills a large fraction of
    // the residual space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the gap: mild penalty proportional to gap size
            score += 0.15 * (post_residual as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out; penalize opening new bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it only if the
        // item is large relative to capacity (few future placement options)
        // or there are no real alternatives.
        score += 55.0 + 4.0 * pressure;
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Slight reward for reusing existing bins, scaled by open-bin count.
        score -= 2.0 * pressure.min(15.0);
    }

    // Stream progression: early in the stream keep bins flexible (avoid
    // leaving tiny residuals that fragment future choices); late in the
    // stream prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fill_ratio;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier fragment; penalize leaving it as an odd gap.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 15.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 120.0 - 0.8 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to the next item's need.
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening new bins when open bins exist and fit reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + open_bins_count as f64;
    }

    // Late in the stream, tighten packing (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (bin_capacity as f64) * 0.9;

    // Penalize large dead space nonlinearly: residuals that can't fit typical items are wasteful
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.02;
    }

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving a residual that can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.05;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.12;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (post_residual as f64) / (bin_capacity as f64) };
        score += 30.0 - 25.0 * pressure;
        // More open bins => mild extra reluctance to open another
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins) when mean is small
    let res = bin_residual as f64;
    let dev = res - mean_residual;
    score += dev * 0.08;

    // Time horizon: early in stream, be more frugal with bins; late, allow looser packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    // Utilization reward: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: penalize residuals too small for the next item
    if next_item_size > 0 && (pr as u32) < next_item_size {
        score += 12.0 * (1.0 - progress) + 6.0;
    } else if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    // Deviation from mean residual: prefer balanced bins
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: baseline competitive score
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress - 10.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "useful" residue
    // classes (small, re-fillable sizes) are rewarded.
    let pr = post_residual;
    let class = pr % 10; // decade residue class
    let useful = match class {
        0 => 1.0,              // exact fill — perfect
        1..=3 => 0.8,          // near-perfect, tiny waste
        4..=7 => 0.3,          // medium leftover
        _ => 0.0,              // 8..=9 residue: awkward dead space
    };
    score -= 12.0 * useful;

    // Integer-division thresholds: how many "typical" small items still fit?
    let slots = pr / 10;
    score -= 2.0 * slots as f64;

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly-ish into the leftover
            let gap = (pr - next_item_size) % 10;
            let bonus = if gap == 0 { 10.0 } else if gap <= 3 { 6.0 } else { 3.0 };
            score -= bonus;
        } else {
            // leftover too small for next item — penalize proportionally to closeness
            let miss = (next_item_size - pr) as f64;
            score += 0.5 * miss.min(20.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home
    // (i.e., current residual is large relative to item, poor fit).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // large items justify a fresh bin; small items should reuse open bins
        score += 25.0 * (1.0 - tightness);
        score -= 5.0 * (open_bins_count as f64).ln();
        // penalize new bins early in the stream when mean residual is still high
        score += 0.3 * (mean_residual - item_size as f64).max(0.0);
    } else {
        // Prefer bins whose residual is closest to (but >=) item size: tight fit reward
        let tight = (bin_residual - item_size) as f64;
        score += 0.1 * tight * tight / 100.0;
    }

    // Progress modulation: later in stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins near the mean residual (keeps balance)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Treat gaps below a threshold as wasted dead space
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.12);
        if gap < dead_threshold {
            score += (dead_threshold - gap) * 8.0; // steep penalty for near-full waste
        }
        // Perfect fit: zero residual is highly rewarded
        if post_residual == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (fill ratio)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 1.5;

    // Penalize if this bin's residual deviates far above the mean residual
    // (bins with large residuals are less scarce)
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 25.0;
        // If few fitting bins, opening new is less costly
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // If next item is large, keep capacity available for it
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more items to pack)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    } else {
        // Reward using existing bins, especially early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
    }

    // Lookahead: if the resulting residual can host the next item, reward it
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        // penalize leaving a gap that blocks the next item
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial match: the closer post_residual is to next_item_size, the better.
        let gap = (post_residual - next_item_size) as f64;
