        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Reward leaving a residual close to the mean residual of open bins
    // (keeps the fleet homogeneous and easy to match later).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.3;

    // Penalize small unusable dead space (< 10 can hold nothing typical).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins are open, discourage spreading; prefer tighter bins (small residual).
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, compactness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.2;

    // New-bin candidate: make it moderately attractive only when nothing fits well
    // (post_residual large relative to capacity means fresh bin keeps flexibility).
    if bin_residual == bin_capacity {
        let flexibility_bonus = post_residual as f64 * 0.5;
        score -= flexibility_bonus;
        // But if a perfect lookahead match exists elsewhere, this stays worse.
        if next_item_size > 0 && post_residual == next_item_size {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that no typical item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.4 * dead * dead / bin_capacity as f64;
