    // Perfect closure bonus: filling a bin exactly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // next item won't fit here; slight penalty for wasting lookahead space
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin is badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 35.0 + 30.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64);

        // If mean residual across open bins is small (all bins nearly full), opening new bin is fine.
        score -= 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
    }

    // Slight preference for bins with residual close to mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Mild time-horizon adaptation: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild pressure toward tight fits; later: strong pressure.
    let tightness = 1.0 - (pr / cap);
    let poly = 1.0 + 3.0 * progress * progress;
    score -= poly * tightness * tightness * cap * 0.5;

    // Penalize awkward residuals that neither vanish nor fit a plausible next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
