        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening fresh bins early, discourage late.
    if bin_residual == bin_capacity {
        score = cap - 20.0 * (1.0 - progress) + 10.0 * progress;
    }

    // Mild coupling with fleet state: spread load when many bins are open.
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quartile
    let q = bin_capacity / 4;
