    score -= harmonic_bonus;

    // Dead-space penalty: post_residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) with non-linear squash
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large leftover
            score += 6.0;
        }
        // harmonic class of next item relative to capacity
        let nq = next_item_size % q.max(1);
        if nq == 0 { score -= 5.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let crowding = mean_residual / bin_capacity as f64;
        score += 40.0 - 35.0 * crowding; // cheap to open when existing residuals are large
        if open_bins_count == 0 { score -= 100.0; }
    } else {
        // favor bins whose residual is below mean (consolidate emptier space elsewhere)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Stream progression: early on, be more selective (penalize waste); late, pack greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (>= 10) can ever fill it.
    if post_residual < 10 {
        score += 200.0; // absolute waste — nearly full bin, but gap is pure loss
    }

    // Gap unusable for the immediate lookahead item: strong penalty unless gap is tiny.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = next_item_size - post_residual;
