    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to remaining capacity or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        score += 3.0 * open_bins_count as f64;
        // If item is big, a fresh bin is fine (it will fill a lot of it).
        score -= 60.0 * fill;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below mean
    // (i.e., more filled bins) to consolidate usage.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
