    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 150.0;
        // Opening a new bin is attractive only if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer new bin when the item is large relative to capacity
        // (keeps open bins' residuals for smaller future items).
        let big = (item_size as f64) / (bin_capacity as f64);
        score -= 40.0 * big;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 * progress;
        // If many bins are open with large mean residual, discourage a new bin.
        score += 5.0 * (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64);
    } else {
        // Mild preference for using already-open bins when many are open.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
        // Prefer filling bins whose residual is already small (below mean).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Modulo-based harmonic bonus: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) remain useful.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 11.0);
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave a residual still usable by the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap just below the next item size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean-residual coupling: prefer bins whose residual is near the mean (avoid outliers).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin; only attractive when
    // the item is large relative to capacity or all fits would be terrible.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 55.0 - 35.0 * large_item;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing potential with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional to leftover dead space after both items
            let two_step_waste = post_residual - next_item_size;
            score += two_step_waste as f64 * 0.5;
        } else {
            // next item won't fit here: penalize large residuals that become dead space
            score += (post_residual as f64 - mean_residual).abs() * 0.3;
        }
    }

    // Penalize small awkward residuals (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0
            - (mean_residual / bin_capacity as f64) * 40.0
            - (fitting_bins_count as f64) * 10.0
            + progress * 20.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Mild preference for bins below mean residual (tighter packing)
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near 0 is ideal.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize bins that become "dead" (residual too small for any realistic item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit but could fit elsewhere, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual > 50 {
            score += 20.0; // wasteful last-chance fit
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly or there are no open bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if fitting_bins_count <= 1 {
            score -= 10.0; // poor alternatives -> new bin is fine
        } else {
            // full bin has residual == capacity; make it less attractive than
            // any bin that leaves less waste, but keep it viable if fits are bad.
            score += 15.0 + 0.5 * mean_residual;
            if post_residual >= 50 {
                score -= 10.0; // roomy new bin for future items
            }
        }
    }

    // Global state: many open bins with high mean residual -> prefer packing
    // into existing bins to consolidate.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Time horizon: early in the stream, keep bins flexible (prefer balanced
    // residuals); late in the stream, prioritize closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 0.15 * (post_residual as f64 - mean_residual).abs();
    } else if progress > 0.7 {
        score += 0.25 * post_residual as f64;
    }

    // Mild penalty for item barely fitting (fragile placements).
    if item_size > bin_residual {
        score += 1000.0; // safety guard (should not happen)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // waste is tolerated more early, penalized more late.
    let coupling = pr * pr / cap * (0.5 + 1.5 * progress * progress);
    score += 0.35 * coupling;

    // Reward tight fits (low post_residual relative to capacity) increasingly over time.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from mean residual
    // (consolidate space into few bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev * (0.5 + progress);

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - diff / cap).max(0.0);
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: bin_residual == bin_capacity implies empty bin;
    // encourage its use only when item is large and stream is late.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score -= 3.0 * size_frac * size_frac * (1.0 - progress);
        score += 2.0 * (1.0 - size_frac) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space classes".
    // Residuals that are small or exactly reusable (multiples of common item sizes) are good.
    let r = post_residual;
    let residue_class = (r % 10) as f64;
    if r > 0 {
        // Penalize residuals that are nonzero but too small for the minimum item (dead space).
        if r < 10 {
            score += 30.0 + (10 - r) as f64 * 2.0;
        } else {
            score -= residue_class * 0.4; // mild reward for "alignable" residuals
        }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual (harmonic match).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0; // perfect harmonic pairing
        } else if next_item_size <= r {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot fraction.
            let overshoot = (next_item_size - r) as f64 / bin_capacity as f64;
            score += overshoot * 10.0;
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // New bin starts with full residual as score; adjust based on context.
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        } else {
            // Only open if current bin would leave a large, awkward residual.
            // Penalize opening when many bins are open (consolidation preference).
            score += (open_bins_count as f64) * 3.0 + progress * 10.0;
            if next_item_size > 0 && next_item_size <= bin_residual - item_size {
                score -= 5.0; // fresh bin can host the next item too
            }
        }
    }

    // Mean residual coupling: if this bin's residual is far above mean, deprioritize slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small tie-breaker toward earlier bins implicitly via residual; keep monotone.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny (unlikely to fit
    // any future item well) are heavily penalized, super-linearly.
    let pr = post_residual as f64;
    if pr <= 10.0 {
        score += 40.0 * (11.0 - pr); // unusable sliver: strong penalty
    } else if pr <= 25.0 {
        score += 15.0 * (26.0 - pr) / 15.0; // awkward gap zone
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot fit into post_residual but would fit a
    // fuller bin's alternative... mild penalty for blocking lookahead.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // would leave a large, useful residual AND current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base new-bin score: post_residual is large, so it's already high.
        // Penalize opening new bins when decent alternatives exist.
        if fitting_bins_count > 0 {
            score += 12.0 * fitting_bins_count as f64;
        }
        // But if this is a large item, opening fresh is often fine.
        if item_size >= 60 {
            score -= 15.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (keeps bin states homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: next item exactly fills this bin
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            // Next item still fits here afterwards
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * slack;
        } else {
            // Dead space: next item cannot use the leftover
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste + 10.0 * progress;
        }
    }

    // ---- Tightness reward: small post_residual is good ----
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // ---- Relative to mean residual ----
    score += (post_residual as f64 - mean_residual) * 0.35;

    // ---- Last-chance bonus: only bin that fits -> avoid opening new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, but more when many bins are open
        // and mean residual is high (existing bins are reusable).
        score += 18.0 + 3.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // If the next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with larger residuals when many bins open
    score -= 0.05 * bin_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly: residuals that can never host
    // typical items (post_residual < 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: opening a new bin should only win when the fit
    // here is terrible. Make the fresh bin slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in the stream, prefer packing into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
        // Many open bins already: discourage proliferation.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Lookahead coupling: if the next item would fit exactly in the post
    // residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            // Blocks next item anyway; mild extra penalty.
            score += 10.0;
        }
    }

    // Global residual context: if this bin's residual is far below the mean,
    // it is already fragmented; using it consolidates waste.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.15;

    // Early stream: keep scores slightly compressed to allow exploration of
    // multiple bins; late stream: sharpen decisions toward best fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 0.9 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);
    // smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * (norm_pr * norm_pr) * (0.5 + progress);
    // reward tight fits (small post_residual) more strongly later in stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    // lookahead: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 15.0 * (ni - pr) / cap * (0.5 + progress);
        } else {
            score -= 8.0 * (pr - ni) / cap;
        }
    }
    // last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }
    // new-bin candidate: penalize mildly, less as stream progresses
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }
    // penalize bins far from mean residual (fragmentation smoothing)
    score += 2.0 * ((pr - mean_residual) / cap).abs();
    // scale with open bins count pressure
    score *= 1.0 + 0.05 * (open_bins_count as f64).sqrt();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division on capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_residual / (bin_capacity / 4).max(1)) as i64; // 0..4 harmonic classes

    // Reward tight fits strongly (class 0 = near-perfect packing).
    score -= match class {
        0 => 60.0,
        1 => 25.0,
        2 => 5.0,
        _ => 0.0,
    };

    // Dead-space penalty: residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead compatibility: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible; reward proportionally.
            score -= 20.0 + 0.25 * (next_item_size as f64);
        } else {
            // Next item won't chain; penalize leftover that is "almost but not" usable.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
        // Harmonic modulo coupling: next item leaves a tiny residual again?
        let next_post = post_residual as i64 - next_item_size as i64;
        if next_post >= 0 && (next_post as u32) < 10 {
            score -= 12.0; // creates another near-tight fit, good
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline so it only wins
    // when open bins are all poor fits.
    if bin_residual == bin_capacity {
        score = cap_f * 0.9 + 10.0 * (open_bins_count as f64).sqrt();
        // If current item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.7 * cap_f {
            score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with high residual (reduce fragmentation across fleet).
    score += 0.05 * (mean_residual - post_f).abs();

    // Mild late-stream consolidation: fewer open bins is better as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // Modulo tie-breaker on post_residual classes to diversify residuals.
    score += (post_residual % 7) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100 stream, but tiny gaps < ~10 are near-useless)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Gaps that cannot fit the lookahead item are moderately penalized.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain useful for the next item.
        score -= 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is the "dirtiest" bin — prefer to dump the item here.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.4;

    // New-bin candidate: only attractive when existing bins would leave
    // bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced under high open-bin pressure
        // relief (few open bins) or when many bins compete poorly.
        score = bin_capacity as f64 * 0.75 + open_bins_count as f64 * (0.4 + 0.5 * progress);
        if post_residual == bin_capacity {
            // untouched new bin; keep as-is
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward residuals that can exactly host the next item,
    // or at least leave useful space relative to it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred
    // (concentrate waste), bins looser than average get a penalty.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits among them.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 120.0; // open bins nearly full -> fresh bin is fine
        } else {
            score += 150.0; // plenty of room left in open bins -> discourage new bin
        }
    }

    // Early in the stream, slightly favor keeping bins open and consolidated.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: penalize when post_residual is small relative to item size.
    if post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        score += waste_frac * waste_frac * 30.0;
    } else {
        score -= 25.0; // perfect fill
    }

    // Reward bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: penalize leaving residual that fits the next item badly
    // (residual too small to be useful), reward residual that pairs with next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 6.0 * (nx / cap); // next item can also fit here
        } else if post_residual > 0 {
            let dead = post_residual as f64 / cap;
            score += dead * 20.0 * (1.0 - progress); // dead space matters more early
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // or few bins can fit the item.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let poor_fit = 1.0 - fill_ratio.min(1.0);
        let open_bonus = (open_bins_count as f64).ln().max(0.5);
        score = 40.0 - fit_pressure * 30.0 - poor_fit * 25.0 * open_bonus - progress * 10.0;
        // If a near-perfect fit exists elsewhere, discourage new bin.
        if fill_ratio > 0.85 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Mild global balancing: prefer bins with residual near mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream: favor consolidation into fewer bins.
    if open_bins_count > 1 && progress > 0.7 && bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: waste after placement, normalized, with non-linear (quadratic/cubic) shaping
    let x = post / cap;
    let mut score = x * (1.0 + 2.0 * x * x);

    // Reward tight fits: small post_residual gets a strong discount
    score -= (1.0 - x) * (1.0 - x) * 8.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 12.0;
    }

    // Non-linear coupling of waste with stream progress: waste is costlier later
    score += x * x * (1.0 + 6.0 * progress * progress);

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when fits exist
    if bin_residual == bin_capacity {
        let fits = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 14.0 + 10.0 / (1.0 + fits) + 4.0 * (1.0 - progress);
        // But allow new bin if current item leaves a bad fit and lookahead matches new bin well
        let look = next_item_size as f64;
        if look > 0.0 {
            let look_res = cap - look;
            if look_res >= 0.0 && (post - look).abs() < 3.0 {
                score -= 18.0;
            }
        }
    }

    // Lookahead coupling: reward if post_residual pairs well with next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post - look).abs();
        score -= (1.0 - diff / cap).max(0.0) * 5.0 * (1.0 - progress);
        // Penalize leaving residual that no plausible item fills
        if post < look {
            score += 2.0 * (look - post) / cap;
        }
    } else {
        // Last item: just minimize waste
        score += x * 3.0;
    }

    // Mild penalty when many bins already open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * x;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    score += ((post - mean_residual) / cap).abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division into capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 10).min(10) as f64; // decile class of dead space

    // Reward small post_residual strongly (best-fit core), non-linearly
    score -= (c - pr) / c * 30.0;

    // Harmonic class bonus: post_residual in "sweet spot" classes (0, 20, 50)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0; // round residual may pair with common item sizes
    }

    // Penalize awkward dead space classes (11..19, 31..39 etc. rarely filled)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    }

    // Lookahead coupling: does next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, scaled by how tightly it packs
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - tight / c);
        } else {
            // next item won't fit: penalize proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(50.0) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer filling bins when many bins are open (reduce bin count pressure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Prefer bins with residual far below mean residual (consolidate emptiness)
    score -= (mean_residual - pr) * 0.3;

    // New-bin candidate: make empty bin moderately attractive only when item is large
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / c;
        score = 45.0 - 30.0 * large_item;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // big items arriving: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (items >= 1, but practically small gaps < ~10)
    // are pure waste. Penalize them super-linearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Gaps in the "awkward middle" (10..20) are hard to fill too.
    else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // If the lookahead item fits exactly in the resulting residual,
    // strongly favor this placement (chains efficient packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual - next_item_size < 10 {
            score -= 8.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot fit here: penalize proportionally to the gap.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage consolidation.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when the current item is large
    // (would leave awkward gaps elsewhere) or all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        if item_size >= 60 || crowded {
            score -= 18.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 0.8;
        }
    } else {
        // Prefer tighter existing bins: residual close to item size = good fit.
        score += (bin_residual - item_size) as f64 * 0.3;
        // Favor bins below the mean residual (tighter than average).
        score += (mean_residual - bin_residual as f64) * 0.4;
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score = post_residual as f64 * 1.0;

    // Strongly reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chain of two perfect placements
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit in leftover: penalize dead space that blocks next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Penalize leaving residuals that are likely unusable (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins with more free space when residuals are large,
    // but prefer filling low-residual bins (avoid scattering)
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists; penalize it moderately so open bins are preferred
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if item is large and few bins fit, new bin is less bad
        if item_size >= 60 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large upcoming items pair well in a fresh bin
        }
    }

    // Slight preference to keep open bin count from exploding
    score += 0.5 * open_bins_count as f64;

    // Mild stream-position term: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong fit reward: quadratic bonus for tight placements.
    let fit_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residuals too small for the smallest possible item (<=1 here,
    // so penalize any residual below a small usable threshold less; focus on mid-range waste).
    let waste = post_residual as f64;
    if waste > 0.0 && waste < 10.0 {
        score += 15.0; // nearly-dead space penalty
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64) / 10.0;
        } else {
            // next item cannot use the residual: mild penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline cost that grows with
    // open-bin pressure, so we only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * (open_bins_count as f64).sqrt();
        // But if no existing bin fits at all, opening is inevitable: soften.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low (stream
    // is consolidating); be pickier when many loose bins exist.
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * residual_gap;

    // Time horizon: late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic waste penalty (dead space grows quadratically worse)
    let mut score = pr * (1.0 + pr / cap);

    // Smooth non-linear coupling of waste with stream progress:
    // early on, waste is tolerable; late, minimize residual aggressively.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of item/capacity
    let tightness = (item_size as f64 / cap) * (1.0 - pr / cap);
    score -= 30.0 * tightness;

    // Lookahead: if the next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_quality = 1.0 / (1.0 + gap);
        score -= 20.0 * fit_quality * (nxt / cap);
        // penalize leaving residual that is awkwardly larger than next item
        score += 0.15 * gap.max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates from the mean (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: only attractive when no good fit exists.
    // Empty bin has pr == cap; give it a mild penalty so existing bins
    // with reasonable fits win, but allow it when fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).ln_1p();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" classes (small leftovers that future small items can fill)
    // are favored; dead-space classes are penalized.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,          // perfect fit: best possible
        1..=5 => 0.5,      // nearly perfect
        6..=15 => 1.5,     // small-class leftover, still useful
        16..=30 => 3.0,    // medium leftover
        31..=49 => 5.0,    // awkward class (too big for tiny items, too small for most)
        _ => 7.0,          // large leftover: wasteful placement
    };
    score += class * 4.0;

    // Reward tight fits nonlinearly: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 18.0 * fill * fill;

    // Perfect fit bonus.
    if pr == 0 { score -= 25.0; }

    // Harmonic check: does leftover match a plausible next-item class?
    // If next item fits exactly or nearly in the leftover, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = (pr - next_item_size) as f64;
        if gap == 0.0 {
            score -= 20.0; // chains perfectly
        } else if gap <= 10.0 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > pr {
        // leftover too small for next item: dead space unless item nearly fills bin
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into bins with low residual
    // (closest-fit pressure), penalize spreading.
    if open_bins_count > 3 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Early in stream: keep bins flexible (penalize very small leftovers
    // that fragment capacity when many items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 && pr > 0 && pr < 10 {
        score += 4.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or bins are heavily fragmented. Baseline score for empty bin is
    // post_residual == capacity, already high; add mild deterrent unless
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // low pressure = open bins mostly full
        score -= 15.0 * (1.0 - pressure);
        if fitting_bins_count == 0 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are nearly unusable dead space.
    if post_residual > 0 {
        let unusable = next_item_size > 0 && (post_residual as u32) < next_item_size;
        if unusable {
            score += 25.0 + 0.5 * post_residual as f64; // dead space penalty
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // mild reward for leaving room for the next item
        score -= 5.0 * (next_item_size as f64 / (post_residual as f64));
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (1.0 - tightness) * (0.5 + 0.5 * progress);

    // Mean residual deviation: prefer bins whose residual is close to the mean (balanced use).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * fitting_bins_count as f64;
        // But if all fits are terrible (huge dead space), new bin is fine.
        if fitting_bins_count > 0 && (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead fit: reward proportional to how much of the residual is consumed
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * frac;
        } else {
            // Next item won't fit here: penalize leftover dead space
            let dead = post_residual as f64;
            score += 0.15 * dead;
        }
    }

    // Prefer bins whose residual is below the mean residual (tight packing)
    let diff = mean_residual - post_residual as f64;
    score += 0.05 * diff;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize the brand-new empty bin candidate unless item is large or fit is poor
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Slight preference to fill nearly-full bins
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * fill_ratio;

    // Late in stream: pack tighter, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Perfect fit gets a large reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space that likely can't be reused by typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is usually wasteful unless
    // current fit is bad and many bins are open with fragmented residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin scaled by stream progress (early waste is costlier over a long stream).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * (1.0 - progress);

        // If there is exactly one fitting bin and it isn't great, allow new bin sometimes:
        // reward new bin when the current bin's post_residual is very small (item barely fits)
        // making it unusable, but only when few bins are open (avoid bin explosion).
        if fitting_bins_count <= 1 && post_residual > 0 && post_residual < 10 {
            score -= 35.0;
        }
        // If mean residual across open bins is large, prefer reusing open bins.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
    } else {
        // Reusing an open bin is generally good; small extra reward scaled by how full it becomes.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Global pressure: many open bins -> encourage consolidation into existing bins.
    if open_bins_count > 4 {
        let pressure = ((open_bins_count as f64 - 4.0) / (open_bins_count as f64 + 4.0)).min(1.0);
        if bin_residual != bin_capacity {
            score -= 12.0 * pressure;
        } else {
            score += 12.0 * pressure;
        }
    }

    // Mild preference for bins whose residual is below mean (keep large residuals for big items).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        if diff > 0.0 {
            score += 0.05 * diff;
        } else {
            score -= 0.03 * (-diff);
        }
    }

    // Tie-breaker: slight deterministic jitter based on step to break symmetries.
    score -= ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic penalty on wasted residual, modulated by stream progress.
    let mut score = prn * prn * (1.0 + 0.8 * progress) * 100.0;

    // Smooth reward for tight fits (small post_residual) growing with progress.
    score -= (1.0 - prn).powi(3) * 40.0 * (0.5 + 0.5 * progress);

    // Dead-space term: residuals too small for typical items are wasted.
    let dead_threshold = 10.0f64.min(cap);
    if pr < dead_threshold {
        score += 60.0 * (dead_threshold - pr) / dead_threshold;
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap / 30.0).exp();
        score -= 25.0 * kernel;
        // Penalize leaving exactly next item size (over-tuning lookahead).
        score += 8.0 * (-((pr - next_item_size as f64).powi(2)) / 50.0).exp() * (pr - next_item_size as f64).signum().abs();
    } else {
        // Last item: strongly prefer minimal residual.
        score += prn * 30.0;
    }

    // New-bin candidate: penalize opening a bin unless existing bins are poor fits.
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 55.0 * (1.0 - 0.6 * scarcity) * (1.0 + 0.5 * progress);
        // If residual mean is high, open bins are roomy; opening new bin less costly.
        score -= (mean_residual / cap).min(1.0) * 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0 * (1.0 - prn);
    }

    // Mild preference to spread load when many bins open (smooth in open count).
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * prn;

    // Non-linear coupling of post_residual with progress (cubic interaction).
    score += 10.0 * prn * prn * prn * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity / 4.
    // Residuals in the "small" classes (0..10) are dead space; penalize them.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);
    score += (class as f64) * 0.05;

    // Perfect-fit harmonic classes: post_residual divisible by common item sizes.
    if post_residual == 0 {
        score -= 50.0; // exact fill
    } else if post_residual <= 10 {
        score += 8.0; // unusable sliver
    }

    // Reward tight fits scaled by how well post_residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to miss size.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 0.2 * next_item_size as f64;
        }
    }

    // Progress-based tie-break: later in stream, prefer consolidating (fill existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.1;

    // Mean-residual coupling: if this bin's residual is far above mean, it's a good filler.
    let diff = bin_residual as f64 - mean_residual;
    score -= 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual that cannot fit even the smallest plausible item (<= 12) is "dead".
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    } else {
        // Larger post_residuals are flexible; reward them mildly.
        score -= 5.0;
    }

    // Perfect fits are excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up; reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 35.0;
        } else if slack < 12.0 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    }
    // Penalize if next item cannot fit in post_residual (bin becomes dead for lookahead).
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage filling existing ones tighter.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure and
        // how early in the stream we are (early stream: prefer consolidation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_pressure + (1.0 - progress) * 10.0;
    } else {
        // Reward using existing bins more when many bins are open.
        score -= open_pressure;
    }

    // Mean-residual coupling: if this bin's residual is well below the mean,
    // it is a tight fit already; prefer it (keeps loose bins available).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual - 10.0 {
        score -= 6.0;
    } else if bin_res_f > mean_residual + 10.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small leftovers slightly
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to item size (tight fit relative to others)
    let mean_r = mean_residual.max(1.0);
    score += (bin_residual as f64 - mean_r).abs() * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when a decent existing fit exists
    if bin_residual == bin_capacity {
        score += 60.0;
        // but allow new bin if no existing bin fits well (large waste otherwise)
        if bin_residual < item_size {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Late in stream: prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    // Slight preference for bins with larger residual when many open bins
    score -= (bin_residual as f64) * 0.05;

    score
}
